
window.MODELS_META = [{"id":"architecture_model_001_alexnet","num":1,"num_str":"001","year":2012,"year_str":"2012","venue":"NeurIPS","venue_group":"ml","era_group":"era1","title":"AlexNet","family_id":"models_cnn_backbones","family_code":"01","family_short":"CNN 主干与现代卷积","family_en":"CNN Backbones","family_icon":"I","family_label":"CNN 主干：从大规模分类到现代卷积","archetype":"sequential_cnn","archetype_en":"sequential_cnn","accent":"#1F4E79","fig_badge":"Figure 2 · PDF p.5","fig_href":"https://proceedings.neurips.cc/paper/2012/hash/c399862d3b9d6b76c8436e924a68c45b-Abstract.html","core_mech":"以 GPU、ReLU、dropout 和深卷积组合首次规模化训练 ImageNet 级深 CNN。","core_mech_en":"First large-scale ImageNet-grade deep CNN trained end-to-end by combining dual-GPU parallelism, non-saturating ReLU activations, dropout regularization, and stacked convolutions.","input_desc":"224×224 RGB 图像","input_en":"224×224 RGB image","output_desc":"类别概率或倒数第二层视觉特征","output_en":"Closed-set class probabilities or penultimate 4096-D visual feature vector","form_title":"核心公式 · 原始 AlexNet 的跨通道局部响应归一化","form_title_en":"Core Formalism · Cross-Channel Local Response Normalization (LRN) in Original AlexNet","nodes":[{"name":"输入图像","desc":"RGB 图像经随机裁剪、翻转与均值处理进入网络。","name_en":"Input Image","desc_en":"RGB image enters the network after random cropping, horizontal flipping, and mean subtraction."},{"name":"11×11 Conv","desc":"大步幅卷积快速降采样，ReLU 取代易饱和激活。","name_en":"11×11 Conv","desc_en":"Large-stride convolution rapidly downsamples spatial resolution while ReLU replaces saturating activations."},{"name":"Pool + LRN","desc":"重叠最大池化压缩空间；原版使用局部响应归一化。","name_en":"Pool + LRN","desc_en":"Overlapping max-pooling compresses spatial dimensions; original formulation applies Local Response Normalization (LRN)."},{"name":"5×5 分组卷积","desc":"原始双 GPU 实现按通道分组计算第二层卷积。","name_en":"5×5 Grouped Conv","desc_en":"Original dual-GPU implementation partitions channels into two parallel groups for second-layer convolution."},{"name":"3×3 Conv 堆叠","desc":"连续三层卷积组合中层纹理与高层形状证据。","name_en":"Stacked 3×3 Convs","desc_en":"Three consecutive 3×3 convolutional layers compose mid-level textures and high-level shape cues."},{"name":"FC6–FC7","desc":"两层大容量全连接层，训练时以 dropout 抑制共适应。","name_en":"FC6–FC7","desc_en":"Two high-capacity fully connected layers regularized via dropout during training to suppress co-adaptation."},{"name":"分类头","desc":"线性层把高维特征映射到固定类别 logits。","name_en":"Classification Head","desc_en":"Linear classifier projects high-dimensional features onto closed-set class logits."},{"name":"Softmax","desc":"将 logits 归一化为封闭类别概率。","name_en":"Softmax","desc_en":"Normalizes raw logits into closed-set categorical probabilities via Softmax."}],"design_principles":["局部卷积与权重共享把图像结构先验写入参数化方式。","ReLU、GPU 并行和数据增强共同使大规模深监督训练成为现实。","dropout 主要约束大容量全连接层，并不替代外部验证。"],"design_principles_en":["Core Hypothesis: End-to-end GPU-trained deep convolutional classifier scaling capacity via ReLU, dropout, and aggressive data augmentation.","Architectural Delta: 5 convolutional layers + 3 fully connected layers integrating multi-GPU execution, ReLU non-linearity, dropout, and crop/color augmentations.","Mathematical Formalism: Cross-Channel Local Response Normalization (LRN) in Original AlexNet."],"med_apps":["可作为理解早期 ImageNet 到医学 2D 迁移的历史起点，但今天不应作为强主干。","早期大步幅与多次下采样容易抹去微小病灶，医学使用应审计输入分辨率。"],"med_apps_en":["Clinical Translation: Catalyzed transfer of generic ImageNet CNN representations across 2D medical imaging classification and detection.","Evidence & Safety Boundary: Historical milestone; superseded as a competitive medical backbone."],"attrs":{"上一代瓶颈":"手工特征占主导，深 CNN 计算昂贵且易饱和或过拟合","核心想法":"GPU 训练的深层卷积分类器，以 ReLU、dropout 和增强扩大可训练规模","关键改进":"5 个卷积层加 3 个全连接层，结合 GPU、ReLU、dropout 与数据增强","医学适配":"推动通用 CNN/ImageNet 表示迁移，后续被医学 2D 任务广泛采用","适用范围与证据":"历史里程碑；不再是医学强基线"},"attrs_en":{"上一代瓶颈":"Hand-crafted features dominated vision; deep CNNs were computationally prohibitive and prone to saturating gradients or severe overfitting.","核心想法":"End-to-end GPU-trained deep convolutional classifier scaling capacity via ReLU, dropout, and aggressive data augmentation.","关键改进":"5 convolutional layers + 3 fully connected layers integrating multi-GPU execution, ReLU non-linearity, dropout, and crop/color augmentations.","医学适配":"Catalyzed transfer of generic ImageNet CNN representations across 2D medical imaging classification and detection.","适用范围与证据":"Historical milestone; superseded as a competitive medical backbone."},"paper_title":"ImageNet Classification with Deep Convolutional Neural Networks","paper_url":"https://proceedings.neurips.cc/paper/2012/hash/c399862d3b9d6b76c8436e924a68c45b-Abstract.html","code_label":"未提供官方实现","code_url":"","has_code":false,"image":"assets/cad8c890b94f8080f8f7.avif"},{"id":"architecture_model_002_resnet","num":2,"num_str":"002","year":2016,"year_str":"2016","venue":"CVPR","venue_group":"cv","era_group":"era2","title":"ResNet","family_id":"models_cnn_backbones","family_code":"01","family_short":"CNN 主干与现代卷积","family_en":"CNN Backbones","family_icon":"I","family_label":"CNN 主干：从大规模分类到现代卷积","archetype":"residual_backbone","archetype_en":"residual_backbone","accent":"#1F4E79","fig_badge":"Figure 2 · PDF p.2","fig_href":"https://openaccess.thecvf.com/content_cvpr_2016/html/He_Deep_Residual_Learning_CVPR_2016_paper.html","core_mech":"显式 identity shortcut 与残差相加 y=x+F(x)。","core_mech_en":"Explicit identity shortcut connections combined with additive residual learning y = x + F(x).","input_desc":"2D 图像或 3D 体数据特征","input_en":"2D image or 3D volumetric feature tensor","output_desc":"分类 logits、金字塔特征或下游编码表示","output_en":"Classification logits, multi-scale feature pyramid, or downstream encoded representations","form_title":"核心公式 · 残差分支与恒等捷径相加","form_title_en":"Core Formalism · Additive Residual Branch with Identity Shortcut Mapping","nodes":[{"name":"Stem","desc":"卷积与下采样建立第一层局部特征。","name_en":"Stem","desc_en":"Initial convolutional stem and downsampling extract low-level local features."},{"name":"块输入 x","desc":"同时进入残差分支与恒等捷径。","name_en":"Block Input x","desc_en":"Splits tensor simultaneously into the non-linear residual branch and the identity shortcut."},{"name":"F(x)","desc":"BasicBlock 用两层 3×3；Bottleneck 用 1×1–3×3–1×1。","name_en":"F(x)","desc_en":"BasicBlock stacks two 3×3 convolutions; Bottleneck uses a 1×1–3×3–1×1 channel compression-expansion design."},{"name":"Identity","desc":"维度不变时直接传递；变化时用 projection shortcut。","name_en":"Identity","desc_en":"Passes features directly when dimensions match, or applies a 1×1 projection shortcut when stride/channels change."},{"name":"残差相加","desc":"计算 y=x+F(x)，保留近似恒等映射与短梯度路径。","name_en":"Residual Addition","desc_en":"Computes y = x + F(x), preserving an unattenuated identity reference and short gradient highway."},{"name":"分层 Stage","desc":"重复残差块并逐级降低分辨率、增加通道。","name_en":"Hierarchical Stages","desc_en":"Stacks residual blocks across stages while progressively halving spatial resolution and doubling channels."},{"name":"全局平均池化","desc":"把最终空间特征聚合为图像级向量。","name_en":"Global Average Pooling","desc_en":"Pools final spatial feature maps into a global image-level representation vector."},{"name":"任务头","desc":"连接分类头，或把多尺度 stage 特征交给检测/分割解码器。","name_en":"Task Head","desc_en":"Feeds the classification head or exports multi-scale stage features to detection/segmentation decoders."}],"design_principles":["残差块学习相对恒等映射的修正，而不是每层重新构造完整表示。","恒等捷径提供不经过权重层的梯度通路，缓解深层优化退化。","projection shortcut 只在空间或通道维度变化时匹配张量形状。"],"design_principles_en":["Core Hypothesis: Reformulate layers to learn residual perturbations y = x + F(x) relative to an identity reference.","Architectural Delta: Parameter-free identity shortcuts and 1×1 projection shortcuts enable stable optimization beyond 100+ layers.","Mathematical Formalism: Additive Residual Branch with Identity Shortcut Mapping."],"med_apps":["3D ResNet、Residual U-Net 与 nnU-Net ResEnc 都复用其块级优化机制。","残差捷径解决深层优化，不等同于 U-Net 用于恢复定位信息的长跳连。"],"med_apps_en":["Clinical Translation: Foundational building block for 3D ResNet, Residual U-Net, and nnU-Net ResEnc across medical modalities.","Evidence & Safety Boundary: Mandatory foundational backbone and fair baseline across 2D and 3D biomedical tasks."],"attrs":{"上一代瓶颈":"网络加深后出现优化退化，训练误差反而上升","核心想法":"用恒等捷径学习残差映射 y=x+F(x)","关键改进":"identity shortcut 与必要时的 projection shortcut 使百层网络可优化","医学适配":"3D ResNet、Residual U-Net 与 nnU-Net ResEnc 的核心结构","适用范围与证据":"仍是必须精通的强主干和公平对照"},"attrs_en":{"上一代瓶颈":"Deepening plain networks triggered optimization degradation where training error paradoxically increased with depth.","核心想法":"Reformulate layers to learn residual perturbations y = x + F(x) relative to an identity reference.","关键改进":"Parameter-free identity shortcuts and 1×1 projection shortcuts enable stable optimization beyond 100+ layers.","医学适配":"Foundational building block for 3D ResNet, Residual U-Net, and nnU-Net ResEnc across medical modalities.","适用范围与证据":"Mandatory foundational backbone and fair baseline across 2D and 3D biomedical tasks."},"paper_title":"Deep Residual Learning for Image Recognition","paper_url":"https://openaccess.thecvf.com/content_cvpr_2016/html/He_Deep_Residual_Learning_CVPR_2016_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/KaimingHe/deep-residual-networks","has_code":true,"image":"assets/fb90d8738ce6fc9467fe.avif"},{"id":"architecture_model_003_densenet","num":3,"num_str":"003","year":2017,"year_str":"2017","venue":"CVPR","venue_group":"cv","era_group":"era2","title":"DenseNet","family_id":"models_cnn_backbones","family_code":"01","family_short":"CNN 主干与现代卷积","family_en":"CNN Backbones","family_icon":"I","family_label":"CNN 主干：从大规模分类到现代卷积","archetype":"dense_connectivity","archetype_en":"dense_connectivity","accent":"#1F4E79","fig_badge":"Figures 1 and 2 · PDF pp.1, 3","fig_href":"https://openaccess.thecvf.com/content_cvpr_2017/html/Huang_Densely_Connected_Convolutional_CVPR_2017_paper.html","core_mech":"每层对所有前层输出做通道 concat，而非仅连接相邻层或做残差相加。","core_mech_en":"Every layer concatenates feature maps from all preceding layers along the channel axis rather than summing adjacent residuals.","input_desc":"图像或前一 transition 的特征图","input_en":"Input image or feature maps from the preceding transition block","output_desc":"复用全部前层表示的分类或编码特征","output_en":"Classification logits or multi-scale concatenated dense features reusing all earlier layers","form_title":"核心公式 · 第 ℓ 层拼接全部早期特征","form_title_en":"Core Formalism · Layer ℓ Channel Concatenation Across All Preceding States","nodes":[{"name":"卷积 Stem","desc":"建立初始低层视觉特征。","name_en":"Convolutional Stem","desc_en":"Extracts initial low-level visual feature representations."},{"name":"特征库","desc":"保存 dense block 内此前所有层的输出。","name_en":"feature","desc_en":"Accumulates feature maps produced by all preceding layers within the dense block."},{"name":"通道拼接","desc":"第 l 层输入为 [x0,…,x(l−1)]，不是逐元素相加。","name_en":"Channel Concatenation","desc_en":"Layer l receives channel concatenation [x_0, …, x_{l-1}] rather than element-wise addition."},{"name":"1×1 Bottleneck","desc":"BN–ReLU–1×1 Conv 控制进入 3×3 卷积的通道成本。","name_en":"1×1 Bottleneck","desc_en":"Pre-activation BN–ReLU–1×1 bottleneck compresses channel width prior to 3×3 spatial convolution."},{"name":"3×3 Growth","desc":"每层只新增 k 个通道，k 为 growth rate。","name_en":"3×3 Growth","desc_en":"Each composite layer appends exactly k new feature channels governed by growth rate k."},{"name":"Dense Block","desc":"新特征回写特征库并供所有后续层直接访问。","name_en":"Dense Block","desc_en":"Appends newly generated features to the shared bank for direct access by all subsequent layers."},{"name":"Transition","desc":"1×1 Conv 与平均池化压缩通道和空间尺寸。","name_en":"Transition","desc_en":"Transition layer (1×1 conv + 2×2 average pooling) compresses both channel count and spatial grid resolution."},{"name":"GAP + Head","desc":"全局池化后输出分类，或导出 dense features 供下游使用。","name_en":"GAP + Head","desc_en":"Applies global pooling for classification or exports multi-scale dense features to downstream decoders."}],"design_principles":["密集拼接使每层直接访问低层与高层特征，强化特征复用。","growth rate 把网络宽度增长显式化，参数可少于同深度普通 CNN。","短连接改善特征和梯度传播，但拼接会增加 activation memory。"],"design_principles_en":["Core Hypothesis: Feed each layer the channel-wise concatenation of all prior layers within a block while bounding width via a fixed growth rate k.","Architectural Delta: Dense short paths enforce explicit multi-scale feature reuse with high parameter efficiency.","Mathematical Formalism: Layer ℓ Channel Concatenation Across All Preceding States."],"med_apps":["DenseNet-121 长期用于胸片编码，H-DenseUNet 将密集连接扩展到肝脏分割。","3D 任务中应把拼接造成的显存增长与参数量优势分开报告。"],"med_apps_en":["Clinical Translation: DenseNet-121 became a canonical chest X-ray backbone (CheXNet); H-DenseUNet extended dense connectivity to 3D liver tumor segmentation.","Evidence & Safety Boundary: Enduring architectural principle, though channel concatenation incurs high GPU activation memory in 3D."],"attrs":{"上一代瓶颈":"深层网络中特征传播与梯度传递受阻，并会重复学习相似表示","核心想法":"每层接收全部前层特征的拼接并以 growth rate 控制宽度","关键改进":"密集短路径带来显式特征复用和较少参数","医学适配":"DenseNet-121 成为胸片经典主干，H-DenseUNet 用于肝肿瘤分割","适用范围与证据":"结构思想仍有价值，但 activation memory 较大"},"attrs_en":{"上一代瓶颈":"Deep networks suffered from attenuated feature propagation and redundant re-learning of low-level representations.","核心想法":"Feed each layer the channel-wise concatenation of all prior layers within a block while bounding width via a fixed growth rate k.","关键改进":"Dense short paths enforce explicit multi-scale feature reuse with high parameter efficiency.","医学适配":"DenseNet-121 became a canonical chest X-ray backbone (CheXNet); H-DenseUNet extended dense connectivity to 3D liver tumor segmentation.","适用范围与证据":"Enduring architectural principle, though channel concatenation incurs high GPU activation memory in 3D."},"paper_title":"Densely Connected Convolutional Networks","paper_url":"https://openaccess.thecvf.com/content_cvpr_2017/html/Huang_Densely_Connected_Convolutional_CVPR_2017_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/liuzhuang13/DenseNet","has_code":true,"image":"assets/54df07934d480169d323.avif"},{"id":"architecture_model_004_convnext","num":4,"num_str":"004","year":2022,"year_str":"2022","venue":"CVPR","venue_group":"cv","era_group":"era3","title":"ConvNeXt","family_id":"models_cnn_backbones","family_code":"01","family_short":"CNN 主干与现代卷积","family_en":"CNN Backbones","family_icon":"I","family_label":"CNN 主干：从大规模分类到现代卷积","archetype":"modern_convnet_block","archetype_en":"modern_convnet_block","accent":"#1F4E79","fig_badge":"Figures 3 and 4 · PDF pp.4, 5","fig_href":"https://openaccess.thecvf.com/content/CVPR2022/html/Liu_A_ConvNet_for_the_2020s_CVPR_2022_paper.html","core_mech":"7×7 depthwise spatial mixer 加 inverted bottleneck 的现代纯卷积块。","core_mech_en":"Modernized pure ConvNet block pairing a 7×7 depthwise spatial mixer with an inverted channel bottleneck.","input_desc":"2D 图像","input_en":"2D image tensor","output_desc":"四级层级特征或分类 logits","output_en":"Four-stage hierarchical feature pyramid or classification logits","form_title":"核心公式 · ConvNeXt 大核深度卷积残差块","form_title_en":"Core Formalism · ConvNeXt Large-Kernel Depthwise Residual Block","nodes":[{"name":"4×4 Patchify","desc":"kernel=stride=4 的卷积 stem 直接生成低分辨率特征。","name_en":"4×4 Patchify","desc_en":"Non-overlapping 4×4 strided patchify stem downsamples input directly into quarter-resolution feature maps."},{"name":"7×7 DWConv","desc":"逐通道大核卷积扩大局部感受野而控制参数量。","name_en":"7×7 DWConv","desc_en":"Depthwise 7×7 spatial convolution expands the effective receptive field while keeping parameter count low."},{"name":"LayerNorm","desc":"通道后置格式下归一化，贴近现代 Transformer 训练配方。","name_en":"LayerNorm","desc_en":"Applies channels-last LayerNorm aligned with modern Vision Transformer training recipes."},{"name":"4× 扩展","desc":"pointwise 线性层扩张通道，形成 inverted bottleneck。","name_en":"4× Channel Expansion","desc_en":"Pointwise 1×1 linear layer expands channel dimension by 4× in an inverted bottleneck configuration."},{"name":"GELU","desc":"在扩展通道空间进行平滑非线性变换。","name_en":"GELU","desc_en":"Applies smooth GELU non-linear activation within the expanded channel space."},{"name":"通道投影","desc":"第二个 pointwise 层压回原通道数。","name_en":"Channel Projection","desc_en":"Second pointwise 1×1 projection compresses channels back to the block dimension."},{"name":"残差相加","desc":"配合 layer scale 与 stochastic depth 稳定深层训练。","name_en":"Residual Addition","desc_en":"Residual connection combined with learnable LayerScale and Stochastic Depth stabilizes deep optimization."},{"name":"Stage Downsample","desc":"独立归一化与 stride-2 卷积构建四级金字塔。","name_en":"Stage Downsample","desc_en":"Separate LayerNorm + 2×2 stride-2 convolution downsamples features across a four-stage pyramid."},{"name":"GAP + Head","desc":"输出分类，或提供多尺度特征给检测/分割解码器。","name_en":"GAP + Head","desc_en":"Outputs class logits or supplies four-stage hierarchical features to dense prediction heads."}],"design_principles":["用大核 depthwise convolution 分离空间混合与通道混合。","inverted bottleneck、LayerNorm 与 GELU 吸收了 ViT/Swin 的有效工程设计。","层级金字塔保留卷积局部先验，同时扩大有效感受野。"],"design_principles_en":["Core Hypothesis: Modernize a pure hierarchical ConvNet using Transformer-era training recipes and large-kernel depthwise convolutions.","Architectural Delta: 7×7 depthwise conv, inverted bottleneck (1×1 expansion), LayerNorm, GELU, and a 4×4 patchify stem.","Mathematical Formalism: ConvNeXt Large-Kernel Depthwise Residual Block."],"med_apps":["适合作为判断 Transformer 或 SSM 增益是否真实的现代 CNN 对照。","3D MedNeXt 继承其块设计，但必须重新评估 spacing、大核成本和 activation memory。"],"med_apps_en":["Clinical Translation: Directly inspired 3D MedNeXt and serves as a rigorous modern CNN control against medical Transformers and SSMs.","Evidence & Safety Boundary: State-of-the-art pure CNN backbone ideal for controlled architectural ablations."],"attrs":{"上一代瓶颈":"Transformer 与 CNN 的比较混入了训练配方和层级设计差异","核心想法":"以现代训练配方和大核 depthwise 卷积重构纯卷积层级主干","关键改进":"7×7 depthwise conv、inverted bottleneck、LayerNorm/GELU 与 patchify stem","医学适配":"直接启发 3D MedNeXt，并作为医学 Transformer/SSM 的强 CNN 对照","适用范围与证据":"现代强 CNN 主干，适合公平架构比较"},"attrs_en":{"上一代瓶颈":"Comparisons between Vision Transformers and CNNs conflated self-attention with modern training recipes and macro-architecture design.","核心想法":"Modernize a pure hierarchical ConvNet using Transformer-era training recipes and large-kernel depthwise convolutions.","关键改进":"7×7 depthwise conv, inverted bottleneck (1×1 expansion), LayerNorm, GELU, and a 4×4 patchify stem.","医学适配":"Directly inspired 3D MedNeXt and serves as a rigorous modern CNN control against medical Transformers and SSMs.","适用范围与证据":"State-of-the-art pure CNN backbone ideal for controlled architectural ablations."},"paper_title":"A ConvNet for the 2020s","paper_url":"https://openaccess.thecvf.com/content/CVPR2022/html/Liu_A_ConvNet_for_the_2020s_CVPR_2022_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/facebookresearch/ConvNeXt","has_code":true,"image":"assets/1db602d1fd9b6125beda.avif"},{"id":"architecture_model_005_fcn","num":5,"num_str":"005","year":2015,"year_str":"2015","venue":"CVPR","venue_group":"cv","era_group":"era1","title":"FCN","family_id":"models_dense_segmentation","family_code":"02","family_short":"稠密预测与医学分割","family_en":"Dense Segmentation","family_icon":"II","family_label":"稠密预测与医学分割：从像素输出到自配置系统","archetype":"dense_prediction_with_skips","archetype_en":"dense_prediction_with_skips","accent":"#145E75","fig_badge":"Figure 3 · PDF p.5","fig_href":"https://openaccess.thecvf.com/content_cvpr_2015/html/Long_Fully_Convolutional_Networks_2015_CVPR_paper.html","core_mech":"FC→Conv 的整图 dense prediction，加 pool3/pool4 分数级 skip fusion。","core_mech_en":"Converts image-level FC layers into 1×1 convolutions for arbitrary-size dense prediction with pool3/pool4 skip score fusion.","input_desc":"任意尺寸 2D 图像","input_en":"Arbitrary-size 2D image","output_desc":"与输入对齐的像素级类别 logits","output_en":"Pixel-aligned semantic class probability map","form_title":"核心公式 · FCN-8s 的三级分数图跳接融合","form_title_en":"Core Formalism · FCN-8s Multi-Stride Score Map Skip Fusion","nodes":[{"name":"卷积 Backbone","desc":"VGG 式卷积与池化逐级生成 pool3、pool4 和深层语义特征。","name_en":"convolution Backbone","desc_en":"Ingests arbitrary-size 2d image and prepares initial tensor representations (convolution Backbone)."},{"name":"FC→Conv","desc":"把分类器全连接层改写为卷积，使网络可处理任意尺寸输入。","name_en":"FC→Conv","desc_en":"Executes FC→Conv to extract primary structural features and establish spatial/sequence encoding."},{"name":"Score32","desc":"在最深低分辨率特征上预测粗语义分数图。","name_en":"Score32","desc_en":"Performs Score32 within the core dense prediction with skips computation pathway."},{"name":"2× 上采样","desc":"learned deconvolution 将粗分数恢复到 pool4 尺度。","name_en":"2× upsampling","desc_en":"Performs 2× upsampling within the core dense prediction with skips computation pathway."},{"name":"Pool4 Score","desc":"用 1×1 Conv 把中层 pool4 特征映射为类别分数。","name_en":"Pool4 Score","desc_en":"Performs Pool4 Score within the core dense prediction with skips computation pathway."},{"name":"FCN-16s 融合","desc":"深层语义分数与 pool4 分数逐元素相加。","name_en":"FCN-16s fusion","desc_en":"Performs FCN-16s fusion within the core dense prediction with skips computation pathway."},{"name":"再 2× 上采样","desc":"把融合结果提升到 pool3 尺度。","name_en":"2× upsampling","desc_en":"Performs 2× upsampling within the core dense prediction with skips computation pathway."},{"name":"Pool3 Score","desc":"较浅层特征提供更细空间定位。","name_en":"Pool3 Score","desc_en":"Performs Pool3 Score within the core dense prediction with skips computation pathway."},{"name":"FCN-8s 融合","desc":"加入 pool3 分数，形成更精细的类别响应。","name_en":"FCN-8s fusion","desc_en":"Applies FCN-8s fusion to project aggregated representations toward the target task head."},{"name":"8× 上采样","desc":"将融合分数恢复到原图并输出逐像素预测。","name_en":"8× upsampling","desc_en":"Produces pixel-aligned semantic class probability map via 8× upsampling."}],"design_principles":["把分类网络完全卷积化后，可一次前向计算整图 dense prediction。","FCN-16s/8s 用浅层 skip score 补偿深层下采样造成的定位损失。","learned deconvolution 学习上采样核，但浅深特征只做分数相加，表达仍较粗。"],"design_principles_en":["Core Hypothesis: Transform fully connected layers into convolutions and append transposed-convolution upsampling for end-to-end pixel-wise training.","Architectural Delta: Learned deconvolution combined with multi-scale coarse-to-fine skip score fusion (FCN-32s → FCN-16s → FCN-8s).","Mathematical Formalism: FCN-8s Multi-Stride Score Map Skip Fusion."],"med_apps":["它是 U-Net 等医学 encoder–decoder 的直接概念祖先。","对精细边界和小结构，FCN 的稀疏 skip 与粗上采样通常不如对称解码器。"],"med_apps_en":["Clinical Translation: Direct progenitor of U-Net and all modern medical encoder–decoder segmentation networks.","Evidence & Safety Boundary: Foundational dense-prediction paradigm; asymmetric score-only upsampling is superseded by symmetric U-Net decoders."],"attrs":{"上一代瓶颈":"分类网络只能给图级标签，逐 patch 推理低效且边界粗","核心想法":"将分类 CNN 的全连接层卷积化，端到端输出像素级预测","关键改进":"learned deconvolution，并在 FCN-16s/8s 中逐步加入浅深特征 skip fusion","医学适配":"是 U-Net 等医学 encoder-decoder 分割网络的直接祖先","适用范围与证据":"范式基础；具体结构已被更强解码器替代"},"attrs_en":{"上一代瓶颈":"Classification CNNs produced only image-level labels; sliding-window patch classification was redundant and boundary-coarse.","核心想法":"Transform fully connected layers into convolutions and append transposed-convolution upsampling for end-to-end pixel-wise training.","关键改进":"Learned deconvolution combined with multi-scale coarse-to-fine skip score fusion (FCN-32s → FCN-16s → FCN-8s).","医学适配":"Direct progenitor of U-Net and all modern medical encoder–decoder segmentation networks.","适用范围与证据":"Foundational dense-prediction paradigm; asymmetric score-only upsampling is superseded by symmetric U-Net decoders."},"paper_title":"Fully Convolutional Networks for Semantic Segmentation","paper_url":"https://openaccess.thecvf.com/content_cvpr_2015/html/Long_Fully_Convolutional_Networks_2015_CVPR_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/shelhamer/fcn.berkeleyvision.org","has_code":true,"image":"assets/944c6cfd4384d2092854.avif"},{"id":"architecture_model_006_u_net","num":6,"num_str":"006","year":2015,"year_str":"2015","venue":"MICCAI","venue_group":"miccai","era_group":"era1","title":"U-Net","family_id":"models_dense_segmentation","family_code":"02","family_short":"稠密预测与医学分割","family_en":"Dense Segmentation","family_icon":"II","family_label":"稠密预测与医学分割：从像素输出到自配置系统","archetype":"u_shaped_encoder_decoder","archetype_en":"u_shaped_encoder_decoder","accent":"#145E75","fig_badge":"Figure 1 · PDF p.2","fig_href":"https://doi.org/10.1007/978-3-319-24574-4_28","core_mech":"对称 U 形多尺度解码器与 encoder–decoder 同尺度 concat long skips。","core_mech_en":"Symmetric U-shaped multi-scale decoder coupled with same-scale encoder–decoder channel concatenation long skips.","input_desc":"2D 生物医学图像","input_en":"2D biomedical microscopy or radiological image","output_desc":"逐像素前景/多类别分割图","output_en":"Pixel-accurate foreground or multi-class segmentation map","form_title":"核心公式 · U-Net 同尺度编码特征拼接到解码器","form_title_en":"Core Formalism · U-Net Same-Scale Feature Concatenation Across Contraction and Expansion Paths","nodes":[{"name":"输入图像","desc":"原始实现结合强弹性形变增强以扩充少标注数据。","name_en":"Input Image","desc_en":"Ingests 2d biomedical microscopy or radiological image and prepares initial tensor representations (Input Image)."},{"name":"高分辨率 Encoder","desc":"重复 3×3 Conv 提取边缘、纹理与小结构位置。","name_en":"Encoder","desc_en":"Executes Encoder to extract primary structural features and establish spatial/sequence encoding."},{"name":"下采样金字塔","desc":"max pooling 逐级扩大视野并增加通道。","name_en":"downsampling","desc_en":"Performs downsampling within the core u shaped encoder decoder computation pathway."},{"name":"语义瓶颈","desc":"最低分辨率层编码大范围上下文与任务语义。","name_en":"Stage 04","desc_en":"Performs Stage 04 within the core u shaped encoder decoder computation pathway."},{"name":"Up-conv","desc":"转置卷积提升空间分辨率并降低通道。","name_en":"Up-conv","desc_en":"Performs Up-conv within the core u shaped encoder decoder computation pathway."},{"name":"同尺度 Concat","desc":"裁剪/对齐 encoder 特征后与 decoder 特征按通道拼接。","name_en":"Concat","desc_en":"Performs Concat within the core u shaped encoder decoder computation pathway."},{"name":"Decoder Conv","desc":"融合定位与语义后逐级细化边界。","name_en":"Decoder Conv","desc_en":"Applies Decoder Conv to project aggregated representations toward the target task head."},{"name":"1×1 分割头","desc":"将最终特征映射为每像素类别 logits。","name_en":"1×1","desc_en":"Produces pixel-accurate foreground or multi-class segmentation map via 1×1."}],"design_principles":["编码器用下采样获得上下文，解码器负责恢复空间定位。","同尺度长跳连绕过瓶颈传递边缘、纹理和小结构坐标。","concat 而非相加允许解码器重新选择浅层与深层证据。"],"design_principles_en":["Core Hypothesis: Pair a contracting semantic encoder with a symmetric expanding decoder linked by same-scale feature concatenation skips.","Architectural Delta: Concatenation long skips, distance-weighted boundary loss, and elastic deformations tailored for few-shot biomedical segmentation.","Mathematical Formalism: U-Net Same-Scale Feature Concatenation Across Contraction and Expansion Paths."],"med_apps":["器官、病灶和细胞分割的强拓扑基线，后续多数变体仍保留其信息路径。","长跳连也会传递背景纹理；semantic gap、spacing 与完整训练 pipeline 仍需单独处理。"],"med_apps_en":["Clinical Translation: Universal infrastructure of biomedical segmentation; the U-shaped topology is also standard across denoising, reconstruction, and diffusion.","Evidence & Safety Boundary: Cornerstone domain infrastructure; mandatory to master from scratch and retain as a primary baseline."],"attrs":{"上一代瓶颈":"FCN 上采样边界粗，生物医学标注稀缺","核心想法":"对称 encoder-decoder 与同尺度长跳连联合语义和精确定位","关键改进":"concat skips、强弹性增强与面向少样本的 U 形多尺度拓扑","医学适配":"成为医学分割基础设施，U-shaped encoder-decoder 也被广泛复用于重建和去噪","适用范围与证据":"领域基础设施；必须从零实现和保留为强基线"},"attrs_en":{"上一代瓶颈":"FCN upsampling lost fine boundary localization, while annotated biomedical datasets were small.","核心想法":"Pair a contracting semantic encoder with a symmetric expanding decoder linked by same-scale feature concatenation skips.","关键改进":"Concatenation long skips, distance-weighted boundary loss, and elastic deformations tailored for few-shot biomedical segmentation.","医学适配":"Universal infrastructure of biomedical segmentation; the U-shaped topology is also standard across denoising, reconstruction, and diffusion.","适用范围与证据":"Cornerstone domain infrastructure; mandatory to master from scratch and retain as a primary baseline."},"paper_title":"U-Net: Convolutional Networks for Biomedical Image Segmentation","paper_url":"https://doi.org/10.1007/978-3-319-24574-4_28","code_label":"作者/机构官方实现","code_url":"https://lmb.informatik.uni-freiburg.de/lmbsoft/unet/","has_code":true,"image":"assets/6416c4c4d626d329ec7e.avif"},{"id":"architecture_model_007_3d_u_net","num":7,"num_str":"007","year":2016,"year_str":"2016","venue":"MICCAI","venue_group":"miccai","era_group":"era2","title":"3D U-Net","family_id":"models_dense_segmentation","family_code":"02","family_short":"稠密预测与医学分割","family_en":"Dense Segmentation","family_icon":"II","family_label":"稠密预测与医学分割：从像素输出到自配置系统","archetype":"volumetric_u_net","archetype_en":"volumetric_u_net","accent":"#145E75","fig_badge":"Figure 2 · PDF p.4","fig_href":"https://doi.org/10.1007/978-3-319-46723-8_49","core_mech":"把 U-Net 的卷积、池化、上采样和 long skip 全部扩展为原生 3D，并支持稀疏切片监督。","core_mech_en":"Extends all U-Net convolutions, pooling, upsampling, and long skips to native 3D tensors with support for sparse slice annotations.","input_desc":"3D CT/MRI 子体积或完整体数据","input_en":"3D CT/MRI sub-volume or whole volumetric scan","output_desc":"稠密 3D 体素分割","output_en":"Dense 3D voxel-wise segmentation volume","form_title":"核心公式 · 三维卷积、上采样与体积跳接","form_title_en":"Core Formalism · Volumetric 3D Convolutions, Upsampling, and 3D Skip Concatenation","nodes":[{"name":"3D Volume","desc":"输入为 C×D×H×W 体数据而非独立切片。","name_en":"3D Volume","desc_en":"Ingests 3d ct/mri sub-volume or whole volumetric scan and prepares initial tensor representations (3D Volume)."},{"name":"3D Conv Encoder","desc":"3×3×3 卷积同时聚合层内与层间邻域。","name_en":"3D Conv Encoder","desc_en":"Executes 3D Conv Encoder to extract primary structural features and establish spatial/sequence encoding."},{"name":"3D Pool","desc":"体素三轴下采样扩大体积感受野。","name_en":"3D Pool","desc_en":"Performs 3D Pool within the core volumetric u net computation pathway."},{"name":"体语义瓶颈","desc":"编码器最低尺度建模器官形状与跨切片连续性。","name_en":"Stage 04","desc_en":"Performs Stage 04 within the core volumetric u net computation pathway."},{"name":"3D Up-conv","desc":"三维转置卷积逐级恢复体素分辨率。","name_en":"3D Up-conv","desc_en":"Performs 3D Up-conv within the core volumetric u net computation pathway."},{"name":"3D Skip Concat","desc":"同尺度体特征跨越瓶颈拼接到解码器。","name_en":"3D Skip Concat","desc_en":"Performs 3D Skip Concat within the core volumetric u net computation pathway."},{"name":"3D Decoder","desc":"融合体上下文与高分辨率边界。","name_en":"3D Decoder","desc_en":"Performs 3D Decoder within the core volumetric u net computation pathway."},{"name":"Voxel Head","desc":"1×1×1 卷积输出每体素类别。","name_en":"Voxel Head","desc_en":"Applies Voxel Head to project aggregated representations toward the target task head."},{"name":"稀疏监督","desc":"只在有标注切片/体素处计算监督损失。","name_en":"Stage 09","desc_en":"Produces dense 3d voxel-wise segmentation volume via Stage 09."}],"design_principles":["所有空间算子原生三维化，显式利用 through-plane continuity。","3D long skip 同时传递体边界与局部形状信息。","训练目标可只作用于稀疏标注位置，而前向仍输出完整体分割。"],"design_principles_en":["Core Hypothesis: Generalize U-Net operators to native 3D volumetric tensors and train with weighted loss on sparsely annotated slices.","Architectural Delta: 3D convolutions, 3D batch normalization, smooth 3D elastic augmentations, and dense volumetric inference.","Mathematical Formalism: Volumetric 3D Convolutions, Upsampling, and 3D Skip Concatenation."],"med_apps":["适合近各向同性 CT/MRI 中形状和连通性关键的器官/病灶任务。","显存、patch 截断和各向异性会改变真实物理视野，不能只报告 voxel patch 大小。"],"med_apps_en":["Clinical Translation: Foundational parent of volumetric CT, MRI, and microscopy segmentation pipelines.","Evidence & Safety Boundary: Canonical 3D baseline; bounded by GPU activation memory, patch field-of-view, and anisotropic slice spacing."],"attrs":{"上一代瓶颈":"逐切片 2D 网络忽略层间上下文和体结构连续性","核心想法":"把 U-Net 全部算子扩展为 3D，并从稀疏标注切片学习体素级输出","关键改进":"3D 卷积、3D elastic augmentation 与体素级 dense prediction","医学适配":"奠定 CT/MRI 体分割母体，支持稀疏体标注","适用范围与证据":"经典 3D 基线；显存、patch context 与各向异性仍是瓶颈"},"attrs_en":{"上一代瓶颈":"Slice-by-slice 2D segmentation ignores inter-slice z-axis continuity and 3D anatomical topology.","核心想法":"Generalize U-Net operators to native 3D volumetric tensors and train with weighted loss on sparsely annotated slices.","关键改进":"3D convolutions, 3D batch normalization, smooth 3D elastic augmentations, and dense volumetric inference.","医学适配":"Foundational parent of volumetric CT, MRI, and microscopy segmentation pipelines.","适用范围与证据":"Canonical 3D baseline; bounded by GPU activation memory, patch field-of-view, and anisotropic slice spacing."},"paper_title":"3D U-Net: Learning Dense Volumetric Segmentation from Sparse Annotation","paper_url":"https://doi.org/10.1007/978-3-319-46723-8_49","code_label":"未提供官方实现","code_url":"","has_code":false,"image":"assets/f3e72a0c35b6fd3cf563.avif"},{"id":"architecture_model_008_v_net","num":8,"num_str":"008","year":2016,"year_str":"2016","venue":"3DV","venue_group":"miccai","era_group":"era2","title":"V-Net","family_id":"models_dense_segmentation","family_code":"02","family_short":"稠密预测与医学分割","family_en":"Dense Segmentation","family_icon":"II","family_label":"稠密预测与医学分割：从像素输出到自配置系统","archetype":"residual_volumetric_segmentation","archetype_en":"residual_volumetric_segmentation","accent":"#145E75","fig_badge":"Figure 2 · PDF p.3","fig_href":"https://doi.org/10.1109/3DV.2016.79","core_mech":"3D residual FCN 与直接可微 Dice overlap objective 的结合。","core_mech_en":"Volumetric 3D residual encoder–decoder trained directly with a differentiable Dice overlap objective.","input_desc":"3D 医学体数据","input_en":"3D medical imaging volume","output_desc":"前景概率体或多类体素分割","output_en":"Foreground probability volume or multi-class voxel segmentation","form_title":"核心公式 · V-Net 直接优化体素级 Dice 重叠","form_title_en":"Core Formalism · Direct Optimization of Differentiable Volumetric Dice Overlap","nodes":[{"name":"3D 输入","desc":"体数据直接进入全卷积分割网络。","name_en":"3D input","desc_en":"Ingests 3d medical imaging volume and prepares initial tensor representations (3D input)."},{"name":"Residual 3D Stage","desc":"多层 3D Conv 的输出与 stage 输入相加。","name_en":"Residual 3D Stage","desc_en":"Executes Residual 3D Stage to extract primary structural features and establish spatial/sequence encoding."},{"name":"Strided Conv","desc":"用可学习 stride-2 卷积替代固定池化完成降采样。","name_en":"Strided Conv","desc_en":"Performs Strided Conv within the core residual volumetric segmentation computation pathway."},{"name":"深层体上下文","desc":"低分辨率残差块聚合大范围三维结构。","name_en":"Stage 04","desc_en":"Performs Stage 04 within the core residual volumetric segmentation computation pathway."},{"name":"3D Deconv","desc":"转置卷积逐级恢复体素尺度。","name_en":"3D Deconv","desc_en":"Performs 3D Deconv within the core residual volumetric segmentation computation pathway."},{"name":"Encoder Skip","desc":"编码器特征与对应解码尺度融合。","name_en":"Encoder Skip","desc_en":"Performs Encoder Skip within the core residual volumetric segmentation computation pathway."},{"name":"体素概率头","desc":"全卷积输出前景概率体。","name_en":"voxel","desc_en":"Applies voxel to project aggregated representations toward the target task head."},{"name":"Dice Objective","desc":"直接优化预测与真值集合的重叠，而非被背景主导的逐体素准确率。","name_en":"Dice Objective","desc_en":"Produces foreground probability volume or multi-class voxel segmentation via Dice Objective."}],"design_principles":["残差 3D 编解码器同时缓解深层优化与体数据上下文建模困难。","strided convolution 让下采样本身可学习。","Dice 型目标以集合重叠归一化前景规模，缓解极端类别不平衡。"],"design_principles_en":["Core Hypothesis: Combine a 3D residual convolutional encoder–decoder with a differentiable soft Dice loss.","Architectural Delta: Strided 3D convolutions replacing pooling, block-wise residual shortcuts, and direct overlap optimization.","Mathematical Formalism: Direct Optimization of Differentiable Volumetric Dice Overlap."],"med_apps":["V-Net 是理解 3D residual segmentation 与 Dice-family loss 的经典节点。","Dice 高并不保证边界距离、拓扑或小病灶检出，仍应联合 HD95/NSD 和 lesion-wise 指标。"],"med_apps_en":["Clinical Translation: Popularized Dice-family losses (Dice + CE) as the standard training objective for medical volumetric segmentation.","Evidence & Safety Boundary: Classic 3D baseline; Dice loss alone remains insensitive to boundary Hausdorff outliers and topological breaks."],"attrs":{"上一代瓶颈":"3D 前景极小，交叉熵易被背景主导","核心想法":"3D residual FCN 直接优化 Dice 型目标","关键改进":"残差 3D 编解码器与面向重叠度的 Dice loss","医学适配":"推动 Dice 型目标在医学体分割中的普及","适用范围与证据":"经典强基线；并非唯一 3D 默认网络"},"attrs_en":{"上一代瓶颈":"Small 3D anatomical targets occupy a tiny fraction of voxels, causing standard cross-entropy to collapse toward background.","核心想法":"Combine a 3D residual convolutional encoder–decoder with a differentiable soft Dice loss.","关键改进":"Strided 3D convolutions replacing pooling, block-wise residual shortcuts, and direct overlap optimization.","医学适配":"Popularized Dice-family losses (Dice + CE) as the standard training objective for medical volumetric segmentation.","适用范围与证据":"Classic 3D baseline; Dice loss alone remains insensitive to boundary Hausdorff outliers and topological breaks."},"paper_title":"V-Net: Fully Convolutional Neural Networks for Volumetric Medical Image Segmentation","paper_url":"https://doi.org/10.1109/3DV.2016.79","code_label":"未提供官方实现","code_url":"","has_code":false,"image":"assets/edebfde2e5b359a60fd3.avif"},{"id":"architecture_model_009_nnu_net","num":9,"num_str":"009","year":2021,"year_str":"2021","venue":"Nature Methods","venue_group":"nature","era_group":"era3","title":"nnU-Net","family_id":"models_dense_segmentation","family_code":"02","family_short":"稠密预测与医学分割","family_en":"Dense Segmentation","family_icon":"II","family_label":"稠密预测与医学分割：从像素输出到自配置系统","archetype":"self_configuring_pipeline","archetype_en":"self_configuring_pipeline","accent":"#145E75","fig_badge":"Figure 1 · PDF p.4","fig_href":"https://doi.org/10.1038/s41592-020-01008-z","core_mech":"dataset fingerprint 驱动的自配置、交叉验证与推理后处理闭环，而不是单一新算子。","core_mech_en":"Dataset-fingerprint-driven self-configuration, 5-fold cross-validation ensembling, and post-processing loop rather than a new neural block.","input_desc":"带影像、标签与 spacing 元数据的新分割数据集","input_en":"New medical segmentation dataset with raw images, masks, and physical voxel spacing metadata","output_desc":"经交叉验证选择和后处理的可复现分割系统","output_en":"Self-configured, cross-validated, and post-processed end-to-end segmentation system","form_title":"核心公式 · 数据指纹驱动配置并集成五折预测","form_title_en":"Core Formalism · Dataset-Fingerprint Rule Engine & 5-Fold Sliding-Window Ensemble","nodes":[{"name":"原始数据集","desc":"影像、标签、模态、尺寸与物理 spacing 构成配置输入。","name_en":"Stage 01","desc_en":"Ingests new medical segmentation dataset with raw images, masks, and physical voxel spacing metadata and prepares initial tensor representations (Stage 01)."},{"name":"Dataset Fingerprint","desc":"统计强度、形状、spacing、类别与病例规模。","name_en":"Dataset Fingerprint","desc_en":"Executes Dataset Fingerprint to extract primary structural features and establish spatial/sequence encoding."},{"name":"Experiment Planner","desc":"按显存预算推导 target spacing、patch、batch、kernel 和 pooling。","name_en":"Experiment Planner","desc_en":"Performs Experiment Planner within the core self configuring pipeline computation pathway."},{"name":"2D/3D/Cascade","desc":"生成适用的 2D、3D full-resolution 与低分辨率级联配置。","name_en":"2D/3D/Cascade","desc_en":"Performs 2D/3D/Cascade within the core self configuring pipeline computation pathway."},{"name":"预处理","desc":"重采样、裁剪、归一化并缓存可复现实验输入。","name_en":"Stage 05","desc_en":"Performs Stage 05 within the core self configuring pipeline computation pathway."},{"name":"U-Net 训练","desc":"CE+Dice、foreground sampling、深监督和强增强构成统一 recipe。","name_en":"U-Net training","desc_en":"Performs U-Net training within the core self configuring pipeline computation pathway."},{"name":"5-fold CV","desc":"各配置交叉验证并保存 fold 模型与 out-of-fold 预测。","name_en":"5-fold CV","desc_en":"Performs 5-fold CV within the core self configuring pipeline computation pathway."},{"name":"滑窗 + TTA","desc":"重叠滑窗、Gaussian weighting 与镜像 TTA 生成全体预测。","name_en":"+ TTA","desc_en":"Performs + TTA within the core self configuring pipeline computation pathway."},{"name":"后处理选择","desc":"仅在交叉验证证实有益时采用连通域等后处理和 ensemble。","name_en":"Stage 09","desc_en":"Applies Stage 09 to project aggregated representations toward the target task head."},{"name":"最终分割","desc":"输出配置、权重、预测与完整可复现 pipeline。","name_en":"Final Segmentation","desc_en":"Produces self-configured, cross-validated, and post-processed end-to-end segmentation system via Final Segmentation."}],"design_principles":["模型配置由数据集 fingerprint 和显存约束推导，而非固定网络图。","把预处理、采样、增强、loss、推理和后处理纳入同一可复现对象。","通过交叉验证选择配置与后处理，减少单次 split 和手工调参偏差。"],"design_principles_en":["Core Hypothesis: Automate preprocessing, network topology, patch/batch sizing, sampling, training schedule, and post-processing directly from dataset statistics.","Architectural Delta: Couples rule-based domain heuristics (spacing, anisotropy, modality normalization) with empirical cross-validation model selection.","Mathematical Formalism: Dataset-Fingerprint Rule Engine & 5-Fold Sliding-Window Ensemble."],"med_apps":["它是大多数新医学分割方法应在相同数据条件下比较的系统级强基线。","其优势不能被简单归因于 U-Net block；公平消融必须锁定完整 pipeline。"],"med_apps_en":["Clinical Translation: Serves as the undisputed reproducible infrastructure across multi-organ and multi-modality medical segmentation benchmarks.","Evidence & Safety Boundary: Mandatory first-line baseline against which any newly proposed segmentation architecture must be benchmarked."],"attrs":{"上一代瓶颈":"新数据集依赖大量专家手调，论文比较常被 pipeline 差异混淆","核心想法":"根据数据集 fingerprint 自动配置预处理、网络、采样、训练与推理","关键改进":"规则与经验结合选择 spacing、patch/batch、2D/3D/cascade、增强和后处理","医学适配":"在多器官、多模态分割中成为统一、可复现的基础设施","适用范围与证据":"在适用的数据与任务设置下，是新分割方法应比较的必做基线"},"attrs_en":{"上一代瓶颈":"Segmentation performance was dominated by manual per-dataset tuning, confounding architectural comparisons across papers.","核心想法":"Automate preprocessing, network topology, patch/batch sizing, sampling, training schedule, and post-processing directly from dataset statistics.","关键改进":"Couples rule-based domain heuristics (spacing, anisotropy, modality normalization) with empirical cross-validation model selection.","医学适配":"Serves as the undisputed reproducible infrastructure across multi-organ and multi-modality medical segmentation benchmarks.","适用范围与证据":"Mandatory first-line baseline against which any newly proposed segmentation architecture must be benchmarked."},"paper_title":"nnU-Net: a self-configuring method for deep learning-based biomedical image segmentation","paper_url":"https://doi.org/10.1038/s41592-020-01008-z","code_label":"作者/机构官方实现","code_url":"https://github.com/MIC-DKFZ/nnUNet","has_code":true,"image":"assets/6cc1dd0b5fc97779ac41.avif"},{"id":"architecture_model_010_unetr","num":10,"num_str":"010","year":2022,"year_str":"2022","venue":"WACV","venue_group":"cv","era_group":"era3","title":"UNETR","family_id":"models_dense_segmentation","family_code":"02","family_short":"稠密预测与医学分割","family_en":"Dense Segmentation","family_icon":"II","family_label":"稠密预测与医学分割：从像素输出到自配置系统","archetype":"vit_cnn_3d_decoder","archetype_en":"vit_cnn_3d_decoder","accent":"#145E75","fig_badge":"Figure 2 · PDF p.4","fig_href":"https://openaccess.thecvf.com/content/WACV2022/html/Hatamizadeh_UNETR_Transformers_for_3D_Medical_Image_Segmentation_WACV_2022_paper.html","core_mech":"多深度 ViT token skips 连接到卷积 U 形解码器的 3D hybrid。","core_mech_en":"3D hybrid segmentation architecture connecting multi-depth Vision Transformer token representations to a convolutional U-shaped decoder.","input_desc":"3D 医学体数据","input_en":"3D medical imaging volume","output_desc":"高分辨率 3D 语义分割","output_en":"High-resolution 3D volumetric semantic segmentation","form_title":"核心公式 · ViT 多深度 token 投影到 CNN 解码器","form_title_en":"Core Formalism · Multi-Depth 3D ViT Token Projection into Convolutional Decoder Stages","nodes":[{"name":"3D Volume","desc":"体数据按非重叠 3D patch 切分。","name_en":"3D Volume","desc_en":"Ingests 3d medical imaging volume and prepares initial tensor representations (3D Volume)."},{"name":"3D Patch Tokens","desc":"每个体 patch 线性投影为 token，并加入位置编码。","name_en":"3D Patch Tokens","desc_en":"Executes 3D Patch Tokens to extract primary structural features and establish spatial/sequence encoding."},{"name":"ViT L3","desc":"浅层 token 保留较多局部与位置细节。","name_en":"ViT L3","desc_en":"Performs ViT L3 within the core vit cnn 3d decoder computation pathway."},{"name":"ViT L6/L9","desc":"中层全局 self-attention 逐步形成体积语义。","name_en":"ViT L6/L9","desc_en":"Performs ViT L6/L9 within the core vit cnn 3d decoder computation pathway."},{"name":"ViT L12","desc":"深层 token 具有一层可达全局的体上下文。","name_en":"ViT L12","desc_en":"Performs ViT L12 within the core vit cnn 3d decoder computation pathway."},{"name":"Token→3D Map","desc":"不同深度 token reshape，并经卷积投影为多尺度体特征。","name_en":"Token→3D Map","desc_en":"Performs Token→3D Map within the core vit cnn 3d decoder computation pathway."},{"name":"CNN Decoder","desc":"转置卷积逐级上采样并融合 Transformer skip。","name_en":"CNN Decoder","desc_en":"Performs CNN Decoder within the core vit cnn 3d decoder computation pathway."},{"name":"浅层 CNN Skip","desc":"直接从输入卷积路径补充最高分辨率定位信息。","name_en":"CNN Skip","desc_en":"Applies CNN Skip to project aggregated representations toward the target task head."},{"name":"3D Seg Head","desc":"卷积头输出每体素类别 logits。","name_en":"3D Seg Head","desc_en":"Produces high-resolution 3d volumetric semantic segmentation via 3D Seg Head."}],"design_principles":["ViT encoder 让远隔体 patch 可通过 self-attention 直接交换信息。","不同 Transformer 深度充当 U-Net 式 skip 层级，而非只用最终 CLS 表示。","CNN decoder 重新注入局部上采样和高分辨率定位偏置。"],"design_principles_en":["Core Hypothesis: Tokenize 3D volumes into non-overlapping 3D patches processed by a ViT encoder, projecting intermediate layers into a 3D CNN decoder.","Architectural Delta: Multi-depth reshape-and-deconvolution skip pathways bridging sequence-level ViT tokens back to spatial voxel grids.","Mathematical Formalism: Multi-Depth 3D ViT Token Projection into Convolutional Decoder Stages."],"med_apps":["适合需要远程器官关系的 3D 分割研究，但通常依赖足够数据或预训练。","patch tokenization 与全局 O(N²) attention 会压缩小病灶并限制可用体素分辨率。"],"med_apps_en":["Clinical Translation: Pioneered global Transformer encoders for 3D multi-organ CT/MRI segmentation.","Evidence & Safety Boundary: Important hybrid milestone, though flat 3D patch attention incurs high quadratic compute and data hunger from scratch."],"attrs":{"上一代瓶颈":"纯卷积的显式全局关系有限","核心想法":"以 3D patch token 的 ViT encoder 接 U 形 CNN decoder","关键改进":"从不同 Transformer 深度向 decoder 建立多尺度 skip","医学适配":"把全局 Transformer encoder 系统引入 3D 医学分割","适用范围与证据":"重要范式节点；从头训练和二次注意力成本明显"},"attrs_en":{"上一代瓶颈":"Pure 3D CNN encoders have restricted explicit global receptive fields across large volumetric scans.","核心想法":"Tokenize 3D volumes into non-overlapping 3D patches processed by a ViT encoder, projecting intermediate layers into a 3D CNN decoder.","关键改进":"Multi-depth reshape-and-deconvolution skip pathways bridging sequence-level ViT tokens back to spatial voxel grids.","医学适配":"Pioneered global Transformer encoders for 3D multi-organ CT/MRI segmentation.","适用范围与证据":"Important hybrid milestone, though flat 3D patch attention incurs high quadratic compute and data hunger from scratch."},"paper_title":"UNETR: Transformers for 3D Medical Image Segmentation","paper_url":"https://openaccess.thecvf.com/content/WACV2022/html/Hatamizadeh_UNETR_Transformers_for_3D_Medical_Image_Segmentation_WACV_2022_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/Project-MONAI/research-contributions","has_code":true,"image":"assets/1c0267ddbd9fd6876f83.avif"},{"id":"architecture_model_011_swin_unetr__ssl","num":11,"num_str":"011","year":2022,"year_str":"2022","venue":"CVPR","venue_group":"cv","era_group":"era3","title":"Swin UNETR (SSL)","family_id":"models_dense_segmentation","family_code":"02","family_short":"稠密预测与医学分割","family_en":"Dense Segmentation","family_icon":"II","family_label":"稠密预测与医学分割：从像素输出到自配置系统","archetype":"hierarchical_3d_transformer_ssl","archetype_en":"hierarchical_3d_transformer_ssl","accent":"#145E75","fig_badge":"Figure 2 · PDF p.3","fig_href":"https://openaccess.thecvf.com/content/CVPR2022/html/Tang_Self-Supervised_Pre-Training_of_Swin_Transformers_for_3D_Medical_Image_Analysis_CVPR_2022_paper.html","core_mech":"3D shifted-window hierarchy 与旋转、重建、对比联合自监督的 Swin UNETR。","core_mech_en":"3D shifted-window hierarchical Swin encoder coupled to a U-shaped CNN decoder and pretrained with multi-task 3D self-supervision.","input_desc":"未标注 3D CT 子体积；微调时输入带标签体数据","input_en":"Unlabeled 3D CT sub-volumes for pretraining; labeled 3D volumes for fine-tuning","output_desc":"预训练层级编码器及下游 3D 分割","output_en":"Pretrained hierarchical 3D Swin encoder and dense downstream volumetric segmentation","form_title":"核心公式 · Swin UNETR 的三任务三维自监督目标","form_title_en":"Core Formalism · Joint 3D Masked Inpainting, Rotation, and Contrastive Self-Supervision","nodes":[{"name":"3D CT Crop","desc":"从体数据采样子体积并构造自监督视图。","name_en":"3D CT Crop","desc_en":"Ingests unlabeled 3d ct sub-volumes for pretraining; labeled 3d volumes for fine-tuning and prepares initial tensor representations (3D CT Crop)."},{"name":"3D Patch Embed","desc":"将局部体块投影为层级 Transformer 的初始 token 网格。","name_en":"3D Patch Embed","desc_en":"Executes 3D Patch Embed to extract primary structural features and establish spatial/sequence encoding."},{"name":"Window MSA","desc":"在固定 3D 窗口内计算 self-attention，避免全局二次矩阵。","name_en":"Window MSA","desc_en":"Performs Window MSA within the core hierarchical 3d transformer ssl computation pathway."},{"name":"Shifted Window","desc":"下一块平移窗口，使信息跨原窗口边界传播。","name_en":"Shifted Window","desc_en":"Performs Shifted Window within the core hierarchical 3d transformer ssl computation pathway."},{"name":"Patch Merging","desc":"逐级减小 D/H/W 并增加通道，形成多尺度体金字塔。","name_en":"Patch Merging","desc_en":"Performs Patch Merging within the core hierarchical 3d transformer ssl computation pathway."},{"name":"三类 SSL Heads","desc":"联合旋转预测、局部重建/遮挡恢复与对比表示学习。","name_en":"SSL Heads","desc_en":"Performs SSL Heads within the core hierarchical 3d transformer ssl computation pathway."},{"name":"Swin Encoder","desc":"预训练后的四级体特征作为下游共享编码器。","name_en":"Swin Encoder","desc_en":"Performs Swin Encoder within the core hierarchical 3d transformer ssl computation pathway."},{"name":"UNETR Decoder","desc":"卷积上采样并融合各 Swin stage 的 skip 特征。","name_en":"UNETR Decoder","desc_en":"Applies UNETR Decoder to project aggregated representations toward the target task head."},{"name":"3D Mask","desc":"分割头输出体素级类别。","name_en":"3D Mask","desc_en":"Produces pretrained hierarchical 3d swin encoder and dense downstream volumetric segmentation via 3D Mask."}],"design_principles":["固定窗口把 3D attention 的成本限制在局部 token 集合内。","shifted windows 与 patch merging 分别解决跨窗通信和层级多尺度。","先在大量未标注 CT 上联合多个体数据 pretext task，再微调 dense prediction。"],"design_principles_en":["Core Hypothesis: Replace flat ViT with a 3D shifted-window Swin pyramid and pretrain on 5,050 unlabeled volumetric CT scans.","Architectural Delta: 3D W-MSA / SW-MSA window hierarchy, patch merging, and tri-objective 3D SSL (inpainting + rotation + contrastive).","Mathematical Formalism: Joint 3D Masked Inpainting, Rotation, and Contrastive Self-Supervision."],"med_apps":["适合利用大量未标注 CT 预训练层级 3D encoder，再迁移到有限标注分割。","窗口、patch 和预训练 recipe 均是性能来源；从头训练时不能把差异只归因于 Transformer。"],"med_apps_en":["Clinical Translation: Standard 3D Transformer segmentation and pretraining baseline within the MONAI ecosystem.","Evidence & Safety Boundary: Valuable when leveraging pretrained weights; from-scratch training under matched recipes does not consistently beat modern 3D CNNs."],"attrs":{"上一代瓶颈":"平坦 UNETR token 序列昂贵且缺自然多尺度，3D 标注有限","核心想法":"层级 shifted-window Transformer 与 U 形解码器结合，并在 5050 个 CT 上自监督预训练","关键改进":"窗口注意力、跨窗 shift、层级特征和多任务 3D 预训练","医学适配":"成为 MONAI 中重要的 3D Transformer 分割与预训练基线","适用范围与证据":"预训练时有价值；同配方从头训练未必优于现代 CNN"},"attrs_en":{"上一代瓶颈":"Flat UNETR tokens lack multi-scale spatial pyramids and scale poorly to high-resolution 3D volumes under limited labels.","核心想法":"Replace flat ViT with a 3D shifted-window Swin pyramid and pretrain on 5,050 unlabeled volumetric CT scans.","关键改进":"3D W-MSA / SW-MSA window hierarchy, patch merging, and tri-objective 3D SSL (inpainting + rotation + contrastive).","医学适配":"Standard 3D Transformer segmentation and pretraining baseline within the MONAI ecosystem.","适用范围与证据":"Valuable when leveraging pretrained weights; from-scratch training under matched recipes does not consistently beat modern 3D CNNs."},"paper_title":"Self-Supervised Pre-Training of Swin Transformers for 3D Medical Image Analysis","paper_url":"https://openaccess.thecvf.com/content/CVPR2022/html/Tang_Self-Supervised_Pre-Training_of_Swin_Transformers_for_3D_Medical_Image_Analysis_CVPR_2022_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/Project-MONAI/research-contributions","has_code":true,"image":"assets/81bc1b45af13e496bcce.avif"},{"id":"architecture_model_012_mednext","num":12,"num_str":"012","year":2023,"year_str":"2023","venue":"MICCAI","venue_group":"miccai","era_group":"era4","title":"MedNeXt","family_id":"models_dense_segmentation","family_code":"02","family_short":"稠密预测与医学分割","family_en":"Dense Segmentation","family_icon":"II","family_label":"稠密预测与医学分割：从像素输出到自配置系统","archetype":"large_kernel_3d_conv_unet","archetype_en":"large_kernel_3d_conv_unet","accent":"#145E75","fig_badge":"Figure 1(a) · PDF p.4","fig_href":"https://doi.org/10.1007/978-3-031-43901-8_39","core_mech":"贯穿 encoder、decoder 和上下采样的全 3D 大核 depthwise ConvNeXt block。","core_mech_en":"Fully 3D large-kernel depthwise ConvNeXt blocks deployed uniformly across encoder, bottleneck, decoder, and residual up/downsampling.","input_desc":"3D 医学影像 patch","input_en":"3D medical imaging patch","output_desc":"多尺度深监督的 3D 分割 logits","output_en":"Multi-scale deep-supervised 3D segmentation logits","form_title":"核心公式 · MedNeXt 大核三维 ConvNeXt 块","form_title_en":"Core Formalism · MedNeXt 3D Depthwise Separable Inverted-Bottleneck Block","nodes":[{"name":"3D Stem","desc":"将输入投影到 MedNeXt 基础通道。","name_en":"3D Stem","desc_en":"Ingests 3d medical imaging patch and prepares initial tensor representations (3D Stem)."},{"name":"k³ DWConv","desc":"大核逐通道 3D 卷积扩大感受野，k 可随配置扩展。","name_en":"k³ DWConv","desc_en":"Executes k³ DWConv to extract primary structural features and establish spatial/sequence encoding."},{"name":"GroupNorm","desc":"适应 3D 小 batch，并在通道混合前稳定激活。","name_en":"GroupNorm","desc_en":"Performs GroupNorm within the core large kernel 3d conv unet computation pathway."},{"name":"1×1×1 扩展","desc":"pointwise 卷积扩展通道后以 GELU 非线性变换。","name_en":"1×1×1","desc_en":"Performs 1×1×1 within the core large kernel 3d conv unet computation pathway."},{"name":"1×1×1 压缩","desc":"投影回块宽度并与输入做 residual add。","name_en":"1×1×1","desc_en":"Performs 1×1×1 within the core large kernel 3d conv unet computation pathway."},{"name":"Residual Down","desc":"可学习下采样块保持 MedNeXt block 语义连续。","name_en":"Residual Down","desc_en":"Performs Residual Down within the core large kernel 3d conv unet computation pathway."},{"name":"大核 Bottleneck","desc":"最低分辨率用深度与大核聚合广域 3D 上下文。","name_en":"large-kernel Bottleneck","desc_en":"Performs large-kernel Bottleneck within the core large kernel 3d conv unet computation pathway."},{"name":"Residual Up","desc":"转置卷积式 MedNeXt block 恢复分辨率。","name_en":"Residual Up","desc_en":"Performs Residual Up within the core large kernel 3d conv unet computation pathway."},{"name":"U-shape Skips","desc":"编码器同尺度特征连接到解码器，并可用 UpKern 初始化大核。","name_en":"U-shape Skips","desc_en":"Applies U-shape Skips to project aggregated representations toward the target task head."},{"name":"Seg Heads","desc":"主头和深监督头输出不同尺度分割。","name_en":"Seg Heads","desc_en":"Produces multi-scale deep-supervised 3d segmentation logits via Seg Heads."}],"design_principles":["用大核 depthwise 3D convolution 获得宽感受野，同时避免 full 3D convolution 的参数爆炸。","inverted bottleneck 将空间混合与通道混合解耦。","残差上下采样与 compound scaling 将 ConvNeXt block 扩展为完整 U 形分割系统。"],"design_principles_en":["Core Hypothesis: Generalize ConvNeXt's large-kernel depthwise inverted bottleneck into a fully 3D encoder–decoder with iterative kernel up-kernelling.","Architectural Delta: Residual inverted-bottleneck resampling layers and compound scaling across depth, width, and 3D kernel size (3³ → 5³ → 7³).","Mathematical Formalism: MedNeXt 3D Depthwise Separable Inverted-Bottleneck Block."],"med_apps":["是现代 3D CNN 强基线，适合与 UNETR、Swin UNETR 和 Mamba 模型做等预算比较。","大核版本训练时间和对 target spacing 的敏感性必须与 Dice 增益一起报告。"],"med_apps_en":["Clinical Translation: Establishes a top-performing pure 3D ConvNet baseline across large-scale unified medical segmentation benchmarks.","Evidence & Safety Boundary: Essential modern 3D CNN baseline; large 7×7×7 kernels increase training wall-clock time."],"attrs":{"上一代瓶颈":"传统 3D U-Net block 陈旧，Transformer 数据饥渴且代价高","核心想法":"把 ConvNeXt 大核 depthwise 设计系统扩展为全 3D encoder-decoder","关键改进":"残差上下采样、inverted bottleneck 与 depth/width/kernel compound scaling","医学适配":"在统一医学分割复测中形成现代强纯卷积基线","适用范围与证据":"高价值对照；大核版本训练较慢"},"attrs_en":{"上一代瓶颈":"Legacy 3D U-Net 3×3×3 blocks had limited receptive fields, while 3D Transformers were memory-heavy and data-hungry.","核心想法":"Generalize ConvNeXt's large-kernel depthwise inverted bottleneck into a fully 3D encoder–decoder with iterative kernel up-kernelling.","关键改进":"Residual inverted-bottleneck resampling layers and compound scaling across depth, width, and 3D kernel size (3³ → 5³ → 7³).","医学适配":"Establishes a top-performing pure 3D ConvNet baseline across large-scale unified medical segmentation benchmarks.","适用范围与证据":"Essential modern 3D CNN baseline; large 7×7×7 kernels increase training wall-clock time."},"paper_title":"MedNeXt: Transformer-driven Scaling of ConvNets for Medical Image Segmentation","paper_url":"https://doi.org/10.1007/978-3-031-43901-8_39","code_label":"作者/机构官方实现","code_url":"https://github.com/MIC-DKFZ/MedNeXt","has_code":true,"image":"assets/c26c478e5eb831fde12f.avif"},{"id":"architecture_model_013_models_genesis","num":13,"num_str":"013","year":2021,"year_str":"2021","venue":"Medical Image Analysis","venue_group":"journal","era_group":"era3","title":"Models Genesis","family_id":"models_dense_segmentation","family_code":"02","family_short":"稠密预测与医学分割","family_en":"Dense Segmentation","family_icon":"II","family_label":"稠密预测与医学分割：从像素输出到自配置系统","archetype":"restorative_3d_self_supervision","archetype_en":"restorative_3d_self_supervision","accent":"#145E75","fig_badge":"Figure 1 · PDF p.3","fig_href":"https://doi.org/10.1016/j.media.2020.101840","core_mech":"多种 3D 变形与遮挡的统一恢复式自监督，而非从 2D ImageNet 迁移。","core_mech_en":"Unified restorative 3D self-supervised learning from non-linear intensity, local pixel shuffling, and in-/out-painting perturbations.","input_desc":"未标注 3D CT 子体积","input_en":"Unlabeled 3D CT/MRI sub-volumes","output_desc":"可迁移的 3D encoder 表示","output_en":"Transferable 3D encoder-decoder representations for segmentation and classification","form_title":"核心公式 · 从多种三维扰动恢复原体积","form_title_en":"Core Formalism · Restorative 3D Autoencoding Across Composite Volumetric Corruptions","nodes":[{"name":"原始 3D Crop","desc":"从 CT 体数据采样含解剖结构的子体积。","name_en":"3D Crop","desc_en":"Ingests unlabeled 3d ct/mri sub-volumes and prepares initial tensor representations (3D Crop)."},{"name":"Nonlinear Warp","desc":"对强度施加非线性变换，迫使模型恢复组织对比。","name_en":"Nonlinear Warp","desc_en":"Executes Nonlinear Warp to extract primary structural features and establish spatial/sequence encoding."},{"name":"Local Shuffle","desc":"局部像素重排破坏纹理但保留粗空间布局。","name_en":"Local Shuffle","desc_en":"Performs Local Shuffle within the core restorative 3d self supervision computation pathway."},{"name":"In/Out-paint","desc":"内部或外部 cutout 移除区域，要求利用上下文补全。","name_en":"In/Out-paint","desc_en":"Performs In/Out-paint within the core restorative 3d self supervision computation pathway."},{"name":"3D Encoder","desc":"共享卷积编码器从受损体数据提取解剖表示。","name_en":"3D Encoder","desc_en":"Performs 3D Encoder within the core restorative 3d self supervision computation pathway."},{"name":"3D Decoder","desc":"恢复原始子体积的形状、纹理和强度。","name_en":"3D Decoder","desc_en":"Performs 3D Decoder within the core restorative 3d self supervision computation pathway."},{"name":"恢复目标","desc":"预测干净体数据并与原始 crop 比较重建误差。","name_en":"objective","desc_en":"Applies objective to project aggregated representations toward the target task head."},{"name":"迁移 Encoder","desc":"丢弃恢复 decoder，将 encoder 初始化到分类或分割任务。","name_en":"Encoder","desc_en":"Produces transferable 3d encoder-decoder representations for segmentation and classification via Encoder."}],"design_principles":["通过可控破坏—恢复任务让无标签 CT 自身提供监督。","不同 corruption 分别要求学习强度、局部纹理和长程解剖上下文。","预训练 decoder 只服务恢复任务，真正复用单位是 3D encoder。"],"design_principles_en":["Core Hypothesis: Train a 3D encoder–decoder to restore native volumes corrupted by non-linear intensity transformations, local shuffling, and masking.","Architectural Delta: Combines four complementary appearance and spatial corruption tasks into a single restorative pretraining objective.","Mathematical Formalism: Restorative 3D Autoencoding Across Composite Volumetric Corruptions."],"med_apps":["它奠定直接在 3D 医学体数据上做领域自监督的路线。","手工 corruption 规定了模型学到的不变性；对 MRI、多序列和定量强度需重新审视。"],"med_apps_en":["Clinical Translation: Established the foundational paradigm for native 3D self-supervised pretraining in volumetric radiology.","Evidence & Safety Boundary: Foundational 3D SSL milestone; now complemented by masked autoencoding (MAE) and self-distillation."],"attrs":{"上一代瓶颈":"2D ImageNet 迁移无法充分覆盖 3D 医学体数据","核心想法":"通过恢复受变换的 3D CT 子体积学习通用解剖表示","关键改进":"多种恢复式自监督任务与跨多个 3D 下游任务验证","医学适配":"奠定医学 3D 自监督预训练路线","适用范围与证据":"奠基价值明确；当前与 MAE、自蒸馏等目标并存或被后者补充"},"attrs_en":{"上一代瓶颈":"2D ImageNet weights fail to capture native 3D volumetric context, while 3D medical annotations are scarce.","核心想法":"Train a 3D encoder–decoder to restore native volumes corrupted by non-linear intensity transformations, local shuffling, and masking.","关键改进":"Combines four complementary appearance and spatial corruption tasks into a single restorative pretraining objective.","医学适配":"Established the foundational paradigm for native 3D self-supervised pretraining in volumetric radiology.","适用范围与证据":"Foundational 3D SSL milestone; now complemented by masked autoencoding (MAE) and self-distillation."},"paper_title":"Models Genesis: Generic Autodidactic Models for 3D Medical Image Analysis","paper_url":"https://doi.org/10.1016/j.media.2020.101840","code_label":"作者/机构官方实现","code_url":"https://github.com/MrGiovanni/ModelsGenesis","has_code":true,"image":"assets/f0c4f62a13b611f9ceca.avif"},{"id":"architecture_model_014_vista3d","num":14,"num_str":"014","year":2025,"year_str":"2025","venue":"CVPR","venue_group":"cv","era_group":"era4","title":"VISTA3D","family_id":"models_dense_segmentation","family_code":"02","family_short":"稠密预测与医学分割","family_en":"Dense Segmentation","family_icon":"II","family_label":"稠密预测与医学分割：从像素输出到自配置系统","archetype":"unified_3d_promptable_segmentation","archetype_en":"unified_3d_promptable_segmentation","accent":"#145E75","fig_badge":"Figure 1 · PDF p.2","fig_href":"https://openaccess.thecvf.com/content/CVPR2025/html/He_VISTA3D_A_Unified_Segmentation_Foundation_Model_For_3D_Medical_Imaging_CVPR_2025_paper.html","core_mech":"127 类自动分支、3D 点提示分支和 supervoxel 蒸馏共存的统一 3D segmentation FM。","core_mech_en":"Unified 3D CT segmentation foundation model integrating a 127-class automated branch, a 3D point-prompt branch, and 2D supervoxel distillation.","input_desc":"3D CT 与可选点提示/目标类别","input_en":"3D CT volume with optional 3D click coordinates or target anatomical class IDs","output_desc":"已知类别自动 mask 或提示条件下的 3D mask","output_en":"Automated 127-class 3D segmentation masks or interactive point-prompted 3D masks (including zero-shot novel structures)","form_title":"核心公式 · 类别提示与点提示统一条件化三维分割","form_title_en":"Core Formalism · Unified Class-Token and 3D Point-Prompt Conditioned Volumetric Decoding","nodes":[{"name":"3D CT","desc":"体数据进入共享 3D 图像编码路径。","name_en":"3D CT","desc_en":"Ingests 3d ct volume with optional 3d click coordinates or target anatomical class ids and prepares initial tensor representations (3D CT)."},{"name":"3D Image Encoder","desc":"提取多尺度体素特征与解剖先验。","name_en":"3D Image Encoder","desc_en":"Executes 3D Image Encoder to extract primary structural features and establish spatial/sequence encoding."},{"name":"Class Embedding","desc":"编码 127 个已知解剖类别，驱动自动分割分支。","name_en":"Class Embedding","desc_en":"Performs Class Embedding within the core unified 3d promptable segmentation computation pathway."},{"name":"3D Point Prompt","desc":"正负点提示定义目标，并支持未见结构交互分割。","name_en":"3D Point Prompt","desc_en":"Performs 3D Point Prompt within the core unified 3d promptable segmentation computation pathway."},{"name":"Automatic Head","desc":"利用类别先验一次预测预定义解剖结构。","name_en":"Automatic Head","desc_en":"Performs Automatic Head within the core unified 3d promptable segmentation computation pathway."},{"name":"Point Head","desc":"把点嵌入与体特征融合，响应用户修正。","name_en":"Point Head","desc_en":"Performs Point Head within the core unified 3d promptable segmentation computation pathway."},{"name":"Supervoxel Prior","desc":"以 3D supervoxel 组织区域，并蒸馏 2D foundation 特征以扩展结构知识。","name_en":"Supervoxel Prior","desc_en":"Performs Supervoxel Prior within the core unified 3d promptable segmentation computation pathway."},{"name":"Unified Decoder","desc":"融合自动类别、提示和共享体特征，保持一个模型接口。","name_en":"Unified Decoder","desc_en":"Applies Unified Decoder to project aggregated representations toward the target task head."},{"name":"3D Masks","desc":"输出自动、交互修正或提示条件下的新结构分割。","name_en":"3D Masks","desc_en":"Produces automated 127-class 3d segmentation masks or interactive point-prompted 3d masks (including zero-shot novel structures) via 3D Masks."}],"design_principles":["自动类别分割与点提示交互共享同一个 3D 编码表示。","类别 embedding 负责已知 anatomy，点 prompt 允许指定或修正实例。","supervoxel 与 2D foundation 特征蒸馏把区域先验迁入原生体模型。"],"design_principles_en":["Core Hypothesis: Unify automated multi-organ 3D segmentation, interactive 3D point prompting, and novel-structure zero-shot transfer in one 3D backbone.","Architectural Delta: Dual class/point prompt decoder coupled with 3D supervoxel feature distillation from 2D foundation models.","Mathematical Formalism: Unified Class-Token and 3D Point-Prompt Conditioned Volumetric Decoding."],"med_apps":["适合把批量自动分割与临床/标注人员的局部纠错放在同一接口。","未见结构能力依赖提示且仍需跨机构前瞻验证，不能等同全自动 zero-shot。"],"med_apps_en":["Clinical Translation: Provides a versatile 3D CT annotation acceleration and interactive correction interface.","Evidence & Safety Boundary: Substantial step forward in 3D promptable segmentation; prospective multi-center workflow validation remains ongoing."],"attrs":{"上一代瓶颈":"自动模型难交互修正，2D SAM 对复杂 3D 解剖和标注流程不匹配","核心想法":"单一 3D 模型统一自动分割、点提示交互和提示条件下的新结构 zero-shot","关键改进":"127 类自动分割、3D prompt 接口与 supervoxel 蒸馏的 2D foundation 特征","医学适配":"面向 CT 的可复用 3D 标注与交互式修正接口","适用范围与证据":"代表 3D promptable segmentation 的实质进展，仍需前瞻跨机构验证"},"attrs_en":{"上一代瓶颈":"Closed-set 3D models cannot interactively refine errors, whereas slice-wise 2D SAM loses 3D volumetric coherence.","核心想法":"Unify automated multi-organ 3D segmentation, interactive 3D point prompting, and novel-structure zero-shot transfer in one 3D backbone.","关键改进":"Dual class/point prompt decoder coupled with 3D supervoxel feature distillation from 2D foundation models.","医学适配":"Provides a versatile 3D CT annotation acceleration and interactive correction interface.","适用范围与证据":"Substantial step forward in 3D promptable segmentation; prospective multi-center workflow validation remains ongoing."},"paper_title":"VISTA3D: A Unified Segmentation Foundation Model for 3D Medical Imaging","paper_url":"https://openaccess.thecvf.com/content/CVPR2025/html/He_VISTA3D_A_Unified_Segmentation_Foundation_Model_For_3D_Medical_Imaging_CVPR_2025_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/Project-MONAI/VISTA","has_code":true,"image":"assets/672617eff2831c1c504c.avif"},{"id":"architecture_model_015_s4","num":15,"num_str":"015","year":2022,"year_str":"2022","venue":"ICLR","venue_group":"ml","era_group":"era3","title":"S4","family_id":"models_ssm_mamba","family_code":"03","family_short":"状态空间与 Mamba","family_en":"State Space & Mamba","family_icon":"III","family_label":"状态空间与 Mamba：长程传播、扫描偏置和 3D 代价","archetype":"structured_state_space","archetype_en":"structured_state_space","accent":"#5B3F8C","fig_badge":"Figure 1 · PDF p.2","fig_href":"https://openreview.net/forum?id=uYLFoz1vlAC","core_mech":"结构化 A 矩阵使线性 SSM 可在长卷积训练与递推推理间等价切换。","core_mech_en":"Parameterizes state matrix A as Normal Plus Low-Rank (NPLR) so linear SSMs switch exact equivalence between O(N log N) convolutional training and O(1) recurrent inference.","input_desc":"长一维序列 x1…xN","input_en":"Long 1D sequence x_1 … x_N","output_desc":"保留长程历史的序列表示 y1…yN","output_en":"Long-range sequence representation y_1 … y_N preserving distant history","form_title":"核心公式 · S4 将结构化状态空间核化为长卷积","form_title_en":"Core Formalism · S4 Structured State-Space Kernelization via Cauchy/Woodbury Identity","nodes":[{"name":"输入序列","desc":"每个时间步先投影到 SSM 通道。","name_en":"input sequence","desc_en":"Ingests long 1d sequence x_1 … x_n and prepares initial tensor representations (input sequence)."},{"name":"连续 SSM","desc":"定义 ḣ=Ah+Bx、y=Ch+Dx 的线性动力系统。","name_en":"continuous SSM","desc_en":"Executes continuous SSM to extract primary structural features and establish spatial/sequence encoding."},{"name":"Structured A","desc":"以 HiPPO/结构化参数约束状态矩阵，兼顾稳定性和长记忆。","name_en":"Structured A","desc_en":"Performs Structured A within the core structured state space computation pathway."},{"name":"离散化","desc":"按采样间隔把 A、B 转为离散状态更新矩阵。","name_en":"discrete","desc_en":"Performs discrete within the core structured state space computation pathway."},{"name":"SSM Kernel","desc":"将线性递推等价为长卷积核，并用结构化计算高效生成。","name_en":"SSM Kernel","desc_en":"Performs SSM Kernel within the core structured state space computation pathway."},{"name":"长卷积路径","desc":"训练时对完整序列并行卷积，常通过 FFT/结构化算法实现。","name_en":"convolution","desc_en":"Performs convolution within the core structured state space computation pathway."},{"name":"递推状态","desc":"推理时可按 h_t=Āh_{t−1}+B̄x_t 逐步更新。","name_en":"Stage 07","desc_en":"Performs Stage 07 within the core structured state space computation pathway."},{"name":"S4 Block","desc":"SSM 输出经非线性、门控/混合和 residual 组成深层网络。","name_en":"S4 Block","desc_en":"Applies S4 Block to project aggregated representations toward the target task head."},{"name":"序列输出","desc":"保留每步表示或汇聚为下游预测。","name_en":"sequence output","desc_en":"Produces long-range sequence representation y_1 … y_n preserving distant history via sequence output."}],"design_principles":["结构化状态矩阵把长期记忆、数值稳定和可计算性同时纳入参数化。","同一线性系统既可作为长卷积并行训练，也可递推执行。","训练通常为次二次/近 O(N log N) 路径，不应与 Mamba 的选择性线性 scan 混为一谈。"],"design_principles_en":["Core Hypothesis: Initialize state matrix A with HiPPO orthogonal polynomial projections and decompose it into diagonal plus low-rank form for fast kernel evaluation.","Architectural Delta: Mathematically unifies continuous-time ODEs, O(1)-step autoregressive recurrence, and parallel FFT convolution training.","Mathematical Formalism: S4 Structured State-Space Kernelization via Cauchy/Woodbury Identity."],"med_apps":["适合 EEG、ECG 等长生理序列的高效长程建模研究。","把 2D/3D 影像展平给 S4 仍需额外空间扫描设计，原模型不天然理解体拓扑。"],"med_apps_en":["Clinical Translation: Provides the mathematical foundation for long-horizon EEG, ECG, waveform modeling, and subsequent visual/3D SSMs.","Evidence & Safety Boundary: Foundational structured SSM; linear time-invariant (LTI) dynamics lack content-dependent selection until Mamba."],"attrs":{"上一代瓶颈":"RNN 难训练，CNN 与 Transformer 难稳定覆盖超长序列","核心想法":"用结构化状态矩阵把长程递推等价为可高效计算的长卷积","关键改进":"稳定的结构化 A 与高效 Cauchy/Vandermonde 核计算","医学适配":"为长 EEG 与波形提供直接机制基础，也启发后续 3D 序列适配","适用范围与证据":"现代 SSM 的数学基础；并行训练常为近 O(N log N) 的长卷积路径，递推推理可线性扩展"},"attrs_en":{"上一代瓶颈":"RNNs suffer from vanishing gradients and sequential training bottlenecks, while Transformers scale quadratically O(N²) on long sequences.","核心想法":"Initialize state matrix A with HiPPO orthogonal polynomial projections and decompose it into diagonal plus low-rank form for fast kernel evaluation.","关键改进":"Mathematically unifies continuous-time ODEs, O(1)-step autoregressive recurrence, and parallel FFT convolution training.","医学适配":"Provides the mathematical foundation for long-horizon EEG, ECG, waveform modeling, and subsequent visual/3D SSMs.","适用范围与证据":"Foundational structured SSM; linear time-invariant (LTI) dynamics lack content-dependent selection until Mamba."},"paper_title":"Efficiently Modeling Long Sequences with Structured State Spaces","paper_url":"https://openreview.net/forum?id=uYLFoz1vlAC","code_label":"作者/机构官方实现","code_url":"https://github.com/state-spaces/s4","has_code":true,"image":"assets/13ad5aece6dafdc2f46c.avif"},{"id":"architecture_model_016_mamba","num":16,"num_str":"016","year":2024,"year_str":"2024","venue":"COLM","venue_group":"ml","era_group":"era4","title":"Mamba","family_id":"models_ssm_mamba","family_code":"03","family_short":"状态空间与 Mamba","family_en":"State Space & Mamba","family_icon":"III","family_label":"状态空间与 Mamba：长程传播、扫描偏置和 3D 代价","archetype":"selective_state_space_block","archetype_en":"selective_state_space_block","accent":"#5B3F8C","fig_badge":"Figure 3 · PDF p.8","fig_href":"https://openreview.net/forum?id=tEYskw1VY2","core_mech":"由当前输入生成 Δ、B、C 的 selective SSM，并用硬件感知并行 scan 执行。","core_mech_en":"Makes SSM discretization step Δ and projections B, C functions of the current input x_k, executed via a hardware-aware parallel associative scan.","input_desc":"长度 N 的 token/连续信号序列","input_en":"Sequence of N tokens or continuous signal samples","output_desc":"内容选择后的长程序列表示","output_en":"Content-selectively filtered long-range sequence representations","form_title":"核心公式 · Mamba 的输入依赖离散化与选择性扫描","form_title_en":"Core Formalism · Input-Dependent Selective Discretization & Parallel Associative Scan","nodes":[{"name":"输入 Tokens","desc":"序列先经线性层扩展并分成内容分支与门控分支。","name_en":"input Tokens","desc_en":"Ingests sequence of n tokens or continuous signal samples and prepares initial tensor representations (input Tokens)."},{"name":"内容分支 x","desc":"承担局部混合与状态空间更新的主信号。","name_en":"Stage 02","desc_en":"Executes Stage 02 to extract primary structural features and establish spatial/sequence encoding."},{"name":"门控分支 z","desc":"经 SiLU 产生与输入相关的输出门。","name_en":"Stage 03","desc_en":"Performs Stage 03 within the core selective state space block computation pathway."},{"name":"1D DWConv","desc":"短核因果卷积在 selective scan 前编码局部邻域。","name_en":"1D DWConv","desc_en":"Performs 1D DWConv within the core selective state space block computation pathway."},{"name":"Δ/B/C 选择器","desc":"由当前 token 生成步长与输入/输出状态参数。","name_en":"Δ/B/C","desc_en":"Performs Δ/B/C within the core selective state space block computation pathway."},{"name":"Selective Scan","desc":"硬件感知并行扫描按 token 决定保留、忘记和输出状态。","name_en":"Selective Scan","desc_en":"Performs Selective Scan within the core selective state space block computation pathway."},{"name":"SiLU Gate","desc":"选择性状态输出与 z 分支逐元素门控。","name_en":"SiLU Gate","desc_en":"Performs SiLU Gate within the core selective state space block computation pathway."},{"name":"输出投影","desc":"将扩展通道压回模型维度。","name_en":"output projection","desc_en":"Applies output projection to project aggregated representations toward the target task head."},{"name":"Residual","desc":"块输入与投影输出相加形成深层 Mamba stack。","name_en":"Residual","desc_en":"Produces content-selectively filtered long-range sequence representations via Residual."}],"design_principles":["固定 SSM 的参数被改为输入依赖选择器，使状态路由具有内容选择性。","不显式构造 N×N attention 矩阵，序列长度方向保持线性 scan。","局部 depthwise conv、选择性状态更新和输出门控承担不同时间尺度。"],"design_principles_en":["Core Hypothesis: Parameterize (Δ_k, B_k, C_k) dynamically from input x_k and compute the resulting time-varying recurrence in SRAM via parallel prefix scan.","Architectural Delta: Input-dependent selective state updates + kernel-fused GPU associative scan achieving O(N) time and memory scaling.","Mathematical Formalism: Input-Dependent Selective Discretization & Parallel Associative Scan."],"med_apps":["适合长生理信号或 3D bottleneck 中需要广域传递而 attention 成本过高的场景。","线性阶不等于低实际延迟；state size、扫描方向、decoder 和内存搬运仍需测量。"],"med_apps_en":["Clinical Translation: Adopted across 3D volumetric segmentation, gigapixel WSI, and long physiological waveforms as a linear-complexity global mixer.","Evidence & Safety Boundary: Major sequence modeling milestone; in 2D/3D medical imaging, standalone superiority over tuned CNNs/Transformers is not universal."],"attrs":{"上一代瓶颈":"固定 SSM 不擅长按内容选择保留、遗忘和输出信息","核心想法":"让状态更新参数随输入变化，并以硬件感知 selective scan 线性处理序列","关键改进":"input-dependent B、C、Delta 与并行 selective scan","医学适配":"吸引 3D 分割、长生理信号和视频作为低成本全局 mixer","适用范围与证据":"序列领域重要；医学中尚无普遍替代 CNN/Transformer 的证据"},"attrs_en":{"上一代瓶颈":"Linear time-invariant SSMs (S4) use static transition matrices and cannot selectively remember or ignore tokens based on content.","核心想法":"Parameterize (Δ_k, B_k, C_k) dynamically from input x_k and compute the resulting time-varying recurrence in SRAM via parallel prefix scan.","关键改进":"Input-dependent selective state updates + kernel-fused GPU associative scan achieving O(N) time and memory scaling.","医学适配":"Adopted across 3D volumetric segmentation, gigapixel WSI, and long physiological waveforms as a linear-complexity global mixer.","适用范围与证据":"Major sequence modeling milestone; in 2D/3D medical imaging, standalone superiority over tuned CNNs/Transformers is not universal."},"paper_title":"Mamba: Linear-Time Sequence Modeling with Selective State Spaces","paper_url":"https://openreview.net/forum?id=tEYskw1VY2","code_label":"作者/机构官方实现","code_url":"https://github.com/state-spaces/mamba","has_code":true,"image":"assets/803193cb08a016c2cc3c.avif"},{"id":"architecture_model_017_vmamba","num":17,"num_str":"017","year":2024,"year_str":"2024","venue":"NeurIPS","venue_group":"ml","era_group":"era4","title":"VMamba","family_id":"models_ssm_mamba","family_code":"03","family_short":"状态空间与 Mamba","family_en":"State Space & Mamba","family_icon":"III","family_label":"状态空间与 Mamba：长程传播、扫描偏置和 3D 代价","archetype":"hierarchical_2d_cross_scan_ssm","archetype_en":"hierarchical_2d_cross_scan_ssm","accent":"#5B3F8C","fig_badge":"Figure 3(a) · PDF p.5","fig_href":"https://proceedings.neurips.cc/paper_files/paper/2024/hash/baa2da9ae4bfed26520bb61d259a3653-Abstract.html","core_mech":"SS2D 将二维网格沿四个方向 selective scan 后再逆映射融合。","core_mech_en":"2D Selective Scan (SS2D) unfolds spatial feature maps along four directional traversal paths, applies selective SSMs, and merges them back.","input_desc":"2D 图像","input_en":"2D image tensor","output_desc":"层级视觉特征或分类 logits","output_en":"Four-stage hierarchical visual feature maps or classification logits","form_title":"核心公式 · VMamba 四方向二维交叉扫描","form_title_en":"Core Formalism · VMamba Four-Way 2D Cross-Scan & Merge (SS2D)","nodes":[{"name":"输入图像","desc":"图像先经卷积式 patch embedding 形成二维 token 网格。","name_en":"Input Image","desc_en":"Ingests 2d image tensor and prepares initial tensor representations (Input Image)."},{"name":"Patch Embed","desc":"保持 H×W 拓扑并映射到 VSS 通道。","name_en":"Patch Embed","desc_en":"Executes Patch Embed to extract primary structural features and establish spatial/sequence encoding."},{"name":"四向展开","desc":"生成横向正反与纵向正反四条扫描序列。","name_en":"unrolled","desc_en":"Performs unrolled within the core hierarchical 2d cross scan ssm computation pathway."},{"name":"SS2D","desc":"每条方向执行 selective scan，传播长程二维上下文。","name_en":"SS2D","desc_en":"Performs SS2D within the core hierarchical 2d cross scan ssm computation pathway."},{"name":"Cross-scan Merge","desc":"把四向输出逆排列并融合回原二维坐标。","name_en":"Cross-scan Merge","desc_en":"Performs Cross-scan Merge within the core hierarchical 2d cross scan ssm computation pathway."},{"name":"VSS Block","desc":"SS2D、归一化、门控/MLP 与 residual 构成视觉状态块。","name_en":"VSS Block","desc_en":"Performs VSS Block within the core hierarchical 2d cross scan ssm computation pathway."},{"name":"Patch Merging","desc":"逐级降低分辨率，形成类似 Swin 的层级金字塔。","name_en":"Patch Merging","desc_en":"Performs Patch Merging within the core hierarchical 2d cross scan ssm computation pathway."},{"name":"多级 VSS","desc":"在四个尺度重复 cross-scan 并扩大语义范围。","name_en":"VSS","desc_en":"Applies VSS to project aggregated representations toward the target task head."},{"name":"任务头","desc":"全局池化分类，或导出各级特征给 dense decoder。","name_en":"Task Head","desc_en":"Produces four-stage hierarchical visual feature maps or classification logits via Task Head."}],"design_principles":["四向 cross-scan 缓解单条 raster 序列对二维邻接关系的破坏。","selective SSM 提供长程传播，patch merging 提供视觉多尺度。","扫描顺序本身成为新的归纳偏置，线性阶仍乘以方向数。"],"design_principles_en":["Core Hypothesis: Traverse 2D feature grids simultaneously along four complementary corner-to-corner paths before summing the selective scan outputs.","Architectural Delta: SS2D four-way cross-scan module embedded within a hierarchical Visual State-Space (VSS) backbone.","Mathematical Formalism: VMamba Four-Way 2D Cross-Scan & Merge (SS2D)."],"med_apps":["可作为医学 2D SSM backbone 或后续 3D 扩展的机制参考。","迁移到体数据需要新增轴向/多方向扫描，不能把 2D 权重直接等同原生 3D 表示。"],"med_apps_en":["Clinical Translation: Serves as the primary 2D vision SSM backbone and initialization for medical 2D segmentation and classification.","Evidence & Safety Boundary: Important visual SSM baseline; native 3D volumetric extension requires tri-axial or multi-directional scan adaptations."],"attrs":{"上一代瓶颈":"将图像按单条 1D 序列展平会破坏二维拓扑","核心想法":"以四方向 2D selective scan 和层级 VSS block 建模视觉结构","关键改进":"SS2D cross-scan 与多尺度层级 backbone","医学适配":"作为医学 2D SSM 的视觉初始化和对照；原生 3D 仍需改造扫描与层级结构","适用范围与证据":"重要视觉 SSM 基线；未普遍淘汰 ConvNeXt/Swin"},"attrs_en":{"上一代瓶颈":"Flattening a 2D image into a single 1D causal raster scan destroys 2D spatial proximity along non-scan directions.","核心想法":"Traverse 2D feature grids simultaneously along four complementary corner-to-corner paths before summing the selective scan outputs.","关键改进":"SS2D four-way cross-scan module embedded within a hierarchical Visual State-Space (VSS) backbone.","医学适配":"Serves as the primary 2D vision SSM backbone and initialization for medical 2D segmentation and classification.","适用范围与证据":"Important visual SSM baseline; native 3D volumetric extension requires tri-axial or multi-directional scan adaptations."},"paper_title":"VMamba: Visual State Space Model","paper_url":"https://proceedings.neurips.cc/paper_files/paper/2024/hash/baa2da9ae4bfed26520bb61d259a3653-Abstract.html","code_label":"作者/机构官方实现","code_url":"https://github.com/MzeroMiko/VMamba","has_code":true,"image":"assets/e9a3f3a74054515fc69f.avif"},{"id":"architecture_model_018_u_mamba","num":18,"num_str":"018","year":2024,"year_str":"2024 (preprint)","venue":"arXiv preprint","venue_group":"journal","era_group":"era4","title":"U-Mamba","family_id":"models_ssm_mamba","family_code":"03","family_short":"状态空间与 Mamba","family_en":"State Space & Mamba","family_icon":"III","family_label":"状态空间与 Mamba：长程传播、扫描偏置和 3D 代价","archetype":"self_configuring_cnn_ssm_unet","archetype_en":"self_configuring_cnn_ssm_unet","accent":"#5B3F8C","fig_badge":"Figure 1 · PDF p.3","fig_href":"https://arxiv.org/abs/2401.04722","core_mech":"在 nnU-Net 风格 residual CNN encoder/bottleneck 中插入 selective SSM，同时保留 CNN long skips。","core_mech_en":"Embeds flattened 1D selective Mamba blocks inside an nnU-Net-style residual CNN encoder/bottleneck while retaining CNN decoder and long skips.","input_desc":"2D/3D 医学影像与 nnU-Net 数据配置","input_en":"2D or 3D medical image within the automated nnU-Net pipeline","output_desc":"逐像素/体素分割","output_en":"Dense pixel- or voxel-level segmentation map","form_title":"核心公式 · CNN 局部特征展平后进入 U-Mamba 长程模块","form_title_en":"Core Formalism · Hybrid Residual 3D Convolution Coupled with Flattened Selective SSM","nodes":[{"name":"nnU-Net Planner","desc":"按数据 fingerprint 决定 2D/3D、patch、kernel、spacing 与通道。","name_en":"nnU-Net Planner","desc_en":"Ingests 2d or 3d medical image within the automated nnu-net pipeline and prepares initial tensor representations (nnU-Net Planner)."},{"name":"医学影像","desc":"预处理后的 2D 图像或 3D patch。","name_en":"Stage 02","desc_en":"Executes Stage 02 to extract primary structural features and establish spatial/sequence encoding."},{"name":"Residual CNN","desc":"高分辨率路径先编码局部边缘与空间细节。","name_en":"Residual CNN","desc_en":"Performs Residual CNN within the core self configuring cnn ssm unet computation pathway."},{"name":"Spatial→Sequence","desc":"在 bottleneck 或各 encoder stage 将空间特征展平为序列。","name_en":"Spatial→Sequence","desc_en":"Performs Spatial→Sequence within the core self configuring cnn ssm unet computation pathway."},{"name":"Mamba Layer","desc":"selective scan 沿序列传播远程依赖；Bot/Enc 变体决定放置范围。","name_en":"Mamba Layer","desc_en":"Performs Mamba Layer within the core self configuring cnn ssm unet computation pathway."},{"name":"Sequence→Spatial","desc":"把状态输出恢复到原特征网格。","name_en":"Sequence→Spatial","desc_en":"Performs Sequence→Spatial within the core self configuring cnn ssm unet computation pathway."},{"name":"CNN Long Skips","desc":"未被序列瓶颈替代的高分辨率 CNN 特征直达 decoder。","name_en":"CNN Long Skips","desc_en":"Performs CNN Long Skips within the core self configuring cnn ssm unet computation pathway."},{"name":"CNN Decoder","desc":"逐级上采样并融合局部 skip 与全局 Mamba 表示。","name_en":"CNN Decoder","desc_en":"Applies CNN Decoder to project aggregated representations toward the target task head."},{"name":"Seg Head","desc":"输出医学分割 logits。","name_en":"Seg Head","desc_en":"Produces dense pixel- or voxel-level segmentation map via Seg Head."}],"design_principles":["CNN 保留高分辨局部归纳偏置，Mamba 只承担成本敏感的长程混合。","Bot 与 Enc 变体通过改变 Mamba 放置位置检验全局建模范围。","沿用 nnU-Net self-configuration，使结构变化与数据适配 recipe 绑定。"],"design_principles_en":["Core Hypothesis: Augment residual CNN blocks with flattened Mamba layers inside the self-configuring nnU-Net framework to combine local priors with long-range mixing.","Architectural Delta: Plug-and-play U-Mamba_Bot and U-Mamba_Enc hybrid architectures preserving nnU-Net preprocessing and long skip connections.","Mathematical Formalism: Hybrid Residual 3D Convolution Coupled with Flattened Selective SSM."],"med_apps":["适合研究 3D attention 太贵而 CNN 全局关系有限的折中方案。","必须与 no-Mamba 同构 residual U-Net 比较，才能归因 selective scan 的独立贡献。"],"med_apps_en":["Clinical Translation: Evaluated across multi-organ CT, MRI, and endoscopy segmentation benchmarks.","Evidence & Safety Boundary: High-visibility hybrid baseline, though subsequent controlled ablations show matched MedNeXt / nnU-Net ResEnc often perform comparably."],"attrs":{"上一代瓶颈":"3D CNN 全局依赖弱，而全局注意力成本高","核心想法":"在 nnU-Net 风格 CNN 中加入 Mamba 作为 bottleneck 或 encoder 全局建模器","关键改进":"自配置 U-Net pipeline 加 CNN-SSM hybrid block","医学适配":"覆盖多类 2D/3D 医学分割任务","适用范围与证据":"高热度研究基线；后续统一配方消融未发现稳定的 Mamba 独立增益"},"attrs_en":{"上一代瓶颈":"Pure 3D CNNs have local receptive fields, whereas 3D self-attention incurs prohibitive quadratic memory on large patches.","核心想法":"Augment residual CNN blocks with flattened Mamba layers inside the self-configuring nnU-Net framework to combine local priors with long-range mixing.","关键改进":"Plug-and-play U-Mamba_Bot and U-Mamba_Enc hybrid architectures preserving nnU-Net preprocessing and long skip connections.","医学适配":"Evaluated across multi-organ CT, MRI, and endoscopy segmentation benchmarks.","适用范围与证据":"High-visibility hybrid baseline, though subsequent controlled ablations show matched MedNeXt / nnU-Net ResEnc often perform comparably."},"paper_title":"U-Mamba: Enhancing Long-range Dependency for Biomedical Image Segmentation","paper_url":"https://arxiv.org/abs/2401.04722","code_label":"作者/机构官方实现","code_url":"https://github.com/bowang-lab/U-Mamba","has_code":true,"image":"assets/3af2449c82da9f586843.avif"},{"id":"architecture_model_019_segmamba","num":19,"num_str":"019","year":2024,"year_str":"2024","venue":"MICCAI","venue_group":"miccai","era_group":"era4","title":"SegMamba","family_id":"models_ssm_mamba","family_code":"03","family_short":"状态空间与 Mamba","family_en":"State Space & Mamba","family_icon":"III","family_label":"状态空间与 Mamba：长程传播、扫描偏置和 3D 代价","archetype":"tri_oriented_3d_mamba_unet","archetype_en":"tri_oriented_3d_mamba_unet","accent":"#5B3F8C","fig_badge":"Figure 1 · PDF p.3","fig_href":"https://doi.org/10.1007/978-3-031-72111-3_54","core_mech":"GSC + Tri-oriented Mamba 的 TSMamba block，以及 FUE 过滤的多尺度 skip。","core_mech_en":"Combines Gated Spatial Convolution (GSC) with Tri-oriented Mamba (ToM) scans along axial, coronal, and sagittal axes plus Feature Uncertainty Estimation (FUE) skips.","input_desc":"3D 医学体数据","input_en":"3D volumetric medical scan (CT / MRI)","output_desc":"多尺度融合的 3D 分割","output_en":"Multi-scale fused 3D volumetric segmentation","form_title":"核心公式 · SegMamba 沿深、高、宽三轴建模","form_title_en":"Core Formalism · Tri-Oriented 3D Volumetric Selective Scan (Depth / Height / Width)","nodes":[{"name":"3D Input","desc":"C×D×H×W 体数据进入大核 depthwise stem。","name_en":"3D Input","desc_en":"Ingests 3d volumetric medical scan (ct / mri) and prepares initial tensor representations (3D Input)."},{"name":"7³ DW Stem","desc":"stride-2 大核逐通道卷积建立首级体特征。","name_en":"7³ DW Stem","desc_en":"Executes 7³ DW Stem to extract primary structural features and establish spatial/sequence encoding."},{"name":"GSC","desc":"Gated Spatial Convolution 在序列化前补充局部三维空间关系。","name_en":"GSC","desc_en":"Performs GSC within the core tri oriented 3d mamba unet computation pathway."},{"name":"Tri-oriented Mamba","desc":"沿 D、H、W 三种取向执行 Mamba，融合各轴长程依赖。","name_en":"Tri-oriented Mamba","desc_en":"Performs Tri-oriented Mamba within the core tri oriented 3d mamba unet computation pathway."},{"name":"TSMamba Block","desc":"GSC、LayerNorm、ToM、MLP 与两级 residual 组成主块。","name_en":"TSMamba Block","desc_en":"Performs TSMamba Block within the core tri oriented 3d mamba unet computation pathway."},{"name":"多尺度 Encoder","desc":"下采样后重复 TSMamba，通道逐级增大。","name_en":"multi-scale Encoder","desc_en":"Performs multi-scale Encoder within the core tri oriented 3d mamba unet computation pathway."},{"name":"FUE","desc":"Feature-level Uncertainty Estimation 过滤和加权多尺度 skip 特征。","name_en":"FUE","desc_en":"Performs FUE within the core tri oriented 3d mamba unet computation pathway."},{"name":"Residual Decoder","desc":"转置卷积上采样并融合经 FUE 筛选的 encoder 特征。","name_en":"Residual Decoder","desc_en":"Applies Residual Decoder to project aggregated representations toward the target task head."},{"name":"Seg Head","desc":"输出每体素类别概率。","name_en":"Seg Head","desc_en":"Produces multi-scale fused 3d volumetric segmentation via Seg Head."}],"design_principles":["GSC 在 Mamba 展平前显式编码局部三维空间关系。","Tri-oriented Mamba 分别沿深度、高度和宽度传播长程信息。","FUE 对多尺度 skip 做不确定性筛选，避免无条件复用所有 encoder 特征。"],"design_principles_en":["Core Hypothesis: Apply gated 3D spatial convolutions followed by tri-directional Mamba scans across forward, reverse, and inter-slice axes.","Architectural Delta: TSMamba block (GSC + Tri-oriented Mamba) paired with uncertainty-weighted multi-scale skip refinement.","Mathematical Formalism: Tri-Oriented 3D Volumetric Selective Scan (Depth / Height / Width)."],"med_apps":["适合 whole-volume 长关系与多尺度分割并重的 3D 研究。","三轴 scan、FUE 和卷积 stem 都是性能来源，消融不能只比较 Mamba 有无。"],"med_apps_en":["Clinical Translation: Representative peer-reviewed 3D medical Mamba architecture for brain tumor and colorectal segmentation.","Evidence & Safety Boundary: Worth reproducing as a 3D SSM reference; still requires broader multi-center and boundary-level validation."],"attrs":{"上一代瓶颈":"高分辨率全体积 Transformer 的显存成本不可承受","核心想法":"用多尺度 3D Mamba 处理 whole-volume 长序列依赖","关键改进":"线性 scan 覆盖中低分辨率 feature grid 上的数十万 token，并保留多尺度解码","医学适配":"代表同行评议的 medical Mamba 3D 分割路线","适用范围与证据":"值得复现；仍缺统一配方、多中心和边界/小病灶证据"},"attrs_en":{"上一代瓶颈":"High-resolution whole-volume 3D Transformers exceed GPU memory, while single-direction 3D flattening loses tri-planar anatomy.","核心想法":"Apply gated 3D spatial convolutions followed by tri-directional Mamba scans across forward, reverse, and inter-slice axes.","关键改进":"TSMamba block (GSC + Tri-oriented Mamba) paired with uncertainty-weighted multi-scale skip refinement.","医学适配":"Representative peer-reviewed 3D medical Mamba architecture for brain tumor and colorectal segmentation.","适用范围与证据":"Worth reproducing as a 3D SSM reference; still requires broader multi-center and boundary-level validation."},"paper_title":"SegMamba: Long-range Sequential Modeling Mamba For 3D Medical Image Segmentation","paper_url":"https://doi.org/10.1007/978-3-031-72111-3_54","code_label":"作者/机构官方实现","code_url":"https://github.com/ge-xing/SegMamba","has_code":true,"image":"assets/83c2490043573d537b24.avif"},{"id":"architecture_model_020_transformer","num":20,"num_str":"020","year":2017,"year_str":"2017","venue":"NeurIPS","venue_group":"ml","era_group":"era2","title":"Transformer","family_id":"models_vision_transformers","family_code":"04","family_short":"视觉 Transformer","family_en":"Vision Transformers","family_icon":"IV","family_label":"视觉 Transformer：全局交互、层级窗口与高分辨率代价","archetype":"encoder_decoder_attention","archetype_en":"encoder_decoder_attention","accent":"#1F4E79","fig_badge":"Figures 1 and 2 · PDF pp.3–4","fig_href":"https://proceedings.neurips.cc/paper_files/paper/2017/hash/3f5ee243547dee91fbd053c1c4a845aa-Abstract.html","core_mech":"无递归的多头 self-attention encoder 与 masked self-/cross-attention decoder。","core_mech_en":"Recurrence-free multi-head self-attention encoder paired with a masked self- and cross-attention decoder.","input_desc":"源 token 序列与右移后的目标 token 序列","input_en":"Source token sequence and right-shifted target token sequence","output_desc":"自回归目标 token 概率","output_en":"Autoregressive target token probabilities or contextualized sequence embeddings","form_title":"核心公式 · 缩放点积注意力的核心前向式","form_title_en":"Core Formalism · Scaled Dot-Product Multi-Head Self-Attention","nodes":[{"name":"源 Tokens","desc":"词嵌入与位置编码相加后送入 encoder。","name_en":"Tokens","desc_en":"Ingests source token sequence and right-shifted target token sequence and prepares initial tensor representations (Tokens)."},{"name":"Encoder MHA","desc":"每个源 token 以 Q/K/V 对全部源 token 做多头 self-attention。","name_en":"Encoder MHA","desc_en":"Executes Encoder MHA to extract primary structural features and establish spatial/sequence encoding."},{"name":"Encoder FFN","desc":"逐位置前馈网络配合 residual 与 LayerNorm。","name_en":"Encoder FFN","desc_en":"Performs Encoder FFN within the core encoder decoder attention computation pathway."},{"name":"Encoder Memory","desc":"堆叠 encoder blocks 后形成供 decoder 查询的上下文。","name_en":"Encoder Memory","desc_en":"Performs Encoder Memory within the core encoder decoder attention computation pathway."},{"name":"目标 Tokens","desc":"训练时输入右移真值；推理时输入已生成 token。","name_en":"objective Tokens","desc_en":"Performs objective Tokens within the core encoder decoder attention computation pathway."},{"name":"Masked MHA","desc":"因果 mask 阻止目标 token 看到未来位置。","name_en":"Masked MHA","desc_en":"Performs Masked MHA within the core encoder decoder attention computation pathway."},{"name":"Cross-attention","desc":"decoder query 从 encoder memory 的 key/value 聚合源信息。","name_en":"Cross-attention","desc_en":"Performs Cross-attention within the core encoder decoder attention computation pathway."},{"name":"Decoder FFN","desc":"跨模态/跨序列融合后逐位置变换。","name_en":"Decoder FFN","desc_en":"Applies Decoder FFN to project aggregated representations toward the target task head."},{"name":"Linear + Softmax","desc":"预测下一个目标 token 的词表分布。","name_en":"Linear + Softmax","desc_en":"Produces autoregressive target token probabilities or contextualized sequence embeddings via Linear + Softmax."}],"design_principles":["scaled dot-product attention 用当前输入动态生成 token 间聚合权重。","多头机制并行学习不同关系，位置编码补回顺序信息。","encoder–decoder cross-attention 将源表示与自回归目标生成解耦。"],"design_principles_en":["Core Hypothesis: Replace recurrence and convolution entirely with parallel multi-head scaled dot-product attention and position encodings.","Architectural Delta: Content-dependent Q/K/V all-pair affinity matrices, multi-head subspace projection, residual LayerNorm, and position-wise FFN.","Mathematical Formalism: Scaled Dot-Product Multi-Head Self-Attention."],"med_apps":["它是 ViT、医学 VLM 和长生理序列模型的共同注意力母体。","标准全局 attention 的 N×N 矩阵在高分辨率 3D 中通常必须窗口化或降采样。"],"med_apps_en":["Clinical Translation: Foundational operator underlying Vision Transformers, medical VLMs, multimodal EHR fusion, and biosignal foundation models.","Evidence & Safety Boundary: Universal deep learning infrastructure; direct application to dense 3D voxels is bottlenecked by O(N²) attention complexity."],"attrs":{"上一代瓶颈":"RNN 串行且长依赖路径长，卷积需堆层获得远程交互","核心想法":"以 scaled dot-product multi-head self-attention 并行建模 token 间关系","关键改进":"Q/K/V 动态全局交互、位置编码、残差和前馈网络","医学适配":"是 ViT、医学 VLM、长生理信号模型的共同基础","适用范围与证据":"基础设施级方法；高分辨 3D 仍受 O(N²) 限制"},"attrs_en":{"上一代瓶颈":"Recurrent networks precluded parallel training across time steps and struggled with long-range dependencies.","核心想法":"Replace recurrence and convolution entirely with parallel multi-head scaled dot-product attention and position encodings.","关键改进":"Content-dependent Q/K/V all-pair affinity matrices, multi-head subspace projection, residual LayerNorm, and position-wise FFN.","医学适配":"Foundational operator underlying Vision Transformers, medical VLMs, multimodal EHR fusion, and biosignal foundation models.","适用范围与证据":"Universal deep learning infrastructure; direct application to dense 3D voxels is bottlenecked by O(N²) attention complexity."},"paper_title":"Attention Is All You Need","paper_url":"https://proceedings.neurips.cc/paper_files/paper/2017/hash/3f5ee243547dee91fbd053c1c4a845aa-Abstract.html","code_label":"作者/机构官方实现","code_url":"https://github.com/tensorflow/tensor2tensor","has_code":true,"image":"assets/a07786789c3653dc89c0.avif"},{"id":"architecture_model_021_vision_transformer__vit","num":21,"num_str":"021","year":2021,"year_str":"2021","venue":"ICLR","venue_group":"ml","era_group":"era3","title":"Vision Transformer (ViT)","family_id":"models_vision_transformers","family_code":"04","family_short":"视觉 Transformer","family_en":"Vision Transformers","family_icon":"IV","family_label":"视觉 Transformer：全局交互、层级窗口与高分辨率代价","archetype":"patch_token_encoder","archetype_en":"patch_token_encoder","accent":"#1F4E79","fig_badge":"Figure 1 · PDF p.3","fig_href":"https://openreview.net/forum?id=YicbFdNTTy","core_mech":"非重叠 patch 线性 token 化、CLS 汇聚与全局 Transformer encoder，完全移除卷积主干。","core_mech_en":"Splits images into non-overlapping patches, linearly projects them into tokens with positional embeddings, and processes them via a pure global Transformer encoder.","input_desc":"固定分辨率二维图像","input_en":"Fixed-resolution 2D image (or 3D sub-volume patches)","output_desc":"CLS 全局表征或类别概率","output_en":"Global [CLS] representation, patch token grid, or classification logits","form_title":"核心公式 · ViT 将图像块线性映射为带位置的 token 序列","form_title_en":"Core Formalism · Non-Overlapping Patch Tokenization & Global Self-Attention Encoding","nodes":[{"name":"输入图像","desc":"图像被规则切成互不重叠的 P×P 区块。","name_en":"Input Image","desc_en":"Ingests fixed-resolution 2d image (or 3d sub-volume patches) and prepares initial tensor representations (Input Image)."},{"name":"Patchify","desc":"每个 patch 展平，使二维空间问题变成长度 N 的序列。","name_en":"Patchify","desc_en":"Executes Patchify to extract primary structural features and establish spatial/sequence encoding."},{"name":"线性 Patch 嵌入","desc":"共享线性投影把每个 patch 映射到 D 维 token。","name_en":"Patch embedding","desc_en":"Performs Patch embedding within the core patch token encoder computation pathway."},{"name":"CLS + 位置","desc":"序列前置可学习 CLS token，并叠加可学习绝对位置编码。","name_en":"CLS +","desc_en":"Performs CLS + within the core patch token encoder computation pathway."},{"name":"全局 MSA","desc":"所有 patch token 在每层内进行全局多头自注意力。","name_en":"global MSA","desc_en":"Performs global MSA within the core patch token encoder computation pathway."},{"name":"MLP Block","desc":"两层前馈网络逐 token 做通道变换；MSA 与 MLP 均带 pre-norm residual。","name_en":"MLP Block","desc_en":"Performs MLP Block within the core patch token encoder computation pathway."},{"name":"L× Encoder","desc":"重复 Transformer encoder，空间分辨率与 token 数保持不变。","name_en":"L× Encoder","desc_en":"Applies L× Encoder to project aggregated representations toward the target task head."},{"name":"CLS Head","desc":"取最终 CLS 状态，经 LayerNorm 与线性头完成分类。","name_en":"CLS Head","desc_en":"Produces global [cls] representation, patch token grid, or classification logits via CLS Head."}],"design_principles":["把固定大小图像块直接视为 token，使纯 Transformer 可在视觉任务中工作。","全局 self-attention 从第一层起建立任意远 patch 间的内容依赖，而不依赖卷积感受野递增。","CLS token 通过多层注意力汇聚整幅图像，预训练规模与正则化决定其数据效率。"],"design_principles_en":["Core Hypothesis: Treat non-overlapping 16×16 image patches as sequence tokens and apply a standard isotropic Transformer encoder.","Architectural Delta: Linear patchify stem, learnable 1D positional embeddings, and global self-attention from the very first layer.","Mathematical Formalism: Non-Overlapping Patch Tokenization & Global Self-Attention Encoding."],"med_apps":["病理切片 patch、眼底图和二维放射影像可直接 token 化，但小病灶可能在粗 patch 中被平均。","医学小数据场景通常需要自然图像或领域自监督预训练，且高分辨率会使全局注意力显存按 N² 增长。"],"med_apps_en":["Clinical Translation: Dominant backbone for large-scale self-supervised pathology (UNI, Virchow) and multimodal medical foundation models.","Evidence & Safety Boundary: Excels under massive pretraining (MAE, DINOv2, CLIP); underperforms CNNs when trained from scratch on small medical cohorts."],"attrs":{"上一代瓶颈":"Transformer 缺少二维图像输入接口，视觉模型长期依赖卷积","核心想法":"把图像切成 patch token 并使用标准 Transformer encoder","关键改进":"patch embedding、位置编码和 class token 形成可扩展视觉编码器","医学适配":"成为医学 foundation encoder 主流，但 3D 和小病灶需更细致 token 化","适用范围与证据":"大规模预训练时强；小数据从头训练不一定优于 CNN"},"attrs_en":{"上一代瓶颈":"Standard Transformers could not directly ingest pixel grids due to quadratic cost, leaving computer vision reliant on CNNs.","核心想法":"Treat non-overlapping 16×16 image patches as sequence tokens and apply a standard isotropic Transformer encoder.","关键改进":"Linear patchify stem, learnable 1D positional embeddings, and global self-attention from the very first layer.","医学适配":"Dominant backbone for large-scale self-supervised pathology (UNI, Virchow) and multimodal medical foundation models.","适用范围与证据":"Excels under massive pretraining (MAE, DINOv2, CLIP); underperforms CNNs when trained from scratch on small medical cohorts."},"paper_title":"An Image Is Worth 16x16 Words: Transformers for Image Recognition at Scale","paper_url":"https://openreview.net/pdf?id=YicbFdNTTy","code_label":"作者/机构官方实现","code_url":"https://github.com/google-research/vision_transformer","has_code":true,"image":"assets/1488994ba7ff1b9b6ebd.avif"},{"id":"architecture_model_022_swin_transformer","num":22,"num_str":"022","year":2021,"year_str":"2021","venue":"ICCV","venue_group":"cv","era_group":"era3","title":"Swin Transformer","family_id":"models_vision_transformers","family_code":"04","family_short":"视觉 Transformer","family_en":"Vision Transformers","family_icon":"IV","family_label":"视觉 Transformer：全局交互、层级窗口与高分辨率代价","archetype":"hierarchical_shifted_window_transformer","archetype_en":"hierarchical_shifted_window_transformer","accent":"#1F4E79","fig_badge":"Figure 3 · PDF p.4","fig_href":"https://openaccess.thecvf.com/content/ICCV2021/html/Liu_Swin_Transformer_Hierarchical_Vision_Transformer_Using_Shifted_Windows_ICCV_2021_paper.html","core_mech":"W-MSA 与 SW-MSA 交替实现局部高效注意力和跨窗连接，并以 patch merging 形成层次金字塔。","core_mech_en":"Alternates regular Windowed Multi-Head Self-Attention (W-MSA) with Shifted-Window Attention (SW-MSA) across a patch-merging multi-scale pyramid.","input_desc":"二维图像","input_en":"2D image (or 3D volume in Video/3D Swin)","output_desc":"四级层次化特征金字塔或任务预测","output_en":"Four-stage multi-scale hierarchical feature pyramid or task predictions","form_title":"核心公式 · 移位窗口注意力实现跨窗口通信","form_title_en":"Core Formalism · Shifted-Window Partitioning for Linear-Complexity Cross-Window Exchange","nodes":[{"name":"输入图像","desc":"以 4×4 patch 为基本单元建立高分辨率 token 网格。","name_en":"Input Image","desc_en":"Ingests 2d image (or 3d volume in video/3d swin) and prepares initial tensor representations (Input Image)."},{"name":"Patch 嵌入","desc":"相邻像素块映射为 C 维 token，保留二维布局。","name_en":"Patch embedding","desc_en":"Executes Patch embedding to extract primary structural features and establish spatial/sequence encoding."},{"name":"窗口划分","desc":"特征被切成 M×M 非重叠局部窗口。","name_en":"Stage 03","desc_en":"Performs Stage 03 within the core hierarchical shifted window transformer computation pathway."},{"name":"W-MSA","desc":"注意力只在各局部窗口内部计算，复杂度相对图像大小近似线性。","name_en":"W-MSA","desc_en":"Performs W-MSA within the core hierarchical shifted window transformer computation pathway."},{"name":"循环移位 + Mask","desc":"下一 block 将窗口平移 M/2，并用 attention mask 保持有效边界。","name_en":"+ Mask","desc_en":"Performs + Mask within the core hierarchical shifted window transformer computation pathway."},{"name":"SW-MSA","desc":"移位窗口让上一层不同窗口的 token 在本层直接交互。","name_en":"SW-MSA","desc_en":"Performs SW-MSA within the core hierarchical shifted window transformer computation pathway."},{"name":"Patch Merging","desc":"拼接 2×2 邻域并线性投影；分辨率减半、通道增宽。","name_en":"Patch Merging","desc_en":"Performs Patch Merging within the core hierarchical shifted window transformer computation pathway."},{"name":"四级 Stage","desc":"重复 W-MSA/SW-MSA 对并逐级下采样，形成 CNN 式层次结构。","name_en":"Stage","desc_en":"Applies Stage to project aggregated representations toward the target task head."},{"name":"多尺度输出","desc":"各 stage 特征可送入分类头、检测 FPN 或分割 decoder。","name_en":"multi-scale output","desc_en":"Produces four-stage multi-scale hierarchical feature pyramid or task predictions via multi-scale output."}],"design_principles":["局部窗口把全局 N² attention 化为随像素数近似线性增长的窗口注意力。","交替的常规窗口与移位窗口在不增加窗口大小的前提下实现跨窗口通信。","patch merging 构造从细纹理到高语义的金字塔，使 Transformer 能原生服务密集预测。"],"design_principles_en":["Core Hypothesis: Restrict self-attention to local non-overlapping windows for linear scaling, shifting window boundaries between consecutive layers to bridge context.","Architectural Delta: Alternating W-MSA / SW-MSA, relative position bias, and 2×2 patch merging producing a CNN-like multi-scale hierarchy.","Mathematical Formalism: Shifted-Window Partitioning for Linear-Complexity Cross-Window Exchange."],"med_apps":["窗口机制适合高分辨率 CT/MR/病理图，但窗口边界和下采样仍可能削弱极小病灶。","层次特征可直接接 U-Net 式 decoder；三维实现需把窗口、移位与相对位置偏置扩展到 D×H×W。"],"med_apps_en":["Clinical Translation: Core backbone for Swin UNETR, TransMorph, MARS, and high-resolution 2D/3D medical dense prediction.","Evidence & Safety Boundary: Enduring hierarchical Transformer standard; window size and anisotropic voxel spacing require careful tuning."],"attrs":{"上一代瓶颈":"ViT 单尺度且全局注意力在高分辨率图像上二次增长","核心想法":"在局部窗口做注意力并通过 shifted windows 和 patch merging 建层级特征","关键改进":"固定窗口近线性计算、跨窗传播与 CNN 式多尺度金字塔","医学适配":"广泛用于 2D/3D 医学分割、检测和 Swin UNETR","适用范围与证据":"层级 Transformer 长期有价值；窗口与 patch 尺度仍是新超参数"},"attrs_en":{"上一代瓶颈":"Isotropic ViT maintains a single coarse token resolution and scales quadratically with image area, hindering dense segmentation.","核心想法":"Restrict self-attention to local non-overlapping windows for linear scaling, shifting window boundaries between consecutive layers to bridge context.","关键改进":"Alternating W-MSA / SW-MSA, relative position bias, and 2×2 patch merging producing a CNN-like multi-scale hierarchy.","医学适配":"Core backbone for Swin UNETR, TransMorph, MARS, and high-resolution 2D/3D medical dense prediction.","适用范围与证据":"Enduring hierarchical Transformer standard; window size and anisotropic voxel spacing require careful tuning."},"paper_title":"Swin Transformer: Hierarchical Vision Transformer using Shifted Windows","paper_url":"https://openaccess.thecvf.com/content/ICCV2021/html/Liu_Swin_Transformer_Hierarchical_Vision_Transformer_Using_Shifted_Windows_ICCV_2021_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/microsoft/Swin-Transformer","has_code":true,"image":"assets/d2ada49b01272180aba7.avif"},{"id":"architecture_model_023_mask2former","num":23,"num_str":"023","year":2022,"year_str":"2022","venue":"CVPR","venue_group":"cv","era_group":"era3","title":"Mask2Former","family_id":"models_dense_segmentation","family_code":"02","family_short":"稠密预测与医学分割","family_en":"Dense Segmentation","family_icon":"II","family_label":"稠密预测与医学分割：从像素输出到自配置系统","archetype":"query_masked_attention_segmentation","archetype_en":"query_masked_attention_segmentation","accent":"#145E75","fig_badge":"Figure 2 · PDF p.3","fig_href":"https://openaccess.thecvf.com/content/CVPR2022/html/Cheng_Masked-Attention_Mask_Transformer_for_Universal_Image_Segmentation_CVPR_2022_paper.html","core_mech":"上一层预测 mask 反向约束下一层 query cross-attention 的迭代集合分割。","core_mech_en":"Iterative set-prediction segmentation where predicted foreground masks from layer l-1 constrain query cross-attention in layer l.","input_desc":"二维图像","input_en":"2D image","output_desc":"一组带类别的二值 mask，可统一实例、语义与全景分割","output_en":"Set of class-labeled binary masks unifying semantic, instance, and panoptic segmentation","form_title":"核心公式 · 上一层 mask 限定下一层交叉注意力","form_title_en":"Core Formalism · Mask-Constrained Cross-Attention Restricted to Predicted Foreground Regions","nodes":[{"name":"输入图像","desc":"单一图像入口，不预设任务专属输出格式。","name_en":"Input Image","desc_en":"Ingests 2d image and prepares initial tensor representations (Input Image)."},{"name":"多尺度 Backbone","desc":"CNN 或 Swin 产生低至高分辨率特征层。","name_en":"multi-scale Backbone","desc_en":"Executes multi-scale Backbone to extract primary structural features and establish spatial/sequence encoding."},{"name":"Pixel Decoder","desc":"多尺度可变形 attention/FPN 融合并输出逐像素特征。","name_en":"Pixel Decoder","desc_en":"Performs Pixel Decoder within the core query masked attention segmentation computation pathway."},{"name":"Mask Features","desc":"高分辨率共享特征供所有 query 生成最终 mask。","name_en":"Mask Features","desc_en":"Performs Mask Features within the core query masked attention segmentation computation pathway."},{"name":"对象 Queries","desc":"固定数量可学习 query 表示潜在区域/实例。","name_en":"Queries","desc_en":"Performs Queries within the core query masked attention segmentation computation pathway."},{"name":"Masked Cross-Attn","desc":"每层 query 只关注上一层预测 mask 内的多尺度像素，而非整图。","name_en":"Masked Cross-Attn","desc_en":"Performs Masked Cross-Attn within the core query masked attention segmentation computation pathway."},{"name":"Self-Attn + FFN","desc":"query 间竞争/去重，并更新其语义状态。","name_en":"Self-Attn + FFN","desc_en":"Performs Self-Attn + FFN within the core query masked attention segmentation computation pathway."},{"name":"类别 Head","desc":"每个 query 输出类别或 no-object 概率。","name_en":"Head","desc_en":"Performs Head within the core query masked attention segmentation computation pathway."},{"name":"Mask Embedding","desc":"query mask embedding 与共享 mask features 点积得到像素 logits。","name_en":"Mask Embedding","desc_en":"Applies Mask Embedding to project aggregated representations toward the target task head."},{"name":"任务 Mask 集","desc":"按类别和 query 组合规则得到语义、实例或全景结果。","name_en":"Mask","desc_en":"Produces set of class-labeled binary masks unifying semantic, instance, and panoptic segmentation via Mask."}],"design_principles":["将分割重写为固定数量 query 对 mask 的集合预测，而不是逐像素独立分类。","masked attention 用上一轮 mask 把 cross-attention 限制在候选区域，既提高效率又强化局部一致性。","同一 class+mask 接口通过不同组合规则覆盖语义、实例和全景分割。"],"design_principles_en":["Core Hypothesis: Formulate all segmentation tasks as mask-classification set prediction using learnable object queries and masked cross-attention.","Architectural Delta: Multi-scale high-resolution pixel decoder + masked cross-attention attending strictly within each query's predicted foreground region.","Mathematical Formalism: Mask-Constrained Cross-Attention Restricted to Predicted Foreground Regions."],"med_apps":["query 集合适合多病灶、多器官和相互重叠实例，但小样本下需要处理 no-object 比例和匹配稳定性。","医学三维化的主要成本在多尺度 voxel features 与 decoder attention；可把 query 作为器官/病灶候选而非类别硬编码。"],"med_apps_en":["Clinical Translation: Inspires unified multi-instance nuclei, lesion, and open-vocabulary query segmentation in pathology and radiology.","Evidence & Safety Boundary: Influential universal task interface; 3D memory scaling, tiny lesions, and bipartite matching stability remain challenging."],"attrs":{"上一代瓶颈":"语义、实例和全景分割依赖各自专用结构，全图 cross-attention 昂贵","核心想法":"把分割统一为一组 mask queries 的分类与掩膜预测","关键改进":"masked cross-attention 只关注当前预测区域，配合多尺度 pixel decoder","医学适配":"启发医学多实例细胞、病灶和开放词汇 mask 接口","适用范围与证据":"任务接口影响持久；3D、小目标和 matching 稳定性仍是门槛"},"attrs_en":{"上一代瓶颈":"Semantic, instance, and panoptic segmentation relied on fragmented task heads, while global cross-attention converged slowly.","核心想法":"Formulate all segmentation tasks as mask-classification set prediction using learnable object queries and masked cross-attention.","关键改进":"Multi-scale high-resolution pixel decoder + masked cross-attention attending strictly within each query's predicted foreground region.","医学适配":"Inspires unified multi-instance nuclei, lesion, and open-vocabulary query segmentation in pathology and radiology.","适用范围与证据":"Influential universal task interface; 3D memory scaling, tiny lesions, and bipartite matching stability remain challenging."},"paper_title":"Masked-attention Mask Transformer for Universal Image Segmentation","paper_url":"https://openaccess.thecvf.com/content/CVPR2022/html/Cheng_Masked-Attention_Mask_Transformer_for_Universal_Image_Segmentation_CVPR_2022_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/facebookresearch/Mask2Former","has_code":true,"image":"assets/340446d69ea19ad8aa1b.avif"},{"id":"architecture_model_024_simclr","num":24,"num_str":"024","year":2020,"year_str":"2020","venue":"ICML","venue_group":"ml","era_group":"era3","title":"SimCLR","family_id":"models_self_supervised_learning","family_code":"05","family_short":"自监督表征学习","family_en":"Self-Supervised Learning","family_icon":"V","family_label":"自监督学习：对比、聚类、自蒸馏与遮挡重建","archetype":"siamese_contrastive_pretraining","archetype_en":"siamese_contrastive_pretraining","accent":"#5B3F8C","fig_badge":"Figure 2 · PDF p.2","fig_href":"https://proceedings.mlr.press/v119/chen20j.html","core_mech":"无动量教师或队列，以大 batch 内的两视图实例对和非线性投影头训练 NT-Xent。","core_mech_en":"Trains an encoder and non-linear MLP projection head via in-batch NT-Xent contrastive loss across dual augmented views without momentum queues.","input_desc":"同一图像经两次随机增强得到的视图","input_en":"Pair of randomly augmented views (x̃_i, x̃_j) of the same image","output_desc":"可迁移的图像 encoder 表征","output_en":"Transferable visual representation h = f(x) (discarding projection head g after pretraining)","form_title":"核心公式 · SimCLR 的批内 NT-Xent 对比目标","form_title_en":"Core Formalism · Normalized Temperature-Scaled Cross-Entropy (NT-Xent) Contrastive Loss","nodes":[{"name":"原始样本","desc":"一个 batch 中每幅图像作为一个实例类别。","name_en":"Stage 01","desc_en":"Ingests pair of randomly augmented views (x̃_i, x̃_j) of the same image and prepares initial tensor representations (Stage 01)."},{"name":"增强视图 A","desc":"随机裁剪、翻转、颜色扰动等组合生成第一视图。","name_en":"Stage 02","desc_en":"Executes Stage 02 to extract primary structural features and establish spatial/sequence encoding."},{"name":"增强视图 B","desc":"独立随机增强生成同一实例的第二视图。","name_en":"Stage 03","desc_en":"Performs Stage 03 within the core siamese contrastive pretraining computation pathway."},{"name":"共享 Encoder f","desc":"两个视图通过完全共享参数的 ResNet 得到 h。","name_en":"Encoder f","desc_en":"Performs Encoder f within the core siamese contrastive pretraining computation pathway."},{"name":"非线性投影 g","desc":"两层 MLP 将 h 映射到训练对比损失的 z 空间。","name_en":"projection g","desc_en":"Performs projection g within the core siamese contrastive pretraining computation pathway."},{"name":"L2 归一化","desc":"z 归一化后以内积表示余弦相似度。","name_en":"L2 normalization","desc_en":"Performs L2 normalization within the core siamese contrastive pretraining computation pathway."},{"name":"Batch 相似矩阵","desc":"2N 个视图两两比较；同源两视图为正对，其余为负对。","name_en":"Batch matrix","desc_en":"Performs Batch matrix within the core siamese contrastive pretraining computation pathway."},{"name":"NT-Xent","desc":"温度缩放交叉熵拉近正对并推远 batch 内负对。","name_en":"NT-Xent","desc_en":"Applies NT-Xent to project aggregated representations toward the target task head."},{"name":"下游表征 h","desc":"预训练后丢弃投影头，保留 encoder 输出微调或线性评估。","name_en":"representation h","desc_en":"Produces transferable visual representation h = f(x) (discarding projection head g after pretraining) via representation h."}],"design_principles":["同一实例的两种增强定义正样本，batch 内其他实例同时充当负样本。","强数据增强决定要学习的不变性，温度参数控制正负相似度分布的锐度。","把对比目标放在投影空间可避免直接扭曲供下游使用的 encoder 表征。"],"design_principles_en":["Core Hypothesis: Maximize agreement between differently augmented views of the same sample in a projected latent space while repelling all other batch samples.","Architectural Delta: Composition of strong augmentations, learnable non-linear MLP projection head g(·), and temperature-scaled cosine contrastive loss.","Mathematical Formalism: Normalized Temperature-Scaled Cross-Entropy (NT-Xent) Contrastive Loss."],"med_apps":["增强必须尊重医学语义：左右翻转、颜色扰动或强裁剪可能改变侧别、染色或病灶标签。","大 batch 负样本需求在 3D 影像中代价高；同患者切片还可能成为假负样本。"],"med_apps_en":["Clinical Translation: Sparked patient-aware, multi-view, and slice-proximity contrastive learning across radiology and pathology.","Evidence & Safety Boundary: Foundational contrastive SSL paradigm; requires large batch sizes and careful medical augmentation design to avoid false negatives."],"attrs":{"上一代瓶颈":"监督预训练依赖人工标签，早期自监督常依赖手工 pretext task","核心想法":"用两种增强视图和 NT-Xent/InfoNCE 学实例级表示","关键改进":"强增强、非线性 projection head、大 batch 与长训练","医学适配":"医学中推动患者级、多视图和体数据对比学习","适用范围与证据":"对比学习基础；医学增强和正负样本定义必须重设"},"attrs_en":{"上一代瓶颈":"Supervised pretraining required costly manual labels, while early heuristic pretext tasks learned brittle representations.","核心想法":"Maximize agreement between differently augmented views of the same sample in a projected latent space while repelling all other batch samples.","关键改进":"Composition of strong augmentations, learnable non-linear MLP projection head g(·), and temperature-scaled cosine contrastive loss.","医学适配":"Sparked patient-aware, multi-view, and slice-proximity contrastive learning across radiology and pathology.","适用范围与证据":"Foundational contrastive SSL paradigm; requires large batch sizes and careful medical augmentation design to avoid false negatives."},"paper_title":"A Simple Framework for Contrastive Learning of Visual Representations","paper_url":"https://proceedings.mlr.press/v119/chen20j.html","code_label":"作者/机构官方实现","code_url":"https://github.com/google-research/simclr","has_code":true,"image":"assets/dc805b88c479dafb8c5a.avif"},{"id":"architecture_model_025_moco","num":25,"num_str":"025","year":2020,"year_str":"2020","venue":"CVPR","venue_group":"cv","era_group":"era3","title":"MoCo","family_id":"models_self_supervised_learning","family_code":"05","family_short":"自监督表征学习","family_en":"Self-Supervised Learning","family_icon":"V","family_label":"自监督学习：对比、聚类、自蒸馏与遮挡重建","archetype":"momentum_dual_encoder_queue","archetype_en":"momentum_dual_encoder_queue","accent":"#5B3F8C","fig_badge":"Figure 2(a–c) · PDF p.3","fig_href":"https://openaccess.thecvf.com/content_CVPR_2020/html/He_Momentum_Contrast_for_Unsupervised_Visual_Representation_Learning_CVPR_2020_paper.html","core_mech":"由 EMA key encoder 维护一致编码、由 FIFO queue 提供大规模跨 batch 负样本的对比字典。","core_mech_en":"Decouples contrastive negative dictionary size from mini-batch size using a FIFO queue of encoded keys updated via a momentum (EMA) encoder.","input_desc":"同一图像的 query 与 key 增强视图","input_en":"Query view x^q and key view x^k of the same image","output_desc":"对比预训练后的 query encoder 表征","output_en":"Contrastively pretrained query encoder representation","form_title":"核心公式 · MoCo 动量 key encoder 与 FIFO 字典更新","form_title_en":"Core Formalism · Momentum-Updated Key Encoder & FIFO Queue Contrastive Dictionary","nodes":[{"name":"Query 视图","desc":"第一随机增强作为当前 mini-batch 的查询。","name_en":"Query","desc_en":"Ingests query view x^q and key view x^k of the same image and prepares initial tensor representations (Query)."},{"name":"Key 视图","desc":"第二随机增强作为与 query 匹配的正 key。","name_en":"Key","desc_en":"Executes Key to extract primary structural features and establish spatial/sequence encoding."},{"name":"Query Encoder","desc":"由损失直接反向传播更新的主编码器。","name_en":"Query Encoder","desc_en":"Performs Query Encoder within the core momentum dual encoder queue computation pathway."},{"name":"Momentum Encoder","desc":"参数是 query encoder 参数的指数移动平均，不接收梯度。","name_en":"Momentum Encoder","desc_en":"Performs Momentum Encoder within the core momentum dual encoder queue computation pathway."},{"name":"Key Queue","desc":"FIFO 字典保存跨多个 mini-batch 的已编码负 key。","name_en":"Key Queue","desc_en":"Performs Key Queue within the core momentum dual encoder queue computation pathway."},{"name":"点积 Logits","desc":"query 与正 key 及队列负 key 的归一化点积形成 logits。","name_en":"Logits","desc_en":"Performs Logits within the core momentum dual encoder queue computation pathway."},{"name":"InfoNCE","desc":"辨认匹配 key 的对比交叉熵只更新 query 分支。","name_en":"InfoNCE","desc_en":"Performs InfoNCE within the core momentum dual encoder queue computation pathway."},{"name":"EMA 更新","desc":"θ_k ← mθ_k +(1−m)θ_q，使字典中的 key 编码保持一致。","name_en":"EMA update","desc_en":"Applies EMA update to project aggregated representations toward the target task head."},{"name":"下游 Encoder","desc":"预训练后导出 query encoder 进行微调。","name_en":"Encoder","desc_en":"Produces contrastively pretrained query encoder representation via Encoder."}],"design_principles":["动态队列把负样本字典大小与 mini-batch 大小解耦。","动量更新使当前 key encoder 与队列中历史 key 的表示缓慢漂移，保持字典一致。","只有 query encoder 接收梯度，key 分支是在线生成稳定训练目标的教师。"],"design_principles_en":["Core Hypothesis: Maintain a large dynamic dictionary queue of negative embeddings encoded by a slowly progressing Exponential Moving Average (EMA) key encoder.","Architectural Delta: EMA key parameter update θ_k ← m θ_k + (1−m) θ_q paired with an enqueue/dequeue FIFO memory bank.","Mathematical Formalism: Momentum-Updated Key Encoder & FIFO Queue Contrastive Dictionary."],"med_apps":["队列降低 3D 医学影像对超大 batch 的依赖，但患者级去重仍是避免假负样本的关键。","动量表征适合跨扫描仪和跨中心预训练；队列中域分布严重失衡时可能学到中心身份。"],"med_apps_en":["Clinical Translation: Well-suited for compute-constrained 2D/3D medical contrastive pretraining where GPU memory restricts batch size.","Evidence & Safety Boundary: Classic contrastive mechanism; its EMA teacher principle directly informed BYOL, DINO, and modern SSL."],"attrs":{"上一代瓶颈":"SimCLR 的负样本规模与 batch size 强绑定","核心想法":"用 momentum encoder 与 queue 构造大而一致的动态负样本字典","关键改进":"EMA 更新 key encoder，把字典规模从当前 batch 解耦","医学适配":"适合医学小 batch、患者级采样和算力受限 SSL","适用范围与证据":"经典实现；其 momentum/EMA teacher 思想被后续方法继承，queue 本身并非统一模板"},"attrs_en":{"上一代瓶颈":"End-to-end contrastive learning (SimCLR) required massive multi-GPU batch sizes to supply sufficient negative samples.","核心想法":"Maintain a large dynamic dictionary queue of negative embeddings encoded by a slowly progressing Exponential Moving Average (EMA) key encoder.","关键改进":"EMA key parameter update θ_k ← m θ_k + (1−m) θ_q paired with an enqueue/dequeue FIFO memory bank.","医学适配":"Well-suited for compute-constrained 2D/3D medical contrastive pretraining where GPU memory restricts batch size.","适用范围与证据":"Classic contrastive mechanism; its EMA teacher principle directly informed BYOL, DINO, and modern SSL."},"paper_title":"Momentum Contrast for Unsupervised Visual Representation Learning","paper_url":"https://openaccess.thecvf.com/content_CVPR_2020/html/He_Momentum_Contrast_for_Unsupervised_Visual_Representation_Learning_CVPR_2020_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/facebookresearch/moco","has_code":true,"image":"assets/e26117f5da2a657f071e.avif"},{"id":"architecture_model_026_mae","num":26,"num_str":"026","year":2022,"year_str":"2022","venue":"CVPR","venue_group":"cv","era_group":"era3","title":"MAE","family_id":"models_self_supervised_learning","family_code":"05","family_short":"自监督表征学习","family_en":"Self-Supervised Learning","family_icon":"V","family_label":"自监督学习：对比、聚类、自蒸馏与遮挡重建","archetype":"asymmetric_masked_autoencoder","archetype_en":"asymmetric_masked_autoencoder","accent":"#5B3F8C","fig_badge":"Figure 1 · PDF p.1","fig_href":"https://openaccess.thecvf.com/content/CVPR2022/html/He_Masked_Autoencoders_Are_Scalable_Vision_Learners_CVPR_2022_paper.html","core_mech":"高比例随机遮蔽后仅编码可见 patch，再用轻量 decoder 重建 mask patch 的非对称自编码器。","core_mech_en":"Asymmetric autoencoder that masks 75% of image patches, encodes only the 25% visible tokens with a heavy ViT, and reconstructs pixels via a lightweight decoder.","input_desc":"随机遮蔽大比例 patch 的图像","input_en":"Image with a high proportion (e.g., 75%) of randomly masked patches","output_desc":"重建的被遮蔽 patch 与预训练视觉 encoder","output_en":"Reconstructed masked patches during pretraining; high-capacity ViT encoder for downstream fine-tuning","form_title":"核心公式 · 只在被遮 patch 上计算像素重建误差","form_title_en":"Core Formalism · Masked Patch Pixel Mean-Squared Error Computed Strictly on Masked Tokens","nodes":[{"name":"输入图像","desc":"图像切成固定大小的非重叠 patch。","name_en":"Input Image","desc_en":"Ingests image with a high proportion (e.g., 75%) of randomly masked patches and prepares initial tensor representations (Input Image)."},{"name":"随机遮蔽 75%","desc":"每幅图随机打乱 patch，仅保留少量可见 token。","name_en":"masked 75%","desc_en":"Executes masked 75% to extract primary structural features and establish spatial/sequence encoding."},{"name":"可见 Tokens","desc":"只有未遮蔽 patch 被线性嵌入并送入 encoder。","name_en":"Tokens","desc_en":"Performs Tokens within the core asymmetric masked autoencoder computation pathway."},{"name":"重型 ViT Encoder","desc":"高容量 encoder 仅处理约 25% token，显著降低预训练计算。","name_en":"ViT Encoder","desc_en":"Performs ViT Encoder within the core asymmetric masked autoencoder computation pathway."},{"name":"补 Mask Token","desc":"把可见编码投影到 decoder 维度，插入共享 mask token 并按原位置复原序列。","name_en":"Mask Token","desc_en":"Performs Mask Token within the core asymmetric masked autoencoder computation pathway."},{"name":"轻量 Decoder","desc":"较浅、较窄的 Transformer 同时处理可见与 mask token。","name_en":"Decoder","desc_en":"Performs Decoder within the core asymmetric masked autoencoder computation pathway."},{"name":"像素预测头","desc":"每个 token 预测对应 patch 的归一化像素值。","name_en":"pixel prediction","desc_en":"Performs pixel prediction within the core asymmetric masked autoencoder computation pathway."},{"name":"Masked MSE","desc":"均方误差只在被遮蔽 patch 上计算。","name_en":"Masked MSE","desc_en":"Applies Masked MSE to project aggregated representations toward the target task head."},{"name":"下游 Encoder","desc":"预训练结束后丢弃 decoder，仅迁移 encoder。","name_en":"Encoder","desc_en":"Produces reconstructed masked patches during pretraining; high-capacity vit encoder for downstream fine-tuning via Encoder."}],"design_principles":["自然图像存在高空间冗余，因此高遮蔽率迫使 encoder 学习对象结构而非局部复制。","遮蔽 token 不进入 encoder，计算集中在可见内容，形成重 encoder、轻 decoder 的非对称设计。","重建损失只监督不可见 patch，避免模型把能力浪费在已知像素的恒等映射。"],"design_principles_en":["Core Hypothesis: Exploit high spatial redundancy in images by dropping 75% of patches before the encoder and reconstructing raw normalized pixels.","Architectural Delta: Asymmetric encoder–decoder design (encoder processes only 25% visible tokens → >3× compute reduction) + high masking ratio.","Mathematical Formalism: Masked Patch Pixel Mean-Squared Error Computed Strictly on Masked Tokens."],"med_apps":["在 CT/MR 中可扩展为 3D block 遮蔽，但遮蔽尺度必须小心保留微小病灶与薄层结构。","像素重建容易偏向低频解剖；加入器官感知、频域或多模态目标可提高临床语义密度。"],"med_apps_en":["Clinical Translation: Workhorse self-supervised pretraining method for 3D CT/MRI volumes, gigapixel pathology, retinal OCT, and biosignals.","Evidence & Safety Boundary: Core SSL infrastructure; pixel-level MSE emphasizes fine texture and intensity, shining brightest under downstream fine-tuning."],"attrs":{"上一代瓶颈":"对比学习依赖强增强和大 batch，ViT 预训练计算昂贵","核心想法":"高比例遮挡图像 patch，仅让重型 encoder 处理可见 token，再轻量重建","关键改进":"约 75% masking 与非对称 encoder-decoder 显著降低计算","医学适配":"成为 2D、3D MRI/CT 与病理预训练的基础方法","适用范围与证据":"基础设施级 SSL；像素重建可能偏重低层强度"},"attrs_en":{"上一代瓶颈":"Contrastive SSL depended heavily on hand-crafted view augmentations, while full-token ViT pretraining was computationally expensive.","核心想法":"Exploit high spatial redundancy in images by dropping 75% of patches before the encoder and reconstructing raw normalized pixels.","关键改进":"Asymmetric encoder–decoder design (encoder processes only 25% visible tokens → >3× compute reduction) + high masking ratio.","医学适配":"Workhorse self-supervised pretraining method for 3D CT/MRI volumes, gigapixel pathology, retinal OCT, and biosignals.","适用范围与证据":"Core SSL infrastructure; pixel-level MSE emphasizes fine texture and intensity, shining brightest under downstream fine-tuning."},"paper_title":"Masked Autoencoders Are Scalable Vision Learners","paper_url":"https://openaccess.thecvf.com/content/CVPR2022/html/He_Masked_Autoencoders_Are_Scalable_Vision_Learners_CVPR_2022_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/facebookresearch/mae","has_code":true,"image":"assets/0bbd46531fb956c95cf0.avif"},{"id":"architecture_model_027_dino","num":27,"num_str":"027","year":2021,"year_str":"2021","venue":"ICCV","venue_group":"cv","era_group":"era3","title":"DINO","family_id":"models_self_supervised_learning","family_code":"05","family_short":"自监督表征学习","family_en":"Self-Supervised Learning","family_icon":"V","family_label":"自监督学习：对比、聚类、自蒸馏与遮挡重建","archetype":"self_distillation_ema_teacher","archetype_en":"self_distillation_ema_teacher","accent":"#5B3F8C","fig_badge":"Figure 2 · PDF p.2","fig_href":"https://openaccess.thecvf.com/content/ICCV2021/html/Caron_Emerging_Properties_in_Self-Supervised_Vision_Transformers_ICCV_2021_paper.html","core_mech":"无负样本的 EMA teacher–student 跨视图概率匹配，以 centering 与 sharpening 防止塌缩。","core_mech_en":"Negative-free self-distillation where a student ViT matches the centered, temperature-sharpened probability distribution of an EMA teacher across multi-crop views.","input_desc":"同一图像的多尺度全局与局部 crops","input_en":"2 global views and multiple local lower-resolution crops of an unlabeled image","output_desc":"无需标签的 ViT 图像与 patch 表征","output_en":"Self-distilled ViT global [CLS] and dense patch representations","form_title":"核心公式 · DINO 中心锐化教师与 EMA 自蒸馏","form_title_en":"Core Formalism · EMA Teacher–Student Cross-View Distillation with Centering & Sharpening","nodes":[{"name":"Multi-Crop 视图","desc":"每图生成两个全局 crop 和多个局部 crop；teacher 只看全局视图。","name_en":"Multi-Crop","desc_en":"Ingests 2 global views and multiple local lower-resolution crops of an unlabeled image and prepares initial tensor representations (Multi-Crop)."},{"name":"Student ViT","desc":"student 处理全部全局与局部视图并接收梯度。","name_en":"Student ViT","desc_en":"Executes Student ViT to extract primary structural features and establish spatial/sequence encoding."},{"name":"Student Head","desc":"MLP 与归一化/权重归一化层输出高维概率 logits。","name_en":"Student Head","desc_en":"Performs Student Head within the core self distillation ema teacher computation pathway."},{"name":"EMA Teacher","desc":"teacher 与 student 同构，参数由 student 的指数移动平均更新。","name_en":"EMA Teacher","desc_en":"Performs EMA Teacher within the core self distillation ema teacher computation pathway."},{"name":"Teacher Head","desc":"仅对全局 crops 生成无梯度目标分布。","name_en":"Teacher Head","desc_en":"Performs Teacher Head within the core self distillation ema teacher computation pathway."},{"name":"Center + Sharpen","desc":"teacher logits 减去移动中心并用较低温度锐化，协同避免塌缩。","name_en":"Center + Sharpen","desc_en":"Performs Center + Sharpen within the core self distillation ema teacher computation pathway."},{"name":"Cross-View CE","desc":"每个 teacher 全局视图监督来自另一视图的 student 输出。","name_en":"Cross-View CE","desc_en":"Performs Cross-View CE within the core self distillation ema teacher computation pathway."},{"name":"动量更新","desc":"训练后期提高 teacher 动量，使目标平滑稳定。","name_en":"update","desc_en":"Applies update to project aggregated representations toward the target task head."},{"name":"语义特征","desc":"导出 student/teacher backbone；ViT attention 常呈现无监督对象区域。","name_en":"feature","desc_en":"Produces self-distilled vit global [cls] and dense patch representations via feature."}],"design_principles":["teacher 不由标签训练，而是 student 参数的平滑时间集成，构成自蒸馏目标。","跨视图一致性要求局部 crop 与不同全局 crop 指向同一语义表示。","centering 抵消单一维度偏置、sharpening 避免均匀输出，两者共同抑制无负样本训练塌缩。"],"design_principles_en":["Core Hypothesis: Train a student network to predict the output distribution of a momentum-updated teacher across global-to-local crops, preventing collapse via centering and sharpening.","Architectural Delta: Multi-crop local-to-global correspondence + EMA teacher centering/sharpening yielding emergent object part segmentation in ViT attention.","Mathematical Formalism: EMA Teacher–Student Cross-View Distillation with Centering & Sharpening."],"med_apps":["多裁剪可从整张病理图与局部组织区域学习尺度一致性，但局部 crop 不应丢失诊断上下文。","无标签 attention 的区域性不等于病灶定位；仍需以标注任务和外部中心验证其临床可读性。"],"med_apps_en":["Clinical Translation: Directly underpins pathology tile foundation models (UNI, Virchow) and radiology self-supervised ViTs.","Evidence & Safety Boundary: Essential precursor to DINOv2; emergent attention maps reflect spatial grouping but should not be over-interpreted as causal proof."],"attrs":{"上一代瓶颈":"无标签 ViT 缺少稳定的语义学习目标与 collapse 控制，对比方法又依赖负样本","核心想法":"student 预测 EMA teacher 在多 crop 上的锐化、居中分布，无标签无显式负样本","关键改进":"self-distillation、EMA、stop-gradient、centering 与 multi-crop","医学适配":"其 patch 表示直接启发病理和放射 foundation encoder","适用范围与证据":"DINOv2 的直接祖先；机制与 collapse 控制仍必须理解"},"attrs_en":{"上一代瓶颈":"Contrastive ViTs required explicit negative pairs or memory banks, while naive self-distillation collapsed to trivial constant outputs.","核心想法":"Train a student network to predict the output distribution of a momentum-updated teacher across global-to-local crops, preventing collapse via centering and sharpening.","关键改进":"Multi-crop local-to-global correspondence + EMA teacher centering/sharpening yielding emergent object part segmentation in ViT attention.","医学适配":"Directly underpins pathology tile foundation models (UNI, Virchow) and radiology self-supervised ViTs.","适用范围与证据":"Essential precursor to DINOv2; emergent attention maps reflect spatial grouping but should not be over-interpreted as causal proof."},"paper_title":"Emerging Properties in Self-Supervised Vision Transformers","paper_url":"https://openaccess.thecvf.com/content/ICCV2021/html/Caron_Emerging_Properties_in_Self-Supervised_Vision_Transformers_ICCV_2021_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/facebookresearch/dino","has_code":true,"image":"assets/b191f9e8afec488c0169.avif"},{"id":"architecture_model_028_ibot","num":28,"num_str":"028","year":2022,"year_str":"2022","venue":"ICLR","venue_group":"ml","era_group":"era3","title":"iBOT","family_id":"models_self_supervised_learning","family_code":"05","family_short":"自监督表征学习","family_en":"Self-Supervised Learning","family_icon":"V","family_label":"自监督学习：对比、聚类、自蒸馏与遮挡重建","archetype":"online_tokenizer_image_patch_distillation","archetype_en":"online_tokenizer_image_patch_distillation","accent":"#5B3F8C","fig_badge":"Figure 3 · PDF p.4","fig_href":"https://openreview.net/forum?id=ydopy-e6Dg","core_mech":"EMA teacher 同时充当在线视觉 tokenizer，以图像级 DINO 蒸馏和被遮 patch token 蒸馏联合训练。","core_mech_en":"Uses the EMA teacher simultaneously as an online visual tokenizer to jointly distill masked patch tokens alongside global [CLS] self-distillation.","input_desc":"同一图像的多裁剪视图与随机遮蔽 patch","input_en":"Multi-crop augmented views with random block-wise patch masking applied to the student","output_desc":"同时具备全局语义和局部 patch 语义的视觉表征","output_en":"ViT representations capturing both global image semantics and fine-grained local patch semantics","form_title":"核心公式 · 图像级蒸馏叠加被遮 patch token 蒸馏","form_title_en":"Core Formalism · Joint Global [CLS] Self-Distillation & Online Masked Patch Token Distillation","nodes":[{"name":"Crops + Patch Mask","desc":"student 视图随机遮蔽部分 patch；teacher 观察对应未遮蔽全局视图。","name_en":"Crops + Patch Mask","desc_en":"Ingests multi-crop augmented views with random block-wise patch masking applied to the student and prepares initial tensor representations (Crops + Patch Mask)."},{"name":"Student ViT","desc":"输出 CLS token 与所有 patch token，接收梯度。","name_en":"Student ViT","desc_en":"Executes Student ViT to extract primary structural features and establish spatial/sequence encoding."},{"name":"EMA Teacher","desc":"同构 teacher 在完整图像上产生在线目标，参数由 EMA 更新。","name_en":"EMA Teacher","desc_en":"Performs EMA Teacher within the core online tokenizer image patch distillation computation pathway."},{"name":"CLS Heads","desc":"student 与 teacher 的 CLS 概率用于跨视图图像级自蒸馏。","name_en":"CLS Heads","desc_en":"Performs CLS Heads within the core online tokenizer image patch distillation computation pathway."},{"name":"Patch Heads","desc":"teacher patch 输出作为在线视觉 token；student 对被遮位置预测这些分布。","name_en":"Patch Heads","desc_en":"Performs Patch Heads within the core online tokenizer image patch distillation computation pathway."},{"name":"全局蒸馏","desc":"不同 crops 的 CLS 概率交叉熵继承 DINO 的图像级不变性。","name_en":"global distillation","desc_en":"Performs global distillation within the core online tokenizer image patch distillation computation pathway."},{"name":"Masked Patch 蒸馏","desc":"只在 student 被遮蔽位置匹配 teacher 对应 patch 分布。","name_en":"Masked Patch distillation","desc_en":"Performs Masked Patch distillation within the core online tokenizer image patch distillation computation pathway."},{"name":"联合目标","desc":"图像级与 patch 级自蒸馏共同更新 student。","name_en":"objective","desc_en":"Applies objective to project aggregated representations toward the target task head."},{"name":"全局 + 稠密特征","desc":"CLS 服务分类，patch tokens 服务检测、分割和对应关系。","name_en":"global + feature","desc_en":"Produces vit representations capturing both global image semantics and fine-grained local patch semantics via global + feature."}],"design_principles":["把 teacher 自身的 patch 分布当作在线 tokenizer，避免依赖离线聚类或固定视觉词表。","masked image modeling 不直接回归像素，而是预测 teacher 的语义 token，提升局部表征的抽象层级。","CLS 跨视图目标与 patch 遮蔽目标分别约束全局不变性和局部可辨性。"],"design_principles_en":["Core Hypothesis: Turn the EMA teacher network itself into an online continuous/categorical tokenizer supervising masked student patch tokens.","Architectural Delta: Unifies DINO-style global self-distillation with masked image modeling (MIM) in a single single-stage online teacher–student loop.","Mathematical Formalism: Joint Global [CLS] Self-Distillation & Online Masked Patch Token Distillation."],"med_apps":["patch 级语义目标更契合病灶分割和组织检索，但位置对应要求增强几何变换可精确追踪。","teacher 可能把数据偏差固化为伪标签，跨机构或跨染色验证仍不可省略。"],"med_apps_en":["Clinical Translation: Core pretraining ingredient in DINOv2, Phikon, UNI, Virchow, and TITAN pathology foundation models.","Evidence & Safety Boundary: Highly effective dense + global SSL objective; standardly deployed in tandem with DINOv2 recipes."],"attrs":{"上一代瓶颈":"BEiT 依赖离线离散 tokenizer，局部与全局目标割裂","核心想法":"用 EMA teacher 作为在线 tokenizer，同时蒸馏 masked patch 和全局 class token","关键改进":"联合在线 tokenization、patch-level MIM 与 image-level self-distillation","医学适配":"成为病理 Phikon、TITAN 等医学 foundation 配方的重要来源","适用范围与证据":"重要训练思想；常与 DINO 系目标组合使用"},"attrs_en":{"上一代瓶颈":"BEiT required a separately pretrained offline discrete VAE tokenizer, decoupling local token recovery from global semantic learning.","核心想法":"Turn the EMA teacher network itself into an online continuous/categorical tokenizer supervising masked student patch tokens.","关键改进":"Unifies DINO-style global self-distillation with masked image modeling (MIM) in a single single-stage online teacher–student loop.","医学适配":"Core pretraining ingredient in DINOv2, Phikon, UNI, Virchow, and TITAN pathology foundation models.","适用范围与证据":"Highly effective dense + global SSL objective; standardly deployed in tandem with DINOv2 recipes."},"paper_title":"iBOT: Image BERT Pre-Training with Online Tokenizer","paper_url":"https://openreview.net/pdf?id=ydopy-e6Dg","code_label":"作者/机构官方实现","code_url":"https://github.com/bytedance/ibot","has_code":true,"image":"assets/e6b1cc75e414f88e27b9.avif"},{"id":"architecture_model_029_dinov2","num":29,"num_str":"029","year":2024,"year_str":"2024","venue":"TMLR","venue_group":"ml","era_group":"era4","title":"DINOv2","family_id":"models_self_supervised_learning","family_code":"05","family_short":"自监督表征学习","family_en":"Self-Supervised Learning","family_icon":"V","family_label":"自监督学习：对比、聚类、自蒸馏与遮挡重建","archetype":"curated_data_composite_self_distillation","archetype_en":"curated_data_composite_self_distillation","accent":"#5B3F8C","fig_badge":"Figure 3 · PDF p.4","fig_href":"https://openreview.net/forum?id=a68SUt6zFt","core_mech":"以 LVD-142M 数据策展配合 DINO+iBOT+KoLeo 复合自监督，并通过跨尺寸蒸馏形成模型家族。","core_mech_en":"Combines automated deduplication/retrieval curation (LVD-142M) with a composite DINO + iBOT + KoLeo objective and multi-resolution distillation.","input_desc":"经自动去重、检索与平衡构建的大规模无标签图像池","input_en":"Large-scale deduplicated and rebalanced unlabeled image corpus","output_desc":"跨域可迁移的全局与 patch 视觉特征","output_en":"Out-of-the-box transferable frozen global and dense patch embeddings across model scales","form_title":"核心公式 · DINO、iBOT 与 KoLeo 的复合目标","form_title_en":"Core Formalism · Composite DINO Image Loss + iBOT Patch MIM Loss + KoLeo Uniformity Regularizer","nodes":[{"name":"原始图像池","desc":"从超大规模未整理网络图像出发。","name_en":"Stage 01","desc_en":"Ingests large-scale deduplicated and rebalanced unlabeled image corpus and prepares initial tensor representations (Stage 01)."},{"name":"LVD-142M 策展","desc":"用种子数据、相似检索、去重与重平衡构造 1.42 亿图像训练集。","name_en":"LVD-142M","desc_en":"Executes LVD-142M to extract primary structural features and establish spatial/sequence encoding."},{"name":"Multi-Crop + Mask","desc":"全局/局部 crops 与 patch masking 同时生成训练视图。","name_en":"Multi-Crop + Mask","desc_en":"Performs Multi-Crop + Mask within the core curated data composite self distillation computation pathway."},{"name":"Student ViT","desc":"ViT-g/14 等 student 输出 CLS 与 patch tokens，并接收梯度。","name_en":"Student ViT","desc_en":"Performs Student ViT within the core curated data composite self distillation computation pathway."},{"name":"EMA Teacher","desc":"teacher 产生平滑的图像级和 patch 级目标。","name_en":"EMA Teacher","desc_en":"Performs EMA Teacher within the core curated data composite self distillation computation pathway."},{"name":"DINO Loss","desc":"跨视图 CLS 自蒸馏学习图像级语义不变性。","name_en":"DINO Loss","desc_en":"Performs DINO Loss within the core curated data composite self distillation computation pathway."},{"name":"iBOT Loss","desc":"student 在被遮位置预测 teacher patch 分布。","name_en":"iBOT Loss","desc_en":"Performs iBOT Loss within the core curated data composite self distillation computation pathway."},{"name":"KoLeo 正则","desc":"鼓励 batch 内特征在单位超球面更均匀分散，提升多样性。","name_en":"KoLeo regularization","desc_en":"Performs KoLeo regularization within the core curated data composite self distillation computation pathway."},{"name":"跨尺寸蒸馏","desc":"用大 teacher 训练更小 ViT，保留高质量表征并降低部署成本。","name_en":"distillation","desc_en":"Applies distillation to project aggregated representations toward the target task head."},{"name":"通用视觉特征","desc":"冻结 backbone 即可支持分类、检索、深度与密集预测。","name_en":"feature","desc_en":"Produces out-of-the-box transferable frozen global and dense patch embeddings across model scales via feature."}],"design_principles":["数据策展是结构的一部分：去重和与目标域相似的重平衡直接决定基础表征覆盖面。","DINO 图像目标、iBOT patch 目标和 KoLeo 分散正则共同约束语义、稠密局部性与特征多样性。","EMA teacher 与跨尺寸蒸馏把大模型的稳定目标迁移到多种容量的无标签 student。"],"design_principles_en":["Core Hypothesis: Curate a balanced, deduplicated pretraining corpus via embedding retrieval and train a scalable ViT family with composite self-distillation.","Architectural Delta: Automated data curation pipeline + DINO + untied-head iBOT + KoLeo sphere uniformity regularizer + high-resolution short adaptation.","Mathematical Formalism: Composite DINO Image Loss + iBOT Patch MIM Loss + KoLeo Uniformity Regularizer."],"med_apps":["DINOv2 是强通用初始化，但 LVD-142M 并非医学策展集，细粒度病理和三维成像仍存在域差。","医学部署应分别验证冻结特征、全量微调和参数高效适配，不能把自然图像零样本性能等同于临床泛化。"],"med_apps_en":["Clinical Translation: Forms the direct algorithmic backbone of modern pathology foundation encoders (UNI, Virchow, Prov-GigaPath) and RAD-DINO.","Evidence & Safety Boundary: Gold-standard frozen visual feature extractor; natural-image weights still benefit from in-domain medical adaptation for 3D/grayscale."],"attrs":{"上一代瓶颈":"早期 SSL 的数据治理与大规模训练配方难扩展、难复现","核心想法":"在清洗的 LVD-142M 上结合 DINO、iBOT 与 KoLeo 训练可复用视觉特征","关键改进":"自动数据筛选、复合自蒸馏目标和多尺寸蒸馏","医学适配":"直接支撑 UNI、Virchow 等病理 foundation encoder","适用范围与证据":"强通用特征底座；自然图像域不能自动覆盖灰阶、3D 和微小病灶"},"attrs_en":{"上一代瓶颈":"Prior self-supervised models degraded on uncurated web noise and often required full end-to-end fine-tuning for dense tasks.","核心想法":"Curate a balanced, deduplicated pretraining corpus via embedding retrieval and train a scalable ViT family with composite self-distillation.","关键改进":"Automated data curation pipeline + DINO + untied-head iBOT + KoLeo sphere uniformity regularizer + high-resolution short adaptation.","医学适配":"Forms the direct algorithmic backbone of modern pathology foundation encoders (UNI, Virchow, Prov-GigaPath) and RAD-DINO.","适用范围与证据":"Gold-standard frozen visual feature extractor; natural-image weights still benefit from in-domain medical adaptation for 3D/grayscale."},"paper_title":"DINOv2: Learning Robust Visual Features without Supervision","paper_url":"https://openreview.net/forum?id=a68SUt6zFt","code_label":"作者/机构官方实现","code_url":"https://github.com/facebookresearch/dinov2","has_code":true,"image":"assets/b6d4c62f5cfada1b9cf7.avif"},{"id":"architecture_model_030_clip","num":30,"num_str":"030","year":2021,"year_str":"2021","venue":"ICML","venue_group":"ml","era_group":"era3","title":"CLIP","family_id":"models_vision_language","family_code":"07","family_short":"图文对齐与医学 VLM","family_en":"Vision-Language Models","family_icon":"VII","family_label":"图文对齐与生成式 VLM：开放语义不等于视觉事实","archetype":"dual_tower_image_text_contrastive","archetype_en":"dual_tower_image_text_contrastive","accent":"#7A3547","fig_badge":"Figure 1 · PDF p.2","fig_href":"https://proceedings.mlr.press/v139/radford21a.html","core_mech":"完全分离的图像/文本双塔，通过批内 N×N 对称对比目标对齐，并用文本 prompt 充当开放词表分类器。","core_mech_en":"Aligns separate image and text encoders in a shared embedding space via symmetric in-batch N×N contrastive loss, turning text prompts into zero-shot classifiers.","input_desc":"批量图像与自然语言文本配对","input_en":"Mini-batch of N paired (image, natural-language caption) samples","output_desc":"共享嵌入空间中的图像/文本向量与零样本类别分数","output_en":"L2-normalized shared-space image/text embeddings and cosine zero-shot classification logits","form_title":"核心公式 · CLIP 图文双塔的对称批内匹配","form_title_en":"Core Formalism · Symmetric Bidirectional In-Batch Image–Text Contrastive Alignment","nodes":[{"name":"图像批次","desc":"N 幅图像构成视觉分支输入。","name_en":"Stage 01","desc_en":"Ingests mini-batch of n paired (image, natural-language caption) samples and prepares initial tensor representations (Stage 01)."},{"name":"Image Encoder","desc":"ResNet 或 ViT 将每幅图像编码为一个全局向量。","name_en":"Image Encoder","desc_en":"Executes Image Encoder to extract primary structural features and establish spatial/sequence encoding."},{"name":"图像投影 + Norm","desc":"线性投影并 L2 归一化到共享 d 维球面。","name_en":"projection + Norm","desc_en":"Performs projection + Norm within the core dual tower image text contrastive computation pathway."},{"name":"文本批次","desc":"与图像配对的 captions，零样本时替换为类别 prompt。","name_en":"Stage 04","desc_en":"Performs Stage 04 within the core dual tower image text contrastive computation pathway."},{"name":"Text Transformer","desc":"因果 Transformer 取 EOT token 作为句子表示。","name_en":"Text Transformer","desc_en":"Performs Text Transformer within the core dual tower image text contrastive computation pathway."},{"name":"文本投影 + Norm","desc":"线性投影并 L2 归一化到同一嵌入空间。","name_en":"projection + Norm","desc_en":"Performs projection + Norm within the core dual tower image text contrastive computation pathway."},{"name":"N×N 相似矩阵","desc":"所有图像与所有文本做余弦相似度并乘可学习温度尺度。","name_en":"N×N matrix","desc_en":"Performs N×N matrix within the core dual tower image text contrastive computation pathway."},{"name":"双向 CE","desc":"图像找文本与文本找图像的交叉熵取平均。","name_en":"CE","desc_en":"Applies CE to project aggregated representations toward the target task head."},{"name":"Prompt 分类","desc":"候选类别写成文本模板，图像按与各文本向量的相似度分类。","name_en":"Prompt","desc_en":"Produces l2-normalized shared-space image/text embeddings and cosine zero-shot classification logits via Prompt."}],"design_principles":["批内配对矩阵把自然语言监督转化为大规模图文匹配分类。","双塔只在最终嵌入空间交互，可分别预计算图像或文本向量并高效检索。","类别名称经 prompt 编码后成为动态分类器权重，从而不训练新分类头即可零样本预测。"],"design_principles_en":["Core Hypothesis: Train dual image and text encoders jointly on 400M image–text pairs to maximize cosine similarity of true pairs against N²−N negatives.","Architectural Delta: Scalable dual-encoder contrastive pretraining + natural-language prompt templates enabling zero-shot open-vocabulary transfer.","Mathematical Formalism: Symmetric Bidirectional In-Batch Image–Text Contrastive Alignment."],"med_apps":["自由文本报告可提供比单一诊断标签更丰富的监督，但否定、历史病变和报告模板会制造配对噪声。","零样本医学分类高度依赖术语和 prompt 设计；跨机构验证与校准优先于仅报告 AUROC。"],"med_apps_en":["Clinical Translation: Foundational blueprint for ConVIRT, GLoRIA, BioViL, BiomedCLIP, CONCH, and multimodal radiology/pathology retrieval.","Evidence & Safety Boundary: Core VLM infrastructure; global pooled vectors lack fine spatial localization and require calibration before clinical thresholding."],"attrs":{"上一代瓶颈":"监督分类器只能识别固定类别，类别标签表达有限","核心想法":"双编码器以对称图文对比损失建立开放词汇共享嵌入空间","关键改进":"海量图文弱监督、prompt zero-shot 与高效检索","医学适配":"奠定 CXR-report、病理-caption 和医学 zero-shot VLM 路线","适用范围与证据":"医学 VLM 基础设施；global embedding、false negatives 与校准仍有限"},"attrs_en":{"上一代瓶颈":"Closed-set classifiers could not generalize to unseen diagnostic categories or leverage rich free-text clinical descriptions.","核心想法":"Train dual image and text encoders jointly on 400M image–text pairs to maximize cosine similarity of true pairs against N²−N negatives.","关键改进":"Scalable dual-encoder contrastive pretraining + natural-language prompt templates enabling zero-shot open-vocabulary transfer.","医学适配":"Foundational blueprint for ConVIRT, GLoRIA, BioViL, BiomedCLIP, CONCH, and multimodal radiology/pathology retrieval.","适用范围与证据":"Core VLM infrastructure; global pooled vectors lack fine spatial localization and require calibration before clinical thresholding."},"paper_title":"Learning Transferable Visual Models From Natural Language Supervision","paper_url":"https://proceedings.mlr.press/v139/radford21a.html","code_label":"作者/机构官方实现","code_url":"https://github.com/openai/CLIP","has_code":true,"image":"assets/311e6533af3fc6ce2cd7.avif"},{"id":"architecture_model_031_blip_2","num":31,"num_str":"031","year":2023,"year_str":"2023","venue":"ICML","venue_group":"ml","era_group":"era4","title":"BLIP-2","family_id":"models_vision_language","family_code":"07","family_short":"图文对齐与医学 VLM","family_en":"Vision-Language Models","family_icon":"VII","family_label":"图文对齐与生成式 VLM：开放语义不等于视觉事实","archetype":"frozen_vision_qformer_frozen_llm_bridge","archetype_en":"frozen_vision_qformer_frozen_llm_bridge","accent":"#7A3547","fig_badge":"Figure 1 · PDF p.1","fig_href":"https://proceedings.mlr.press/v202/li23q.html","core_mech":"Q-Former 的 learnable queries 作为冻结图像 encoder 与冻结 LLM 之间唯一可训练的视觉信息瓶颈。","core_mech_en":"Bridges a frozen pretrained image encoder to a frozen LLM using a lightweight Querying Transformer (Q-Former) with learnable query tokens as an information bottleneck.","input_desc":"图像与文本配对，生成阶段输入图像和文本 prompt","input_en":"Image + text caption (Stage 1) or image + natural-language instruction prompt (Stage 2)","output_desc":"图像条件文本或视觉语言表征","output_en":"Fixed-length visual query embeddings and autoregressive image-conditioned text generation","form_title":"核心公式 · Q-Former queries 压缩视觉 token 后投影给 LLM","form_title_en":"Core Formalism · Learnable Q-Former Queries Extracting Text-Relevant Visual Tokens for a Frozen LLM","nodes":[{"name":"输入图像","desc":"图像由已预训练且冻结的视觉主干读取。","name_en":"Input Image","desc_en":"Ingests image + text caption (stage 1) or image + natural-language instruction prompt (stage 2) and prepares initial tensor representations (Input Image)."},{"name":"冻结 Image Encoder","desc":"高容量 ViT 产生空间视觉 tokens，BLIP-2 训练时不更新。","name_en":"Frozen Image Encoder","desc_en":"Executes Frozen Image Encoder to extract primary structural features and establish spatial/sequence encoding."},{"name":"可学习 Queries","desc":"固定数量 query token 是视觉信息进入语言侧的可训练瓶颈。","name_en":"Learnable Query Tokens","desc_en":"Performs Learnable Query Tokens within the core frozen vision qformer frozen llm bridge computation pathway."},{"name":"Q-Former","desc":"共享 self-attention 的两个 Transformer 子模块中，query 以周期性交叉注意力读取冻结视觉 tokens。","name_en":"Q-Former","desc_en":"Performs Q-Former within the core frozen vision qformer frozen llm bridge computation pathway."},{"name":"表征学习三目标","desc":"图文对比、图文匹配与图像条件文本生成共同训练 query–vision 对齐。","name_en":"representation objective","desc_en":"Performs representation objective within the core frozen vision qformer frozen llm bridge computation pathway."},{"name":"LLM 投影","desc":"Q-Former 输出线性映射到目标 LLM 的 token embedding 维度。","name_en":"LLM projection","desc_en":"Performs LLM projection within the core frozen vision qformer frozen llm bridge computation pathway."},{"name":"文本 Prompt","desc":"任务指令或问题与视觉前缀共同构成 LLM 上下文。","name_en":"Text Prompt","desc_en":"Performs Text Prompt within the core frozen vision qformer frozen llm bridge computation pathway."},{"name":"冻结 LLM","desc":"OPT 或 FlanT5 等语言模型保持冻结，仅由视觉前缀条件化。","name_en":"Frozen LLM","desc_en":"Applies Frozen LLM to project aggregated representations toward the target task head."},{"name":"条件生成","desc":"LLM 自回归/序列到序列地产生描述、答案或其他文本。","name_en":"Stage 09","desc_en":"Produces fixed-length visual query embeddings and autoregressive image-conditioned text generation via Stage 09."}],"design_principles":["Q-Former 用少量 learnable queries 从密集视觉 tokens 中抽取与文本最相关的信息，形成窄接口。","视觉 encoder 与 LLM 均冻结，把训练成本和灾难性遗忘集中到轻量跨模态桥。","先做视觉语言表征对齐，再做面向 LLM 的生成对齐，分阶段解决模态差异与语言接口差异。"],"design_principles_en":["Core Hypothesis: Keep both the vision encoder and LLM frozen, training only a lightweight Q-Former bottleneck to extract language-informative visual features.","Architectural Delta: Two-stage pretraining: Stage 1 vision–language representation learning (ITC + ITM + ITG) followed by Stage 2 vision-to-LLM generative alignment.","Mathematical Formalism: Learnable Q-Former Queries Extracting Text-Relevant Visual Tokens for a Frozen LLM."],"med_apps":["可将冻结医学图像主干接入领域 LLM，但固定 query 数可能压缩掉多病灶或三维细节。","生成流畅度来自 LLM，不等于影像事实正确；需要定位证据、否定识别和幻觉审计。"],"med_apps_en":["Clinical Translation: Canonical connector architecture behind medical VQA, report generation, and multimodal LLM assistants.","Evidence & Safety Boundary: Highly influential modular paradigm; strong frozen LLM priors can still hallucinate plausible text detached from visual query tokens."],"attrs":{"上一代瓶颈":"端到端训练大型视觉语言模型成本过高","核心想法":"冻结视觉 encoder 与 LLM，只训练 Q-Former 连接视觉查询和语言空间","关键改进":"两阶段图文表示与生成训练的轻量 connector","医学适配":"成为最有影响力的 connector-based 医学 MLLM、VQA 和报告生成模板之一","适用范围与证据":"架构影响持久；语言先验可能覆盖真实视觉证据"},"attrs_en":{"上一代瓶颈":"End-to-end joint pretraining of giant vision encoders and multi-billion-parameter LLMs was computationally prohibitive.","核心想法":"Keep both the vision encoder and LLM frozen, training only a lightweight Q-Former bottleneck to extract language-informative visual features.","关键改进":"Two-stage pretraining: Stage 1 vision–language representation learning (ITC + ITM + ITG) followed by Stage 2 vision-to-LLM generative alignment.","医学适配":"Canonical connector architecture behind medical VQA, report generation, and multimodal LLM assistants.","适用范围与证据":"Highly influential modular paradigm; strong frozen LLM priors can still hallucinate plausible text detached from visual query tokens."},"paper_title":"BLIP-2: Bootstrapping Language-Image Pre-training with Frozen Image Encoders and Large Language Models","paper_url":"https://proceedings.mlr.press/v202/li23q.html","code_label":"作者/机构官方实现","code_url":"https://github.com/salesforce/LAVIS","has_code":true,"image":"assets/2fa465929474eab89acc.avif"},{"id":"architecture_model_032_segment_anything__sam","num":32,"num_str":"032","year":2023,"year_str":"2023","venue":"ICCV","venue_group":"cv","era_group":"era4","title":"Segment Anything (SAM)","family_id":"models_promptable_segmentation","family_code":"06","family_short":"可提示交互式分割","family_en":"Promptable Segmentation","family_icon":"VI","family_label":"可提示分割：把固定类别头改造成交互式纠错接口","archetype":"promptable_segmentation_three_part","archetype_en":"promptable_segmentation_three_part","accent":"#145E75","fig_badge":"Figure 4 · PDF p.5","fig_href":"https://openaccess.thecvf.com/content/ICCV2023/html/Kirillov_Segment_Anything_ICCV_2023_paper.html","core_mech":"可缓存的重型 image encoder、轻量 prompt encoder 与双向 attention mask decoder 解耦，并以动态 hypernetwork 输出多候选 mask。","core_mech_en":"Decouples a heavy cacheable ViT image encoder from a lightweight spatial prompt encoder (points/boxes/masks) and an ambiguity-aware two-way attention mask decoder.","input_desc":"图像与点、框、粗 mask 或文本映射后的空间提示","input_en":"2D image + interactive spatial prompts (foreground/background points, bounding box, or coarse mask)","output_desc":"多个候选二值 mask 及其质量分数","output_en":"Multiple candidate binary segmentation masks with predicted IoU quality scores","form_title":"核心公式 · SAM 由 mask token 动态生成逐像素 mask","form_title_en":"Core Formalism · Prompt-Conditioned Two-Way Attention & Dynamic Hypernetwork Mask Generation","nodes":[{"name":"输入图像","desc":"图像统一缩放/填充到模型分辨率。","name_en":"Input Image","desc_en":"Ingests 2d image + interactive spatial prompts (foreground/background points, bounding box, or coarse mask) and prepares initial tensor representations (Input Image)."},{"name":"ViT Image Encoder","desc":"重型 ViT 一次性计算稠密图像 embedding，可对多次提示复用。","name_en":"ViT Image Encoder","desc_en":"Executes ViT Image Encoder to extract primary structural features and establish spatial/sequence encoding."},{"name":"点 / 框 / Mask","desc":"正负点、边界框为 sparse prompts；已有 mask 为 dense prompt。","name_en":"Mask","desc_en":"Performs Mask within the core promptable segmentation three part computation pathway."},{"name":"Prompt Encoder","desc":"坐标位置编码加类型 embedding 表示点/框，卷积表示 mask。","name_en":"Prompt Encoder","desc_en":"Performs Prompt Encoder within the core promptable segmentation three part computation pathway."},{"name":"Two-Way Transformer","desc":"prompt tokens 与 image tokens 双向 cross-attention，既更新提示也回写图像表示。","name_en":"Two-Way Transformer","desc_en":"Performs Two-Way Transformer within the core promptable segmentation three part computation pathway."},{"name":"Mask Tokens","desc":"若干输出 token 分别表示候选 mask；另有 IoU token 估计质量。","name_en":"Mask Tokens","desc_en":"Performs Mask Tokens within the core promptable segmentation three part computation pathway."},{"name":"上采样 Embedding","desc":"转置卷积把低分辨率图像 embedding 提升到 mask 网格。","name_en":"upsampling Embedding","desc_en":"Performs upsampling Embedding within the core promptable segmentation three part computation pathway."},{"name":"动态 Mask Head","desc":"每个 mask token 经小 MLP 生成权重，与上采样图像 embedding 逐点内积。","name_en":"dynamic Mask Head","desc_en":"Applies dynamic Mask Head to project aggregated representations toward the target task head."},{"name":"多 Mask + IoU","desc":"对歧义提示输出多个候选，并以预测 IoU 排序。","name_en":"Mask + IoU","desc_en":"Produces multiple candidate binary segmentation masks with predicted iou quality scores via Mask + IoU."}],"design_principles":["把图像编码与提示解码拆开，使昂贵 image embedding 可被交互式多轮提示反复复用。","two-way attention 不是单向读取图像，而是让 prompt 与 image tokens 相互条件化。","多 mask 输出显式承认单点等提示的固有歧义，并以独立质量头帮助选择。"],"design_principles_en":["Core Hypothesis: Amortize heavy image feature extraction once per image, then decode masks in real time (<50 ms) conditioned on flexible spatial prompts.","Architectural Delta: Decoupled ViT-H encoder + positional prompt encoder + 2-layer two-way Transformer decoder + SA-1B 1.1-billion-mask data engine.","Mathematical Formalism: Prompt-Conditioned Two-Way Attention & Dynamic Hypernetwork Mask Generation."],"med_apps":["框/点交互可降低逐像素勾画成本，但自然图像预训练在低对比、细长结构和三维连续性上并非天然可靠。","临床系统应记录提示类型、交互轮数和失败区域；单一 Dice 不能反映人机交互成本。"],"med_apps_en":["Clinical Translation: Transformed interactive medical image annotation, semi-automated contour refinement, and specialist adapter development.","Evidence & Safety Boundary: Annotation infrastructure; zero-shot SAM struggles on low-contrast boundaries, thin branching vessels, and unprompted 3D volumes."],"attrs":{"上一代瓶颈":"传统分割绑定固定数据集和标签集，每换目标需重新训练","核心想法":"可复用 ViT image encoder 加点、框、mask prompt encoder 与轻量 mask decoder","关键改进":"promptable mask proposal、候选 mask/IoU 预测与 SA-1B 数据引擎","医学适配":"成为医学交互标注和专科适配的重要底座","适用范围与证据":"标注基础设施；原版对低对比、小结构、血管和 3D 不可靠"},"attrs_en":{"上一代瓶颈":"Traditional segmentation networks were locked to fixed training classes and could not interactively segment arbitrary user-specified targets.","核心想法":"Amortize heavy image feature extraction once per image, then decode masks in real time (<50 ms) conditioned on flexible spatial prompts.","关键改进":"Decoupled ViT-H encoder + positional prompt encoder + 2-layer two-way Transformer decoder + SA-1B 1.1-billion-mask data engine.","医学适配":"Transformed interactive medical image annotation, semi-automated contour refinement, and specialist adapter development.","适用范围与证据":"Annotation infrastructure; zero-shot SAM struggles on low-contrast boundaries, thin branching vessels, and unprompted 3D volumes."},"paper_title":"Segment Anything","paper_url":"https://openaccess.thecvf.com/content/ICCV2023/html/Kirillov_Segment_Anything_ICCV_2023_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/facebookresearch/segment-anything","has_code":true,"image":"assets/0f08205f87f93c5073f3.avif"},{"id":"architecture_model_033_medsam","num":33,"num_str":"033","year":2024,"year_str":"2024","venue":"Nature Communications","venue_group":"nature","era_group":"era4","title":"MedSAM","family_id":"models_promptable_segmentation","family_code":"06","family_short":"可提示交互式分割","family_en":"Promptable Segmentation","family_icon":"VI","family_label":"可提示分割：把固定类别头改造成交互式纠错接口","archetype":"box_prompted_medical_sam_adaptation","archetype_en":"box_prompted_medical_sam_adaptation","accent":"#145E75","fig_badge":"Figure 2(b) · PDF p.3","fig_href":"https://www.nature.com/articles/s41467-024-44824-z","core_mech":"在 SAM 提示式架构上以大规模多模态医学分割监督做领域适配，并将 box prompt 作为稳定的目标定位接口。","core_mech_en":"Adapts the promptable SAM architecture across 1.57 million medical image–mask pairs spanning 10 imaging modalities using bounding-box prompts.","input_desc":"标准化二维医学图像与目标边界框","input_en":"Normalized 2D medical image slice + target anatomical/lesion bounding box prompt","output_desc":"边界框条件下的医学目标分割 mask","output_en":"Box-conditioned binary segmentation mask for the target medical structure","form_title":"核心公式 · 以框提示和医学 mask 联合适配 SAM","form_title_en":"Core Formalism · Domain-Adapted Medical Box-Prompted Mask Decoding (Dice + Cross-Entropy)","nodes":[{"name":"医学图像","desc":"CT、MR、X-ray、超声、内镜和病理等二维图像统一强度与尺寸接口。","name_en":"Stage 01","desc_en":"Ingests normalized 2d medical image slice + target anatomical/lesion bounding box prompt and prepares initial tensor representations (Stage 01)."},{"name":"领域适配 Image Encoder","desc":"以 SAM ViT 为初始化，从大规模医学图像-mask 对学习医学视觉特征。","name_en":"Image Encoder","desc_en":"Executes Image Encoder to extract primary structural features and establish spatial/sequence encoding."},{"name":"Box Prompt","desc":"真值 mask 外接框在训练时可加入扰动，模拟用户或检测器提供的近似框。","name_en":"Box Prompt","desc_en":"Performs Box Prompt within the core box prompted medical sam adaptation computation pathway."},{"name":"SAM Prompt Encoder","desc":"框的两个角点经位置编码和类型 embedding 形成 sparse prompt tokens。","name_en":"SAM Prompt Encoder","desc_en":"Performs SAM Prompt Encoder within the core box prompted medical sam adaptation computation pathway."},{"name":"Mask Decoder","desc":"SAM two-way Transformer 融合医学 image embedding 与 box tokens。","name_en":"Mask Decoder","desc_en":"Performs Mask Decoder within the core box prompted medical sam adaptation computation pathway."},{"name":"动态 Mask Head","desc":"mask token 生成动态权重，并与上采样图像特征组合成 logits。","name_en":"dynamic Mask Head","desc_en":"Performs dynamic Mask Head within the core box prompted medical sam adaptation computation pathway."},{"name":"医学 Mask 监督","desc":"跨模态、跨器官的像素级标注驱动领域适配，不改变提示式接口。","name_en":"Mask","desc_en":"Applies Mask to project aggregated representations toward the target task head."},{"name":"目标 Mask","desc":"输出框内外一致的单目标分割，可由人工框或检测器框触发。","name_en":"objective Mask","desc_en":"Produces box-conditioned binary segmentation mask for the target medical structure via objective Mask."}],"design_principles":["保留 SAM 的图像–提示–mask 三段式接口，但用医学图像-mask 对纠正自然图像域偏移。","以 box 作为主要提示把任务限定在候选解剖/病灶区域，减少开放式分割歧义。","训练时扰动框使模型容忍人工或上游检测器边界不精确，而不是只适配真值紧框。"],"design_principles_en":["Core Hypothesis: Fine-tune SAM's image encoder and mask decoder on a massive multi-modality medical corpus using bounding boxes as a reliable spatial prompt.","Architectural Delta: Curated 1.57M medical image–mask dataset across 10 modalities + end-to-end domain adaptation with extensive internal/external validation.","Mathematical Formalism: Domain-Adapted Medical Box-Prompted Mask Decoding (Dice + Cross-Entropy)."],"med_apps":["框提示适合临床交互或检测后精分，但性能上限与失败模式同时依赖框质量。","二维切片泛化不能自动保证三维连续性；体积测量前需加跨切片一致性和目标级质控。"],"med_apps_en":["Clinical Translation: Standard interactive box-prompted segmentation tool for radiology, oncology, endoscopy, and pathology annotation.","Evidence & Safety Boundary: Strong domain-adaptation evidence; remains reliant on manual or detector-generated bounding boxes per slice/ROI."],"attrs":{"上一代瓶颈":"原 SAM 跨到医学低对比、多模态图像时 zero-shot 波动大","核心想法":"在 157 万医学 image-mask pairs 上领域微调 SAM","关键改进":"覆盖 10 种模态的大规模 box-prompt 训练和内外部任务评估","医学适配":"用于跨模态交互式医学分割与标注加速","适用范围与证据":"强领域适配证据；仍依赖 box prompt，非全自动 3D 终点"},"attrs_en":{"上一代瓶颈":"Out-of-the-box natural-image SAM exhibited high variance and boundary leakage on low-contrast, multi-modality medical scans.","核心想法":"Fine-tune SAM's image encoder and mask decoder on a massive multi-modality medical corpus using bounding boxes as a reliable spatial prompt.","关键改进":"Curated 1.57M medical image–mask dataset across 10 modalities + end-to-end domain adaptation with extensive internal/external validation.","医学适配":"Standard interactive box-prompted segmentation tool for radiology, oncology, endoscopy, and pathology annotation.","适用范围与证据":"Strong domain-adaptation evidence; remains reliant on manual or detector-generated bounding boxes per slice/ROI."},"paper_title":"Segment Anything in Medical Images","paper_url":"https://doi.org/10.1038/s41467-024-44824-z","code_label":"作者/机构官方实现","code_url":"https://github.com/bowang-lab/MedSAM","has_code":true,"image":"assets/2e72090cb6c489c7ba32.avif"},{"id":"architecture_model_034_sam_2","num":34,"num_str":"034","year":2025,"year_str":"2025","venue":"ICLR","venue_group":"ml","era_group":"era4","title":"SAM 2","family_id":"models_promptable_segmentation","family_code":"06","family_short":"可提示交互式分割","family_en":"Promptable Segmentation","family_icon":"VI","family_label":"可提示分割：把固定类别头改造成交互式纠错接口","archetype":"streaming_promptable_segmentation_memory","archetype_en":"streaming_promptable_segmentation_memory","accent":"#145E75","fig_badge":"Figure 3 · PDF p.5","fig_href":"https://arxiv.org/abs/2408.00714","core_mech":"在 SAM 提示式 decoder 外加入 memory attention、mask-conditioned memory encoder 和 object pointer，构成可交互的流式时序闭环。","core_mech_en":"Extends promptable SAM with a streaming memory bank, memory cross-attention, mask-conditioned memory encoder, and occlusion score head across sequences.","input_desc":"图像或视频帧、当前帧提示及历史对象记忆","input_en":"Video stream or 3D slice stack + spatial prompts (points/box/mask) on one or more reference frames","output_desc":"当前帧对象 mask，并更新供后续帧读取的记忆","output_en":"Temporally/slice-propagated segmentation masks with updated object memory state","form_title":"核心公式 · SAM 2 读取历史记忆并把当前 mask 写回","form_title_en":"Core Formalism · Streaming Memory Attention Conditioning Current Frame/Slice on Past Prompted Masks","nodes":[{"name":"当前帧","desc":"同一接口既处理单张图像，也处理视频流中的一帧。","name_en":"Stage 01","desc_en":"Ingests video stream or 3d slice stack + spatial prompts (points/box/mask) on one or more reference frames and prepares initial tensor representations (Stage 01)."},{"name":"Hiera Image Encoder","desc":"层次化视觉 backbone 输出多尺度当前帧特征。","name_en":"Hiera Image Encoder","desc_en":"Executes Hiera Image Encoder to extract primary structural features and establish spatial/sequence encoding."},{"name":"Prompt Encoder","desc":"点、框或 mask 提示编码为当前对象的条件 tokens。","name_en":"Prompt Encoder","desc_en":"Performs Prompt Encoder within the core streaming promptable segmentation memory computation pathway."},{"name":"Memory Bank","desc":"保存近期提示帧/预测帧的空间记忆与对象指针，并控制容量。","name_en":"Memory Bank","desc_en":"Performs Memory Bank within the core streaming promptable segmentation memory computation pathway."},{"name":"Memory Attention","desc":"当前帧 tokens 通过 self-attention 与 cross-attention 检索历史对象证据。","name_en":"Memory Attention","desc_en":"Performs Memory Attention within the core streaming promptable segmentation memory computation pathway."},{"name":"SAM Mask Decoder","desc":"融合当前提示、带记忆的图像特征与对象指针，预测候选 mask。","name_en":"SAM Mask Decoder","desc_en":"Performs SAM Mask Decoder within the core streaming promptable segmentation memory computation pathway."},{"name":"Object Pointer","desc":"从 mask token 提取紧凑对象身份向量，帮助跨帧区分对象。","name_en":"Object Pointer","desc_en":"Performs Object Pointer within the core streaming promptable segmentation memory computation pathway."},{"name":"当前帧 Mask","desc":"输出对象 mask、质量/存在性信息，可接受下一轮纠正提示。","name_en":"Mask","desc_en":"Performs Mask within the core streaming promptable segmentation memory computation pathway."},{"name":"Memory Encoder","desc":"将预测 mask 与当前图像特征融合、压缩为空间记忆表示。","name_en":"Memory Encoder","desc_en":"Applies Memory Encoder to project aggregated representations toward the target task head."},{"name":"流式记忆更新","desc":"新空间记忆和 object pointer 写入 bank，供后续帧读取。","name_en":"update","desc_en":"Produces temporally/slice-propagated segmentation masks with updated object memory state via update."}],"design_principles":["把视频分割建模为带外部记忆的流式推理：当前帧只读取有限历史状态，不重复处理整段视频。","空间 memory 保存对象外观与位置，object pointer 保存紧凑身份，两者共同降低遮挡后的身份漂移。","预测 mask 经 memory encoder 写回状态，形成 mask→memory→未来帧 attention 的显式闭环。"],"design_principles_en":["Core Hypothesis: Condition current-frame image features on a FIFO memory bank of past prompted frames and predicted object pointers via memory attention.","Architectural Delta: Streaming memory attention + mask-conditioned memory encoder + occlusion prediction head + SA-V video data engine.","Mathematical Formalism: Streaming Memory Attention Conditioning Current Frame/Slice on Past Prompted Masks."],"med_apps":["可用于内镜、超声视频或切片序列的交互传播，但误分割也会写入记忆并累积漂移。","三维 CT/MR 切片不是自然视频；各向异性层厚和突变解剖要求按体数据重新验证传播顺序。"],"med_apps_en":["Clinical Translation: Enables rapid interactive propagation of prompts across surgical endoscopy videos, echocardiography, and 3D CT/MRI slice stacks.","Evidence & Safety Boundary: High utility for interactive 3D/video annotation; sequential slice tracking does not replace native 3D volumetric topology priors."],"attrs":{"上一代瓶颈":"SAM 缺少跨帧时间一致性和纠错记忆","核心想法":"用 streaming memory 在图像和视频中传播 prompt 与对象状态","关键改进":"memory bank、任意帧交互纠正与大规模 SA-V 数据引擎","医学适配":"适合内镜、超声视频和 CT/MRI 切片提示传播","适用范围与证据":"交互工具潜力高；相邻切片不等于真实 3D 几何"},"attrs_en":{"上一代瓶颈":"Static 2D SAM required re-prompting every frame or slice independently, lacking temporal or inter-slice memory propagation.","核心想法":"Condition current-frame image features on a FIFO memory bank of past prompted frames and predicted object pointers via memory attention.","关键改进":"Streaming memory attention + mask-conditioned memory encoder + occlusion prediction head + SA-V video data engine.","医学适配":"Enables rapid interactive propagation of prompts across surgical endoscopy videos, echocardiography, and 3D CT/MRI slice stacks.","适用范围与证据":"High utility for interactive 3D/video annotation; sequential slice tracking does not replace native 3D volumetric topology priors."},"paper_title":"SAM 2: Segment Anything in Images and Videos","paper_url":"https://proceedings.iclr.cc/paper_files/paper/2025/file/45c1f6a8cbf2da59ebf2c802b4f742cd-Paper-Conference.pdf","code_label":"作者/机构官方实现","code_url":"https://github.com/facebookresearch/sam2","has_code":true,"image":"assets/4412061ad8f185d841d3.avif"},{"id":"architecture_model_035_convirt","num":35,"num_str":"035","year":2022,"year_str":"2022 (preprint 2020)","venue":"MLHC","venue_group":"journal","era_group":"era3","title":"ConVIRT","family_id":"models_vision_language","family_code":"07","family_short":"图文对齐与医学 VLM","family_en":"Vision-Language Models","family_icon":"VII","family_label":"图文对齐与生成式 VLM：开放语义不等于视觉事实","archetype":"medical_image_report_dual_encoder_contrastive","archetype_en":"medical_image_report_dual_encoder_contrastive","accent":"#7A3547","fig_badge":"Figure 2 · PDF p.6","fig_href":"https://proceedings.mlr.press/v182/zhang22a.html","core_mech":"将自然生成的医学图像–报告对输入全局双塔，通过双向跨模态对比预训练医学视觉 encoder。","core_mech_en":"Pretrains medical visual encoders directly from naturally occurring paired radiology images and free-text reports via bidirectional contrastive loss.","input_desc":"医学图像与配套自由文本报告","input_en":"Paired medical image (e.g., chest X-ray) and corresponding clinical radiology report sentence","output_desc":"对齐的图像与报告全局表征","output_en":"Contrastively aligned visual encoder representation for downstream low-label classification","form_title":"核心公式 · 医学图像与报告的双向对比对齐","form_title_en":"Core Formalism · Bidirectional Medical Image-to-Report & Report-to-Image Contrastive Objective","nodes":[{"name":"医学图像","desc":"放射影像经随机视觉增强送入图像分支。","name_en":"Stage 01","desc_en":"Ingests paired medical image (e.g., chest x-ray) and corresponding clinical radiology report sentence and prepares initial tensor representations (Stage 01)."},{"name":"Image Encoder","desc":"卷积主干与全局池化提取整幅影像表示。","name_en":"Image Encoder","desc_en":"Executes Image Encoder to extract primary structural features and establish spatial/sequence encoding."},{"name":"图像投影","desc":"MLP/线性头将影像特征投影并归一化到共享空间。","name_en":"projection","desc_en":"Performs projection within the core medical image report dual encoder contrastive computation pathway."},{"name":"放射报告","desc":"与图像同期生成的自然语言报告提供无人工标签监督。","name_en":"Radiology Report","desc_en":"Performs Radiology Report within the core medical image report dual encoder contrastive computation pathway."},{"name":"Text Encoder","desc":"BERT 类编码器将 token 序列聚合为报告级语义向量。","name_en":"Text Encoder","desc_en":"Performs Text Encoder within the core medical image report dual encoder contrastive computation pathway."},{"name":"文本投影","desc":"报告表示投影并归一化到与图像相同维度。","name_en":"projection","desc_en":"Performs projection within the core medical image report dual encoder contrastive computation pathway."},{"name":"跨模态相似矩阵","desc":"mini-batch 内所有图像与报告两两计算相似度。","name_en":"cross-modal matrix","desc_en":"Performs cross-modal matrix within the core medical image report dual encoder contrastive computation pathway."},{"name":"双向对比损失","desc":"图像检索报告和报告检索图像两个方向共同优化。","name_en":"loss","desc_en":"Applies loss to project aggregated representations toward the target task head."},{"name":"下游影像特征","desc":"丢弃训练投影头后，图像 encoder 可微调到分类等医学任务。","name_en":"feature","desc_en":"Produces contrastively aligned visual encoder representation for downstream low-label classification via feature."}],"design_principles":["利用影像–报告的天然配对，把临床工作流文本变成大规模弱监督而无需逐图人工标签。","双向批内对比要求匹配图文靠近、非匹配样本分离，从而学习报告语义可辨的视觉空间。","训练投影空间与下游表征分离，使对比几何约束不必完全承担临床任务接口。"],"design_principles_en":["Core Hypothesis: Use naturally co-occurring clinical radiology reports as free-form weak supervision via bidirectional image–text contrastive learning.","Architectural Delta: Domain-specific image and clinical text dual towers trained with symmetric InfoNCE, achieving strong label efficiency with 1%–10% labels.","Mathematical Formalism: Bidirectional Medical Image-to-Report & Report-to-Image Contrastive Objective."],"med_apps":["报告常省略正常所见、包含比较历史或否定语句，图文配对不是像素级真值。","患者级划分和同检查多图处理是必要 QA，否则相近图像/报告会造成数据泄漏或假负样本。"],"med_apps_en":["Clinical Translation: Pioneered the medical CLIP paradigm before or alongside general-domain CLIP, establishing report-supervised radiology pretraining.","Evidence & Safety Boundary: Landmark medical VLM foundation; global pooling captures study-level semantics but remains coarse for tiny focal lesions."],"attrs":{"上一代瓶颈":"ImageNet 或纯图像 SSL 对医学高类间相似度与临床语义帮助有限","核心想法":"对配对医学影像与报告做双向全局对比学习","关键改进":"用自然语言报告作为弱监督，并展示少标签迁移","医学适配":"奠定医学 CLIP 式胸片表示学习","适用范围与证据":"医学图文对齐 landmark；局部定位能力有限"},"attrs_en":{"上一代瓶颈":"ImageNet pretraining struggled with subtle gray-scale radiographic findings, while rule-based report labelers (CheXpert) lost clinical nuance.","核心想法":"Use naturally co-occurring clinical radiology reports as free-form weak supervision via bidirectional image–text contrastive learning.","关键改进":"Domain-specific image and clinical text dual towers trained with symmetric InfoNCE, achieving strong label efficiency with 1%–10% labels.","医学适配":"Pioneered the medical CLIP paradigm before or alongside general-domain CLIP, establishing report-supervised radiology pretraining.","适用范围与证据":"Landmark medical VLM foundation; global pooling captures study-level semantics but remains coarse for tiny focal lesions."},"paper_title":"Contrastive Learning of Medical Visual Representations from Paired Images and Text","paper_url":"https://proceedings.mlr.press/v182/zhang22a.html","code_label":"未提供官方实现","code_url":"","has_code":false,"image":"assets/9ff64cdd9108214ecc83.avif"},{"id":"architecture_model_036_gloria","num":36,"num_str":"036","year":2021,"year_str":"2021","venue":"ICCV","venue_group":"cv","era_group":"era3","title":"GLoRIA","family_id":"models_vision_language","family_code":"07","family_short":"图文对齐与医学 VLM","family_en":"Vision-Language Models","family_icon":"VII","family_label":"图文对齐与生成式 VLM：开放语义不等于视觉事实","archetype":"global_local_image_report_alignment","archetype_en":"global_local_image_report_alignment","accent":"#7A3547","fig_badge":"Figure 2 · PDF p.4","fig_href":"https://openaccess.thecvf.com/content/ICCV2021/html/Huang_GLoRIA_A_Multimodal_Global-Local_Representation_Learning_Framework_for_Label-Efficient_Medical_ICCV_2021_paper.html","core_mech":"在全局图文对比之外，以词为 query 对 CNN region grid 做软 attention 并训练局部区域–词对齐。","core_mech_en":"Combines global image–report contrastive alignment with word-queried soft attention over local CNN image grid regions for fine-grained phrase grounding.","input_desc":"医学图像与对应放射报告","input_en":"Medical image (chest X-ray) + paired free-text radiology report","output_desc":"全局图文对齐表征与局部区域–词语对齐特征","output_en":"Globally aligned image/text embeddings + word-grounded local spatial attention maps","form_title":"核心公式 · GLoRIA 由词语注意力汇聚对应影像区域","form_title_en":"Core Formalism · Word-Attended Local Region Context Aggregation & Local–Global Contrastive Loss","nodes":[{"name":"胸片图像","desc":"整幅 X-ray 输入视觉主干。","name_en":"Chest Radiograph","desc_en":"Ingests medical image (chest x-ray) + paired free-text radiology report and prepares initial tensor representations (Chest Radiograph)."},{"name":"局部 Region Grid","desc":"CNN 保留 H×W 空间特征，每个位置代表一个影像区域。","name_en":"local Region Grid","desc_en":"Executes local Region Grid to extract primary structural features and establish spatial/sequence encoding."},{"name":"全局图像向量","desc":"region grid 经聚合得到检查级视觉表示。","name_en":"global vector","desc_en":"Performs global vector within the core global local image report alignment computation pathway."},{"name":"报告 Tokens","desc":"报告分词后送入语言 encoder。","name_en":"Tokens","desc_en":"Performs Tokens within the core global local image report alignment computation pathway."},{"name":"词级特征","desc":"每个报告 token/词保留上下文化表示。","name_en":"feature","desc_en":"Performs feature within the core global local image report alignment computation pathway."},{"name":"全局文本向量","desc":"报告序列聚合成检查级文本表示。","name_en":"global vector","desc_en":"Performs global vector within the core global local image report alignment computation pathway."},{"name":"Global Alignment","desc":"在 batch 内对比配对的全局图像和报告表示。","name_en":"Global Alignment","desc_en":"Performs Global Alignment within the core global local image report alignment computation pathway."},{"name":"词→区域 Attention","desc":"每个词按相似度从所有视觉 regions 聚合其对应图像上下文。","name_en":"→ Attention","desc_en":"Performs → Attention within the core global local image report alignment computation pathway."},{"name":"Local Alignment","desc":"对齐词特征与其 attention 加权的局部视觉上下文。","name_en":"Local Alignment","desc_en":"Applies Local Alignment to project aggregated representations toward the target task head."},{"name":"全局 + 局部表征","desc":"联合目标后的特征支持少标签分类、检索和定位。","name_en":"global + local representation","desc_en":"Produces globally aligned image/text embeddings + word-grounded local spatial attention maps via global + local representation."}],"design_principles":["全局对比保证一份报告与整幅影像语义匹配，局部对齐进一步把词语落到影像区域。","词到区域 attention 是软对应，不需要边界框即可从报告学习潜在定位。","局部和全局目标互补：前者保留细粒度病灶线索，后者稳定检查级语义。"],"design_principles_en":["Core Hypothesis: Align individual report words with attention-weighted combinations of local convolutional sub-regions alongside global study alignment.","Architectural Delta: Joint global contrastive loss + word-to-region attention-weighted local contrastive objective without requiring bounding-box annotations.","Mathematical Formalism: Word-Attended Local Region Context Aggregation & Local–Global Contrastive Loss."],"med_apps":["可利用报告中的病灶词实现弱监督定位，但 attention 热图不是经过校准的病灶边界。","否定、正常描述和非视觉性临床信息需在文本处理或评估中单独审计。"],"med_apps_en":["Clinical Translation: Enables zero-shot phrase grounding, text-to-image retrieval, and label-efficient chest X-ray segmentation/classification.","Evidence & Safety Boundary: Established local grounding in medical VLMs; soft attention heatmaps remain coarse and do not guarantee causal localization."],"attrs":{"上一代瓶颈":"global 图文 embedding 难定位细粒度征象","核心想法":"同时对齐整图-报告和局部影像区域-报告词语","关键改进":"基于 attention 的 global-local contrastive objectives","医学适配":"支持胸片检索、少标注分类/分割和 phrase grounding","适用范围与证据":"开启医学 local grounding 主线；attention map 不等于因果解释"},"attrs_en":{"上一代瓶颈":"Global image–report embeddings collapse spatial coordinates, failing to localize focal findings like small pneumothoraces or nodules.","核心想法":"Align individual report words with attention-weighted combinations of local convolutional sub-regions alongside global study alignment.","关键改进":"Joint global contrastive loss + word-to-region attention-weighted local contrastive objective without requiring bounding-box annotations.","医学适配":"Enables zero-shot phrase grounding, text-to-image retrieval, and label-efficient chest X-ray segmentation/classification.","适用范围与证据":"Established local grounding in medical VLMs; soft attention heatmaps remain coarse and do not guarantee causal localization."},"paper_title":"GLoRIA: A Multimodal Global-Local Representation Learning Framework for Label-efficient Medical Image Recognition","paper_url":"https://openaccess.thecvf.com/content/ICCV2021/html/Huang_GLoRIA_A_Multimodal_Global-Local_Representation_Learning_Framework_for_Label-Efficient_Medical_ICCV_2021_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/marshuang80/gloria","has_code":true,"image":"assets/5317d0a07401e62426fb.avif"},{"id":"architecture_model_037_biovil","num":37,"num_str":"037","year":2022,"year_str":"2022","venue":"ECCV","venue_group":"cv","era_group":"era3","title":"BioViL","family_id":"models_vision_language","family_code":"07","family_short":"图文对齐与医学 VLM","family_en":"Vision-Language Models","family_icon":"VII","family_label":"图文对齐与生成式 VLM：开放语义不等于视觉事实","archetype":"radiology_specialized_global_local_vision_language","archetype_en":"radiology_specialized_global_local_vision_language","accent":"#7A3547","fig_badge":"Figure 1 · PDF p.3","fig_href":"https://www.ecva.net/papers/eccv_2022/papers_ECCV/html/1557_ECCV_2022_paper.php","core_mech":"以放射报告专用 CXR-BERT 提升文本语义，再联合学习检查级图文对比与短语–视觉 patch grounding。","core_mech_en":"Pairs a radiology-specialized text encoder (CXR-BERT with RSM masked pretraining) with joint global and local patch–phrase contrastive alignment.","input_desc":"胸部 X-ray 与对应放射报告/短语","input_en":"Chest radiograph + radiology report findings/impression text","output_desc":"具备报告语义与局部 grounding 能力的胸片表征","output_en":"Negation- and clinical-syntax-aware visual-linguistic embeddings and local phrase grounding maps","form_title":"核心公式 · BioViL 用放射短语查询局部视觉 patch","form_title_en":"Core Formalism · Radiology-Specific CXR-BERT Semantic Encoding + Local Patch–Phrase Alignment","nodes":[{"name":"胸部 X-ray","desc":"单幅胸片进入保留空间特征的视觉 encoder。","name_en":"Chest X-Ray","desc_en":"Ingests chest radiograph + radiology report findings/impression text and prepares initial tensor representations (Chest X-Ray)."},{"name":"CXR Image Encoder","desc":"卷积主干同时产生全局检查向量和局部 patch/region 表征。","name_en":"CXR Image Encoder","desc_en":"Executes CXR Image Encoder to extract primary structural features and establish spatial/sequence encoding."},{"name":"视觉投影","desc":"全局与局部视觉特征映射到共享图文维度。","name_en":"Visual Projection","desc_en":"Performs Visual Projection within the core radiology specialized global local vision language computation pathway."},{"name":"报告 / 短语","desc":"放射报告既提供完整句义，也提供可定位的短语查询。","name_en":"Stage 04","desc_en":"Performs Stage 04 within the core radiology specialized global local vision language computation pathway."},{"name":"CXR-BERT","desc":"先在放射报告上领域预训练的语言 encoder 表达否定与专业术语。","name_en":"CXR-BERT","desc_en":"Performs CXR-BERT within the core radiology specialized global local vision language computation pathway."},{"name":"文本投影","desc":"句级和 token/短语级语言特征映射到共享空间。","name_en":"projection","desc_en":"Performs projection within the core radiology specialized global local vision language computation pathway."},{"name":"全局图文对比","desc":"检查级图像与对应报告在 batch 内双向对齐。","name_en":"Global Image–Text Alignment","desc_en":"Performs Global Image–Text Alignment within the core radiology specialized global local vision language computation pathway."},{"name":"短语–Patch 对齐","desc":"短语向量与视觉网格计算相似图，强化局部语义。","name_en":"–Patch","desc_en":"Applies –Patch to project aggregated representations toward the target task head."},{"name":"BioViL 表征","desc":"支持零/少样本分类、图文检索和短语 grounding。","name_en":"BioViL representation","desc_en":"Produces negation- and clinical-syntax-aware visual-linguistic embeddings and local phrase grounding maps via BioViL representation."}],"design_principles":["先训练放射学专用语言模型，减少通用 BERT 对专业缩写、否定和报告句式的语义误读。","图像 encoder 保留空间网格，使报告短语不仅与整图对齐，也能在 patch 级计算 grounding。","全局配对约束诊断语义，局部相似约束解剖位置，形成可迁移且可查询的共享空间。"],"design_principles_en":["Core Hypothesis: Pretrain a dedicated radiology language model (CXR-BERT) with radiology section matching, then align it globally and locally with chest X-rays.","Architectural Delta: Domain-tailored text modeling + symmetric global/local contrastive projection + MS-CXR phrase grounding benchmark.","Mathematical Formalism: Radiology-Specific CXR-BERT Semantic Encoding + Local Patch–Phrase Alignment."],"med_apps":["短语 grounding 可作为检索和可解释界面，但相似图仍不是像素级标注替代品。","模型专为胸片与英文报告训练；迁移到 CT、其他语言或不同报告规范需重新对齐。"],"med_apps_en":["Clinical Translation: Strong specialist baseline for chest X-ray zero-shot classification, phrase grounding, and semantic report evaluation.","Evidence & Safety Boundary: Proved that clinical text modeling is as critical as visual architecture; scope is primarily specialized to chest radiography."],"attrs":{"上一代瓶颈":"通用文本 encoder 不理解放射学否定、关系和叙述结构","核心想法":"以放射学专科语言模型增强全局图文对齐和局部 grounding","关键改进":"强化文本侧临床语义，并联合 image-text contrastive learning","医学适配":"在胸片 phrase grounding、分类、分割和检索上形成强专科模型","适用范围与证据":"证明文本建模不是附属模块；模态范围仍以 CXR 为主"},"attrs_en":{"上一代瓶颈":"Generic BERT text encoders mishandled radiological negations ('no pleural effusion'), temporal comparisons, and clinical syntax.","核心想法":"Pretrain a dedicated radiology language model (CXR-BERT) with radiology section matching, then align it globally and locally with chest X-rays.","关键改进":"Domain-tailored text modeling + symmetric global/local contrastive projection + MS-CXR phrase grounding benchmark.","医学适配":"Strong specialist baseline for chest X-ray zero-shot classification, phrase grounding, and semantic report evaluation.","适用范围与证据":"Proved that clinical text modeling is as critical as visual architecture; scope is primarily specialized to chest radiography."},"paper_title":"Making the Most of Text Semantics to Improve Biomedical Vision-Language Processing","paper_url":"https://www.ecva.net/papers/eccv_2022/papers_ECCV/papers/136960001.pdf","code_label":"未提供官方实现","code_url":"","has_code":false,"image":"assets/6b3ce9de00b0c0e6b3b1.avif"},{"id":"architecture_model_038_biomedclip","num":38,"num_str":"038","year":2025,"year_str":"2025 (preprint 2023)","venue":"NEJM AI","venue_group":"journal","era_group":"era4","title":"BiomedCLIP","family_id":"models_vision_language","family_code":"07","family_short":"图文对齐与医学 VLM","family_en":"Vision-Language Models","family_icon":"VII","family_label":"图文对齐与生成式 VLM：开放语义不等于视觉事实","archetype":"biomedical_figure_caption_dual_tower","archetype_en":"biomedical_figure_caption_dual_tower","accent":"#7A3547","fig_badge":"Figure 1(c) and 1(d) · PDF p.15","fig_href":"https://arxiv.org/abs/2303.00915","core_mech":"以 PMC-15M 广域生物医学 figure–caption 语料、ViT 视觉塔和 PubMedBERT 文本塔训练领域 CLIP。","core_mech_en":"Domain-specific CLIP trained on PMC-15M (15 million biomedical figure–caption pairs from PubMed Central) using a ViT vision tower and PubMedBERT text tower.","input_desc":"生物医学图像/论文图与对应 caption","input_en":"Biomedical image (radiology, pathology, microscopy, chart) + scientific figure caption","output_desc":"开放词汇生物医学图文共享嵌入","output_en":"Open-vocabulary biomedical multimodal embeddings for retrieval, zero-shot classification, and VQA","form_title":"核心公式 · BiomedCLIP 以领域文本 prompt 构造零样本分类器","form_title_en":"Core Formalism · Broad-Coverage Biomedical Figure–Caption Contrastive Alignment","nodes":[{"name":"生物医学图像","desc":"来自论文的显微、放射、病理、图表等多样视觉内容。","name_en":"Stage 01","desc_en":"Ingests biomedical image (radiology, pathology, microscopy, chart) + scientific figure caption and prepares initial tensor representations (Stage 01)."},{"name":"ViT Image Tower","desc":"视觉 Transformer 将图像 patch 汇聚为全局向量。","name_en":"ViT Image Tower","desc_en":"Executes ViT Image Tower to extract primary structural features and establish spatial/sequence encoding."},{"name":"图像投影","desc":"视觉向量投影并归一化到共享嵌入空间。","name_en":"projection","desc_en":"Performs projection within the core biomedical figure caption dual tower computation pathway."},{"name":"论文 Caption","desc":"与 figure 配对的生物医学描述包含实体、模态和实验语境。","name_en":"Caption","desc_en":"Performs Caption within the core biomedical figure caption dual tower computation pathway."},{"name":"PubMedBERT Tower","desc":"领域语言 encoder 处理生物医学术语和论文句法。","name_en":"PubMedBERT Tower","desc_en":"Performs PubMedBERT Tower within the core biomedical figure caption dual tower computation pathway."},{"name":"文本投影","desc":"caption 向量投影并归一化到视觉同一空间。","name_en":"projection","desc_en":"Performs projection within the core biomedical figure caption dual tower computation pathway."},{"name":"对称 CLIP Loss","desc":"在 PMC-15M batch 内进行图像↔caption 双向对比。","name_en":"symmetric CLIP Loss","desc_en":"Applies symmetric CLIP Loss to project aggregated representations toward the target task head."},{"name":"开放词汇嵌入","desc":"以文本 prompt 做零样本分类，或用于检索和下游适配。","name_en":"Open-Vocabulary Embedding","desc_en":"Produces open-vocabulary biomedical multimodal embeddings for retrieval, zero-shot classification, and vqa via Open-Vocabulary Embedding."}],"design_principles":["把 PubMed 论文 figure–caption 天然配对扩展为跨模态预训练数据，而不局限单一临床数据集。","领域语言 encoder 与视觉 encoder 在统一归一化空间中通过对称对比目标共同更新。","文本 prompt 定义任务标签，使同一模型可跨多类生物医学视觉任务复用。"],"design_principles_en":["Core Hypothesis: Harvest 15M diverse biomedical figure–caption pairs from PMC open-access articles and train a ViT + PubMedBERT dual encoder with long context.","Architectural Delta: Large-scale multi-specialty biomedical corpus (PMC-15M) + domain-specific PubMedBERT text encoder + patch-dropout scaling.","Mathematical Formalism: Broad-Coverage Biomedical Figure–Caption Contrastive Alignment."],"med_apps":["PMC-15M 覆盖广但论文插图包含面板、箭头和合成图表，与原始临床影像分布不同。","零样本结果要按模态、机构和 label wording 分层评估，避免把学术 caption 偏差带入临床判断。"],"med_apps_en":["Clinical Translation: Widely used open-weight backbone for cross-modality biomedical retrieval, zero-shot triage, and VQA initialization.","Evidence & Safety Boundary: Broadest open biomedical CLIP model; scientific publication figures differ in resolution and calibration from raw clinical DICOMs."],"attrs":{"上一代瓶颈":"既有医学 CLIP 多局限于胸片单一模态","核心想法":"在 PMC-15M 科学 figure-caption pairs 上训练 ViT 与 PubMedBERT 双编码器","关键改进":"扩大到多类生物医学图像和专科文本的开放预训练","医学适配":"用于跨模态检索、zero-shot 分类和 VQA","适用范围与证据":"开放权重且覆盖广；科学 figure 与真实 DICOM 分布仍不同"},"attrs_en":{"上一代瓶颈":"Prior medical CLIP models were restricted to single modalities (mostly chest X-rays) and lacked broad biomedical taxonomy coverage.","核心想法":"Harvest 15M diverse biomedical figure–caption pairs from PMC open-access articles and train a ViT + PubMedBERT dual encoder with long context.","关键改进":"Large-scale multi-specialty biomedical corpus (PMC-15M) + domain-specific PubMedBERT text encoder + patch-dropout scaling.","医学适配":"Widely used open-weight backbone for cross-modality biomedical retrieval, zero-shot triage, and VQA initialization.","适用范围与证据":"Broadest open biomedical CLIP model; scientific publication figures differ in resolution and calibration from raw clinical DICOMs."},"paper_title":"BiomedCLIP: a multimodal biomedical foundation model pretrained from fifteen million scientific image-text pairs","paper_url":"https://doi.org/10.1056/AIoa2400640","code_label":"作者/机构官方实现","code_url":"https://huggingface.co/microsoft/BiomedCLIP-PubMedBERT_256-vit_base_patch16_224","has_code":true,"image":"assets/5b79108d2a71fc1f0ae2.avif"},{"id":"architecture_model_039_uni","num":39,"num_str":"039","year":2024,"year_str":"2024","venue":"Nature Medicine","venue_group":"nature","era_group":"era4","title":"UNI","family_id":"models_pathology_foundations","family_code":"08","family_short":"计算病理基础模型","family_en":"Pathology Foundations","family_icon":"VIII","family_label":"病理基础模型：从 patch encoder 到 whole-slide 多模态推理","archetype":"pathology_tile_dinov2_foundation_encoder","archetype_en":"pathology_tile_dinov2_foundation_encoder","accent":"#7A3547","fig_badge":"Figure 1(b) · PDF p.Official HTML Figure 1 asset","fig_href":"https://www.nature.com/articles/s41591-024-02857-3","core_mech":"在超过一亿病理图块上以 DINOv2 式 teacher–student 训练 ViT-L/16，向多类病理任务提供统一冻结 tile encoder。","core_mech_en":"ViT-L/16 tile encoder pretrained via DINOv2 self-distillation and iBOT masked patch modeling on over 100 million H&E histopathology patches (Mass-100K).","input_desc":"全视野病理切片切出的无标签组织图块","input_en":"256×256 H&E histopathology tissue tiles extracted from whole-slide images (WSIs)","output_desc":"可冻结迁移的病理图块表征及其下游切片级聚合","output_en":"Frozen transferable tile embeddings for ROI tasks or MIL whole-slide aggregation","form_title":"核心公式 · UNI 联合 tile 级自蒸馏与 patch 级遮蔽蒸馏","form_title_en":"Core Formalism · UNI Joint Tile-Level DINO Self-Distillation & Masked Patch iBOT Distillation","nodes":[{"name":"WSI 库","desc":"跨器官、染色和机构的大规模全视野病理切片。","name_en":"WSI","desc_en":"Ingests 256×256 h&e histopathology tissue tiles extracted from whole-slide images (wsis) and prepares initial tensor representations (WSI)."},{"name":"组织 Tile 采样","desc":"组织检测后从 WSI 提取高倍率图块，去除大面积背景。","name_en":"Tile sampling","desc_en":"Executes Tile sampling to extract primary structural features and establish spatial/sequence encoding."},{"name":"Multi-Crop + Mask","desc":"对 tile 生成局部/全局 crops 与遮蔽 patch 视图。","name_en":"Multi-Crop + Mask","desc_en":"Performs Multi-Crop + Mask within the core pathology tile dinov2 foundation encoder computation pathway."},{"name":"ViT-L/16 Student","desc":"大容量视觉 Transformer 输出 tile 的 CLS 与 patch 表征。","name_en":"ViT-L/16 Student","desc_en":"Performs ViT-L/16 Student within the core pathology tile dinov2 foundation encoder computation pathway."},{"name":"EMA Teacher","desc":"同构 teacher 提供平滑的全局和局部自蒸馏目标。","name_en":"EMA Teacher","desc_en":"Performs EMA Teacher within the core pathology tile dinov2 foundation encoder computation pathway."},{"name":"DINO 图像目标","desc":"跨增强视图对齐 tile 级 CLS 语义。","name_en":"DINO objective","desc_en":"Performs DINO objective within the core pathology tile dinov2 foundation encoder computation pathway."},{"name":"iBOT Patch 目标","desc":"在遮蔽位置预测 teacher patch 表示，保留组织局部结构。","name_en":"iBOT Patch objective","desc_en":"Performs iBOT Patch objective within the core pathology tile dinov2 foundation encoder computation pathway."},{"name":"冻结 Tile Embedding","desc":"预训练后每个病理 tile 被编码为通用向量。","name_en":"Tile Embedding","desc_en":"Applies Tile Embedding to project aggregated representations toward the target task head."},{"name":"任务级 Aggregator","desc":"线性探针、kNN、MIL 或其他聚合器把 tile 向量变为 ROI/WSI 预测。","name_en":"Aggregator","desc_en":"Produces frozen transferable tile embeddings for roi tasks or mil whole-slide aggregation via Aggregator."}],"design_principles":["把病理基础模型训练单元设为组织 tile，以超大规模无标签 WSI 转化为可管理的视觉样本。","DINOv2 式图像级自蒸馏与 patch 遮蔽蒸馏同时学习形态语义和局部组织结构。","预训练 encoder 与任务聚合器解耦，同一 tile 表征可用在线性探针、ROI 和 WSI 级任务。"],"design_principles_en":["Core Hypothesis: Scale DINOv2 self-supervised pretraining to >100M non-public diagnostic tissue tiles across 20 major tissue types (100,000+ WSIs).","Architectural Delta: Massive non-TCGA clinical tissue diversity + DINOv2/iBOT recipe evaluated systematically across 34 clinical pathology tasks.","Mathematical Formalism: UNI Joint Tile-Level DINO Self-Distillation & Masked Patch iBOT Distillation."],"med_apps":["强 tile encoder 不自动解决 WSI 级空间推理；聚合方法、取样倍率和 tile 数仍决定病例级性能。","染色、扫描仪和组织来源偏移需独立验证，且患者级/切片级划分必须防止近重复泄漏。"],"med_apps_en":["Clinical Translation: Widely adopted frozen tile feature extractor for cancer subtyping, biomarker prediction, ROI retrieval, and cell segmentation.","Evidence & Safety Boundary: Mature pathology tile foundation model; slide-level diagnosis still requires training an MIL or slide aggregator on top."],"attrs":{"上一代瓶颈":"ImageNet 或小规模 TCGA encoder 跨组织迁移弱","核心想法":"在超过一亿病理 patches 上用 DINOv2 训练 ViT-L 通用 tile encoder","关键改进":"大规模多组织 WSI 数据、自监督预训练与 34 个临床任务评估","医学适配":"原论文及后续比较报告较强的病理 label efficiency 和跨任务迁移","适用范围与证据":"病理 foundation model 的成熟代表；slide 聚合仍常需任务训练"},"attrs_en":{"上一代瓶颈":"ImageNet-pretrained encoders and small TCGA-only models generalized poorly across diverse tissue types and rare cancers.","核心想法":"Scale DINOv2 self-supervised pretraining to >100M non-public diagnostic tissue tiles across 20 major tissue types (100,000+ WSIs).","关键改进":"Massive non-TCGA clinical tissue diversity + DINOv2/iBOT recipe evaluated systematically across 34 clinical pathology tasks.","医学适配":"Widely adopted frozen tile feature extractor for cancer subtyping, biomarker prediction, ROI retrieval, and cell segmentation.","适用范围与证据":"Mature pathology tile foundation model; slide-level diagnosis still requires training an MIL or slide aggregator on top."},"paper_title":"Towards a General-Purpose Foundation Model for Computational Pathology","paper_url":"https://doi.org/10.1038/s41591-024-02857-3","code_label":"作者/机构官方实现","code_url":"https://github.com/mahmoodlab/UNI","has_code":true,"image":"assets/37aedbbc953f7d86624b.avif"},{"id":"architecture_model_040_conch","num":40,"num_str":"040","year":2024,"year_str":"2024","venue":"Nature Medicine","venue_group":"nature","era_group":"era4","title":"CONCH","family_id":"models_pathology_foundations","family_code":"08","family_short":"计算病理基础模型","family_en":"Pathology Foundations","family_icon":"VIII","family_label":"病理基础模型：从 patch encoder 到 whole-slide 多模态推理","archetype":"pathology_contrastive_captioner","archetype_en":"pathology_contrastive_captioner","accent":"#7A3547","fig_badge":"Figure 1(c) · PDF p.Official HTML Figure 1 asset","fig_href":"https://www.nature.com/articles/s41591-024-02856-4","core_mech":"在病理领域把 CLIP 式全局对比与 CoCa 式图像条件 caption decoder 联合训练，同时服务判别与生成。","core_mech_en":"CoCa-style computational pathology vision–language foundation model jointly trained with contrastive image–text alignment and generative caption decoding on 1.17M pairs.","input_desc":"组织病理图像与人工生成的病理文本描述","input_en":"Histopathology image tile/ROI + paired pathology text description or prompt","output_desc":"病理图文共享表征及图像条件文本生成","output_en":"Shared multimodal retrieval/zero-shot embeddings + autoregressive pathology caption/text generation","form_title":"核心公式 · CONCH 联合图文对比与图像条件 captioning","form_title_en":"Core Formalism · Joint Contrastive Image–Text Alignment & Cross-Attended Generative Caption Loss","nodes":[{"name":"病理图像","desc":"组织图像进入视觉 encoder，保留供对比与生成使用的视觉 tokens。","name_en":"Histopathology Image","desc_en":"Ingests histopathology image tile/roi + paired pathology text description or prompt and prepares initial tensor representations (Histopathology Image)."},{"name":"Image Encoder","desc":"ViT 将病理形态编码为全局向量和空间 token 序列。","name_en":"Image Encoder","desc_en":"Executes Image Encoder to extract primary structural features and establish spatial/sequence encoding."},{"name":"病理 Caption","desc":"由人类撰写/筛选的病理描述提供细粒度形态与诊断语义。","name_en":"Caption","desc_en":"Performs Caption within the core pathology contrastive captioner computation pathway."},{"name":"Text Encoder","desc":"语言 Transformer 把 caption 编码为全局文本向量。","name_en":"Text Encoder","desc_en":"Performs Text Encoder within the core pathology contrastive captioner computation pathway."},{"name":"共享嵌入","desc":"图像与文本全局向量投影、归一化后进入共同空间。","name_en":"embedding","desc_en":"Performs embedding within the core pathology contrastive captioner computation pathway."},{"name":"图文对比","desc":"CoCa 式 contrastive loss 对齐配对图像与文本并分离非配对样本。","name_en":"Image–Text Contrastive Loss","desc_en":"Performs Image–Text Contrastive Loss within the core pathology contrastive captioner computation pathway."},{"name":"Multimodal Decoder","desc":"文本解码器以因果 self-attention 和对视觉 tokens 的 cross-attention 生成 caption。","name_en":"Multimodal Decoder","desc_en":"Performs Multimodal Decoder within the core pathology contrastive captioner computation pathway."},{"name":"Captioning Loss","desc":"teacher-forcing 的 next-token loss 要求视觉特征保留可描述的细节。","name_en":"Captioning Loss","desc_en":"Applies Captioning Loss to project aggregated representations toward the target task head."},{"name":"CONCH 表征","desc":"支持零样本分类、图文/图图检索、分割适配与图像描述。","name_en":"CONCH representation","desc_en":"Produces shared multimodal retrieval/zero-shot embeddings + autoregressive pathology caption/text generation via CONCH representation."}],"design_principles":["对比目标学习可检索、可零样本分类的全局图文几何；caption 目标迫使视觉 tokens 保留生成所需细节。","multimodal decoder 通过 cross-attention 在每个生成 token 时读取病理图像，而不只依赖单一全局向量。","人类病理描述比通用网络 alt-text 更贴近领域概念，使开放词汇表征具有专业语义。"],"design_principles_en":["Core Hypothesis: Pretrain a ViT vision encoder, text encoder, and multimodal caption decoder on 1.17M curated human histopathology image–caption pairs.","Architectural Delta: Unifies CLIP-style dual-encoder retrieval/zero-shot transfer with CoCa-style generative captioning in computational pathology.","Mathematical Formalism: Joint Contrastive Image–Text Alignment & Cross-Attended Generative Caption Loss."],"med_apps":["同一 backbone 可连接检索、零样本和生成，但生成内容必须以图像证据和不确定性机制约束。","病理 caption 覆盖和语言风格会限定开放词汇边界；罕见病种不能仅凭通用相似度宣称可靠。"],"med_apps_en":["Clinical Translation: Enables zero-shot cancer subtyping, text-to-tile search, WSI zero-shot MI-Zero classification, and pathology captioning.","Evidence & Safety Boundary: Top-performing multimodal pathology foundation model; performance is bounded by educational/caption terminology coverage."],"attrs":{"上一代瓶颈":"vision-only 病理 encoder 缺少 zero-shot 与跨模态检索接口","核心想法":"以 117 万病理 image-caption pairs 学开放语义视觉语言表示","关键改进":"病理专科图文对齐，统一分类、检索、caption 和分割迁移","医学适配":"支持病理 zero-shot/few-shot 和文本驱动检索","适用范围与证据":"独立 benchmark 表现强；caption 构造和术语覆盖决定上限"},"attrs_en":{"上一代瓶颈":"Vision-only pathology foundation models (UNI, Virchow) lack native text interfaces for zero-shot classification or cross-modal search.","核心想法":"Pretrain a ViT vision encoder, text encoder, and multimodal caption decoder on 1.17M curated human histopathology image–caption pairs.","关键改进":"Unifies CLIP-style dual-encoder retrieval/zero-shot transfer with CoCa-style generative captioning in computational pathology.","医学适配":"Enables zero-shot cancer subtyping, text-to-tile search, WSI zero-shot MI-Zero classification, and pathology captioning.","适用范围与证据":"Top-performing multimodal pathology foundation model; performance is bounded by educational/caption terminology coverage."},"paper_title":"A Visual-Language Foundation Model for Computational Pathology","paper_url":"https://doi.org/10.1038/s41591-024-02856-4","code_label":"作者/机构官方实现","code_url":"https://github.com/mahmoodlab/CONCH","has_code":true,"image":"assets/12486ce6f5f7de5bf583.avif"},{"id":"architecture_model_041_prov_gigapath","num":41,"num_str":"041","year":2024,"year_str":"2024","venue":"Nature","venue_group":"nature","era_group":"era4","title":"Prov-GigaPath","family_id":"models_pathology_foundations","family_code":"08","family_short":"计算病理基础模型","family_en":"Pathology Foundations","family_icon":"VIII","family_label":"病理基础模型：从 patch encoder 到 whole-slide 多模态推理","archetype":"two_level_tile_and_long_context_slide_encoder","archetype_en":"two_level_tile_and_long_context_slide_encoder","accent":"#7A3547","fig_badge":"Figure 1 · PDF p.3","fig_href":"https://www.nature.com/articles/s41586-024-07441-w","core_mech":"DINOv2 病理 tile encoder 与 LongNet 膨胀注意力 slide encoder 两级串联，并以 masked tile reconstruction 预训练全切片上下文。","core_mech_en":"Two-stage gigapixel pathology foundation model pairing a DINOv2 tile encoder with a LongNet dilated-attention whole-slide encoder pretrained via masked tile reconstruction.","input_desc":"全视野病理切片及其组织 tile 坐标序列","input_en":"Whole-slide image (WSI) decomposed into tens of thousands of tissue tiles with 2D spatial (x, y) coordinates","output_desc":"整张 WSI 的长上下文表征与病例级任务预测","output_en":"Contextualized whole-slide representation and patient/case-level diagnostic or genomic predictions","form_title":"核心公式 · Prov-GigaPath 在超长 tile 序列上重建被遮表征","form_title_en":"Core Formalism · Masked Tile Embedding Reconstruction Across Tens of Thousands of WSI Coordinates via LongNet","nodes":[{"name":"全视野切片","desc":"真实临床流程产生的 gigapixel WSI，单图远超普通视觉模型输入范围。","name_en":"Whole-Slide Image (WSI)","desc_en":"Ingests whole-slide image (wsi) decomposed into tens of thousands of tissue tiles with 2d spatial (x, y) coordinates and prepares initial tensor representations (Whole-Slide Image (WSI))."},{"name":"组织 Tiling","desc":"检测组织区并提取大量定尺度 tile，同时保留其二维坐标。","name_en":"Tiling","desc_en":"Executes Tiling to extract primary structural features and establish spatial/sequence encoding."},{"name":"DINOv2 Tile Encoder","desc":"第一阶段在约 13 亿病理 tiles 上自监督训练 ViT，逐 tile 输出形态向量。","name_en":"DINOv2 Tile Encoder","desc_en":"Performs DINOv2 Tile Encoder within the core two level tile and long context slide encoder computation pathway."},{"name":"Tile 序列 + 坐标","desc":"一张 WSI 的 tile embeddings 按空间位置组成超长序列。","name_en":"Tile sequence +","desc_en":"Performs Tile sequence + within the core two level tile and long context slide encoder computation pathway."},{"name":"Masked Tile 输入","desc":"slide 预训练时遮蔽部分 tile embeddings，要求模型利用跨区域上下文恢复。","name_en":"Masked Tile input","desc_en":"Performs Masked Tile input within the core two level tile and long context slide encoder computation pathway."},{"name":"LongNet Slide Encoder","desc":"膨胀注意力以稀疏、多尺度连接覆盖数万 tile，避免全局 N² attention。","name_en":"LongNet Slide Encoder","desc_en":"Performs LongNet Slide Encoder within the core two level tile and long context slide encoder computation pathway."},{"name":"Slide MAE 目标","desc":"由上下文预测被遮 tile 表征，训练 whole-slide 级关系建模。","name_en":"Slide MAE objective","desc_en":"Performs Slide MAE objective within the core two level tile and long context slide encoder computation pathway."},{"name":"WSI Embedding","desc":"聚合后的长上下文表示包含跨区域组织结构与病灶异质性。","name_en":"WSI Embedding","desc_en":"Applies WSI Embedding to project aggregated representations toward the target task head."},{"name":"病例级 Head","desc":"接分类、检索、分型或预后任务头进行少量适配。","name_en":"Head","desc_en":"Produces contextualized whole-slide representation and patient/case-level diagnostic or genomic predictions via Head."}],"design_principles":["先用 tile encoder 学局部细胞/组织形态，再用独立 slide encoder 学跨 tile 空间关系，分层匹配 WSI 尺度。","LongNet 的 dilated attention 以多尺度稀疏连接扩大上下文，使超长 tile 序列无需完整两两注意力。","slide-level masked autoencoding 要求从可见区域推断被遮 tile 表征，显式预训练病例级组织上下文。"],"design_principles_en":["Core Hypothesis: Encode tiles via DINOv2, then model whole-slide spatial dependencies across all tiles using LongNet dilated attention pretrained with MAE.","Architectural Delta: 1.3B-tile real-world clinical pretraining (171,189 WSIs) + LongNet linear-scaling dilated slide attention + vision-language report alignment.","Mathematical Formalism: Masked Tile Embedding Reconstruction Across Tens of Thousands of WSI Coordinates via LongNet."],"med_apps":["whole-slide encoder 能捕捉肿瘤–间质、多个病灶区和空间异质性，这是独立 tile 分类不能提供的。","组织采样、坐标编码和超长序列截断均会影响病例结论；外部国家、染色和扫描流程仍需验证。"],"med_apps_en":["Clinical Translation: Targets whole-slide cancer subtyping, mutation/biomarker prediction, and prognostic modeling across health-system cohorts.","Evidence & Safety Boundary: Represents true whole-slide context pretraining; external multi-institutional calibration remains essential."],"attrs":{"上一代瓶颈":"独立 tile 表示无法捕获病例级、跨区域关系","核心想法":"DINOv2 tile encoder 加 LongNet/MAE slide encoder 建模超长全切片上下文","关键改进":"在 13 亿 tiles 上预训练并进行 whole-slide long-context aggregation","医学适配":"面向病理病例级诊断、分型和预后迁移","适用范围与证据":"whole-slide 建模是实质变化；跨国家流程仍需验证"},"attrs_en":{"上一代瓶颈":"Tile-level encoders treat patches independently, while standard self-attention cannot scale to 40,000+ tiles per gigapixel WSI.","核心想法":"Encode tiles via DINOv2, then model whole-slide spatial dependencies across all tiles using LongNet dilated attention pretrained with MAE.","关键改进":"1.3B-tile real-world clinical pretraining (171,189 WSIs) + LongNet linear-scaling dilated slide attention + vision-language report alignment.","医学适配":"Targets whole-slide cancer subtyping, mutation/biomarker prediction, and prognostic modeling across health-system cohorts.","适用范围与证据":"Represents true whole-slide context pretraining; external multi-institutional calibration remains essential."},"paper_title":"A Whole-Slide Foundation Model for Digital Pathology from Real-World Data","paper_url":"https://doi.org/10.1038/s41586-024-07441-w","code_label":"作者/机构官方实现","code_url":"https://github.com/prov-gigapath/prov-gigapath","has_code":true,"image":"assets/791888436d5b65d56de9.avif"},{"id":"architecture_model_042_merlin","num":42,"num_str":"042","year":2026,"year_str":"2026 (preprint 2024)","venue":"Nature","venue_group":"nature","era_group":"era4","title":"Merlin","family_id":"models_volumetric_foundations","family_code":"09","family_short":"CT/MRI 检查级模型","family_en":"Volumetric Study FMs","family_icon":"IX","family_label":"CT/MRI 检查级基础模型：输入单位从切片走向完整 study","archetype":"native_3d_ct_multitask_vision_language","archetype_en":"native_3d_ct_multitask_vision_language","accent":"#6B5700","fig_badge":"Figure 1 · PDF p.Official HTML Figure 1 asset","fig_href":"https://www.nature.com/articles/s41586-026-10181-8","core_mech":"以 I3D ResNet-152 原生编码完整 CT，并用 EHR phenotype prediction 与 Clinical Longformer 报告对比进行多源多任务预训练。","core_mech_en":"Native 3D abdominal CT foundation model encoding whole volumes with an I3D ResNet-152 supervised jointly by EHR diagnosis codes (phenotypes) and radiology reports.","input_desc":"三维 CT 体积、同检查放射报告与 EHR diagnosis codes","input_en":"Volumetric 3D abdominal CT scan + paired free-text radiology report + longitudinal EHR ICD diagnosis codes","output_desc":"检查级 3D 视觉语言表征及零样本/适配后临床任务输出","output_en":"Study-level 3D visual-linguistic representation supporting zero-shot findings, EHR phenotype prediction, and 3D segmentation","form_title":"核心公式 · Merlin 用 EHR 表型与长报告联合监督 3D CT","form_title_en":"Core Formalism · Joint Multi-Task Supervision: 3D CT–Report Contrastive Loss + EHR Phenotype Binary Cross-Entropy","nodes":[{"name":"3D CT Volume","desc":"完整体积经统一视野与体素预处理输入，而不是随机单切片。","name_en":"3D CT Volume","desc_en":"Ingests volumetric 3d abdominal ct scan + paired free-text radiology report + longitudinal ehr icd diagnosis codes and prepares initial tensor representations (3D CT Volume)."},{"name":"I3D ResNet-152","desc":"将 2D ResNet 卷积核沿深度维膨胀，原生编码层间解剖与全体积上下文。","name_en":"I3D ResNet-152","desc_en":"Executes I3D ResNet-152 to extract primary structural features and establish spatial/sequence encoding."},{"name":"CT Embedding","desc":"3D feature map 经聚合/投影得到检查级向量，同时保留可供下游 decoder 使用的空间特征。","name_en":"CT Embedding","desc_en":"Performs CT Embedding within the core native 3d ct multitask vision language computation pathway."},{"name":"EHR Diagnosis Codes","desc":"检查相关的结构化表型/诊断代码提供多标签临床监督。","name_en":"EHR Diagnosis Codes","desc_en":"Performs EHR Diagnosis Codes within the core native 3d ct multitask vision language computation pathway."},{"name":"表型预测 Head","desc":"由 CT embedding 预测多种 diagnosis-code phenotypes，注入结构化疾病语义。","name_en":"prediction Head","desc_en":"Performs prediction Head within the core native 3d ct multitask vision language computation pathway."},{"name":"放射报告","desc":"长篇 findings/impression 等检查文本作为非结构化监督。","name_en":"Radiology Report","desc_en":"Performs Radiology Report within the core native 3d ct multitask vision language computation pathway."},{"name":"Clinical Longformer","desc":"长上下文临床语言 encoder 处理最长 4,096 tokens 的报告内容。","name_en":"Clinical Longformer","desc_en":"Performs Clinical Longformer within the core native 3d ct multitask vision language computation pathway."},{"name":"CT–报告对比","desc":"检查级 CT 与配对报告在共享空间对齐，并与非配对报告分离。","name_en":"CT–","desc_en":"Performs CT– within the core native 3d ct multitask vision language computation pathway."},{"name":"多任务预训练","desc":"结构化 EHR 预测与报告对比可联合/分阶段优化同一 3D encoder。","name_en":"multi-task pretraining","desc_en":"Applies multi-task pretraining to project aggregated representations toward the target task head."},{"name":"临床任务接口","desc":"冻结/适配后用于零样本 findings、检索、疾病预测、报告生成和 3D 分割。","name_en":"Stage 10","desc_en":"Produces study-level 3d visual-linguistic representation supporting zero-shot findings, ehr phenotype prediction, and 3d segmentation via Stage 10."}],"design_principles":["I3D 把二维预训练卷积核沿 z 轴膨胀，在继承初始化的同时让模型直接学习体积解剖。","EHR codes 提供结构化多标签疾病监督，长报告提供自由文本语义，两者从不同角度约束同一 CT encoder。","CT–报告共享嵌入支持零样本与检索，保留的 3D feature hierarchy 又可接生成或分割 decoder。"],"design_principles_en":["Core Hypothesis: Train a native 3D convolutional encoder on 15,331 paired abdominal CTs using both free-text reports (Clinical-Longformer) and 1,692 EHR phenotypes.","Architectural Delta: Synergistic dual supervision (radiology prose + structured EHR codes) on native 3D volumes, validated across 44,098 external CTs.","Mathematical Formalism: Joint Multi-Task Supervision: 3D CT–Report Contrastive Loss + EHR Phenotype Binary Cross-Entropy."],"med_apps":["Merlin 代表从逐切片 2D VLM 转向原生 3D 检查级建模，并已覆盖外部 CT 验证与多类适配任务。","训练主域仍以腹部 CT 和回顾性 EHR 为核心；代码标签偏差、报告生成事实性与前瞻工作流安全需分别验证。"],"med_apps_en":["Clinical Translation: Supports zero-shot abnormality classification, cross-modal retrieval, 5-year chronic disease risk prediction, and 3D organ segmentation.","Evidence & Safety Boundary: Among the most thoroughly externally validated 3D CT foundation models; evidence remains retrospective."],"attrs":{"上一代瓶颈":"逐切片 2D VLM 无法充分建模体积解剖和检查级上下文","核心想法":"联合 3D CT、EHR diagnosis codes 与报告学习检查级视觉语言表示","关键改进":"原生 3D encoder、多源临床监督与 44098 个外部 CT 的验证","医学适配":"代表腹部 CT 主训练域上的原生 3D VLM 与外部大规模评估","适用范围与证据":"已发表证据较强的 3D CT FM 之一；仍为回顾性且非自治报告安全证明"},"attrs_en":{"上一代瓶颈":"Slice-wise 2D VLMs fail to capture 3D volumetric continuity, while report-only supervision misses structured longitudinal EHR outcomes.","核心想法":"Train a native 3D convolutional encoder on 15,331 paired abdominal CTs using both free-text reports (Clinical-Longformer) and 1,692 EHR phenotypes.","关键改进":"Synergistic dual supervision (radiology prose + structured EHR codes) on native 3D volumes, validated across 44,098 external CTs.","医学适配":"Supports zero-shot abnormality classification, cross-modal retrieval, 5-year chronic disease risk prediction, and 3D organ segmentation.","适用范围与证据":"Among the most thoroughly externally validated 3D CT foundation models; evidence remains retrospective."},"paper_title":"Merlin: a Computed Tomography Vision-Language Foundation Model and Dataset","paper_url":"https://doi.org/10.1038/s41586-026-10181-8","code_label":"作者/机构官方实现","code_url":"https://github.com/StanfordMIMI/Merlin","has_code":true,"image":"assets/c56c2a02376ec883fa1f.avif"},{"id":"architecture_model_043_deep_autoencoder","num":43,"num_str":"043","year":2006,"year_str":"2006","venue":"Science","venue_group":"journal","era_group":"era1","title":"Deep Autoencoder","family_id":"models_generative","family_code":"10","family_short":"生成、扩散与流匹配","family_en":"Generative, Diffusion & Flow","family_icon":"X","family_label":"生成模型：从潜变量与对抗学习到 diffusion、flow 与 consistency","archetype":"layerwise_pretrained_symmetric_bottleneck","archetype_en":"layerwise_pretrained_symmetric_bottleneck","accent":"#6B5700","fig_badge":"Figure 1 · PDF p.2","fig_href":"https://www.cs.toronto.edu/~hinton/papers.html","core_mech":"逐层 RBM 生成式预训练初始化深层对称 encoder–decoder，再以全局重建误差微调非线性 bottleneck。","core_mech_en":"Layer-by-layer Restricted Boltzmann Machine (RBM) generative pretraining initializing a deep symmetric encoder–decoder fine-tuned via global reconstruction error.","input_desc":"高维数据向量或展平图像","input_en":"High-dimensional input vector or flattened image patch","output_desc":"低维 bottleneck 表征与输入重建","output_en":"Low-dimensional non-linear bottleneck code z and reconstructed input x̂","form_title":"核心公式 · 深层自编码器以重建约束低维 bottleneck","form_title_en":"Core Formalism · Non-Linear Bottleneck Manifold Compression via Reconstruction Minimization","nodes":[{"name":"高维输入 x","desc":"像素或其他连续/二值高维观测进入深层非线性压缩器。","name_en":"input x","desc_en":"Ingests high-dimensional input vector or flattened image patch and prepares initial tensor representations (input x)."},{"name":"逐层 RBM 预训练","desc":"从底到顶依次训练受限玻尔兹曼机，每层学习上一层表示的生成模型。","name_en":"RBM pretraining","desc_en":"Executes RBM pretraining to extract primary structural features and establish spatial/sequence encoding."},{"name":"Encoder 下层","desc":"把输入投影到逐渐更窄的隐藏层，提取局部到抽象特征。","name_en":"Encoder","desc_en":"Performs Encoder within the core layerwise pretrained symmetric bottleneck computation pathway."},{"name":"Encoder 高层","desc":"继续压缩并为 bottleneck 提供初始化良好的深层表示。","name_en":"Encoder","desc_en":"Performs Encoder within the core layerwise pretrained symmetric bottleneck computation pathway."},{"name":"低维 Code","desc":"网络最窄层是非线性降维坐标，也是供下游使用的 latent。","name_en":"Code","desc_en":"Performs Code within the core layerwise pretrained symmetric bottleneck computation pathway."},{"name":"Decoder 高层","desc":"将 encoder 权重展开为近似镜像解码路径并逐步扩维。","name_en":"Decoder","desc_en":"Performs Decoder within the core layerwise pretrained symmetric bottleneck computation pathway."},{"name":"Decoder 下层","desc":"把高层 latent 细化回输入维度的重建表示。","name_en":"Decoder","desc_en":"Performs Decoder within the core layerwise pretrained symmetric bottleneck computation pathway."},{"name":"重建 x̂","desc":"输出与输入同维度，度量模型保留的信息。","name_en":"reconstruction x̂","desc_en":"Applies reconstruction x̂ to project aggregated representations toward the target task head."},{"name":"全局 Fine-Tune","desc":"以重建误差对展开后的整个 encoder–decoder 反向传播微调。","name_en":"global Fine-Tune","desc_en":"Produces low-dimensional non-linear bottleneck code z and reconstructed input x̂ via global Fine-Tune."}],"design_principles":["非线性 encoder–decoder 以重建约束学习低维 manifold，突破 PCA 的线性子空间限制。","2006 年方案先逐层生成式预训练再展开为自编码器，解决当时深网从随机初始化难优化的问题。","bottleneck 容量与重建误差共同定义信息压缩：过宽会学恒等映射，过窄会丢失任务相关细节。"],"design_principles_en":["Core Hypothesis: Pretrain stacked RBMs greedily layer-by-layer, then unfold into a symmetric encoder–decoder fine-tuned by backpropagation.","Architectural Delta: Demonstrated that deep non-linear bottleneck manifolds could be stably optimized to compress high-dimensional perceptual data.","Mathematical Formalism: Non-Linear Bottleneck Manifold Compression via Reconstruction Minimization."],"med_apps":["该结构奠定医学图像去噪、压缩、缺失重建和基于重建误差的异常检测。","低重建误差不保证临床正常，强 decoder 也可能重建异常；异常检测必须进行病种和设备分层验证。"],"med_apps_en":["Clinical Translation: Conceptual ancestor of medical denoising autoencoders, unsupervised anomaly detection, and latent-space compression.","Evidence & Safety Boundary: Historical foundation; deterministic L2 autoencoders blur high-frequency details and lack a tractable generative sampling density."],"attrs":{"上一代瓶颈":"PCA 与手工字典只能表达线性或预设结构","核心想法":"用深层 encoder-decoder 学非线性低维 latent 并重建输入","关键改进":"可学习的 bottleneck 表征与逐层预训练","医学适配":"奠定医学去噪、异常检测、压缩和 latent generative 接口","适用范围与证据":"思想基础；普通 AE 的采样、不确定性和 L2 模糊有限"},"attrs_en":{"上一代瓶颈":"Linear PCA could not capture curved data manifolds, while deep non-linear autoencoders failed to optimize from random initialization.","核心想法":"Pretrain stacked RBMs greedily layer-by-layer, then unfold into a symmetric encoder–decoder fine-tuned by backpropagation.","关键改进":"Demonstrated that deep non-linear bottleneck manifolds could be stably optimized to compress high-dimensional perceptual data.","医学适配":"Conceptual ancestor of medical denoising autoencoders, unsupervised anomaly detection, and latent-space compression.","适用范围与证据":"Historical foundation; deterministic L2 autoencoders blur high-frequency details and lack a tractable generative sampling density."},"paper_title":"Reducing the Dimensionality of Data with Neural Networks","paper_url":"https://pubmed.ncbi.nlm.nih.gov/16873662/","code_label":"未提供官方实现","code_url":"","has_code":false,"image":"assets/10db81cefaccf99c2d0a.avif"},{"id":"architecture_model_044_gan","num":44,"num_str":"044","year":2014,"year_str":"2014","venue":"NeurIPS","venue_group":"ml","era_group":"era1","title":"GAN","family_id":"models_generative","family_code":"10","family_short":"生成、扩散与流匹配","family_en":"Generative, Diffusion & Flow","family_icon":"X","family_label":"生成模型：从潜变量与对抗学习到 diffusion、flow 与 consistency","archetype":"adversarial_generator_discriminator_game","archetype_en":"adversarial_generator_discriminator_game","accent":"#6B5700","fig_badge":"Figure 1 · PDF p.4","fig_href":"https://proceedings.neurips.cc/paper/2014/hash/f033ed80deb0234979a61f95710dbe25-Abstract.html","core_mech":"生成器与判别器通过同一 value function 对抗优化，以数据驱动判别器替代固定重建损失。","core_mech_en":"Generator and discriminator networks engage in a two-player minimax game, replacing hand-crafted pixel reconstruction losses with a learned adversarial critic.","input_desc":"先验噪声 z 与真实数据样本 x","input_en":"Latent noise vector z ~ p_z(z) and real data samples x ~ p_data(x)","output_desc":"逼近真实数据分布的生成样本","output_en":"Synthesized samples G(z) approximating the real data distribution","form_title":"核心公式 · GAN 生成器与判别器的 minimax 博弈","form_title_en":"Core Formalism · Two-Player Minimax Adversarial Value Function Between Generator G and Discriminator D","nodes":[{"name":"先验噪声 z","desc":"从简单分布采样的 latent 随机向量提供生成多样性。","name_en":"Prior Latent Noise z","desc_en":"Ingests latent noise vector z ~ p_z(z) and real data samples x ~ p_data(x) and prepares initial tensor representations (Prior Latent Noise z)."},{"name":"Generator G","desc":"可微网络把 z 映射为数据空间样本 G(z)。","name_en":"Generator G","desc_en":"Executes Generator G to extract primary structural features and establish spatial/sequence encoding."},{"name":"生成样本","desc":"由 G 产生、训练时应逐渐接近真实分布的候选样本。","name_en":"Synthesized Sample","desc_en":"Performs Synthesized Sample within the core adversarial generator discriminator game computation pathway."},{"name":"真实样本 x","desc":"从未知真实数据分布采样，作为判别器正例。","name_en":"Real Data Sample x","desc_en":"Performs Real Data Sample x within the core adversarial generator discriminator game computation pathway."},{"name":"Discriminator D","desc":"同一判别网络对真实和生成样本输出为真的概率。","name_en":"Discriminator D","desc_en":"Performs Discriminator D within the core adversarial generator discriminator game computation pathway."},{"name":"log D(x)","desc":"奖励判别器把真实样本判断为真。","name_en":"log D(x)","desc_en":"Performs log D(x) within the core adversarial generator discriminator game computation pathway."},{"name":"log(1−D(G(z)))","desc":"判别器奖励识别假样本；生成器则通过相反方向欺骗 D。","name_en":"log(1−D(G(z","desc_en":"Applies log(1−D(G(z to project aggregated representations toward the target task head."},{"name":"生成分布 p_g","desc":"训练后丢弃判别器，通过采样 z 直接生成新数据。","name_en":"p_g","desc_en":"Produces synthesized samples g(z) approximating the real data distribution via p_g."}],"design_principles":["判别器估计真实与生成分布的可分性，生成器通过判别梯度隐式学习数据分布而无需显式 likelihood。","训练是二人 minimax 博弈；理想均衡处生成分布等于真实分布，判别器无法区分二者。","判别器相当于可学习损失，会持续适应当前生成错误，而不是固定的像素距离。"],"design_principles_en":["Core Hypothesis: Pit a generator G against an adversarial discriminator D trained to distinguish real samples from synthesized ones.","Architectural Delta: Implicit density learning via Jensen-Shannon divergence minimization yielding sharp, high-frequency visual samples.","Mathematical Formalism: Two-Player Minimax Adversarial Value Function Between Generator G and Discriminator D."],"med_apps":["可用于合成影像、增强和跨模态映射，但视觉逼真不代表病灶、剂量或定量值真实。","mode collapse 和不稳定训练会隐性减少病种多样性；隐私重复与罕见病例覆盖必须审计。"],"med_apps_en":["Clinical Translation: Catalyzed medical cross-modality synthesis (MR-to-CT), low-dose perceptual enhancement, and synthetic cohort augmentation.","Evidence & Safety Boundary: Foundational generative paradigm; training instability, mode collapse, and anatomically unfaithful hallucinations pose severe clinical risks."],"attrs":{"上一代瓶颈":"显式 likelihood 生成模型难训练且样本常过度平滑","核心想法":"generator 与 discriminator 进行对抗式分布学习","关键改进":"min-max 学习可直接产生锐利样本而无需显式密度","医学适配":"推动 MR-CT 翻译、低剂量增强和合成数据","适用范围与证据":"历史基础；mode collapse、训练不稳和 hallucination 风险突出"},"attrs_en":{"上一代瓶颈":"Pixel-wise L1/L2 and maximum-likelihood generative models averaged over uncertain modes, producing blurry textures.","核心想法":"Pit a generator G against an adversarial discriminator D trained to distinguish real samples from synthesized ones.","关键改进":"Implicit density learning via Jensen-Shannon divergence minimization yielding sharp, high-frequency visual samples.","医学适配":"Catalyzed medical cross-modality synthesis (MR-to-CT), low-dose perceptual enhancement, and synthetic cohort augmentation.","适用范围与证据":"Foundational generative paradigm; training instability, mode collapse, and anatomically unfaithful hallucinations pose severe clinical risks."},"paper_title":"Generative Adversarial Nets","paper_url":"https://papers.neurips.cc/paper_files/paper/2014/hash/f033ed80deb0234979a61f95710dbe25-Abstract.html","code_label":"未提供官方实现","code_url":"","has_code":false,"image":"assets/0b06c4d30e085f8a04be.avif"},{"id":"architecture_model_045_pix2pix","num":45,"num_str":"045","year":2017,"year_str":"2017","venue":"CVPR","venue_group":"cv","era_group":"era2","title":"pix2pix","family_id":"models_generative","family_code":"10","family_short":"生成、扩散与流匹配","family_en":"Generative, Diffusion & Flow","family_icon":"X","family_label":"生成模型：从潜变量与对抗学习到 diffusion、flow 与 consistency","archetype":"paired_conditional_unet_patchgan","archetype_en":"paired_conditional_unet_patchgan","accent":"#6B5700","fig_badge":"Figure 2 · PDF p.3","fig_href":"https://openaccess.thecvf.com/content_cvpr_2017/html/Isola_Image-To-Image_Translation_With_CVPR_2017_paper.html","core_mech":"以 U-Net 生成器保持逐像素空间对应，70×70 conditional PatchGAN 学局部真实感，并用配对 L1 锚定结构。","core_mech_en":"Pairs a U-Net generator (preserving pixel-level spatial alignment) with a 70×70 conditional PatchGAN discriminator and paired L1 structural anchoring.","input_desc":"空间配准的成对源域图像 x 与目标域图像 y","input_en":"Spatially co-registered paired source image x and target ground-truth image y","output_desc":"与 x 对齐的目标域预测 G(x)","output_en":"Spatially aligned translated target-domain image G(x)","form_title":"核心公式 · pix2pix 结合条件对抗真实感与配对 L1 保真","form_title_en":"Core Formalism · Conditional PatchGAN Adversarial Objective Coupled with Paired L1 Pixel Fidelity","nodes":[{"name":"条件图像 x","desc":"源域图像同时输入 generator 和 discriminator，限定生成内容。","name_en":"Stage 01","desc_en":"Ingests spatially co-registered paired source image x and target ground-truth image y and prepares initial tensor representations (Stage 01)."},{"name":"U-Net Encoder","desc":"逐层下采样提取从局部纹理到全局语义的条件特征。","name_en":"U-Net Encoder","desc_en":"Executes U-Net Encoder to extract primary structural features and establish spatial/sequence encoding."},{"name":"Generator Bottleneck","desc":"最深层压缩表示捕获整体结构；训练时 dropout 可提供随机性。","name_en":"Generator Bottleneck","desc_en":"Performs Generator Bottleneck within the core paired conditional unet patchgan computation pathway."},{"name":"U-Net Decoder","desc":"转置卷积/上采样逐级恢复目标域分辨率。","name_en":"U-Net Decoder","desc_en":"Performs U-Net Decoder within the core paired conditional unet patchgan computation pathway."},{"name":"长 Skip Concats","desc":"同尺度 encoder 特征拼接到 decoder，直接传递边缘与空间位置。","name_en":"Skip Concats","desc_en":"Performs Skip Concats within the core paired conditional unet patchgan computation pathway."},{"name":"生成目标 G(x)","desc":"与输入逐像素对齐的目标域预测。","name_en":"objective G(x","desc_en":"Performs objective G(x within the core paired conditional unet patchgan computation pathway."},{"name":"配对真值 y","desc":"同一对象/位置的真实目标域图像。","name_en":"Stage 07","desc_en":"Performs Stage 07 within the core paired conditional unet patchgan computation pathway."},{"name":"70×70 PatchGAN","desc":"判别器对 x 与 y/G(x) 的局部 patch 对输出真假网格，而非单一全图分数。","name_en":"70×70 PatchGAN","desc_en":"Performs 70×70 PatchGAN within the core paired conditional unet patchgan computation pathway."},{"name":"cGAN Loss","desc":"鼓励生成局部纹理落在真实条件目标分布。","name_en":"cGAN Loss","desc_en":"Applies cGAN Loss to project aggregated representations toward the target task head."},{"name":"L1 Fidelity","desc":"像素 L1 保持配对图的低频结构与整体对应，并与对抗损失加权相加。","name_en":"L1 Fidelity","desc_en":"Produces spatially aligned translated target-domain image g(x) via L1 Fidelity."}],"design_principles":["conditional GAN 让判别器同时看 x 和输出，迫使真实性与给定输入相一致，而非任意生成。","PatchGAN 把判别学习限制在局部感受野，充当可学习的高频纹理损失并可卷积应用到任意尺寸。","U-Net skips 和 L1 保持配对结构，adversarial loss 弥补单纯像素回归造成的过度平滑。"],"design_principles_en":["Core Hypothesis: Condition both U-Net generator and patch-level discriminator on the input image x while anchoring low-frequency structure via L1 loss.","Architectural Delta: U-Net skip generator + 70×70 Markovian PatchGAN critic + λ||y − G(x)||_1 structural constraint.","Mathematical Formalism: Conditional PatchGAN Adversarial Objective Coupled with Paired L1 Pixel Fidelity."],"med_apps":["适用于严格配准的低剂量→常规剂量、MR→CT 等 mapping；配准误差会被模型当作生成目标。","Patch 级真实感不能保证器官拓扑或定量测量一致，必须检查病灶保真和物理/临床约束。"],"med_apps_en":["Clinical Translation: Workhorse baseline for paired low-dose-to-full-dose PET/CT, MR-to-synthetic-CT radiation planning, and virtual histological staining.","Evidence & Safety Boundary: Strong paired image-translation baseline; remains an image-domain mapping without physical sensor consistency guarantees."],"attrs":{"上一代瓶颈":"纯 L1/L2 输出过平滑，普通 GAN 不保证输入输出对应","核心想法":"以输入为条件训练 PatchGAN，并以 L1 保持配对结构","关键改进":"paired fidelity 与 learned local texture loss 结合，常用 U-Net generator","医学适配":"用于 paired 低剂量、PET、MR-CT 和骨抑制映射","适用范围与证据":"强 mapping 基线；不保证测量一致，可能生成逼真但错误结构"},"attrs_en":{"上一代瓶颈":"Pure L1/L2 regression blurs high-frequency textures, while unconditional GANs do not preserve patient-specific spatial anatomy.","核心想法":"Condition both U-Net generator and patch-level discriminator on the input image x while anchoring low-frequency structure via L1 loss.","关键改进":"U-Net skip generator + 70×70 Markovian PatchGAN critic + λ||y − G(x)||_1 structural constraint.","医学适配":"Workhorse baseline for paired low-dose-to-full-dose PET/CT, MR-to-synthetic-CT radiation planning, and virtual histological staining.","适用范围与证据":"Strong paired image-translation baseline; remains an image-domain mapping without physical sensor consistency guarantees."},"paper_title":"Image-to-Image Translation with Conditional Adversarial Networks","paper_url":"https://openaccess.thecvf.com/content_cvpr_2017/html/Isola_Image-To-Image_Translation_With_CVPR_2017_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/phillipi/pix2pix","has_code":true,"image":"assets/821e89c819b81693fd9f.avif"},{"id":"architecture_model_046_cyclegan","num":46,"num_str":"046","year":2017,"year_str":"2017","venue":"ICCV","venue_group":"cv","era_group":"era2","title":"CycleGAN","family_id":"models_generative","family_code":"10","family_short":"生成、扩散与流匹配","family_en":"Generative, Diffusion & Flow","family_icon":"X","family_label":"生成模型：从潜变量与对抗学习到 diffusion、flow 与 consistency","archetype":"unpaired_bidirectional_cycle_consistent_gan","archetype_en":"unpaired_bidirectional_cycle_consistent_gan","accent":"#6B5700","fig_badge":"Figure 3 · PDF p.3","fig_href":"https://openaccess.thecvf.com/content_iccv_2017/html/Zhu_Unpaired_Image-To-Image_Translation_ICCV_2017_paper.html","core_mech":"双生成器、双 PatchGAN 与 X→Y→X / Y→X→Y 两个 cycle L1 闭环，使不成对域转换可训练。","core_mech_en":"Couples dual generators (G: X→Y, F: Y→X) and dual PatchGAN discriminators with forward and backward L1 cycle-consistency loops for unpaired translation.","input_desc":"两组不成对的域 X 与域 Y 图像","input_en":"Two unpaired collections of images from source domain X and target domain Y","output_desc":"X→Y 与 Y→X 两个方向的域转换图像","output_en":"Bi-directional domain-translated images G(x) ∈ Y and F(y) ∈ X","form_title":"核心公式 · CycleGAN 的双向对抗与两个循环一致性闭环","form_title_en":"Core Formalism · Bidirectional Adversarial Losses + Forward/Backward Cycle Consistency (X→Y→X & Y→X→Y)","nodes":[{"name":"真实域 X","desc":"从源域边缘分布独立采样，无需与 Y 样本一一对应。","name_en":"Stage 01","desc_en":"Ingests two unpaired collections of images from source domain x and target domain y and prepares initial tensor representations (Stage 01)."},{"name":"真实域 Y","desc":"从目标域边缘分布独立采样，不要求同患者或配准。","name_en":"Stage 02","desc_en":"Executes Stage 02 to extract primary structural features and establish spatial/sequence encoding."},{"name":"Generator G:X→Y","desc":"残差式 generator 把 X 图像映射为 Y 风格。","name_en":"Generator G:X→Y","desc_en":"Performs Generator G:X→Y within the core unpaired bidirectional cycle consistent gan computation pathway."},{"name":"Generator F:Y→X","desc":"第二个 generator 学习反方向 Y→X 映射。","name_en":"Generator F:Y→X","desc_en":"Performs Generator F:Y→X within the core unpaired bidirectional cycle consistent gan computation pathway."},{"name":"生成 Ŷ","desc":"G(x) 应在外观上不可与真实域 Y 区分。","name_en":"Ŷ","desc_en":"Performs Ŷ within the core unpaired bidirectional cycle consistent gan computation pathway."},{"name":"生成 X̂","desc":"F(y) 应在外观上不可与真实域 X 区分。","name_en":"X̂","desc_en":"Performs X̂ within the core unpaired bidirectional cycle consistent gan computation pathway."},{"name":"PatchGAN D_Y","desc":"区分真实 y 与 G(x)，约束 X→Y 的目标域局部纹理。","name_en":"PatchGAN D_Y","desc_en":"Performs PatchGAN D_Y within the core unpaired bidirectional cycle consistent gan computation pathway."},{"name":"PatchGAN D_X","desc":"区分真实 x 与 F(y)，约束 Y→X 的目标域局部纹理。","name_en":"PatchGAN D_X","desc_en":"Performs PatchGAN D_X within the core unpaired bidirectional cycle consistent gan computation pathway."},{"name":"Cycle 重建 x̃","desc":"F(G(x)) 应回到原 x，以 L1 cycle loss 约束前向映射可逆。","name_en":"Cycle reconstruction x̃","desc_en":"Applies Cycle reconstruction x̃ to project aggregated representations toward the target task head."},{"name":"Cycle 重建 ỹ","desc":"G(F(y)) 应回到原 y，以 L1 cycle loss 约束反向映射可逆。","name_en":"Cycle reconstruction ỹ","desc_en":"Produces bi-directional domain-translated images g(x) ∈ y and f(y) ∈ x via Cycle reconstruction ỹ."}],"design_principles":["两个 adversarial losses 只匹配 X 与 Y 的边缘分布，并不需要病例级配对。","双向 cycle consistency 要求映射后仍能恢复原样本，从大量可能的域映射中缩小解空间。","两个生成器与两个判别器形成闭环：目标域真实感和往返可恢复性共同约束转换。"],"design_principles_en":["Core Hypothesis: Constrain unpaired cross-domain mapping by requiring that translating X→Y and back Y→X recovers the original input image.","Architectural Delta: Dual adversarial critics + forward/backward cycle-consistency L1 loss + identity mapping regularizer.","Mathematical Formalism: Bidirectional Adversarial Losses + Forward/Backward Cycle Consistency (X→Y→X & Y→X→Y)."],"med_apps":["可在缺乏配对扫描时探索 MR↔CT、对比度转换或 scanner harmonization。","cycle 可逆不等于解剖、病灶或 HU 等定量值守恒；医学使用必须增加结构/物理约束和逐病例审计。"],"med_apps_en":["Clinical Translation: Widely used for unpaired MR-to-CT synthesis, stain normalization in pathology, and cross-vendor scanner style harmonization.","Evidence & Safety Boundary: Useful for exploratory domain adaptation, but cycle consistency is under-constrained and can hallucinate or erase lesions when pathology prevalence differs across domains."],"attrs":{"上一代瓶颈":"医学跨模态病例常不成对，pix2pix 无法直接训练","核心想法":"用双向生成器、两个判别器和 cycle consistency 学无配对域转换","关键改进":"cycle loss 缩小任意 domain mapping 的解空间","医学适配":"用于 MR-CT、MRI contrast 和 scanner harmonization","适用范围与证据":"探索与 style transfer 仍有用；cycle 不保证解剖或定量值保持"},"attrs_en":{"上一代瓶颈":"Acquiring perfectly co-registered paired multi-modality scans (e.g., same-patient paired MR and CT) is often clinically infeasible.","核心想法":"Constrain unpaired cross-domain mapping by requiring that translating X→Y and back Y→X recovers the original input image.","关键改进":"Dual adversarial critics + forward/backward cycle-consistency L1 loss + identity mapping regularizer.","医学适配":"Widely used for unpaired MR-to-CT synthesis, stain normalization in pathology, and cross-vendor scanner style harmonization.","适用范围与证据":"Useful for exploratory domain adaptation, but cycle consistency is under-constrained and can hallucinate or erase lesions when pathology prevalence differs across domains."},"paper_title":"Unpaired Image-to-Image Translation using Cycle-Consistent Adversarial Networks","paper_url":"https://openaccess.thecvf.com/content_ICCV_2017/papers/Zhu_Unpaired_Image-To-Image_Translation_ICCV_2017_paper.pdf","code_label":"作者/机构官方实现","code_url":"https://github.com/junyanz/CycleGAN","has_code":true,"image":"assets/b10da645cce0d9858b09.avif"},{"id":"architecture_model_047_fbpconvnet","num":47,"num_str":"047","year":2017,"year_str":"2017","venue":"IEEE Transactions on Image Processing","venue_group":"journal","era_group":"era2","title":"FBPConvNet","family_id":"models_inverse_reconstruction","family_code":"11","family_short":"物理约束医学重建","family_en":"Physics-Informed Recon","family_icon":"XI","family_label":"物理约束重建：从后处理到展开优化与测量一致性","archetype":"analytic_reconstruction_postprocess","archetype_en":"analytic_reconstruction_postprocess","accent":"#145E75","fig_badge":"Figure 2 · PDF p.8","fig_href":"https://pubmed.ncbi.nlm.nih.gov/28641250/","core_mech":"解析 FBP 与单次残差 U-Net 串联，而非端到端替代投影算子或进行 unrolled data consistency。","core_mech_en":"Cascades analytical Filtered Backprojection (FBP) with a multi-scale residual U-Net in the image domain to remove sparse-view streaking artifacts.","input_desc":"稀疏视角 CT 投影 y（sinogram）与已知扫描几何","input_en":"Sparse-view CT sinogram measurements y with known acquisition geometry","output_desc":"伪影抑制后的 CT 图像 x_hat","output_en":"Artifact-suppressed CT image x̂ = x_FBP + R_θ(x_FBP)","form_title":"核心公式 · 解析初值、残差校正与仅审计的数据一致性","form_title_en":"Core Formalism · Analytical FBP Initialization Followed by Residual Convolutional Artifact Subtraction","nodes":[{"name":"投影 y","desc":"稀疏角度线积分测量；几何决定前向算子 A","name_en":"projection y","desc_en":"Ingests sparse-view ct sinogram measurements y with known acquisition geometry and prepares initial tensor representations (projection y)."},{"name":"FBP / A*","desc":"滤波后反投影；这里的 A* 含解析滤波，不是可学习层","name_en":"FBP / A*","desc_en":"Executes FBP / A* to extract primary structural features and establish spatial/sequence encoding."},{"name":"初始 CT","desc":"x0=FBP(y)，保留条纹和欠采样伪影","name_en":"CT","desc_en":"Performs CT within the core analytic reconstruction postprocess computation pathway."},{"name":"残差 U-Net","desc":"多尺度卷积编码—解码器只在图像域学习伪影校正","name_en":"residual U-Net","desc_en":"Performs residual U-Net within the core analytic reconstruction postprocess computation pathway."},{"name":"校正残差","desc":"R_theta(x0)，与解析初值相加得到重建","name_en":"residual","desc_en":"Performs residual within the core analytic reconstruction postprocess computation pathway."},{"name":"x_hat","desc":"x_hat=x0+R_theta(x0)","name_en":"x_hat","desc_en":"Performs x_hat within the core analytic reconstruction postprocess computation pathway."},{"name":"前投影 A","desc":"可将 x_hat 投影回测量域做离线核查","name_en":"projection A","desc_en":"Performs projection A within the core analytic reconstruction postprocess computation pathway."},{"name":"DC 审计","desc":"比较 A(x_hat) 与 y；原结构不把残差反馈给网络","name_en":"DC","desc_en":"Applies DC to project aggregated representations toward the target task head."},{"name":"单次后处理","desc":"K=0 个展开迭代；无交替 data-consistency 更新","name_en":"Stage 09","desc_en":"Produces artifact-suppressed ct image x̂ = x_fbp + r_θ(x_fbp) via Stage 09."}],"design_principles":["先用已知 CT 物理得到可解释的 FBP 初值，再把学习限制为图像域残差校正。","U-Net 的多尺度感受野能识别由稀疏角度造成的全局条纹，同时长跳连保留局部结构。","该模型没有展开迭代和反馈式数据一致性；视觉改善不保证 A(x_hat) 与实测投影一致。"],"design_principles_en":["Core Hypothesis: Exploit the fact that normal-operator streaking artifacts in 2D CT have a translational convolutional structure well matched to a multi-scale residual U-Net.","Architectural Delta: Fast analytical FBP inversion + residual U-Net learning the difference between streaked FBP and full-view ground truth.","Mathematical Formalism: Analytical FBP Initialization Followed by Residual Convolutional Artifact Subtraction."],"med_apps":["适合作为稀疏视角或低剂量 CT 的快速后处理基线，部署链路短。","对训练分布外的金属、截断或新几何，残差网络可能删去病灶或补出结构，必须回投影审计。"],"med_apps_en":["Clinical Translation: Canonical, fast image-domain post-processing baseline for sparse-view and low-dose CT reconstruction.","Evidence & Safety Boundary: High practical speed and historical impact, but enforces zero projection-domain data consistency at inference—risking hallucinated or smoothed subtle lesions."],"attrs":{"上一代瓶颈":"解析稀疏 CT 重建存在条纹，而直接端到端学习难扩展","核心想法":"先做解析 FBP，再用 residual U-Net/CNN 去除稀疏视角伪影","关键改进":"保留快速成熟的 FBP，并只学习 image-domain artifact residual","医学适配":"成为 sparse-view CT 极强 post-processing 基线","适用范围与证据":"历史与实用价值高；推理后无 projection data consistency"},"attrs_en":{"上一代瓶颈":"Analytical FBP suffers from severe streaking under sparse views, while traditional iterative MBIR takes minutes to hours per volume.","核心想法":"Exploit the fact that normal-operator streaking artifacts in 2D CT have a translational convolutional structure well matched to a multi-scale residual U-Net.","关键改进":"Fast analytical FBP inversion + residual U-Net learning the difference between streaked FBP and full-view ground truth.","医学适配":"Canonical, fast image-domain post-processing baseline for sparse-view and low-dose CT reconstruction.","适用范围与证据":"High practical speed and historical impact, but enforces zero projection-domain data consistency at inference—risking hallucinated or smoothed subtle lesions."},"paper_title":"Deep Convolutional Neural Network for Inverse Problems in Imaging","paper_url":"https://pubmed.ncbi.nlm.nih.gov/28641250/","code_label":"未提供官方实现","code_url":"","has_code":false,"image":"assets/6cf059a09f523bde1623.avif"},{"id":"architecture_model_048_learned_primal_dual","num":48,"num_str":"048","year":2018,"year_str":"2018","venue":"IEEE Transactions on Medical Imaging","venue_group":"journal","era_group":"era2","title":"Learned Primal-Dual","family_id":"models_inverse_reconstruction","family_code":"11","family_short":"物理约束医学重建","family_en":"Physics-Informed Recon","family_icon":"XI","family_label":"物理约束重建：从后处理到展开优化与测量一致性","archetype":"unrolled_primal_dual_reconstruction","archetype_en":"unrolled_primal_dual_reconstruction","accent":"#145E75","fig_badge":"Figure 2 · PDF p.7","fig_href":"https://arxiv.org/abs/1707.06474","core_mech":"同时学习 measurement-domain dual 与 image-domain primal 更新，并在每个 unrolled stage 显式调用 A 和 A*。","core_mech_en":"Unrolls primal–dual proximal optimization into K stages of paired measurement-domain (dual) and image-domain (primal) residual CNNs calling A and A* at every stage.","input_desc":"测量 y、前向算子 A 与伴随算子 A*","input_en":"Raw tomographic measurements y, forward projection operator A, and adjoint backprojection operator A*","output_desc":"K 级展开后的图像域 primal 重建 x_hat","output_en":"Reconstructed image x^{(K)} after K unrolled primal–dual iterations","form_title":"核心公式 · 展开式 primal–dual 双域更新","form_title_en":"Core Formalism · Coupled Primal (Image) & Dual (Sinogram) Learned Proximal Updates Calling A and A*","nodes":[{"name":"测量 y","desc":"CT sinogram 等 measurement-domain 数据","name_en":"Stage 01","desc_en":"Ingests raw tomographic measurements y, forward projection operator a, and adjoint backprojection operator a* and prepares initial tensor representations (Stage 01)."},{"name":"Primal h_k","desc":"多通道图像域记忆；首通道最终作为重建","name_en":"Primal h_k","desc_en":"Executes Primal h_k to extract primary structural features and establish spatial/sequence encoding."},{"name":"A","desc":"把当前 primal 图像投影到测量域","name_en":"A","desc_en":"Performs A within the core unrolled primal dual reconstruction computation pathway."},{"name":"Dual f_k","desc":"多通道测量域记忆，保留历史残差与特征","name_en":"Dual f_k","desc_en":"Performs Dual f_k within the core unrolled primal dual reconstruction computation pathway."},{"name":"Dual 更新","desc":"f_{k+1}=Gamma_{theta_k}(f_k,A(h_k),y)","name_en":"Dual update","desc_en":"Performs Dual update within the core unrolled primal dual reconstruction computation pathway."},{"name":"A*","desc":"把更新后的 dual 特征反投影回图像域","name_en":"A*","desc_en":"Performs A* within the core unrolled primal dual reconstruction computation pathway."},{"name":"Primal 更新","desc":"h_{k+1}=Lambda_{theta_k}(h_k,A*(f_{k+1}))","name_en":"Primal update","desc_en":"Performs Primal update within the core unrolled primal dual reconstruction computation pathway."},{"name":"K 级展开","desc":"每级显式经过 A、dual update、A*、primal update","name_en":"K unrolled","desc_en":"Applies K unrolled to project aggregated representations toward the target task head."},{"name":"x_hat","desc":"读取最终 primal 状态的图像通道","name_en":"x_hat","desc_en":"Produces reconstructed image x^{(k)} after k unrolled primal–dual iterations via x_hat."}],"design_principles":["把一阶 primal-dual 优化算法展开为固定深度网络，使每级更新都有明确的测量域和图像域角色。","A 与 A* 在每级中保持显式，网络学习的是更新规则，而不是重新学习成像几何。","多通道 primal/dual memory 比单一图像迭代能携带更丰富的历史状态，但也增加显存。"],"design_principles_en":["Core Hypothesis: Replace both the dual proximal operator in measurement space and the primal proximal operator in image space with small multi-channel residual CNNs across K≈10 stages.","Architectural Delta: Explicitly embeds forward operator A and adjoint A* inside every unrolled layer with multi-channel memory states in both primal and dual spaces.","Mathematical Formalism: Coupled Primal (Image) & Dual (Sinogram) Learned Proximal Updates Calling A and A*."],"med_apps":["在 CT 等线性投影系统中，可直接把校准后的 projector/backprojector 嵌入训练和推理。","算子失配、散射或运动会让所谓数据一致性对错误物理一致；3D 展开还受 projector 计算和显存限制。"],"med_apps_en":["Clinical Translation: Established the gold-standard paradigm for physics-informed unrolled CT and tomographic reconstruction.","Evidence & Safety Boundary: Strong measurement-consistent baseline; requires storing K stages of 2D/3D activations during backpropagation and accurate projector calibration."],"attrs":{"上一代瓶颈":"仅在图像域学习 proximal 难利用 sinogram/k-space 结构","核心想法":"在展开迭代中同时学习 measurement-domain dual 与 image-domain primal 更新","关键改进":"每个 stage 显式调用 A 与 A*，保留 measurement residual","医学适配":"在 CT 上建立网络作为可解释优化算法的范式","适用范围与证据":"仍值得复现；3D projector、operator mismatch 与内存是限制"},"attrs_en":{"上一代瓶颈":"Image-domain post-processing discards sinogram residuals, while hand-crafted TV primal–dual algorithms require ratusan iterations and produce patchy cartoons.","核心想法":"Replace both the dual proximal operator in measurement space and the primal proximal operator in image space with small multi-channel residual CNNs across K≈10 stages.","关键改进":"Explicitly embeds forward operator A and adjoint A* inside every unrolled layer with multi-channel memory states in both primal and dual spaces.","医学适配":"Established the gold-standard paradigm for physics-informed unrolled CT and tomographic reconstruction.","适用范围与证据":"Strong measurement-consistent baseline; requires storing K stages of 2D/3D activations during backpropagation and accurate projector calibration."},"paper_title":"Learned Primal-Dual Reconstruction","paper_url":"https://arxiv.org/abs/1707.06474","code_label":"作者/机构官方实现","code_url":"https://github.com/adler-j/learned_primal_dual","has_code":true,"image":"assets/98f0b4bc5845d159e8d6.avif"},{"id":"architecture_model_049_variational_network","num":49,"num_str":"049","year":2018,"year_str":"2018","venue":"Magnetic Resonance in Medicine","venue_group":"journal","era_group":"era2","title":"Variational Network","family_id":"models_inverse_reconstruction","family_code":"11","family_short":"物理约束医学重建","family_en":"Physics-Informed Recon","family_icon":"XI","family_label":"物理约束重建：从后处理到展开优化与测量一致性","archetype":"unrolled_variational_mri","archetype_en":"unrolled_variational_mri","accent":"#145E75","fig_badge":"Figure 1 · PDF p.7","fig_href":"https://pubmed.ncbi.nlm.nih.gov/29115689/","core_mech":"把多线圈 MRI 的变分梯度下降展开，并联合学习卷积滤波器、势函数与每级更新权重。","core_mech_en":"Unrolls K steps of gradient descent on a generalized Fields-of-Experts variational energy for multi-coil MRI, jointly learning convolutional filters, non-linear potentials, and data weights.","input_desc":"欠采样多线圈 k-space y、采样掩膜 P 与线圈灵敏度 S","input_en":"Undersampled multi-coil k-space data y, sampling mask P, and pre-estimated coil sensitivity maps S","output_desc":"K 次变分更新后的复数 MRI 图像 x_hat","output_en":"Complex-valued reconstructed MRI image x^{(K)} after K unrolled variational steps","form_title":"核心公式 · 学习正则梯度与多线圈数据梯度","form_title_en":"Core Formalism · Unrolled Variational Gradient Descent with Multi-Coil SENSE Forward Operator A and Adjoint A*","nodes":[{"name":"多线圈 y","desc":"PFSx 加噪后的欠采样 k-space","name_en":"multi-coil y","desc_en":"Ingests undersampled multi-coil k-space data y, sampling mask p, and pre-estimated coil sensitivity maps s and prepares initial tensor representations (multi-coil y)."},{"name":"A=PFS","desc":"灵敏度调制、傅里叶变换与采样掩膜","name_en":"A=PFS","desc_en":"Executes A=PFS to extract primary structural features and establish spatial/sequence encoding."},{"name":"A*=S*F*P*","desc":"零填充逆 FFT 后做线圈组合","name_en":"A*=S*F*P*","desc_en":"Performs A*=S*F*P* within the core unrolled variational mri computation pathway."},{"name":"图像 x_k","desc":"由 A*y 初始化并在复数图像域更新","name_en":"x_k","desc_en":"Performs x_k within the core unrolled variational mri computation pathway."},{"name":"数据梯度","desc":"A*(A x_k-y)，把采样点残差带回图像域","name_en":"Data Fidelity Gradient","desc_en":"Performs Data Fidelity Gradient within the core unrolled variational mri computation pathway."},{"name":"学习滤波器","desc":"K_i x_k 提取局部特征，K_i* 回传正则梯度","name_en":"Stage 06","desc_en":"Performs Stage 06 within the core unrolled variational mri computation pathway."},{"name":"势函数 phi","desc":"学习非线性 influence functions，替代手工正则项","name_en":"phi","desc_en":"Performs phi within the core unrolled variational mri computation pathway."},{"name":"变分更新","desc":"x_{k+1}=x_k-dcgrad-ΣK_i*phi_i(K_i x_k)","name_en":"Variational Update","desc_en":"Applies Variational Update to project aggregated representations toward the target task head."},{"name":"x_hat","desc":"K 个 stage 后的复数重建与幅度图","name_en":"x_hat","desc_en":"Produces complex-valued reconstructed mri image x^{(k)} after k unrolled variational steps via x_hat."}],"design_principles":["从变分目标的梯度下降推导每一级，而不是把重建当作无结构的图像到图像回归。","多线圈 forward model PFS 与伴随 S*F*P* 保证采样残差以正确几何进入更新。","滤波器和势函数由数据学习，替代固定的稀疏先验，同时保持有限级可解释展开。"],"design_principles_en":["Core Hypothesis: Unfold K=10 gradient descent steps of a variational energy combining learned convolutional filter-bank potentials with exact multi-coil k-space data consistency.","Architectural Delta: End-to-end training of stage-specific filter kernels, spline activation derivatives (potentials), and data-consistency step weights.","Mathematical Formalism: Unrolled Variational Gradient Descent with Multi-Coil SENSE Forward Operator A and Adjoint A*."],"med_apps":["适用于给定采样 mask 和可靠 coil maps 的加速多线圈 MRI，可把重建速度固定在 K 级前向。","序列、场强、厂商或灵敏度估计改变时，学习到的正则与数据项权重可能失配。"],"med_apps_en":["Clinical Translation: First unrolled MRI reconstruction architecture validated in clinical reader studies to achieve 4× accelerated knee MRI acquisition.","Evidence & Safety Boundary: Foundational clinical unrolled MRI milestone; shallow Fields-of-Experts regularizers were later deepened into U-Net cascades in E2E-VarNet."],"attrs":{"上一代瓶颈":"手工 regularizer 和 potential 表达能力有限","核心想法":"展开变分梯度下降，学习滤波器、势函数并显式使用多线圈 forward model","关键改进":"端到端学习每步 variational update 与数据项","医学适配":"在 accelerated MRI 中已有临床工作流速度和质量证据","适用范围与证据":"unrolled MRI 的核心祖型；序列与厂商迁移仍有限"},"attrs_en":{"上一代瓶颈":"Compressed-sensing MRI with fixed wavelet/TV regularizers reconstructed slowly and introduced staircasing or over-smoothing.","核心想法":"Unfold K=10 gradient descent steps of a variational energy combining learned convolutional filter-bank potentials with exact multi-coil k-space data consistency.","关键改进":"End-to-end training of stage-specific filter kernels, spline activation derivatives (potentials), and data-consistency step weights.","医学适配":"First unrolled MRI reconstruction architecture validated in clinical reader studies to achieve 4× accelerated knee MRI acquisition.","适用范围与证据":"Foundational clinical unrolled MRI milestone; shallow Fields-of-Experts regularizers were later deepened into U-Net cascades in E2E-VarNet."},"paper_title":"Learning a Variational Network for Reconstruction of Accelerated MRI Data","paper_url":"https://pubmed.ncbi.nlm.nih.gov/29115689/","code_label":"作者/机构官方实现","code_url":"https://github.com/VLOGroup/mri-variationalnetwork","has_code":true,"image":"assets/2aa3b9297a3d0de20177.avif"},{"id":"architecture_model_050_modl","num":50,"num_str":"050","year":2019,"year_str":"2019","venue":"IEEE Transactions on Medical Imaging","venue_group":"journal","era_group":"era2","title":"MoDL","family_id":"models_inverse_reconstruction","family_code":"11","family_short":"物理约束医学重建","family_en":"Physics-Informed Recon","family_icon":"XI","family_label":"物理约束重建：从后处理到展开优化与测量一致性","archetype":"unrolled_denoiser_cg_reconstruction","archetype_en":"unrolled_denoiser_cg_reconstruction","accent":"#145E75","fig_badge":"Figure 1 · PDF p.3","fig_href":"https://pubmed.ncbi.nlm.nih.gov/30106719/","core_mech":"共享 CNN prior 与可微共轭梯度 data-consistency 子问题交替展开。","core_mech_en":"Alternates a weight-shared multi-layer CNN denoiser prior D_θ with a differentiable numerical Conjugate Gradient (CG) solver enforcing exact data consistency (A*A + λI)^{-1}.","input_desc":"测量 y、已知前向算子 A 与伴随 A*","input_en":"Undersampled multi-coil k-space measurements b, forward operator A (incorporating coil maps + FFT + mask), and adjoint A*","output_desc":"K 次共享权重迭代后的重建 x_hat","output_en":"Reconstructed MRI image x_K after K weight-shared alternating minimization stages","form_title":"核心公式 · 共享去噪先验与 CG 数据一致性方程","form_title_en":"Core Formalism · Weight-Shared CNN Denoiser Coupled with Unrolled Conjugate Gradient Data-Consistency Sub-Problem","nodes":[{"name":"测量 y","desc":"MRI k-space 或其他线性成像测量","name_en":"Stage 01","desc_en":"Ingests undersampled multi-coil k-space measurements b, forward operator a (incorporating coil maps + fft + mask), and adjoint a* and prepares initial tensor representations (Stage 01)."},{"name":"A / A*","desc":"成像 forward/adjoint；构成 A*A 与 A*y","name_en":"A / A*","desc_en":"Executes A / A* to extract primary structural features and establish spatial/sequence encoding."},{"name":"状态 x_k","desc":"A*y 初始化的当前图像","name_en":"x_k","desc_en":"Performs x_k within the core unrolled denoiser cg reconstruction computation pathway."},{"name":"共享 CNN","desc":"D_theta(x_k) 在各级复用同一组卷积参数","name_en":"CNN","desc_en":"Performs CNN within the core unrolled denoiser cg reconstruction computation pathway."},{"name":"先验变量 z_k","desc":"CNN 给出的去伪影/去噪候选","name_en":"prior z_k","desc_en":"Performs prior z_k within the core unrolled denoiser cg reconstruction computation pathway."},{"name":"CG 数据一致性","desc":"近似求解 (A*A+lambda I)x=A*y+lambda z_k","name_en":"CG data consistency","desc_en":"Performs CG data consistency within the core unrolled denoiser cg reconstruction computation pathway."},{"name":"权重共享","desc":"D_theta 和 lambda 跨 unrolled iterations 共享","name_en":"Stage 07","desc_en":"Performs Stage 07 within the core unrolled denoiser cg reconstruction computation pathway."},{"name":"K 次展开","desc":"CNN prior 与 CG/DC 子问题交替","name_en":"K unrolled","desc_en":"Applies K unrolled to project aggregated representations toward the target task head."},{"name":"x_hat","desc":"最后一次 CG 解","name_en":"x_hat","desc_en":"Produces reconstructed mri image x_k after k weight-shared alternating minimization stages via x_hat."}],"design_principles":["将 learned denoiser 视为模型先验，并用显式线性子问题恢复测量一致性。","CG 只需要 A 和 A* 的矩阵—向量乘，无需显式存储 A*A。","跨迭代共享 CNN 参数显著缩小模型，但把各级先验更新约束为同一映射。"],"design_principles_en":["Core Hypothesis: Share a single CNN denoiser across all K unrolled stages to reduce parameters, and solve the quadratic data-consistency sub-problem accurately via internal CG iterations.","Architectural Delta: Weight-shared plug-and-play regularizer + backpropagation through numerical Conjugate Gradient steps handling arbitrary linear operators A.","Mathematical Formalism: Weight-Shared CNN Denoiser Coupled with Unrolled Conjugate Gradient Data-Consistency Sub-Problem."],"med_apps":["适用于多线圈 MRI、CT 等可准确实现 A/A* 的线性逆问题，是 model-based deep learning 的强基线。","线圈图、几何或噪声模型错误会进入每次 CG；K 与每级 CG 步数共同决定延迟。"],"med_apps_en":["Clinical Translation: Core infrastructure baseline for multi-coil parallel MRI, dynamic cardiac MRI, and physics-based CT reconstruction.","Evidence & Safety Boundary: Mandatory unrolled baseline; depends on accurate coil sensitivity maps and incurs inner-loop CG compute cost."],"attrs":{"上一代瓶颈":"各展开 stage 独立参数导致模型大且数据需求高","核心想法":"共享 CNN denoiser，并用有限次共轭梯度近似求解每步 data-consistency 子问题","关键改进":"跨迭代共享 learned prior，加 A* A 线性系统的 CG 更新","医学适配":"成为多线圈 MRI 和 CT model-based deep learning 强基线","适用范围与证据":"基础设施级方法；依赖 operator/coil maps 且迭代计算较重"},"attrs_en":{"上一代瓶颈":"Gradient-step unrolled networks converged slowly for complex multi-coil forward operators A whose normal operator A*A is not diagonally invertible.","核心想法":"Share a single CNN denoiser across all K unrolled stages to reduce parameters, and solve the quadratic data-consistency sub-problem accurately via internal CG iterations.","关键改进":"Weight-shared plug-and-play regularizer + backpropagation through numerical Conjugate Gradient steps handling arbitrary linear operators A.","医学适配":"Core infrastructure baseline for multi-coil parallel MRI, dynamic cardiac MRI, and physics-based CT reconstruction.","适用范围与证据":"Mandatory unrolled baseline; depends on accurate coil sensitivity maps and incurs inner-loop CG compute cost."},"paper_title":"MoDL: Model-Based Deep Learning Architecture for Inverse Problems","paper_url":"https://pubmed.ncbi.nlm.nih.gov/30106719/","code_label":"作者/机构官方实现","code_url":"https://github.com/hkaggarwal/modl","has_code":true,"image":"assets/97f6fa72832c943d8fef.avif"},{"id":"architecture_model_051_varnet","num":51,"num_str":"051","year":2020,"year_str":"2020","venue":"MICCAI","venue_group":"miccai","era_group":"era3","title":"VarNet","family_id":"models_inverse_reconstruction","family_code":"11","family_short":"物理约束医学重建","family_en":"Physics-Informed Recon","family_icon":"XI","family_label":"物理约束重建：从后处理到展开优化与测量一致性","archetype":"cascaded_kspace_variational_network","archetype_en":"cascaded_kspace_variational_network","accent":"#145E75","fig_badge":"Figure 1 · PDF p.4","fig_href":"https://arxiv.org/abs/2004.06688","core_mech":"灵敏度估计网络加多级 k-space variational cascades，将图像正则与采样点 DC 工程化为统一流程。","core_mech_en":"End-to-End Variational Network combining a joint U-Net coil sensitivity estimation module (SME) with K k-space variational cascades using U-Net image regularizers.","input_desc":"欠采样多线圈 k-space y 与采样掩膜 M","input_en":"Raw undersampled multi-coil k-space y and Cartesian undersampling mask M (including auto-calibration lines)","output_desc":"灵敏度组合后的 MRI 幅度图 x_hat","output_en":"Root-sum-of-squares or coil-combined MRI magnitude image x̂","form_title":"核心公式 · k-space 软数据一致性级联更新","form_title_en":"Core Formalism · End-to-End Sensitivity Map Estimation + k-Space Variational Cascades","nodes":[{"name":"多线圈 k-space","desc":"原始欠采样 y，采样位置由 M 标记","name_en":"Multi-Coil k-Space","desc_en":"Ingests raw undersampled multi-coil k-space y and cartesian undersampling mask m (including auto-calibration lines) and prepares initial tensor representations (Multi-Coil k-Space)."},{"name":"灵敏度网络","desc":"从中心 k-space 估计并归一化 coil sensitivity maps S","name_en":"Sensitivity Map Network","desc_en":"Executes Sensitivity Map Network to extract primary structural features and establish spatial/sequence encoding."},{"name":"A / A*","desc":"A=PFS；A* 逆 FFT 后按 S* 做 sensitivity reduction","name_en":"A / A*","desc_en":"Performs A / A* within the core cascaded kspace variational network computation pathway."},{"name":"k-space 状态","desc":"每个 cascade 维护完整多线圈频域估计 k_t","name_en":"k-space","desc_en":"Performs k-space within the core cascaded kspace variational network computation pathway."},{"name":"图像正则器","desc":"A* 折叠到图像域，经 U-Net 后由 A 展回多线圈 k-space","name_en":"regularization","desc_en":"Performs regularization within the core cascaded kspace variational network computation pathway."},{"name":"采样点 DC","desc":"M(k_t-y) 的软数据一致性更新","name_en":"Sampled k-Space DC","desc_en":"Performs Sampled k-Space DC within the core cascaded kspace variational network computation pathway."},{"name":"K 级展开迭代","desc":"每级执行 k_{t+1}=k_t-eta_t M(k_t-y)-A R_t(A* k_t)，构成固定深度 variational cascade","name_en":"K unrolled iterative","desc_en":"Applies K unrolled iterative to project aggregated representations toward the target task head."},{"name":"RSS 图像","desc":"最终 k-space 逆 FFT 后做 root-sum-of-squares","name_en":"RSS","desc_en":"Produces root-sum-of-squares or coil-combined mri magnitude image x̂ via RSS."}],"design_principles":["把 coil sensitivity estimation、图像域正则器和 k-space 数据一致性纳入同一端到端级联。","每级在 A*/A 之间往返，使卷积先验工作在组合图像域，而残差在真实采样 k-space 上计算。","soft data consistency 允许网络学习采样点更新强度，并非简单硬替换。"],"design_principles_en":["Core Hypothesis: Estimate smooth coil sensitivity maps end-to-end from low-frequency ACS k-space via a dedicated U-Net, feeding directly into K k-space variational U-Net cascades.","Architectural Delta: Self-contained raw-k-space-to-image pipeline standardized on the public fastMRI multi-coil benchmark.","Mathematical Formalism: End-to-End Sensitivity Map Estimation + k-Space Variational Cascades."],"med_apps":["为 fastMRI 多线圈原始数据提供可复现的强基线，便于比较采样 mask 和加速因子。","公开 VarNet 的离线指标不能替代前瞻诊断验证；coil map、厂商与序列域移位仍需单独评估。"],"med_apps_en":["Clinical Translation: De facto public benchmark champion and baseline for accelerated multi-coil knee and brain MRI reconstruction.","Evidence & Safety Boundary: Proven long-term value; high GPU memory during unrolled training and sensitivity to out-of-distribution k-space sampling patterns remain key considerations."],"attrs":{"上一代瓶颈":"多线圈 benchmark、coil handling 和训练流程碎片化","核心想法":"多级 learned regularizer 与 k-space data consistency 交替，并估计 coil sensitivity maps","关键改进":"把 variational cascade 工程化到 fastMRI 原始 k-space 标准评测","医学适配":"形成公开 MRI 重建基线；同类变分/展开式 AI reconstruction 另有前瞻膝 MRI 诊断等效证据","适用范围与证据":"长期价值已证明；前瞻证据不等同于公开 VarNet 本身，且显存、采样 mask 和厂商域移位仍需验证"},"attrs_en":{"上一代瓶颈":"Prior unrolled MRI methods depended on external offline ESPIRiT coil maps that broke down under narrow calibration regions or motion.","核心想法":"Estimate smooth coil sensitivity maps end-to-end from low-frequency ACS k-space via a dedicated U-Net, feeding directly into K k-space variational U-Net cascades.","关键改进":"Self-contained raw-k-space-to-image pipeline standardized on the public fastMRI multi-coil benchmark.","医学适配":"De facto public benchmark champion and baseline for accelerated multi-coil knee and brain MRI reconstruction.","适用范围与证据":"Proven long-term value; high GPU memory during unrolled training and sensitivity to out-of-distribution k-space sampling patterns remain key considerations."},"paper_title":"End-to-End Variational Networks for Accelerated MRI Reconstruction","paper_url":"https://arxiv.org/abs/2004.06688","code_label":"作者/机构官方实现","code_url":"https://github.com/facebookresearch/fastMRI/tree/main/fastmri_examples/varnet","has_code":true,"image":"assets/db3c4e3c341eb3302e40.avif"},{"id":"architecture_model_052_dncnn","num":52,"num_str":"052","year":2017,"year_str":"2017","venue":"IEEE Transactions on Image Processing","venue_group":"journal","era_group":"era2","title":"DnCNN","family_id":"models_denoising_restoration","family_code":"12","family_short":"去噪与图像恢复","family_en":"Denoising & Restoration","family_icon":"XII","family_label":"去噪与图像恢复：残差、盲点与长程建模的假设边界","archetype":"residual_noise_cnn","archetype_en":"residual_noise_cnn","accent":"#145E75","fig_badge":"Figure 1 · PDF p.4","fig_href":"https://pubmed.ncbi.nlm.nih.gov/28166495/","core_mech":"深 CNN 回归噪声残差，再与输入显式相减，而非直接回归 clean image。","core_mech_en":"Trains a deep plain CNN with BatchNorm and ReLU to regress the additive noise residual R_θ(y) ≈ n rather than the clean image, recovering x̂ = y − R_θ(y).","input_desc":"含噪图像 y=x+n","input_en":"Noisy observation y = x + n","output_desc":"去噪图像 x_hat=y-R_theta(y)","output_en":"Denoised image estimate x̂ = y − R_θ(y)","form_title":"核心公式 · 噪声残差回归与输入相减","form_title_en":"Core Formalism · Residual Noise Regression x̂ = y − R_θ(y) Preserving the Clean Identity Signal","nodes":[{"name":"含噪图像","desc":"原论文主要建模加性白高斯噪声","name_en":"Noisy Input Image","desc_en":"Ingests noisy observation y = x + n and prepares initial tensor representations (Noisy Input Image)."},{"name":"Conv+ReLU","desc":"首层从 y 提取浅层局部噪声/纹理特征","name_en":"Conv+ReLU","desc_en":"Executes Conv+ReLU to extract primary structural features and establish spatial/sequence encoding."},{"name":"深卷积栈","desc":"多层 3×3 Conv+BN+ReLU 扩大感受野","name_en":"convolution","desc_en":"Performs convolution within the core residual noise cnn computation pathway."},{"name":"线性 Conv","desc":"末层回归与图像同尺寸的噪声残差","name_en":"Conv","desc_en":"Performs Conv within the core residual noise cnn computation pathway."},{"name":"n_hat","desc":"R_theta(y) 逼近噪声而非直接复制干净图像","name_en":"n_hat","desc_en":"Performs n_hat within the core residual noise cnn computation pathway."},{"name":"残差相减","desc":"x_hat=y-n_hat，保留显式 identity path","name_en":"Residual Subtraction","desc_en":"Applies Residual Subtraction to project aggregated representations toward the target task head."},{"name":"x_hat","desc":"恢复后的图像","name_en":"x_hat","desc_en":"Produces denoised image estimate x̂ = y − r_θ(y) via x_hat."}],"design_principles":["残差学习让网络集中预测相对稀疏、幅度较小的噪声分量，而输入沿 identity path 保留。","连续 3×3 卷积在不下采样时逐层扩大感受野，保持逐像素输出。","BatchNorm 与固定噪声训练在 AWGN 上有效，但真实医学噪声常具强度依赖和空间相关性。"],"design_principles_en":["Core Hypothesis: Predict only the zero-mean noise residual R_θ(y) so the target mapping is much closer to zero than to the identity image.","Architectural Delta: Synergy between residual noise learning and batch normalization, supporting single-model blind Gaussian denoising across noise levels.","Mathematical Formalism: Residual Noise Regression x̂ = y − R_θ(y) Preserving the Clean Identity Signal."],"med_apps":["可作为低剂量 CT、PET、X-ray 或 MRI 图像域去噪的透明基线。","若未建模 Poisson、Rician、重建纹理或病灶稀有性，残差网络可能把低对比病灶当作噪声。"],"med_apps_en":["Clinical Translation: Universal lightweight baseline for low-dose CT, planar X-ray, ultrasound, and MRI image-space denoising.","Evidence & Safety Boundary: Foundational restoration baseline; i.i.d. AWGN assumptions fail on spatially correlated CT sinogram streaks or Poisson PET noise without domain adaptation."],"attrs":{"上一代瓶颈":"直接回归 clean image 还需复制大部分解剖信号","核心想法":"预测噪声残差 r(y)，以 xhat=y-r(y) 保留 identity path","关键改进":"深残差噪声学习和可扩展的 noise-level 训练","医学适配":"广泛作为低剂量 CT、PET、X-ray 和 MRI 去噪基线","适用范围与证据":"基础设施级 baseline；原版 AWGN 与 BatchNorm 假设不匹配真实医学噪声"},"attrs_en":{"上一代瓶颈":"Directly mapping a noisy image to a clean image forced deep networks to re-synthesize all low-frequency anatomical structures.","核心想法":"Predict only the zero-mean noise residual R_θ(y) so the target mapping is much closer to zero than to the identity image.","关键改进":"Synergy between residual noise learning and batch normalization, supporting single-model blind Gaussian denoising across noise levels.","医学适配":"Universal lightweight baseline for low-dose CT, planar X-ray, ultrasound, and MRI image-space denoising.","适用范围与证据":"Foundational restoration baseline; i.i.d. AWGN assumptions fail on spatially correlated CT sinogram streaks or Poisson PET noise without domain adaptation."},"paper_title":"Beyond a Gaussian Denoiser: Residual Learning of Deep CNN for Image Denoising","paper_url":"https://pubmed.ncbi.nlm.nih.gov/28166495/","code_label":"作者/机构官方实现","code_url":"https://github.com/cszn/DnCNN","has_code":true,"image":"assets/f921bf2e7a1d26a9b448.avif"},{"id":"architecture_model_053_noise2noise","num":53,"num_str":"053","year":2018,"year_str":"2018","venue":"ICML","venue_group":"ml","era_group":"era2","title":"Noise2Noise","family_id":"models_denoising_restoration","family_code":"12","family_short":"去噪与图像恢复","family_en":"Denoising & Restoration","family_icon":"XII","family_label":"去噪与图像恢复：残差、盲点与长程建模的假设边界","archetype":"paired_noisy_self_supervision","archetype_en":"paired_noisy_self_supervision","accent":"#145E75","fig_badge":"Official repository network.py, lines 59–114 · PDF p.Repository source lines 59–114","fig_href":"https://github.com/NVlabs/noise2noise/blob/7355519e7bfc49e0606cca8867748e736431244b/network.py#L59-L114","core_mech":"使用同一信号的两次独立无偏噪声实现进行 noisy-to-noisy 监督，训练阶段不需要干净靶图。","core_mech_en":"Trains a denoising network using pairs of independent noisy realizations (y_1, y_2) of the same underlying anatomy without ever observing clean ground truth.","input_desc":"同一潜在图像 x 的两次独立含噪观测 y1、y2","input_en":"Two independent noisy observations (y_1, y_2) of the exact same underlying clean signal x","output_desc":"以单次含噪观测为输入的条件均值估计 x_hat","output_en":"Clean conditional expectation estimate x̂ = f_θ(y_1)","form_title":"核心公式 · 无偏独立噪声对的监督等价目标","form_title_en":"Core Formalism · Equivalence of Expected L2 Risk Under Independent Zero-Mean Noisy Targets E[y_2|x] = x","nodes":[{"name":"潜在图像 x","desc":"训练时不可见；两次采集共享同一真实信号","name_en":"Stage 01","desc_en":"Ingests two independent noisy observations (y_1, y_2) of the exact same underlying clean signal x and prepares initial tensor representations (Stage 01)."},{"name":"噪声 n1","desc":"与 n2 条件独立且 E[n1|x]=0","name_en":"noise n1","desc_en":"Executes noise n1 to extract primary structural features and establish spatial/sequence encoding."},{"name":"噪声 n2","desc":"独立、条件无偏的第二次噪声实现","name_en":"noise n2","desc_en":"Performs noise n2 within the core paired noisy self supervision computation pathway."},{"name":"输入 y1","desc":"y1=x+n1","name_en":"input y1","desc_en":"Performs input y1 within the core paired noisy self supervision computation pathway."},{"name":"恢复网络","desc":"f_theta(y1)，架构可为 U-Net/CNN","name_en":"Stage 05","desc_en":"Performs Stage 05 within the core paired noisy self supervision computation pathway."},{"name":"目标 y2","desc":"y2=x+n2，不要求 clean target","name_en":"objective y2","desc_en":"Performs objective y2 within the core paired noisy self supervision computation pathway."},{"name":"N2N 损失","desc":"最小化 ||f_theta(y1)-y2||^2；总体最优为条件均值","name_en":"N2N loss","desc_en":"Applies N2N loss to project aggregated representations toward the target task head."},{"name":"x_hat","desc":"推理时只需一个 noisy input","name_en":"x_hat","desc_en":"Produces clean conditional expectation estimate x̂ = f_θ(y_1) via x_hat."}],"design_principles":["在平方损失下，只要目标噪声条件无偏，noisy target 与 clean target 具有相同的总体最优预测。","两个观测必须对应同一潜在信号；独立性是去除目标噪声而不学习它的关键。","Noise2Noise 改变监督数据契约，而不是规定某一种网络主干。"],"design_principles_en":["Core Hypothesis: Exploit the statistical property that replacing a clean L2 regression target x with an independent zero-mean noisy target y_2 leaves the optimal Bayes estimator unchanged.","Architectural Delta: Eliminates the need for clean training targets whenever two independent noisy measurements of static anatomy can be acquired or split.","Mathematical Formalism: Equivalence of Expected L2 Risk Under Independent Zero-Mean Noisy Targets E[y_2|x] = x."],"med_apps":["可从 PET list-mode 计数拆分、MRI 重复采样或多次低剂量采集构造训练对。","患者运动、生理变化、造影剂/摄取变化会破坏同一潜在 x 假设，导致解剖或病灶偏差。"],"med_apps_en":["Clinical Translation: Directly applicable to splitting list-mode PET counts, multi-NEX MRI averages, dose-split CT projections, and cryo-EM / fluorescence microscopy.","Evidence & Safety Boundary: Enduring mathematical principle; breaks down if inter-scan patient motion occurs or if noise realizations share correlated bias."],"attrs":{"上一代瓶颈":"clean target 昂贵或无法采集","核心想法":"用同一潜在图像的两次独立、条件无偏 noisy observations 进行监督","关键改进":"证明 noisy-to-noisy MSE 与 clean-target MSE 具有相同最优条件均值","医学适配":"可用于拆分 PET counts、MRI k-space 或可重复低剂量测量","适用范围与证据":"长期有用；独立性、运动和 uptake mismatch 会造成目标偏差"},"attrs_en":{"上一代瓶颈":"Acquiring noiseless ground-truth scans (e.g., high-dose CT or long-exposure microscopy) is often clinically unethical or physically impossible.","核心想法":"Exploit the statistical property that replacing a clean L2 regression target x with an independent zero-mean noisy target y_2 leaves the optimal Bayes estimator unchanged.","关键改进":"Eliminates the need for clean training targets whenever two independent noisy measurements of static anatomy can be acquired or split.","医学适配":"Directly applicable to splitting list-mode PET counts, multi-NEX MRI averages, dose-split CT projections, and cryo-EM / fluorescence microscopy.","适用范围与证据":"Enduring mathematical principle; breaks down if inter-scan patient motion occurs or if noise realizations share correlated bias."},"paper_title":"Noise2Noise: Learning Image Restoration without Clean Data","paper_url":"https://arxiv.org/abs/1803.04189","code_label":"作者/机构官方实现","code_url":"https://github.com/NVlabs/noise2noise","has_code":true,"image":"assets/5a7ab8e40084ca78ccfb.avif"},{"id":"architecture_model_054_noise2self","num":54,"num_str":"054","year":2019,"year_str":"2019","venue":"ICML","venue_group":"ml","era_group":"era2","title":"Noise2Self","family_id":"models_denoising_restoration","family_code":"12","family_short":"去噪与图像恢复","family_en":"Denoising & Restoration","family_icon":"XII","family_label":"去噪与图像恢复：残差、盲点与长程建模的假设边界","archetype":"single_image_j_invariant_denoising","archetype_en":"single_image_j_invariant_denoising","accent":"#145E75","fig_badge":"Figure 1 · PDF p.2","fig_href":"https://proceedings.mlr.press/v97/batson19a.html","core_mech":"通过 J-invariant 遮挡使单幅 noisy image 同时提供输入与 held-out 监督目标。","core_mech_en":"Formalizes single-image self-supervised denoising via J-invariant functions whose prediction for pixel subset J does not depend on the observed noisy values in J.","input_desc":"单幅含噪图像 y","input_en":"Single noisy image y (no paired second scan and no clean ground truth)","output_desc":"由多次 J-invariant 预测聚合的去噪图像 x_hat","output_en":"Denoised image x̂ predicted from J-invariant masked neighborhoods","form_title":"核心公式 · J-invariant 单图像自监督风险","form_title_en":"Core Formalism · J-Invariant Self-Supervised Loss Equating Noisy Hold-Out Error to Clean Expected Risk","nodes":[{"name":"单幅 y","desc":"唯一含噪观测，不需要配对或 clean target","name_en":"Stage 01","desc_en":"Ingests single noisy image y (no paired second scan and no clean ground truth) and prepares initial tensor representations (Stage 01)."},{"name":"索引分组 J","desc":"把像素/体素索引划分为若干 held-out 子集","name_en":"Stage 02","desc_en":"Executes Stage 02 to extract primary structural features and establish spatial/sequence encoding."},{"name":"遮挡 J","desc":"预测 J 时替换或移除 y_J，阻止信息泄漏","name_en":"masked J","desc_en":"Performs masked J within the core single image j invariant denoising computation pathway."},{"name":"J-invariant 网络","desc":"f_theta(y) 在 J 上只能读取补集 J^c","name_en":"J-invariant","desc_en":"Performs J-invariant within the core single image j invariant denoising computation pathway."},{"name":"held-out 预测","desc":"从邻域上下文预测被遮挡位置","name_en":"held-out prediction","desc_en":"Performs held-out prediction within the core single image j invariant denoising computation pathway."},{"name":"自监督风险","desc":"仅在 J 上比较预测与原始 noisy y_J","name_en":"self-supervised","desc_en":"Performs self-supervised within the core single image j invariant denoising computation pathway."},{"name":"分组聚合","desc":"轮换所有 J 并拼回完整预测","name_en":"Grouped Aggregation","desc_en":"Applies Grouped Aggregation to project aggregated representations toward the target task head."},{"name":"x_hat","desc":"单图像自监督去噪结果","name_en":"x_hat","desc_en":"Produces denoised image x̂ predicted from j-invariant masked neighborhoods via x_hat."}],"design_principles":["J-invariance 禁止网络用某位置的噪声直接复制该位置，迫使其利用其他位置的信号相关性。","当各位置噪声条件独立且零均值时，held-out noisy risk 可无偏估计监督风险。","方法依赖数据冗余；孤立的小结构若无法由邻域预测，可能被平滑掉。"],"design_principles_en":["Core Hypothesis: Partition pixels into subsets J and train a J-invariant network to predict pixels in J strictly from their complement J^c under pixel-wise independent noise.","Architectural Delta: Provides the rigorous statistical proof and optimal combination theorem for blind-spot single-image self-supervised denoising.","Mathematical Formalism: J-Invariant Self-Supervised Loss Equating Noisy Hold-Out Error to Clean Expected Risk."],"med_apps":["适合无法获得重复采集或 clean target 的显微、PET、MRI 等场景。","重建引入的空间相关噪声、条纹和各向异性会破坏条件独立假设，应按噪声相关长度设计 J。"],"med_apps_en":["Clinical Translation: Used in single-shot fluorescence microscopy, low-count nuclear medicine, and unrepeatable dynamic medical acquisitions.","Evidence & Safety Boundary: Theoretical cornerstone of blind-spot denoising; fails when noise is spatially correlated (e.g., FBP CT streaks) and can erase isolated 1-pixel micro-structures."],"attrs":{"上一代瓶颈":"Noise2Noise 仍需同一解剖的第二个独立观测","核心想法":"以 J-invariance 让预测某像素集合时不能读取该集合输入","关键改进":"在条件独立零均值噪声下将单幅 noisy image 变成自监督风险","医学适配":"可用于显微、PET、MRI 等无 clean target 场景","适用范围与证据":"方法基础重要；空间相关噪声和孤立病灶可能被错误去除"},"attrs_en":{"上一代瓶颈":"Noise2Noise still required two independent co-registered noisy acquisitions of the same patient or specimen.","核心想法":"Partition pixels into subsets J and train a J-invariant network to predict pixels in J strictly from their complement J^c under pixel-wise independent noise.","关键改进":"Provides the rigorous statistical proof and optimal combination theorem for blind-spot single-image self-supervised denoising.","医学适配":"Used in single-shot fluorescence microscopy, low-count nuclear medicine, and unrepeatable dynamic medical acquisitions.","适用范围与证据":"Theoretical cornerstone of blind-spot denoising; fails when noise is spatially correlated (e.g., FBP CT streaks) and can erase isolated 1-pixel micro-structures."},"paper_title":"Noise2Self: Blind Denoising by Self-Supervision","paper_url":"https://proceedings.mlr.press/v97/batson19a.html","code_label":"作者/机构官方实现","code_url":"https://github.com/czbiohub-sf/noise2self","has_code":true,"image":"assets/55e5f4c88594f7d9bf5d.avif"},{"id":"architecture_model_055_ddpm","num":55,"num_str":"055","year":2020,"year_str":"2020","venue":"NeurIPS","venue_group":"ml","era_group":"era3","title":"DDPM","family_id":"models_generative","family_code":"10","family_short":"生成、扩散与流匹配","family_en":"Generative, Diffusion & Flow","family_icon":"X","family_label":"生成模型：从潜变量与对抗学习到 diffusion、flow 与 consistency","archetype":"discrete_diffusion","archetype_en":"discrete_diffusion","accent":"#6B5700","fig_badge":"Figure 2 · PDF p.2","fig_href":"https://papers.neurips.cc/paper_files/paper/2020/hash/4c5bcfec8584af0d967f1ab10179ca4b-Abstract.html","core_mech":"预设离散高斯前向链，加训练稳定的 epsilon/score 网络，再按学习到的随机逆链逐步采样。","core_mech_en":"Defines a fixed discrete Markov Gaussian forward noising chain and trains a noise-prediction U-Net (ε_θ) across all noise scales for iterative reverse sampling.","input_desc":"训练时的干净样本 x0；生成时的高斯噪声 xT","input_en":"Clean training image x_0 (during training); pure Gaussian noise x_T ~ N(0,I) (during sampling)","output_desc":"经 T 步随机逆扩散得到的样本 x0_hat","output_en":"Sample x̂_0 synthesized via T iterative stochastic reverse denoising steps","form_title":"核心公式 · DDPM 闭式加噪与 epsilon 预测目标","form_title_en":"Core Formalism · Closed-Form Forward Gaussian Marginals & Noise-Prediction Variational Bound Simplification","nodes":[{"name":"数据 x0","desc":"训练分布中的干净图像","name_en":"x0","desc_en":"Ingests clean training image x_0 (during training); pure gaussian noise x_t ~ n(0,i) (during sampling) and prepares initial tensor representations (x0)."},{"name":"前向 q","desc":"q(x_t|x_{t-1}) 逐步加入预设方差的高斯噪声","name_en":"Stage 02","desc_en":"Executes Stage 02 to extract primary structural features and establish spatial/sequence encoding."},{"name":"噪声 epsilon","desc":"重参数化 x_t=sqrt(alpha_bar_t)x0+sqrt(1-alpha_bar_t)epsilon","name_en":"noise epsilon","desc_en":"Performs noise epsilon within the core discrete diffusion computation pathway."},{"name":"噪声状态 x_t","desc":"t 越大越接近标准高斯，x_T 作为生成起点","name_en":"noise x_t","desc_en":"Performs noise x_t within the core discrete diffusion computation pathway."},{"name":"时间 t","desc":"正弦/学习嵌入条件化去噪网络","name_en":"Stage 05","desc_en":"Performs Stage 05 within the core discrete diffusion computation pathway."},{"name":"epsilon / score","desc":"网络预测 epsilon_theta；等价 score s_theta=-epsilon_theta/sigma_t","name_en":"epsilon / score","desc_en":"Performs epsilon / score within the core discrete diffusion computation pathway."},{"name":"逆转移 p_theta","desc":"由 epsilon_theta 参数化 p(x_{t-1}|x_t) 的均值并注入随机噪声","name_en":"p_theta","desc_en":"Performs p_theta within the core discrete diffusion computation pathway."},{"name":"T 步随机链","desc":"x_T→…→x_0，原始 DDPM 需要数百至千步","name_en":"Stage 08","desc_en":"Performs Stage 08 within the core discrete diffusion computation pathway."},{"name":"ODE 路径","desc":"原始 DDPM 不使用 ODE；后续可由对应 score 构造 probability-flow ODE","name_en":"ODE","desc_en":"Applies ODE to project aggregated representations toward the target task head."},{"name":"生成样本","desc":"最终 x0_hat","name_en":"Synthesized Sample","desc_en":"Produces sample x̂_0 synthesized via t iterative stochastic reverse denoising steps via Synthesized Sample."}],"design_principles":["固定前向高斯链把复杂数据分布平滑到简单噪声，学习任务被分解为多个噪声尺度的回归。","噪声预测与 score 估计只差已知尺度因子，因此可用于构造逆向生成动力学。","原始高质量来自细粒度随机逆链，代价是大量网络评估；ODE 不是原论文的主采样路径。"],"design_principles_en":["Core Hypothesis: Destroy data structure gradually via a fixed Gaussian diffusion process and learn the reverse Markov transition via stable multi-scale L2 noise regression.","Architectural Delta: Re-weighted ε-prediction objective + time-conditioned U-Net achieving stable optimization and high mode coverage.","Mathematical Formalism: Closed-Form Forward Gaussian Marginals & Noise-Prediction Variational Bound Simplification."],"med_apps":["是医学图像合成、重建先验、去噪和跨模态生成的基础，但部署延迟通常需要加速采样器。","生成质量不能证明患者级事实保真；罕见病灶、设备域移位和不确定性校准需独立验证。"],"med_apps_en":["Clinical Translation: Foundational prior for medical image synthesis, counterfactual generation, denoising, and diffusion-based inverse problem solvers.","Evidence & Safety Boundary: Core generative infrastructure; standard 1,000-step ancestral sampling is too slow for real-time clinical workflows without acceleration."],"attrs":{"上一代瓶颈":"GAN min-max 训练不稳、mode coverage 差，VAE 高频模糊","核心想法":"通过逐步高斯加噪并训练网络在各噪声尺度预测噪声来生成数据","关键改进":"稳定的多噪声尺度监督回归与可解释逆扩散链","医学适配":"成为医学重建、生成、去噪和跨模态 diffusion 的基础","适用范围与证据":"生成建模基础设施；原始数百至千步采样不适合常规部署"},"attrs_en":{"上一代瓶颈":"GANs suffered from adversarial instability and mode dropping, while likelihood-based flows and VAEs struggled with sample sharpness.","核心想法":"Destroy data structure gradually via a fixed Gaussian diffusion process and learn the reverse Markov transition via stable multi-scale L2 noise regression.","关键改进":"Re-weighted ε-prediction objective + time-conditioned U-Net achieving stable optimization and high mode coverage.","医学适配":"Foundational prior for medical image synthesis, counterfactual generation, denoising, and diffusion-based inverse problem solvers.","适用范围与证据":"Core generative infrastructure; standard 1,000-step ancestral sampling is too slow for real-time clinical workflows without acceleration."},"paper_title":"Denoising Diffusion Probabilistic Models","paper_url":"https://papers.neurips.cc/paper_files/paper/2020/hash/4c5bcfec8584af0d967f1ab10179ca4b-Abstract.html","code_label":"作者/机构官方实现","code_url":"https://github.com/hojonathanho/diffusion","has_code":true,"image":"assets/06139c7552ac4cb9d086.avif"},{"id":"architecture_model_056_ddim","num":56,"num_str":"056","year":2021,"year_str":"2021","venue":"ICLR","venue_group":"ml","era_group":"era3","title":"DDIM","family_id":"models_generative","family_code":"10","family_short":"生成、扩散与流匹配","family_en":"Generative, Diffusion & Flow","family_icon":"X","family_label":"生成模型：从潜变量与对抗学习到 diffusion、flow 与 consistency","archetype":"implicit_deterministic_diffusion","archetype_en":"implicit_deterministic_diffusion","accent":"#6B5700","fig_badge":"Figure 2 · PDF p.5","fig_href":"https://openreview.net/forum?id=St1giarCHLP","core_mech":"在相同 DDPM 训练边缘下采用隐式非 Markov、可确定性的跳步轨迹。","core_mech_en":"Constructs non-Markovian, deterministic reverse sampling trajectories that share the exact same marginal training distributions as DDPM.","input_desc":"与 DDPM 相同目标训练的 epsilon 网络和初始噪声 xT","input_en":"Pretrained DDPM noise-prediction network ε_θ and initial Gaussian noise x_T","output_desc":"少步确定性或可控随机性的生成样本 x0_hat","output_en":"Sample x̂_0 generated in 10–50 deterministic (or tunable-stochasticity) subsequence steps","form_title":"核心公式 · 确定性 DDIM 跳步更新","form_title_en":"Core Formalism · Deterministic Non-Markovian Subsequence Reverse Update Sharing DDPM Marginals","nodes":[{"name":"数据 x0","desc":"训练时的干净样本","name_en":"x0","desc_en":"Ingests pretrained ddpm noise-prediction network ε_θ and initial gaussian noise x_t and prepares initial tensor representations (x0)."},{"name":"训练加噪","desc":"沿 DDPM 边缘分布 q(x_t|x0) 采样，不改变训练目标","name_en":"training","desc_en":"Executes training to extract primary structural features and establish spatial/sequence encoding."},{"name":"噪声 epsilon","desc":"构造任意时间 t 的 x_t","name_en":"noise epsilon","desc_en":"Performs noise epsilon within the core implicit deterministic diffusion computation pathway."},{"name":"epsilon / score","desc":"复用 epsilon_theta(x_t,t)，可换算为 score","name_en":"epsilon / score","desc_en":"Performs epsilon / score within the core implicit deterministic diffusion computation pathway."},{"name":"x0 估计","desc":"由 x_t 与 epsilon_theta 解析估计 x0_hat","name_en":"x0","desc_en":"Performs x0 within the core implicit deterministic diffusion computation pathway."},{"name":"DDIM 更新","desc":"跳步计算 x_{t'}；eta=0 时无额外随机噪声","name_en":"DDIM update","desc_en":"Performs DDIM update within the core implicit deterministic diffusion computation pathway."},{"name":"非 Markov 路径","desc":"保持训练边缘分布但重定义生成联合路径","name_en":"Markov","desc_en":"Performs Markov within the core implicit deterministic diffusion computation pathway."},{"name":"ODE-like 极限","desc":"确定性轨迹对应连续极限的概率流视角","name_en":"ODE-like","desc_en":"Applies ODE-like to project aggregated representations toward the target task head."},{"name":"x0_hat","desc":"用选定时间子序列少步生成","name_en":"x0_hat","desc_en":"Produces sample x̂_0 generated in 10–50 deterministic (or tunable-stochasticity) subsequence steps via x0_hat."}],"design_principles":["DDIM 不改动 DDPM 的噪声预测训练，只在采样时选择不同的非 Markov 生成路径。","eta=0 时同一初始噪声产生确定性输出，便于反演、插值和可复现实验。","跨越更多时间步可显著减少 NFE，但离散误差首先影响高频边缘与细小结构。"],"design_principles_en":["Core Hypothesis: Reformulate the forward process as non-Markovian while preserving marginal distributions p(x_t|x_0), enabling exact reuse of pretrained DDPM weights with strided step schedules.","Architectural Delta: 10×–50× sampling acceleration without retraining + deterministic latent-to-image invertible mapping (DDIM inversion).","Mathematical Formalism: Deterministic Non-Markovian Subsequence Reverse Update Sharing DDPM Marginals."],"med_apps":["可直接加速既有医学 diffusion prior 的重建或生成，无需重新训练主网络。","少步设置必须用病灶级、定量强度和下游诊断指标验证，不能只看全局感知质量。"],"med_apps_en":["Clinical Translation: Standard sampler for accelerating medical diffusion reconstruction, counterfactual editing, and latent interpolation.","Evidence & Safety Boundary: Essential deployment accelerator; overly coarse step strides first degrade fine anatomical vessels and micro-calcifications."],"attrs":{"上一代瓶颈":"DDPM 需要大量逐步逆扩散","核心想法":"在相同训练目标下构造 non-Markov、可确定性采样轨迹","关键改进":"无需重训即可大幅减少 time steps，并支持 deterministic ODE-like sampling","医学适配":"用于加速医学 diffusion reconstruction 与生成实验","适用范围与证据":"部署研究必需；大步长离散误差会先损害细小结构"},"attrs_en":{"上一代瓶颈":"DDPM required hundreds to thousands of sequential network evaluations, making inference prohibitively slow.","核心想法":"Reformulate the forward process as non-Markovian while preserving marginal distributions p(x_t|x_0), enabling exact reuse of pretrained DDPM weights with strided step schedules.","关键改进":"10×–50× sampling acceleration without retraining + deterministic latent-to-image invertible mapping (DDIM inversion).","医学适配":"Standard sampler for accelerating medical diffusion reconstruction, counterfactual editing, and latent interpolation.","适用范围与证据":"Essential deployment accelerator; overly coarse step strides first degrade fine anatomical vessels and micro-calcifications."},"paper_title":"Denoising Diffusion Implicit Models","paper_url":"https://openreview.net/pdf?id=St1giarCHLP","code_label":"作者/机构官方实现","code_url":"https://github.com/ermongroup/ddim","has_code":true,"image":"assets/6339001402b3d8009b52.avif"},{"id":"architecture_model_057_score_sde","num":57,"num_str":"057","year":2021,"year_str":"2021","venue":"ICLR","venue_group":"ml","era_group":"era3","title":"Score-SDE","family_id":"models_generative","family_code":"10","family_short":"生成、扩散与流匹配","family_en":"Generative, Diffusion & Flow","family_icon":"X","family_label":"生成模型：从潜变量与对抗学习到 diffusion、flow 与 consistency","archetype":"continuous_score_sde","archetype_en":"continuous_score_sde","accent":"#6B5700","fig_badge":"Figure 2 · PDF p.4","fig_href":"https://openreview.net/forum?id=PxTIG12RRHS","core_mech":"以连续 score field 同时定义 reverse-time SDE、predictor-corrector sampler 与同边缘的 probability-flow ODE。","core_mech_en":"Unifies discrete diffusion and score matching into a continuous-time Stochastic Differential Equation (SDE) with a corresponding deterministic Probability-Flow ODE.","input_desc":"数据样本 x(0)；生成时的先验噪声 x(T)","input_en":"Continuous data sample x(0); prior noise distribution x(T) at terminal time T","output_desc":"经 reverse SDE 或 probability-flow ODE 得到的样本","output_en":"Samples generated via Predictor-Corrector reverse SDE or exact likelihoods via Probability-Flow ODE","form_title":"核心公式 · 同一 score 的反向 SDE 与概率流 ODE","form_title_en":"Core Formalism · Continuous-Time Forward/Reverse SDE & Marginal-Equivalent Probability-Flow ODE","nodes":[{"name":"数据 x(0)","desc":"未知数据分布 p0","name_en":"x(0","desc_en":"Ingests continuous data sample x(0); prior noise distribution x(t) at terminal time t and prepares initial tensor representations (x(0)."},{"name":"前向 SDE","desc":"dx=f(x,t)dt+g(t)dW，把 p0 连续扰动到简单先验","name_en":"SDE","desc_en":"Executes SDE to extract primary structural features and establish spatial/sequence encoding."},{"name":"先验 pT","desc":"终点通常接近高斯噪声","name_en":"prior pT","desc_en":"Performs prior pT within the core continuous score sde computation pathway."},{"name":"Score 网络","desc":"s_theta(x,t)≈∇_x log p_t(x)，用连续时间 denoising score matching 训练","name_en":"Score","desc_en":"Performs Score within the core continuous score sde computation pathway."},{"name":"Reverse SDE","desc":"漂移含 -g(t)^2 s_theta，并保留随机扩散项","name_en":"Reverse SDE","desc_en":"Performs Reverse SDE within the core continuous score sde computation pathway."},{"name":"Predictor","desc":"数值离散 reverse SDE 前进一步","name_en":"Predictor","desc_en":"Performs Predictor within the core continuous score sde computation pathway."},{"name":"Corrector","desc":"Langevin MCMC 在当前噪声尺度校正分布","name_en":"Corrector","desc_en":"Performs Corrector within the core continuous score sde computation pathway."},{"name":"PF-ODE","desc":"dx=[f-0.5g^2 s_theta]dt，与 SDE 共享边缘分布且为确定性","name_en":"PF-ODE","desc_en":"Applies PF-ODE to project aggregated representations toward the target task head."},{"name":"生成样本","desc":"reverse SDE/PC 或 PF-ODE 的 t=0 端点","name_en":"Synthesized Sample","desc_en":"Produces samples generated via predictor-corrector reverse sde or exact likelihoods via probability-flow ode via Synthesized Sample."}],"design_principles":["连续时间 SDE 统一了离散 diffusion 与多噪声尺度 score matching。","反向 SDE 的随机路径和 PF-ODE 的确定性路径使用同一 score，并具有相同时间边缘分布。","predictor-corrector 将数值积分与每尺度 MCMC 校正组合，但质量和计算量均依赖步长策略。"],"design_principles_en":["Core Hypothesis: Cast forward corruption as a continuous Itô SDE whose reverse-time SDE and deterministic PF-ODE depend solely on the time-dependent score ∇_x log p_t(x).","Architectural Delta: Unified VE/VP/sub-VP SDE taxonomy + Predictor-Corrector (PC) samplers + exact log-likelihood computation + controllable inverse conditional sampling.","Mathematical Formalism: Continuous-Time Forward/Reverse SDE & Marginal-Equivalent Probability-Flow ODE."],"med_apps":["可把测量 likelihood gradient 加入 reverse dynamics，用于 MRI/CT posterior sampling 与不确定性研究。","score prior、噪声 SDE 和真实测量 likelihood 任一失配都会使样本不再代表可信后验。"],"med_apps_en":["Clinical Translation: Provides the rigorous continuous-time mathematical foundation for MRI/CT score-based posterior reconstruction.","Evidence & Safety Boundary: Foundational mathematical framework; practical medical inverse solving still depends on accurate likelihood score approximations."],"attrs":{"上一代瓶颈":"离散 diffusion 和 score matching 缺少统一连续框架","核心想法":"以连续时间 score network 统一 reverse SDE、probability-flow ODE 与采样器","关键改进":"反向 SDE、predictor-corrector 与同边缘分布的确定性 PF-ODE","医学适配":"为 MRI/CT posterior sampling 和 likelihood guidance 提供理论接口","适用范围与证据":"核心数学基础；posterior 与采样仍受 score/likelihood mismatch 影响"},"attrs_en":{"上一代瓶颈":"SMLD (score matching) and DDPM (diffusion) were developed as separate discrete heuristics lacking a unified continuous mathematical theory.","核心想法":"Cast forward corruption as a continuous Itô SDE whose reverse-time SDE and deterministic PF-ODE depend solely on the time-dependent score ∇_x log p_t(x).","关键改进":"Unified VE/VP/sub-VP SDE taxonomy + Predictor-Corrector (PC) samplers + exact log-likelihood computation + controllable inverse conditional sampling.","医学适配":"Provides the rigorous continuous-time mathematical foundation for MRI/CT score-based posterior reconstruction.","适用范围与证据":"Foundational mathematical framework; practical medical inverse solving still depends on accurate likelihood score approximations."},"paper_title":"Score-Based Generative Modeling through Stochastic Differential Equations","paper_url":"https://openreview.net/pdf?id=PxTIG12RRHS","code_label":"作者/机构官方实现","code_url":"https://github.com/yang-song/score_sde","has_code":true,"image":"assets/d336ef3c13eb64a51513.avif"},{"id":"architecture_model_058_latent_diffusion","num":58,"num_str":"058","year":2022,"year_str":"2022","venue":"CVPR","venue_group":"cv","era_group":"era3","title":"Latent Diffusion","family_id":"models_generative","family_code":"10","family_short":"生成、扩散与流匹配","family_en":"Generative, Diffusion & Flow","family_icon":"X","family_label":"生成模型：从潜变量与对抗学习到 diffusion、flow 与 consistency","archetype":"latent_conditional_diffusion","archetype_en":"latent_conditional_diffusion","accent":"#6B5700","fig_badge":"Figure 3 · PDF p.4","fig_href":"https://openaccess.thecvf.com/content/CVPR2022/html/Rombach_High-Resolution_Image_Synthesis_With_Latent_Diffusion_Models_CVPR_2022_paper.html","core_mech":"先以 autoencoder 压缩图像，再在 latent grid 上运行可 cross-attention 条件化的 diffusion。","core_mech_en":"Perceptually compresses high-resolution images into a lower-dimensional spatial latent grid via a VQ/KL autoencoder before running cross-attention-conditioned diffusion.","input_desc":"图像 x 与可选条件 c；生成时为 latent 高斯噪声 zT","input_en":"High-resolution image x (encoded to z_0 = E(x)) + optional multimodal conditioning c (text, mask, layout)","output_desc":"由解码器还原的高分辨率图像 x_hat","output_en":"High-resolution synthesized image x̂ = D(ẑ_0) decoded from denoised latent grid","form_title":"核心公式 · 潜空间条件扩散训练目标","form_title_en":"Core Formalism · Conditional Denoising Diffusion Inside a Perceptually Compressed Autoencoder Latent Space","nodes":[{"name":"图像 x","desc":"像素空间训练样本","name_en":"Stage 01","desc_en":"Ingests high-resolution image x (encoded to z_0 = e(x)) + optional multimodal conditioning c (text, mask, layout) and prepares initial tensor representations (Stage 01)."},{"name":"VAE 编码器","desc":"感知/对抗正则的 autoencoder 将 x 压缩到 z0","name_en":"VAE encoder","desc_en":"Executes VAE encoder to extract primary structural features and establish spatial/sequence encoding."},{"name":"latent z0","desc":"较低空间分辨率、较高语义密度的连续网格","name_en":"latent z0","desc_en":"Performs latent z0 within the core latent conditional diffusion computation pathway."},{"name":"latent 加噪","desc":"q(z_t|z0) 在潜空间逐步加入高斯噪声","name_en":"latent","desc_en":"Performs latent within the core latent conditional diffusion computation pathway."},{"name":"条件 c","desc":"文本或其他模态经 cross-attention 注入","name_en":"Stage 05","desc_en":"Performs Stage 05 within the core latent conditional diffusion computation pathway."},{"name":"U-Net score","desc":"epsilon_theta(z_t,t,c) 在 latent grid 上预测噪声/score","name_en":"U-Net score","desc_en":"Performs U-Net score within the core latent conditional diffusion computation pathway."},{"name":"逆 SDE / ODE","desc":"DDPM、DDIM 等 solver 从 zT 迭代到 z0_hat","name_en":"SDE / ODE","desc_en":"Performs SDE / ODE within the core latent conditional diffusion computation pathway."},{"name":"VAE 解码器","desc":"把 z0_hat 映射回像素空间","name_en":"VAE decoder","desc_en":"Applies VAE decoder to project aggregated representations toward the target task head."},{"name":"x_hat","desc":"高分辨率生成或条件转换结果","name_en":"x_hat","desc_en":"Produces high-resolution synthesized image x̂ = d(ẑ_0) decoded from denoised latent grid via x_hat."}],"design_principles":["把感知压缩与生成建模解耦，使扩散主干在更小的 latent 网格上运行。","cross-attention 提供统一条件接口，可接文本、类别或其他模态 token。","生成上限受 autoencoder reconstruction ceiling 限制；latent 中已丢失的信息无法由数据一致性自动恢复。"],"design_principles_en":["Core Hypothesis: Separate perceptual high-frequency compression (autoencoder) from semantic generative modeling (diffusion U-Net in latent space) with cross-attention conditioning.","Architectural Delta: Dramatic spatial token reduction (e.g., 8× downsampling per axis) + flexible cross-attention conditioning mechanism.","Mathematical Formalism: Conditional Denoising Diffusion Inside a Perceptually Compressed Autoencoder Latent Space."],"med_apps":["适合高分辨医学合成与跨模态研究，并显著降低像素空间 diffusion 的内存和计算。","微钙化、小血管、薄壁和定量强度可能在 VAE 压缩阶段消失，必须先审计 autoencoder 重建误差。"],"med_apps_en":["Clinical Translation: Dominant architecture for high-resolution 2D/3D medical image synthesis, report-to-image generation, and synthetic data augmentation.","Evidence & Safety Boundary: Pragmatic scaling route; the frozen first-stage autoencoder sets an upper bound on fidelity and can bottleneck tiny micro-lesions or quantitative HU values."],"attrs":{"上一代瓶颈":"pixel-space diffusion 在高分辨率和 3D 上计算过重","核心想法":"先用 autoencoder 压缩图像，再在 latent grid 上扩散并以 cross-attention 条件化","关键改进":"用较小空间网格建模语义，支持更大 backbone 与多模态条件","医学适配":"用于医学合成、跨模态 translation 和高分辨生成","适用范围与证据":"现实的大模型路线；autoencoder ceiling 可能丢微钙化、小血管和定量强度"},"attrs_en":{"上一代瓶颈":"Pixel-space diffusion scaled poorly in compute and VRAM on high-resolution 2D images and 3D medical volumes.","核心想法":"Separate perceptual high-frequency compression (autoencoder) from semantic generative modeling (diffusion U-Net in latent space) with cross-attention conditioning.","关键改进":"Dramatic spatial token reduction (e.g., 8× downsampling per axis) + flexible cross-attention conditioning mechanism.","医学适配":"Dominant architecture for high-resolution 2D/3D medical image synthesis, report-to-image generation, and synthetic data augmentation.","适用范围与证据":"Pragmatic scaling route; the frozen first-stage autoencoder sets an upper bound on fidelity and can bottleneck tiny micro-lesions or quantitative HU values."},"paper_title":"High-Resolution Image Synthesis with Latent Diffusion Models","paper_url":"https://openaccess.thecvf.com/content/CVPR2022/html/Rombach_High-Resolution_Image_Synthesis_With_Latent_Diffusion_Models_CVPR_2022_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/CompVis/latent-diffusion","has_code":true,"image":"assets/855dec856e4895bf939a.avif"},{"id":"architecture_model_059_ddrm","num":59,"num_str":"059","year":2022,"year_str":"2022","venue":"NeurIPS","venue_group":"ml","era_group":"era3","title":"DDRM","family_id":"models_generative","family_code":"10","family_short":"生成、扩散与流匹配","family_en":"Generative, Diffusion & Flow","family_icon":"X","family_label":"生成模型：从潜变量与对抗学习到 diffusion、flow 与 consistency","archetype":"svd_conditioned_diffusion_inverse","archetype_en":"svd_conditioned_diffusion_inverse","accent":"#6B5700","fig_badge":"Figure 2 · PDF p.3","fig_href":"https://papers.nips.cc/paper_files/paper/2022/hash/95504595b6169131b6ed6cd72eb05616-Abstract-Conference.html","core_mech":"在退化算子 SVD 基中把预训练 diffusion prior 与线性观测条件分量逐时间步耦合。","core_mech_en":"Couples an unconditional pretrained diffusion prior with a linear forward operator y = Hx + z by running conditional reverse diffusion in the SVD spectral domain of H.","input_desc":"线性退化测量 y=A x+n、已知 A 及预训练无条件 diffusion prior","input_en":"Linearly degraded measurement y = Hx + z, known SVD of operator H, and an unconditional pretrained diffusion model","output_desc":"满足线性测量约束的恢复样本 x_hat","output_en":"Restored image x̂ consistent with both linear measurements y and the pretrained diffusion prior","form_title":"核心公式 · SVD 坐标中的逐奇异方向条件逆扩散","form_title_en":"Core Formalism · Spectral-Space Conditional Reverse Diffusion Along Singular Vectors of Operator H","nodes":[{"name":"测量 y","desc":"含已知噪声水平的线性观测","name_en":"Stage 01","desc_en":"Ingests linearly degraded measurement y = hx + z, known svd of operator h, and an unconditional pretrained diffusion model and prepares initial tensor representations (Stage 01)."},{"name":"A / A*","desc":"已知线性退化及其伴随；A=U Sigma V*","name_en":"A / A*","desc_en":"Executes A / A* to extract primary structural features and establish spatial/sequence encoding."},{"name":"SVD 坐标","desc":"将可观测、弱观测和零空间方向分离","name_en":"SVD","desc_en":"Performs SVD within the core svd conditioned diffusion inverse computation pathway."},{"name":"Diffusion 加噪","desc":"无条件 prior 的预设噪声层级与前向高斯过程","name_en":"Diffusion","desc_en":"Performs Diffusion within the core svd conditioned diffusion inverse computation pathway."},{"name":"去噪 / score","desc":"预训练网络提供各 t 的 clean/noise 估计，无需为 A 重训","name_en":"denoising / score","desc_en":"Performs denoising / score within the core svd conditioned diffusion inverse computation pathway."},{"name":"谱域 DC","desc":"按 singular value 和观测噪声对每个方向做条件更新","name_en":"DC","desc_en":"Performs DC within the core svd conditioned diffusion inverse computation pathway."},{"name":"T 步恢复","desc":"每个逆扩散时间步交替 prior 预测与 SVD 条件采样","name_en":"Stage 07","desc_en":"Performs Stage 07 within the core svd conditioned diffusion inverse computation pathway."},{"name":"ODE 路径边界","desc":"原始 DDRM 使用离散条件逆扩散；未给出保持 SVD 条件更新的 PF-ODE 版本","name_en":"ODE","desc_en":"Applies ODE to project aggregated representations toward the target task head."},{"name":"x_hat","desc":"由 V 基变换回图像域的恢复样本","name_en":"x_hat","desc_en":"Produces restored image x̂ consistent with both linear measurements y and the pretrained diffusion prior via x_hat."}],"design_principles":["在 A 的奇异向量基中，测量约束可按每个 singular direction 与噪声水平解析处理。","无条件 diffusion prior 与退化算子解耦，同一 prior 可用于多种线性恢复任务。","T 个逆扩散步骤构成恢复迭代，但不是学习优化器式的 stage-by-stage unrolling。"],"design_principles_en":["Core Hypothesis: Transform the reverse diffusion process into the Singular Value Decomposition (SVD) basis of H, conditioning spectral coefficients directly on observed measurements and noise level.","Architectural Delta: Zero-shot plug-and-play linear inverse solver requiring only 20 DDIM-style steps and zero task-specific retraining.","Mathematical Formalism: Spectral-Space Conditional Reverse Diffusion Along Singular Vectors of Operator H."],"med_apps":["适合具有可计算 SVD 或快速谱分解的线性 MRI、去模糊和超分辨研究。","大规模 CT 显式 SVD 通常不可行，非线性/Poisson 成像也不满足其解析条件化假设。"],"med_apps_en":["Clinical Translation: Applicable to super-resolution, deblurring, inpainting, and compressed sensing MRI where the forward operator admits tractable spectral decomposition.","Evidence & Safety Boundary: Important zero-shot inverse solver milestone; computing explicit full SVD is intractable for large 3D cone-beam CT or non-linear forward operators."],"attrs":{"上一代瓶颈":"每种线性退化都需重新训练专用模型","核心想法":"利用线性退化算子 A 的 SVD 构造 diffusion restoration posterior","关键改进":"将无条件 diffusion prior 与已知线性 forward model 解耦","医学适配":"同一 prior 可研究 MRI、去模糊、超分辨和部分 CT 线性逆问题","适用范围与证据":"inverse solver 重要节点；大规模 CT 的 SVD 和非线性 likelihood 不便"},"attrs_en":{"上一代瓶颈":"Supervised restoration required retraining a separate model whenever the degradation operator, blur kernel, or undersampling mask changed.","核心想法":"Transform the reverse diffusion process into the Singular Value Decomposition (SVD) basis of H, conditioning spectral coefficients directly on observed measurements and noise level.","关键改进":"Zero-shot plug-and-play linear inverse solver requiring only 20 DDIM-style steps and zero task-specific retraining.","医学适配":"Applicable to super-resolution, deblurring, inpainting, and compressed sensing MRI where the forward operator admits tractable spectral decomposition.","适用范围与证据":"Important zero-shot inverse solver milestone; computing explicit full SVD is intractable for large 3D cone-beam CT or non-linear forward operators."},"paper_title":"Denoising Diffusion Restoration Models","paper_url":"https://papers.nips.cc/paper_files/paper/2022/hash/95504595b6169131b6ed6cd72eb05616-Abstract-Conference.html","code_label":"作者/机构官方实现","code_url":"https://github.com/bahjat-kawar/ddrm","has_code":true,"image":"assets/6b1764b6b92c73ca986e.avif"},{"id":"architecture_model_060_dps","num":60,"num_str":"060","year":2023,"year_str":"2023","venue":"ICLR","venue_group":"ml","era_group":"era4","title":"DPS","family_id":"models_generative","family_code":"10","family_short":"生成、扩散与流匹配","family_en":"Generative, Diffusion & Flow","family_icon":"X","family_label":"生成模型：从潜变量与对抗学习到 diffusion、flow 与 consistency","archetype":"likelihood_guided_diffusion_inverse","archetype_en":"likelihood_guided_diffusion_inverse","accent":"#6B5700","fig_badge":"Figure 3 · PDF p.6","fig_href":"https://arxiv.org/abs/2209.14687","core_mech":"在每个 diffusion 逆时间步，把预训练先验 score 与经 x0 估计反传的测量 likelihood gradient 相加。","core_mech_en":"Approximates intractable time-dependent measurement likelihood scores ∇_{x_t} log p_t(y|x_t) via backpropagation through the Tweedie posterior mean estimate x̂_0(x_t).","input_desc":"噪声测量 y、可微前向模型 A 与预训练 diffusion score prior","input_en":"Corrupted measurement y, general differentiable forward operator A(·), and pretrained unconditional score network s_θ","output_desc":"近似后验样本 x_hat ~ p(x|y)","output_en":"Posterior sample x̂ ~ p(x|y) satisfying noisy linear or non-linear measurement constraints","form_title":"核心公式 · 先验 score 与测量 likelihood 梯度耦合","form_title_en":"Core Formalism · Prior Score Coupled with Measurement Likelihood Gradient via Tweedie Denoised Estimate x̂_0","nodes":[{"name":"测量 y","desc":"可为线性或非线性、带噪观测","name_en":"Stage 01","desc_en":"Ingests corrupted measurement y, general differentiable forward operator a(·), and pretrained unconditional score network s_θ and prepares initial tensor representations (Stage 01)."},{"name":"A / A*","desc":"可微 forward A；反向传播/伴随 A* 传递 likelihood gradient","name_en":"A / A*","desc_en":"Executes A / A* to extract primary structural features and establish spatial/sequence encoding."},{"name":"Diffusion 加噪","desc":"训练 prior 的前向噪声过程，生成从 x0 到 xT 的尺度","name_en":"Diffusion","desc_en":"Performs Diffusion within the core likelihood guided diffusion inverse computation pathway."},{"name":"状态 x_t","desc":"从高斯 xT 开始的当前后验采样状态","name_en":"x_t","desc_en":"Performs x_t within the core likelihood guided diffusion inverse computation pathway."},{"name":"先验 score","desc":"s_theta(x_t,t) 或等价 epsilon predictor","name_en":"prior score","desc_en":"Performs prior score within the core likelihood guided diffusion inverse computation pathway."},{"name":"x0 估计","desc":"由 x_t 与 score 构造去噪估计 x0_hat(x_t)","name_en":"x0","desc_en":"Performs x0 within the core likelihood guided diffusion inverse computation pathway."},{"name":"Likelihood 梯度","desc":"对 ||y-A(x0_hat)||^2 求梯度；线性情形含 A*(A x0_hat-y)","name_en":"Likelihood","desc_en":"Performs Likelihood within the core likelihood guided diffusion inverse computation pathway."},{"name":"后验 score","desc":"先验 score 与近似 measurement guidance 相加","name_en":"score","desc_en":"Performs score within the core likelihood guided diffusion inverse computation pathway."},{"name":"逆 SDE / ODE","desc":"T 个数值步骤反复计算 score、x0_hat 与 DC guidance","name_en":"SDE / ODE","desc_en":"Applies SDE / ODE to project aggregated representations toward the target task head."},{"name":"x_hat","desc":"t=0 的近似 posterior sample","name_en":"x_hat","desc_en":"Produces posterior sample x̂ ~ p(x|y) satisfying noisy linear or non-linear measurement constraints via x_hat."}],"design_principles":["用 Tweedie/去噪估计把不可直接求得的 noisy-state likelihood 近似为对 x0_hat 的测量残差。","可微 A 使同一无条件 prior 能接入不同线性或非线性 inverse problems。","每个逆时间步都执行 score 与 data-consistency guidance，属于采样迭代而非固定 K 级学习优化器。"],"design_principles_en":["Core Hypothesis: Approximate p(y|x_t) ≈ p(y | x̂_0(x_t)) using Tweedie's formula and take a gradient step ∇_{x_t} ||y − A(x̂_0(x_t))||² at every reverse diffusion step.","Architectural Delta: Handles general noisy linear and non-linear differentiable forward operators without SVD or task-specific retraining.","Mathematical Formalism: Prior Score Coupled with Measurement Likelihood Gradient via Tweedie Denoised Estimate x̂_0."],"med_apps":["可为 MRI、CT、PET 等显式测量模型生成多个候选样本，用于研究条件不确定性。","guidance 权重、噪声似然和 A 的误差会改变样本分布；多样性不等于经过校准的临床后验。"],"med_apps_en":["Clinical Translation: Widely used in accelerated multi-coil MRI, sparse-view CT, phase retrieval, and PET posterior sampling research.","Evidence & Safety Boundary: Core diffusion inverse baseline; requires backpropagation through the score network at every step (high memory/latency) and sensitive guidance-scale tuning."],"attrs":{"上一代瓶颈":"早期 diffusion inverse 方法难处理 noisy 或 nonlinear operators","核心想法":"把 learned score prior 与可微 measurement likelihood gradient 结合","关键改进":"通过 x0 估计近似 posterior score guidance，支持通用 differentiable A","医学适配":"可用于 MRI、CT、PET 等测量模型耦合的 posterior sampling","适用范围与证据":"研究主干；guidance 调参、NFE 和 posterior calibration 仍是限制"},"attrs_en":{"上一代瓶颈":"Projection-based diffusion solvers failed under heavy measurement noise or non-linear operators without closed-form SVD.","核心想法":"Approximate p(y|x_t) ≈ p(y | x̂_0(x_t)) using Tweedie's formula and take a gradient step ∇_{x_t} ||y − A(x̂_0(x_t))||² at every reverse diffusion step.","关键改进":"Handles general noisy linear and non-linear differentiable forward operators without SVD or task-specific retraining.","医学适配":"Widely used in accelerated multi-coil MRI, sparse-view CT, phase retrieval, and PET posterior sampling research.","适用范围与证据":"Core diffusion inverse baseline; requires backpropagation through the score network at every step (high memory/latency) and sensitive guidance-scale tuning."},"paper_title":"Diffusion Posterior Sampling for General Noisy Inverse Problems","paper_url":"https://arxiv.org/abs/2209.14687","code_label":"作者/机构官方实现","code_url":"https://github.com/DPS2022/diffusion-posterior-sampling","has_code":true,"image":"assets/e89b537f5e8357d7d9d1.avif"},{"id":"architecture_model_061_diffusionmbir","num":61,"num_str":"061","year":2023,"year_str":"2023","venue":"CVPR","venue_group":"cv","era_group":"era4","title":"DiffusionMBIR","family_id":"models_generative","family_code":"10","family_short":"生成、扩散与流匹配","family_en":"Generative, Diffusion & Flow","family_icon":"X","family_label":"生成模型：从潜变量与对抗学习到 diffusion、flow 与 consistency","archetype":"slice_diffusion_3d_mbir","archetype_en":"slice_diffusion_3d_mbir","accent":"#6B5700","fig_badge":"Figure 2 · PDF p.3","fig_href":"https://openaccess.thecvf.com/content/CVPR2023/html/Chung_Solving_3D_Inverse_Problems_Using_Pre-Trained_2D_Diffusion_Models_CVPR_2023_paper.html","core_mech":"把预训练 2D diffusion slice prior 嵌入 3D MBIR/data-consistency 外循环，并显式加跨切片约束。","core_mech_en":"Embeds a pretrained 2D slice diffusion score prior into an alternating 3D Model-Based Iterative Reconstruction (MBIR) loop with explicit z-axis total variation regularization.","input_desc":"3D 测量 y、体成像算子 A/A* 与预训练 2D diffusion prior","input_en":"3D tomographic measurements y, 3D forward/adjoint operators A/A*, and a pretrained 2D axial diffusion model","output_desc":"数据一致且具跨切片约束的 3D 体 x_hat","output_en":"Volumetric 3D reconstruction x̂ maintaining 3D measurement fidelity and inter-slice smoothness","form_title":"核心公式 · 2D diffusion 先验约束下的 3D MBIR 数据一致性","form_title_en":"Core Formalism · Alternating 2D Slice Diffusion Prior Updates & 3D ADMM/CG Measurement Data Consistency with z-TV","nodes":[{"name":"3D 测量 y","desc":"稀疏/有限角 CT 投影或欠采样 MRI 数据","name_en":"3D y","desc_en":"Ingests 3d tomographic measurements y, 3d forward/adjoint operators a/a*, and a pretrained 2d axial diffusion model and prepares initial tensor representations (3D y)."},{"name":"A / A*","desc":"真实 3D forward 与 adjoint，提供 volume-level 数据项","name_en":"A / A*","desc_en":"Executes A / A* to extract primary structural features and establish spatial/sequence encoding."},{"name":"前向噪声状态 x_t","desc":"沿预训练 2D prior 的 forward/noise schedule 定义尺度，并从 x_T/初始化反向更新","name_en":"noise x_t","desc_en":"Performs noise x_t within the core slice diffusion 3d mbir computation pathway."},{"name":"2D 切片视图","desc":"把体按一个或多个正交方向拆成 2D slices","name_en":"2D slice","desc_en":"Performs 2D slice within the core slice diffusion 3d mbir computation pathway."},{"name":"2D diffusion prior","desc":"预训练 2D score/denoiser 在每个噪声尺度处理切片","name_en":"2D diffusion prior","desc_en":"Performs 2D diffusion prior within the core slice diffusion 3d mbir computation pathway."},{"name":"重组 3D 体","desc":"把切片 prior 更新重新堆叠到共享体坐标","name_en":"3D","desc_en":"Performs 3D within the core slice diffusion 3d mbir computation pathway."},{"name":"跨切片约束","desc":"3D 正则/一致性项抑制独立切片造成的不连续","name_en":"slice constraint","desc_en":"Performs slice constraint within the core slice diffusion 3d mbir computation pathway."},{"name":"MBIR / DC","desc":"利用 A*(A x-y) 与 3D regularizer 更新体状态","name_en":"MBIR / DC","desc_en":"Performs MBIR / DC within the core slice diffusion 3d mbir computation pathway."},{"name":"逆扩散外循环","desc":"各 t 交替 2D prior、3D regularization 与 measurement update；原方法走离散 reverse updates，不是 PF-ODE","name_en":"reverse diffusion","desc_en":"Applies reverse diffusion to project aggregated representations toward the target task head."},{"name":"x_hat","desc":"t=0 的 3D 重建","name_en":"x_hat","desc_en":"Produces volumetric 3d reconstruction x̂ maintaining 3d measurement fidelity and inter-slice smoothness via x_hat."}],"design_principles":["复用数据充足、成本较低的 2D diffusion prior，避免从头训练完整 3D 生成模型。","3D A/A* 数据项把所有切片共同约束到同一测量，跨切片正则补偿独立 2D prior。","每个逆时间步交替 prior 与 MBIR/DC，形成 physics-guided sampling，而非纯切片生成。"],"design_principles_en":["Core Hypothesis: Apply a data-efficient pretrained 2D axial score prior slice-by-slice while enforcing 3D physical data consistency and z-axis TV continuity in an outer splitting loop.","Architectural Delta: Pragmatically bridges 2D generative score priors to 3D cone-beam/helical CT and 3D MRI reconstruction without 3D diffusion training.","Mathematical Formalism: Alternating 2D Slice Diffusion Prior Updates & 3D ADMM/CG Measurement Data Consistency with z-TV."],"med_apps":["适合稀疏/有限角 CT 和压缩感知 MRI 等 3D inverse problems 的低成本 prior 复用。","2D prior 仍可能产生切片间不一致或把罕见三维结构投射为常见二维形态，必须做体级和测量域验证。"],"med_apps_en":["Clinical Translation: Used for sparse-view CT, limited-angle CT, and volumetric compressed-sensing reconstruction.","Evidence & Safety Boundary: Practical 2D-to-3D reconstruction compromise; slice-wise 2D priors plus z-TV still cannot fully capture complex 3D non-local anatomical priors."],"attrs":{"上一代瓶颈":"训练真正 3D diffusion 的数据与显存成本很高","核心想法":"以预训练 2D diffusion prior 配合 3D measurement fidelity/MBIR","关键改进":"跨切片/体积一致性正则把 2D prior 复用于 3D inverse tasks","医学适配":"用于 sparse/limited-angle CT 与 compressed-sensing MRI","适用范围与证据":"有代表性的 3D 折中；2D slice prior 不等于真实 3D anatomy"},"attrs_en":{"上一代瓶颈":"Training native whole-volume high-resolution 3D diffusion models is bottlenecked by scarce 3D cohorts and extreme GPU memory.","核心想法":"Apply a data-efficient pretrained 2D axial score prior slice-by-slice while enforcing 3D physical data consistency and z-axis TV continuity in an outer splitting loop.","关键改进":"Pragmatically bridges 2D generative score priors to 3D cone-beam/helical CT and 3D MRI reconstruction without 3D diffusion training.","医学适配":"Used for sparse-view CT, limited-angle CT, and volumetric compressed-sensing reconstruction.","适用范围与证据":"Practical 2D-to-3D reconstruction compromise; slice-wise 2D priors plus z-TV still cannot fully capture complex 3D non-local anatomical priors."},"paper_title":"Solving 3D Inverse Problems using Pre-trained 2D Diffusion Models","paper_url":"https://openaccess.thecvf.com/content/CVPR2023/papers/Chung_Solving_3D_Inverse_Problems_Using_Pre-Trained_2D_Diffusion_Models_CVPR_2023_paper.pdf","code_label":"作者/机构官方实现","code_url":"https://github.com/hyungjin-chung/DiffusionMBIR","has_code":true,"image":"assets/c734a73bf00a8da07e76.avif"},{"id":"architecture_model_062_flow_matching","num":62,"num_str":"062","year":2023,"year_str":"2023","venue":"ICLR","venue_group":"ml","era_group":"era4","title":"Flow Matching","family_id":"models_generative","family_code":"10","family_short":"生成、扩散与流匹配","family_en":"Generative, Diffusion & Flow","family_icon":"X","family_label":"生成模型：从潜变量与对抗学习到 diffusion、flow 与 consistency","archetype":"probability_path_velocity_ode","archetype_en":"probability_path_velocity_ode","accent":"#6B5700","fig_badge":"Figure 2 · PDF p.6","fig_href":"https://arxiv.org/abs/2210.02747","core_mech":"在已知 probability path 上回归 velocity（而非 score），再直接积分神经 ODE 完成分布运输。","core_mech_en":"Trains continuous normalizing flows without ODE simulation by directly regressing the marginal vector field u_t(x) along conditional probability paths.","input_desc":"源分布样本 x0（通常高斯噪声）与数据样本 x1","input_en":"Source prior sample x_0 ~ p_0 and target data sample x_1 ~ p_1 interpolated along a conditional path x_t","output_desc":"沿学习 ODE 从源分布运输得到的生成样本","output_en":"Samples generated by integrating the learned velocity field dx/dt = v_θ(x_t, t) from t=0 to t=1","form_title":"核心公式 · 条件速度回归与生成 ODE","form_title_en":"Core Formalism · Simulation-Free Conditional Flow Matching (CFM) Velocity Regression & ODE Transport","nodes":[{"name":"源噪声 x0","desc":"易采样的 base distribution，通常 N(0,I)","name_en":"noise x0","desc_en":"Ingests source prior sample x_0 ~ p_0 and target data sample x_1 ~ p_1 interpolated along a conditional path x_t and prepares initial tensor representations (noise x0)."},{"name":"数据 x1","desc":"训练数据分布中的样本","name_en":"x1","desc_en":"Executes x1 to extract primary structural features and establish spatial/sequence encoding."},{"name":"样本 coupling","desc":"联合抽取 (x0,x1)，决定条件概率路径的配对","name_en":"coupling","desc_en":"Performs coupling within the core probability path velocity ode computation pathway."},{"name":"前向概率路径","desc":"构造 x_t 与已知 p_t(x|x1)；直线路径常写 x_t=(1-t)x0+t x1","name_en":"Stage 04","desc_en":"Performs Stage 04 within the core probability path velocity ode computation pathway."},{"name":"目标速度 u_t","desc":"条件路径的解析 velocity target；训练目标不是 score","name_en":"objective u_t","desc_en":"Performs objective u_t within the core probability path velocity ode computation pathway."},{"name":"速度场 v_theta","desc":"普通 U-Net/Transformer 回归 v_theta(x_t,t)","name_en":"velocity field v_theta","desc_en":"Performs velocity field v_theta within the core probability path velocity ode computation pathway."},{"name":"FM 回归","desc":"最小化 ||v_theta-u_t||^2；无需求解 score 或 likelihood","name_en":"FM","desc_en":"Performs FM within the core probability path velocity ode computation pathway."},{"name":"生成 ODE","desc":"dx/dt=v_theta(x,t)，从 t=0 数值积分到 t=1","name_en":"ODE","desc_en":"Applies ODE to project aggregated representations toward the target task head."},{"name":"生成样本","desc":"ODE 终点 x(1)","name_en":"Synthesized Sample","desc_en":"Produces samples generated by integrating the learned velocity field dx/dt = v_θ(x_t, t) from t=0 to t=1 via Synthesized Sample."}],"design_principles":["在预先选定的概率路径上直接监督速度场，避免 normalizing flow 的逐层可逆性和 Jacobian 约束。","条件 velocity 的平方回归可得到同一边缘运输的 marginal velocity，无需显式学习 score。","推理只解常微分方程；轨迹曲率和 solver 误差决定所需函数评估次数。"],"design_principles_en":["Core Hypothesis: Construct conditional probability paths (e.g., optimal transport straight lines) with closed-form conditional velocities and train v_θ via simple L2 regression.","Architectural Delta: Simulation-free training with unconstrained U-Net/DiT backbones + straight optimal-transport paths enabling fast few-step ODE integration.","Mathematical Formalism: Simulation-Free Conditional Flow Matching (CFM) Velocity Regression & ODE Transport."],"med_apps":["可把解剖、模态或测量作为条件输入，研究少步医学跨模态生成和 inverse solver。","更少 ODE 步数不等于病灶更保真；coupling、条件路径及临床指标仍需专门设计与验证。"],"med_apps_en":["Clinical Translation: Rapidly adopted for fast medical image synthesis, cross-modality translation, and operator-conditioned inverse reconstruction.","Evidence & Safety Boundary: High-momentum generative paradigm; clinical superiority and calibrated posterior uncertainty over unrolled/diffusion baselines remain open research."],"attrs":{"上一代瓶颈":"normalizing flow 受可逆层和 Jacobian 限制，diffusion 采样步骤多","核心想法":"在选定概率路径上回归条件 velocity field，再解 ODE 从 source transport 到 data","关键改进":"普通 U-Net/DiT 即可训练，无需 exact invertibility；直路径可少步积分","医学适配":"启发 operator-conditioned 医学 inverse solver 与少步跨模态生成","适用范围与证据":"高速发展；医学 coupling、likelihood 耦合与临床 superiority 尚未解决"},"attrs_en":{"上一代瓶颈":"Continuous Normalizing Flows required costly backpropagation through ODE solvers, while diffusion models relied on curved stochastic paths.","核心想法":"Construct conditional probability paths (e.g., optimal transport straight lines) with closed-form conditional velocities and train v_θ via simple L2 regression.","关键改进":"Simulation-free training with unconstrained U-Net/DiT backbones + straight optimal-transport paths enabling fast few-step ODE integration.","医学适配":"Rapidly adopted for fast medical image synthesis, cross-modality translation, and operator-conditioned inverse reconstruction.","适用范围与证据":"High-momentum generative paradigm; clinical superiority and calibrated posterior uncertainty over unrolled/diffusion baselines remain open research."},"paper_title":"Flow Matching for Generative Modeling","paper_url":"https://arxiv.org/abs/2210.02747","code_label":"未提供官方实现","code_url":"","has_code":false,"image":"assets/3fd67e8c25c23b0b13c3.avif"},{"id":"architecture_model_063_rectified_flow","num":63,"num_str":"063","year":2023,"year_str":"2023","venue":"ICLR","venue_group":"ml","era_group":"era4","title":"Rectified Flow","family_id":"models_generative","family_code":"10","family_short":"生成、扩散与流匹配","family_en":"Generative, Diffusion & Flow","family_icon":"X","family_label":"生成模型：从潜变量与对抗学习到 diffusion、flow 与 consistency","archetype":"straightened_transport_ode","archetype_en":"straightened_transport_ode","accent":"#6B5700","fig_badge":"Figure 2 · PDF p.4","fig_href":"https://mlanthology.org/iclr/2023/liu2023iclr-flow/","core_mech":"以直线端点路径训练 velocity，并通过 reflow 重新耦合端点以进一步拉直 ODE 轨迹。","core_mech_en":"Learns an ODE velocity field along straight linear interpolations x_t = (1−t)x_0 + t x_1 and iteratively straightens trajectories via reflow recoupling.","input_desc":"源噪声 z0 与目标数据 x1 的 coupling","input_en":"Coupled pairs (x_0, x_1) from source distribution π_0 and target distribution π_1","output_desc":"沿近直线 ODE 少步运输得到的样本 x_hat","output_en":"Nearly straight-line ODE transport trajectories enabling high-fidelity 1-to-few-step Euler generation","form_title":"核心公式 · 直线速度目标与 reflow 重新耦合","form_title_en":"Core Formalism · Linear Interpolation Velocity Matching & Iterative Reflow Trajectory Straightening","nodes":[{"name":"源噪声 z0","desc":"标准高斯等 base sample","name_en":"noise z0","desc_en":"Ingests coupled pairs (x_0, x_1) from source distribution π_0 and target distribution π_1 and prepares initial tensor representations (noise z0)."},{"name":"目标 x1","desc":"数据分布样本","name_en":"objective x1","desc_en":"Executes objective x1 to extract primary structural features and establish spatial/sequence encoding."},{"name":"初始 coupling","desc":"配对 z0 与 x1；配对质量决定交叉轨迹复杂度","name_en":"coupling","desc_en":"Performs coupling within the core straightened transport ode computation pathway."},{"name":"直线前向路径","desc":"x_t=(1-t)z0+t x1，目标速度为 x1-z0","name_en":"Stage 04","desc_en":"Performs Stage 04 within the core straightened transport ode computation pathway."},{"name":"速度场 v_theta","desc":"回归 E[x1-z0|x_t]；目标为 velocity 而非 score","name_en":"velocity field v_theta","desc_en":"Performs velocity field v_theta within the core straightened transport ode computation pathway."},{"name":"Rectified ODE","desc":"dx/dt=v_theta(x,t)，从噪声积分到数据","name_en":"Rectified ODE","desc_en":"Performs Rectified ODE within the core straightened transport ode computation pathway."},{"name":"生成端点对","desc":"用当前 ODE 将 z0 映射为 x1_hat，形成新 coupling","name_en":"Stage 07","desc_en":"Performs Stage 07 within the core straightened transport ode computation pathway."},{"name":"Reflow","desc":"在新端点对上重训，使轨迹进一步变直、减少交叉","name_en":"Reflow","desc_en":"Performs Reflow within the core straightened transport ode computation pathway."},{"name":"少步求解","desc":"直轨迹可用 Euler 等粗步长积分，甚至蒸馏为单步","name_en":"Stage 09","desc_en":"Applies Stage 09 to project aggregated representations toward the target task head."},{"name":"x_hat","desc":"ODE 终点生成样本","name_en":"x_hat","desc_en":"Produces nearly straight-line ode transport trajectories enabling high-fidelity 1-to-few-step euler generation via x_hat."}],"design_principles":["用端点线性插值监督 velocity，使学习到的流尽量沿短而直的运输轨迹。","reflow 以模型自身生成的端点重新配对并重训，逐轮降低轨迹弯曲和交叉。","训练不需要 score；速度场的直线性直接关系到粗步长 ODE 的离散误差。"],"design_principles_en":["Core Hypothesis: Drive transport paths as close to straight lines as possible by regressing the constant displacement (x_1 − x_0) and iteratively re-pairing (z_0, ẑ_1) via reflow.","Architectural Delta: Simple ODE velocity formulation + Reflow procedure that provably reduces transport cost and straightens trajectories for 1-step distillation.","Mathematical Formalism: Linear Interpolation Velocity Matching & Iterative Reflow Trajectory Straightening."],"med_apps":["对需要交互速度的医学图像生成、translation 或条件重建具有少步潜力。","轨迹更直只保证数值积分更容易，不保证微小病灶、定量强度或患者身份信息保持。"],"med_apps_en":["Clinical Translation: Provides a principled mathematical route for real-time few-step medical domain translation and generative modeling.","Evidence & Safety Boundary: Genuine algorithmic speed advantage; reflow distillation can subtly smooth high-frequency diagnostic textures if not audited."],"attrs":{"上一代瓶颈":"弯曲生成轨迹需要更多 ODE steps 才能准确积分","核心想法":"从 source-target coupling 学直线速度场，并用 reflow 进一步拉直轨迹","关键改进":"优化 trajectory straightness，降低 coarse-step integration error","医学适配":"为少步医学生成与 translation 提供速度路线","适用范围与证据":"少步潜力真实；高频和病灶 fidelity、uncertainty 仍需专门验证"},"attrs_en":{"上一代瓶颈":"Curved ODE transport trajectories accumulate high discretization error under large Euler step sizes.","核心想法":"Drive transport paths as close to straight lines as possible by regressing the constant displacement (x_1 − x_0) and iteratively re-pairing (z_0, ẑ_1) via reflow.","关键改进":"Simple ODE velocity formulation + Reflow procedure that provably reduces transport cost and straightens trajectories for 1-step distillation.","医学适配":"Provides a principled mathematical route for real-time few-step medical domain translation and generative modeling.","适用范围与证据":"Genuine algorithmic speed advantage; reflow distillation can subtly smooth high-frequency diagnostic textures if not audited."},"paper_title":"Flow Straight and Fast: Learning to Generate and Transfer Data with Rectified Flow","paper_url":"https://mlanthology.org/iclr/2023/liu2023iclr-flow/","code_label":"作者/机构官方实现","code_url":"https://github.com/gnobitab/RectifiedFlow","has_code":true,"image":"assets/fc2dc5b4a9271c2d1ccd.avif"},{"id":"architecture_model_064_consistency_models","num":64,"num_str":"064","year":2023,"year_str":"2023","venue":"ICML","venue_group":"ml","era_group":"era4","title":"Consistency Models","family_id":"models_generative","family_code":"10","family_short":"生成、扩散与流匹配","family_en":"Generative, Diffusion & Flow","family_icon":"X","family_label":"生成模型：从潜变量与对抗学习到 diffusion、flow 与 consistency","archetype":"probability_flow_consistency","archetype_en":"probability_flow_consistency","accent":"#6B5700","fig_badge":"Figure 2 · PDF p.3","fig_href":"https://proceedings.mlr.press/v202/song23a.html","core_mech":"学习沿 PF-ODE 轨迹不变的 endpoint map，使任意噪声尺度可直接一步映射到 clean sample。","core_mech_en":"Learns a self-consistent function f_θ(x_t, t) = x_ε that maps any point along a Probability-Flow ODE trajectory directly to its clean origin in a single step.","input_desc":"噪声状态 x_t；蒸馏模式下还需预训练 diffusion score teacher","input_en":"Noisy state x_t along a PF-ODE trajectory (distilled from a pretrained score model or trained standalone)","output_desc":"一次或少数几次函数调用得到的 clean sample","output_en":"One-step or few-step clean sample estimate x̂_0","form_title":"核心公式 · 概率流轨迹上的端点一致性与边界条件","form_title_en":"Core Formalism · Trajectory Self-Consistency f_θ(x_{t_{n+1}}, t_{n+1}) = f_{θ^-}(x_{t_n}, t_n) with Boundary Condition f_θ(x_ε, ε) = x_ε","nodes":[{"name":"数据 x0","desc":"训练分布样本","name_en":"x0","desc_en":"Ingests noisy state x_t along a pf-ode trajectory (distilled from a pretrained score model or trained standalone) and prepares initial tensor representations (x0)."},{"name":"前向加噪","desc":"在多个时间尺度生成 x_t 与 x_s","name_en":"Forward Gaussian Noising","desc_en":"Executes Forward Gaussian Noising to extract primary structural features and establish spatial/sequence encoding."},{"name":"噪声 x_T","desc":"生成时的起始高斯状态","name_en":"noise x_T","desc_en":"Performs noise x_T within the core probability flow consistency computation pathway."},{"name":"Score / PF-ODE","desc":"蒸馏时用 diffusion score teacher 的 probability-flow ODE 连接相邻时间","name_en":"Score / PF-ODE","desc_en":"Performs Score / PF-ODE within the core probability flow consistency computation pathway."},{"name":"同轨迹时间对","desc":"构造 (x_t,t) 与 (x_s,s)，二者位于同一 PF-ODE 轨迹","name_en":"Stage 05","desc_en":"Performs Stage 05 within the core probability flow consistency computation pathway."},{"name":"一致性函数 f_theta","desc":"把任意轨迹点直接映射到共同的 clean endpoint","name_en":"f_theta","desc_en":"Performs f_theta within the core probability flow consistency computation pathway."},{"name":"一致性损失","desc":"匹配 f_theta(x_t,t) 与 EMA target f_bar(x_s,s)，并满足边界 f(x,epsilon)=x","name_en":"loss","desc_en":"Performs loss within the core probability flow consistency computation pathway."},{"name":"一步路径","desc":"x_T→f_theta(x_T,T)，无需完整 ODE 积分","name_en":"Stage 08","desc_en":"Performs Stage 08 within the core probability flow consistency computation pathway."},{"name":"少步路径","desc":"输出后再加受控噪声并重复 f_theta 以提升质量","name_en":"Stage 09","desc_en":"Applies Stage 09 to project aggregated representations toward the target task head."},{"name":"x_hat","desc":"one/few-step clean sample","name_en":"x_hat","desc_en":"Produces one-step or few-step clean sample estimate x̂_0 via x_hat."}],"design_principles":["同一 probability-flow ODE 轨迹上的所有状态应映射到同一个干净端点。","可由 score-based diffusion 蒸馏，也可通过 consistency training 独立学习；两种训练证据需区分。","推理跳过逐步 ODE/SDE 数值积分，一步速度来自端点映射而非更粗的普通 diffusion solver。"],"design_principles_en":["Core Hypothesis: Enforce that any two adjacent points on the same PF-ODE trajectory map to the exact same clean endpoint under an EMA target network.","Architectural Delta: Supports single-step generation (1 NFE) as well as zero-shot multi-step iterative refinement trading compute for quality.","Mathematical Formalism: Trajectory Self-Consistency f_θ(x_{t_{n+1}}, t_{n+1}) = f_{θ^-}(x_{t_n}, t_n) with Boundary Condition f_θ(x_ε, ε) = x_ε."],"med_apps":["适合对延迟敏感的交互重建、床旁生成或大体积推理探索。","医学 raw-data 条件化、少步病灶保真和后验校准证据仍少，不能从自然图像速度结果外推临床等效。"],"med_apps_en":["Clinical Translation: Highly attractive for real-time medical reconstruction, interactive synthesis, and low-latency clinical workflows.","Evidence & Safety Boundary: Important speed frontier; raw-data medical inverse benchmarks and quantitative bias audits at 1–2 NFEs remain limited."],"attrs":{"上一代瓶颈":"高质量 diffusion 需要许多 solver steps","核心想法":"把同一 probability-flow ODE 轨迹上的任意点直接映射到相同 clean endpoint","关键改进":"可由预训练 diffusion 蒸馏或独立训练，实现 one/few-step generation","医学适配":"对实时医学重建和交互生成有直接吸引力","适用范围与证据":"速度方向重要；医学 raw-data benchmark 和校准证据不足"},"attrs_en":{"上一代瓶颈":"Even accelerated ODE/DDIM samplers required 10–50 sequential neural evaluations, limiting real-time intraoperative or streaming use.","核心想法":"Enforce that any two adjacent points on the same PF-ODE trajectory map to the exact same clean endpoint under an EMA target network.","关键改进":"Supports single-step generation (1 NFE) as well as zero-shot multi-step iterative refinement trading compute for quality.","医学适配":"Highly attractive for real-time medical reconstruction, interactive synthesis, and low-latency clinical workflows.","适用范围与证据":"Important speed frontier; raw-data medical inverse benchmarks and quantitative bias audits at 1–2 NFEs remain limited."},"paper_title":"Consistency Models","paper_url":"https://proceedings.mlr.press/v202/song23a/song23a.pdf","code_label":"作者/机构官方实现","code_url":"https://github.com/openai/consistency_models","has_code":true,"image":"assets/a12b96ff2efcd6b4aff4.avif"},{"id":"architecture_model_065_dit","num":65,"num_str":"065","year":2023,"year_str":"2023","venue":"ICCV","venue_group":"cv","era_group":"era4","title":"DiT","family_id":"models_generative","family_code":"10","family_short":"生成、扩散与流匹配","family_en":"Generative, Diffusion & Flow","family_icon":"X","family_label":"生成模型：从潜变量与对抗学习到 diffusion、flow 与 consistency","archetype":"transformer_diffusion_backbone","archetype_en":"transformer_diffusion_backbone","accent":"#6B5700","fig_badge":"Figure 3 · PDF p.3","fig_href":"https://openaccess.thecvf.com/content/ICCV2023/html/Peebles_Scalable_Diffusion_Models_with_Transformers_ICCV_2023_paper.html","core_mech":"把 noisy latent patch 化，以 adaLN-Zero 条件化的 Transformer blocks 作为 diffusion score/velocity backbone。","core_mech_en":"Replaces the convolutional U-Net backbone in Latent Diffusion with an isotropic Vision Transformer over latent patches conditioned via Adaptive LayerNorm-Zero (adaLN-Zero).","input_desc":"加噪 latent 图像 z_t、时间 t 与可选类别/条件 c","input_en":"Noisy latent tensor z_t, diffusion timestep t, and conditioning embedding c","output_desc":"epsilon/score 参数与可选方差预测，经逆扩散得到并解码的图像","output_en":"Predicted noise ε_θ, diagonal covariance Σ_θ, or velocity v_θ on the latent token grid","form_title":"核心公式 · adaLN-Zero 条件注意力与 epsilon 预测","form_title_en":"Core Formalism · Patchified Latent Diffusion Transformer Conditioned via Zero-Initialized Adaptive LayerNorm","nodes":[{"name":"latent z0","desc":"通常由预训练 VAE 编码图像得到","name_en":"latent z0","desc_en":"Ingests noisy latent tensor z_t, diffusion timestep t, and conditioning embedding c and prepares initial tensor representations (latent z0)."},{"name":"前向加噪","desc":"q(z_t|z0) 生成各噪声尺度的 latent","name_en":"Forward Gaussian Noising","desc_en":"Executes Forward Gaussian Noising to extract primary structural features and establish spatial/sequence encoding."},{"name":"噪声 z_t","desc":"训练输入；生成从 z_T 开始","name_en":"noise z_t","desc_en":"Performs noise z_t within the core transformer diffusion backbone computation pathway."},{"name":"Patch tokens","desc":"将 z_t 分块、线性投影并加入位置编码","name_en":"Patch tokens","desc_en":"Performs Patch tokens within the core transformer diffusion backbone computation pathway."},{"name":"t / class","desc":"时间与类别嵌入生成 adaLN 的 scale、shift、gate","name_en":"t / class","desc_en":"Performs t / class within the core transformer diffusion backbone computation pathway."},{"name":"DiT blocks","desc":"全局 self-attention+MLP；adaLN-Zero 条件化并零初始化残差门","name_en":"DiT blocks","desc_en":"Performs DiT blocks within the core transformer diffusion backbone computation pathway."},{"name":"epsilon / score","desc":"线性头输出每个 latent patch 的噪声预测；原论文 ADM-style 配置还学习方差，epsilon 可按噪声尺度换算为 score","name_en":"epsilon / score","desc_en":"Performs epsilon / score within the core transformer diffusion backbone computation pathway."},{"name":"逆 SDE / ODE","desc":"用 DDPM、DDIM 等 sampler 反复调用 DiT","name_en":"SDE / ODE","desc_en":"Performs SDE / ODE within the core transformer diffusion backbone computation pathway."},{"name":"VAE 解码器","desc":"将去噪 latent 还原为像素图像","name_en":"VAE decoder","desc_en":"Applies VAE decoder to project aggregated representations toward the target task head."},{"name":"生成图像","desc":"最终解码结果","name_en":"Generated Image","desc_en":"Produces predicted noise ε_θ, diagonal covariance σ_θ, or velocity v_θ on the latent token grid via Generated Image."}],"design_principles":["用标准 Transformer token pipeline 替代 U-Net 多尺度卷积主干，把扩散建模转化为可扩展的 patch 序列计算。","adaLN-Zero 将时间和类别条件注入每个 block，并以零门控稳定深网络初始训练。","DiT 是 denoiser/score backbone，不定义独立的前向噪声或 ODE；采样动力学仍由外部 diffusion solver 决定。"],"design_principles_en":["Core Hypothesis: Tokenize latent feature maps into patches and process them through standard Transformer blocks modulated by scale/shift/gate parameters regressed from (t, c).","Architectural Delta: adaLN-Zero initialization (initializing each residual block as exact identity) + predictable Gflops scaling laws improving FID monotonically with compute.","Mathematical Formalism: Patchified Latent Diffusion Transformer Conditioned via Zero-Initialized Adaptive LayerNorm."],"med_apps":["适合多模态 token 条件和 3D patch 研究，可与文本、报告或解剖标签统一接口。","3D token 数量和训练数据规模增长快；全局生成指标也可能掩盖微小结构和定量信号损失。"],"med_apps_en":["Clinical Translation: Backbone of choice for scalable 3D volumetric latent diffusion, spatio-temporal video generation, and multimodal medical synthesis.","Evidence & Safety Boundary: Major generative backbone shift; requires well-trained 3D/2D VAEs and large training cohorts to justify Transformer compute."],"attrs":{"上一代瓶颈":"U-Net diffusion 的扩展规律和多模态 token 接口有限","核心想法":"将 latent image patch 化，用 Transformer blocks 与 adaptive LayerNorm 做 diffusion backbone","关键改进":"以模型规模和计算量系统提升生成质量，条件以 adaLN 注入","医学适配":"适合医学多模态、3D patch 和 report/image cross-attention 研究","适用范围与证据":"生成 backbone 重要演化；3D token、数据规模和微小结构仍是风险"},"attrs_en":{"上一代瓶颈":"Convolutional U-Net inductive biases plateaued under massive compute scaling and lacked a uniform token interface across modalities.","核心想法":"Tokenize latent feature maps into patches and process them through standard Transformer blocks modulated by scale/shift/gate parameters regressed from (t, c).","关键改进":"adaLN-Zero initialization (initializing each residual block as exact identity) + predictable Gflops scaling laws improving FID monotonically with compute.","医学适配":"Backbone of choice for scalable 3D volumetric latent diffusion, spatio-temporal video generation, and multimodal medical synthesis.","适用范围与证据":"Major generative backbone shift; requires well-trained 3D/2D VAEs and large training cohorts to justify Transformer compute."},"paper_title":"Scalable Diffusion Models with Transformers","paper_url":"https://openaccess.thecvf.com/content/ICCV2023/html/Peebles_Scalable_Diffusion_Models_with_Transformers_ICCV_2023_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/facebookresearch/DiT","has_code":true,"image":"assets/59b64107d0502a0de70e.avif"},{"id":"architecture_model_066_spatial_transformer_network","num":66,"num_str":"066","year":2015,"year_str":"2015","venue":"NeurIPS","venue_group":"ml","era_group":"era1","title":"Spatial Transformer Network","family_id":"models_registration_geometry","family_code":"13","family_short":"可微配准与投影几何","family_en":"Registration & SE(3)","family_icon":"XIII","family_label":"配准与投影几何：可微变换、拓扑约束和 SE(3) 闭环","archetype":"differentiable_coordinate_warp","archetype_en":"differentiable_coordinate_warp","accent":"#1F4E79","fig_badge":"Figure 2 · PDF p.3","fig_href":"https://proceedings.neurips.cc/paper/2015/hash/33ceb07bf4eeb3da587e268d663aba1a-Abstract.html","core_mech":"定位网络预测变换参数，grid generator 与可微 sampler 将任务梯度传回几何坐标。","core_mech_en":"Predicts geometric transformation parameters θ via a localization network, generates a transformed sampling grid, and warps feature maps via a differentiable sampler.","input_desc":"输入特征图/图像 U","input_en":"Input image or feature map U","output_desc":"按学习变换重采样后的 V","output_en":"Spatially warped feature map V resampled over learned coordinates T_θ(G)","form_title":"核心公式 · 可学习坐标变换与双线性采样","form_title_en":"Core Formalism · Differentiable Coordinate Grid Generation & Bilinear/Trilinear Image Sampling","nodes":[{"name":"输入 U","desc":"图像或中间特征图","name_en":"input U","desc_en":"Ingests input image or feature map u and prepares initial tensor representations (input U)."},{"name":"定位网络","desc":"CNN/MLP 从 U 预测变换参数","name_en":"Localization Network","desc_en":"Executes Localization Network to extract primary structural features and establish spatial/sequence encoding."},{"name":"参数 theta","desc":"仿射、TPS 等低维几何参数","name_en":"theta","desc_en":"Performs theta within the core differentiable coordinate warp computation pathway."},{"name":"网格生成器","desc":"对每个输出坐标计算其输入采样位置 T_theta(G)","name_en":"Grid Generator","desc_en":"Performs Grid Generator within the core differentiable coordinate warp computation pathway."},{"name":"可微采样器","desc":"双线性插值；梯度可传至输入与 theta","name_en":"Differentiable Sampler","desc_en":"Performs Differentiable Sampler within the core differentiable coordinate warp computation pathway."},{"name":"变换后 V","desc":"与下游网络尺寸约定一致的重采样结果","name_en":"Stage 06","desc_en":"Applies Stage 06 to project aggregated representations toward the target task head."},{"name":"下游损失","desc":"分类/配准等任务损失反传到定位网络","name_en":"loss","desc_en":"Produces spatially warped feature map v resampled over learned coordinates t_θ(g) via loss."}],"design_principles":["将坐标变换与插值写成可微模块，使几何参数能由最终任务损失端到端学习。","采用 inverse sampling：逐输出位置查询输入，可避免 forward splat 的空洞。","STN 只提供可微 warping，不自动保证变换平滑、可逆、无 folding 或符合解剖。"],"design_principles_en":["Core Hypothesis: Formulate coordinate transformation and sub-pixel bilinear/trilinear interpolation as an explicit, sub-differentiable neural module.","Architectural Delta: Sub-gradients with respect to sampling grid coordinates allow upstream networks to learn affine, projective, or thin-plate-spline warps end-to-end.","Mathematical Formalism: Differentiable Coordinate Grid Generation & Bilinear/Trilinear Image Sampling."],"med_apps":["是 VoxelMorph、可微配准、ROI 对齐和 2D/3D warping 的基础算子。","医学形变需要另加平滑、Jacobian、边界或拓扑约束；仅靠下游分类损失可能学到非物理裁剪。"],"med_apps_en":["Clinical Translation: Provides the foundational differentiable warping operator (`grid_sample`) underlying VoxelMorph and all modern learned medical registration.","Evidence & Safety Boundary: Essential differentiable geometry primitive; requires explicit regularization when generalized from low-DOF affine to dense displacement fields."],"attrs":{"上一代瓶颈":"普通 CNN 无法对采样坐标和几何变换端到端求导","核心想法":"用 localization network、grid generator 与可微 sampler 学习空间变换","关键改进":"把重采样写成可微算子，使下游 loss 可反传到变换参数","医学适配":"成为 VoxelMorph、可微配准和 2D/3D warping 的算子基础","适用范围与证据":"基础设施；本身不保证变换平滑、可逆或物理合理"},"attrs_en":{"上一代瓶颈":"Standard CNN pooling offered only tiny local translation invariance and could not differentiate through spatial coordinate warping.","核心想法":"Formulate coordinate transformation and sub-pixel bilinear/trilinear interpolation as an explicit, sub-differentiable neural module.","关键改进":"Sub-gradients with respect to sampling grid coordinates allow upstream networks to learn affine, projective, or thin-plate-spline warps end-to-end.","医学适配":"Provides the foundational differentiable warping operator (`grid_sample`) underlying VoxelMorph and all modern learned medical registration.","适用范围与证据":"Essential differentiable geometry primitive; requires explicit regularization when generalized from low-DOF affine to dense displacement fields."},"paper_title":"Spatial Transformer Networks","paper_url":"https://proceedings.neurips.cc/paper/2015/hash/33ceb07bf4eeb3da587e268d663aba1a-Abstract.html","code_label":"未提供官方实现","code_url":"","has_code":false,"image":"assets/098c6725bae0921f58aa.avif"},{"id":"architecture_model_067_voxelmorph","num":67,"num_str":"067","year":2019,"year_str":"2019","venue":"IEEE Transactions on Medical Imaging","venue_group":"journal","era_group":"era2","title":"VoxelMorph","family_id":"models_registration_geometry","family_code":"13","family_short":"可微配准与投影几何","family_en":"Registration & SE(3)","family_icon":"XIII","family_label":"配准与投影几何：可微变换、拓扑约束和 SE(3) 闭环","archetype":"amortized_dense_registration","archetype_en":"amortized_dense_registration","accent":"#1F4E79","fig_badge":"Figure 3 · PDF p.4","fig_href":"https://pubmed.ncbi.nlm.nih.gov/30716034/","core_mech":"3D U-Net 一次前向预测 dense displacement，并用可微 warping、图像相似度和平滑项无监督训练。","core_mech_en":"Amortizes pairwise 3D deformable registration into a single U-Net forward pass predicting a dense displacement field u trained unsupervised via image similarity and diffusion smoothness.","input_desc":"移动图像 m 与固定图像 f","input_en":"Pair of 3D moving volume m and fixed volume f","output_desc":"稠密形变 phi 及配准图像 m∘phi","output_en":"Dense 3D deformation field φ = Id + u (or velocity field integrated via scaling-and-squaring) and warped volume m ∘ φ","form_title":"核心公式 · 摊销形变预测的相似度与平滑目标","form_title_en":"Core Formalism · Unsupervised Amortized Deformation Prediction: L_sim(f, m ∘ φ) + λ ||∇u||²","nodes":[{"name":"m 与 f","desc":"同维度 2D/3D moving/fixed image pair","name_en":"m f","desc_en":"Ingests pair of 3d moving volume m and fixed volume f and prepares initial tensor representations (m f)."},{"name":"通道拼接","desc":"把 m、f 作为联合输入，不依赖真实位移标签","name_en":"Channel Concatenation","desc_en":"Executes Channel Concatenation to extract primary structural features and establish spatial/sequence encoding."},{"name":"3D U-Net","desc":"encoder-decoder 提取多尺度对应与形变上下文","name_en":"3D U-Net","desc_en":"Performs 3D U-Net within the core amortized dense registration computation pathway."},{"name":"位移场 u","desc":"卷积头一次前向预测每体素 displacement；phi=Id+u","name_en":"Displacement Field u","desc_en":"Performs Displacement Field u within the core amortized dense registration computation pathway."},{"name":"空间变换器","desc":"可微插值计算 m∘phi","name_en":"Spatial Transformer","desc_en":"Performs Spatial Transformer within the core amortized dense registration computation pathway."},{"name":"图像相似度","desc":"NCC/MSE 等无监督数据项比较 m∘phi 与 f","name_en":"Image Similarity Loss","desc_en":"Performs Image Similarity Loss within the core amortized dense registration computation pathway."},{"name":"平滑正则","desc":"惩罚位移空间梯度，控制局部粗糙与 folding 风险","name_en":"Smoothness Regularizer","desc_en":"Applies Smoothness Regularizer to project aggregated representations toward the target task head."},{"name":"配准结果","desc":"phi 与 warped moving image","name_en":"Registered Output","desc_en":"Produces dense 3d deformation field φ = id + u (or velocity field integrated via scaling-and-squaring) and warped volume m ∘ φ via Registered Output."}],"design_principles":["用训练集学习从图像对到形变场的映射，把逐病例优化摊销为一次网络前向。","相似度损失提供无配准标签监督，可微 warper 把误差传回位移预测。","平滑正则只鼓励局部平滑；基础版本不严格保证微分同胚或逆一致。"],"design_principles_en":["Core Hypothesis: Train a 3D convolutional U-Net over a population of scans to predict the dense deformation field in sub-second GPU inference without ground-truth warps.","Architectural Delta: Amortized U-Net displacement/velocity prediction + Spatial Transformer warping + unsupervised LNCC/MSE + anatomical segmentation Dice auxiliary loss.","Mathematical Formalism: Unsupervised Amortized Deformation Prediction: L_sim(f, m ∘ φ) + λ ||∇u||²."],"med_apps":["适合 CT/MRI 大批量快速 deformable registration，并作为学习式配准的通用基线。","跨模态强度不对应、切除/肿瘤变化和域移位会误导相似度；需报告 folding/Jacobian 与病理保持。"],"med_apps_en":["Clinical Translation: Foundational fast learning-based baseline for brain MRI, chest CT inspiration–expiration, and longitudinal registration.","Evidence & Safety Boundary: Core registration infrastructure; simple gradient smoothing does not strictly prevent topological folding (|J_φ| ≤ 0) under large deformations."],"attrs":{"上一代瓶颈":"经典 deformable registration 每对病例都需迭代优化，速度慢","核心想法":"3D U-Net 接收固定/移动图像并一次 forward 预测 dense displacement","关键改进":"以图像相似度加平滑正则做无监督 amortized registration","医学适配":"成为 CT/MRI 快速配准最常用的学习式基线","适用范围与证据":"基础设施级 baseline；跨域、相似度选择和 folding 仍是问题"},"attrs_en":{"上一代瓶颈":"Classical iterative deformable registration (ANTs/SyN, Elastix) optimized every image pair from scratch, taking minutes to hours on CPU.","核心想法":"Train a 3D convolutional U-Net over a population of scans to predict the dense deformation field in sub-second GPU inference without ground-truth warps.","关键改进":"Amortized U-Net displacement/velocity prediction + Spatial Transformer warping + unsupervised LNCC/MSE + anatomical segmentation Dice auxiliary loss.","医学适配":"Foundational fast learning-based baseline for brain MRI, chest CT inspiration–expiration, and longitudinal registration.","适用范围与证据":"Core registration infrastructure; simple gradient smoothing does not strictly prevent topological folding (|J_φ| ≤ 0) under large deformations."},"paper_title":"VoxelMorph: A Learning Framework for Deformable Medical Image Registration","paper_url":"https://pubmed.ncbi.nlm.nih.gov/30716034/","code_label":"作者/机构官方实现","code_url":"https://github.com/voxelmorph/voxelmorph","has_code":true,"image":"assets/e1fb4b9da829eaf29178.avif"},{"id":"architecture_model_068_gradicon","num":68,"num_str":"068","year":2023,"year_str":"2023","venue":"CVPR","venue_group":"cv","era_group":"era4","title":"GradICON","family_id":"models_registration_geometry","family_code":"13","family_short":"可微配准与投影几何","family_en":"Registration & SE(3)","family_icon":"XIII","family_label":"配准与投影几何：可微变换、拓扑约束和 SE(3) 闭环","archetype":"bidirectional_gradient_inverse_consistent_registration","archetype_en":"bidirectional_gradient_inverse_consistent_registration","accent":"#1F4E79","fig_badge":"Figure 2 · PDF p.5","fig_href":"https://openaccess.thecvf.com/content/CVPR2023/html/Tian_GradICON_Approximate_Diffeomorphisms_via_Gradient_Inverse_Consistency_CVPR_2023_paper.html","core_mech":"通过双向预测与复合映射 Jacobian 的 gradient inverse-consistency 正则获得近似微分同胚。","core_mech_en":"Enforces diffeomorphic regularity without tuning sensitive multi-scale smoothness weights by penalizing the Frobenius norm of the composed forward–backward Jacobian deviation from identity.","input_desc":"图像 A 与图像 B","input_en":"Ordered pairs (I^A, I^B) and (I^B, I^A) fed symmetrically to a registration network","output_desc":"近似互逆、规则的双向配准映射 Phi_AB 与 Phi_BA","output_en":"Approximately diffeomorphic, inverse-consistent forward map Φ^AB and backward map Φ^BA","form_title":"核心公式 · 复合映射梯度的双向逆一致性","form_title_en":"Core Formalism · Gradient Inverse Consistency Regularizer: ||∇(Φ^AB ∘ Φ^BA)(x) − I||_F²","nodes":[{"name":"图像 A/B","desc":"交换顺序后分别预测两个方向","name_en":"A/B","desc_en":"Ingests ordered pairs (i^a, i^b) and (i^b, i^a) fed symmetrically to a registration network and prepares initial tensor representations (A/B)."},{"name":"共享配准网络","desc":"多尺度卷积网络 g_theta 对两个方向复用权重","name_en":"registration","desc_en":"Executes registration to extract primary structural features and establish spatial/sequence encoding."},{"name":"Phi_AB","desc":"将 A 的坐标映射到 B 的预测变换","name_en":"Phi_AB","desc_en":"Performs Phi_AB within the core bidirectional gradient inverse consistent registration computation pathway."},{"name":"Phi_BA","desc":"交换输入得到的反向预测变换","name_en":"Phi_BA","desc_en":"Performs Phi_BA within the core bidirectional gradient inverse consistent registration computation pathway."},{"name":"双向 warping","desc":"计算 A∘Phi_AB、B∘Phi_BA 并评估图像匹配","name_en":"Bidirectional Warping","desc_en":"Performs Bidirectional Warping within the core bidirectional gradient inverse consistent registration computation pathway."},{"name":"映射复合","desc":"Phi_AB∘Phi_BA 与 Phi_BA∘Phi_AB 应接近 identity","name_en":"Stage 06","desc_en":"Performs Stage 06 within the core bidirectional gradient inverse consistent registration computation pathway."},{"name":"复合 Jacobian","desc":"对复合映射求空间梯度/Jacobian，而非只比较位移值","name_en":"Composed Jacobian","desc_en":"Performs Composed Jacobian within the core bidirectional gradient inverse consistent registration computation pathway."},{"name":"GradICON 损失","desc":"惩罚 ∇(Phi_AB∘Phi_BA)-I 及反向项，并结合图像相似度","name_en":"GradICON loss","desc_en":"Applies GradICON loss to project aggregated representations toward the target task head."},{"name":"双向形变","desc":"近似 inverse-consistent 的配准场与 warped images","name_en":"Bidirectional Deformation","desc_en":"Produces approximately diffeomorphic, inverse-consistent forward map φ^ab and backward map φ^ba via Bidirectional Deformation."}],"design_principles":["同时预测正反变换，并要求两者复合的局部导数接近单位变换。","对 inverse-consistency 误差的空间梯度进行约束，比只最小化复合位移更关注局部形变结构。","近似 inverse consistency 改善规则性，但不等同于数学上处处保证正 Jacobian 的严格微分同胚。"],"design_principles_en":["Core Hypothesis: Penalize the spatial gradient (Jacobian) of the composed forward–backward transformation relative to the identity matrix I via first-order Taylor expansion.","Architectural Delta: First-order Gradient Inverse Consistency (GradICON) loss yielding near-zero folding and fast convergence across multi-step cascades.","Mathematical Formalism: Gradient Inverse Consistency Regularizer: ||∇(Φ^AB ∘ Φ^BA)(x) − I||_F²."],"med_apps":["适合跨数据集的器官 CT/MRI 配准，并提供比单纯平滑位移更直接的折叠控制信号。","切除、病灶出现/消失和强模态差异没有真实一一对应，强制可逆仍可能产生不合理拉伸。"],"med_apps_en":["Clinical Translation: Provides a highly regular, topology-preserving 3D registration baseline across brain MRI, lung CT, and abdominal scans.","Evidence & Safety Boundary: Superior theoretical and empirical regularity over raw smoothness penalties; space-occupying tumors without topological correspondence still require special handling."],"attrs":{"上一代瓶颈":"单纯平滑位移会过度平滑，直接 inverse-consistency 优化不稳","核心想法":"同时预测正反变换并惩罚复合映射 Jacobian 偏离单位阵","关键改进":"用逆一致性的梯度结构获得规则、近似微分同胚的变换","医学适配":"在多数据集统一 protocol 上提供强通用配准基线","适用范围与证据":"比单纯换 encoder 更具长期价值；仍需病理保持和极端域移位验证"},"attrs_en":{"上一代瓶颈":"Penalizing displacement norm ||Φ^AB(Φ^BA(x)) − x||² required tedious hyperparameter schedules and still permitted local Jacobian folding.","核心想法":"Penalize the spatial gradient (Jacobian) of the composed forward–backward transformation relative to the identity matrix I via first-order Taylor expansion.","关键改进":"First-order Gradient Inverse Consistency (GradICON) loss yielding near-zero folding and fast convergence across multi-step cascades.","医学适配":"Provides a highly regular, topology-preserving 3D registration baseline across brain MRI, lung CT, and abdominal scans.","适用范围与证据":"Superior theoretical and empirical regularity over raw smoothness penalties; space-occupying tumors without topological correspondence still require special handling."},"paper_title":"GradICON: Approximate Diffeomorphisms via Gradient Inverse Consistency","paper_url":"https://openaccess.thecvf.com/content/CVPR2023/html/Tian_GradICON_Approximate_Diffeomorphisms_via_Gradient_Inverse_Consistency_CVPR_2023_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/uncbiag/ICON","has_code":true,"image":"assets/07598dd1edabdd73aa9a.avif"},{"id":"architecture_model_069_unigradicon","num":69,"num_str":"069","year":2024,"year_str":"2024","venue":"MICCAI","venue_group":"miccai","era_group":"era4","title":"uniGradICON","family_id":"models_registration_geometry","family_code":"13","family_short":"可微配准与投影几何","family_en":"Registration & SE(3)","family_icon":"XIII","family_label":"配准与投影几何：可微变换、拓扑约束和 SE(3) 闭环","archetype":"universal_registration_foundation_model","archetype_en":"universal_registration_foundation_model","accent":"#1F4E79","fig_badge":"Official repository src/unigradicon/__init__.py, lines 218–232 · PDF p.Repository source lines 218–232","fig_href":"https://github.com/uncbiag/uniGradICON/blob/3e83a9268b09308660c4857c7956f895c1b4b7c3/src/unigradicon/__init__.py#L218-L232","core_mech":"将 GradICON 在异质多数据集上联合训练为单一通用注册器，支持 zero-shot 与目标域微调。","core_mech_en":"Trains a single multi-step GradICON architecture jointly across heterogeneous multi-organ, multi-modality datasets to serve as a zero-shot registration foundation model.","input_desc":"来自多解剖、多模态、多数据集的 moving/fixed 图像对","input_en":"3D fixed/moving volume pair from any anatomical region or modality (zero-shot or rapid fine-tuning)","output_desc":"新任务上的 zero-shot 或微调双向形变","output_en":"Diffeomorphic bidirectional deformation fields Φ^AB, Φ^BA","form_title":"核心公式 · 跨数据集共享的相似度与 GradICON 目标","form_title_en":"Core Formalism · Multi-Dataset Composite Similarity & Gradient Inverse Consistency Foundation Training","nodes":[{"name":"多域训练对","desc":"联合采样不同器官、模态、分辨率和数据集的图像对","name_en":"training","desc_en":"Ingests 3d fixed/moving volume pair from any anatomical region or modality (zero-shot or rapid fine-tuning) and prepares initial tensor representations (training)."},{"name":"统一空间接口","desc":"按共同张量/坐标约定重采样和强度预处理","name_en":"spatial","desc_en":"Executes spatial to extract primary structural features and establish spatial/sequence encoding."},{"name":"共享 GradICON","desc":"单一跨任务卷积配准网络学习通用对应与形变先验","name_en":"GradICON","desc_en":"Performs GradICON within the core universal registration foundation model computation pathway."},{"name":"Phi_MF","desc":"moving→fixed 的预测映射","name_en":"Phi_MF","desc_en":"Performs Phi_MF within the core universal registration foundation model computation pathway."},{"name":"Phi_FM","desc":"交换输入得到 fixed→moving 映射","name_en":"Phi_FM","desc_en":"Performs Phi_FM within the core universal registration foundation model computation pathway."},{"name":"任务相似度","desc":"按训练协议比较双向 warped images；跨模态度量决定可学对应","name_en":"Stage 06","desc_en":"Performs Stage 06 within the core universal registration foundation model computation pathway."},{"name":"GradICON 正则","desc":"复合映射梯度接近 identity，保持共享模型的规则性","name_en":"GradICON regularization","desc_en":"Performs GradICON regularization within the core universal registration foundation model computation pathway."},{"name":"Zero-shot","desc":"未见任务直接一次前向预测，无需病例级优化","name_en":"Zero-shot","desc_en":"Performs Zero-shot within the core universal registration foundation model computation pathway."},{"name":"可选微调","desc":"在目标域少量数据上更新模型以适配细结构/模态","name_en":"fine-tuning","desc_en":"Applies fine-tuning to project aggregated representations toward the target task head."},{"name":"通用配准","desc":"双向形变与 warped image","name_en":"registration","desc_en":"Produces diffeomorphic bidirectional deformation fields φ^ab, φ^ba via registration."}],"design_principles":["通过多任务联合训练把器官、模态和形变统计汇总到单一共享注册器，而非每任务单独训练。","保留 GradICON 的双向复合梯度约束，使规模扩展不丢失核心几何正则。","foundation model 在此指跨训练任务 zero-shot/可微调能力，不表示覆盖所有临床域。"],"design_principles_en":["Core Hypothesis: Unify diverse public 3D registration cohorts (brain, lung, abdomen, knee; CT & MRI) under a single GradICON training objective.","Architectural Delta: Demonstrates that a single frozen registration weight set achieves strong out-of-the-box zero-shot accuracy on unseen anatomical domains and fast one-shot adaptation.","Mathematical Formalism: Multi-Dataset Composite Similarity & Gradient Inverse Consistency Foundation Training."],"med_apps":["可作为多器官、多模态注册的统一初始化或基线，减少每个新任务重新训练的成本。","未覆盖的儿科、术后、植入物或极端病理仍可能失效；需按目标域报告 landmark、Jacobian 和病理保持。"],"med_apps_en":["Clinical Translation: First credible, open-weight foundation model for 3D medical deformable image registration.","Evidence & Safety Boundary: Rapidly advancing registration foundation baseline; extreme cross-modality contrasts (e.g., ultrasound-to-MRI) still benefit from domain adaptation."],"attrs":{"上一代瓶颈":"task-specific registration 网络迁移到新器官或模态时脆弱","核心想法":"在多解剖、多模态、多数据集联合训练 GradICON，支持 zero-shot 与微调","关键改进":"共享跨任务的对应特征与形变先验，同时保留 inverse consistency","医学适配":"是 registration foundation model 的早期可信实例","适用范围与证据":"高速发展；尚未覆盖所有临床域和细结构"},"attrs_en":{"上一代瓶颈":"Conventional learning-based registration required training a separate network for every organ, modality, and FOV.","核心想法":"Unify diverse public 3D registration cohorts (brain, lung, abdomen, knee; CT & MRI) under a single GradICON training objective.","关键改进":"Demonstrates that a single frozen registration weight set achieves strong out-of-the-box zero-shot accuracy on unseen anatomical domains and fast one-shot adaptation.","医学适配":"First credible, open-weight foundation model for 3D medical deformable image registration.","适用范围与证据":"Rapidly advancing registration foundation baseline; extreme cross-modality contrasts (e.g., ultrasound-to-MRI) still benefit from domain adaptation."},"paper_title":"uniGradICON: A Foundation Model for Medical Image Registration","paper_url":"https://papers.miccai.org/miccai-2024/816-Paper0527.html","code_label":"作者/机构官方实现","code_url":"https://github.com/uncbiag/uniGradICON","has_code":true,"image":"assets/0998f5b5a469a6a22393.avif"},{"id":"architecture_model_070_diffpose","num":70,"num_str":"070","year":2024,"year_str":"2024","venue":"CVPR","venue_group":"cv","era_group":"era4","title":"DiffPose","family_id":"models_registration_geometry","family_code":"13","family_short":"可微配准与投影几何","family_en":"Registration & SE(3)","family_icon":"XIII","family_label":"配准与投影几何：可微变换、拓扑约束和 SE(3) 闭环","archetype":"differentiable_2d3d_pose_registration","archetype_en":"differentiable_2d3d_pose_registration","accent":"#1F4E79","fig_badge":"Figure 2 · PDF p.3","fig_href":"https://openaccess.thecvf.com/content/CVPR2024/html/Gopalakrishnan_Intraoperative_2D3D_Image_Registration_via_Differentiable_X-ray_Rendering_CVPR_2024_paper.html","core_mech":"合成 DRR 训练的 pose initializer 与可微 X-ray renderer 驱动的 SE(3) 测试时优化闭环结合。","core_mech_en":"Couples a patient-specific SE(3) pose initializer (trained self-supervised on synthetic DRRs) with test-time gradient optimization through a differentiable X-ray ray-casting renderer.","input_desc":"术前 CT 体 V、术中 2D X-ray y、投影标定参数","input_en":"Preoperative 3D CT volume V, intraoperative 2D X-ray fluoroscopy image y, and C-arm intrinsic calibration","output_desc":"CT 到 X-ray 的刚体 SE(3) 位姿 T_hat","output_en":"Sub-millimeter 6-DoF rigid pose T̂ ∈ SE(3) aligning preoperative CT to intraoperative X-ray","form_title":"核心公式 · 可微 DRR 相似度驱动的 SE(3) 位姿更新","form_title_en":"Core Formalism · Geodesic SE(3) Pose Initialization + Differentiable DRR Multiscale LNCC Refinement","nodes":[{"name":"术前 CT","desc":"带物理空间信息的 3D attenuation volume","name_en":"Preoperative 3D CT","desc_en":"Ingests preoperative 3d ct volume v, intraoperative 2d x-ray fluoroscopy image y, and c-arm intrinsic calibration and prepares initial tensor representations (Preoperative 3D CT)."},{"name":"术中 X-ray","desc":"单幅目标透视图及已知/估计内外参","name_en":"Intraoperative 2D X-Ray","desc_en":"Executes Intraoperative 2D X-Ray to extract primary structural features and establish spatial/sequence encoding."},{"name":"合成 DRR 对","desc":"从 CT 随机采样 pose 渲染训练图像，提供已知相对位姿","name_en":"Synthetic DRR Pairs","desc_en":"Performs Synthetic DRR Pairs within the core differentiable 2d3d pose registration computation pathway."},{"name":"Pose 回归器","desc":"从 X-ray/DRR 特征预测测试时优化的初始 T0","name_en":"Pose","desc_en":"Performs Pose within the core differentiable 2d3d pose registration computation pathway."},{"name":"SE(3) 参数","desc":"用 Lie algebra/geodesic 几何更新旋转和平移","name_en":"SE(3","desc_en":"Performs SE(3 within the core differentiable 2d3d pose registration computation pathway."},{"name":"可微 X-ray 渲染","desc":"按 T 对 CT 做射线积分，生成 DRR(T) 并对 pose 求梯度","name_en":"Differentiable X-Ray Rendering","desc_en":"Performs Differentiable X-Ray Rendering within the core differentiable 2d3d pose registration computation pathway."},{"name":"稀疏多尺度 LNCC","desc":"比较 DRR(T) 与真实 X-ray 的局部归一化相关","name_en":"multi-scale LNCC","desc_en":"Performs multi-scale LNCC within the core differentiable 2d3d pose registration computation pathway."},{"name":"测试时优化","desc":"从 T0 反传图像相似度，迭代更新 SE(3) pose","name_en":"Test-Time Optimization","desc_en":"Applies Test-Time Optimization to project aggregated representations toward the target task head."},{"name":"T_hat","desc":"收敛后的 2D/3D 刚体配准","name_en":"T_hat","desc_en":"Produces sub-millimeter 6-dof rigid pose t̂ ∈ se(3) aligning preoperative ct to intraoperative x-ray via T_hat."}],"design_principles":["学习回归器扩大捕获范围，可微物理渲染在测试时用真实目标图像闭环精修。","SE(3) 几何把旋转和平移更新限制在合法刚体变换上，而非回归任意 6 个独立数。","多尺度局部相似度提高弱重叠下的优化可用性，但仍依赖正确投影标定和成像外观。"],"design_principles_en":["Core Hypothesis: Generate synthetic DRRs across SE(3) for a patient's preoperative CT to train a rapid pose regressor, then refine the estimate at test time via differentiable DRR gradients.","Architectural Delta: Double-geodesic SE(3) loss + sparse patch-based differentiable rendering accelerating test-time optimization to sub-second latency.","Mathematical Formalism: Geodesic SE(3) Pose Initialization + Differentiable DRR Multiscale LNCC Refinement."],"med_apps":["适用于术中 X-ray 与术前 CT 对齐，可服务导航、植入物定位和解剖覆盖确认。","散射、金属、器械遮挡、错误标定和真实软组织变形会破坏 DRR–X-ray 对应并形成错误局部极值。"],"med_apps_en":["Clinical Translation: Enables accurate intraoperative 2D X-ray to 3D CT registration for orthopedic, spinal, and endovascular image-guided surgery.","Evidence & Safety Boundary: Exemplary hybrid learning + projective physics loop; requires accurate C-arm calibration and robustness to surgical tool occlusion."],"attrs":{"上一代瓶颈":"直接 pose regression 跨病人/视角泛化差，纯优化捕获范围有限","核心想法":"用合成 DRR 自监督 pose regressor 初始化，再以可微 X-ray renderer 和 SE(3) 几何测试时优化","关键改进":"学习初始化、真实投影 forward model、geodesic pose 与 sparse multiscale LNCC 闭环","医学适配":"用于术中 X-ray 到术前 CT 的 2D/3D 配准","适用范围与证据":"几何融合范式价值高；标定、散射、金属和外部设备仍会致败"},"attrs_en":{"上一代瓶颈":"Direct CNN pose regression generalized poorly outside training poses, while pure gradient-based DRR optimization had a narrow capture range.","核心想法":"Generate synthetic DRRs across SE(3) for a patient's preoperative CT to train a rapid pose regressor, then refine the estimate at test time via differentiable DRR gradients.","关键改进":"Double-geodesic SE(3) loss + sparse patch-based differentiable rendering accelerating test-time optimization to sub-second latency.","医学适配":"Enables accurate intraoperative 2D X-ray to 3D CT registration for orthopedic, spinal, and endovascular image-guided surgery.","适用范围与证据":"Exemplary hybrid learning + projective physics loop; requires accurate C-arm calibration and robustness to surgical tool occlusion."},"paper_title":"Intraoperative 2D/3D Image Registration via Differentiable X-ray Rendering","paper_url":"https://openaccess.thecvf.com/content/CVPR2024/papers/Gopalakrishnan_Intraoperative_2D3D_Image_Registration_via_Differentiable_X-ray_Rendering_CVPR_2024_paper.pdf","code_label":"作者/机构官方实现","code_url":"https://github.com/eigenvivek/DiffPose","has_code":true,"image":"assets/3be6ffd699d13b8efbdf.avif"},{"id":"architecture_model_071_x2ct_gan","num":71,"num_str":"071","year":2019,"year_str":"2019","venue":"CVPR","venue_group":"cv","era_group":"era2","title":"X2CT-GAN","family_id":"models_neural_fields_2d3d","family_code":"14","family_short":"2D→3D 与神经辐射场","family_en":"2D-to-3D & Neural Fields","family_icon":"XIV","family_label":"2D→3D 与神经场：表示能力、投影一致性和不可辨识性","archetype":"biplanar_2d_to_3d_gan","archetype_en":"biplanar_2d_to_3d_gan","accent":"#1F4E79","fig_badge":"Figure 3 · PDF p.3","fig_href":"https://openaccess.thecvf.com/content_CVPR_2019/html/Ying_X2CT-GAN_Reconstructing_CT_From_Biplanar_X-Rays_With_Generative_Adversarial_Networks_CVPR_2019_paper.html","core_mech":"双正交 2D 编码器将特征提升并融合到 3D，再以体素重建和 3D adversarial loss 联合监督。","core_mech_en":"Lifts features from two orthogonal (bi-planar PA + lateral) 2D chest X-rays into 3D via backprojection-inspired feature expansion and cross-view fusion supervised by 3D voxel + GAN losses.","input_desc":"正位与侧位两幅正交 X-ray","input_en":"Pair of orthogonal posterior–anterior (PA) and lateral 2D chest radiographs","output_desc":"端到端生成的 3D CT 体","output_en":"Synthesized 3D volumetric chest CT tensor","form_title":"核心公式 · 双视图特征提升与 3D 对抗重建","form_title_en":"Core Formalism · Bi-Planar 2D-to-3D Feature Lifting, Orthogonal Fusion & 3D Adversarial Reconstruction","nodes":[{"name":"双平面 X-ray","desc":"两幅近正交投影提供互补但仍不充分的 3D 信息","name_en":"X-ray","desc_en":"Ingests pair of orthogonal posterior–anterior (pa) and lateral 2d chest radiographs and prepares initial tensor representations (X-ray)."},{"name":"双 2D 编码器","desc":"各视图独立提取多尺度投影特征","name_en":"2D encoder","desc_en":"Executes 2D encoder to extract primary structural features and establish spatial/sequence encoding."},{"name":"2D→3D 提升","desc":"将视图特征 reshape/扩展到体素特征块","name_en":"2D→3D","desc_en":"Performs 2D→3D within the core biplanar 2d to 3d gan computation pathway."},{"name":"跨视图融合","desc":"在共享 3D 坐标中拼接或融合两方向特征","name_en":"fusion","desc_en":"Performs fusion within the core biplanar 2d to 3d gan computation pathway."},{"name":"3D 解码器","desc":"3D 上采样/卷积逐级生成完整体积","name_en":"3D decoder","desc_en":"Performs 3D decoder within the core biplanar 2d to 3d gan computation pathway."},{"name":"预测 CT","desc":"体素强度输出 x_hat","name_en":"prediction CT","desc_en":"Performs prediction CT within the core biplanar 2d to 3d gan computation pathway."},{"name":"体素重建损失","desc":"MSE/L1 等与配对真实 CT 比较，约束患者级内容","name_en":"voxel reconstruction loss","desc_en":"Performs voxel reconstruction loss within the core biplanar 2d to 3d gan computation pathway."},{"name":"3D 判别器","desc":"对抗损失推动局部体纹理接近真实 CT 分布","name_en":"3D discriminator","desc_en":"Applies 3D discriminator to project aggregated representations toward the target task head."},{"name":"3D CT","desc":"融合重建与 adversarial supervision 的生成结果","name_en":"3D CT","desc_en":"Produces synthesized 3d volumetric chest ct tensor via 3D CT."}],"design_principles":["双视图分别编码后在 3D 特征空间融合，比单视图提供更多深度约束，但问题仍高度欠定。","2D-to-3D feature lifting 让 generator 可直接输出体素网格，而非逐切片预测。","体素损失约束配对内容，对抗损失改善分布外观；后者可能以逼真纹理掩盖患者级错误。"],"design_principles_en":["Core Hypothesis: Encode PA and lateral radiographs via parallel 2D DenseNet-like encoders, expand 2D feature maps along the orthogonal depth axes, and fuse them inside a 3D decoder.","Architectural Delta: View-specific 2D-to-3D feature liftingconnections + bi-planar orthogonal fusion + 3D PatchGAN + projection consistency losses.","Mathematical Formalism: Bi-Planar 2D-to-3D Feature Lifting, Orthogonal Fusion & 3D Adversarial Reconstruction."],"med_apps":["可作为低投影视图到 3D CT 生成研究的历史基线，适合探索粗解剖和规划先验。","没有显式 Beer–Lambert forward consistency 或不确定性时，不应把生成体当作真实诊断 CT 或定量 HU。"],"med_apps_en":["Clinical Translation: Canonical baseline for bi-planar 2D X-ray to 3D CT volumetric lifting.","Evidence & Safety Boundary: Historically important 2D-to-3D baseline; must never be treated as a diagnostic replacement for true CT acquisition due to null-space hallucination."],"attrs":{"上一代瓶颈":"2D 投影到 3D 体积高度欠定，早期方法缺统一端到端表示","核心想法":"将双正交 X-ray 的 2D 特征 reshape/fuse 为 3D CT，并联合 MSE 与 adversarial loss","关键改进":"双视图 encoder、2D-to-3D generation 与跨视图 feature fusion","医学适配":"奠定深度 2D-to-3D CT 生成的历史基线","适用范围与证据":"重要但不唯一；逼真纹理不等于患者真实 anatomy"},"attrs_en":{"上一代瓶颈":"Reconstructing a 3D volume from 1–2 planar X-ray projections is severely ill-posed, and standard 2D networks lack a 3D spatial bottleneck.","核心想法":"Encode PA and lateral radiographs via parallel 2D DenseNet-like encoders, expand 2D feature maps along the orthogonal depth axes, and fuse them inside a 3D decoder.","关键改进":"View-specific 2D-to-3D feature liftingconnections + bi-planar orthogonal fusion + 3D PatchGAN + projection consistency losses.","医学适配":"Canonical baseline for bi-planar 2D X-ray to 3D CT volumetric lifting.","适用范围与证据":"Historically important 2D-to-3D baseline; must never be treated as a diagnostic replacement for true CT acquisition due to null-space hallucination."},"paper_title":"X2CT-GAN: Reconstructing CT from Biplanar X-Rays with Generative Adversarial Networks","paper_url":"https://openaccess.thecvf.com/content_CVPR_2019/html/Ying_X2CT-GAN_Reconstructing_CT_From_Biplanar_X-Rays_With_Generative_Adversarial_Networks_CVPR_2019_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/kylekma/X2CT","has_code":true,"image":"assets/1c22c7b08117f5647659.avif"},{"id":"architecture_model_072_nerf","num":72,"num_str":"072","year":2020,"year_str":"2020","venue":"ECCV","venue_group":"cv","era_group":"era3","title":"NeRF","family_id":"models_neural_fields_2d3d","family_code":"14","family_short":"2D→3D 与神经辐射场","family_en":"2D-to-3D & Neural Fields","family_icon":"XIV","family_label":"2D→3D 与神经场：表示能力、投影一致性和不可辨识性","archetype":"neural_radiance_field","archetype_en":"neural_radiance_field","accent":"#1F4E79","fig_badge":"Figure 7 · PDF p.18","fig_href":"https://arxiv.org/abs/2003.08934","core_mech":"位置编码坐标 MLP 预测连续密度与视角相关颜色，再沿相机射线做可微体渲染。","core_mech_en":"Represents a continuous 3D scene as a 5D coordinate MLP (x,y,z,θ,φ) → (σ, c) with Fourier positional encoding, optimized via differentiable emission–absorption volume rendering.","input_desc":"带相机内外参的多视角 RGB 图像与采样射线","input_en":"3D spatial coordinates x=(x,y,z) and 2D viewing direction d=(θ,φ) along calibrated camera rays","output_desc":"新视角渲染图像及连续密度/颜色场","output_en":"Volume density σ(x), view-dependent RGB radiance c(x,d), and rendered 2D novel views","form_title":"核心公式 · NeRF 发射—吸收体渲染积分","form_title_en":"Core Formalism · Classical Emission–Absorption Volume Rendering Integral Along Camera Rays","nodes":[{"name":"多视角图像","desc":"每个像素对应已知相机原点 o 与方向 d","name_en":"Stage 01","desc_en":"Ingests 3d spatial coordinates x=(x,y,z) and 2d viewing direction d=(θ,φ) along calibrated camera rays and prepares initial tensor representations (Stage 01)."},{"name":"射线采样","desc":"沿 r(t)=o+t d 分层采样 3D 点","name_en":"Ray Sampling","desc_en":"Executes Ray Sampling to extract primary structural features and establish spatial/sequence encoding."},{"name":"位置编码","desc":"将坐标 x 与方向 d 映射到多频 Fourier features","name_en":"Positional Encoding","desc_en":"Performs Positional Encoding within the core neural radiance field computation pathway."},{"name":"密度 MLP","desc":"F_theta(x) 输出体密度 sigma 与中间特征；sigma 与视角无关","name_en":"MLP","desc_en":"Performs MLP within the core neural radiance field computation pathway."},{"name":"颜色头","desc":"结合方向 d 输出视角相关 RGB c(x,d)","name_en":"Stage 05","desc_en":"Performs Stage 05 within the core neural radiance field computation pathway."},{"name":"体渲染积分","desc":"按 transmittance 与 alpha compositing 累积沿射线颜色","name_en":"Volume Rendering Integral","desc_en":"Performs Volume Rendering Integral within the core neural radiance field computation pathway."},{"name":"光度损失","desc":"比较渲染像素与观测 RGB，监督 per-scene field","name_en":"loss","desc_en":"Performs loss within the core neural radiance field computation pathway."},{"name":"场景优化","desc":"反复采样射线并更新 MLP；经典 NeRF 每场景训练","name_en":"optimization","desc_en":"Applies optimization to project aggregated representations toward the target task head."},{"name":"新视角","desc":"从任意相机射线查询连续场并渲染","name_en":"Stage 09","desc_en":"Produces volume density σ(x), view-dependent rgb radiance c(x,d), and rendered 2d novel views via Stage 09."}],"design_principles":["用连续坐标 MLP 表示场景，而非固定分辨率 voxel/mesh；任意位置都可查询。","位置编码提供高频基函数，使 MLP 能拟合细节；方向条件只进入颜色分支。","可微 alpha-compositing 将像素误差反传到整条射线的密度与颜色。"],"design_principles_en":["Core Hypothesis: Encode continuous spatial coordinates with high-frequency sinusoids so a compact MLP memorizes a continuous volumetric density and radiance field.","Architectural Delta: Fourier positional encoding overcoming MLP spectral bias + hierarchical coarse-to-fine stratified ray sampling.","Mathematical Formalism: Classical Emission–Absorption Volume Rendering Integral Along Camera Rays."],"med_apps":["可启发内镜新视角、医学隐式场和稀疏投影场表示。","原始 NeRF 的可见光发射—吸收 RGB 模型不是 X-ray 线积分物理，不能直接解释为衰减系数或 HU。"],"med_apps_en":["Clinical Translation: Catalyzed medical Implicit Neural Representations (INRs), sparse-view CBCT attenuation fields (NAF), and surgical endoscopy scene reconstruction.","Evidence & Safety Boundary: Foundational neural field paradigm; visible-light occlusion/emission rendering must be rewritten into Beer–Lambert transmission for X-ray/CT."],"attrs":{"上一代瓶颈":"离散 voxel/mesh 分辨率固定，novel-view fidelity 受限","核心想法":"连续坐标 MLP 表示密度和视角相关颜色，并沿射线可微体渲染","关键改进":"positional encoding、per-scene optimization 与连续 volumetric rendering","医学适配":"启发稀疏投影 attenuation fields、内镜场建模和医学 INR","适用范围与证据":"场表示基础；原始可见光 alpha-compositing 不能直接当 X-ray 物理"},"attrs_en":{"上一代瓶颈":"Discrete voxel grids scaled cubically in memory, while triangle meshes struggled to optimize complex topology via gradient descent.","核心想法":"Encode continuous spatial coordinates with high-frequency sinusoids so a compact MLP memorizes a continuous volumetric density and radiance field.","关键改进":"Fourier positional encoding overcoming MLP spectral bias + hierarchical coarse-to-fine stratified ray sampling.","医学适配":"Catalyzed medical Implicit Neural Representations (INRs), sparse-view CBCT attenuation fields (NAF), and surgical endoscopy scene reconstruction.","适用范围与证据":"Foundational neural field paradigm; visible-light occlusion/emission rendering must be rewritten into Beer–Lambert transmission for X-ray/CT."},"paper_title":"NeRF: Representing Scenes as Neural Radiance Fields for View Synthesis","paper_url":"https://arxiv.org/abs/2003.08934","code_label":"作者/机构官方实现","code_url":"https://github.com/bmild/nerf","has_code":true,"image":"assets/d84ce484840cb317fdb2.avif"},{"id":"architecture_model_073_naf","num":73,"num_str":"073","year":2022,"year_str":"2022","venue":"MICCAI","venue_group":"miccai","era_group":"era3","title":"NAF","family_id":"models_neural_fields_2d3d","family_code":"14","family_short":"2D→3D 与神经辐射场","family_en":"2D-to-3D & Neural Fields","family_icon":"XIV","family_label":"2D→3D 与神经场：表示能力、投影一致性和不可辨识性","archetype":"neural_attenuation_field_cbct","archetype_en":"neural_attenuation_field_cbct","accent":"#1F4E79","fig_badge":"Figure 1 · PDF p.3","fig_href":"https://conferences.miccai.org/2022/papers/349-Paper0974.html","core_mech":"以 hash-encoded 坐标网络表示 X-ray attenuation，并用 Beer–Lambert 重投影误差逐病例优化。","core_mech_en":"Rewrites NeRF for cone-beam CT by replacing view-dependent emission–absorption with an isotropic X-ray linear attenuation field μ(x) optimized via Beer–Lambert reprojection error and hash encoding.","input_desc":"稀疏视角 CBCT 投影 y、每幅投影的射线几何","input_en":"3D spatial coordinates x along calibrated X-ray source-to-detector rays and sparse 2D CBCT projections y","output_desc":"连续 X-ray attenuation field mu(x) 与可查询 3D 重建","output_en":"Continuous 3D X-ray attenuation coefficient field μ_θ(x) queried at arbitrary voxel grids","form_title":"核心公式 · 衰减场的 Beer–Lambert 重投影一致性","form_title_en":"Core Formalism · Beer–Lambert Logarithmic Line-Integral Reprojection Consistency Over Multi-Resolution Hash Grids","nodes":[{"name":"CBCT 投影","desc":"稀疏视角实测/模拟 X-ray 强度或对数投影","name_en":"CBCT projection","desc_en":"Ingests 3d spatial coordinates x along calibrated x-ray source-to-detector rays and sparse 2d cbct projections y and prepares initial tensor representations (CBCT projection)."},{"name":"锥束射线","desc":"由源—探测器几何确定每像素 3D ray","name_en":"Stage 02","desc_en":"Executes Stage 02 to extract primary structural features and establish spatial/sequence encoding."},{"name":"Hash 编码","desc":"多分辨率 hash grid 编码 3D 坐标以加速高频拟合","name_en":"Hash","desc_en":"Performs Hash within the core neural attenuation field cbct computation pathway."},{"name":"衰减场 MLP","desc":"F_theta(x) 输出非负线性衰减系数 mu(x)，不预测 RGB","name_en":"attenuation field MLP","desc_en":"Performs attenuation field MLP within the core neural attenuation field cbct computation pathway."},{"name":"Beer–Lambert","desc":"沿射线积分 p_hat=∫mu(r(s))ds，再映射为 X-ray 强度/对数投影","name_en":"Beer–Lambert","desc_en":"Performs Beer–Lambert within the core neural attenuation field cbct computation pathway."},{"name":"重投影损失","desc":"比较 p_hat 与输入投影 y，形成 measurement consistency","name_en":"reprojection loss","desc_en":"Performs reprojection loss within the core neural attenuation field cbct computation pathway."},{"name":"射线采样优化","desc":"每病例反复抽射线、积分并更新 field 参数","name_en":"sampling optimization","desc_en":"Performs sampling optimization within the core neural attenuation field cbct computation pathway."},{"name":"体素查询","desc":"在规则 3D 网格采样 mu_theta(x)","name_en":"voxel","desc_en":"Applies voxel to project aggregated representations toward the target task head."},{"name":"3D 衰减体","desc":"连续场或导出的 voxel volume","name_en":"3D","desc_en":"Produces continuous 3d x-ray attenuation coefficient field μ_θ(x) queried at arbitrary voxel grids via 3D."}],"design_principles":["把 NeRF 的 radiance field 改写为非负 attenuation field，使渲染符合 X-ray 射线积分。","只用输入投影重投影误差做 per-case self-supervision，不需要成对 ground-truth CT。","多分辨率 hash encoding 提升坐标场的训练速度和细节表达，但不能补足未观测的零空间。"],"design_principles_en":["Core Hypothesis: Model a view-independent scalar attenuation field μ(x) using multi-resolution hash grid encoding (Instant-NGP) supervised purely by line-integral projection residuals.","Architectural Delta: Physically faithful Beer–Lambert line integral + multi-resolution learnable hash table reducing self-supervised 3D CBCT reconstruction to minutes.","Mathematical Formalism: Beer–Lambert Logarithmic Line-Integral Reprojection Consistency Over Multi-Resolution Hash Grids."],"med_apps":["适合 sparse-view CBCT 的病例级自监督重建，可在连续坐标中任意分辨率查询。","真实散射、束硬化、金属和校准误差若未纳入 renderer，会被场错误吸收为解剖；模拟与真实证据应分开报告。"],"med_apps_en":["Clinical Translation: Fast, self-supervised per-patient sparse-view CBCT reconstruction requiring zero external training datasets.","Evidence & Safety Boundary: Correct physics adaptation of NeRF to tomography; without an external population prior, extreme view sparsity still exhibits null-space streaks."],"attrs":{"上一代瓶颈":"稀疏 CBCT 重建缺细节，监督网络需大量成对训练数据","核心想法":"用坐标网络表示 X-ray attenuation，并最小化输入投影的重投影误差","关键改进":"将 NeRF 改为符合 Beer-Lambert 的 attenuation field，并用 hash encoding 加速","医学适配":"适用于 phantom/人体 sparse-view CBCT 的自监督 per-case reconstruction；需区分模拟投影与真实 acquisition","适用范围与证据":"正确的医学 NeRF 改写；无外部 prior 时仍不能创造缺失信息"},"attrs_en":{"上一代瓶颈":"Applying RGB NeRF directly to X-ray projections violated transmission physics, while Fourier MLP encodings took hours to optimize per patient.","核心想法":"Model a view-independent scalar attenuation field μ(x) using multi-resolution hash grid encoding (Instant-NGP) supervised purely by line-integral projection residuals.","关键改进":"Physically faithful Beer–Lambert line integral + multi-resolution learnable hash table reducing self-supervised 3D CBCT reconstruction to minutes.","医学适配":"Fast, self-supervised per-patient sparse-view CBCT reconstruction requiring zero external training datasets.","适用范围与证据":"Correct physics adaptation of NeRF to tomography; without an external population prior, extreme view sparsity still exhibits null-space streaks."},"paper_title":"Neural Attenuation Fields for Sparse-View CBCT Reconstruction","paper_url":"https://conferences.miccai.org/2022/papers/349-Paper0974.html","code_label":"作者/机构官方实现","code_url":"https://github.com/ruyi-zha/naf_cbct","has_code":true,"image":"assets/dda9bc53e7c559aedb0d.avif"},{"id":"architecture_model_074_3d_gaussian_splatting","num":74,"num_str":"074","year":2023,"year_str":"2023","venue":"ACM Transactions on Graphics / SIGGRAPH","venue_group":"journal","era_group":"era4","title":"3D Gaussian Splatting","family_id":"models_neural_fields_2d3d","family_code":"14","family_short":"2D→3D 与神经辐射场","family_en":"2D-to-3D & Neural Fields","family_icon":"XIV","family_label":"2D→3D 与神经场：表示能力、投影一致性和不可辨识性","archetype":"explicit_gaussian_radiance_splatting","archetype_en":"explicit_gaussian_radiance_splatting","accent":"#1F4E79","fig_badge":"Figure 2 · PDF p.5","fig_href":"https://repo-sam.inria.fr/fungraph/3d-gaussian-splatting/","core_mech":"显式优化各向异性 3D Gaussians，并通过屏幕空间 splatting 与自适应增密实现实时 radiance rendering。","core_mech_en":"Represents 3D scenes explicitly as millions of anisotropic 3D Gaussians (position, covariance, opacity, spherical harmonics) rendered in real time via differentiable tile-based rasterization.","input_desc":"带标定多视角 RGB 图像与 SfM/点云初始化","input_en":"Calibrated multi-view images and initial sparse point cloud","output_desc":"可实时新视角渲染的显式 3D Gaussian 集合","output_en":"Explicit set of anisotropic 3D Gaussians supporting >100 FPS real-time novel-view synthesis","form_title":"核心公式 · 3D 协方差投影与前向 alpha 合成","form_title_en":"Core Formalism · Projective 3D-to-2D Covariance Splatting & Front-to-Back Alpha Compositing","nodes":[{"name":"多视角图像","desc":"已知相机内外参与监督 RGB","name_en":"Stage 01","desc_en":"Ingests calibrated multi-view images and initial sparse point cloud and prepares initial tensor representations (Stage 01)."},{"name":"稀疏点初始化","desc":"由 SfM 点云初始化 Gaussian 中心和颜色","name_en":"Stage 02","desc_en":"Executes Stage 02 to extract primary structural features and establish spatial/sequence encoding."},{"name":"3D Gaussians","desc":"每个 primitive 有位置、各向异性协方差、opacity 与球谐颜色","name_en":"3D Gaussians","desc_en":"Performs 3D Gaussians within the core explicit gaussian radiance splatting computation pathway."},{"name":"屏幕投影","desc":"用视图 Jacobian 将 3D covariance 投影为 2D 椭圆 footprint","name_en":"projection","desc_en":"Performs projection within the core explicit gaussian radiance splatting computation pathway."},{"name":"排序 Splat","desc":"tile-based visibility-aware rasterization，按深度累积 primitive","name_en":"Splat","desc_en":"Performs Splat within the core explicit gaussian radiance splatting computation pathway."},{"name":"Alpha 合成","desc":"前到后 opacity compositing 得到像素颜色","name_en":"Alpha","desc_en":"Performs Alpha within the core explicit gaussian radiance splatting computation pathway."},{"name":"光度损失","desc":"L1 与结构相似度等比较渲染和观测图像","name_en":"loss","desc_en":"Performs loss within the core explicit gaussian radiance splatting computation pathway."},{"name":"增密 / 剪枝","desc":"依据梯度分裂、克隆或删除 Gaussians，自适应分配容量","name_en":"Stage 08","desc_en":"Applies Stage 08 to project aggregated representations toward the target task head."},{"name":"实时渲染","desc":"优化后的显式 primitive 可快速 rasterize 新视角","name_en":"Stage 09","desc_en":"Produces explicit set of anisotropic 3d gaussians supporting >100 fps real-time novel-view synthesis via Stage 09."}],"design_principles":["以显式各向异性 Gaussian primitives 替代每射线 MLP 查询，交换部分内存以换取实时 rasterization。","3D covariance 经相机投影成为屏幕椭圆，并通过可微 alpha compositing 参与图像损失。","增密和剪枝让表示容量随场景细节自适应，而非固定 voxel 分辨率。"],"design_principles_en":["Core Hypothesis: Replace implicit continuous MLPs with explicit 3D Gaussian primitives projected directly to 2D screen space via closed-form EWA covariance splatting.","Architectural Delta: Anisotropic 3D covariance optimization (R S S^T R^T) + adaptive clone/split/prune density control + fast tile-based GPU sorting rasterizer.","Mathematical Formalism: Projective 3D-to-2D Covariance Splatting & Front-to-Back Alpha Compositing."],"med_apps":["可启发内镜/术野新视角、动态解剖可视化和医学 X-ray Gaussian renderer。","原始 RGB opacity compositing 不保证 HU、attenuation 或患者解剖真实性；医学应用必须重写物理和定量验证。"],"med_apps_en":["Clinical Translation: Rapidly adapted to surgical endoscopy 3D reconstruction (EndoGaussian) and radiative X-ray Gaussian tomography (R2-Gaussian).","Evidence & Safety Boundary: Genuine real-time rendering breakthrough; discrete Gaussian primitives can still produce needle-like artifacts under sparse views."],"attrs":{"上一代瓶颈":"NeRF 每射线 MLP 查询使训练与渲染较慢","核心想法":"以显式各向异性 3D Gaussians 和 visibility-aware splatting 表示场景","关键改进":"直接优化 Gaussian 位置、协方差、不透明度和颜色，实现实时渲染","医学适配":"启发 X-ray radiative Gaussian splatting 和动态 tomography","适用范围与证据":"实时渲染优势真实；不自动保证 HU、解剖或成像物理"},"attrs_en":{"上一代瓶颈":"Continuous coordinate MLPs in NeRF required querying hundreds of points along every ray, bottlenecking real-time rendering and interactive editing.","核心想法":"Replace implicit continuous MLPs with explicit 3D Gaussian primitives projected directly to 2D screen space via closed-form EWA covariance splatting.","关键改进":"Anisotropic 3D covariance optimization (R S S^T R^T) + adaptive clone/split/prune density control + fast tile-based GPU sorting rasterizer.","医学适配":"Rapidly adapted to surgical endoscopy 3D reconstruction (EndoGaussian) and radiative X-ray Gaussian tomography (R2-Gaussian).","适用范围与证据":"Genuine real-time rendering breakthrough; discrete Gaussian primitives can still produce needle-like artifacts under sparse views."},"paper_title":"3D Gaussian Splatting for Real-Time Radiance Field Rendering","paper_url":"https://repo-sam.inria.fr/fungraph/3d-gaussian-splatting/","code_label":"作者/机构官方实现","code_url":"https://github.com/graphdeco-inria/gaussian-splatting","has_code":true,"image":"assets/0d4e76d63e3e92fce513.avif"},{"id":"architecture_model_075_gcn","num":75,"num_str":"075","year":2017,"year_str":"2017","venue":"ICLR","venue_group":"ml","era_group":"era2","title":"GCN","family_id":"models_graph_neural_networks","family_code":"15","family_short":"图神经网络与医学拓扑","family_en":"Graph & Mesh Networks","family_icon":"XV","family_label":"图神经网络：当边、拓扑和关系本身就是医学信息","archetype":"normalized_graph_convolution","archetype_en":"normalized_graph_convolution","accent":"#5B3F8C","fig_badge":"Figure 1 · PDF p.4","fig_href":"https://arxiv.org/abs/1609.02907","core_mech":"以加自环的对称归一化邻接执行共享线性变换后的固定权重邻居聚合。","core_mech_en":"First-order spectral graph convolution approximation that aggregates 1-hop neighbor features weighted by the symmetrically normalized adjacency matrix with self-loops.","input_desc":"图 G=(V,E)、节点特征 X 与邻接矩阵 A","input_en":"Graph G=(V,E) with node feature matrix X ∈ R^{N×C} and adjacency matrix A","output_desc":"节点级或图级预测","output_en":"Updated node embeddings H^{(L)} for node classification, link prediction, or pooled graph classification","form_title":"核心公式 · 对称归一化图卷积更新","form_title_en":"Core Formalism · Symmetrically Normalized Adjacency Propagation: H^{(l+1)} = σ(D̃^{-1/2} Ã D̃^{-1/2} H^{(l)} W^{(l)})","nodes":[{"name":"图与特征","desc":"节点特征 X、邻接 A；边定义允许的信息传递范围","name_en":"feature","desc_en":"Ingests graph g=(v,e) with node feature matrix x ∈ r^{n×c} and adjacency matrix a and prepares initial tensor representations (feature)."},{"name":"加入自环","desc":"A_tilde=A+I，使节点保留自身特征","name_en":"Stage 02","desc_en":"Executes Stage 02 to extract primary structural features and establish spatial/sequence encoding."},{"name":"归一化邻接","desc":"D_tilde^{-1/2} A_tilde D_tilde^{-1/2} 稳定不同度数的聚合","name_en":"Normalized Adjacency","desc_en":"Performs Normalized Adjacency within the core normalized graph convolution computation pathway."},{"name":"线性变换","desc":"H^l W^l 把节点特征映射到新通道","name_en":"Stage 04","desc_en":"Performs Stage 04 within the core normalized graph convolution computation pathway."},{"name":"邻居聚合","desc":"按归一化邻接对一跳邻居做加权求和","name_en":"Neighborhood Aggregation","desc_en":"Performs Neighborhood Aggregation within the core normalized graph convolution computation pathway."},{"name":"激活 / 堆叠","desc":"sigma 后得到 H^{l+1}；L 层覆盖 L-hop 邻域","name_en":"Stage 06","desc_en":"Performs Stage 06 within the core normalized graph convolution computation pathway."},{"name":"任务读出","desc":"节点分类头或 pooling 后的图级分类头","name_en":"Stage 07","desc_en":"Applies Stage 07 to project aggregated representations toward the target task head."},{"name":"预测","desc":"节点标签、图标签或连续值","name_en":"prediction","desc_en":"Produces updated node embeddings h^{(l)} for node classification, link prediction, or pooled graph classification via prediction."}],"design_principles":["用一阶谱近似得到局部 message passing，不需要图拉普拉斯特征分解。","对称度归一化控制高度节点的消息尺度，自环保留自身信息。","邻接矩阵决定信息泄漏边界；多层堆叠会引起 over-smoothing 和 oversquashing。"],"design_principles_en":["Core Hypothesis: Truncate Chebyshev spectral polynomials to first order, yielding a localized spatial 1-hop neighborhood averaging operator with shared linear weights.","Architectural Delta: Simple, parameter-efficient message passing scaling linearly with number of graph edges O(|E|).","Mathematical Formalism: Symmetrically Normalized Adjacency Propagation: H^{(l+1)} = σ(D̃^{-1/2} Ã D̃^{-1/2} H^{(l)} W^{(l)})."],"med_apps":["可用于病人 population graph、血管/气道树、细胞图和解剖 mesh 的节点或图级任务。","若边由结局相关变量、医院 ID 或全数据统计构造，可能发生验证集泄漏；构图必须在 split 内完成。"],"med_apps_en":["Clinical Translation: Foundational GNN used across brain connectomes (fMRI/DTI), vascular/airway trees, cortical surface meshes, and spatial cell graphs.","Evidence & Safety Boundary: Core GNN baseline; stacking many GCN layers causes over-smoothing, and transductive patient-similarity graphs risk severe cohort leakage."],"attrs":{"上一代瓶颈":"谱图卷积需特征分解，难扩展且参数不易共享","核心想法":"用归一化邻接矩阵的一阶谱近似做邻居特征聚合","关键改进":"局部 message passing 的简单可训练形式","医学适配":"用于 population graph、血管/气道树和解剖 mesh","适用范围与证据":"GNN 基础；深层 over-smoothing 与构图泄漏需警惕"},"attrs_en":{"上一代瓶颈":"Exact spectral graph CNNs required O(N³) Laplacian eigendecomposition and could not transfer across graphs of varying topology.","核心想法":"Truncate Chebyshev spectral polynomials to first order, yielding a localized spatial 1-hop neighborhood averaging operator with shared linear weights.","关键改进":"Simple, parameter-efficient message passing scaling linearly with number of graph edges O(|E|).","医学适配":"Foundational GNN used across brain connectomes (fMRI/DTI), vascular/airway trees, cortical surface meshes, and spatial cell graphs.","适用范围与证据":"Core GNN baseline; stacking many GCN layers causes over-smoothing, and transductive patient-similarity graphs risk severe cohort leakage."},"paper_title":"Semi-Supervised Classification with Graph Convolutional Networks","paper_url":"https://arxiv.org/abs/1609.02907","code_label":"作者/机构官方实现","code_url":"https://github.com/tkipf/gcn","has_code":true,"image":"assets/2ea4cff0ceeb601d1b18.avif"},{"id":"architecture_model_076_gat","num":76,"num_str":"076","year":2018,"year_str":"2018","venue":"ICLR","venue_group":"ml","era_group":"era2","title":"GAT","family_id":"models_graph_neural_networks","family_code":"15","family_short":"图神经网络与医学拓扑","family_en":"Graph & Mesh Networks","family_icon":"XV","family_label":"图神经网络：当边、拓扑和关系本身就是医学信息","archetype":"masked_graph_attention","archetype_en":"masked_graph_attention","accent":"#5B3F8C","fig_badge":"Figure 1 · PDF p.4","fig_href":"https://arxiv.org/abs/1710.10903","core_mech":"对预定义邻域内的边计算 masked multi-head attention，再以数据依赖权重聚合邻居特征。","core_mech_en":"Replaces fixed degree-normalized edge weights with content-dependent multi-head masked self-attention coefficients α_{ij} computed over 1-hop graph neighborhoods.","input_desc":"图 G=(V,E) 与节点特征 X","input_en":"Graph G=(V,E) and node feature vectors {h_i}","output_desc":"注意力聚合后的节点或图级预测","output_en":"Anisotropically aggregated node representations h'_i and attention edge weights α_{ij}","form_title":"核心公式 · 邻域掩码注意力与加权消息聚合","form_title_en":"Core Formalism · Neighborhood-Masked LeakyReLU Attention Coefficients & Multi-Head Message Aggregation","nodes":[{"name":"节点与边","desc":"预定义邻域 N(i) 限制可注意的节点对","name_en":"Stage 01","desc_en":"Ingests graph g=(v,e) and node feature vectors {h_i} and prepares initial tensor representations (Stage 01)."},{"name":"特征投影","desc":"共享 W 将 h_i、h_j 映射到 attention 空间","name_en":"feature projection","desc_en":"Executes feature projection to extract primary structural features and establish spatial/sequence encoding."},{"name":"边注意力 e_ij","desc":"LeakyReLU(a^T[Wh_i || Wh_j]) 计算相邻节点兼容性","name_en":"Edge Attention Logits e_ij","desc_en":"Performs Edge Attention Logits e_ij within the core masked graph attention computation pathway."},{"name":"邻域 Softmax","desc":"仅在 j∈N(i) 上归一化得到 alpha_ij","name_en":"Neighborhood Softmax","desc_en":"Performs Neighborhood Softmax within the core masked graph attention computation pathway."},{"name":"多头聚合","desc":"各 head 独立加权求和 Σ_j alpha_ij W h_j","name_en":"aggregation","desc_en":"Performs aggregation within the core masked graph attention computation pathway."},{"name":"Concat / 平均","desc":"中间层拼接多头，最终层可平均以稳定预测","name_en":"Concat","desc_en":"Performs Concat within the core masked graph attention computation pathway."},{"name":"图层堆叠","desc":"激活后进入下一层，扩大多跳上下文","name_en":"Stage 07","desc_en":"Performs Stage 07 within the core masked graph attention computation pathway."},{"name":"任务读出","desc":"节点头或图 pooling/head","name_en":"Stage 08","desc_en":"Applies Stage 08 to project aggregated representations toward the target task head."},{"name":"预测","desc":"节点、边或图级输出","name_en":"prediction","desc_en":"Produces anisotropically aggregated node representations h'_i and attention edge weights α_{ij} via prediction."}],"design_principles":["在已有边上为不同邻居学习输入相关权重，替代 GCN 的固定度归一化权重。","masked attention 仍依赖预先定义的 adjacency；GAT 不会自动发现任意远程边。","多头机制提高训练稳定性和表示容量，但 attention 权重不是因果或医学解释。"],"design_principles_en":["Core Hypothesis: Compute learnable attention scores e_{ij} = a^T [W h_i || W h_j] normalized via softmax over each node's 1-hop neighborhood N_i.","Architectural Delta: Inductive, degree-agnostic anisotropic neighborhood weighting + multi-head stabilization.","Mathematical Formalism: Neighborhood-Masked LeakyReLU Attention Coefficients & Multi-Head Message Aggregation."],"med_apps":["适合血管分支、病人关系、组织细胞相互作用等邻居贡献不均的医学图。","异质边类型、批次效应和构图偏差应显式建模；仅展示高 attention 边不足以证明临床机制。"],"med_apps_en":["Clinical Translation: Widely applied to histopathology cell- microenvironment graphs, brain functional connectivity, and multimodal patient networks.","Evidence & Safety Boundary: Standard anisotropic GNN; learned attention weights α_{ij} aid inspection but do not guarantee causal biological importance."],"attrs":{"上一代瓶颈":"GCN 对邻居使用固定归一化权重，难表达异质关系","核心想法":"以 masked attention 为不同邻居自适应分配权重","关键改进":"多头图注意力仍需预定义 adjacency/neighborhood，但不需预设已有边的权重","医学适配":"适合血管分支、病人关系和细胞相互作用图","适用范围与证据":"重要图模型；attention 权重不自动等于医学解释"},"attrs_en":{"上一代瓶颈":"GCN weighted neighbors solely by static node degrees, preventing the network from prioritizing diagnostically critical neighbors.","核心想法":"Compute learnable attention scores e_{ij} = a^T [W h_i || W h_j] normalized via softmax over each node's 1-hop neighborhood N_i.","关键改进":"Inductive, degree-agnostic anisotropic neighborhood weighting + multi-head stabilization.","医学适配":"Widely applied to histopathology cell- microenvironment graphs, brain functional connectivity, and multimodal patient networks.","适用范围与证据":"Standard anisotropic GNN; learned attention weights α_{ij} aid inspection but do not guarantee causal biological importance."},"paper_title":"Graph Attention Networks","paper_url":"https://arxiv.org/abs/1710.10903","code_label":"作者/机构官方实现","code_url":"https://github.com/PetarV-/GAT","has_code":true,"image":"assets/0a6f3f7618a2de03683d.avif"},{"id":"architecture_model_077_lstm","num":77,"num_str":"077","year":1997,"year_str":"1997","venue":"Neural Computation","venue_group":"journal","era_group":"era1","title":"LSTM","family_id":"models_temporal_biomedical","family_code":"16","family_short":"生理时序与波形模型","family_en":"Temporal Physiological AI","family_icon":"XVI","family_label":"生理时序模型：门控、膨胀卷积、长状态与领域预训练","archetype":"gated_recurrent_memory","archetype_en":"gated_recurrent_memory","accent":"#6B5700","fig_badge":"Figure 1 · PDF p.7","fig_href":"https://doi.org/10.1162/neco.1997.9.8.1735","core_mech":"带门控的加性 cell memory 与 recurrent hidden state 分离，使长期信息可选择性保留和读出。","core_mech_en":"Separates an additive linear cell memory state c_t (governed by forget and input gates) from the non-linear recurrent hidden state h_t to preserve long-term temporal gradients.","input_desc":"时间序列 x_1…x_T","input_en":"Sequential physiological waveform or longitudinal clinical time series x_1 … x_T","output_desc":"逐时刻隐藏状态或序列级预测","output_en":"Step-wise hidden states h_t or sequence-level diagnostic prediction","form_title":"核心公式 · LSTM 门控记忆与隐藏状态更新","form_title_en":"Core Formalism · Gated Additive Constant Error Carousel Cell Update: c_t = f_t ⊙ c_{t-1} + i_t ⊙ c̃_t","nodes":[{"name":"输入 x_t","desc":"当前 ECG/EEG/临床变量向量","name_en":"input x_t","desc_en":"Ingests sequential physiological waveform or longitudinal clinical time series x_1 … x_t and prepares initial tensor representations (input x_t)."},{"name":"h_{t-1}, c_{t-1}","desc":"前一时刻短期隐藏状态与长期 cell memory","name_en":"h_{t-1}, c_{t-1}","desc_en":"Executes h_{t-1}, c_{t-1} to extract primary structural features and establish spatial/sequence encoding."},{"name":"i/f/o 门","desc":"sigmoid 门控制写入、保留与读出；forget gate 属后来成为标准的现代 LSTM 式","name_en":"i/f/o","desc_en":"Performs i/f/o within the core gated recurrent memory computation pathway."},{"name":"候选记忆 g_t","desc":"tanh(W_x x_t+W_h h_{t-1}+b) 提议写入内容","name_en":"g_t","desc_en":"Performs g_t within the core gated recurrent memory computation pathway."},{"name":"Cell 更新","desc":"现代式 c_t=f_t⊙c_{t-1}+i_t⊙g_t，形成加性记忆通路","name_en":"Cell update","desc_en":"Performs Cell update within the core gated recurrent memory computation pathway."},{"name":"Hidden 更新","desc":"h_t=o_t⊙tanh(c_t)","name_en":"Hidden update","desc_en":"Performs Hidden update within the core gated recurrent memory computation pathway."},{"name":"时间/序列头","desc":"对 h_t 逐点预测，或聚合 h_1…h_T 做序列分类","name_en":"sequence","desc_en":"Applies sequence to project aggregated representations toward the target task head."},{"name":"预测","desc":"事件、节律、状态或连续值","name_en":"prediction","desc_en":"Produces step-wise hidden states h_t or sequence-level diagnostic prediction via prediction."}],"design_principles":["加性 cell-state 通路让误差信号跨较长时间传播，缓解普通 RNN 的梯度消失。","输入、遗忘与输出门按当前输入和历史状态选择写入、保留和读出内容。","1997 原始 LSTM 强调 constant-error memory 与 input/output gates；现代标准 forget gate 是后续扩展，不应混作同年原始细节。"],"design_principles_en":["Core Hypothesis: Introduce a linear self-connected memory cell c_t regulated by multiplicative sigmoid input, forget, and output gates.","Architectural Delta: Additive cell-state highway enabling gradient propagation across hundreds of time steps.","Mathematical Formalism: Gated Additive Constant Error Carousel Cell Update: c_t = f_t ⊙ c_{t-1} + i_t ⊙ c̃_t."],"med_apps":["在中小数据的 ECG、EEG、EMG 和纵向表格序列上仍是可靠、易解释的基线。","串行递归限制长记录吞吐，缺失模式、采样不规则和跨患者状态初始化需显式处理。"],"med_apps_en":["Clinical Translation: Long-standing workhorse for 12-lead ECG arrhythmia classification, ICU vitals early-warning scores, and irregular EHR trajectories.","Evidence & Safety Boundary: Reliable low-data sequential baseline; sequential step-by-step recurrence prevents parallel training across ultra-long multi-thousand-sample waveforms."],"attrs":{"上一代瓶颈":"vanilla RNN 长依赖中梯度消失或爆炸","核心想法":"用 cell state 和 input/forget/output gates 保留长期信息","关键改进":"带近恒等记忆通路的门控循环更新","医学适配":"长期用于小中型 ECG、EEG、EMG 与纵向临床序列","适用范围与证据":"仍是低数据序列基线；串行训练慢且长窗口扩展有限"},"attrs_en":{"上一代瓶颈":"Vanilla RNNs multiplied recurrent weight matrices repeatedly across time, causing gradients to vanish or explode over >20 steps.","核心想法":"Introduce a linear self-connected memory cell c_t regulated by multiplicative sigmoid input, forget, and output gates.","关键改进":"Additive cell-state highway enabling gradient propagation across hundreds of time steps.","医学适配":"Long-standing workhorse for 12-lead ECG arrhythmia classification, ICU vitals early-warning scores, and irregular EHR trajectories.","适用范围与证据":"Reliable low-data sequential baseline; sequential step-by-step recurrence prevents parallel training across ultra-long multi-thousand-sample waveforms."},"paper_title":"Long Short-Term Memory","paper_url":"https://doi.org/10.1162/neco.1997.9.8.1735","code_label":"未提供官方实现","code_url":"","has_code":false,"image":"assets/690b3687de8c5d810a5b.avif"},{"id":"architecture_model_078_temporal_convolutional_network__tcn","num":78,"num_str":"078","year":2018,"year_str":"2018","venue":"arXiv preprint","venue_group":"journal","era_group":"era2","title":"Temporal Convolutional Network (TCN)","family_id":"models_temporal_biomedical","family_code":"16","family_short":"生理时序与波形模型","family_en":"Temporal Physiological AI","family_icon":"XVI","family_label":"生理时序模型：门控、膨胀卷积、长状态与领域预训练","archetype":"causal_dilated_temporal_convolution","archetype_en":"causal_dilated_temporal_convolution","accent":"#6B5700","fig_badge":"Figure 1 · PDF p.4","fig_href":"https://arxiv.org/abs/1803.01271","core_mech":"以因果、指数扩张的 1D 卷积残差块并行覆盖长历史，而不使用循环状态。","core_mech_en":"Stacks 1D causal convolutions with exponentially increasing dilation factors d = 2^l inside residual blocks to cover long historical receptive fields in parallel.","input_desc":"长度 T 的多通道时间序列 X","input_en":"Multi-channel continuous physiological time series X ∈ R^{C×T}","output_desc":"逐时刻或序列级预测","output_en":"Causal step-wise sequence predictions or pooled episode classification","form_title":"核心公式 · 因果扩张卷积与残差时间块","form_title_en":"Core Formalism · Causal Exponentially Dilated 1D Convolution Preserving Temporal Ordering","nodes":[{"name":"序列 X","desc":"形状为 time×channels；可按任务做因果或固定窗口输入","name_en":"sequence X","desc_en":"Ingests multi-channel continuous physiological time series x ∈ r^{c×t} and prepares initial tensor representations (sequence X)."},{"name":"因果卷积","desc":"左侧 padding 保证时刻 t 不读取未来样本","name_en":"Causal 1D Convolution","desc_en":"Executes Causal 1D Convolution to extract primary structural features and establish spatial/sequence encoding."},{"name":"扩张卷积","desc":"d=1,2,4… 的 1D kernel 指数扩大感受野","name_en":"Dilated 1D Convolution","desc_en":"Performs Dilated 1D Convolution within the core causal dilated temporal convolution computation pathway."},{"name":"残差块","desc":"两层 dilated Conv、非线性、dropout/weight norm 加 residual branch","name_en":"residual block","desc_en":"Performs residual block within the core causal dilated temporal convolution computation pathway."},{"name":"Residual / 1×1","desc":"通道不同时用 1×1 projection，再与 block 输出相加","name_en":"Residual / 1×1","desc_en":"Performs Residual / 1×1 within the core causal dilated temporal convolution computation pathway."},{"name":"层级堆叠","desc":"多个 dilation level 并行训练，覆盖固定的长历史窗口","name_en":"hierarchical","desc_en":"Performs hierarchical within the core causal dilated temporal convolution computation pathway."},{"name":"有效感受野","desc":"由 kernel、dilation 和层数预先确定；超出窗口的信息不可见","name_en":"receptive field","desc_en":"Performs receptive field within the core causal dilated temporal convolution computation pathway."},{"name":"任务头","desc":"逐时刻 1×1 head 或全局 pooling 后分类/回归","name_en":"Task Head","desc_en":"Applies Task Head to project aggregated representations toward the target task head."},{"name":"预测","desc":"序列标签、分割或连续值","name_en":"prediction","desc_en":"Produces causal step-wise sequence predictions or pooled episode classification via prediction."}],"design_principles":["用因果卷积保证在线预测不泄漏未来，用 dilation 在较少层数下覆盖长时间范围。","所有时间位置可并行计算，避免 RNN 的逐步隐藏状态依赖。","残差块稳定深层训练，但可见历史范围由结构预先固定，不会按样本动态选择远程依赖。"],"design_principles_en":["Core Hypothesis: Combine strict causal padding (no future leakage) with exponentially dilated 1D convolutions (d=1, 2, 4, 8…) and residual shortcuts.","Architectural Delta: Full temporal parallelization during training + exact, deterministic receptive field calculation R = 1 + Σ (k−1)·d_l + low streaming memory.","Mathematical Formalism: Causal Exponentially Dilated 1D Convolution Preserving Temporal Ordering."],"med_apps":["是 ECG/EEG 等等间隔生理信号的高吞吐强基线，尤其适合流式事件检测。","不规则采样、跨小时缺口或依赖超出感受野时，需要时间编码、重采样或更长上下文机制。"],"med_apps_en":["Clinical Translation: Highly competitive, fast, and stable baseline for continuous ECG, EEG seizure detection, PPG, and EMG envelope decoding.","Evidence & Safety Boundary: Practical first-line waveform baseline; receptive field is fixed by network depth/dilation and weights remain static across inputs."],"attrs":{"上一代瓶颈":"RNN 串行计算且有效记忆长度不稳定","核心想法":"用 causal dilated 1D convolution 与 residual blocks 建模长序列","关键改进":"并行卷积、指数扩张感受野和稳定残差优化","医学适配":"成为 ECG/EEG 等生理信号强、便宜、稳定的 baseline","适用范围与证据":"长期实用；感受野由 dilation/depth 固定且全局自适应关系有限"},"attrs_en":{"上一代瓶颈":"Recurrent networks (LSTM/GRU) could not parallelize across time during training and exhibited unstable effective memory horizons.","核心想法":"Combine strict causal padding (no future leakage) with exponentially dilated 1D convolutions (d=1, 2, 4, 8…) and residual shortcuts.","关键改进":"Full temporal parallelization during training + exact, deterministic receptive field calculation R = 1 + Σ (k−1)·d_l + low streaming memory.","医学适配":"Highly competitive, fast, and stable baseline for continuous ECG, EEG seizure detection, PPG, and EMG envelope decoding.","适用范围与证据":"Practical first-line waveform baseline; receptive field is fixed by network depth/dilation and weights remain static across inputs."},"paper_title":"An Empirical Evaluation of Generic Convolutional and Recurrent Networks for Sequence Modeling","paper_url":"https://arxiv.org/abs/1803.01271","code_label":"作者/机构官方实现","code_url":"https://github.com/locuslab/TCN","has_code":true,"image":"assets/0e79161ad60dafb69d91.avif"},{"id":"architecture_model_079_heartbeit","num":79,"num_str":"079","year":2023,"year_str":"2023","venue":"npj Digital Medicine","venue_group":"journal","era_group":"era4","title":"HeartBEiT","family_id":"models_temporal_biomedical","family_code":"16","family_short":"生理时序与波形模型","family_en":"Temporal Physiological AI","family_icon":"XVI","family_label":"生理时序模型：门控、膨胀卷积、长状态与领域预训练","archetype":"ecg_image_masked_pretraining_transformer","archetype_en":"ecg_image_masked_pretraining_transformer","accent":"#6B5700","fig_badge":"Figure 1 · PDF p.2","fig_href":"https://www.nature.com/articles/s41746-023-00840-9","core_mech":"将标准版式 ECG 渲染为图像，以 BEiT 式离散 masked-patch prediction 预训练专用 ViT。","core_mech_en":"Renders standard 12-lead ECG waveforms as 2D layout images and pretrains a Vision Transformer via BEiT-style discrete masked patch token prediction on 8.5 million ECGs.","input_desc":"按标准版式渲染的 12 导联 ECG 图像","input_en":"Standardized 2D image rendering of a 12-lead clinical electrocardiogram","output_desc":"ECG 诊断分类概率或迁移表征","output_en":"Pretrained ECG ViT representation for low-label arrhythmia, LVEF, and STEMI classification","form_title":"核心公式 · ECG 图像遮挡 patch 的离散 token 预测","form_title_en":"Core Formalism · Masked Patch Visual Token Prediction Over Rendered 12-Lead ECG Waveform Plots","nodes":[{"name":"12 导联波形","desc":"原始 ECG 被裁切、标度并排版为临床样式图像","name_en":"12","desc_en":"Ingests standardized 2d image rendering of a 12-lead clinical electrocardiogram and prepares initial tensor representations (12)."},{"name":"ECG 渲染图","desc":"模型实际输入是二维波形图，不是原始采样序列 token","name_en":"ECG","desc_en":"Executes ECG to extract primary structural features and establish spatial/sequence encoding."},{"name":"图像 patches","desc":"切分固定大小 patch 并线性嵌入为 ViT tokens","name_en":"patches","desc_en":"Performs patches within the core ecg image masked pretraining transformer computation pathway."},{"name":"随机遮挡","desc":"大比例 patch 替换为 mask token，保留可见上下文","name_en":"masked","desc_en":"Performs masked within the core ecg image masked pretraining transformer computation pathway."},{"name":"离散视觉目标","desc":"BEiT-style tokenizer 为被遮挡 patch 提供离散 code targets","name_en":"discrete objective","desc_en":"Performs discrete objective within the core ecg image masked pretraining transformer computation pathway."},{"name":"HeartBEiT 编码器","desc":"Vision Transformer 从可见 ECG 形态建模跨导联与长程空间关系","name_en":"HeartBEiT encoder","desc_en":"Performs HeartBEiT encoder within the core ecg image masked pretraining transformer computation pathway."},{"name":"掩码预测头","desc":"预训练时预测 masked patch 的离散 token","name_en":"masked prediction","desc_en":"Performs masked prediction within the core ecg image masked pretraining transformer computation pathway."},{"name":"诊断微调头","desc":"用全局 token/pooled representation 做多标签分类","name_en":"fine-tuning","desc_en":"Applies fine-tuning to project aggregated representations toward the target task head."},{"name":"诊断输出","desc":"节律、结构或其他 ECG 标签概率","name_en":"output","desc_en":"Produces pretrained ecg vit representation for low-label arrhythmia, lvef, and stemi classification via output."}],"design_principles":["把 ECG 版面视为二维视觉结构，使 ViT 同时建模单导联形态和跨导联空间关系。","BEiT 式 masked image modeling 在无诊断标签的大规模 ECG 上预训练领域表示。","预训练单位是渲染图 patch；采样时刻、精确幅值和设备元数据只有在版式保留时才可间接读取。"],"design_principles_en":["Core Hypothesis: Convert clinical 12-lead ECGs into standardized 2D visual plots and pretrain a ViT to reconstruct masked waveform patches via discrete visual tokens.","Architectural Delta: Large-scale in-domain masked pretraining across 8.5M ECGs from 2.1M patients, directly compatible with printed/scanned paper ECGs.","Mathematical Formalism: Masked Patch Visual Token Prediction Over Rendered 12-Lead ECG Waveform Plots."],"med_apps":["适合有大量 ECG 图像归档但下游标注有限的分类迁移，并能复用视觉 Transformer 工具链。","版式、纸速、增益、裁切和打印噪声改变会形成域移位；不能把图像模型等同于原始波形基础模型。"],"med_apps_en":["Clinical Translation: Improves label-efficient transfer for reduced LVEF screening, hypertrophic cardiomyopathy, and myocardial infarction detection.","Evidence & Safety Boundary: Demonstrates the power of scale in ECG SSL; rasterizing 1D voltage time series into 2D pixels discards microvolt resolution and ties the model to a fixed plot layout."],"attrs":{"上一代瓶颈":"ImageNet 初始化与小型监督模型难覆盖 ECG 形态及标签稀缺","核心想法":"把 ECG 渲染为图像并用 BEiT 式 masked image modeling 进行大规模领域预训练","关键改进":"在 850 万 ECG、210 万患者上做领域 masked pretraining","医学适配":"提高 ECG 少标签迁移和外部分类表现","适用范围与证据":"证明领域预训练价值；渲染、截断和缩放可能损失精确采样、幅值及采集元数据，并依赖固定版式"},"attrs_en":{"上一代瓶颈":"Small supervised ECG models overfit single-center cohorts, while natural-image ViT weights did not capture fine QRS/ST-segment morphology.","核心想法":"Convert clinical 12-lead ECGs into standardized 2D visual plots and pretrain a ViT to reconstruct masked waveform patches via discrete visual tokens.","关键改进":"Large-scale in-domain masked pretraining across 8.5M ECGs from 2.1M patients, directly compatible with printed/scanned paper ECGs.","医学适配":"Improves label-efficient transfer for reduced LVEF screening, hypertrophic cardiomyopathy, and myocardial infarction detection.","适用范围与证据":"Demonstrates the power of scale in ECG SSL; rasterizing 1D voltage time series into 2D pixels discards microvolt resolution and ties the model to a fixed plot layout."},"paper_title":"A Foundational Vision Transformer Improves Diagnostic Performance for Electrocardiograms","paper_url":"https://www.nature.com/articles/s41746-023-00840-9","code_label":"未提供官方实现","code_url":"","has_code":false,"image":"assets/ac535782d0e0fcbc75df.avif"},{"id":"architecture_model_080_labram","num":80,"num_str":"080","year":2024,"year_str":"2024","venue":"ICLR","venue_group":"ml","era_group":"era4","title":"LaBraM","family_id":"models_temporal_biomedical","family_code":"16","family_short":"生理时序与波形模型","family_en":"Temporal Physiological AI","family_icon":"XVI","family_label":"生理时序模型：门控、膨胀卷积、长状态与领域预训练","archetype":"eeg_masked_neural_token_transformer","archetype_en":"eeg_masked_neural_token_transformer","accent":"#6B5700","fig_badge":"Figure 1 · PDF p.3","fig_href":"https://proceedings.iclr.cc/paper_files/paper/2024/file/47393e8594c82ce8fd83adc672cf9872-Paper-Conference.pdf","core_mech":"以 VQ neural tokenizer 提供离散 EEG patch 目标，再用跨通道/时间 Transformer 做 masked code prediction。","core_mech_en":"Trains a vector-quantized (VQ) neural spectrum tokenizer to predict Fourier amplitude/phase spectra of EEG patches, then pretrains a cross-channel Transformer via masked code prediction.","input_desc":"多通道连续 EEG 片段及通道身份","input_en":"Multi-channel continuous EEG recordings with arbitrary montage channel counts and recording lengths","output_desc":"通用 EEG 表征与下游分类/检测输出","output_en":"Universal EEG representation transferable across seizure detection, sleep staging, emotion, and motor BCI","form_title":"核心公式 · EEG patch 向量量化与遮挡神经码预测","form_title_en":"Core Formalism · Fourier-Spectrum Guided Neural Vector Quantization + Symmetric Masked EEG Code Prediction","nodes":[{"name":"多通道 EEG","desc":"不同 montage、记录长度和采样条件的脑电序列","name_en":"channel EEG","desc_en":"Ingests multi-channel continuous eeg recordings with arbitrary montage channel counts and recording lengths and prepares initial tensor representations (channel EEG)."},{"name":"通道时间 patches","desc":"每个通道沿时间切片并映射为 neural embeddings","name_en":"channel patches","desc_en":"Executes channel patches to extract primary structural features and establish spatial/sequence encoding."},{"name":"时空身份编码","desc":"加入时间位置与电极/通道标识，保留 montage 结构","name_en":"Stage 03","desc_en":"Performs Stage 03 within the core eeg masked neural token transformer computation pathway."},{"name":"Neural tokenizer","desc":"向量量化网络把连续 EEG patch 编成离散 neural codes","name_en":"Neural tokenizer","desc_en":"Performs Neural tokenizer within the core eeg masked neural token transformer computation pathway."},{"name":"Masked patches","desc":"遮挡部分 channel-time tokens，只给编码器可见上下文","name_en":"Masked patches","desc_en":"Performs Masked patches within the core eeg masked neural token transformer computation pathway."},{"name":"大规模 Transformer","desc":"在跨通道、跨时间 token 上做 self-attention","name_en":"Transformer","desc_en":"Performs Transformer within the core eeg masked neural token transformer computation pathway."},{"name":"Code 预测头","desc":"预测被遮挡位置的离散 tokenizer targets","name_en":"Code prediction","desc_en":"Performs Code prediction within the core eeg masked neural token transformer computation pathway."},{"name":"下游任务头","desc":"对预训练 tokens 做分类、检测或 BCI 解码","name_en":"Stage 08","desc_en":"Applies Stage 08 to project aggregated representations toward the target task head."},{"name":"EEG 输出","desc":"事件/状态标签或任务表征","name_en":"EEG output","desc_en":"Produces universal eeg representation transferable across seizure detection, sleep staging, emotion, and motor bci via EEG output."}],"design_principles":["把异质 EEG 统一为 channel-time patches，并显式编码电极身份与时间位置。","VQ neural tokenizer 将连续信号变为离散语义目标，使 masked modeling 不必逐样本回归原始振幅。","大规模 Transformer 在跨时间和跨通道维度共享参数，迁移能力依赖 montage 与预处理对齐。"],"design_principles_en":["Core Hypothesis: Segment each EEG channel into fixed-duration temporal patches, learn a discrete neural codebook predicting frequency amplitude/phase, and pretrain a Transformer with spatial+temporal embeddings via masked code prediction.","Architectural Delta: Spectrum-guided discrete neural tokenizer + factorized electrode-spatial and temporal embeddings unifying ~2,500 hours across 20 heterogeneous EEG cohorts.","Mathematical Formalism: Fourier-Spectrum Guided Neural Vector Quantization + Symmetric Masked EEG Code Prediction."],"med_apps":["可迁移到 EEG 分类、事件检测和 BCI 的少标签任务，是领域预训练的重要代表。","跨设备、跨人群、缺失电极和独立临床队列证据仍有限；离散 tokenizer 也可能忽略低幅但关键事件。"],"med_apps_en":["Clinical Translation: Canonical foundation model for cross-montage EEG abnormality classification, event detection, and brain–computer interfaces.","Evidence & Safety Boundary: Significant methodological leap for heterogeneous neurophysiology; clinical cross-hospital sensitivity and false-alarm calibration require ongoing validation."],"attrs":{"上一代瓶颈":"电极数、记录长度和任务差异使一任务一模型难迁移","核心想法":"以 channel patches、VQ neural tokenizer 和 masked code prediction 统一异质 EEG","关键改进":"跨约 20 个数据集、约 2500 小时 EEG 预训练离散神经信号 tokenizer 与 Transformer","医学适配":"支持 EEG 分类、检测和 BCI 的迁移与少样本学习","适用范围与证据":"原论文在四类下游任务报告优势；跨设备、跨人群和独立临床验证仍不足"},"attrs_en":{"上一代瓶颈":"EEG datasets vary wildly in electrode montage (16 to 128 channels), sampling rates, and low SNR, preventing cross-dataset pretraining.","核心想法":"Segment each EEG channel into fixed-duration temporal patches, learn a discrete neural codebook predicting frequency amplitude/phase, and pretrain a Transformer with spatial+temporal embeddings via masked code prediction.","关键改进":"Spectrum-guided discrete neural tokenizer + factorized electrode-spatial and temporal embeddings unifying ~2,500 hours across 20 heterogeneous EEG cohorts.","医学适配":"Canonical foundation model for cross-montage EEG abnormality classification, event detection, and brain–computer interfaces.","适用范围与证据":"Significant methodological leap for heterogeneous neurophysiology; clinical cross-hospital sensitivity and false-alarm calibration require ongoing validation."},"paper_title":"Large Brain Model for Learning Generic Representations with Tremendous EEG Data in BCI","paper_url":"https://proceedings.iclr.cc/paper_files/paper/2024/file/47393e8594c82ce8fd83adc672cf9872-Paper-Conference.pdf","code_label":"作者/机构官方实现","code_url":"https://github.com/935963004/LaBraM","has_code":true,"image":"assets/69adf2cfca7df91e8a09.avif"},{"id":"architecture_model_081_vgg_16_19","num":81,"num_str":"081","year":2015,"year_str":"2015 (preprint 2014)","venue":"ICLR","venue_group":"ml","era_group":"era1","title":"VGG-16/19","family_id":"models_cnn_backbones","family_code":"01","family_short":"CNN 主干与现代卷积","family_en":"CNN Backbones","family_icon":"I","family_label":"CNN 主干：从大规模分类到现代卷积","archetype":"deep_plain_small_kernel_cnn","archetype_en":"deep_plain_small_kernel_cnn","accent":"#1F4E79","fig_badge":"Table 1 · PDF p.3","fig_href":"https://arxiv.org/abs/1409.1556","core_mech":"以高度同质的 3×3 plain-convolution blocks 规律加深到 16/19 层，无残差连接。","core_mech_en":"Homogeneous stacking of 3×3 plain convolutional blocks systematically deepened to 16–19 layers without residual shortcuts.","input_desc":"固定尺寸 RGB/医学 2D 图像","input_en":"Fixed-size RGB or 2D grayscale medical image","output_desc":"分类 logits 或供下游使用的多层卷积特征","output_en":"Classification logits or multi-stage intermediate convolutional feature maps","form_title":"核心公式 · 连续小卷积核形成更大有效感受野","form_title_en":"Core Formalism · Stacked 3×3 Kernels Emulating Large Effective Receptive Fields","nodes":[{"name":"输入图像","desc":"经典配置为 224×224；医学任务可替换通道与尺寸","name_en":"Input Image","desc_en":"Ingests fixed-size rgb or 2d grayscale medical image and prepares initial tensor representations (Input Image)."},{"name":"Conv Block 1","desc":"2×3×3 Conv-64 后 2×2 max-pool","name_en":"Conv Block 1","desc_en":"Executes Conv Block 1 to extract primary structural features and establish spatial/sequence encoding."},{"name":"Conv Block 2","desc":"2×3×3 Conv-128 后 max-pool","name_en":"Conv Block 2","desc_en":"Performs Conv Block 2 within the core deep plain small kernel cnn computation pathway."},{"name":"Conv Block 3","desc":"VGG-16 为 3 层、VGG-19 为 4 层 3×3 Conv-256","name_en":"Conv Block 3","desc_en":"Performs Conv Block 3 within the core deep plain small kernel cnn computation pathway."},{"name":"Conv Block 4","desc":"3/4 层 3×3 Conv-512 后 max-pool","name_en":"Conv Block 4","desc_en":"Performs Conv Block 4 within the core deep plain small kernel cnn computation pathway."},{"name":"Conv Block 5","desc":"3/4 层 3×3 Conv-512 后 max-pool","name_en":"Conv Block 5","desc_en":"Performs Conv Block 5 within the core deep plain small kernel cnn computation pathway."},{"name":"全连接头","desc":"两层 4096-unit FC+ReLU+dropout，再接分类层","name_en":"Fully Connected Head","desc_en":"Applies Fully Connected Head to project aggregated representations toward the target task head."},{"name":"类别输出","desc":"softmax logits；卷积块也常被截取作 encoder/感知特征","name_en":"Class Logits Output","desc_en":"Produces classification logits or multi-stage intermediate convolutional feature maps via Class Logits Output."}],"design_principles":["连续堆叠 3×3 卷积，以多个非线性和较少参数获得等效大感受野。","每个 stage 通过 max-pool 降采样并增加通道，形成规则层级特征。","网络是 plain feed-forward CNN，无 residual shortcuts；超深优化和全连接参数量因此受限。"],"design_principles_en":["Core Hypothesis: Replace large kernels with homogeneous stacks of 3×3 convolutions interleaved with 2×2 max-pooling up to 16–19 weight layers.","Architectural Delta: Stacked 3×3 filters capture equivalent large receptive fields with fewer parameters and deeper non-linearities.","Mathematical Formalism: Stacked 3×3 Kernels Emulating Large Effective Receptive Fields."],"med_apps":["可作为迁移学习、感知损失和传统医学 2D encoder 的历史参照。","参数量与显存效率弱于现代残差/轻量主干，且 ImageNet 纹理偏置不能替代医学域预训练。"],"med_apps_en":["Clinical Translation: Widely used for early medical transfer learning, perceptual feature losses, and 2D encoder initialization.","Evidence & Safety Boundary: Historical reference and perceptual loss extractor; heavy FC parameters and lack of residual paths limit modern primary use."],"attrs":{"上一代瓶颈":"早期 CNN 使用较大卷积核且结构异质，深度扩展规律不清","核心想法":"用连续 3×3 卷积和周期性池化把网络规律地加深到 16/19 层","关键改进":"以小卷积堆叠扩大有效感受野并形成可迁移的层级特征","医学适配":"长期作为医学影像迁移学习、感知损失和编码器基线","适用范围与证据":"历史主干与表征参照；参数量大、缺残差连接，现已少作首选"},"attrs_en":{"上一代瓶颈":"Early CNNs relied on heterogeneous large kernels (11×11, 7×7) with unclear scaling rules for network depth.","核心想法":"Replace large kernels with homogeneous stacks of 3×3 convolutions interleaved with 2×2 max-pooling up to 16–19 weight layers.","关键改进":"Stacked 3×3 filters capture equivalent large receptive fields with fewer parameters and deeper non-linearities.","医学适配":"Widely used for early medical transfer learning, perceptual feature losses, and 2D encoder initialization.","适用范围与证据":"Historical reference and perceptual loss extractor; heavy FC parameters and lack of residual paths limit modern primary use."},"paper_title":"Very Deep Convolutional Networks for Large-Scale Image Recognition","paper_url":"https://arxiv.org/abs/1409.1556","code_label":"未提供官方实现","code_url":"","has_code":false,"image":"assets/e353412f87eadd2a7faa.avif"},{"id":"architecture_model_082_googlenet___inception_v1","num":82,"num_str":"082","year":2015,"year_str":"2015","venue":"CVPR","venue_group":"cv","era_group":"era1","title":"GoogLeNet / Inception-v1","family_id":"models_cnn_backbones","family_code":"01","family_short":"CNN 主干与现代卷积","family_en":"CNN Backbones","family_icon":"I","family_label":"CNN 主干：从大规模分类到现代卷积","archetype":"multibranch_inception_cnn","archetype_en":"multibranch_inception_cnn","accent":"#1F4E79","fig_badge":"Figure 2 · PDF p.4","fig_href":"https://openaccess.thecvf.com/content_cvpr_2015/html/Szegedy_Going_Deeper_With_2015_CVPR_paper.html","core_mech":"在每个 Inception module 中并行执行 1×1、降维后 3×3/5×5 和 pooling 分支，再通道拼接。","core_mech_en":"Parallel multi-scale branches (1×1, bottlenecked 3×3, 5×5 convolutions, and pooling) concatenated within each Inception module.","input_desc":"2D 图像","input_en":"2D image tensor","output_desc":"全局分类 logits 与多尺度中间特征","output_en":"Global classification logits and multi-scale intermediate representations","form_title":"核心公式 · Inception 多尺度分支并行与通道拼接","form_title_en":"Core Formalism · Parallel Multi-Scale Inception Branches with 1×1 Bottlenecks","nodes":[{"name":"卷积 Stem","desc":"大步长卷积/池化先降低空间分辨率","name_en":"Convolutional Stem","desc_en":"Ingests 2d image tensor and prepares initial tensor representations (Convolutional Stem)."},{"name":"1×1 分支","desc":"直接 1×1 Conv 捕获通道组合","name_en":"1×1","desc_en":"Executes 1×1 to extract primary structural features and establish spatial/sequence encoding."},{"name":"3×3 分支","desc":"1×1 bottleneck 降维后接 3×3 Conv","name_en":"3×3","desc_en":"Performs 3×3 within the core multibranch inception cnn computation pathway."},{"name":"5×5 分支","desc":"1×1 bottleneck 后接 5×5 Conv，覆盖更大局部尺度","name_en":"5×5","desc_en":"Performs 5×5 within the core multibranch inception cnn computation pathway."},{"name":"Pooling 分支","desc":"3×3 max-pool 后接 1×1 projection","name_en":"Pooling","desc_en":"Performs Pooling within the core multibranch inception cnn computation pathway."},{"name":"通道拼接","desc":"将四个空间对齐分支沿 channel 维合并","name_en":"Channel Concatenation","desc_en":"Performs Channel Concatenation within the core multibranch inception cnn computation pathway."},{"name":"Inception 堆叠","desc":"多个模块与阶段间池化构成 22-layer 主干","name_en":"Inception","desc_en":"Performs Inception within the core multibranch inception cnn computation pathway."},{"name":"辅助分类器","desc":"训练时从中间层接 auxiliary heads 改善梯度与正则化","name_en":"Auxiliary Classifier","desc_en":"Performs Auxiliary Classifier within the core multibranch inception cnn computation pathway."},{"name":"GAP 分类头","desc":"全局平均池化、dropout、线性分类，替代大型 FC 堆叠","name_en":"GAP","desc_en":"Applies GAP to project aggregated representations toward the target task head."},{"name":"类别输出","desc":"主分类 logits","name_en":"Class Logits Output","desc_en":"Produces global classification logits and multi-scale intermediate representations via Class Logits Output."}],"design_principles":["同一层并行处理多个卷积尺度和 pooling，上下文由 concat 显式聚合。","1×1 bottleneck 在昂贵 3×3/5×5 前降维，使多分支计算可控。","辅助分类头只在训练中帮助梯度和正则化，推理主路径仍走最终 GAP head。"],"design_principles_en":["Core Hypothesis: Execute parallel 1×1, 3×3, 5×5 convolutions and pooling within each layer and concatenate their outputs channel-wise.","Architectural Delta: 1×1 bottleneck projections compress channel dimensions prior to expensive spatial kernels for efficient multi-scale aggregation.","Mathematical Formalism: Parallel Multi-Scale Inception Branches with 1×1 Bottlenecks."],"med_apps":["多尺度分支思想适合大小差异显著的病灶、器官和纹理检测。","原始 5×5 分支与复杂手工拓扑已少作首选；现代比较应控制参数量和训练 recipe。"],"med_apps_en":["Clinical Translation: Inspired multi-branch 2D/3D medical encoders and multi-scale lesion detection networks.","Evidence & Safety Boundary: Multi-scale branching remains influential, though complex hand-tuned Inception topologies are largely superseded by residual/ConvNeXt blocks."],"attrs":{"上一代瓶颈":"单一路径卷积难同时覆盖多尺度，直接增加宽度计算昂贵","核心想法":"在同一层并行组合 1×1、3×3、5×5 卷积和池化后拼接","关键改进":"以 1×1 bottleneck 降维并用 Inception 模块高效聚合多尺度","医学适配":"启发医学多尺度病灶检测和多分支 2D/3D 编码器","适用范围与证据":"多尺度设计仍重要；原始模块已被更简洁的残差和层级结构取代"},"attrs_en":{"上一代瓶颈":"Single-kernel convolutional layers struggled to capture multi-scale structures simultaneously, while naively widening layers exploded FLOPs.","核心想法":"Execute parallel 1×1, 3×3, 5×5 convolutions and pooling within each layer and concatenate their outputs channel-wise.","关键改进":"1×1 bottleneck projections compress channel dimensions prior to expensive spatial kernels for efficient multi-scale aggregation.","医学适配":"Inspired multi-branch 2D/3D medical encoders and multi-scale lesion detection networks.","适用范围与证据":"Multi-scale branching remains influential, though complex hand-tuned Inception topologies are largely superseded by residual/ConvNeXt blocks."},"paper_title":"Going Deeper with Convolutions","paper_url":"https://openaccess.thecvf.com/content_cvpr_2015/html/Szegedy_Going_Deeper_With_2015_CVPR_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/BVLC/caffe/tree/master/models/bvlc_googlenet","has_code":true,"image":"assets/d235919a60856ff7e968.avif"},{"id":"architecture_model_083_resnext","num":83,"num_str":"083","year":2017,"year_str":"2017","venue":"CVPR","venue_group":"cv","era_group":"era2","title":"ResNeXt","family_id":"models_cnn_backbones","family_code":"01","family_short":"CNN 主干与现代卷积","family_en":"CNN Backbones","family_icon":"I","family_label":"CNN 主干：从大规模分类到现代卷积","archetype":"aggregated_grouped_residual_cnn","archetype_en":"aggregated_grouped_residual_cnn","accent":"#1F4E79","fig_badge":"Figure 3 · PDF p.4","fig_href":"https://openaccess.thecvf.com/content_cvpr_2017/html/Xie_Aggregated_Residual_Transformations_CVPR_2017_paper.html","core_mech":"在 residual bottleneck 中以 cardinality 控制的 grouped 3×3 convolution 聚合多个等拓扑变换。","core_mech_en":"Aggregates multiple homogeneous residual branches via grouped 3×3 convolutions governed by a cardinality hyperparameter.","input_desc":"图像或上一 stage 特征","input_en":"Input image or preceding stage feature map","output_desc":"分组聚合残差特征与分类/下游输出","output_en":"Grouped aggregated residual representations and downstream task predictions","form_title":"核心公式 · cardinality 控制的聚合残差变换","form_title_en":"Core Formalism · Cardinality-Controlled Aggregated Residual Transformations","nodes":[{"name":"输入 x","desc":"当前 stage feature map","name_en":"input x","desc_en":"Ingests input image or preceding stage feature map and prepares initial tensor representations (input x)."},{"name":"1×1 降维","desc":"把通道映射到分组变换的 bottleneck 宽度","name_en":"1×1","desc_en":"Executes 1×1 to extract primary structural features and establish spatial/sequence encoding."},{"name":"分组 3×3","desc":"cardinality C 个同拓扑分支，以 grouped convolution 高效实现","name_en":"Grouped 3×3 Conv","desc_en":"Performs Grouped 3×3 Conv within the core aggregated grouped residual cnn computation pathway."},{"name":"1×1 扩维","desc":"融合分组输出并恢复 block 输出通道","name_en":"1×1","desc_en":"Performs 1×1 within the core aggregated grouped residual cnn computation pathway."},{"name":"Identity / 投影","desc":"尺寸相同时直连，stage 切换时用 projection shortcut","name_en":"Identity / projection","desc_en":"Performs Identity / projection within the core aggregated grouped residual cnn computation pathway."},{"name":"残差相加","desc":"y=shortcut(x)+Σ_i T_i(x)","name_en":"Residual Addition","desc_en":"Performs Residual Addition within the core aggregated grouped residual cnn computation pathway."},{"name":"层级堆叠","desc":"在多个空间尺度重复 aggregated residual blocks","name_en":"hierarchical","desc_en":"Applies hierarchical to project aggregated representations toward the target task head."},{"name":"GAP / 任务头","desc":"全局分类或作为检测、分割 encoder 输出","name_en":"GAP","desc_en":"Produces grouped aggregated residual representations and downstream task predictions via GAP."}],"design_principles":["除深度和宽度外，引入 cardinality 作为表示容量维度。","等拓扑分支的 split-transform-merge 可由 grouped 3×3 convolution 紧凑实现。","残差捷径保持优化稳定，分组卷积控制在相近计算量下增加变换多样性。"],"design_principles_en":["Core Hypothesis: Aggregate C parallel identical-topology transformations inside a residual bottleneck, introducing cardinality C as a third scaling axis.","Architectural Delta: Formulates split–transform–merge cleanly as grouped convolution with minimal engineering overhead.","Mathematical Formalism: Cardinality-Controlled Aggregated Residual Transformations."],"med_apps":["可替换 2D/3D 医学分类、检测和分割编码器中的普通 ResNet bottleneck。","分组数、每组宽度和 3D 内存需共同调节；架构优势不能替代强数据增强与外部验证。"],"med_apps_en":["Clinical Translation: Frequently adopted in 2D/3D medical classification, nodule detection, and volumetric encoder backbones.","Evidence & Safety Boundary: Grouped/depthwise convolution is now a permanent staple of modern CNNs."],"attrs":{"上一代瓶颈":"仅靠加深或加宽网络的计算收益递减且设计空间复杂","核心想法":"在残差块中并行聚合等拓扑分支，以 cardinality 控制表示容量","关键改进":"引入 grouped convolution 实现可扩展的 split-transform-merge","医学适配":"常用于 2D/3D 医学分类、检测和分割编码器","适用范围与证据":"grouped convolution 已成现代 CNN 基础构件；原始主干不是当前唯一强基线"},"attrs_en":{"上一代瓶颈":"Scaling depth or width alone yielded diminishing returns and required intricate per-branch hyperparameter tuning.","核心想法":"Aggregate C parallel identical-topology transformations inside a residual bottleneck, introducing cardinality C as a third scaling axis.","关键改进":"Formulates split–transform–merge cleanly as grouped convolution with minimal engineering overhead.","医学适配":"Frequently adopted in 2D/3D medical classification, nodule detection, and volumetric encoder backbones.","适用范围与证据":"Grouped/depthwise convolution is now a permanent staple of modern CNNs."},"paper_title":"Aggregated Residual Transformations for Deep Neural Networks","paper_url":"https://openaccess.thecvf.com/content_cvpr_2017/html/Xie_Aggregated_Residual_Transformations_CVPR_2017_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/facebookresearch/ResNeXt","has_code":true,"image":"assets/593079305d6062e5271a.avif"},{"id":"architecture_model_084_senet","num":84,"num_str":"084","year":2018,"year_str":"2018","venue":"CVPR","venue_group":"cv","era_group":"era2","title":"SENet","family_id":"models_cnn_backbones","family_code":"01","family_short":"CNN 主干与现代卷积","family_en":"CNN Backbones","family_icon":"I","family_label":"CNN 主干：从大规模分类到现代卷积","archetype":"channel_recalibration_cnn","archetype_en":"channel_recalibration_cnn","accent":"#1F4E79","fig_badge":"Figure 1 · PDF p.2","fig_href":"https://openaccess.thecvf.com/content_cvpr_2018/html/Hu_Squeeze-and-Excitation_Networks_CVPR_2018_paper.html","core_mech":"全局平均池化 squeeze 后经 bottleneck MLP 产生每通道 sigmoid 门，对卷积特征逐通道重标定。","core_mech_en":"Global average pooling (Squeeze) followed by a lightweight bottleneck MLP (Excitation) producing per-channel sigmoid gates.","input_desc":"卷积 block 的多通道特征 X","input_en":"Multi-channel convolutional feature tensor X","output_desc":"输入自适应通道重标定后的特征或任务预测","output_en":"Input-adaptively channel-recalibrated feature tensor or classification output","form_title":"核心公式 · 通道 squeeze、excitation 与重标定","form_title_en":"Core Formalism · Channel Squeeze, Excitation, and Adaptive Recalibration","nodes":[{"name":"特征 X","desc":"任意主干 block 产生的 H×W×C 特征","name_en":"feature X","desc_en":"Ingests multi-channel convolutional feature tensor x and prepares initial tensor representations (feature X)."},{"name":"主变换 F","desc":"ResNet/Inception 等原有卷积变换得到 U","name_en":"Stage 02","desc_en":"Executes Stage 02 to extract primary structural features and establish spatial/sequence encoding."},{"name":"Squeeze","desc":"对 U 每通道做 global average pooling 得到 z∈R^C","name_en":"Squeeze","desc_en":"Performs Squeeze within the core channel recalibration cnn computation pathway."},{"name":"FC 降维","desc":"W1 z 后 ReLU，按 reduction ratio 压缩通道描述","name_en":"FC","desc_en":"Performs FC within the core channel recalibration cnn computation pathway."},{"name":"FC+Sigmoid","desc":"W2 恢复 C 维并输出 0–1 通道门 s","name_en":"FC+Sigmoid","desc_en":"Performs FC+Sigmoid within the core channel recalibration cnn computation pathway."},{"name":"通道缩放","desc":"U_hat_c=s_c·U_c，对整张 feature map 逐通道重标定","name_en":"Channel Scaling","desc_en":"Performs Channel Scaling within the core channel recalibration cnn computation pathway."},{"name":"残差合并","desc":"在 SE-ResNet 中将 U_hat 与 shortcut 相加","name_en":"residual","desc_en":"Applies residual to project aggregated representations toward the target task head."},{"name":"任务输出","desc":"进入后续 stage 或分类/分割头","name_en":"Task Output","desc_en":"Produces input-adaptively channel-recalibrated feature tensor or classification output via Task Output."}],"design_principles":["global squeeze 把每通道的全图响应压缩为上下文描述，随后门控网络学习通道依赖。","excitation 是输入自适应的软重标定，可插入多种主干而几乎不改变空间尺寸。","SE 权重只说明模型的通道增益，不提供病灶空间定位，也不自动构成因果解释。"],"design_principles_en":["Core Hypothesis: Squeeze global spatial statistics per channel and excite a small gating MLP to dynamically recalibrate channel responses.","Architectural Delta: Models inter-channel dependencies explicitly at negligible parameter and compute overhead; plug-and-play across backbones.","Mathematical Formalism: Channel Squeeze, Excitation, and Adaptive Recalibration."],"med_apps":["可用于器官分割、病灶分类和多模态 feature-channel 融合，计算开销低。","小数据中门控可能追随扫描协议或设备通道偏差；解释时应结合空间证据和外部队列。"],"med_apps_en":["Clinical Translation: Ubiquitous across medical organ segmentation, lesion classification, and multi-sequence MRI channel fusion.","Evidence & Safety Boundary: Canonical channel-attention module; provides global channel weighting rather than spatial localization."],"attrs":{"上一代瓶颈":"普通卷积隐式混合通道，缺少输入自适应的通道选择","核心想法":"全局汇聚通道统计后用小型门控网络重标定各通道响应","关键改进":"以极低开销显式建模通道依赖并可插入任意主干","医学适配":"广泛用于器官分割、病灶分类和多模态通道融合","适用范围与证据":"通道注意力经典模块；解释性有限，空间定位仍需其他机制"},"attrs_en":{"上一代瓶颈":"Standard convolutions fuse channels with fixed learned weights, lacking global content-aware channel selection.","核心想法":"Squeeze global spatial statistics per channel and excite a small gating MLP to dynamically recalibrate channel responses.","关键改进":"Models inter-channel dependencies explicitly at negligible parameter and compute overhead; plug-and-play across backbones.","医学适配":"Ubiquitous across medical organ segmentation, lesion classification, and multi-sequence MRI channel fusion.","适用范围与证据":"Canonical channel-attention module; provides global channel weighting rather than spatial localization."},"paper_title":"Squeeze-and-Excitation Networks","paper_url":"https://openaccess.thecvf.com/content_cvpr_2018/html/Hu_Squeeze-and-Excitation_Networks_CVPR_2018_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/hujie-frank/SENet","has_code":true,"image":"assets/700c02d515d4c575125a.avif"},{"id":"architecture_model_085_efficientnet","num":85,"num_str":"085","year":2019,"year_str":"2019","venue":"ICML","venue_group":"ml","era_group":"era2","title":"EfficientNet","family_id":"models_cnn_backbones","family_code":"01","family_short":"CNN 主干与现代卷积","family_en":"CNN Backbones","family_icon":"I","family_label":"CNN 主干：从大规模分类到现代卷积","archetype":"compound_scaled_mbconv_cnn","archetype_en":"compound_scaled_mbconv_cnn","accent":"#1F4E79","fig_badge":"Table 1 · PDF p.5","fig_href":"https://proceedings.mlr.press/v97/tan19a.html","core_mech":"以 NAS 设计的 MBConv+SE 基线配合 depth/width/resolution 三维 compound scaling。","core_mech_en":"NAS-discovered MBConv+SE baseline scaled jointly across depth, width, and input resolution via a compound coefficient φ.","input_desc":"2D 图像与缩放系数 phi","input_en":"2D image scaled according to compound coefficient φ","output_desc":"效率优化的分类 logits 或层级特征","output_en":"Compute-efficient classification logits or multi-scale feature pyramid","form_title":"核心公式 · 深度、宽度与分辨率的复合缩放律","form_title_en":"Core Formalism · Principled Compound Scaling of Depth, Width, and Resolution","nodes":[{"name":"复合缩放","desc":"depth=alpha^phi、width=beta^phi、resolution=gamma^phi，并满足近似计算约束","name_en":"Compound Scaling","desc_en":"Ingests 2d image scaled according to compound coefficient φ and prepares initial tensor representations (Compound Scaling)."},{"name":"输入图像","desc":"分辨率随 B0→B7 同步扩大","name_en":"Input Image","desc_en":"Executes Input Image to extract primary structural features and establish spatial/sequence encoding."},{"name":"卷积 Stem","desc":"3×3 stride-2 Conv 建立浅层特征","name_en":"Convolutional Stem","desc_en":"Performs Convolutional Stem within the core compound scaled mbconv cnn computation pathway."},{"name":"Block 输入","desc":"前一 MBConv 的输出；identity shortcut 从这里绕过主变换","name_en":"Block input","desc_en":"Performs Block input within the core compound scaled mbconv cnn computation pathway."},{"name":"MBConv 扩维","desc":"1×1 expansion 形成高维 inverted bottleneck；首类 MBConv1 可不扩维","name_en":"MBConv","desc_en":"Performs MBConv within the core compound scaled mbconv cnn computation pathway."},{"name":"Depthwise Conv","desc":"3×3/5×5 逐通道空间卷积，stride 控制 stage 下采样","name_en":"Depthwise Conv","desc_en":"Performs Depthwise Conv within the core compound scaled mbconv cnn computation pathway."},{"name":"SE 门控","desc":"global pooling 与小 MLP 对 expanded channels 重标定","name_en":"SE","desc_en":"Performs SE within the core compound scaled mbconv cnn computation pathway."},{"name":"线性投影","desc":"1×1 project 回低维；尺寸相同时接 identity skip 与 stochastic depth","name_en":"projection","desc_en":"Performs projection within the core compound scaled mbconv cnn computation pathway."},{"name":"NAS-B0 Stages","desc":"按搜索得到的 kernel、扩张率、通道和重复数堆叠 MBConv","name_en":"NAS-B0 Stages","desc_en":"Applies NAS-B0 Stages to project aggregated representations toward the target task head."},{"name":"GAP 分类头","desc":"1×1 head、global average pooling、dropout 与 FC","name_en":"GAP","desc_en":"Produces compute-efficient classification logits or multi-scale feature pyramid via GAP."}],"design_principles":["先以 NAS 得到 EfficientNet-B0，再用单一 phi 协调深度、宽度和输入分辨率，而非只放大一维。","MBConv 以 expansion、depthwise spatial filtering、SE 与线性 projection 获得较高计算效率。","compound coefficients 是经验/搜索确定的缩放规律，不保证直接迁移到 3D 体数据。"],"design_principles_en":["Core Hypothesis: Couple depth (α^φ), width (β^φ), and resolution (γ^φ) under a unified compound scaling constraint.","Architectural Delta: Combines MobileInvertedBottleneck (MBConv + SE) with empirically calibrated compound scaling laws.","Mathematical Formalism: Principled Compound Scaling of Depth, Width, and Resolution."],"med_apps":["适合作为超声、X-ray、皮肤图像及移动筛查的参数/算力效率基线。","在高分辨率 3D CT/MRI 中，体素数主导内存，2D compound scaling 需重新设计而非机械套用。"],"med_apps_en":["Clinical Translation: Widely deployed in resource-constrained 2D medical classification, point-of-care ultrasound, and dermatology/fundus screening.","Evidence & Safety Boundary: Strong 2D efficiency baseline; depthwise separable kernels and high resolution require separate activation-memory audits in 3D."],"attrs":{"上一代瓶颈":"任意单独加深、加宽或提高分辨率常造成计算失衡","核心想法":"用复合系数联合缩放网络深度、宽度和输入分辨率","关键改进":"以 NAS 获得 B0 基线，并系统研究、经验确定 compound scaling 系数","医学适配":"后续被用于算力受限的医学分类、超声和移动端筛查","适用范围与证据":"仍是效率基线；高分辨率 3D 医学任务的内存瓶颈需另行处理"},"attrs_en":{"上一代瓶颈":"Scaling network depth, width, or image resolution in isolation rapidly saturates accuracy and wastes FLOPs.","核心想法":"Couple depth (α^φ), width (β^φ), and resolution (γ^φ) under a unified compound scaling constraint.","关键改进":"Combines MobileInvertedBottleneck (MBConv + SE) with empirically calibrated compound scaling laws.","医学适配":"Widely deployed in resource-constrained 2D medical classification, point-of-care ultrasound, and dermatology/fundus screening.","适用范围与证据":"Strong 2D efficiency baseline; depthwise separable kernels and high resolution require separate activation-memory audits in 3D."},"paper_title":"EfficientNet: Rethinking Model Scaling for Convolutional Neural Networks","paper_url":"https://proceedings.mlr.press/v97/tan19a.html","code_label":"作者/机构官方实现","code_url":"https://github.com/tensorflow/tpu/tree/master/models/official/efficientnet","has_code":true,"image":"assets/bd372ed165307e223e7a.avif"},{"id":"architecture_model_086_u_net","num":86,"num_str":"086","year":2020,"year_str":"2020","venue":"IEEE Transactions on Medical Imaging","venue_group":"journal","era_group":"era3","title":"U-Net++","family_id":"models_dense_segmentation","family_code":"02","family_short":"稠密预测与医学分割","family_en":"Dense Segmentation","family_icon":"II","family_label":"稠密预测与医学分割：从像素输出到自配置系统","archetype":"nested_dense_skip_unet","archetype_en":"nested_dense_skip_unet","accent":"#145E75","fig_badge":"Figure 1 · PDF p.2","fig_href":"https://doi.org/10.1109/TMI.2019.2959609","core_mech":"以 X_i,j 嵌套稠密卷积节点重写 U-Net 跳连，并从多个顶层节点施加深监督。","core_mech_en":"Rewrites U-Net skip pathways as a dense nested grid of intermediate convolutional nodes X_{i,j} with multi-depth deep supervision.","input_desc":"2D/3D 医学图像","input_en":"2D or 3D medical image","output_desc":"深监督融合或选定深度的分割概率图","output_en":"Deeply supervised ensemble or depth-pruned segmentation probability map","form_title":"核心公式 · U-Net++ 嵌套稠密跳连节点更新","form_title_en":"Core Formalism · U-Net++ Nested Dense Skip Node Update Equation","nodes":[{"name":"输入图像","desc":"进入多尺度卷积 encoder","name_en":"Input Image","desc_en":"Ingests 2d or 3d medical image and prepares initial tensor representations (Input Image)."},{"name":"X_i,0 编码器","desc":"沿 i 增大逐级下采样，形成不同语义深度的特征","name_en":"X_i,0 encoder","desc_en":"Executes X_i,0 encoder to extract primary structural features and establish spatial/sequence encoding."},{"name":"上采样邻级","desc":"将 X_{i+1,j-1} 上采样到第 i 层分辨率","name_en":"upsampling","desc_en":"Performs upsampling within the core nested dense skip unet computation pathway."},{"name":"嵌套节点 X_i,j","desc":"X_i,j=H([X_i,0…X_i,j-1,Up(X_{i+1,j-1})])","name_en":"X_i,j","desc_en":"Performs X_i,j within the core nested dense skip unet computation pathway."},{"name":"Dense skip 路径","desc":"同分辨率早期节点全部拼接，逐步缩小 encoder/decoder 语义差","name_en":"Dense skip","desc_en":"Performs Dense skip within the core nested dense skip unet computation pathway."},{"name":"嵌套 U 网格","desc":"不同 j 构成由浅到深的多个可用 U-Net 子网络","name_en":"U mesh","desc_en":"Performs U mesh within the core nested dense skip unet computation pathway."},{"name":"深监督 heads","desc":"从 X_0,1…X_0,J 接多个 segmentation heads 联合训练","name_en":"deep supervision heads","desc_en":"Applies deep supervision heads to project aggregated representations toward the target task head."},{"name":"分割输出","desc":"平均多头或剪枝后选定一个深度 head","name_en":"Segmentation Output","desc_en":"Produces deeply supervised ensemble or depth-pruned segmentation probability map via Segmentation Output."}],"design_principles":["不是只在 encoder 与 decoder 之间接一条长跳连，而是在跳连路径上加入逐级卷积节点。","同尺度 dense concatenation 让浅特征逐步被深语义加工后再进入 decoder。","深监督训练多个有效深度，可在推理时做多头平均或按速度要求剪枝。"],"design_principles_en":["Core Hypothesis: Bridge the encoder–decoder semantic gap via dense intermediate convolutional skip pathways and multi-scale deep supervision.","Architectural Delta: Nested dense skip nodes X_{i,j} progressively fuse multi-scale features and support inference-time model pruning.","Mathematical Formalism: U-Net++ Nested Dense Skip Node Update Equation."],"med_apps":["常用于器官、息肉、细胞和小病灶分割，尤其适合需要多尺度边界融合的任务。","嵌套节点显著增加 activation memory；收益应与 nnU-Net 等强配置在同数据划分和训练预算下比较。"],"med_apps_en":["Clinical Translation: Widely used in polyp, nuclei, liver, and small-lesion medical segmentation studies.","Evidence & Safety Boundary: Classic U-Net skip variant; practical gains must always be verified against a properly configured nnU-Net baseline."],"attrs":{"上一代瓶颈":"原始 U-Net 直接拼接低层与高层特征，语义不匹配且多尺度融合粗糙","核心想法":"以嵌套稠密跳连和深监督逐步缩小 encoder 与 decoder 特征语义差距","关键改进":"在跳连路径中引入中间卷积节点并支持可剪枝的多深度输出","医学适配":"常用于器官、息肉、细胞和小病灶分割","适用范围与证据":"医学分割经典变体；复杂跳连的增益需与 nnU-Net 等强基线公平比较"},"attrs_en":{"上一代瓶颈":"Standard U-Net directly concatenates raw shallow encoder features with high-level decoder features across a large semantic gap.","核心想法":"Bridge the encoder–decoder semantic gap via dense intermediate convolutional skip pathways and multi-scale deep supervision.","关键改进":"Nested dense skip nodes X_{i,j} progressively fuse multi-scale features and support inference-time model pruning.","医学适配":"Widely used in polyp, nuclei, liver, and small-lesion medical segmentation studies.","适用范围与证据":"Classic U-Net skip variant; practical gains must always be verified against a properly configured nnU-Net baseline."},"paper_title":"UNet++: Redesigning Skip Connections to Exploit Multiscale Features in Image Segmentation","paper_url":"https://doi.org/10.1109/TMI.2019.2959609","code_label":"作者/机构官方实现","code_url":"https://github.com/MrGiovanni/UNetPlusPlus","has_code":true,"image":"assets/bd6950062b274aef16bd.avif"},{"id":"architecture_model_087_attention_u_net","num":87,"num_str":"087","year":2018,"year_str":"2018","venue":"MIDL","venue_group":"miccai","era_group":"era2","title":"Attention U-Net","family_id":"models_dense_segmentation","family_code":"02","family_short":"稠密预测与医学分割","family_en":"Dense Segmentation","family_icon":"II","family_label":"稠密预测与医学分割：从像素输出到自配置系统","archetype":"gated_skip_unet","archetype_en":"gated_skip_unet","accent":"#145E75","fig_badge":"Figure 1 · PDF p.3","fig_href":"https://openreview.net/forum?id=Skft7cijM","core_mech":"由粗尺度 decoder gating signal 计算空间 attention coefficients，在拼接前逐位置筛选 encoder skip。","core_mech_en":"Computes spatial soft-attention coefficients α ∈ [0,1] from coarse decoder gating signals to filter encoder skips prior to concatenation.","input_desc":"医学图像","input_en":"2D or 3D medical image","output_desc":"经空间注意力门筛选 skip features 的分割图","output_en":"Segmentation map decoded from spatially gated skip connections","form_title":"核心公式 · decoder 条件化的空间注意力门","form_title_en":"Core Formalism · Additive Decoder-Conditioned Spatial Attention Gate","nodes":[{"name":"输入图像","desc":"进入标准 U-Net encoder","name_en":"Input Image","desc_en":"Ingests 2d or 3d medical image and prepares initial tensor representations (Input Image)."},{"name":"Encoder skip x_l","desc":"高分辨率浅层特征，含目标边界与大量背景","name_en":"Encoder skip x_l","desc_en":"Executes Encoder skip x_l to extract primary structural features and establish spatial/sequence encoding."},{"name":"Decoder gate g","desc":"较粗尺度深层语义信号，为注意力提供目标上下文","name_en":"Decoder gate g","desc_en":"Performs Decoder gate g within the core gated skip unet computation pathway."},{"name":"加性注意力","desc":"1×1 投影 x_l 与 g，对齐后相加、ReLU，再经 psi 计算 logits","name_en":"attention","desc_en":"Performs attention within the core gated skip unet computation pathway."},{"name":"空间系数 alpha","desc":"sigmoid 得到逐位置软门，通常在通道间共享","name_en":"spatial alpha","desc_en":"Performs spatial alpha within the core gated skip unet computation pathway."},{"name":"门控 skip","desc":"x_hat_l=alpha⊙x_l，抑制与目标无关的背景响应","name_en":"skip","desc_en":"Performs skip within the core gated skip unet computation pathway."},{"name":"Decoder 融合","desc":"将 gated skip 与上采样 decoder feature 拼接并卷积","name_en":"Decoder fusion","desc_en":"Applies Decoder fusion to project aggregated representations toward the target task head."},{"name":"分割输出","desc":"全分辨率类别概率图","name_en":"Segmentation Output","desc_en":"Produces segmentation map decoded from spatially gated skip connections via Segmentation Output."}],"design_principles":["用深层 decoder 语义作为 gating signal，决定浅层 skip 中哪些空间位置值得传递。","attention gate 位于 skip connection 上，不替代 encoder-decoder 主干或全局 self-attention。","软门可端到端学习，无需额外 ROI 裁剪标签，但注意力图仍由分割损失间接监督。"],"design_principles_en":["Core Hypothesis: Gate high-resolution encoder skip features spatially using contextual gating signals from the coarser decoder stage.","Architectural Delta: Lightweight additive attention gates suppress irrelevant background regions without requiring explicit two-stage ROI localization.","Mathematical Formalism: Additive Decoder-Conditioned Spatial Attention Gate."],"med_apps":["适合小器官和小病灶场景，可减少背景 skip feature 对 decoder 的干扰。","提升高度依赖数据、损失和基线；若 gate 过早抑制弱病灶，decoder 无法从被删除的细节恢复。"],"med_apps_en":["Clinical Translation: Frequently integrated into pancreas, small-lesion, and multi-organ segmentation networks.","Evidence & Safety Boundary: Practical and lightweight spatial gating module, though improvements depend heavily on loss and pipeline setup."],"attrs":{"上一代瓶颈":"U-Net 跳连把大量背景细节无差别传给 decoder，小器官易被淹没","核心想法":"用 decoder gating 信号对 skip 特征做空间注意力筛选","关键改进":"在不额外裁剪 ROI 的情况下突出与目标相关的局部区域","医学适配":"广泛用于小器官和病灶分割以及级联定位","适用范围与证据":"注意力门控仍实用；提升通常依赖数据、损失和基线配置"},"attrs_en":{"上一代瓶颈":"Unfiltered U-Net skip connections pass cluttered background activations to the decoder, degrading small-organ false-positive rates.","核心想法":"Gate high-resolution encoder skip features spatially using contextual gating signals from the coarser decoder stage.","关键改进":"Lightweight additive attention gates suppress irrelevant background regions without requiring explicit two-stage ROI localization.","医学适配":"Frequently integrated into pancreas, small-lesion, and multi-organ segmentation networks.","适用范围与证据":"Practical and lightweight spatial gating module, though improvements depend heavily on loss and pipeline setup."},"paper_title":"Attention U-Net: Learning Where to Look for the Pancreas","paper_url":"https://openreview.net/pdf?id=Skft7cijM","code_label":"作者/机构官方实现","code_url":"https://github.com/ozan-oktay/Attention-Gated-Networks","has_code":true,"image":"assets/a434fd585a879e119bed.avif"},{"id":"architecture_model_088_h_denseunet","num":88,"num_str":"088","year":2018,"year_str":"2018","venue":"IEEE Transactions on Medical Imaging","venue_group":"journal","era_group":"era2","title":"H-DenseUNet","family_id":"models_dense_segmentation","family_code":"02","family_short":"稠密预测与医学分割","family_en":"Dense Segmentation","family_icon":"II","family_label":"稠密预测与医学分割：从像素输出到自配置系统","archetype":"hybrid_2d_3d_dense_unet","archetype_en":"hybrid_2d_3d_dense_unet","accent":"#145E75","fig_badge":"Figure 2 · PDF p.4","fig_href":"https://doi.org/10.1109/TMI.2018.2845918","core_mech":"先以 2D DenseUNet 学切片内细节，再将特征堆叠进 3D DenseUNet，并通过 hybrid feature fusion 联合预测。","core_mech_en":"Extracts intra-slice features via a 2D DenseUNet, stacks them into a 3D DenseUNet, and fuses both via a hybrid feature fusion (HFF) layer.","input_desc":"高分辨率腹部 CT 体","input_en":"High-resolution volumetric abdominal CT scan","output_desc":"肝脏/肿瘤 3D 分割概率体","output_en":"3D volumetric liver and tumor segmentation probability volume","form_title":"核心公式 · 2D 切片特征堆叠与 3D 混合融合","form_title_en":"Core Formalism · Hybrid 2D Intra-Slice and 3D Inter-Slice Dense Feature Fusion","nodes":[{"name":"CT 体","desc":"按轴位切片供 2D 分支，同时保留 3D 体坐标","name_en":"CT","desc_en":"Ingests high-resolution volumetric abdominal ct scan and prepares initial tensor representations (CT)."},{"name":"2D DenseUNet","desc":"逐切片 dense blocks+U-shaped decoder 提取高分辨率平面纹理","name_en":"2D DenseUNet","desc_en":"Executes 2D DenseUNet to extract primary structural features and establish spatial/sequence encoding."},{"name":"2D 先验特征","desc":"切片预测/特征保留细粒度边界与纹理","name_en":"2D prior feature","desc_en":"Performs 2D prior feature within the core hybrid 2d 3d dense unet computation pathway."},{"name":"2D→3D 堆叠","desc":"将对应切片特征重排为与体数据对齐的 3D feature volume","name_en":"2D→3D","desc_en":"Performs 2D→3D within the core hybrid 2d 3d dense unet computation pathway."},{"name":"3D DenseUNet","desc":"在较受控容量下用 3D dense blocks 学跨切片上下文","name_en":"3D DenseUNet","desc_en":"Performs 3D DenseUNet within the core hybrid 2d 3d dense unet computation pathway."},{"name":"Hybrid Feature Fusion","desc":"融合 2D intra-slice 与 3D inter-slice 特征并支持联合优化","name_en":"Hybrid Feature Fusion","desc_en":"Performs Hybrid Feature Fusion within the core hybrid 2d 3d dense unet computation pathway."},{"name":"3D 分割头","desc":"1×1×1 卷积映射到肝脏/肿瘤类别 logits","name_en":"3D","desc_en":"Applies 3D to project aggregated representations toward the target task head."},{"name":"概率体","desc":"完整体素级 segmentation mask","name_en":"Stage 08","desc_en":"Produces 3d volumetric liver and tumor segmentation probability volume via Stage 08."}],"design_principles":["2D DenseUNet 以较低显存学习高分辨率切片纹理，3D DenseUNet 补充跨切片解剖连续性。","2D-to-3D 重排与 hybrid fusion 让两种上下文在统一体坐标中联合使用。","dense connections 强化特征复用和梯度流，但会增加 activation memory，尤其在 3D 分支。"],"design_principles_en":["Core Hypothesis: Cascade a deep 2D DenseUNet for high-resolution in-plane representation with a 3D DenseUNet for volumetric context.","Architectural Delta: End-to-end joint Hybrid Feature Fusion (HFF) reconciling 2D transferability with 3D volumetric continuity.","Mathematical Formalism: Hybrid 2D Intra-Slice and 3D Inter-Slice Dense Feature Fusion."],"med_apps":["针对肝脏与肿瘤 CT 分割设计，是高分辨体数据中平衡 2D 细节和 3D 上下文的代表。","对非轴向各向异性、其他器官和现代 patch-based 3D 配置的优势需重新验证，不能直接外推。"],"med_apps_en":["Clinical Translation: Landmark hybrid 2.5D/3D architecture for volumetric CT liver and tumor segmentation.","Evidence & Safety Boundary: Historically strong hybrid design; modern patch-based 3D nnU-Net and MedNeXt pipelines offer simpler reproducibility."],"attrs":{"上一代瓶颈":"纯 2D 缺跨切片信息，纯 3D 在高分辨率 CT 上显存和数据需求过高","核心想法":"先以 2D DenseUNet 提取丰富切片内特征，再用 3D DenseUNet 融合体上下文","关键改进":"混合 2D/3D 稠密连接在计算可控下同时建模纹理与体结构","医学适配":"是 Dense U-Net 系列在肝脏与肿瘤 3D 分割中的代表","适用范围与证据":"历史强基线；现代 patch-based 3D 与自动配置框架通常更易复现"},"attrs_en":{"上一代瓶颈":"Pure 2D networks miss z-axis continuity, whereas pure 3D networks cannot fit deep high-resolution encoders in GPU memory.","核心想法":"Cascade a deep 2D DenseUNet for high-resolution in-plane representation with a 3D DenseUNet for volumetric context.","关键改进":"End-to-end joint Hybrid Feature Fusion (HFF) reconciling 2D transferability with 3D volumetric continuity.","医学适配":"Landmark hybrid 2.5D/3D architecture for volumetric CT liver and tumor segmentation.","适用范围与证据":"Historically strong hybrid design; modern patch-based 3D nnU-Net and MedNeXt pipelines offer simpler reproducibility."},"paper_title":"H-DenseUNet: Hybrid Densely Connected UNet for Liver and Tumor Segmentation From CT Volumes","paper_url":"https://doi.org/10.1109/TMI.2018.2845918","code_label":"作者/机构官方实现","code_url":"https://github.com/xmengli/H-DenseUNet","has_code":true,"image":"assets/96879eafd21ccee68ba4.avif"},{"id":"architecture_model_089_deit","num":89,"num_str":"089","year":2021,"year_str":"2021","venue":"ICML","venue_group":"ml","era_group":"era3","title":"DeiT","family_id":"models_vision_transformers","family_code":"04","family_short":"视觉 Transformer","family_en":"Vision Transformers","family_icon":"IV","family_label":"视觉 Transformer：全局交互、层级窗口与高分辨率代价","archetype":"distilled_data_efficient_vit","archetype_en":"distilled_data_efficient_vit","accent":"#1F4E79","fig_badge":"Figure 2 · PDF p.4","fig_href":"https://proceedings.mlr.press/v139/touvron21a.html","core_mech":"增加 distillation token 和专用 head，使 CNN teacher 信号通过 Transformer attention 注入 ViT。","core_mech_en":"Augments ViT with a learnable distillation token that interacts with patch tokens via self-attention to distill inductive biases from a CNN teacher.","input_desc":"ImageNet/医学 2D 图像与训练时 CNN teacher logits","input_en":"2D image (plus CNN teacher hard predictions during training)","output_desc":"class token 与 distillation token 融合的分类预测","output_en":"Fused class-token and distillation-token classification prediction","form_title":"核心公式 · 类别 token 与蒸馏 token 的双头目标","form_title_en":"Core Formalism · Joint Classification Token & Hard-Label Teacher Distillation Token Objective","nodes":[{"name":"输入图像","desc":"经强增强与常规 ImageNet 规模监督训练","name_en":"Input Image","desc_en":"Ingests 2d image (plus cnn teacher hard predictions during training) and prepares initial tensor representations (Input Image)."},{"name":"Patch tokens","desc":"固定大小 image patches 线性投影并加位置编码","name_en":"Patch tokens","desc_en":"Executes Patch tokens to extract primary structural features and establish spatial/sequence encoding."},{"name":"CLS + Distill","desc":"两个可学习 token 分别服务真实标签与 teacher 蒸馏","name_en":"CLS + Distill","desc_en":"Performs CLS + Distill within the core distilled data efficient vit computation pathway."},{"name":"ViT Encoder","desc":"多层 MHSA+MLP 共同更新 patch、class 和 distillation tokens","name_en":"ViT Encoder","desc_en":"Performs ViT Encoder within the core distilled data efficient vit computation pathway."},{"name":"CNN Teacher","desc":"训练时提供 hard/soft teacher target，不进入部署主干","name_en":"CNN Teacher","desc_en":"Performs CNN Teacher within the core distilled data efficient vit computation pathway."},{"name":"Class head","desc":"CLS token 对真实类别标签优化","name_en":"Class head","desc_en":"Performs Class head within the core distilled data efficient vit computation pathway."},{"name":"Distill head","desc":"distillation token 对 teacher 预测优化","name_en":"Distill head","desc_en":"Performs Distill head within the core distilled data efficient vit computation pathway."},{"name":"双头融合","desc":"推理时通常平均 class 与 distillation head 预测","name_en":"fusion","desc_en":"Applies fusion to project aggregated representations toward the target task head."},{"name":"类别输出","desc":"最终分类 logits/probabilities","name_en":"Class Logits Output","desc_en":"Produces fused class-token and distillation-token classification prediction via Class Logits Output."}],"design_principles":["数据效率主要来自强训练 recipe、正则和增强，并非只靠改变 ViT block。","distillation token 在 self-attention 中与图像 patches 共同交互，学习 CNN teacher 的归纳偏置。","teacher 只在训练中提供目标，部署时 DeiT 仍是纯 Transformer。"],"design_principles_en":["Core Hypothesis: Combine aggressive data augmentation/regularization with a dedicated distillation token that learns from a convnet teacher.","Architectural Delta: Attention-based token distillation (distinct from logit averaging) + RandAugment, Mixup, CutMix, and Stochastic Depth recipe.","Mathematical Formalism: Joint Classification Token & Hard-Label Teacher Distillation Token Objective."],"med_apps":["可在有限医学标签下把 CNN teacher 的经验迁移到 ViT，并保留纯 token encoder 的扩展接口。","ImageNet teacher 的纹理/类别偏置可能迁移到医学域；最好使用领域 teacher、领域预训练和外部验证。"],"med_apps_en":["Clinical Translation: Lowered the barrier for training and fine-tuning Vision Transformers on moderate-sized medical imaging cohorts.","Evidence & Safety Boundary: Established standard ViT training recipes; in-domain medical SSL pretraining still outperforms purely supervised recipes."],"attrs":{"上一代瓶颈":"原始 ViT 依赖超大私有数据，常规数据规模下训练不稳","核心想法":"用强增强、正则化和蒸馏 token 在 ImageNet 上高效训练 ViT","关键改进":"把 CNN 教师知识通过 attention distillation 注入 Transformer","医学适配":"降低医学 ViT 从头训练或小数据微调的门槛","适用范围与证据":"训练 recipe 影响巨大；医学域仍需领域预训练与严格外部验证"},"attrs_en":{"上一代瓶颈":"Original ViT required hundreds of millions of proprietary images (JFT-300M) and failed to generalize when trained on medium-sized datasets.","核心想法":"Combine aggressive data augmentation/regularization with a dedicated distillation token that learns from a convnet teacher.","关键改进":"Attention-based token distillation (distinct from logit averaging) + RandAugment, Mixup, CutMix, and Stochastic Depth recipe.","医学适配":"Lowered the barrier for training and fine-tuning Vision Transformers on moderate-sized medical imaging cohorts.","适用范围与证据":"Established standard ViT training recipes; in-domain medical SSL pretraining still outperforms purely supervised recipes."},"paper_title":"Training Data-Efficient Image Transformers & Distillation through Attention","paper_url":"https://proceedings.mlr.press/v139/touvron21a.html","code_label":"作者/机构官方实现","code_url":"https://github.com/facebookresearch/deit","has_code":true,"image":"assets/ca9c54f89c407a6cd0ee.avif"},{"id":"architecture_model_090_pvt","num":90,"num_str":"090","year":2021,"year_str":"2021","venue":"ICCV","venue_group":"cv","era_group":"era3","title":"PVT","family_id":"models_vision_transformers","family_code":"04","family_short":"视觉 Transformer","family_en":"Vision Transformers","family_icon":"IV","family_label":"视觉 Transformer：全局交互、层级窗口与高分辨率代价","archetype":"pyramidal_spatial_reduction_transformer","archetype_en":"pyramidal_spatial_reduction_transformer","accent":"#1F4E79","fig_badge":"Figure 3 · PDF p.4","fig_href":"https://openaccess.thecvf.com/content/ICCV2021/html/Wang_Pyramid_Vision_Transformer_A_Versatile_Backbone_for_Dense_Prediction_Without_ICCV_2021_paper.html","core_mech":"以逐级降低 token 分辨率的 Transformer pyramid 和 spatial-reduction attention 提供多尺度 dense-prediction backbone。","core_mech_en":"Constructs a progressive four-stage token pyramid using Spatial-Reduction Attention (SRA) to compress K/V resolution before attention.","input_desc":"高分辨率 2D 图像","input_en":"High-resolution 2D image","output_desc":"四级多尺度 Transformer 特征或分类/密集预测输出","output_en":"Four-stage multi-scale feature pyramid (1/4 to 1/32 stride) for detection and segmentation","form_title":"核心公式 · 压缩 K/V 的空间降采样注意力","form_title_en":"Core Formalism · Spatial-Reduction Attention (SRA) for Multi-Scale Pyramid Tokens","nodes":[{"name":"输入图像","desc":"高分辨率输入，目标是替代 CNN feature pyramid","name_en":"Input Image","desc_en":"Ingests high-resolution 2d image and prepares initial tensor representations (Input Image)."},{"name":"Stage-1 patches","desc":"非重叠 patch embedding 生成最高分辨率 token map","name_en":"Stage-1 patches","desc_en":"Executes Stage-1 patches to extract primary structural features and establish spatial/sequence encoding."},{"name":"SRA","desc":"Spatial-Reduction Attention 在计算 K/V 前按比例下采样 token，Q 保持原分辨率","name_en":"SRA","desc_en":"Performs SRA within the core pyramidal spatial reduction transformer computation pathway."},{"name":"Transformer block","desc":"SRA、MLP、LayerNorm 与 residual 组成各 stage 编码块","name_en":"Transformer block","desc_en":"Performs Transformer block within the core pyramidal spatial reduction transformer computation pathway."},{"name":"Patch 下采样","desc":"阶段间重排/嵌入降低 H×W、增加 channel，形成金字塔","name_en":"Patch downsampling","desc_en":"Performs Patch downsampling within the core pyramidal spatial reduction transformer computation pathway."},{"name":"四级特征","desc":"输出 {F1,F2,F3,F4}，空间分辨率逐级降低","name_en":"feature","desc_en":"Performs feature within the core pyramidal spatial reduction transformer computation pathway."},{"name":"任务头","desc":"分类 head 或 FPN/检测/分割 decoder 消费多尺度特征","name_en":"Task Head","desc_en":"Applies Task Head to project aggregated representations toward the target task head."},{"name":"预测","desc":"分类或密集输出","name_en":"prediction","desc_en":"Produces four-stage multi-scale feature pyramid (1/4 to 1/32 stride) for detection and segmentation via prediction."}],"design_principles":["通过 stage-wise token 下采样建立与 CNN 类似的分辨率金字塔，适配检测和分割。","SRA 仅压缩 K/V 的空间长度，显著降低高分辨率 self-attention 计算。","PVT-v1 仍使用位置编码和非重叠 patch embedding；不应把后续 PVTv2 的 overlap/卷积 FFN 混入。"],"design_principles_en":["Core Hypothesis: Progressively shrink patch stride across four stages while spatially downsampling Key and Value tensors inside self-attention.","Architectural Delta: Pyramid token shrinking + Spatial-Reduction Attention (SRA) reducing attention memory and compute on high-resolution grids.","Mathematical Formalism: Spatial-Reduction Attention (SRA) for Multi-Scale Pyramid Tokens."],"med_apps":["适合高分辨病理、内镜和 2D 医学检测/分割中需要多尺度特征的任务。","小病灶可能在早期 patch 化或 SRA 中受损；3D 扩展还需重新设计 token 长度与内存。"],"med_apps_en":["Clinical Translation: Frequently used as a drop-in hierarchical Transformer encoder for polyp, skin lesion, and ultrasound segmentation.","Evidence & Safety Boundary: Pioneered pyramid Vision Transformers; often succeeded by Swin or SegFormer (MiT) in recent pipelines."],"attrs":{"上一代瓶颈":"平坦 ViT 保持固定 token 尺度，密集预测计算高且缺多尺度层级","核心想法":"逐级降低 token 分辨率并增加通道，形成 Transformer 金字塔","关键改进":"用 spatial-reduction attention 高效构建可替换 CNN 的层级主干","医学适配":"适配医学检测、分割和高分辨率病理特征金字塔","适用范围与证据":"奠定层级视觉 Transformer；后续 Swin、MiT 等结构更常用"},"attrs_en":{"上一代瓶颈":"Columnar ViTs output single-scale low-resolution feature maps unsuitable for FPN/U-Net style dense prediction.","核心想法":"Progressively shrink patch stride across four stages while spatially downsampling Key and Value tensors inside self-attention.","关键改进":"Pyramid token shrinking + Spatial-Reduction Attention (SRA) reducing attention memory and compute on high-resolution grids.","医学适配":"Frequently used as a drop-in hierarchical Transformer encoder for polyp, skin lesion, and ultrasound segmentation.","适用范围与证据":"Pioneered pyramid Vision Transformers; often succeeded by Swin or SegFormer (MiT) in recent pipelines."},"paper_title":"Pyramid Vision Transformer: A Versatile Backbone for Dense Prediction without Convolutions","paper_url":"https://openaccess.thecvf.com/content/ICCV2021/html/Wang_Pyramid_Vision_Transformer_A_Versatile_Backbone_for_Dense_Prediction_Without_ICCV_2021_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/whai362/PVT","has_code":true,"image":"assets/a52788591965925ce087.avif"},{"id":"architecture_model_091_segformer","num":91,"num_str":"091","year":2021,"year_str":"2021","venue":"NeurIPS","venue_group":"ml","era_group":"era3","title":"SegFormer","family_id":"models_dense_segmentation","family_code":"02","family_short":"稠密预测与医学分割","family_en":"Dense Segmentation","family_icon":"II","family_label":"稠密预测与医学分割：从像素输出到自配置系统","archetype":"hierarchical_mit_mlp_segmentation","archetype_en":"hierarchical_mit_mlp_segmentation","accent":"#145E75","fig_badge":"Figure 2 · PDF p.3","fig_href":"https://proceedings.neurips.cc/paper_files/paper/2021/hash/64f1f27bf1b4ec22924fd0acb550c235-Abstract.html","core_mech":"层级 MiT 编码器结合 overlap patch、K/V 缩减 attention 与含 depthwise Conv 的 Mix-FFN，再接全 MLP 轻量 decoder。","core_mech_en":"Hierarchical Mix Transformer (MiT) encoder with overlapping patches, sequence-reduced attention, and 3×3 depthwise Mix-FFN paired with an all-MLP decoder.","input_desc":"任意常见分辨率的 2D 图像","input_en":"2D image of arbitrary test resolution","output_desc":"全分辨率语义分割概率图","output_en":"Full-resolution semantic segmentation probability map","form_title":"核心公式 · 带局部卷积的 Mix-FFN 与多尺度 MLP 解码","form_title_en":"Core Formalism · Position-Encoding-Free Mix-FFN & Multi-Scale All-MLP Aggregation","nodes":[{"name":"输入图像","desc":"无需固定绝对位置编码尺寸","name_en":"Input Image","desc_en":"Ingests 2d image of arbitrary test resolution and prepares initial tensor representations (Input Image)."},{"name":"Overlap Patch","desc":"带重叠的卷积式 patch embedding 保留局部连续性并逐级下采样","name_en":"Overlap Patch","desc_en":"Executes Overlap Patch to extract primary structural features and establish spatial/sequence encoding."},{"name":"Efficient Attention","desc":"按 reduction ratio 压缩 K/V token 数，Q 保持当前 stage 分辨率","name_en":"Efficient Attention","desc_en":"Performs Efficient Attention within the core hierarchical mit mlp segmentation computation pathway."},{"name":"Mix-FFN","desc":"MLP 中插入 3×3 depthwise Conv，引入局部位置偏置而不需显式位置编码","name_en":"Mix-FFN","desc_en":"Performs Mix-FFN within the core hierarchical mit mlp segmentation computation pathway."},{"name":"MiT 四级编码器","desc":"重复 overlap embedding、efficient attention 与 Mix-FFN，通道递增","name_en":"MiT encoder","desc_en":"Performs MiT encoder within the core hierarchical mit mlp segmentation computation pathway."},{"name":"多尺度 F1–F4","desc":"从高分辨边界到低分辨语义的四级特征","name_en":"multi-scale F1–F4","desc_en":"Performs multi-scale F1–F4 within the core hierarchical mit mlp segmentation computation pathway."},{"name":"MLP 投影","desc":"各尺度独立线性投影到共同通道数并上采样到同一分辨率","name_en":"MLP projection","desc_en":"Performs MLP projection within the core hierarchical mit mlp segmentation computation pathway."},{"name":"轻量融合头","desc":"concat 后用 MLP/1×1 Conv 融合，接 dropout 与分类层","name_en":"fusion","desc_en":"Applies fusion to project aggregated representations toward the target task head."},{"name":"分割图","desc":"上采样到输入大小的类别 logits/probabilities","name_en":"Segmentation Map","desc_en":"Produces full-resolution semantic segmentation probability map via Segmentation Map."}],"design_principles":["MiT 用层级多尺度编码器解决平坦 ViT 对 dense prediction 不友好的问题。","efficient attention 通过缩减 K/V 控制高分辨率计算，Mix-FFN 的 depthwise Conv 提供局部位置线索。","解码器只做各尺度 MLP 投影、上采样和融合，把大部分表示能力放在 encoder。"],"design_principles_en":["Core Hypothesis: Pair a hierarchical multi-scale Transformer encoder (using 3×3 depthwise convolutions for positional cues) with a lightweight all-MLP decoder.","Architectural Delta: Overlapping patch merging, spatial-reduction self-attention, Mix-FFN without fixed positional encodings, and MLP multi-scale fusion.","Mathematical Formalism: Position-Encoding-Free Mix-FFN & Multi-Scale All-MLP Aggregation."],"med_apps":["适合作为 2D 内镜、病理、超声和一般医学分割的轻量 Transformer 基线。","2D 成功不能直接外推到完整 3D 体；重叠 patch、缩减比例和上采样需按小病灶尺寸验证。"],"med_apps_en":["Clinical Translation: Popular lightweight Transformer baseline for 2D endoscopy, dermatology, ultrasound, and histopathology segmentation.","Evidence & Safety Boundary: Strong 2D dense-prediction baseline; extending sequence-reduced attention to 3D still requires careful memory engineering."],"attrs":{"上一代瓶颈":"Transformer 分割器常依赖重型 decoder 与固定位置编码，跨分辨率泛化受限","核心想法":"MiT 层级编码器结合轻量全 MLP decoder 融合多尺度特征","关键改进":"overlap patch embedding、efficient attention 和简洁解码器兼顾精度与效率","医学适配":"常作为 2D 医学分割、内镜和病理的 Transformer 基线","适用范围与证据":"强通用密集预测基线；3D 体数据仍需专门内存设计"},"attrs_en":{"上一代瓶颈":"Early Transformer segmenters relied on heavy decoders and fixed interpolated positional embeddings that degraded across resolutions.","核心想法":"Pair a hierarchical multi-scale Transformer encoder (using 3×3 depthwise convolutions for positional cues) with a lightweight all-MLP decoder.","关键改进":"Overlapping patch merging, spatial-reduction self-attention, Mix-FFN without fixed positional encodings, and MLP multi-scale fusion.","医学适配":"Popular lightweight Transformer baseline for 2D endoscopy, dermatology, ultrasound, and histopathology segmentation.","适用范围与证据":"Strong 2D dense-prediction baseline; extending sequence-reduced attention to 3D still requires careful memory engineering."},"paper_title":"SegFormer: Simple and Efficient Design for Semantic Segmentation with Transformers","paper_url":"https://proceedings.neurips.cc/paper_files/paper/2021/hash/64f1f27bf1b4ec22924fd0acb550c235-Abstract.html","code_label":"作者/机构官方实现","code_url":"https://github.com/NVlabs/SegFormer","has_code":true,"image":"assets/79a9dc5778f55b2c90a5.avif"},{"id":"architecture_model_092_beit","num":92,"num_str":"092","year":2022,"year_str":"2022 (preprint 2021)","venue":"ICLR","venue_group":"ml","era_group":"era3","title":"BEiT","family_id":"models_self_supervised_learning","family_code":"05","family_short":"自监督表征学习","family_en":"Self-Supervised Learning","family_icon":"V","family_label":"自监督学习：对比、聚类、自蒸馏与遮挡重建","archetype":"离散视觉词表驱动的掩码图像建模","archetype_en":"discrete_visual_token_mim","accent":"#5B3F8C","fig_badge":"Figure 1 · PDF p.2","fig_href":"https://openreview.net/forum?id=p-BhZSz59o4","core_mech":"BEiT 的辨识点是预测外部 tokenizer 产生的离散视觉码，而非 MAE 式像素重建或普通对比学习。","core_mech_en":"Pretrains Vision Transformers via BERT-style Masked Image Modeling by predicting discrete visual tokens generated by an external dVAE tokenizer.","input_desc":"原始图像，以及对其 patch 随机遮挡后的 token 序列","input_en":"Raw image (for dVAE tokenizer) + block-wise masked patch sequence (for ViT encoder)","output_desc":"被遮挡位置的离散视觉 token 分布；微调时复用 Transformer 图像表示","output_en":"Categorical distribution over discrete visual codes at masked positions; transferable ViT backbone","form_title":"核心公式 · 离散视觉词的掩码预测目标","form_title_en":"Core Formalism · Masked Patch Prediction Over Discrete Visual Codebook Tokens","nodes":[{"name":"原始图像","desc":"同一图像同时产生学生输入和离散监督目标","name_en":"Stage 01","desc_en":"Ingests raw image (for dvae tokenizer) + block-wise masked patch sequence (for vit encoder) and prepares initial tensor representations (Stage 01)."},{"name":"离散视觉 tokenizer","desc":"预训练 dVAE 将图像 patch 映射为视觉词表索引，训练 BEiT 时固定","name_en":"discrete tokenizer","desc_en":"Executes discrete tokenizer to extract primary structural features and establish spatial/sequence encoding."},{"name":"Patch embedding 与 mask","desc":"图像切块并用可学习 mask token 替换随机位置","name_en":"Patch embedding mask","desc_en":"Performs Patch embedding mask within the core discrete visual token mim computation pathway."},{"name":"BEiT Transformer encoder","desc":"对可见 patch 与 mask token 做全局上下文建模","name_en":"BEiT Transformer encoder","desc_en":"Performs BEiT Transformer encoder within the core discrete visual token mim computation pathway."},{"name":"Masked-token head","desc":"仅在被遮挡位置预测视觉词表概率","name_en":"Masked-token head","desc_en":"Performs Masked-token head within the core discrete visual token mim computation pathway."},{"name":"离散 token 交叉熵","desc":"预测分布与 tokenizer 给出的码索引对齐","name_en":"discrete token","desc_en":"Applies discrete token to project aggregated representations toward the target task head."},{"name":"预训练视觉表示","desc":"丢弃预测头后供分类、检测或分割微调","name_en":"pretraining","desc_en":"Produces categorical distribution over discrete visual codes at masked positions; transferable vit backbone via pretraining."}],"design_principles":["把图像 patch 当作视觉词元，学习类似 BERT 的双向上下文。","监督目标来自独立离散 tokenizer，不是直接回归像素。","损失只计算被遮挡位置，预训练后保留 encoder 做下游迁移。"],"design_principles_en":["Core Hypothesis: Quantize image patches into discrete visual tokens via a discrete VAE, then train a ViT to predict the hidden token IDs of masked patches.","Architectural Delta: Decouples continuous pixel array into a continuous patch embedding input view and a discrete semantic token target view.","Mathematical Formalism: Masked Patch Prediction Over Discrete Visual Codebook Tokens."],"med_apps":["可在大量无标注 CT、MRI、病理 patch 上学习上下文表示，再接医学任务头。","若离散 tokenizer 未在医学域训练，微小病灶与定量灰度可能被量化目标忽略。"],"med_apps_en":["Clinical Translation: Directly inspired HeartBEiT (12-lead ECG) and LaBraM (neural VQ tokenizer for EEG) biomedical foundation pretraining.","Evidence & Safety Boundary: Pioneering MIM milestone; offline tokenizer training is often simplified by MAE pixel regression or iBOT online teachers."],"attrs":{"上一代瓶颈":"监督预训练依赖标签，早期图像 SSL 难直接复用 BERT 的 masked objective","核心想法":"把图像 patch 映射为离散视觉 token，随机遮挡后预测 tokenizer 码","关键改进":"以离散 VAE token 作为视觉词表实现 masked image modeling","医学适配":"启发 HeartBEiT 与医学 ViT 的 masked image modeling 预训练","适用范围与证据":"MIM 关键里程碑；tokenizer 偏差和预训练数据覆盖仍决定上限"},"attrs_en":{"上一代瓶颈":"Directly regressing raw RGB pixel values in BERT-style masked pretraining wasted model capacity on high-frequency local noise.","核心想法":"Quantize image patches into discrete visual tokens via a discrete VAE, then train a ViT to predict the hidden token IDs of masked patches.","关键改进":"Decouples continuous pixel array into a continuous patch embedding input view and a discrete semantic token target view.","医学适配":"Directly inspired HeartBEiT (12-lead ECG) and LaBraM (neural VQ tokenizer for EEG) biomedical foundation pretraining.","适用范围与证据":"Pioneering MIM milestone; offline tokenizer training is often simplified by MAE pixel regression or iBOT online teachers."},"paper_title":"BEiT: BERT Pre-Training of Image Transformers","paper_url":"https://openreview.net/pdf?id=p-BhZSz59o4","code_label":"作者/机构官方实现","code_url":"https://github.com/microsoft/unilm/tree/master/beit","has_code":true,"image":"assets/840392d7e8a5a0a66d0c.avif"},{"id":"architecture_model_093_byol","num":93,"num_str":"093","year":2020,"year_str":"2020","venue":"NeurIPS","venue_group":"ml","era_group":"era3","title":"BYOL","family_id":"models_self_supervised_learning","family_code":"05","family_short":"自监督表征学习","family_en":"Self-Supervised Learning","family_icon":"V","family_label":"自监督学习：对比、聚类、自蒸馏与遮挡重建","archetype":"无负样本的在线网络—EMA 目标网络自蒸馏","archetype_en":"negative_free_ema_self_distillation","accent":"#5B3F8C","fig_badge":"Figure 2 · PDF p.4","fig_href":"https://proceedings.neurips.cc/paper_files/paper/2020/hash/f3ada80d5c4ee70142b17b8192b2958e-Abstract.html","core_mech":"没有负样本队列或聚类码本，核心稳定器是 stop-gradient、EMA 教师和仅在线侧存在的 predictor。","core_mech_en":"Negative-free self-supervised representation learning stabilized by an asymmetric online predictor MLP, stop-gradient, and an EMA target encoder.","input_desc":"同一图像的两种随机增强视图","input_en":"Two differently augmented views (v, v') of the same image","output_desc":"在线 encoder 的增强不变表示","output_en":"Augmentation-invariant representation from the online encoder f_θ","form_title":"核心公式 · 跨视图回归与 EMA 教师更新","form_title_en":"Core Formalism · Asymmetric Cross-View Cosine Regression with EMA Target Network","nodes":[{"name":"双增强视图","desc":"裁剪、颜色扰动、模糊等产生 v1 与 v2","name_en":"Stage 01","desc_en":"Ingests two differently augmented views (v, v') of the same image and prepares initial tensor representations (Stage 01)."},{"name":"在线 encoder","desc":"可训练主干提取当前视图表示","name_en":"encoder","desc_en":"Executes encoder to extract primary structural features and establish spatial/sequence encoding."},{"name":"在线 projector","desc":"把 backbone 表示映射到自监督空间","name_en":"projector","desc_en":"Performs projector within the core negative free ema self distillation computation pathway."},{"name":"非对称 predictor","desc":"仅在线分支存在，预测目标分支投影","name_en":"symmetric predictor","desc_en":"Performs symmetric predictor within the core negative free ema self distillation computation pathway."},{"name":"目标 encoder + projector","desc":"参数由在线分支指数滑动平均更新，不接收梯度","name_en":"objective encoder + projector","desc_en":"Performs objective encoder + projector within the core negative free ema self distillation computation pathway."},{"name":"Stop-gradient target","desc":"目标表示归一化后作为固定回归靶","name_en":"Stop-gradient target","desc_en":"Performs Stop-gradient target within the core negative free ema self distillation computation pathway."},{"name":"对称余弦回归损失","desc":"v1 预测 v2 与 v2 预测 v1 两个方向求和","name_en":"symmetric loss","desc_en":"Applies symmetric loss to project aggregated representations toward the target task head."},{"name":"迁移表示","desc":"下游只使用在线 encoder","name_en":"Stage 08","desc_en":"Produces augmentation-invariant representation from the online encoder f_θ via Stage 08."}],"design_principles":["用同一图像跨视图预测学习增强不变性。","目标网络由在线网络 EMA 更新并停止梯度，形成缓慢变化的自蒸馏靶。","在线分支额外 predictor 造成结构不对称，无需显式负样本。"],"design_principles_en":["Core Hypothesis: Train an online network (with an extra predictor head) to regress the stop-gradient representation of a momentum-updated target network.","Architectural Delta: Eliminates explicit negative pairs entirely while avoiding representation collapse via architectural asymmetry and EMA dynamics.","Mathematical Formalism: Asymmetric Cross-View Cosine Regression with EMA Target Network."],"med_apps":["适合将无标注医学影像转成可线性探测或少样本微调的表示。","医学增强必须保持病灶与左右、灰度等语义，否则不变性目标会主动抹除临床信号。"],"med_apps_en":["Clinical Translation: Widely used for unlabeled chest X-ray, fundus, and histopathology pretraining where same-disease negatives are prevalent.","Evidence & Safety Boundary: Classic non-contrastive SSL framework; requires careful normalization and domain-valid augmentations."],"attrs":{"上一代瓶颈":"对比学习依赖大批量负样本，假负例可能破坏语义","核心想法":"在线网络预测目标网络的增强视图表示，目标参数用指数滑动平均更新","关键改进":"在无显式负样本下，以不对称预测器和 EMA 教师经验上避免坍塌；其机制有多种理论解释","医学适配":"适合无标签医学图像预训练和跨增强一致性学习","适用范围与证据":"非对比 SSL 经典方法；增强策略与域内多样性对医学迁移至关重要"},"attrs_en":{"上一代瓶颈":"Contrastive methods were sensitive to negative sample batch sizes and false-negative collisions among clinically similar scans.","核心想法":"Train an online network (with an extra predictor head) to regress the stop-gradient representation of a momentum-updated target network.","关键改进":"Eliminates explicit negative pairs entirely while avoiding representation collapse via architectural asymmetry and EMA dynamics.","医学适配":"Widely used for unlabeled chest X-ray, fundus, and histopathology pretraining where same-disease negatives are prevalent.","适用范围与证据":"Classic non-contrastive SSL framework; requires careful normalization and domain-valid augmentations."},"paper_title":"Bootstrap Your Own Latent: A New Approach to Self-Supervised Learning","paper_url":"https://proceedings.neurips.cc/paper_files/paper/2020/hash/f3ada80d5c4ee70142b17b8192b2958e-Abstract.html","code_label":"作者/机构官方实现","code_url":"https://github.com/google-deepmind/deepmind-research/tree/master/byol","has_code":true,"image":"assets/6f73c01a3f198440a38b.avif"},{"id":"architecture_model_094_swav","num":94,"num_str":"094","year":2020,"year_str":"2020","venue":"NeurIPS","venue_group":"ml","era_group":"era3","title":"SwAV","family_id":"models_self_supervised_learning","family_code":"05","family_short":"自监督表征学习","family_en":"Self-Supervised Learning","family_icon":"V","family_label":"自监督学习：对比、聚类、自蒸馏与遮挡重建","archetype":"在线原型聚类与跨视图 swapped prediction","archetype_en":"online_prototype_swapped_clustering","accent":"#5B3F8C","fig_badge":"Figure 1 · PDF p.4","fig_href":"https://proceedings.neurips.cc/paper/2020/hash/70feb62b69f16e0238f741fab228fec2-Abstract.html","core_mech":"以在线平衡原型分配作为跨视图预测目标，区别于 BYOL 的 EMA 表示回归和 SimCLR 的实例负样本。","core_mech_en":"Replaces pairwise instance comparisons with online Sinkhorn-Knopp balanced prototype cluster assignment and swapped cross-view prediction.","input_desc":"同一图像的两张全局裁剪和若干局部裁剪","input_en":"2 global high-resolution views + M small local crops of the same image","output_desc":"可迁移图像表示与在线 prototype 分配","output_en":"Transferable visual backbone and online learnable prototype codebook","form_title":"核心公式 · 均衡原型分配与跨视图交换预测","form_title_en":"Core Formalism · Swapped Cross-View Prediction of Sinkhorn-Balanced Prototype Codes","nodes":[{"name":"Multi-crop views","desc":"高分辨率全局视图配合低分辨率局部视图扩大上下文组合","name_en":"Multi-crop views","desc_en":"Ingests 2 global high-resolution views + m small local crops of the same image and prepares initial tensor representations (Multi-crop views)."},{"name":"共享 ConvNet encoder","desc":"各视图共享 ResNet 等主干","name_en":"ConvNet encoder","desc_en":"Executes ConvNet encoder to extract primary structural features and establish spatial/sequence encoding."},{"name":"投影与 L2 归一化","desc":"得到适合原型匹配的单位向量","name_en":"projection L2 normalization","desc_en":"Performs projection L2 normalization within the core online prototype swapped clustering computation pathway."},{"name":"可学习 prototypes","desc":"特征与原型点积形成聚类 logits","name_en":"prototypes","desc_en":"Performs prototypes within the core online prototype swapped clustering computation pathway."},{"name":"Sinkhorn-Knopp 分配","desc":"对全局视图求近似均衡的在线软聚类码","name_en":"Sinkhorn-Knopp","desc_en":"Performs Sinkhorn-Knopp within the core online prototype swapped clustering computation pathway."},{"name":"Swapped prediction loss","desc":"一视图预测另一视图的 prototype 分配","name_en":"Swapped prediction loss","desc_en":"Applies Swapped prediction loss to project aggregated representations toward the target task head."},{"name":"预训练表示","desc":"下游复用共享 encoder","name_en":"pretraining","desc_en":"Produces transferable visual backbone and online learnable prototype codebook via pretraining."}],"design_principles":["不同视图不直接做实例对比，而是互相预测在线聚类分配。","Sinkhorn 约束批内原型使用近似均衡，降低全部样本落入单一原型的坍塌。","多裁剪让局部区域与全局图像共享语义，同时控制计算量。"],"design_principles_en":["Core Hypothesis: Compute online soft cluster assignments over learnable prototypes using Sinkhorn-Knopp equipartition and predict view A's code from view B.","Architectural Delta: Online balanced clustering + multi-crop augmentation strategy enabling memory-efficient small-batch SSL training.","Mathematical Formalism: Swapped Cross-View Prediction of Sinkhorn-Balanced Prototype Codes."],"med_apps":["可把病理局部 patch、放射图像局部视野与整图放进统一自监督训练。","均衡 prototype 是优化约束而非真实病种患病率，不能把原型直接解释为临床类别。"],"med_apps_en":["Clinical Translation: Applied to large-scale unlabeled histopathology patch clustering and radiographic representation learning.","Evidence & Safety Boundary: Foundational clustering-based SSL method; multi-crop strategy became standard in DINO and DINOv2."],"attrs":{"上一代瓶颈":"实例级对比需要大量负样本且把语义相近图像当作负例","核心想法":"让不同增强视图预测彼此的在线 prototype 聚类分配","关键改进":"用 balanced online clustering 与 multi-crop 训练学习可扩展表征","医学适配":"可用于大规模病理 patch 和放射影像无标签预训练","适用范围与证据":"聚类式 SSL 重要路线；prototype 数量与采样偏差需谨慎控制"},"attrs_en":{"上一代瓶颈":"Instance discrimination treated every distinct image as a negative, ignoring shared semantic clusters and scaling poorly.","核心想法":"Compute online soft cluster assignments over learnable prototypes using Sinkhorn-Knopp equipartition and predict view A's code from view B.","关键改进":"Online balanced clustering + multi-crop augmentation strategy enabling memory-efficient small-batch SSL training.","医学适配":"Applied to large-scale unlabeled histopathology patch clustering and radiographic representation learning.","适用范围与证据":"Foundational clustering-based SSL method; multi-crop strategy became standard in DINO and DINOv2."},"paper_title":"Unsupervised Learning of Visual Features by Contrasting Cluster Assignments","paper_url":"https://proceedings.neurips.cc/paper/2020/hash/70feb62b69f16e0238f741fab228fec2-Abstract.html","code_label":"作者/机构官方实现","code_url":"https://github.com/facebookresearch/swav","has_code":true,"image":"assets/c9a8fab7e0f96876cbc3.avif"},{"id":"architecture_model_095_align","num":95,"num_str":"095","year":2021,"year_str":"2021","venue":"ICML","venue_group":"ml","era_group":"era3","title":"ALIGN","family_id":"models_vision_language","family_code":"07","family_short":"图文对齐与医学 VLM","family_en":"Vision-Language Models","family_icon":"VII","family_label":"图文对齐与生成式 VLM：开放语义不等于视觉事实","archetype":"十亿级噪声图文对的双编码器对比对齐","archetype_en":"billion_scale_noisy_dual_encoder_clip","accent":"#7A3547","fig_badge":"Figure 1 · PDF p.2","fig_href":"https://proceedings.mlr.press/v139/jia21b.html","core_mech":"ALIGN 的主要贡献不是新交互模块，而是简单 EfficientNet/BERT 双塔在十亿级未精洗图文对上的规模化训练。","core_mech_en":"Demonstrates that a simple EfficientNet + BERT dual encoder trained on over one billion noisy web image–alt-text pairs learns robust cross-modal representations.","input_desc":"网页图像与未经精细清洗的 alt-text 对","input_en":"Web image + minimally filtered raw alt-text description","output_desc":"共享空间中的图像和文本 embedding，用于检索与零样本分类","output_en":"Shared-space image and text embeddings for cross-modal retrieval and zero-shot classification","form_title":"核心公式 · 海量噪声图文对的双向对比对齐","form_title_en":"Core Formalism · Billion-Scale Noisy Image–Alt-Text Bidirectional Contrastive Learning","nodes":[{"name":"网页图像","desc":"弱监督图像侧输入","name_en":"Stage 01","desc_en":"Ingests web image + minimally filtered raw alt-text description and prepares initial tensor representations (Stage 01)."},{"name":"噪声 alt-text","desc":"大规模但存在错配、缺漏与模板噪声","name_en":"noise alt-text","desc_en":"Executes noise alt-text to extract primary structural features and establish spatial/sequence encoding."},{"name":"EfficientNet-L2","desc":"独立图像 encoder 生成全局视觉特征","name_en":"EfficientNet-L2","desc_en":"Performs EfficientNet-L2 within the core billion scale noisy dual encoder clip computation pathway."},{"name":"BERT-Large","desc":"独立文本 encoder 生成句级特征","name_en":"BERT-Large","desc_en":"Performs BERT-Large within the core billion scale noisy dual encoder clip computation pathway."},{"name":"投影与归一化","desc":"两模态映射到同维单位球","name_en":"projection normalization","desc_en":"Performs projection normalization within the core billion scale noisy dual encoder clip computation pathway."},{"name":"批内相似度矩阵","desc":"所有图像与所有文本做点积并除以温度","name_en":"matrix","desc_en":"Performs matrix within the core billion scale noisy dual encoder clip computation pathway."},{"name":"双向对比交叉熵","desc":"image-to-text 与 text-to-image 两方向识别配对项","name_en":"Stage 07","desc_en":"Applies Stage 07 to project aggregated representations toward the target task head."},{"name":"零样本/检索表示","desc":"文本提示可充当分类原型","name_en":"zero-shot","desc_en":"Produces shared-space image and text embeddings for cross-modal retrieval and zero-shot classification via zero-shot."}],"design_principles":["图像与文本分别编码，跨模态交互只发生在全局 embedding 相似度。","用极大规模弱配对数据吸收单对噪声，而不是依赖昂贵人工清洗。","对称批内对比损失同时训练图搜文与文搜图。"],"design_principles_en":["Core Hypothesis: Trade stringent manual data cleaning for sheer data scale (1.8B noisy pairs) using a simple dual-encoder contrastive objective.","Architectural Delta: Proved that massive scale can empirically overcome high caption noise in web-scale vision–language pretraining.","Mathematical Formalism: Billion-Scale Noisy Image–Alt-Text Bidirectional Contrastive Learning."],"med_apps":["可迁移为影像—报告双塔，用于零样本标签提示和跨模态检索。","医学数据规模远小于网页语料，且同义报告会形成假负样本，需要语义软标签或患者级采样修正。"],"med_apps_en":["Clinical Translation: Methodologically inspired harvesting large-scale noisy hospital PACS archives and scientific figure-caption corpora.","Evidence & Safety Boundary: Web-scale VLM milestone; in clinical medicine, uncurated label/report noise and privacy leakage require far stricter governance."],"attrs":{"上一代瓶颈":"高质量人工图文配对昂贵，早期 VLM 数据规模受限","核心想法":"用双编码器在十亿级噪声网页图文对上做对比对齐","关键改进":"在其网页语料与评测条件下，以极大规模弱监督缓解标签噪声并获得零样本迁移","医学适配":"方法上启发从报告、图注和病历构建医学图文预训练数据","适用范围与证据":"规模化 VLM 里程碑；原论文不是医学验证，医学隐私、噪声和临床语义错配更突出"},"attrs_en":{"上一代瓶颈":"Curating clean, human-verified image captions was expensive and bottlenecked dataset scale.","核心想法":"Trade stringent manual data cleaning for sheer data scale (1.8B noisy pairs) using a simple dual-encoder contrastive objective.","关键改进":"Proved that massive scale can empirically overcome high caption noise in web-scale vision–language pretraining.","医学适配":"Methodologically inspired harvesting large-scale noisy hospital PACS archives and scientific figure-caption corpora.","适用范围与证据":"Web-scale VLM milestone; in clinical medicine, uncurated label/report noise and privacy leakage require far stricter governance."},"paper_title":"Scaling Up Visual and Vision-Language Representation Learning With Noisy Text Supervision","paper_url":"https://proceedings.mlr.press/v139/jia21b.html","code_label":"未提供官方实现","code_url":"","has_code":false,"image":"assets/3b7218148b4756ec4c44.avif"},{"id":"architecture_model_096_blip","num":96,"num_str":"096","year":2022,"year_str":"2022","venue":"ICML","venue_group":"ml","era_group":"era3","title":"BLIP","family_id":"models_vision_language","family_code":"07","family_short":"图文对齐与医学 VLM","family_en":"Vision-Language Models","family_icon":"VII","family_label":"图文对齐与生成式 VLM：开放语义不等于视觉事实","archetype":"MED 多模态编码—解码与 CapFilt 数据自举","archetype_en":"multimodal_encoder_decoder_capfilt","accent":"#7A3547","fig_badge":"Figure 2 · PDF p.2","fig_href":"https://proceedings.mlr.press/v162/li22n.html","core_mech":"区别于纯双塔，BLIP 用共享 MED 同时承担对齐、跨注意力匹配和因果生成，并把 captioner-filter 作为数据循环的一部分。","core_mech_en":"Unifies vision–language understanding and generation via a Multimodal Mixture of Encoder–Decoder (MED) coupled with a CapFilt data bootstrapping loop.","input_desc":"图像、原始网页描述及由 captioner 生成的合成描述","input_en":"Image + noisy web caption + synthetically generated and filtered captions","output_desc":"图文检索/匹配表示和自回归图像描述","output_en":"Unimodal embeddings (ITC), cross-modal matching scores (ITM), and autoregressive captions (LM)","form_title":"核心公式 · CapFilt 清洗后的三目标联合预训练","form_title_en":"Core Formalism · Joint ITC + ITM + LM Pretraining with Synthetic Captioner–Filter Bootstrapping","nodes":[{"name":"噪声图文对","desc":"原始网页配对是训练语料起点","name_en":"noise","desc_en":"Ingests image + noisy web caption + synthetically generated and filtered captions and prepares initial tensor representations (noise)."},{"name":"CapFilt","desc":"captioner 生成补充描述，filter 剔除与图像不一致的原始或合成文本","name_en":"CapFilt","desc_en":"Executes CapFilt to extract primary structural features and establish spatial/sequence encoding."},{"name":"ViT 图像 encoder","desc":"输出视觉 token，供三种文本模式共享","name_en":"ViT encoder","desc_en":"Performs ViT encoder within the core multimodal encoder decoder capfilt computation pathway."},{"name":"Unimodal text encoder","desc":"与图像全局表示计算 image-text contrastive 目标","name_en":"Unimodal text encoder","desc_en":"Performs Unimodal text encoder within the core multimodal encoder decoder capfilt computation pathway."},{"name":"Image-grounded text encoder","desc":"双向自注意力加视觉 cross-attention，执行 image-text matching","name_en":"Image-grounded text encoder","desc_en":"Performs Image-grounded text encoder within the core multimodal encoder decoder capfilt computation pathway."},{"name":"Image-grounded text decoder","desc":"因果自注意力加视觉 cross-attention，自回归生成描述","name_en":"Image-grounded text decoder","desc_en":"Performs Image-grounded text decoder within the core multimodal encoder decoder capfilt computation pathway."},{"name":"ITC + ITM + LM","desc":"对齐、细粒度匹配与语言建模联合训练","name_en":"ITC + ITM + LM","desc_en":"Applies ITC + ITM + LM to project aggregated representations toward the target task head."},{"name":"理解与生成输出","desc":"统一支持检索、匹配、问答适配和 caption","name_en":"output","desc_en":"Produces unimodal embeddings (itc), cross-modal matching scores (itm), and autoregressive captions (lm) via output."}],"design_principles":["同一 MED 文本骨架切换单模态编码、图像条件编码和图像条件解码三种模式。","ITC 负责全局对齐，ITM 负责细粒度判别，LM 负责开放式生成。","CapFilt 让模型反过来生成并筛选训练描述，改善网络语料质量。"],"design_principles_en":["Core Hypothesis: Share weights across a multimodal encoder–decoder trained jointly on contrastive, matching, and generative objectives while bootstrapping clean captions.","Architectural Delta: Weight-shared MED architecture + CapFilt (a captioner generates synthetic descriptions while a filter removes noisy image–text pairs).","Mathematical Formalism: Joint ITC + ITM + LM Pretraining with Synthetic Captioner–Filter Bootstrapping."],"med_apps":["可将报告生成、影像检索与医学视觉问答置于一套预训练接口。","自动生成或过滤的医学描述可能遗漏阴性发现和不确定措辞，必须保留来源与人工抽检。"],"med_apps_en":["Clinical Translation: Provides a versatile blueprint for joint radiology report retrieval, image-report matching verification, and caption generation.","Evidence & Safety Boundary: Data bootstrapping remains highly relevant; in medicine, synthetic captions must be audited against hallucinated clinical findings."],"attrs":{"上一代瓶颈":"网页图文噪声大，理解与生成模型往往分开训练","核心想法":"以统一 encoder-decoder 架构结合图文对比、匹配和生成目标","关键改进":"用 captioner-filter 构造更干净合成描述并统一多任务预训练","医学适配":"为医学报告生成、问答与跨模态检索提供通用范式","适用范围与证据":"VLM 数据清洗与多目标训练仍关键；临床事实性需独立约束"},"attrs_en":{"上一代瓶颈":"Pure dual encoders (CLIP) cannot generate free text, while noisy web captions degrade generative language modeling.","核心想法":"Share weights across a multimodal encoder–decoder trained jointly on contrastive, matching, and generative objectives while bootstrapping clean captions.","关键改进":"Weight-shared MED architecture + CapFilt (a captioner generates synthetic descriptions while a filter removes noisy image–text pairs).","医学适配":"Provides a versatile blueprint for joint radiology report retrieval, image-report matching verification, and caption generation.","适用范围与证据":"Data bootstrapping remains highly relevant; in medicine, synthetic captions must be audited against hallucinated clinical findings."},"paper_title":"BLIP: Bootstrapping Language-Image Pre-training for Unified Vision-Language Understanding and Generation","paper_url":"https://proceedings.mlr.press/v162/li22n.html","code_label":"作者/机构官方实现","code_url":"https://github.com/salesforce/BLIP","has_code":true,"image":"assets/4da2fadb9fb85d4a0074.avif"},{"id":"architecture_model_097_florence_2","num":97,"num_str":"097","year":2024,"year_str":"2024","venue":"CVPR","venue_group":"cv","era_group":"era4","title":"Florence-2","family_id":"models_vision_language","family_code":"07","family_short":"图文对齐与医学 VLM","family_en":"Vision-Language Models","family_icon":"VII","family_label":"图文对齐与生成式 VLM：开放语义不等于视觉事实","archetype":"提示驱动的统一视觉序列到序列模型","archetype_en":"prompted_unified_vision_seq2seq","accent":"#7A3547","fig_badge":"Figure 2, section 1 · PDF p.3","fig_href":"https://openaccess.thecvf.com/content/CVPR2024/html/Xiao_Florence-2_Advancing_a_Unified_Representation_for_a_Variety_of_Vision_Tasks_CVPR_2024_paper.html","core_mech":"核心不是增加多个 head，而是用任务提示和位置 token 将 caption、检测、grounding、分割全部改写为 seq2seq。","core_mech_en":"Reformulates captioning, object detection, phrase grounding, and segmentation into a single prompt-driven sequence-to-sequence generation task with quantized coordinate tokens.","input_desc":"图像与任务提示，例如 caption、detect、ground 或 segment","input_en":"2D image + task-specific text prompt (e.g., <OD>, <CAPTION>, <REFERRING_EXPRESSION_SEGMENTATION>)","output_desc":"文本、类别与量化位置 token 序列，后处理为描述、框或多边形","output_en":"Unified token sequence decoding text descriptions, class labels, and quantized 0–999 bounding-box or polygon coordinates","form_title":"核心公式 · 提示驱动的统一视觉任务序列生成","form_title_en":"Core Formalism · Unified Task-Prompted Sequence-to-Sequence Generation Over Text & Coordinate Tokens","nodes":[{"name":"输入图像","desc":"所有视觉任务共享同一图像接口","name_en":"Input Image","desc_en":"Ingests 2d image + task-specific text prompt (e.g., <od>, <caption>, <referring_expression_segmentation>) and prepares initial tensor representations (Input Image)."},{"name":"任务文本提示","desc":"特殊任务 token 指定描述、检测、定位或分割","name_en":"prompt","desc_en":"Executes prompt to extract primary structural features and establish spatial/sequence encoding."},{"name":"DaViT vision encoder","desc":"产生层级视觉 token","name_en":"DaViT vision encoder","desc_en":"Performs DaViT vision encoder within the core prompted unified vision seq2seq computation pathway."},{"name":"Linear projection + LayerNorm","desc":"把视觉 token 对齐到语言维度","name_en":"Linear projection + LayerNorm","desc_en":"Performs Linear projection + LayerNorm within the core prompted unified vision seq2seq computation pathway."},{"name":"多模态 Transformer encoder","desc":"拼接视觉 token 与提示 token 后联合编码","name_en":"multimodal Transformer encoder","desc_en":"Performs multimodal Transformer encoder within the core prompted unified vision seq2seq computation pathway."},{"name":"自回归 Transformer decoder","desc":"按统一词表逐 token 生成任务答案","name_en":"Transformer decoder","desc_en":"Performs Transformer decoder within the core prompted unified vision seq2seq computation pathway."},{"name":"扩展位置词表","desc":"量化坐标 token 表示 box、quad 与 polygon 顶点","name_en":"Stage 07","desc_en":"Applies Stage 07 to project aggregated representations toward the target task head."},{"name":"任务后处理","desc":"把生成序列解析成 caption、检测框或分割多边形","name_en":"Stage 08","desc_en":"Produces unified token sequence decoding text descriptions, class labels, and quantized 0–999 bounding-box or polygon coordinates via Stage 08."}],"design_principles":["把多种视觉任务统一为由提示条件化的序列生成。","视觉 token 与文本提示在 encoder 中融合，decoder 不依赖任务专属检测或分割头。","坐标量化为词表 token，使文本与空间输出共享交叉熵目标。"],"design_principles_en":["Core Hypothesis: Represent spatial coordinates as discrete vocabulary tokens (1,000 bins) so a single DaViT + seq2seq Transformer handles all vision tasks.","Architectural Delta: Unified coordinate-token sequence interface + FLD-5B (5.4B multi-task annotations across 126M images) unified pretraining.","Mathematical Formalism: Unified Task-Prompted Sequence-to-Sequence Generation Over Text & Coordinate Tokens."],"med_apps":["可作为医学弱标注接口，把同一影像转成描述、框或区域草案。","自然图像位置词表与训练分布不保证微小病灶或 3D 体积定位准确，需领域微调和逐任务校准。"],"med_apps_en":["Clinical Translation: Offers a unified promptable foundation interface adaptable to medical lesion detection, grounded reporting, and polygon annotation.","Evidence & Safety Boundary: Frontier generalist vision interface; clinical precision on sub-millimeter boundaries and 3D volumes requires dedicated adaptation."],"attrs":{"上一代瓶颈":"视觉任务通常需要不同 head、标签格式和专用模型","核心想法":"把检测、分割、描述与定位统一为基于提示的序列到序列任务","关键改进":"以统一文本提示和位置 token 在多任务数据上训练单一生成模型","医学适配":"可作为医学 VLM 的通用视觉接口和弱标注工具，但需领域适配","适用范围与证据":"通用视觉基础模型前沿；医学细粒度定位和安全性尚未充分验证"},"attrs_en":{"上一代瓶颈":"Multi-task vision systems required separate specialized task heads, loss functions, and architectural branches for boxes, masks, and text.","核心想法":"Represent spatial coordinates as discrete vocabulary tokens (1,000 bins) so a single DaViT + seq2seq Transformer handles all vision tasks.","关键改进":"Unified coordinate-token sequence interface + FLD-5B (5.4B multi-task annotations across 126M images) unified pretraining.","医学适配":"Offers a unified promptable foundation interface adaptable to medical lesion detection, grounded reporting, and polygon annotation.","适用范围与证据":"Frontier generalist vision interface; clinical precision on sub-millimeter boundaries and 3D volumes requires dedicated adaptation."},"paper_title":"Florence-2: Advancing a Unified Representation for a Variety of Vision Tasks","paper_url":"https://openaccess.thecvf.com/content/CVPR2024/html/Xiao_Florence-2_Advancing_a_Unified_Representation_for_a_Variety_of_Vision_Tasks_CVPR_2024_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/microsoft/Florence-2","has_code":true,"image":"assets/8e5f42588e09448468f2.avif"},{"id":"architecture_model_098_medclip","num":98,"num_str":"098","year":2022,"year_str":"2022","venue":"EMNLP","venue_group":"journal","era_group":"era3","title":"MedCLIP","family_id":"models_vision_language","family_code":"07","family_short":"图文对齐与医学 VLM","family_en":"Vision-Language Models","family_icon":"VII","family_label":"图文对齐与生成式 VLM：开放语义不等于视觉事实","archetype":"基于医学语义软标签的非配对图文对比学习","archetype_en":"soft_semantic_unpaired_medical_clip","accent":"#7A3547","fig_badge":"Figure 3 · PDF p.4","fig_href":"https://aclanthology.org/2022.emnlp-main.256/","core_mech":"MedCLIP 的关键不是更深双塔，而是用医学知识构造任意图像—文本间的软语义配对。","core_mech_en":"Replaces hard binary 1-to-1 image–report pairing with a soft semantic similarity matrix derived from clinical entity extraction, enabling unpaired contrastive learning.","input_desc":"可分别采样的胸片与报告句子，以及图像标签和文本实体","input_en":"Independently sampled chest radiographs and clinical report sentences with extracted UMLS/CheXpert entities","output_desc":"医学图像/文本共享 embedding、零样本分类与检索相似度","output_en":"Shared medical image–text embeddings and zero-shot disease probabilities","form_title":"核心公式 · 疾病语义软标签驱动的非配对图文对齐","form_title_en":"Core Formalism · Knowledge-Driven Soft Semantic Target Matching Across Unpaired Images & Texts","nodes":[{"name":"非配对胸片批次","desc":"图像不必与同批文本来自同一检查","name_en":"chest X-ray (CXR","desc_en":"Ingests independently sampled chest radiographs and clinical report sentences with extracted umls/chexpert entities and prepares initial tensor representations (chest X-ray (CXR)."},{"name":"非配对报告句子","desc":"从独立文本库采样","name_en":"Stage 02","desc_en":"Executes Stage 02 to extract primary structural features and establish spatial/sequence encoding."},{"name":"医学知识抽取","desc":"把图像标签与报告实体映射到共同的 14 类临床语义向量","name_en":"Stage 03","desc_en":"Performs Stage 03 within the core soft semantic unpaired medical clip computation pathway."},{"name":"视觉 encoder","desc":"ResNet 或 ViT 生成胸片 embedding","name_en":"encoder","desc_en":"Performs encoder within the core soft semantic unpaired medical clip computation pathway."},{"name":"ClinicalBERT text encoder","desc":"编码报告或类别提示","name_en":"ClinicalBERT text encoder","desc_en":"Performs ClinicalBERT text encoder within the core soft semantic unpaired medical clip computation pathway."},{"name":"语义相似度软矩阵","desc":"由图像/文本临床标签余弦相似度构成非二元目标","name_en":"matrix","desc_en":"Performs matrix within the core soft semantic unpaired medical clip computation pathway."},{"name":"双向 semantic matching loss","desc":"预测 embedding 相似度分布拟合软语义目标","name_en":"semantic matching loss","desc_en":"Applies semantic matching loss to project aggregated representations toward the target task head."},{"name":"零样本与检索接口","desc":"类别提示、图像与报告可直接比较","name_en":"zero-shot","desc_en":"Produces shared medical image–text embeddings and zero-shot disease probabilities via zero-shot."}],"design_principles":["图像和文本解耦采样，扩大可组合训练对数量。","临床实体/标签相似度提供软配对，避免把同语义不同患者误作纯负样本。","双向语义匹配损失用软分布替代 CLIP 的严格对角 one-hot 目标。"],"design_principles_en":["Core Hypothesis: Construct a soft semantic target similarity matrix between any image and any text using extracted clinical entities, training via KL divergence.","Architectural Delta: Decouples contrastive training from strict 1-to-1 pairs and eliminates same-pathology false-negative penalties.","Mathematical Formalism: Knowledge-Driven Soft Semantic Target Matching Across Unpaired Images & Texts."],"med_apps":["适合胸片零样本分类、报告检索和少样本迁移。","语义矩阵受限于标签抽取器与 14 类本体，未编码的细粒度、位置和否定语义仍可能丢失。"],"med_apps_en":["Clinical Translation: Applied to label-efficient chest X-ray zero-shot classification, semantic retrieval, and unpaired pretraining.","Evidence & Safety Boundary: Important medical CLIP modification; bounded by the accuracy of rule-based clinical entity extractors and chest X-ray scope."],"attrs":{"上一代瓶颈":"医学影像与文本严格配对数据有限，CLIP 式一一对应假设过强","核心想法":"通过语义匹配把不严格配对的胸片和报告句子用于对比预训练","关键改进":"基于临床标签/语义相似度构造软配对，扩大可用监督","医学适配":"用于胸片零样本分类、检索和少样本迁移","适用范围与证据":"医学 CLIP 代表；主要受限于胸片单域、标签抽取噪声及缺少细粒度定位"},"attrs_en":{"上一代瓶颈":"Standard CLIP treats other patients sharing the exact same pathology in a batch as false negatives and requires strictly paired data.","核心想法":"Construct a soft semantic target similarity matrix between any image and any text using extracted clinical entities, training via KL divergence.","关键改进":"Decouples contrastive training from strict 1-to-1 pairs and eliminates same-pathology false-negative penalties.","医学适配":"Applied to label-efficient chest X-ray zero-shot classification, semantic retrieval, and unpaired pretraining.","适用范围与证据":"Important medical CLIP modification; bounded by the accuracy of rule-based clinical entity extractors and chest X-ray scope."},"paper_title":"MedCLIP: Contrastive Learning from Unpaired Medical Images and Text","paper_url":"https://aclanthology.org/2022.emnlp-main.256/","code_label":"作者/机构官方实现","code_url":"https://github.com/RyanWangZf/MedCLIP","has_code":true,"image":"assets/f6c239525e0336087f1e.avif"},{"id":"architecture_model_099_med_flamingo","num":99,"num_str":"099","year":2023,"year_str":"2023","venue":"Machine Learning for Health / PMLR","venue_group":"journal","era_group":"era4","title":"Med-Flamingo","family_id":"models_vision_language","family_code":"07","family_short":"图文对齐与医学 VLM","family_en":"Vision-Language Models","family_icon":"VII","family_label":"图文对齐与生成式 VLM：开放语义不等于视觉事实","archetype":"冻结双主干、Perceiver 压缩与门控跨注意力的医学少样本 VLM","archetype_en":"perceiver_gated_cross_attention_vlm","accent":"#7A3547","fig_badge":"Figure 2 · PDF p.3","fig_href":"https://proceedings.mlr.press/v225/moor23a.html","core_mech":"区别于单一投影接 LLM，Med-Flamingo 用 Perceiver 固定视觉 latent，并在多层冻结 LLM 中反复注入门控跨注意力。","core_mech_en":"Compresses variable-number medical images via a Perceiver Resampler and injects them into a frozen LLM through tanh-gated cross-attention layers for few-shot in-context learning.","input_desc":"交错的医学图像、文本及若干上下文示例","input_en":"Interleaved sequence of exemplar medical images, clinical text, and a query medical image/question","output_desc":"条件于图像和 in-context 示例的自回归医学回答或解释","output_en":"Autoregressive medical VQA answer or clinical rationale conditioned on in-context exemplars","form_title":"核心公式 · 交错门控跨注意力注入多图上下文","form_title_en":"Core Formalism · Tanh-Gated Cross-Attention Conditioning a Frozen LLM on Interleaved Medical Visual Latents","nodes":[{"name":"交错图文上下文","desc":"支持一张或多张图像与示例问答顺序混排","name_en":"Stage 01","desc_en":"Ingests interleaved sequence of exemplar medical images, clinical text, and a query medical image/question and prepares initial tensor representations (Stage 01)."},{"name":"CLIP ViT-L/14","desc":"预训练视觉 encoder；Flamingo 训练中保持冻结","name_en":"CLIP ViT-L/14","desc_en":"Executes CLIP ViT-L/14 to extract primary structural features and establish spatial/sequence encoding."},{"name":"Perceiver Resampler","desc":"把可变数量视觉特征压成固定数量 latent token","name_en":"Perceiver Resampler","desc_en":"Performs Perceiver Resampler within the core perceiver gated cross attention vlm computation pathway."},{"name":"LLaMA-7B 文本 token","desc":"医学提示、示例和待答问题进入冻结语言主干","name_en":"LLaMA-7B token","desc_en":"Performs LLaMA-7B token within the core perceiver gated cross attention vlm computation pathway."},{"name":"Gated cross-attention layers","desc":"插入语言层之间，门控地读取最近图像 latent","name_en":"Gated cross-attention layers","desc_en":"Performs Gated cross-attention layers within the core perceiver gated cross attention vlm computation pathway."},{"name":"冻结 LLaMA language model","desc":"保留通用生成能力，主要训练连接模块","name_en":"LLaMA language model","desc_en":"Performs LLaMA language model within the core perceiver gated cross attention vlm computation pathway."},{"name":"医学持续预训练","desc":"PMC-OA 与医学教材图文数据更新 resampler/cross-attention","name_en":"pretraining","desc_en":"Applies pretraining to project aggregated representations toward the target task head."},{"name":"Few-shot 生成","desc":"按 next-token 概率生成回答或 rationale","name_en":"Few-shot","desc_en":"Produces autoregressive medical vqa answer or clinical rationale conditioned on in-context exemplars via Few-shot."}],"design_principles":["Perceiver 将任意图像 token 压缩为固定视觉 latent，控制跨注意力成本。","门控 cross-attention 插入冻结语言模型，使文本生成按交错图像条件化。","通过医学图文持续预训练连接层，保留基础主干并获得 in-context few-shot 能力。"],"design_principles_en":["Core Hypothesis: Continue pretraining a Flamingo-style gated cross-attention architecture on interleaved biomedical textbook/article figures and text.","Architectural Delta: Perceiver Resampler fixed-token visual compression + zero-initialized tanh-gated cross-attention interleaved inside a frozen LLM.","Mathematical Formalism: Tanh-Gated Cross-Attention Conditioning a Frozen LLM on Interleaved Medical Visual Latents."],"med_apps":["能用少量示例快速切换医学视觉问答格式，适合作为研究型原型。","生成 rationale 不等于可验证推理；冻结主干仍可继承通用域偏差与幻觉，不能当作临床证据链。"],"med_apps_en":["Clinical Translation: Prototype for few-shot in-context medical visual question answering and clinical rationale generation.","Evidence & Safety Boundary: Early medical MLLM milestone; human evaluation cohorts were small and LLM priors can still generate plausible-sounding errors."],"attrs":{"上一代瓶颈":"通用多模态模型医学知识不足，专用模型又难做少样本对话","核心想法":"在冻结的语言模型中插入跨注意力层，接收交错医学图像与文本上下文","关键改进":"基于 Flamingo 进行医学图文持续预训练并支持 in-context few-shot","医学适配":"用于 few-shot 医学视觉问答与 rationale generation 原型","适用范围与证据":"早期医学 MLLM；评测规模小，语言先验可能掩盖视觉不足"},"attrs_en":{"上一代瓶颈":"General-purpose VLMs lacked medical domain knowledge, while task-specific medical models could not adapt on the fly from a few examples.","核心想法":"Continue pretraining a Flamingo-style gated cross-attention architecture on interleaved biomedical textbook/article figures and text.","关键改进":"Perceiver Resampler fixed-token visual compression + zero-initialized tanh-gated cross-attention interleaved inside a frozen LLM.","医学适配":"Prototype for few-shot in-context medical visual question answering and clinical rationale generation.","适用范围与证据":"Early medical MLLM milestone; human evaluation cohorts were small and LLM priors can still generate plausible-sounding errors."},"paper_title":"Med-Flamingo: a Multimodal Medical Few-shot Learner","paper_url":"https://proceedings.mlr.press/v225/moor23a.html","code_label":"作者/机构官方实现","code_url":"https://github.com/snap-stanford/med-flamingo","has_code":true,"image":"assets/b4b3c31597ad9174720f.avif"},{"id":"architecture_model_100_llava_med","num":100,"num_str":"100","year":2023,"year_str":"2023","venue":"NeurIPS Datasets and Benchmarks","venue_group":"ml","era_group":"era4","title":"LLaVA-Med","family_id":"models_vision_language","family_code":"07","family_short":"图文对齐与医学 VLM","family_en":"Vision-Language Models","family_icon":"VII","family_label":"图文对齐与生成式 VLM：开放语义不等于视觉事实","archetype":"生物医学视觉 encoder—线性 projector—LLM 指令微调","archetype_en":"biomedical_visual_instruction_tuned_mllm","accent":"#7A3547","fig_badge":"Figure 3 · PDF p.5","fig_href":"https://proceedings.neurips.cc/paper_files/paper/2023/hash/5abcdf8ecdcacba028c6662789194572-Abstract-Datasets_and_Benchmarks.html","core_mech":"其贡献主要是将 LLaVA 两阶段训练移到生物医学域：PMC 图注概念对齐后再做合成医学指令微调。","core_mech_en":"Adapts the LLaVA visual-instruction-tuning paradigm to biomedicine via two-stage training: PMC figure–caption alignment followed by GPT-4-synthesized biomedical instruction tuning.","input_desc":"生物医学图像、图注或用户指令/问题","input_en":"Biomedical image + user clinical question or conversational instruction","output_desc":"面向图像的自回归回答、描述与解释文本","output_en":"Open-ended autoregressive biomedical explanation, visual QA response, or figure analysis","form_title":"核心公式 · 视觉投影对齐后的医学指令生成","form_title_en":"Core Formalism · Linear/MLP Visual Projection + Two-Stage Biomedical Autoregressive Instruction Tuning","nodes":[{"name":"生物医学图像","desc":"来自 PMC 图文对及下游医学问答数据","name_en":"Stage 01","desc_en":"Ingests biomedical image + user clinical question or conversational instruction and prepares initial tensor representations (Stage 01)."},{"name":"文本指令","desc":"由论文图注和 GPT-4 辅助构造的对话式任务","name_en":"Stage 02","desc_en":"Executes Stage 02 to extract primary structural features and establish spatial/sequence encoding."},{"name":"CLIP ViT vision encoder","desc":"提取 patch-level 视觉 token","name_en":"CLIP ViT vision encoder","desc_en":"Performs CLIP ViT vision encoder within the core biomedical visual instruction tuned mllm computation pathway."},{"name":"线性 multimodal projector","desc":"把视觉特征映射到 LLM token embedding 维度","name_en":"multimodal projector","desc_en":"Performs multimodal projector within the core biomedical visual instruction tuned mllm computation pathway."},{"name":"生物医学概念对齐阶段","desc":"用过滤后的 PMC 图像—图注数据先训练视觉语言连接","name_en":"Stage 05","desc_en":"Performs Stage 05 within the core biomedical visual instruction tuned mllm computation pathway."},{"name":"LLaVA/Vicuna language model","desc":"接收视觉 token 与指令 token 并自回归解码","name_en":"LLaVA/Vicuna language model","desc_en":"Performs LLaVA/Vicuna language model within the core biomedical visual instruction tuned mllm computation pathway."},{"name":"医学指令微调","desc":"对生成的多模态问答/对话数据继续优化","name_en":"fine-tuning","desc_en":"Applies fine-tuning to project aggregated representations toward the target task head."},{"name":"医学多模态回答","desc":"图像问答、描述或研究辅助文本","name_en":"multimodal","desc_en":"Produces open-ended autoregressive biomedical explanation, visual qa response, or figure analysis via multimodal."}],"design_principles":["先把预训练视觉特征映射进语言模型 embedding 空间。","先做图像—图注概念对齐，再用医学指令数据训练对话遵循。","保持 LLaVA 的简单线性连接结构，以数据构造而非复杂 fusion 获得领域能力。"],"design_principles_en":["Core Hypothesis: Project BiomedCLIP/ViT visual tokens into an LLM and fine-tune on multi-turn biomedical instructions synthesized from PubMed captions.","Architectural Delta: Fast 15-hour two-stage curriculum: Stage 1 linear projection concept alignment on PMC-15M + Stage 2 end-to-end synthetic instruction tuning.","Mathematical Formalism: Linear/MLP Visual Projection + Two-Stage Biomedical Autoregressive Instruction Tuning."],"med_apps":["适合生物医学图像问答、论文图像解释与医学教学研究。","PMC 图注偏研究图表而非临床全流程，回答可靠性和患者级安全性必须单独验证。"],"med_apps_en":["Clinical Translation: Widely adopted open-source baseline for biomedical VQA, conversational research assistance, and MLLM benchmarking.","Evidence & Safety Boundary: Foundational open medical MLLM; synthetic caption-derived instructions cannot substitute for verified clinical DICOM ground truth."],"attrs":{"上一代瓶颈":"通用 LLaVA 缺医学术语和科研图像知识，人工指令数据昂贵","核心想法":"将生物医学视觉编码器通过投影连接到 LLM，并用合成指令数据微调","关键改进":"利用 PubMed 图注生成大规模医学多模态指令并高效训练","医学适配":"用于生物医学图像问答、解释与研究辅助","适用范围与证据":"重要开放基线；合成指令偏差和临床真实性限制直接部署"},"attrs_en":{"上一代瓶颈":"General LLaVA lacked biomedical terminology and figure interpretation skills, while manual clinician instruction datasets were unavailable.","核心想法":"Project BiomedCLIP/ViT visual tokens into an LLM and fine-tune on multi-turn biomedical instructions synthesized from PubMed captions.","关键改进":"Fast 15-hour two-stage curriculum: Stage 1 linear projection concept alignment on PMC-15M + Stage 2 end-to-end synthetic instruction tuning.","医学适配":"Widely adopted open-source baseline for biomedical VQA, conversational research assistance, and MLLM benchmarking.","适用范围与证据":"Foundational open medical MLLM; synthetic caption-derived instructions cannot substitute for verified clinical DICOM ground truth."},"paper_title":"LLaVA-Med: Training a Large Language-and-Vision Assistant for Biomedicine in One Day","paper_url":"https://proceedings.neurips.cc/paper_files/paper/2023/hash/5abcdf8ecdcacba028c6662789194572-Abstract-Datasets_and_Benchmarks.html","code_label":"作者/机构官方实现","code_url":"https://github.com/microsoft/LLaVA-Med","has_code":true,"image":"assets/b4b0768232ea1ee84270.avif"},{"id":"architecture_model_101_radfm","num":101,"num_str":"101","year":2025,"year_str":"2025 (preprint 2023)","venue":"Nature Communications","venue_group":"nature","era_group":"era4","title":"RadFM","family_id":"models_vision_language","family_code":"07","family_short":"图文对齐与医学 VLM","family_en":"Vision-Language Models","family_icon":"VII","family_label":"图文对齐与生成式 VLM：开放语义不等于视觉事实","archetype":"统一 2D/3D 放射影像的视觉 encoder—Perceiver—LLM","archetype_en":"unified_2d_3d_perceiver_radiology_mllm","accent":"#7A3547","fig_badge":"Figure 5(c) · PDF p.12","fig_href":"https://doi.org/10.1038/s41467-025-62385-7","core_mech":"RadFM 的模型特异性在于统一 2D/3D 视觉 encoder 与 Perceiver 扫描聚合，再接生成式 LLM。","core_mech_en":"Unifies 2D radiographs and 3D volumetric scans (CT/MRI) via a 2D/3D ViT + Perceiver 3D aggregator feeding into a generative radiology LLM.","input_desc":"一张或一组 2D 图像、3D CT/MRI 体积及文本指令","input_en":"Single/multiple 2D radiographs or 3D CT/MRI volumes + natural-language clinical instruction","output_desc":"放射学自由文本回答、报告或识别结果","output_en":"Free-text radiology report, VQA answer, abnormality diagnosis, or rationale","form_title":"核心公式 · 二维切片聚合为统一三维扫描条件","form_title_en":"Core Formalism · Unified 2D/3D Visual Token Perceiver Aggregation for Generative Radiology LLM","nodes":[{"name":"2D/3D 扫描序列","desc":"允许不同模态、体积深度、时间点或多图组合","name_en":"2D/3D sequence","desc_en":"Ingests single/multiple 2d radiographs or 3d ct/mri volumes + natural-language clinical instruction and prepares initial tensor representations (2D/3D sequence)."},{"name":"文本指令","desc":"描述任务与问题上下文","name_en":"Stage 02","desc_en":"Executes Stage 02 to extract primary structural features and establish spatial/sequence encoding."},{"name":"统一视觉 encoder","desc":"把 2D 图像与 3D 体积编码为可变长度视觉特征","name_en":"encoder","desc_en":"Performs encoder within the core unified 2d 3d perceiver radiology mllm computation pathway."},{"name":"Perceiver aggregator","desc":"跨切片/扫描聚合为固定数量视觉 token","name_en":"Perceiver aggregator","desc_en":"Performs Perceiver aggregator within the core unified 2d 3d perceiver radiology mllm computation pathway."},{"name":"放射视觉 token","desc":"保留多图和体积上下文后对齐语言空间","name_en":"token","desc_en":"Performs token within the core unified 2d 3d perceiver radiology mllm computation pathway."},{"name":"自回归 LLM","desc":"联合读取视觉 token 与文本提示","name_en":"Autoregressive LLM","desc_en":"Performs Autoregressive LLM within the core unified 2d 3d perceiver radiology mllm computation pathway."},{"name":"多任务放射指令训练","desc":"2D、3D 与图文任务共享生成目标","name_en":"multi-task training","desc_en":"Applies multi-task training to project aggregated representations toward the target task head."},{"name":"自由文本响应","desc":"问答、报告与分类可表达为文本","name_en":"Stage 08","desc_en":"Produces free-text radiology report, vqa answer, abnormality diagnosis, or rationale via Stage 08."}],"design_principles":["视觉 encoder 同时容纳 2D 与 3D 扫描，而不是为每个模态建立孤立系统。","Perceiver 将跨切片、跨时间或跨模态的可变长度特征压成固定 token。","用 LLM 把识别、问答和报告统一为条件文本生成。"],"design_principles_en":["Core Hypothesis: Encode both 2D images and 3D volumetric patches into unified visual tokens compressed by a Perceiver resampler before an autoregressive LLM.","Architectural Delta: Unified 2D/3D visual tokenization + RadMD 16M multi-modal radiology instruction dataset + RadBench evaluation.","Mathematical Formalism: Unified 2D/3D Visual Token Perceiver Aggregation for Generative Radiology LLM."],"med_apps":["能在 CT、MRI、X-ray 等混合任务间共享视觉语言接口。","固定 token 压缩可能丢失微小三维病灶，且生成正确性不能由语言流畅度替代。"],"med_apps_en":["Clinical Translation: Addresses multi-modality radiology VQA, report generation, and disease triage across X-ray, CT, and MRI.","Evidence & Safety Boundary: Important 3D-capable radiology MLLM proof-of-concept; hallucination rates and external clinical calibration remain critical hurdles."],"attrs":{"上一代瓶颈":"多数医学 VLM 只支持单张 2D 图像且任务和模态碎片化","核心想法":"统一编码 2D 图像、3D 体积和文本，并以自回归 LLM 完成放射学多任务","关键改进":"引入可变长度 3D visual tokens 与跨模态指令数据","医学适配":"覆盖 CT、MRI、X-ray 等问答、报告与识别任务","适用范围与证据":"通用放射模型 proof-of-concept；外部临床可靠性和幻觉仍是核心风险"},"attrs_en":{"上一代瓶颈":"Most medical MLLMs accepted only single 2D slices, failing to ingest volumetric 3D CT/MRI studies natively.","核心想法":"Encode both 2D images and 3D volumetric patches into unified visual tokens compressed by a Perceiver resampler before an autoregressive LLM.","关键改进":"Unified 2D/3D visual tokenization + RadMD 16M multi-modal radiology instruction dataset + RadBench evaluation.","医学适配":"Addresses multi-modality radiology VQA, report generation, and disease triage across X-ray, CT, and MRI.","适用范围与证据":"Important 3D-capable radiology MLLM proof-of-concept; hallucination rates and external clinical calibration remain critical hurdles."},"paper_title":"Towards Generalist Foundation Model for Radiology by Leveraging Web-scale 2D&3D Medical Data","paper_url":"https://doi.org/10.1038/s41467-025-62385-7","code_label":"作者/机构官方实现","code_url":"https://github.com/chaoyi-wu/RadFM","has_code":true,"image":"assets/81901b7907c365072968.avif"},{"id":"architecture_model_102_maira_1","num":102,"num_str":"102","year":2023,"year_str":"2023 preprint","venue":"arXiv preprint","venue_group":"journal","era_group":"era4","title":"MAIRA-1","family_id":"models_vision_language","family_code":"07","family_short":"图文对齐与医学 VLM","family_en":"Vision-Language Models","family_icon":"VII","family_label":"图文对齐与生成式 VLM：开放语义不等于视觉事实","archetype":"胸片专用 RAD-DINO—四层适配器—完整微调 Vicuna 报告生成","archetype_en":"specialist_cxr_adapter_report_llm","accent":"#7A3547","fig_badge":"Table 3 · PDF p.6","fig_href":"https://arxiv.org/abs/2311.13668","core_mech":"MAIRA-1 不是通用图文预训练模型，而是冻结胸片 RAD-DINO、使用四层 adapter，并完整微调 Vicuna-7B 的专用报告生成器。","core_mech_en":"Specialist chest X-ray report generator pairing a frozen CXR-specific RAD-DINO visual encoder, a 4-layer MLP adapter, and a fully fine-tuned Vicuna-7B LLM.","input_desc":"胸部 X 光图像及可选 indication 文本","input_en":"Frontal chest X-ray + clinical indication/history prompt","output_desc":"放射报告 Findings 文本","output_en":"Structured clinical radiology Findings narrative","form_title":"核心公式 · RAD-DINO 经四层适配器条件化报告生成","form_title_en":"Core Formalism · Frozen RAD-DINO Patch Tokens Projected via 4-Layer Adapter into Fine-Tuned LLM","nodes":[{"name":"胸片输入","desc":"高分辨率正位胸片；训练域为 MIMIC-CXR","name_en":"chest X-ray (CXR) input","desc_en":"Ingests frontal chest x-ray + clinical indication/history prompt and prepares initial tensor representations (chest X-ray (CXR) input)."},{"name":"Indication/提示文本","desc":"可提供检查问题和生成格式","name_en":"Indication/ prompt","desc_en":"Executes Indication/ prompt to extract primary structural features and establish spatial/sequence encoding."},{"name":"冻结 RAD-DINO ViT-B","desc":"518 像素胸片专用视觉 encoder，输出较密集图像 token","name_en":"RAD-DINO ViT-B","desc_en":"Performs RAD-DINO ViT-B within the core specialist cxr adapter report llm computation pathway."},{"name":"四层前馈 adapter","desc":"把 RAD-DINO token 映射到 Vicuna embedding 空间","name_en":"adapter","desc_en":"Performs adapter within the core specialist cxr adapter report llm computation pathway."},{"name":"Vicuna-7B","desc":"对报告生成任务进行完整 fine-tuning，而非只训练 adapter","name_en":"Vicuna-7B","desc_en":"Performs Vicuna-7B within the core specialist cxr adapter report llm computation pathway."},{"name":"GPT-3.5 文本增强","desc":"对训练报告进行改写，增加叙述多样性","name_en":"GPT-3.5","desc_en":"Performs GPT-3.5 within the core specialist cxr adapter report llm computation pathway."},{"name":"报告 next-token loss","desc":"视觉与文本条件下教师强制训练","name_en":"next-token loss","desc_en":"Applies next-token loss to project aggregated representations toward the target task head."},{"name":"Findings 草稿","desc":"自动生成胸片所见段落","name_en":"Findings","desc_en":"Produces structured clinical radiology findings narrative via Findings."}],"design_principles":["用胸片专用 RAD-DINO 代替通用自然图像 encoder。","四层 adapter 保留大量视觉 token，再输入 Vicuna-7B。","视觉 encoder 冻结，但语言模型针对报告任务完整微调，并用文本改写扩充监督。"],"design_principles_en":["Core Hypothesis: Combine a domain-pretrained chest X-ray self-supervised encoder (RAD-DINO) with full LLM fine-tuning tailored specifically to CXR reporting.","Architectural Delta: Frozen high-resolution RAD-DINO ViT-B/14 (49×49 grid) + 4-layer MLP adapter + text augmentation + RadGraph/radiologist evaluation.","Mathematical Formalism: Frozen RAD-DINO Patch Tokens Projected via 4-Layer Adapter into Fine-Tuned LLM."],"med_apps":["直接面向胸片 Findings 草拟，可作为研究基线和人工复核候选。","仅凭生成文本不能排除漏诊或幻觉；MIMIC-CXR 域外设备、人群和报告风格需独立验证。"],"med_apps_en":["Clinical Translation: Dedicated baseline for automated chest X-ray Findings drafting and clinical factuality evaluation.","Evidence & Safety Boundary: Representative specialist report generator; lacks explicit spatial bounding-box grounding (addressed in MAIRA-2)."],"attrs":{"上一代瓶颈":"通用 VLM 报告缺结构化临床表述且易遗漏异常","核心想法":"将胸片专用视觉编码器与 Vicuna-7B 对齐并针对放射学报告生成完整微调","关键改进":"使用 CXR 专用视觉编码、文本数据增强与完整 LLM fine-tuning 强化胸片叙述","医学适配":"面向胸片 findings/impression 自动草拟与研究基线","适用范围与证据":"报告生成代表模型；需逐项事实核验和放射科医生复核"},"attrs_en":{"上一代瓶颈":"General-purpose VLMs produced stylistically generic reports and frequently omitted subtle thoracic abnormalities.","核心想法":"Combine a domain-pretrained chest X-ray self-supervised encoder (RAD-DINO) with full LLM fine-tuning tailored specifically to CXR reporting.","关键改进":"Frozen high-resolution RAD-DINO ViT-B/14 (49×49 grid) + 4-layer MLP adapter + text augmentation + RadGraph/radiologist evaluation.","医学适配":"Dedicated baseline for automated chest X-ray Findings drafting and clinical factuality evaluation.","适用范围与证据":"Representative specialist report generator; lacks explicit spatial bounding-box grounding (addressed in MAIRA-2)."},"paper_title":"MAIRA-1: A Specialised Large Multimodal Model for Radiology Report Generation","paper_url":"https://arxiv.org/abs/2311.13668","code_label":"未提供官方实现","code_url":"","has_code":false,"image":"assets/708bcf405db93275ddb5.avif"},{"id":"architecture_model_103_maira_2","num":103,"num_str":"103","year":2024,"year_str":"2024 preprint","venue":"arXiv preprint","venue_group":"journal","era_group":"era4","title":"MAIRA-2","family_id":"models_vision_language","family_code":"07","family_short":"图文对齐与医学 VLM","family_en":"Vision-Language Models","family_icon":"VII","family_label":"图文对齐与生成式 VLM：开放语义不等于视觉事实","archetype":"多上下文胸片输入与文本—边界框联合生成","archetype_en":"longitudinal_grounded_box_report_mllm","accent":"#7A3547","fig_badge":"Figure 1(b) · PDF p.3","fig_href":"https://arxiv.org/abs/2406.04449","core_mech":"相较 MAIRA-1，MAIRA-2 增加多视图/既往/报告上下文，并把报告句子与生成式 bounding-box token 绑定。","core_mech_en":"Extends MAIRA-1 with multi-view (AP/PA + lateral), prior study/report longitudinal context, and interleaved quantized bounding-box tokens for grounded reporting.","input_desc":"当前正位/侧位胸片、既往正位胸片与报告、indication、technique、comparison 和任务提示","input_en":"Current frontal & lateral CXR, prior CXR, prior report, indication, technique, comparison + task prompt","output_desc":"普通 Findings、逐句关联边界框的 grounded Findings，或短语定位框","output_en":"Ungrounded Findings, spatially grounded Findings (linking each clinical sentence to bounding boxes), or phrase grounding","form_title":"核心公式 · 多视图与既往检查条件下的 grounded 报告似然","form_title_en":"Core Formalism · Longitudinal Multi-View Conditioned Autoregressive Generation of Interleaved Text & Box Tokens","nodes":[{"name":"当前正/侧位胸片","desc":"正位为主要定位画布，侧位提供补充视角","name_en":"chest X-ray (CXR","desc_en":"Ingests current frontal & lateral cxr, prior cxr, prior report, indication, technique, comparison + task prompt and prepares initial tensor representations (chest X-ray (CXR)."},{"name":"既往图像与报告","desc":"用于比较时间变化，可为空","name_en":"Stage 02","desc_en":"Executes Stage 02 to extract primary structural features and establish spatial/sequence encoding."},{"name":"Indication/Technique/Comparison","desc":"以交错文本 token 提供真实报告上下文","name_en":"Indication/Technique/Comparison","desc_en":"Performs Indication/Technique/Comparison within the core longitudinal grounded box report mllm computation pathway."},{"name":"冻结 RAD-DINO-MAIRA-2 ViT-B","desc":"87M 参数胸片视觉 encoder","name_en":"RAD-DINO-MAIRA-2 ViT-B","desc_en":"Performs RAD-DINO-MAIRA-2 ViT-B within the core longitudinal grounded box report mllm computation pathway."},{"name":"四层 MLP adapter","desc":"从零训练，将一个或多个图像 token 映射到语言维度","name_en":"MLP adapter","desc_en":"Performs MLP adapter within the core longitudinal grounded box report mllm computation pathway."},{"name":"完整微调 Vicuna-7B v1.5","desc":"接收交错图像与文本上下文，按任务提示生成","name_en":"fine-tuning Vicuna-7B v1.5","desc_en":"Performs fine-tuning Vicuna-7B v1.5 within the core longitudinal grounded box report mllm computation pathway."},{"name":"句子—对象—框 token","desc":"可生成对象标记与量化 box，实现描述和定位绑定","name_en":"token","desc_en":"Performs token within the core longitudinal grounded box report mllm computation pathway."},{"name":"Grounded/ungrounded 多任务 LM","desc":"普通报告、grounded 报告与 phrase grounding 共享生成训练","name_en":"Grounded/ungrounded multi-task LM","desc_en":"Applies Grounded/ungrounded multi-task LM to project aggregated representations toward the target task head."},{"name":"可定位报告输出","desc":"解析为纯文本或带边界框的句子序列","name_en":"output","desc_en":"Produces ungrounded findings, spatially grounded findings (linking each clinical sentence to bounding boxes), or phrase grounding via output."}],"design_principles":["把放射科医师实际使用的当前、既往与检查指征上下文一并送入模型。","用同一自回归序列同时表达所见文本和与句子关联的边界框。","普通报告、grounded 报告和 phrase grounding 进行多任务训练。"],"design_principles_en":["Core Hypothesis: Condition the LLM on full longitudinal clinical context (multi-view + prior study/report) while emitting spatial bounding-box tokens inline with findings.","Architectural Delta: Unified sequence generation of clinical prose and quantized spatial coordinates + comprehensive longitudinal chest X-ray context.","Mathematical Formalism: Longitudinal Multi-View Conditioned Autoregressive Generation of Interleaved Text & Box Tokens."],"med_apps":["定位框使报告句子能够回指当前正位胸片区域，便于人工核验。","框只覆盖可局灶定位的发现，正常解剖、弥漫性改变和错误推理仍不能因此自动验证。"],"med_apps_en":["Clinical Translation: Sets the standard for auditable, spatially grounded adult chest X-ray report drafting and human-in-the-loop review.","Evidence & Safety Boundary: Major step toward verifiable clinical VLMs; accurate box localization still requires mandatory radiologist verification."],"attrs":{"上一代瓶颈":"纯文本报告难追溯到影像证据，模型错误不易审计","核心想法":"在报告生成时同时输出与叙述实体对应的图像区域定位","关键改进":"把检测式 grounding 与长文本生成统一，并接收当前/既往胸片、既往报告、检查指征及比较信息","医学适配":"用于成人胸片的可定位报告与研究性人机复核","适用范围与证据":"可审计报告生成的重要方向；grounding 正确不等于诊断正确"},"attrs_en":{"上一代瓶颈":"Un-grounded text reports cannot be visually audited on the image, and single-image inputs ignore longitudinal interval change.","核心想法":"Condition the LLM on full longitudinal clinical context (multi-view + prior study/report) while emitting spatial bounding-box tokens inline with findings.","关键改进":"Unified sequence generation of clinical prose and quantized spatial coordinates + comprehensive longitudinal chest X-ray context.","医学适配":"Sets the standard for auditable, spatially grounded adult chest X-ray report drafting and human-in-the-loop review.","适用范围与证据":"Major step toward verifiable clinical VLMs; accurate box localization still requires mandatory radiologist verification."},"paper_title":"MAIRA-2: Grounded Radiology Report Generation","paper_url":"https://arxiv.org/abs/2406.04449","code_label":"作者/机构官方实现","code_url":"https://huggingface.co/microsoft/maira-2","has_code":true,"image":"assets/69f42b1bd8823224dc8d.avif"},{"id":"architecture_model_104_biomedgpt","num":104,"num_str":"104","year":2024,"year_str":"2024","venue":"Nature Medicine","venue_group":"nature","era_group":"era4","title":"BiomedGPT","family_id":"models_vision_language","family_code":"07","family_short":"图文对齐与医学 VLM","family_en":"Vision-Language Models","family_icon":"VII","family_label":"图文对齐与生成式 VLM：开放语义不等于视觉事实","archetype":"多模态 token 统一的 encoder—decoder 生物医学通才模型","archetype_en":"unified_token_encoder_decoder_generalist","accent":"#7A3547","fig_badge":"Figure 2(a) · PDF p.5","fig_href":"https://doi.org/10.1038/s41591-024-03185-2","core_mech":"BiomedGPT 以模态无关、任务无关的 encoder—decoder token 化接口统一生物医学视觉、语言和多模态输出。","core_mech_en":"Modality- and task-agnostic encoder–decoder Transformer unifying biomedical images, clinical text, and bounding boxes into a discrete token sequence interface.","input_desc":"文本 token、2D 图像 patch/token 及任务指令","input_en":"2D biomedical image patches, text tokens, and task-specifying instruction prompt","output_desc":"文本、类别、坐标或图像 token 等统一序列输出","output_en":"Unified autoregressive token stream representing free text, classification labels, or spatial coordinates","form_title":"核心公式 · 跨模态任务统一为提示条件序列生成","form_title_en":"Core Formalism · Unified Sequence-to-Sequence Autoregressive Modeling Over Multimodal Biomedical Tokens","nodes":[{"name":"多模态输入","desc":"医学图像、自然语言与结构化任务提示","name_en":"multimodal input","desc_en":"Ingests 2d biomedical image patches, text tokens, and task-specifying instruction prompt and prepares initial tensor representations (multimodal input)."},{"name":"ResNet patch front-end","desc":"图像经卷积块稀疏编码为视觉 patch token","name_en":"ResNet patch front-end","desc_en":"Executes ResNet patch front-end to extract primary structural features and establish spatial/sequence encoding."},{"name":"BPE + token embedding","desc":"文本和任务提示编码到共享维度","name_en":"BPE + token embedding","desc_en":"Performs BPE + token embedding within the core unified token encoder decoder generalist computation pathway."},{"name":"统一输入序列","desc":"模态、位置和任务标记区分不同 token 语义","name_en":"input sequence","desc_en":"Performs input sequence within the core unified token encoder decoder generalist computation pathway."},{"name":"Transformer encoder","desc":"跨模态上下文编码并形成共享语义表示","name_en":"Transformer encoder","desc_en":"Performs Transformer encoder within the core unified token encoder decoder generalist computation pathway."},{"name":"Transformer decoder","desc":"条件于 encoder 表示自回归预测目标 token","name_en":"Transformer decoder","desc_en":"Performs Transformer decoder within the core unified token encoder decoder generalist computation pathway."},{"name":"统一多任务预训练","desc":"文本、图像、视觉语言与定位任务按 seq2seq 格式混合","name_en":"multi-task pretraining","desc_en":"Applies multi-task pretraining to project aggregated representations toward the target task head."},{"name":"任务化输出","desc":"解码为回答、标签、区域或生成内容","name_en":"output","desc_en":"Produces unified autoregressive token stream representing free text, classification labels, or spatial coordinates via output."}],"design_principles":["把不同模态离散成 token，以相同 encoder—decoder 接口处理。","把分类、生成、问答和定位重写为带任务提示的 seq2seq。","多领域多任务联合预训练使参数在放射、病理、皮肤和文本任务间共享。"],"design_principles_en":["Core Hypothesis: Map vision patches, text subwords, and spatial locations into a shared discrete vocabulary processed by a unified BART/OFA-style encoder–decoder.","Architectural Delta: Multi-task, multi-specialty pretraining + instruction fine-tuning across vision, language, VQA, captioning, and detection.","Mathematical Formalism: Unified Sequence-to-Sequence Autoregressive Modeling Over Multimodal Biomedical Tokens."],"med_apps":["一个模型可复用到多种生物医学理解和生成任务，降低每任务重新设计 head 的成本。","统一 token 不代表统一证据强度；跨模态任务的数据规模、标注质量和安全验证仍须逐项报告。"],"med_apps_en":["Clinical Translation: Generalist biomedical foundation baseline spanning radiology, pathology, ophthalmology, dermatology, and biomedical NLP.","Evidence & Safety Boundary: Representative generalist architecture; specialist models often retain an edge on high-stakes quantitative or 3D tasks."],"attrs":{"上一代瓶颈":"生物医学模型按模态和任务分散，难共享知识与接口","核心想法":"以统一序列到序列框架处理生物医学图像、文本和多种输出格式","关键改进":"在多领域多任务数据上联合预训练并用任务提示统一预测","医学适配":"覆盖放射、病理、皮肤、文本理解和生成任务","适用范围与证据":"generalist 医学模型代表；跨中心临床价值仍依赖专门验证"},"attrs_en":{"上一代瓶颈":"Biomedical AI models were siloed by modality (radiology vs. pathology vs. text) and task head architecture.","核心想法":"Map vision patches, text subwords, and spatial locations into a shared discrete vocabulary processed by a unified BART/OFA-style encoder–decoder.","关键改进":"Multi-task, multi-specialty pretraining + instruction fine-tuning across vision, language, VQA, captioning, and detection.","医学适配":"Generalist biomedical foundation baseline spanning radiology, pathology, ophthalmology, dermatology, and biomedical NLP.","适用范围与证据":"Representative generalist architecture; specialist models often retain an edge on high-stakes quantitative or 3D tasks."},"paper_title":"A Generalist Vision-Language Foundation Model for Diverse Biomedical Tasks","paper_url":"https://doi.org/10.1038/s41591-024-03185-2","code_label":"作者/机构官方实现","code_url":"https://github.com/taokz/BiomedGPT","has_code":true,"image":"assets/9163365699c6c1f86cb1.avif"},{"id":"architecture_model_105_virchow","num":105,"num_str":"105","year":2024,"year_str":"2024","venue":"Nature Medicine","venue_group":"nature","era_group":"era4","title":"Virchow","family_id":"models_pathology_foundations","family_code":"08","family_short":"计算病理基础模型","family_en":"Pathology Foundations","family_icon":"VIII","family_label":"病理基础模型：从 patch encoder 到 whole-slide 多模态推理","archetype":"百万级 WSI tile 的 DINOv2 ViT-H 自监督病理 encoder","archetype_en":"clinical_scale_dinov2_vith_tile_encoder","accent":"#7A3547","fig_badge":"Figure 1(e–f) · PDF p.Official full-size Figure 1 asset","fig_href":"https://www.nature.com/articles/s41591-024-03141-0","core_mech":"Virchow 是 632M ViT-H/14 的病理 tile foundation encoder，以约 150 万临床 WSI 的 DINOv2 自监督规模取胜。","core_mech_en":"632M-parameter ViT-H/14 computational pathology tile foundation model pretrained with DINOv2 on 2 billion tiles from 1.5 million clinical H&E whole-slide images.","input_desc":"H&E 全切片切出的组织 tile 及其全局/局部增强视图","input_en":"224×224 H&E histopathology tissue tile (with global and local crops during pretraining)","output_desc":"tile-level 632M ViT embedding；下游可经 WSI aggregator 形成病例预测","output_en":"2560-D tile representation ([CLS] concatenated with mean patch token) feeding downstream WSI aggregators","form_title":"核心公式 · 病理 tile 的 DINOv2 全局蒸馏与 iBOT 掩码学习","form_title_en":"Core Formalism · 632M ViT-H/14 DINOv2 Global Distillation + iBOT Masked Patch + KoLeo Regularization","nodes":[{"name":"H&E whole-slide images","desc":"约 150 万 WSI 的临床病理训练库","name_en":"H&E whole-slide images","desc_en":"Ingests 224×224 h&e histopathology tissue tile (with global and local crops during pretraining) and prepares initial tensor representations (H&E whole-slide images)."},{"name":"组织 tile 与多裁剪","desc":"WSI 切块后形成全局和局部组织视图","name_en":"tile","desc_en":"Executes tile to extract primary structural features and establish spatial/sequence encoding."},{"name":"ViT-H/14 student","desc":"632M 参数 tile encoder 学习 patch 与全局表征","name_en":"ViT-H/14 student","desc_en":"Performs ViT-H/14 student within the core clinical scale dinov2 vith tile encoder computation pathway."},{"name":"EMA teacher","desc":"按 DINOv2 更新，提供跨视图自蒸馏目标","name_en":"EMA teacher","desc_en":"Performs EMA teacher within the core clinical scale dinov2 vith tile encoder computation pathway."},{"name":"DINOv2 多视图目标","desc":"结合全局/局部自蒸馏与 patch-level 学习","name_en":"DINOv2 multi-view objective","desc_en":"Performs DINOv2 multi-view objective within the core clinical scale dinov2 vith tile encoder computation pathway."},{"name":"Virchow tile embedding","desc":"可冻结抽取局部组织形态表示","name_en":"Virchow tile embedding","desc_en":"Performs Virchow tile embedding within the core clinical scale dinov2 vith tile encoder computation pathway."},{"name":"下游 WSI aggregator","desc":"MIL/attention 等任务模型汇聚数千 tile；不是 Virchow 预训练主体","name_en":"WSI aggregator","desc_en":"Applies WSI aggregator to project aggregated representations toward the target task head."},{"name":"临床任务 head","desc":"癌症检测、稀有癌、细胞或 biomarker 预测","name_en":"head","desc_en":"Produces 2560-d tile representation ([cls] concatenated with mean patch token) feeding downstream wsi aggregators via head."}],"design_principles":["在大规模临床 H&E tile 上训练 ViT-H，而非从 ImageNet 特征起步。","DINOv2 的多视图 student—teacher 自蒸馏无需人工病理标签。","预训练产物首先是 tile encoder；WSI 级结论仍需额外聚合器。"],"design_principles_en":["Core Hypothesis: Scale both model capacity (ViT-H/14, 632M) and clinical data volume (1.5M WSIs from MSKCC) under DINOv2 self-supervised learning.","Architectural Delta: Institutional gigapixel scale (1.5M slides) + 632M ViT-H architecture demonstrating strong pan-cancer and rare-cancer generalization.","Mathematical Formalism: 632M ViT-H/14 DINOv2 Global Distillation + iBOT Masked Patch + KoLeo Regularization."],"med_apps":["为 pan-cancer、稀有癌、细胞识别和 biomarker 任务提供低样本 tile 特征。","tile 级强表示不自动解决 WSI 空间稀疏性，聚合器、患者去重和扫描域移位必须单独评估。"],"med_apps_en":["Clinical Translation: Supports pan-cancer detection, rare tumor identification, biomarker prediction, and cell-level pathology tasks.","Evidence & Safety Boundary: Landmark high-capacity pathology tile encoder; independent benchmarks show ensemble diversity with UNI/CONCH remains valuable."],"attrs":{"上一代瓶颈":"病理监督标签稀缺且稀有癌种难覆盖，ImageNet 特征域差距大","核心想法":"在百万级全切片 patch 上自监督预训练大规模 ViT 病理编码器","关键改进":"利用海量临床 WSI 和 DINOv2 式预训练提升低样本与稀有任务迁移","医学适配":"支持 pan-cancer detection、稀有癌、细胞识别和 biomarker prediction","适用范围与证据":"病理 FM 关键里程碑；患者级去重、扫描域移位和独立比较仍重要"},"attrs_en":{"上一代瓶颈":"Smaller pathology models struggled on rare cancer variants and cross-laboratory staining variations.","核心想法":"Scale both model capacity (ViT-H/14, 632M) and clinical data volume (1.5M WSIs from MSKCC) under DINOv2 self-supervised learning.","关键改进":"Institutional gigapixel scale (1.5M slides) + 632M ViT-H architecture demonstrating strong pan-cancer and rare-cancer generalization.","医学适配":"Supports pan-cancer detection, rare tumor identification, biomarker prediction, and cell-level pathology tasks.","适用范围与证据":"Landmark high-capacity pathology tile encoder; independent benchmarks show ensemble diversity with UNI/CONCH remains valuable."},"paper_title":"A Foundation Model for Clinical-Grade Computational Pathology and Rare Cancers Detection","paper_url":"https://doi.org/10.1038/s41591-024-03141-0","code_label":"作者/机构官方实现","code_url":"https://huggingface.co/paige-ai/Virchow","has_code":true,"image":"assets/f68e890ce0b7c62c55c4.avif"},{"id":"architecture_model_106_chief","num":106,"num_str":"106","year":2024,"year_str":"2024","venue":"Nature","venue_group":"nature","era_group":"era4","title":"CHIEF","family_id":"models_pathology_foundations","family_code":"08","family_short":"计算病理基础模型","family_en":"Pathology Foundations","family_icon":"VIII","family_label":"病理基础模型：从 patch encoder 到 whole-slide 多模态推理","archetype":"tile 自监督与 WSI 弱监督相接的双阶段病理基础模型","archetype_en":"two_stage_tile_and_site_wsi_foundation","accent":"#7A3547","fig_badge":"Figure 1(a) · PDF p.Official full-size Figure 1 asset","fig_href":"https://www.nature.com/articles/s41586-024-07894-z","core_mech":"CHIEF 明确串联 CTransPath tile 自监督和带解剖条件的 WSI attention 弱监督，而非只发布局部 patch encoder。","core_mech_en":"Couples self-supervised tile encoding (CTransPath) with anatomical-site-conditioned whole-slide attention aggregation trained across 60,530 WSIs.","input_desc":"H&E WSI、tile 特征及训练时的癌症/解剖部位弱标签","input_en":"H&E whole-slide image tiles + anatomical primary site text/categorical embedding","output_desc":"通用 tile embedding、WSI embedding 和诊断/预后任务输出","output_en":"Slide-level diagnostic representation for cancer detection, tumor origin, genomic mutation, and survival prediction","form_title":"核心公式 · CHIEF 的注意力式全切片聚合与判读","form_title_en":"Core Formalism · Anatomical-Site-Conditioned Attention MIL Whole-Slide Aggregation & Contrastive Supervision","nodes":[{"name":"Whole-slide image","desc":"多中心、多癌种 WSI 输入","name_en":"Whole-slide image","desc_en":"Ingests h&e whole-slide image tiles + anatomical primary site text/categorical embedding and prepares initial tensor representations (Whole-slide image)."},{"name":"WSI tile 序列","desc":"从组织区域采样局部 patch","name_en":"WSI tile sequence","desc_en":"Executes WSI tile sequence to extract primary structural features and establish spatial/sequence encoding."},{"name":"CHIEF-CTransPath","desc":"自监督 Swin Transformer tile encoder，输出 768 维局部特征","name_en":"CHIEF-CTransPath","desc_en":"Performs CHIEF-CTransPath within the core two stage tile and site wsi foundation computation pathway."},{"name":"解剖部位 token/监督","desc":"向 WSI 模型提供组织来源上下文","name_en":"token","desc_en":"Performs token within the core two stage tile and site wsi foundation computation pathway."},{"name":"Attention WSI aggregator","desc":"对可变数量 tile 加权汇聚并识别关键实例","name_en":"Attention WSI aggregator","desc_en":"Performs Attention WSI aggregator within the core two stage tile and site wsi foundation computation pathway."},{"name":"WSI 弱监督预训练","desc":"用 slide-level 癌症相关标签训练全片模式识别","name_en":"WSI weakly supervised pretraining","desc_en":"Performs WSI weakly supervised pretraining within the core two stage tile and site wsi foundation computation pathway."},{"name":"CHIEF WSI embedding","desc":"可冻结迁移的 768 维全片表示","name_en":"CHIEF WSI embedding","desc_en":"Applies CHIEF WSI embedding to project aggregated representations toward the target task head."},{"name":"诊断/分子/生存 heads","desc":"肿瘤来源、biomarker 与预后模型","name_en":"heads","desc_en":"Produces slide-level diagnostic representation for cancer detection, tumor origin, genomic mutation, and survival prediction via heads."}],"design_principles":["先用无标签 tile 学局部组织形态，再用 slide 弱标签学全片模式。","attention 聚合在大量实例中选择与病例标签相关的区域。","解剖部位上下文与多中心预训练共同提升跨癌种复用。"],"design_principles_en":["Core Hypothesis: Combine a pretrained hybrid CNN-Transformer tile encoder with a weakly supervised WSI attention aggregator conditioned on anatomical site.","Architectural Delta: Two-stage tile + slide pretraining across 19 anatomical sites with broad multi-center external validation.","Mathematical Formalism: Anatomical-Site-Conditioned Attention MIL Whole-Slide Aggregation & Contrastive Supervision."],"med_apps":["同一 WSI 表示可迁移到癌种识别、分子标志物和生存风险。","弱监督注意力不是病理学因果定位，回顾性预后关联也不等同于治疗决策效益。"],"med_apps_en":["Clinical Translation: Applied to cancer detection, tumor origin identification, genomic profile inference, and survival risk stratification.","Evidence & Safety Boundary: Demonstrates broad multi-center retrospective validation; prognostic risk scores still require prospective trial verification."],"attrs":{"上一代瓶颈":"patch encoder 与 slide-level 预后模型割裂，跨癌种迁移有限","核心想法":"联合自监督图像预训练与弱监督全切片聚合学习癌症表征","关键改进":"在多中心多癌种 WSI 上学习可用于诊断和生存预测的通用表示","医学适配":"用于癌种识别、分子标志物和预后风险建模","适用范围与证据":"临床广度突出；回顾性关联不等同于前瞻性决策效益"},"attrs_en":{"上一代瓶颈":"Standalone patch encoders lacked pre-trained slide-level aggregators conditioned on anatomical site context.","核心想法":"Combine a pretrained hybrid CNN-Transformer tile encoder with a weakly supervised WSI attention aggregator conditioned on anatomical site.","关键改进":"Two-stage tile + slide pretraining across 19 anatomical sites with broad multi-center external validation.","医学适配":"Applied to cancer detection, tumor origin identification, genomic profile inference, and survival risk stratification.","适用范围与证据":"Demonstrates broad multi-center retrospective validation; prognostic risk scores still require prospective trial verification."},"paper_title":"A Pathology Foundation Model for Cancer Diagnosis and Prognosis Prediction","paper_url":"https://doi.org/10.1038/s41586-024-07894-z","code_label":"作者/机构官方实现","code_url":"https://github.com/hms-dbmi/CHIEF","has_code":true,"image":"assets/ae286e936572fc945474.avif"},{"id":"architecture_model_107_titan","num":107,"num_str":"107","year":2025,"year_str":"2025","venue":"Nature Medicine","venue_group":"nature","era_group":"era4","title":"TITAN","family_id":"models_pathology_foundations","family_code":"08","family_short":"计算病理基础模型","family_en":"Pathology Foundations","family_icon":"VIII","family_label":"病理基础模型：从 patch encoder 到 whole-slide 多模态推理","archetype":"iBOT 全片视觉预训练加 CoCa 多尺度图文对齐","archetype_en":"three_stage_ibot_coca_wsi_foundation","accent":"#7A3547","fig_badge":"Figure 1(d) · PDF p.5","fig_href":"https://doi.org/10.1038/s41591-025-03982-3","core_mech":"TITAN 的特异性是三阶段 whole-slide 预训练：特征网格 iBOT、ROI caption CoCa、WSI report CoCa。","core_mech_en":"Three-stage multimodal whole-slide foundation model pretrained via iBOT on 2D tile feature grids, CoCa on synthetic ROI captions, and CoCa on whole-slide pathology reports.","input_desc":"预提取病理 patch 网格、ROI 合成描述和 WSI 病理报告","input_en":"Pre-extracted 2D spatial grid of WSI patch embeddings (CONCH v1.5) + ROI descriptions / clinical pathology reports","output_desc":"通用 whole-slide embedding、跨模态检索分数与病理文本生成","output_en":"General-purpose whole-slide embedding, zero-shot slide classification, cross-modal report retrieval, and slide report generation","form_title":"核心公式 · 病理 tile、切片—文本对齐与报告生成三阶段目标","form_title_en":"Core Formalism · Three-Stage Slide Pretraining: Grid iBOT + ROI Caption CoCa + Clinical WSI Report CoCa","nodes":[{"name":"空间化 patch feature grid","desc":"病理 patch encoder 特征按 WSI 二维坐标重新排列","name_en":"spatial patch feature grid","desc_en":"Ingests pre-extracted 2d spatial grid of wsi patch embeddings (conch v1.5) + roi descriptions / clinical pathology reports and prepares initial tensor representations (spatial patch feature grid)."},{"name":"TITAN slide ViT","desc":"把 patch feature 当作 ViT patch embedding，建模全片上下文","name_en":"TITAN slide ViT","desc_en":"Executes TITAN slide ViT to extract primary structural features and establish spatial/sequence encoding."},{"name":"Stage 1 iBOT student–teacher","desc":"在 ROI/WSI 特征网格上做掩码建模与知识蒸馏","name_en":"Stage 1 iBOT student–teacher","desc_en":"Performs Stage 1 iBOT student–teacher within the core three stage ibot coca wsi foundation computation pathway."},{"name":"Stage 2 ROI-caption pairs","desc":"8k×8k ROI 与 PathChat 合成细粒度形态描述","name_en":"Stage 2 ROI-caption pairs","desc_en":"Performs Stage 2 ROI-caption pairs within the core three stage ibot coca wsi foundation computation pathway."},{"name":"Stage 3 WSI-report pairs","desc":"全切片与临床病理报告对齐","name_en":"Stage 3 WSI-report pairs","desc_en":"Performs Stage 3 WSI-report pairs within the core three stage ibot coca wsi foundation computation pathway."},{"name":"CoCa text encoder","desc":"编码 ROI caption 和 slide report","name_en":"CoCa text encoder","desc_en":"Performs CoCa text encoder within the core three stage ibot coca wsi foundation computation pathway."},{"name":"CoCa multimodal decoder","desc":"对视觉表示做 cross-attention 并生成描述/报告","name_en":"CoCa multimodal decoder","desc_en":"Performs CoCa multimodal decoder within the core three stage ibot coca wsi foundation computation pathway."},{"name":"对比对齐 + captioning","desc":"ROI 与 WSI 两个尺度联合优化检索和生成","name_en":"contrastive alignment + captioning","desc_en":"Applies contrastive alignment + captioning to project aggregated representations toward the target task head."},{"name":"TITAN slide 表示与语言能力","desc":"支持零样本、检索、报告生成和线性探测","name_en":"TITAN slide","desc_en":"Produces general-purpose whole-slide embedding, zero-shot slide classification, cross-modal report retrieval, and slide report generation via TITAN slide."}],"design_principles":["先把 patch 特征按坐标组成二维网格，再在 embedding 空间训练全片 ViT。","Stage 1 用 iBOT 视觉自监督学习 ROI/WSI 结构。","Stage 2/3 用 CoCa 分别对齐细粒度 ROI 描述和 slide-level 报告，同时训练检索与生成。"],"design_principles_en":["Core Hypothesis: Pretrain a Vision Transformer slide encoder directly over spatial grids of tile embeddings using progressive visual and clinical report supervision.","Architectural Delta: Progressive 3-stage slide-level curriculum (335K WSIs) bridging spatial tile grids, synthetic ROI morphology captions, and clinical reports.","Mathematical Formalism: Three-Stage Slide Pretraining: Grid iBOT + ROI Caption CoCa + Clinical WSI Report CoCa."],"med_apps":["把病理基础模型从 tile 表示推进到整片、零样本、报告和跨模态检索。","合成 caption 与机构报告可带入风格偏差；公开权重若不含完整 decoder，则论文生成能力不能直接复现。"],"med_apps_en":["Clinical Translation: Enables zero-shot whole-slide subtyping, rare cancer retrieval, biomarker prediction, and slide-level representation reuse.","Evidence & Safety Boundary: Frontier multimodal slide foundation model; note that the publicly released weights omit the generative text decoder."],"attrs":{"上一代瓶颈":"仅 patch 级预训练缺整片上下文，纯视觉模型难接入语言任务","核心想法":"以 slide encoder 汇聚 gigapixel WSI，并与病理报告文本进行跨模态对齐","关键改进":"在整片尺度联合视觉自监督和图文对齐，支持零样本与生成任务","医学适配":"用于 WSI 分类、检索、报告和生物标志物预测","适用范围与证据":"whole-slide 多模态 FM 前沿；公开权重移除了多模态 decoder，论文报告生成功能不能完整复现"},"attrs_en":{"上一代瓶颈":"Most pathology foundation models stopped at the tile level, requiring task-specific MIL training from scratch for every slide-level task.","核心想法":"Pretrain a Vision Transformer slide encoder directly over spatial grids of tile embeddings using progressive visual and clinical report supervision.","关键改进":"Progressive 3-stage slide-level curriculum (335K WSIs) bridging spatial tile grids, synthetic ROI morphology captions, and clinical reports.","医学适配":"Enables zero-shot whole-slide subtyping, rare cancer retrieval, biomarker prediction, and slide-level representation reuse.","适用范围与证据":"Frontier multimodal slide foundation model; note that the publicly released weights omit the generative text decoder."},"paper_title":"A Multimodal Whole-Slide Foundation Model for Pathology","paper_url":"https://doi.org/10.1038/s41591-025-03982-3","code_label":"作者/机构官方实现","code_url":"https://github.com/mahmoodlab/TITAN","has_code":true,"image":"assets/cea0e975856606bfe37d.avif"},{"id":"architecture_model_108_prism2","num":108,"num_str":"108","year":2026,"year_str":"2026","venue":"Nature Medicine","venue_group":"nature","era_group":"era4","title":"PRISM2","family_id":"models_pathology_foundations","family_code":"08","family_short":"计算病理基础模型","family_en":"Pathology Foundations","family_icon":"VIII","family_label":"病理基础模型：从 patch encoder 到 whole-slide 多模态推理","archetype":"Virchow2—Perceiver—Phi-3 的双嵌入临床对话病理模型","archetype_en":"perceiver_phi3_dual_embedding_pathology_fm","accent":"#7A3547","fig_badge":"Figure 1(a) · PDF p.Official full-size Figure 1 asset","fig_href":"https://www.nature.com/articles/s41591-026-04521-4","core_mech":"PRISM2 明确提供双嵌入：Perceiver 的通用 base embedding，以及 Phi-3 隐状态导出的诊断 embedding。","core_mech_en":"Pairs a Perceiver slide encoder over Virchow2 tile embeddings with a Phi-3 LLM trained on single-turn clinical dialogues derived from pathology reports, exposing dual embeddings.","input_desc":"一个病例的一张或多张 H&E WSI、文本提示与由报告改写的单轮临床对话","input_en":"Multi-slide H&E case tile embeddings (Virchow2) + clinical prompt / diagnostic query","output_desc":"2560 维 base embedding、3072 维 diagnostic embedding、报告或问答文本","output_en":"2560-D base slide embedding, 3072-D LLM diagnostic embedding, or autoregressive pathology text response","form_title":"核心公式 · PRISM2 基础嵌入与诊断嵌入的双接口","form_title_en":"Core Formalism · Dual-Interface Perceiver Base Slide Embedding & Phi-3 Diagnostic Hidden-State Embedding","nodes":[{"name":"病例 WSI tiles","desc":"一张或多张超大 WSI 先切成组织 tiles","name_en":"WSI tiles","desc_en":"Ingests multi-slide h&e case tile embeddings (virchow2) + clinical prompt / diagnostic query and prepares initial tensor representations (WSI tiles)."},{"name":"Virchow2 tile encoder","desc":"逐 tile 产生冻结病理 embedding","name_en":"Virchow2 tile encoder","desc_en":"Executes Virchow2 tile encoder to extract primary structural features and establish spatial/sequence encoding."},{"name":"Perceiver slide encoder","desc":"跨大量 tile 交叉注意力压缩为 slide latents","name_en":"Perceiver slide encoder","desc_en":"Performs Perceiver slide encoder within the core perceiver phi3 dual embedding pathology fm computation pathway."},{"name":"Base embedding","desc":"Perceiver pooling 的 2560 维轻量通用全片表示","name_en":"Base embedding","desc_en":"Performs Base embedding within the core perceiver phi3 dual embedding pathology fm computation pathway."},{"name":"BioGPT text encoder","desc":"Stage 1 提供诊断摘要文本 embedding 的对比目标","name_en":"BioGPT text encoder","desc_en":"Performs BioGPT text encoder within the core perceiver phi3 dual embedding pathology fm computation pathway."},{"name":"Phi-3 Mini 128k","desc":"Stage 1 自回归生成；Stage 2 冻结 slide encoder 后微调临床对话","name_en":"Phi-3 Mini 128k","desc_en":"Performs Phi-3 Mini 128k within the core perceiver phi3 dual embedding pathology fm computation pathway."},{"name":"Stage 1 对比 + 自回归","desc":"slide 表示同时对齐 BioGPT 摘要并支持 Phi-3 文本生成","name_en":"Stage 1 +","desc_en":"Performs Stage 1 + within the core perceiver phi3 dual embedding pathology fm computation pathway."},{"name":"Stage 2 dialogue tuning","desc":"报告、开放问答、是非题和选择题；仅优化语言接口","name_en":"Stage 2 dialogue tuning","desc_en":"Applies Stage 2 dialogue tuning to project aggregated representations toward the target task head."},{"name":"Diagnostic embedding/文本","desc":"固定图像提示下取 Phi-3 assistant 位置隐状态，或直接生成单轮回答","name_en":"Diagnostic embedding","desc_en":"Produces 2560-d base slide embedding, 3072-d llm diagnostic embedding, or autoregressive pathology text response via Diagnostic embedding."}],"design_principles":["Virchow2 负责局部 tile，Perceiver 把超长序列压成可迁移 base embedding。","Stage 1 让同一 slide 表示同时满足 BioGPT 对比对齐与 Phi-3 自回归生成。","Stage 2 冻结 slide encoder，仅用报告改写的单轮临床对话强化 prompt-based inference。"],"design_principles_en":["Core Hypothesis: Connect a Perceiver slide aggregator to a clinical LLM (Phi-3) via conversational report supervision, extracting both visual and LLM-contextualized embeddings.","Architectural Delta: Exposes dual reusable interfaces (Perceiver base embedding + LLM last-token diagnostic embedding) alongside promptable zero-shot inference.","Mathematical Formalism: Dual-Interface Perceiver Base Slide Embedding & Phi-3 Diagnostic Hidden-State Embedding."],"med_apps":["base embedding 更适合 biomarker、生存等迁移；diagnostic embedding 更偏癌症诊断语义。","临床对话是丰富监督形式，不表示模型被设计为多轮部署聊天代理；生成输出仍可能错误。"],"med_apps_en":["Clinical Translation: Designed as a promptable whole-slide diagnostic representation and conversational reasoning engine rather than a patient-facing chatbot.","Evidence & Safety Boundary: Emerging 2025/2026 frontier preprint; requires independent multi-center replication and pathologist workflow validation."],"attrs":{"上一代瓶颈":"两阶段 patch/slide/LLM 管线信息瓶颈多且难统一适配","核心想法":"将 Virchow2 tile embeddings 输入 Perceiver slide encoder，再连接 Phi-3 进行临床对话式推理","关键改进":"第一阶段训练 slide encoder，第二阶段冻结它并训练语言接口与 prompt-based inference","医学适配":"以临床对话作为监督和病理全切片推理接口，不以部署聊天代理为目标","适用范围与证据":"新近前沿；需要独立复现、病理医生盲评和部署安全证据"},"attrs_en":{"上一代瓶颈":"Two-stage MIL + LLM pathology pipelines suffered from rigid task heads and disconnected visual vs. linguistic representations.","核心想法":"Connect a Perceiver slide aggregator to a clinical LLM (Phi-3) via conversational report supervision, extracting both visual and LLM-contextualized embeddings.","关键改进":"Exposes dual reusable interfaces (Perceiver base embedding + LLM last-token diagnostic embedding) alongside promptable zero-shot inference.","医学适配":"Designed as a promptable whole-slide diagnostic representation and conversational reasoning engine rather than a patient-facing chatbot.","适用范围与证据":"Emerging 2025/2026 frontier preprint; requires independent multi-center replication and pathologist workflow validation."},"paper_title":"End-to-End Multimodal Pathology Foundation Model with Clinical Dialogue","paper_url":"https://doi.org/10.1038/s41591-026-04521-4","code_label":"作者/机构官方实现","code_url":"https://huggingface.co/paige-ai/Prism2","has_code":true,"image":"assets/2827be379bdbb50eb27c.avif"},{"id":"architecture_model_109_bme_x","num":109,"num_str":"109","year":2025,"year_str":"2025 (online 2024)","venue":"Nature Biomedical Engineering","venue_group":"nature","era_group":"era4","title":"BME-X","family_id":"models_volumetric_foundations","family_code":"09","family_short":"CT/MRI 检查级模型","family_en":"Volumetric Study FMs","family_icon":"IX","family_label":"CT/MRI 检查级基础模型：输入单位从切片走向完整 study","archetype":"组织标签先验驱动的双 DU-Net 脑 MRI 增强","archetype_en":"tissue_prior_dual_unet_mri_harmonization","accent":"#6B5700","fig_badge":"Figure 1(a) · PDF p.Official full-size Figure 1 asset","fig_href":"https://www.nature.com/articles/s41551-024-01283-7","core_mech":"BME-X 不是通用 MRI encoder，而是先预测组织标签、再用组织感知 DU-Net 生成增强图像的两阶段恢复模型。","core_mech_en":"Two-stage brain MRI enhancement foundation model that first estimates tissue probability maps and then conditions a Dual U-Net (DU-Net) to restore harmonized images.","input_desc":"受运动、低分辨率、噪声、扫描仪或场强差异影响的结构脑 MRI","input_en":"Structural brain MRI degraded by motion, low resolution, noise, or cross-scanner field-strength shifts","output_desc":"高质量、组织强度更一致的增强 MRI，可供分割、配准与诊断","output_en":"Harmonized, artifact-corrected, high-resolution brain MRI ready for downstream morphometry, registration, and diagnosis","form_title":"核心公式 · 组织概率图条件化的脑 MRI 增强","form_title_en":"Core Formalism · Tissue-Probability-Conditioned Dual-Domain Brain MRI Restoration & Harmonization","nodes":[{"name":"低质量结构脑 MRI","desc":"覆盖运动、降采样、噪声、对比/扫描仪差异等退化","name_en":"MRI","desc_en":"Ingests structural brain mri degraded by motion, low resolution, noise, or cross-scanner field-strength shifts and prepares initial tensor representations (MRI)."},{"name":"Tissue-classification DU-Net","desc":"密集连接 U-Net 从退化图像预测背景、CSF、灰质、白质等组织标签","name_en":"Tissue-classification DU-Net","desc_en":"Executes Tissue-classification DU-Net to extract primary structural features and establish spatial/sequence encoding."},{"name":"软组织标签图","desc":"作为解剖条件，不是最终分割产品","name_en":"soft tissue","desc_en":"Performs soft tissue within the core tissue prior dual unet mri harmonization computation pathway."},{"name":"图像—组织条件融合","desc":"将低质量 MRI 与预测组织图拼接","name_en":"fusion","desc_en":"Performs fusion within the core tissue prior dual unet mri harmonization computation pathway."},{"name":"Tissue-aware enhancement DU-Net","desc":"在组织先验约束下恢复清晰度、分辨率与标准化对比","name_en":"Tissue-aware enhancement DU-Net","desc_en":"Performs Tissue-aware enhancement DU-Net within the core tissue prior dual unet mri harmonization computation pathway."},{"name":"合成退化—高质量配对训练","desc":"从高质量结构 MRI 构造多种退化，联合学习组织和增强目标","name_en":"training","desc_en":"Performs training within the core tissue prior dual unet mri harmonization computation pathway."},{"name":"增强 MRI","desc":"一个固定模型覆盖多类结构脑 MRI 增强任务","name_en":"MRI","desc_en":"Applies MRI to project aggregated representations toward the target task head."},{"name":"下游验证链","desc":"组织分割、皮层测量、配准和诊断模型检验实际效用与偏差","name_en":"Stage 08","desc_en":"Produces harmonized, artifact-corrected, high-resolution brain mri ready for downstream morphometry, registration, and diagnosis via Stage 08."}],"design_principles":["先把复杂退化问题转成较稳定的组织分类，再以组织图约束增强。","低质量图像与软组织标签共同输入第二个 DU-Net，避免只追求纹理锐化。","一个预训练模型统一运动校正、超分、去噪、harmonization 与 3T→7T-like 增强。"],"design_principles_en":["Core Hypothesis: Pre-estimate anatomical tissue segmentation probabilities to explicitly guide a tissue-aware enhancement network across diverse degradations.","Architectural Delta: Couples anatomical tissue priors with unified motion correction, super-resolution, denoising, and multi-site scanner harmonization.","Mathematical Formalism: Tissue-Probability-Conditioned Dual-Domain Brain MRI Restoration & Harmonization."],"med_apps":["增强价值用组织分割、配准、诊断和组织体积偏差共同验证，而不只看 PSNR。","模型专用于结构脑 MRI；组织先验错误可能把异常解剖拉向常见形态，病灶保真需单独检查。"],"med_apps_en":["Clinical Translation: Serves as a universal structural brain MRI pre-processing and harmonization front-end improving downstream FreeSurfer/segmentation consistency.","Evidence & Safety Boundary: Representative restoration-oriented MRI foundation model; must be audited to ensure subtle focal lesions are not harmonized away."],"attrs":{"上一代瓶颈":"MRI 增强模型通常按 degradation 或扫描仪分别训练，且增强质量与下游价值脱节","核心想法":"先预测组织标签，再用 tissue-aware enhancement network 统一结构脑 MRI 的运动校正、超分、去噪和扫描仪协调化","关键改进":"以组织标签约束增强，并验证增强图像能改善后续分割、配准与诊断模型","医学适配":"面向结构脑 MRI 的多任务图像增强，而非多器官通用编码器","适用范围与证据":"MRI enhancement foundation 路线代表；真实世界协议差异和前瞻证据仍有限"},"attrs_en":{"上一代瓶颈":"MRI restoration networks were typically trained per degradation or scanner, often smoothing tissue boundaries needed by downstream tools.","核心想法":"Pre-estimate anatomical tissue segmentation probabilities to explicitly guide a tissue-aware enhancement network across diverse degradations.","关键改进":"Couples anatomical tissue priors with unified motion correction, super-resolution, denoising, and multi-site scanner harmonization.","医学适配":"Serves as a universal structural brain MRI pre-processing and harmonization front-end improving downstream FreeSurfer/segmentation consistency.","适用范围与证据":"Representative restoration-oriented MRI foundation model; must be audited to ensure subtle focal lesions are not harmonized away."},"paper_title":"A Foundation Model for Enhancing Magnetic Resonance Images and Downstream Segmentation, Registration and Diagnostic Tasks","paper_url":"https://www.nature.com/articles/s41551-024-01283-7","code_label":"作者/机构官方实现","code_url":"https://github.com/DBC-Lab/Brain_MRI_Enhancement","has_code":true,"image":"assets/0ebae0bb01fd4bda5693.avif"},{"id":"architecture_model_110_prima","num":110,"num_str":"110","year":2026,"year_str":"2026","venue":"Nature Biomedical Engineering","venue_group":"nature","era_group":"era4","title":"Prima","family_id":"models_volumetric_foundations","family_code":"09","family_short":"CT/MRI 检查级模型","family_en":"Volumetric Study FMs","family_icon":"IX","family_label":"CT/MRI 检查级基础模型：输入单位从切片走向完整 study","archetype":"VQ-VAE 体积 token—sequence ViT—study ViT 的层级 MRI-report CLIP","archetype_en":"hierarchical_vqvae_study_vit_mri_clip","accent":"#6B5700","fig_badge":"Extended Data Figure 1(c) · PDF p.30","fig_href":"https://www.nature.com/articles/s41551-025-01608-0","core_mech":"Prima 的核心链路是 32×32×4 子体积 VQ-VAE token、sequence ViT、study ViT，再以神经放射报告做 CLIP 对齐。","core_mech_en":"Hierarchical clinical brain MRI study foundation model chaining 32×32×4 sub-volume VQ-VAE tokenization, a sequence-level ViT, and a study-level ViT aligned with radiology reports.","input_desc":"一个真实脑 MRI study 中的多序列 3D 体积、序列名称/描述与配对报告","input_en":"Complete clinical brain MRI study (multiple heterogeneous 3D sequences + sequence metadata) + paired neuroradiology report","output_desc":"完整检查级 embedding、零样本相似度及冻结特征上的 52 任务 MLP 预测","output_en":"Study-level multimodal embedding supporting zero-shot retrieval and 52 neurological diagnostic/triage MLP probes","form_title":"核心公式 · 从三维子体积到序列再到检查级的层级对齐","form_title_en":"Core Formalism · Three-Level Hierarchical Study Encoding (3D VQ-VAE → Sequence ViT → Study ViT) + Report CLIP","nodes":[{"name":"多序列 MRI study","desc":"一个检查包含不同序列、方向和数量的 3D volumes","name_en":"multi-sequence MRI study","desc_en":"Ingests complete clinical brain mri study (multiple heterogeneous 3d sequences + sequence metadata) + paired neuroradiology report and prepares initial tensor representations (multi-sequence MRI study)."},{"name":"3D VQ-VAE volume tokenizer","desc":"体积切为 32×32×4 子块，去背景并编码为离散/潜在 token；以方向置换增强不变性","name_en":"3D VQ-VAE volume tokenizer","desc_en":"Executes 3D VQ-VAE volume tokenizer to extract primary structural features and establish spatial/sequence encoding."},{"name":"序列名称 embedding","desc":"自由文本序列描述提示扫描平面与对比类型","name_en":"sequence embedding","desc_en":"Performs sequence embedding within the core hierarchical vqvae study vit mri clip computation pathway."},{"name":"Sequence ViT","desc":"融合一个 volume 的 token、位置编码和序列描述，输出 series register","name_en":"Sequence ViT","desc_en":"Performs Sequence ViT within the core hierarchical vqvae study vit mri clip computation pathway."},{"name":"Study ViT","desc":"汇聚所有 series registers，形成完整检查表示","name_en":"Study ViT","desc_en":"Performs Study ViT within the core hierarchical vqvae study vit mri clip computation pathway."},{"name":"神经放射学文本 encoder","desc":"编码经 LLM 摘要的阳性报告要点","name_en":"encoder","desc_en":"Performs encoder within the core hierarchical vqvae study vit mri clip computation pathway."},{"name":"MRI-report CLIP + patient discrimination","desc":"对齐 study 与报告并减少同患者/批采样带来的低效","name_en":"MRI-report CLIP + patient discrimination","desc_en":"Performs MRI-report CLIP + patient discrimination within the core hierarchical vqvae study vit mri clip computation pathway."},{"name":"Prima study embedding","desc":"用于零样本检索、解释与迁移","name_en":"Prima study embedding","desc_en":"Applies Prima study embedding to project aggregated representations toward the target task head."},{"name":"冻结特征 MLP probes","desc":"冻结 tokenizer 与两级 ViT 后训练诊断、优先级和转诊 heads","name_en":"feature MLP probes","desc_en":"Produces study-level multimodal embedding supporting zero-shot retrieval and 52 neurological diagnostic/triage mlp probes via feature MLP probes."}],"design_principles":["先用 VQ-VAE 把高分辨率 MRI volume 压成可处理的子体积 token。","Sequence ViT 建模单序列，Study ViT 再汇聚整个检查，保留真实 PACS 层级。","以报告摘要做 CLIP 对齐；下游冻结表示，只训练轻量 MLP probes。"],"design_principles_en":["Core Hypothesis: Tokenize 3D sub-volumes via VQ-VAE and aggregate variable multi-sequence studies through hierarchical sequence- and study-level Transformers aligned with reports.","Architectural Delta: Trained on >200,000 uncurated clinical MRI series (~30,000 studies) with LLM-summarized report alignment and health-system-wide evaluation.","Mathematical Formalism: Three-Level Hierarchical Study Encoding (3D VQ-VAE → Sequence ViT → Study ViT) + Report CLIP."],"med_apps":["模型输入单位是完整 study，可同时利用序列组合、方向和报告语义。","报告摘要和单卫生系统训练可能引入标签泄漏或流程偏差；优先级/转诊预测不等同于已改善临床结局。"],"med_apps_en":["Clinical Translation: Evaluated across 52 neuroimaging diagnoses, acuity triage, and specialist referral recommendations over a 1-year health-system cohort.","Evidence & Safety Boundary: Strong health-system-scale study-level evidence; predominantly validated within a single health system and retrospective workflow."],"attrs":{"上一代瓶颈":"研究队列规模有限且筛选偏差大，模型难覆盖真实临床异质性","核心想法":"以 VQ-VAE 把 MRI 体积离散化，再用 sequence ViT、study ViT 和 MRI-report CLIP 学习层级检查表征","关键改进":"以报告摘要对齐层级神经影像表示，冻结表示后训练 MLP probes","医学适配":"用于 52 种诊断、优先级与转诊建议等脑 MRI 任务","适用范围与证据":"有一年 health-system-wide 与外部评估；仍主要来自单一卫生系统，尚未证明工作流结局改善"},"attrs_en":{"上一代瓶颈":"Curated research MRI models fail on real-world hospital studies containing variable numbers of sequences, protocols, and artifacts.","核心想法":"Tokenize 3D sub-volumes via VQ-VAE and aggregate variable multi-sequence studies through hierarchical sequence- and study-level Transformers aligned with reports.","关键改进":"Trained on >200,000 uncurated clinical MRI series (~30,000 studies) with LLM-summarized report alignment and health-system-wide evaluation.","医学适配":"Evaluated across 52 neuroimaging diagnoses, acuity triage, and specialist referral recommendations over a 1-year health-system cohort.","适用范围与证据":"Strong health-system-scale study-level evidence; predominantly validated within a single health system and retrospective workflow."},"paper_title":"Learning Neuroimaging Models from Health System-Scale Data","paper_url":"https://www.nature.com/articles/s41551-025-01608-0","code_label":"作者/机构官方实现","code_url":"https://github.com/MLNeurosurg/Prima","has_code":true,"image":"assets/81270f82682ba756f280.avif"},{"id":"architecture_model_111_mars","num":111,"num_str":"111","year":2026,"year_str":"2026","venue":"Nature Biomedical Engineering","venue_group":"nature","era_group":"era4","title":"MARS","family_id":"models_volumetric_foundations","family_code":"09","family_short":"CT/MRI 检查级模型","family_en":"Volumetric Study FMs","family_icon":"IX","family_label":"CT/MRI 检查级基础模型：输入单位从切片走向完整 study","archetype":"3D Swin 的结构—序列解耦多目标 MRI 预训练","archetype_en":"anatomy_sequence_disentangled_3d_swin_fm","accent":"#6B5700","fig_badge":"Figure 6 · PDF p.17","fig_href":"https://www.nature.com/articles/s41551-026-01740-5","core_mech":"MARS 用 3D Swin 加结构/序列双支路、元数据与对比约束，并通过重建/合成把 anatomy-invariant 与 sequence-specific 信息解耦。","core_mech_en":"Multi-sequence 3D MRI foundation model pairing a 3D Swin backbone with dual structure/sequence branches and acquisition metadata to disentangle anatomy from contrast.","input_desc":"跨 10 个解剖区、多 MRI 序列的 3D volume 及其遮挡/跨序列变体","input_en":"Multi-sequence 3D MRI volumes across 10 anatomical regions with sequence metadata and cross-sequence masking","output_desc":"可迁移 3D Swin 表示，以及供分割、分类、配准、预测和报告任务使用的权重","output_en":"Disentangled anatomical and sequence representations transferable across 44 segmentation, classification, registration, and report tasks","form_title":"核心公式 · 结构—序列解耦及采集参数约束","form_title_en":"Core Formalism · Anatomy–Sequence Disentanglement Conditioned on MRI Acquisition Parameters","nodes":[{"name":"多器官多序列 MRI","desc":"336,476 个体积，覆盖不同序列和扫描协议","name_en":"organ multi-sequence MRI","desc_en":"Ingests multi-sequence 3d mri volumes across 10 anatomical regions with sequence metadata and cross-sequence masking and prepares initial tensor representations (organ multi-sequence MRI)."},{"name":"3D Swin Transformer","desc":"层级窗口注意力提取多尺度体积特征","name_en":"3D Swin Transformer","desc_en":"Executes 3D Swin Transformer to extract primary structural features and establish spatial/sequence encoding."},{"name":"Structure branch","desc":"1×1×1 卷积头分离 anatomy-invariant 结构特征","name_en":"Structure branch","desc_en":"Performs Structure branch within the core anatomy sequence disentangled 3d swin fm computation pathway."},{"name":"Sequence branch","desc":"独立头分离与对比度、扫描参数相关的 sequence-specific 特征","name_en":"Sequence branch","desc_en":"Performs Sequence branch within the core anatomy sequence disentangled 3d swin fm computation pathway."},{"name":"结构/序列对比 heads","desc":"分别约束同解剖跨序列一致性与序列差异","name_en":"sequence heads","desc_en":"Performs sequence heads within the core anatomy sequence disentangled 3d swin fm computation pathway."},{"name":"部位与采集参数 heads","desc":"结构支路预测解剖部位；序列支路预测 TR、TE、flip angle 等元数据","name_en":"heads","desc_en":"Performs heads within the core anatomy sequence disentangled 3d swin fm computation pathway."},{"name":"3D reconstruction/synthesis decoder","desc":"从遮挡输入重建，并可通过噪声映射调制 sequence 特征做序列合成","name_en":"3D reconstruction/synthesis decoder","desc_en":"Performs 3D reconstruction/synthesis decoder within the core anatomy sequence disentangled 3d swin fm computation pathway."},{"name":"残差特征再融合","desc":"结构与序列支路拼接聚合回主 latent","name_en":"residual feature fusion","desc_en":"Applies residual feature fusion to project aggregated representations toward the target task head."},{"name":"多任务迁移","desc":"预训练 3D Swin 接分割、分类、TransMorph 配准或报告生成适配器","name_en":"multi-task","desc_en":"Produces disentangled anatomical and sequence representations transferable across 44 segmentation, classification, registration, and report tasks via multi-task."}],"design_principles":["3D Swin 共享主干，但显式拆出解剖结构与 MRI 序列变化两类 latent。","结构/序列对比和部位/采集参数预测让两个支路承担不同信息。","遮挡重建与受 sequence latent 调制的合成任务补充体素级生成约束。"],"design_principles_en":["Core Hypothesis: Explicitly factorize 3D MRI representations into an anatomy-invariant structural branch and a sequence-specific contrast branch guided by acquisition metadata.","Architectural Delta: Pretrained on ~160,000 3D MRI scans via cross-sequence synthesis, masked reconstruction, and contrastive disentanglement.","Mathematical Formalism: Anatomy–Sequence Disentanglement Conditioned on MRI Acquisition Parameters."],"med_apps":["同一预训练权重可接分割、分类、配准、进展预测与报告生成适配器。","44 项结果来自异质任务和不同 heads，不能把总体胜出直接解释为单一临床场景已前瞻验证。"],"med_apps_en":["Clinical Translation: Adapts across 44 diverse downstream MRI tasks spanning segmentation, diagnosis, deformable registration, progression, and reporting.","Evidence & Safety Boundary: Broad multi-task scope reported by authors; independent external replication under standardized baselines remains necessary."],"attrs":{"上一代瓶颈":"单序列、单器官预训练难处理临床 MRI 协议和对比度异质性","核心想法":"在大规模多序列 MRI 上解耦 anatomy-invariant 表征与 sequence-specific variation","关键改进":"以 sequence-disentangled pretraining 迁移到 44 个分割、分类、配准、进展预测和报告生成任务","医学适配":"适配多器官 MRI 分割、诊断、配准、进展预测与报告生成","适用范围与证据":"原作者在 44 个任务中报告 41 个第一；不等于独立或前瞻验证"},"attrs_en":{"上一代瓶颈":"Single-sequence or single-organ MRI models brittlely fail when clinical pulse sequences, TR/TE parameters, or contrasts vary.","核心想法":"Explicitly factorize 3D MRI representations into an anatomy-invariant structural branch and a sequence-specific contrast branch guided by acquisition metadata.","关键改进":"Pretrained on ~160,000 3D MRI scans via cross-sequence synthesis, masked reconstruction, and contrastive disentanglement.","医学适配":"Adapts across 44 diverse downstream MRI tasks spanning segmentation, diagnosis, deformable registration, progression, and reporting.","适用范围与证据":"Broad multi-task scope reported by authors; independent external replication under standardized baselines remains necessary."},"paper_title":"Large-Scale Multi-Sequence Pretraining for Generalizable MRI Analysis in Versatile Clinical Applications","paper_url":"https://www.nature.com/articles/s41551-026-01740-5","code_label":"作者/机构官方实现","code_url":"https://github.com/zqiuak/MARS","has_code":true,"image":"assets/31e0002f296196b8c8a1.avif"},{"id":"architecture_model_112_decipher_mr","num":112,"num_str":"112","year":2026,"year_str":"2026","venue":"npj Digital Medicine","venue_group":"journal","era_group":"era4","title":"Decipher-MR","family_id":"models_volumetric_foundations","family_code":"09","family_short":"CT/MRI 检查级模型","family_en":"Volumetric Study FMs","family_icon":"IX","family_label":"CT/MRI 检查级基础模型：输入单位从切片走向完整 study","archetype":"3D DINOv2/iBOT 视觉自监督加 PubMedBERT 报告对比对齐","archetype_en":"organ_aware_3d_vit_mri_report_clip","accent":"#6B5700","fig_badge":"Figure 1 with enlarged Figure 1(b) · PDF p.3","fig_href":"https://doi.org/10.1038/s41746-026-02596-4","core_mech":"Decipher-MR 明确采用 8³ patch 的 3D ViT-Base、DINOv2/iBOT 视觉预训练、PubMedBERT MLM，再做器官感知的 MRI-report CLIP 对齐。","core_mech_en":"3D MRI vision–language foundation model combining an 8³-patch 3D ViT-Base (pretrained via 3D DINOv2/iBOT) with PubMedBERT MLM and organ-aware MRI–report CLIP alignment.","input_desc":"单个 3D MRI series 与同 study 的器官级报告文本","input_en":"3D MRI series volume + paired study-level organ-parsed radiology report text","output_desc":"512 维共享 MRI—文本 embedding、冻结视觉特征及轻量下游 decoder 输出","output_en":"512-D shared 3D MRI–text embedding and frozen 3D visual features for lightweight downstream decoders","form_title":"核心公式 · 三维自蒸馏、体素块掩码与器官感知图文对齐","form_title_en":"Core Formalism · 3D Self-Distilled ViT + Organ-Aware Multi-Sequence MRI-to-Report Contrastive Alignment","nodes":[{"name":"3D MRI series","desc":"跨器官、序列和病理；预处理后形成可变尺寸体积","name_en":"3D MRI series","desc_en":"Ingests 3d mri series volume + paired study-level organ-parsed radiology report text and prepares initial tensor representations (3D MRI series)."},{"name":"8×8×8 volume patches","desc":"非重叠子体积线性投影；三线性位置插值支持不同尺寸","name_en":"8×8×8 volume patches","desc_en":"Executes 8×8×8 volume patches to extract primary structural features and establish spatial/sequence encoding."},{"name":"3D ViT-Base student","desc":"86M 参数、768 维视觉 encoder","name_en":"3D ViT-Base student","desc_en":"Performs 3D ViT-Base student within the core organ aware 3d vit mri report clip computation pathway."},{"name":"EMA teacher + iBOT","desc":"图像级多裁剪自蒸馏和遮挡 patch 预测联合预训练","name_en":"EMA teacher + iBOT","desc_en":"Performs EMA teacher + iBOT within the core organ aware 3d vit mri report clip computation pathway."},{"name":"器官级 MRI 报告","desc":"清洗后提取与当前器官相关的描述和结论","name_en":"organ MRI","desc_en":"Performs organ MRI within the core organ aware 3d vit mri report clip computation pathway."},{"name":"PubMedBERT text encoder","desc":"先在 MRI 报告上以 MLM 继续预训练","name_en":"PubMedBERT text encoder","desc_en":"Performs PubMedBERT text encoder within the core organ aware 3d vit mri report clip computation pathway."},{"name":"双线性投影到 512 维","desc":"视觉和文本 [CLS] 映射到共享空间","name_en":"projection 512","desc_en":"Performs projection 512 within the core organ aware 3d vit mri report clip computation pathway."},{"name":"Image-report contrastive stage","desc":"同 study series/report 为正，器官内采样硬负并避免同 study 假负","name_en":"Image-report contrastive stage","desc_en":"Applies Image-report contrastive stage to project aggregated representations toward the target task head."},{"name":"冻结 encoder + 轻量 decoder","desc":"分类、回归、检索、分割和定位任务","name_en":"encoder + decoder","desc_en":"Produces 512-d shared 3d mri–text embedding and frozen 3d visual features for lightweight downstream decoders via encoder + decoder."}],"design_principles":["Stage 1 独立预训练 3D 视觉 encoder 和医学文本 encoder。","视觉侧用 DINOv2 student—teacher 与 iBOT 遮挡 patch 学全局和局部表示。","Stage 2 将 3D ViT 与 PubMedBERT 投影到 512 维共享空间，按器官和 study 规则做图文对比。"],"design_principles_en":["Core Hypothesis: Pretrain a 3D ViT via self-distillation on ~200,000 MRI series, then align series embeddings with organ-parsed radiology report segments.","Architectural Delta: Native 8×8×8 3D patch ViT + 3D DINOv2/iBOT visual SSL + organ-gated cross-modal contrastive learning.","Mathematical Formalism: 3D Self-Distilled ViT + Organ-Aware Multi-Sequence MRI-to-Report Contrastive Alignment."],"med_apps":["原生 3D token 与报告弱监督共同支持 MRI 检索、分类、分割和异常定位。","报告是 study 级而 series 是局部输入，配对噪声和文本泄漏必须通过同 study 采样、外部集与无文本消融检验。"],"med_apps_en":["Clinical Translation: Supports zero-shot 3D MRI retrieval, disease classification, and label-efficient segmentation/grading across organs.","Evidence & Safety Boundary: Recent 3D MRI VLM preprint; pretraining weights/code are not fully public, requiring independent verification."],"attrs":{"上一代瓶颈":"3D MRI 标签稀缺且传统视觉预训练难吸收放射学语义","核心想法":"先以 DINOv2 式视觉自监督学习 3D MRI 表示，再做 report-guided contrastive alignment","关键改进":"在约 200000 个 MRI series、22000 余个 studies 上连接体积级视觉 token、多序列 MRI 与临床文本","医学适配":"用于 3D MRI 检索、分类和跨任务迁移","适用范围与证据":"新近 3D 医学 VLM；数据覆盖、文本泄漏和独立复现仍需检验，专属预训练代码/权重未开放"},"attrs_en":{"上一代瓶颈":"3D MRI lacks massive manual labels, while naive global report alignment ignores which series or organ corresponds to which report sentence.","核心想法":"Pretrain a 3D ViT via self-distillation on ~200,000 MRI series, then align series embeddings with organ-parsed radiology report segments.","关键改进":"Native 8×8×8 3D patch ViT + 3D DINOv2/iBOT visual SSL + organ-gated cross-modal contrastive learning.","医学适配":"Supports zero-shot 3D MRI retrieval, disease classification, and label-efficient segmentation/grading across organs.","适用范围与证据":"Recent 3D MRI VLM preprint; pretraining weights/code are not fully public, requiring independent verification."},"paper_title":"Decipher-MR: A Vision-Language Foundation Model for 3D MRI Representations","paper_url":"https://doi.org/10.1038/s41746-026-02596-4","code_label":"未提供官方实现","code_url":"","has_code":false,"image":"assets/c7b265173c410d30f8b4.avif"},{"id":"architecture_model_113_noise2void","num":113,"num_str":"113","year":2019,"year_str":"2019","venue":"CVPR","venue_group":"cv","era_group":"era2","title":"Noise2Void","family_id":"models_denoising_restoration","family_code":"12","family_short":"去噪与图像恢复","family_en":"Denoising & Restoration","family_icon":"XII","family_label":"去噪与图像恢复：残差、盲点与长程建模的假设边界","archetype":"单张噪声图像上的 blind-spot 自监督去噪","archetype_en":"single_image_blind_spot_denoising","accent":"#145E75","fig_badge":"Figures 2 and 3 · PDF pp.4 and 5","fig_href":"https://openaccess.thecvf.com/content_CVPR_2019/html/Krull_Noise2Void_-_Learning_Denoising_From_Single_Noisy_Images_CVPR_2019_paper.html","core_mech":"Noise2Void 通过输入操纵构造 blind spot，只从单张 noisy 图像回归其被隐藏中心，而非需要成对噪声或 clean target。","core_mech_en":"Implements practical single-image blind-spot denoising by randomly masking center pixels via neighborhood replacement so a standard U-Net predicts held-out pixels.","input_desc":"一张噪声图像；训练时随机选取中心像素并用邻域值替换","input_en":"Single noisy image (with random center pixels replaced by neighboring values during training)","output_desc":"每个像素的条件期望估计形成的去噪图像","output_en":"Denoised image estimate x̂ from a single forward pass","form_title":"核心公式 · 盲点条件独立假设下的单图自监督去噪","form_title_en":"Core Formalism · Blind-Spot Center-Pixel Replacement Training Under Pixel-Wise Conditional Independence","nodes":[{"name":"单张 noisy image","desc":"不需要 clean target 或重复采集","name_en":"noisy image","desc_en":"Ingests single noisy image (with random center pixels replaced by neighboring values during training) and prepares initial tensor representations (noisy image)."},{"name":"随机像素采样","desc":"选择少量中心像素作为本轮监督位置","name_en":"pixel sampling","desc_en":"Executes pixel sampling to extract primary structural features and establish spatial/sequence encoding."},{"name":"Blind-spot manipulation","desc":"把中心值替换为邻域随机值，使网络不能复制目标像素","name_en":"Blind-spot manipulation","desc_en":"Performs Blind-spot manipulation within the core single image blind spot denoising computation pathway."},{"name":"CNN/U-Net denoiser","desc":"仅从周围空间上下文预测被替换中心","name_en":"CNN/U-Net denoiser","desc_en":"Performs CNN/U-Net denoiser within the core single image blind spot denoising computation pathway."},{"name":"采样位置回归损失","desc":"输出与原 noisy 中心值比较，未采样像素不计损失","name_en":"sampling loss","desc_en":"Performs sampling loss within the core single image blind spot denoising computation pathway."},{"name":"全图普通前向","desc":"推理时不再替换像素，网络一次输出所有位置","name_en":"Stage 06","desc_en":"Applies Stage 06 to project aggregated representations toward the target task head."},{"name":"去噪图像","desc":"估计由邻域条件决定的 clean signal","name_en":"Denoised Image","desc_en":"Produces denoised image estimate x̂ from a single forward pass via Denoised Image."}],"design_principles":["训练时遮断中心像素自身到输出的捷径，只允许网络利用邻域。","若噪声在给定信号下零均值且像素间条件独立，预测 noisy 中心的期望等于 clean 信号。","稀疏采样位置计算损失，使一张图像自身即可同时提供输入和目标。"],"design_principles_en":["Core Hypothesis: Create a receptive-field blind spot via a simple input masking scheme (replacing target pixels with a random neighbor) so gradients flow only through surrounding context.","Architectural Delta: Efficient multi-pixel blind-spot training recipe applicable to any standard U-Net without paired or clean training data.","Mathematical Formalism: Blind-Spot Center-Pixel Replacement Training Under Pixel-Wise Conditional Independence."],"med_apps":["适用于显微、低剂量和难以重复采集 clean/noisy pair 的场景。","空间相关噪声、结构化条纹、重建伪影或邻域内不独立的 MRI 噪声会破坏核心假设。"],"med_apps_en":["Clinical Translation: Widely used in biomedical microscopy, OCT speckle reduction, and single-acquisition low-dose imaging.","Evidence & Safety Boundary: Classic self-supervised denoiser; structured/correlated noise violates pixel-wise independence and gets preserved as signal."],"attrs":{"上一代瓶颈":"监督去噪需要干净目标，Noise2Noise 仍需独立噪声配对","核心想法":"通过 blind-spot 预测遮挡中心像素，仅用单张噪声图像训练去噪网络","关键改进":"利用条件独立、零均值噪声假设从同一图像构造自监督目标","医学适配":"用于显微、低剂量和无法重复采集的医学图像去噪","适用范围与证据":"自监督去噪经典方法；结构化噪声和相关噪声会违反假设"},"attrs_en":{"上一代瓶颈":"Exact J-invariant mask-by-mask forward passes were computationally slow, while supervised denoising required unavailable clean targets.","核心想法":"Create a receptive-field blind spot via a simple input masking scheme (replacing target pixels with a random neighbor) so gradients flow only through surrounding context.","关键改进":"Efficient multi-pixel blind-spot training recipe applicable to any standard U-Net without paired or clean training data.","医学适配":"Widely used in biomedical microscopy, OCT speckle reduction, and single-acquisition low-dose imaging.","适用范围与证据":"Classic self-supervised denoiser; structured/correlated noise violates pixel-wise independence and gets preserved as signal."},"paper_title":"Noise2Void - Learning Denoising From Single Noisy Images","paper_url":"https://openaccess.thecvf.com/content_CVPR_2019/html/Krull_Noise2Void_-_Learning_Denoising_From_Single_Noisy_Images_CVPR_2019_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/juglab/n2v","has_code":true,"image":"assets/3fa94f715753558b0311.avif"},{"id":"architecture_model_114_red_net","num":114,"num_str":"114","year":2016,"year_str":"2016","venue":"NeurIPS","venue_group":"ml","era_group":"era2","title":"RED-Net","family_id":"models_denoising_restoration","family_code":"12","family_short":"去噪与图像恢复","family_en":"Denoising & Restoration","family_icon":"XII","family_label":"去噪与图像恢复：残差、盲点与长程建模的假设边界","archetype":"对称卷积—反卷积深层图像恢复网络","archetype_en":"symmetric_conv_deconv_residual_autoencoder","accent":"#145E75","fig_badge":"Figures 1 and 2 · PDF pp.3 and 4","fig_href":"https://papers.nips.cc/paper_files/paper/2016/hash/0ed9422357395a0d4879191c66f4faa2-Abstract.html","core_mech":"相较普通 autoencoder，RED-Net 在每个镜像卷积—反卷积层之间建立对称加法 skip，而不只保留少数 U-Net 尺度跳连。","core_mech_en":"Deep symmetric convolutional–deconvolutional autoencoder connected by layer-by-layer additive residual skip connections at every mirrored depth.","input_desc":"含噪、压缩或受退化影响的图像","input_en":"Noisy, blurry, or low-dose degraded image","output_desc":"恢复后的高质量图像或残差校正图","output_en":"Restored clean image recovered via multi-depth additive residual shortcuts","form_title":"核心公式 · 对称卷积—反卷积与跨层残差重建","form_title_en":"Core Formalism · Symmetric Mirrored Convolution–Deconvolution Autoencoder with Dense Additive Skips","nodes":[{"name":"退化图像","desc":"去噪、去块或超分等恢复输入","name_en":"Stage 01","desc_en":"Ingests noisy, blurry, or low-dose degraded image and prepares initial tensor representations (Stage 01)."},{"name":"深卷积 encoder","desc":"连续卷积与 ReLU 扩大感受野并压缩局部信息","name_en":"convolution encoder","desc_en":"Executes convolution encoder to extract primary structural features and establish spatial/sequence encoding."},{"name":"深层语义特征","desc":"包含退化上下文但细节传递路径较长","name_en":"feature","desc_en":"Performs feature within the core symmetric conv deconv residual autoencoder computation pathway."},{"name":"镜像反卷积 decoder","desc":"逐层重建空间分辨率与图像结构","name_en":"transposed convolution decoder","desc_en":"Performs transposed convolution decoder within the core symmetric conv deconv residual autoencoder computation pathway."},{"name":"对称 skip additions","desc":"encoder 第 i 层直接加到镜像 decoder 层，传递边缘并改善梯度","name_en":"symmetric skip additions","desc_en":"Performs symmetric skip additions within the core symmetric conv deconv residual autoencoder computation pathway."},{"name":"重建层","desc":"融合深层上下文和浅层高频特征","name_en":"reconstruction","desc_en":"Applies reconstruction to project aggregated representations toward the target task head."},{"name":"恢复图像","desc":"以像素级监督训练的最终输出","name_en":"Stage 07","desc_en":"Produces restored clean image recovered via multi-depth additive residual shortcuts via Stage 07."}],"design_principles":["encoder 用深卷积获取大感受野，decoder 用反卷积恢复图像。","同尺度对称 skip 以加法传递高频细节并缩短反向传播路径。","网络直接学习退化到 clean 的端到端映射，可按任务调整深度与输出残差。"],"design_principles_en":["Core Hypothesis: Pair every convolutional encoding layer with a mirrored deconvolutional decoding layer linked by an element-wise additive residual skip.","Architectural Delta: Preserves full spatial resolution options and shortens backpropagation paths across 10–30+ layer restoration autoencoders.","Mathematical Formalism: Symmetric Mirrored Convolution–Deconvolution Autoencoder with Dense Additive Skips."],"med_apps":["为低剂量 CT、MRI 去噪与残差式重建提供经典深层 encoder-decoder 模板。","它不显式调用成像 forward operator，像素看似清晰仍可能与原始测量不一致。"],"med_apps_en":["Clinical Translation: Popularized residual encoder–decoder (RED-CNN) architectures as a primary baseline for low-dose CT image-domain denoising.","Evidence & Safety Boundary: Historically influential in low-dose CT denoising; purely image-domain L2 training can still over-smooth low-contrast liver lesions."],"attrs":{"上一代瓶颈":"早期浅层去噪/超分模型感受野有限，深层编解码器易丢局部信息","核心想法":"深卷积 encoder-decoder 通过对称 skip 连接重建高频图像细节","关键改进":"把卷积与反卷积层镜像连接，改善梯度和细节传递","医学适配":"启发 CT/MRI 去噪、低剂量恢复和残差式重建网络","适用范围与证据":"历史恢复基线；缺显式成像物理与现代注意力建模"},"attrs_en":{"上一代瓶颈":"Deep convolutional autoencoders lost fine spatial details through bottleneck compression and suffered from vanishing gradients.","核心想法":"Pair every convolutional encoding layer with a mirrored deconvolutional decoding layer linked by an element-wise additive residual skip.","关键改进":"Preserves full spatial resolution options and shortens backpropagation paths across 10–30+ layer restoration autoencoders.","医学适配":"Popularized residual encoder–decoder (RED-CNN) architectures as a primary baseline for low-dose CT image-domain denoising.","适用范围与证据":"Historically influential in low-dose CT denoising; purely image-domain L2 training can still over-smooth low-contrast liver lesions."},"paper_title":"Image Restoration Using Very Deep Convolutional Encoder-Decoder Networks with Symmetric Skip Connections","paper_url":"https://papers.nips.cc/paper_files/paper/2016/hash/0ed9422357395a0d4879191c66f4faa2-Abstract.html","code_label":"未提供官方实现","code_url":"","has_code":false,"image":"assets/1936be72753e83a3d3a9.avif"},{"id":"architecture_model_115_swinir","num":115,"num_str":"115","year":2021,"year_str":"2021","venue":"ICCV Workshops","venue_group":"cv","era_group":"era3","title":"SwinIR","family_id":"models_denoising_restoration","family_code":"12","family_short":"去噪与图像恢复","family_en":"Denoising & Restoration","family_icon":"XII","family_label":"去噪与图像恢复：残差、盲点与长程建模的假设边界","archetype":"浅层卷积—残差 Swin Transformer—任务重建头","archetype_en":"residual_swin_transformer_restoration","accent":"#145E75","fig_badge":"Figure 2 · PDF p.3","fig_href":"https://openaccess.thecvf.com/content/ICCV2021W/AIM/html/Liang_SwinIR_Image_Restoration_Using_Swin_Transformer_ICCVW_2021_paper.html","core_mech":"SwinIR 把多个带卷积残差的 RSTB 置于浅层卷积和任务重建头之间，以移窗注意力服务高分辨率恢复。","core_mech_en":"Sandwiches multiple Residual Swin Transformer Blocks (RSTBs, each ending in a 3×3 convolutional residual) between a shallow CNN extractor and a reconstruction head.","input_desc":"低分辨率、含噪或受压缩伪影影响的图像","input_en":"Low-resolution, noisy, or artifact-corrupted image","output_desc":"超分、去噪或 JPEG artifact reduction 后的图像","output_en":"Super-resolved, denoised, or artifact-restored high-resolution image","form_title":"核心公式 · 残差 Swin Transformer 块的深浅特征融合","form_title_en":"Core Formalism · Residual Swin Transformer Block (RSTB) Combining Shifted-Window Attention & Conv Inductive Bias","nodes":[{"name":"退化图像","desc":"任务不同但共享主干接口","name_en":"Stage 01","desc_en":"Ingests low-resolution, noisy, or artifact-corrupted image and prepares initial tensor representations (Stage 01)."},{"name":"Shallow Conv","desc":"提取低频基础特征并建立长残差支路","name_en":"Shallow Conv","desc_en":"Executes Shallow Conv to extract primary structural features and establish spatial/sequence encoding."},{"name":"Residual Swin Transformer Blocks","desc":"每个 RSTB 含多层 shifted-window attention、MLP 与块内卷积残差","name_en":"Residual Swin Transformer Blocks","desc_en":"Performs Residual Swin Transformer Blocks within the core residual swin transformer restoration computation pathway."},{"name":"Window/shifted-window attention","desc":"窗口内建模，交替移窗让相邻窗口通信","name_en":"Window/shifted-window attention","desc_en":"Performs Window/shifted-window attention within the core residual swin transformer restoration computation pathway."},{"name":"Deep feature fusion","desc":"多个 RSTB 后卷积并与浅层特征相加","name_en":"Deep feature fusion","desc_en":"Performs Deep feature fusion within the core residual swin transformer restoration computation pathway."},{"name":"任务特定重建 head","desc":"超分用 pixel-shuffle/上采样；去噪与去伪影用卷积输出","name_en":"reconstruction head","desc_en":"Applies reconstruction head to project aggregated representations toward the target task head."},{"name":"恢复图像","desc":"与输入同尺寸或按设定倍率放大","name_en":"Stage 07","desc_en":"Produces super-resolved, denoised, or artifact-restored high-resolution image via Stage 07."}],"design_principles":["浅层卷积保留低频基底，深层 Transformer 只需学习复杂残差。","shifted-window attention 以局部窗口成本获得跨窗口非局部建模。","统一 RSTB 主干，按超分、去噪或去伪影切换重建 head。"],"design_principles_en":["Core Hypothesis: Combine local shifted-window self-attention (for content-adaptive long-range self-similarity) with residual convolutional layers for translational stability.","Architectural Delta: Shallow feature CNN + deep RSTB cascade + long global skip connection achieving state-of-the-art PSNR across restoration benchmarks.","Mathematical Formalism: Residual Swin Transformer Block (RSTB) Combining Shifted-Window Attention & Conv Inductive Bias."],"med_apps":["适合高分辨率病理、低剂量 CT、MRI 和显微图像恢复迁移。","自然图像感知指标提升不保证 HU、ADC 或病灶边界保真，需配测量一致性和下游任务评价。"],"med_apps_en":["Clinical Translation: Widely adopted backbone for MRI super-resolution, low-dose CT/PET denoising, and microscopy image restoration.","Evidence & Safety Boundary: Strong modern restoration backbone; remains an image-space mapping unless embedded inside an unrolled physics data-consistency loop."],"attrs":{"上一代瓶颈":"CNN 恢复网络局部感受野限制长程依赖，全局 attention 成本过高","核心想法":"以浅层卷积、深层残差 Swin blocks 和重建 head 统一多类图像恢复","关键改进":"用 shifted-window attention 在高分辨率下高效建模非局部结构","医学适配":"常用于低剂量 CT、MRI、显微图像去噪与超分辨率迁移","适用范围与证据":"强恢复 backbone；未显式保证数据一致性或病灶保真"},"attrs_en":{"上一代瓶颈":"Pure CNN restoration networks had content-independent local kernels, while naive ViTs lost fine pixel boundaries and translation equivariance.","核心想法":"Combine local shifted-window self-attention (for content-adaptive long-range self-similarity) with residual convolutional layers for translational stability.","关键改进":"Shallow feature CNN + deep RSTB cascade + long global skip connection achieving state-of-the-art PSNR across restoration benchmarks.","医学适配":"Widely adopted backbone for MRI super-resolution, low-dose CT/PET denoising, and microscopy image restoration.","适用范围与证据":"Strong modern restoration backbone; remains an image-space mapping unless embedded inside an unrolled physics data-consistency loop."},"paper_title":"SwinIR: Image Restoration Using Swin Transformer","paper_url":"https://openaccess.thecvf.com/content/ICCV2021W/AIM/html/Liang_SwinIR_Image_Restoration_Using_Swin_Transformer_ICCVW_2021_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/JingyunLiang/SwinIR","has_code":true,"image":"assets/724befd52855cf81a64e.avif"},{"id":"architecture_model_116_restormer","num":116,"num_str":"116","year":2022,"year_str":"2022","venue":"CVPR","venue_group":"cv","era_group":"era3","title":"Restormer","family_id":"models_denoising_restoration","family_code":"12","family_short":"去噪与图像恢复","family_en":"Denoising & Restoration","family_icon":"XII","family_label":"去噪与图像恢复：残差、盲点与长程建模的假设边界","archetype":"层级 encoder-decoder 中的通道转置注意力与门控深度卷积 FFN","archetype_en":"channel_transposed_attention_restormer","accent":"#145E75","fig_badge":"Figure 2 · PDF p.3","fig_href":"https://openaccess.thecvf.com/content/CVPR2022/html/Zamir_Restormer_Efficient_Transformer_for_High-Resolution_Image_Restoration_CVPR_2022_paper.html","core_mech":"Restormer 用 MDTA 在通道维做转置注意力，并以 GDFN 门控深度卷积替代普通 Transformer FFN。","core_mech_en":"Replaces spatial N×N self-attention with Multi-Dconv Head Transposed Attention (MDTA) across channels (C×C) paired with a Gated-Dconv Feed-Forward Network (GDFN).","input_desc":"高分辨率受退化图像","input_en":"High-resolution degraded image","output_desc":"去噪、去雨、去模糊等恢复图像","output_en":"Restored high-resolution image","form_title":"核心公式 · 跨通道转置注意力的高分辨率恢复","form_title_en":"Core Formalism · Linear-Complexity Channel-Wise Transposed Attention (MDTA) + Gated Depthwise FFN (GDFN)","nodes":[{"name":"退化高分辨率图像","desc":"保持原空间网格输入","name_en":"Stage 01","desc_en":"Ingests high-resolution degraded image and prepares initial tensor representations (Stage 01)."},{"name":"Overlapped patch embedding","desc":"3×3 卷积生成重叠局部 token，不做硬切块","name_en":"Overlapped patch embedding","desc_en":"Executes Overlapped patch embedding to extract primary structural features and establish spatial/sequence encoding."},{"name":"四级层级 encoder","desc":"逐级降采样、增加通道并积累多尺度上下文","name_en":"hierarchical encoder","desc_en":"Performs hierarchical encoder within the core channel transposed attention restormer computation pathway."},{"name":"MDTA","desc":"Multi-Dconv Head Transposed Attention 在通道维计算注意力，Q/K/V 前含 depthwise conv","name_en":"MDTA","desc_en":"Performs MDTA within the core channel transposed attention restormer computation pathway."},{"name":"GDFN","desc":"门控 depthwise-conv 前馈网络同时建模局部结构和通道选择","name_en":"GDFN","desc_en":"Performs GDFN within the core channel transposed attention restormer computation pathway."},{"name":"对称多尺度 decoder","desc":"逐级上采样并融合 encoder 同尺度 skip","name_en":"symmetric multi-scale decoder","desc_en":"Performs symmetric multi-scale decoder within the core channel transposed attention restormer computation pathway."},{"name":"高分辨率 refinement blocks","desc":"输出前继续在原尺度细化纹理","name_en":"refinement blocks","desc_en":"Applies refinement blocks to project aggregated representations toward the target task head."},{"name":"残差恢复输出","desc":"预测残差与输入相加得到 clean 图像","name_en":"residual output","desc_en":"Produces restored high-resolution image via residual output."}],"design_principles":["把注意力矩阵转到通道维，避免随像素数二次增长。","Q/K/V 与 FFN 都嵌入 depthwise 卷积，让全局通道交互保留局部空间归纳偏置。","层级 encoder-decoder、同尺度 skip 和原尺度 refinement 协同恢复细节。"],"design_principles_en":["Core Hypothesis: Compute cross-covariance attention across feature channels (C×C instead of HW×HW) after applying 3×3 depthwise convolutions for local spatial context.","Architectural Delta: O(HW · C²) linear spatial scaling via MDTA + element-wise gated depthwise convolutional FFN controlling fine detail propagation.","Mathematical Formalism: Linear-Complexity Channel-Wise Transposed Attention (MDTA) + Gated Depthwise FFN (GDFN)."],"med_apps":["对高分辨率病理、CT/MRI 去噪和运动伪影校正具有较好计算可扩展性。","MDTA 是通道统计而非物理数据一致性；定量医学重建仍需显式测量约束或残差验证。"],"med_apps_en":["Clinical Translation: Well-suited for high-resolution digital pathology restoration, whole-slice MRI motion correction, and low-dose CT denoising.","Evidence & Safety Boundary: Compute-efficient high-resolution Transformer restorer; must be audited for quantitative intensity preservation."],"attrs":{"上一代瓶颈":"标准自注意力对像素数呈二次复杂度，难处理大图","核心想法":"用通道维 transposed attention 和门控深度卷积前馈网络恢复高分辨率图像","关键改进":"在线性空间复杂度下兼顾全局通道交互与局部空间建模","医学适配":"适合高分辨率病理、CT/MRI 去噪和运动伪影校正","适用范围与证据":"高效 restoration 基线；医学成像算子和不确定性仍需额外约束"},"attrs_en":{"上一代瓶颈":"Even windowed spatial self-attention restricted receptive fields or incurred heavy memory overhead on megapixel medical scans.","核心想法":"Compute cross-covariance attention across feature channels (C×C instead of HW×HW) after applying 3×3 depthwise convolutions for local spatial context.","关键改进":"O(HW · C²) linear spatial scaling via MDTA + element-wise gated depthwise convolutional FFN controlling fine detail propagation.","医学适配":"Well-suited for high-resolution digital pathology restoration, whole-slice MRI motion correction, and low-dose CT denoising.","适用范围与证据":"Compute-efficient high-resolution Transformer restorer; must be audited for quantitative intensity preservation."},"paper_title":"Restormer: Efficient Transformer for High-Resolution Image Restoration","paper_url":"https://openaccess.thecvf.com/content/CVPR2022/html/Zamir_Restormer_Efficient_Transformer_for_High-Resolution_Image_Restoration_CVPR_2022_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/swz30/Restormer","has_code":true,"image":"assets/6045910651ee06368b1d.avif"},{"id":"architecture_model_117_automap","num":117,"num_str":"117","year":2018,"year_str":"2018","venue":"Nature","venue_group":"nature","era_group":"era2","title":"AUTOMAP","family_id":"models_inverse_reconstruction","family_code":"11","family_short":"物理约束医学重建","family_en":"Physics-Informed Recon","family_icon":"XI","family_label":"物理约束重建：从后处理到展开优化与测量一致性","archetype":"测量域到图像域的全连接流形域变换","archetype_en":"fully_connected_sensor_domain_manifold","accent":"#145E75","fig_badge":"Figure 1 · PDF p.15","fig_href":"https://www.nature.com/articles/nature25988","core_mech":"AUTOMAP 的标志是大规模全连接层直接承担 domain transform，而非先做 FBP/IFFT 再用 CNN 后处理。","core_mech_en":"Learns the sensor-to-image domain transform directly via large fully connected layers mapping flattened raw measurements to an image grid followed by sparse convolutional refinement.","input_desc":"MRI k-space、CT 投影等序列化测量向量","input_en":"Flattened raw sensor measurement vector (e.g., k-space samples or Radon projections)","output_desc":"重建图像","output_en":"Reconstructed spatial-domain image","form_title":"核心公式 · 从传感域到图像域的端到端逆映射","form_title_en":"Core Formalism · Fully Connected Sensor-to-Image Domain Transform Manifold Learning","nodes":[{"name":"测量域向量 y","desc":"复数 k-space 或投影数据按实数通道展开","name_en":"measurement domain vector y","desc_en":"Ingests flattened raw sensor measurement vector (e.g., k-space samples or radon projections) and prepares initial tensor representations (measurement domain vector y)."},{"name":"全连接 domain transform 1","desc":"从测量坐标学习到高维隐空间的稠密映射","name_en":"fully connected domain transform 1","desc_en":"Executes fully connected domain transform 1 to extract primary structural features and establish spatial/sequence encoding."},{"name":"全连接 domain transform 2","desc":"继续逼近傅里叶/投影逆变换对应的流形映射","name_en":"fully connected domain transform 2","desc_en":"Performs fully connected domain transform 2 within the core fully connected sensor domain manifold computation pathway."},{"name":"二维重排","desc":"将稠密隐向量恢复为图像网格","name_en":"2D","desc_en":"Performs 2D within the core fully connected sensor domain manifold computation pathway."},{"name":"卷积细化层","desc":"在图像域去除残余伪影并利用局部结构","name_en":"convolution","desc_en":"Performs convolution within the core fully connected sensor domain manifold computation pathway."},{"name":"端到端图像监督","desc":"测量输入与目标图像直接成对训练","name_en":"Stage 06","desc_en":"Applies Stage 06 to project aggregated representations toward the target task head."},{"name":"重建图像","desc":"网络一次前向产生结果","name_en":"Reconstructed Image","desc_en":"Produces reconstructed spatial-domain image via Reconstructed Image."}],"design_principles":["不显式编码解析逆变换，而以稠密层学习测量坐标到图像坐标的全局映射。","域变换后用卷积利用自然/医学图像的局部结构进行细化。","通过端到端配对监督把成像逆问题写成单一可微网络。"],"design_principles_en":["Core Hypothesis: Frame tomographic reconstruction as a data-driven manifold mapping between sensor and image domains parameterized by dense fully connected layers.","Architectural Delta: Unified end-to-end neural domain transformation across arbitrary k-space trajectories and projection geometries on small grids.","Mathematical Formalism: Fully Connected Sensor-to-Image Domain Transform Manifold Learning."],"med_apps":["历史上证明 MRI、CT 等测量域到图像域可直接学习，推动 learned reconstruction。","全连接层参数随测量和图像尺寸急剧增长，且扫描几何改变后难复用；没有显式数据一致性保证。"],"med_apps_en":["Clinical Translation: Historically provocative demonstration of learned sensor-to-image inversion in low-resolution MRI and PET.","Evidence & Safety Boundary: Historical curiosity rather than a scalable baseline: O(N⁴) fully connected parameters cannot scale to clinical 512²/3D grids and discard known Fourier/Radon physics."],"attrs":{"上一代瓶颈":"传统重建需手工推导逆算子且难联合优化所有处理步骤","核心想法":"以全连接域变换层加卷积网络端到端学习测量域到图像域映射","关键改进":"首次展示跨 MRI、CT 等成像问题直接学习重建映射的统一思路","医学适配":"奠定端到端医学重建范式并推动 learned reconstruction","适用范围与证据":"历史里程碑；全连接层参数巨大、算子迁移和物理一致性较弱"},"attrs_en":{"上一代瓶颈":"Conventional pipelines treated Fourier/Radon inversion as fixed analytical steps separate from downstream denoising.","核心想法":"Frame tomographic reconstruction as a data-driven manifold mapping between sensor and image domains parameterized by dense fully connected layers.","关键改进":"Unified end-to-end neural domain transformation across arbitrary k-space trajectories and projection geometries on small grids.","医学适配":"Historically provocative demonstration of learned sensor-to-image inversion in low-resolution MRI and PET.","适用范围与证据":"Historical curiosity rather than a scalable baseline: O(N⁴) fully connected parameters cannot scale to clinical 512²/3D grids and discard known Fourier/Radon physics."},"paper_title":"Image Reconstruction by Domain-Transform Manifold Learning","paper_url":"https://www.nature.com/articles/nature25988","code_label":"作者/机构官方实现","code_url":"https://github.com/MattRosenLab/AUTOMAP","has_code":true,"image":"assets/2841a2f5cf19fa50e6d6.avif"},{"id":"architecture_model_118_learn","num":118,"num_str":"118","year":2018,"year_str":"2018","venue":"IEEE Transactions on Medical Imaging","venue_group":"journal","era_group":"era2","title":"LEARN","family_id":"models_inverse_reconstruction","family_code":"11","family_short":"物理约束医学重建","family_en":"Physics-Informed Recon","family_icon":"XI","family_label":"物理约束重建：从后处理到展开优化与测量一致性","archetype":"CT 数据保真梯度与迭代特异 CNN 正则梯度的展开网络","archetype_en":"unrolled_ct_gradient_expert_cascade","accent":"#145E75","fig_badge":"Figure 2 · PDF p.Official PMC Figure 2 full-size asset","fig_href":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6019143/","core_mech":"LEARN 每个展开阶段并行计算 CT 数据梯度和 learned experts CNN 正则梯度，再做残差更新。","core_mech_en":"Unrolls K iterative sparse-view CT reconstruction stages where each stage combines an explicit projection residual gradient A^T(Ax^t − y) with a stage-specific 3-layer CNN regularizer.","input_desc":"稀疏视角 CT 投影 y、系统矩阵 A/Aᵀ 和初始图像 x0","input_en":"Sparse-view CT sinogram y, system projection matrix A / backprojection A^T, and initial image x^0","output_desc":"固定阶段后的 CT 重建 xN","output_en":"Reconstructed CT image x^K after K≈50 unrolled expert stages","form_title":"核心公式 · 数据一致性与阶段特异 CNN 正则梯度的展开更新","form_title_en":"Core Formalism · Unrolled Iterative CT Gradient Descent with Stage-Specific Learned Expert Regularizers","nodes":[{"name":"稀疏投影 y","desc":"校准与对数变换后的 CT measurement","name_en":"projection y","desc_en":"Ingests sparse-view ct sinogram y, system projection matrix a / backprojection a^t, and initial image x^0 and prepares initial tensor representations (projection y)."},{"name":"A 与 Aᵀ","desc":"前向投影和反投影显式进入每一阶段","name_en":"A Aᵀ","desc_en":"Executes A Aᵀ to extract primary structural features and establish spatial/sequence encoding."},{"name":"初始重建 x0","desc":"可为零、FBP 或传统迭代结果","name_en":"reconstruction x0","desc_en":"Performs reconstruction x0 within the core unrolled ct gradient expert cascade computation pathway."},{"name":"数据保真梯度","desc":"每阶段计算 λt Aᵀ(Axt−y)","name_en":"Data Consistency Gradient","desc_en":"Performs Data Consistency Gradient within the core unrolled ct gradient expert cascade computation pathway."},{"name":"阶段特异 3-layer CNN","desc":"学习 fields-of-experts 正则梯度，卷积核与非线性随阶段变化","name_en":"3-layer CNN","desc_en":"Performs 3-layer CNN within the core unrolled ct gradient expert cascade computation pathway."},{"name":"残差迭代更新","desc":"当前图像减去数据梯度和 learned regularizer 得到下一阶段","name_en":"residual iterative update","desc_en":"Performs residual iterative update within the core unrolled ct gradient expert cascade computation pathway."},{"name":"端到端重建损失","desc":"投影输入与高质量 CT 成对监督所有展开参数","name_en":"reconstruction loss","desc_en":"Applies reconstruction loss to project aggregated representations toward the target task head."},{"name":"xN 重建","desc":"固定 N 个阶段后的最终 CT","name_en":"xN reconstruction","desc_en":"Produces reconstructed ct image x^k after k≈50 unrolled expert stages via xN reconstruction."}],"design_principles":["把 fields-of-experts 迭代固定展开为有限深度网络。","每阶段显式包含 Aᵀ(Ax−y)，保留 CT 系统矩阵的数据保真梯度。","正则梯度由阶段特异 CNN 学习，而非整条迭代共享一组固定先验参数。"],"design_principles_en":["Core Hypothesis: Unfold a fixed number of gradient descent steps on a variational CT objective, replacing hand-crafted regularizer gradients with stage-specific 3-layer CNNs.","Architectural Delta: Direct integration of CT projection/backprojection operators into an end-to-end trainable unrolled residual cascade.","Mathematical Formalism: Unrolled Iterative CT Gradient Descent with Stage-Specific Learned Expert Regularizers."],"med_apps":["是 sparse-view CT 中 model-based deep learning 与 algorithm unrolling 的早期代表。","若几何、标定或噪声与训练 A 不一致，显式算子也会把错误物理约束反复注入重建。"],"med_apps_en":["Clinical Translation: Early foundational milestone for model-based deep learning in sparse-view and low-dose CT reconstruction.","Evidence & Safety Boundary: Methodologically important unrolled CT baseline; fixed system matrices and stage-specific parameters require significant memory."],"attrs":{"上一代瓶颈":"FBP 后处理忽略投影域一致性，传统迭代正则设计耗时且手工","核心想法":"把 CT 数据保真梯度和学习到的正则梯度交替展开为固定阶段网络","关键改进":"显式嵌入系统矩阵并学习每阶段正则更新，实现端到端 sparse-view CT","医学适配":"是 CT model-based deep learning 和 unrolling 的早期代表","适用范围与证据":"仍具方法论价值；固定几何和训练分布限制跨扫描器泛化"},"attrs_en":{"上一代瓶颈":"Post-processing FBP ignored sinogram data consistency, while classical Fields-of-Experts required slow iterative convergence.","核心想法":"Unfold a fixed number of gradient descent steps on a variational CT objective, replacing hand-crafted regularizer gradients with stage-specific 3-layer CNNs.","关键改进":"Direct integration of CT projection/backprojection operators into an end-to-end trainable unrolled residual cascade.","医学适配":"Early foundational milestone for model-based deep learning in sparse-view and low-dose CT reconstruction.","适用范围与证据":"Methodologically important unrolled CT baseline; fixed system matrices and stage-specific parameters require significant memory."},"paper_title":"LEARN: Learned Experts' Assessment-Based Reconstruction Network for Sparse-Data CT","paper_url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6019143/","code_label":"未提供官方实现","code_url":"","has_code":false,"image":"assets/c5a98d44bf952c4506de.avif"},{"id":"architecture_model_119_ddnm","num":119,"num_str":"119","year":2023,"year_str":"2023","venue":"ICLR","venue_group":"ml","era_group":"era4","title":"DDNM","family_id":"models_generative","family_code":"10","family_short":"生成、扩散与流匹配","family_en":"Generative, Diffusion & Flow","family_icon":"X","family_label":"生成模型：从潜变量与对抗学习到 diffusion、flow 与 consistency","archetype":"扩散先验中的范围空间替换与零空间生成","archetype_en":"range_null_space_decomposed_diffusion","accent":"#6B5700","fig_badge":"Figure 2 · PDF p.5","fig_href":"https://arxiv.org/abs/2212.00490","core_mech":"DDNM 用 A†y 固定 range-space 信息，只让 diffusion denoiser 生成 null-space 分量。","core_mech_en":"Decomposes reverse diffusion intermediate estimates x̂_{0|t} via the Moore–Penrose pseudoinverse A† into a fixed measurement range-space component A†y and a generated null-space component (I − A†A)x̂_{0|t}.","input_desc":"线性退化测量 y=Ax+n、已知 A 及伪逆 A†、预训练无条件扩散模型","input_en":"Linear measurement y = Ax + n, known operator A with pseudoinverse A†, and a pretrained unconditional diffusion model","output_desc":"满足或近似满足测量约束的恢复图像样本","output_en":"Zero-shot restored image satisfying A x̂ = y while filling null-space details via the diffusion prior","form_title":"核心公式 · 扩散估计的范围空间替换与零空间保留","form_title_en":"Core Formalism · Range–Null Space Decomposition: x̄_{0|t} = A†y + (I − A†A)x̂_{0|t}","nodes":[{"name":"测量 y 与算子 A","desc":"超分、修复、去模糊、压缩感知等线性逆问题","name_en":"y A","desc_en":"Ingests linear measurement y = ax + n, known operator a with pseudoinverse a†, and a pretrained unconditional diffusion model and prepares initial tensor representations (y A)."},{"name":"扩散状态 xt","desc":"从高斯噪声开始的逆扩散变量","name_en":"xt","desc_en":"Executes xt to extract primary structural features and establish spatial/sequence encoding."},{"name":"预训练 diffusion denoiser","desc":"无任务再训练地从 xt 估计 clean x0|t","name_en":"pretraining diffusion denoiser","desc_en":"Performs pretraining diffusion denoiser within the core range null space decomposed diffusion computation pathway."},{"name":"A† 范围空间锚点","desc":"A†y 给出由测量确定的解分量","name_en":"A† range space","desc_en":"Performs A† range space within the core range null space decomposed diffusion computation pathway."},{"name":"零空间投影","desc":"(I−A†A)x0|t 保留生成先验只能在 null space 补充的分量","name_en":"null space projection","desc_en":"Performs null space projection within the core range null space decomposed diffusion computation pathway."},{"name":"x̂0|t 数据一致估计","desc":"A†y+(I−A†A)x0|t；含噪版按噪声方差调整","name_en":"x̂0|t","desc_en":"Performs x̂0|t within the core range null space decomposed diffusion computation pathway."},{"name":"DDPM 逆步更新","desc":"由校正的 clean estimate 采样下一时间步","name_en":"DDPM update","desc_en":"Applies DDPM update to project aggregated representations toward the target task head."},{"name":"零样本恢复结果","desc":"循环到 t=0 得到一个或多个可行样本","name_en":"zero-shot","desc_en":"Produces zero-shot restored image satisfying a x̂ = y while filling null-space details via the diffusion prior via zero-shot."}],"design_principles":["测量确定的范围空间分量由 A†y 直接替换。","扩散模型只负责填充 (I−A†A) 所描述的零空间自由度。","数据一致校正在每个逆扩散步插入，因此不需为每个退化算子重新训练网络。"],"design_principles_en":["Core Hypothesis: Directly replace the range-space component of each step's denoised estimate x̂_{0|t} with A†y, leaving the diffusion model to synthesize only the null-space component.","Architectural Delta: Backpropagation-free zero-shot linear inverse solver with a noise-aware extension (DDNM+) handling additive measurement noise.","Mathematical Formalism: Range–Null Space Decomposition: x̄_{0|t} = A†y + (I − A†A)x̂_{0|t}."],"med_apps":["可研究 MRI 欠采样、CT 缺失投影和去模糊等线性逆问题的零样本扩散先验。","医学算子往往含噪、非线性或无精确伪逆；预训练自然图像先验也可能在 null space 生成错误解剖。"],"med_apps_en":["Clinical Translation: Used in zero-shot MRI reconstruction, sparse CT restoration, super-resolution, and inpainting.","Evidence & Safety Boundary: Clean mathematical decomposition of range vs. null space; highlights directly that null-space anatomy is synthesized purely by the prior."],"attrs":{"上一代瓶颈":"通用扩散先验直接采样不满足观测，任务专用训练成本高","核心想法":"把扩散采样分解为满足线性测量的范围空间部分与可生成的零空间部分","关键改进":"利用伪逆投影在每步注入数据一致性，实现零样本多退化恢复","医学适配":"可用于 MRI、CT、去模糊和缺失数据的扩散逆问题研究","适用范围与证据":"零样本基线重要；依赖已知线性算子与准确噪声模型"},"attrs_en":{"上一代瓶颈":"Unconditional diffusion samples violate measurement constraints, whereas backpropagating likelihood gradients through U-Nets (DPS) is memory-heavy.","核心想法":"Directly replace the range-space component of each step's denoised estimate x̂_{0|t} with A†y, leaving the diffusion model to synthesize only the null-space component.","关键改进":"Backpropagation-free zero-shot linear inverse solver with a noise-aware extension (DDNM+) handling additive measurement noise.","医学适配":"Used in zero-shot MRI reconstruction, sparse CT restoration, super-resolution, and inpainting.","适用范围与证据":"Clean mathematical decomposition of range vs. null space; highlights directly that null-space anatomy is synthesized purely by the prior."},"paper_title":"Zero-Shot Image Restoration Using Denoising Diffusion Null-Space Model","paper_url":"https://arxiv.org/abs/2212.00490","code_label":"作者/机构官方实现","code_url":"https://github.com/wyhuai/DDNM","has_code":true,"image":"assets/409e066e8c7e455a51ed.avif"},{"id":"architecture_model_120_realnvp","num":120,"num_str":"120","year":2017,"year_str":"2017","venue":"ICLR","venue_group":"ml","era_group":"era2","title":"RealNVP","family_id":"models_generative","family_code":"10","family_short":"生成、扩散与流匹配","family_en":"Generative, Diffusion & Flow","family_icon":"X","family_label":"生成模型：从潜变量与对抗学习到 diffusion、flow 与 consistency","archetype":"仿射 coupling 与多尺度 split 的精确似然 normalizing flow","archetype_en":"affine_coupling_exact_likelihood_flow","accent":"#6B5700","fig_badge":"Figures 2 and 4 · PDF pp.4, 6","fig_href":"https://openreview.net/forum?id=HkpbnH9lx","core_mech":"RealNVP 以三角 Jacobian 的 affine coupling 获得同时精确可逆、可采样且可算 log-likelihood 的映射。","core_mech_en":"Constructs an exactly invertible normalizing flow using stacked affine coupling layers whose triangular Jacobians permit O(D) log-determinant and exact likelihood evaluation.","input_desc":"连续化图像 x","input_en":"Continuous-valued image or feature vector x","output_desc":"潜变量 z、精确 log-likelihood，或由 z 反演生成的图像","output_en":"Latent variable z = f(x), exact log-density log p_X(x), or exact inverse sample x = f^{-1}(z)","form_title":"核心公式 · 仿射耦合层的可逆变换与精确似然","form_title_en":"Core Formalism · Bijective Affine Coupling Layer & Change-of-Variables Exact Log-Likelihood","nodes":[{"name":"数据 x","desc":"训练样本经尺度变换/连续化后输入","name_en":"Stage 01","desc_en":"Ingests continuous-valued image or feature vector x and prepares initial tensor representations (Stage 01)."},{"name":"通道/棋盘划分","desc":"把变量拆成 xa 与 xb","name_en":"channel","desc_en":"Executes channel to extract primary structural features and establish spatial/sequence encoding."},{"name":"s,t conditioner","desc":"以 xa 经任意非可逆子网预测缩放和平移","name_en":"s,t conditioner","desc_en":"Performs s,t conditioner within the core affine coupling exact likelihood flow computation pathway."},{"name":"Affine coupling","desc":"ya=xa；yb=xb·exp(s(xa))+t(xa)，可显式求逆","name_en":"Affine coupling","desc_en":"Performs Affine coupling within the core affine coupling exact likelihood flow computation pathway."},{"name":"交替 mask/置换","desc":"让后续 coupling 更新此前未变换的变量","name_en":"mask","desc_en":"Performs mask within the core affine coupling exact likelihood flow computation pathway."},{"name":"Squeeze 与 multi-scale split","desc":"逐尺度分出部分 latent，降低后续计算","name_en":"Squeeze multi-scale split","desc_en":"Performs Squeeze multi-scale split within the core affine coupling exact likelihood flow computation pathway."},{"name":"三角 Jacobian log-det","desc":"log|det J| 为 s 的逐元素和，可精确计算似然","name_en":"Jacobian log-det","desc_en":"Applies Jacobian log-det to project aggregated representations toward the target task head."},{"name":"潜变量 z / 逆向样本","desc":"匹配简单先验并可沿逆 coupling 生成","name_en":"latent variable z","desc_en":"Produces latent variable z = f(x), exact log-density log p_x(x), or exact inverse sample x = f^{-1}(z) via latent variable z."}],"design_principles":["coupling 层只变换一半变量，使逆映射有闭式表达。","三角 Jacobian 将行列式化为缩放项之和，可做精确最大似然。","交替划分和多尺度 split 让所有维度逐步混合并控制计算。"],"design_principles_en":["Core Hypothesis: Split dimensions in each coupling layer so half remain unchanged while scaling and translating the other half via unconstrained neural networks s(·), t(·).","Architectural Delta: Triangular Jacobian with closed-form sum-of-logs determinant + exact single-pass forward density estimation and inverse sampling.","Mathematical Formalism: Bijective Affine Coupling Layer & Change-of-Variables Exact Log-Likelihood."],"med_apps":["可作为医学图像精确密度估计、生成和可逆重建先验的基础。","高 likelihood 不等同于病理异常检测可靠，flow 可能更敏感于低级纹理和扫描域而非疾病语义。"],"med_apps_en":["Clinical Translation: Applied to invertible medical image priors, exact-likelihood out-of-distribution detection, and bijective registration.","Evidence & Safety Boundary: Foundational normalizing flow; coupling layers require deep stacking for expressivity and raw pixel likelihoods often mis-score semantic OOD anomalies."],"attrs":{"上一代瓶颈":"一般生成网络缺精确似然，早期 flow 的可扩展性和可逆设计有限","核心想法":"用仿射 coupling layers 构造可逆网络并精确计算 log-determinant","关键改进":"通过三角 Jacobian 实现高效双向变换、采样与精确密度估计","医学适配":"用于医学图像生成、异常检测和可逆重建先验","适用范围与证据":"normalizing flow 基础；coupling 表达受限且高维似然未必对应临床异常"},"attrs_en":{"上一代瓶颈":"GANs and VAEs lacked exact tractable likelihood evaluation, while autoregressive density models were slow to sample.","核心想法":"Split dimensions in each coupling layer so half remain unchanged while scaling and translating the other half via unconstrained neural networks s(·), t(·).","关键改进":"Triangular Jacobian with closed-form sum-of-logs determinant + exact single-pass forward density estimation and inverse sampling.","医学适配":"Applied to invertible medical image priors, exact-likelihood out-of-distribution detection, and bijective registration.","适用范围与证据":"Foundational normalizing flow; coupling layers require deep stacking for expressivity and raw pixel likelihoods often mis-score semantic OOD anomalies."},"paper_title":"Density Estimation Using Real NVP","paper_url":"https://openreview.net/pdf?id=HkpbnH9lx","code_label":"未提供官方实现","code_url":"","has_code":false,"image":"assets/58d8870ac7529f6e0912.avif"},{"id":"architecture_model_121_glow","num":121,"num_str":"121","year":2018,"year_str":"2018","venue":"NeurIPS","venue_group":"ml","era_group":"era2","title":"Glow","family_id":"models_generative","family_code":"10","family_short":"生成、扩散与流匹配","family_en":"Generative, Diffusion & Flow","family_icon":"X","family_label":"生成模型：从潜变量与对抗学习到 diffusion、flow 与 consistency","archetype":"ActNorm—可逆 1×1 卷积—仿射 coupling 的多尺度 flow","archetype_en":"invertible_1x1_conv_multiscale_flow","accent":"#6B5700","fig_badge":"Figure 2 · PDF p.4","fig_href":"https://proceedings.neurips.cc/paper/2018/hash/d139db6a236200b21cc7f752979132d0-Abstract.html","core_mech":"Glow 在 RealNVP coupling 上加入数据依赖 ActNorm 和可学习可逆 1×1 通道卷积。","core_mech_en":"Enhances multi-scale affine coupling flows with activation normalization (ActNorm) and learnable invertible 1×1 channel convolutions parameterized via LU decomposition.","input_desc":"连续化图像","input_en":"Continuous-valued image x","output_desc":"精确似然和层级潜变量，或由潜变量反演的生成图像","output_en":"Hierarchical latent variables z, exact log-likelihood log p(x), and exact latent-to-image synthesis","form_title":"核心公式 · ActNorm、可逆 1×1 卷积与耦合层的流似然","form_title_en":"Core Formalism · Multi-Scale Flow Step Combining ActNorm, Invertible 1×1 Convolution & Affine Coupling","nodes":[{"name":"连续化图像","desc":"离散像素加入噪声并做 logit/尺度预处理","name_en":"continuous","desc_en":"Ingests continuous-valued image x and prepares initial tensor representations (continuous)."},{"name":"Squeeze","desc":"将空间 2×2 邻域重排到通道维","name_en":"Squeeze","desc_en":"Executes Squeeze to extract primary structural features and establish spatial/sequence encoding."},{"name":"ActNorm","desc":"每通道可逆仿射变换，首批数据依赖初始化","name_en":"ActNorm","desc_en":"Performs ActNorm within the core invertible 1x1 conv multiscale flow computation pathway."},{"name":"Invertible 1×1 convolution","desc":"学习完整可逆通道混合，替代固定 permutation","name_en":"Invertible 1×1 convolution","desc_en":"Performs Invertible 1×1 convolution within the core invertible 1x1 conv multiscale flow computation pathway."},{"name":"Affine coupling","desc":"一半通道条件化另一半的 scale 与 shift","name_en":"Affine coupling","desc_en":"Performs Affine coupling within the core invertible 1x1 conv multiscale flow computation pathway."},{"name":"Multi-scale split","desc":"每层级分出 latent，并对剩余特征继续 flow","name_en":"Multi-scale split","desc_en":"Performs Multi-scale split within the core invertible 1x1 conv multiscale flow computation pathway."},{"name":"精确 change-of-variables","desc":"累加 ActNorm、1×1 conv 和 coupling 的 log-det","name_en":"change-of-variables","desc_en":"Applies change-of-variables to project aggregated representations toward the target task head."},{"name":"层级 z / 逆向样本","desc":"从高斯先验采样并严格反演全部步骤","name_en":"hierarchical z","desc_en":"Produces hierarchical latent variables z, exact log-likelihood log p(x), and exact latent-to-image synthesis via hierarchical z."}],"design_principles":["每个 flow step 依次执行 ActNorm、可逆 1×1 卷积和 affine coupling。","可逆 1×1 卷积学习通道置换，比固定 shuffle 更灵活。","多尺度 squeeze/split 建立层级 latent，并保留精确 change-of-variables 似然。"],"design_principles_en":["Core Hypothesis: Replace fixed channel reversals with a learnable invertible 1×1 convolution and stabilize deep flow training via data-dependent ActNorm.","Architectural Delta: ActNorm (scale/bias per channel) + LU-factored invertible 1×1 convolution reducing log-det cost from O(C³) to O(C).","Mathematical Formalism: Multi-Scale Flow Step Combining ActNorm, Invertible 1×1 Convolution & Affine Coupling."],"med_apps":["是医学 normalizing-flow 生成、异常检测和不确定性建模的常用结构母体。","精确密度可能偏好平滑或低复杂度扫描，异常分数需与设备、重建核和人群协变量解耦。"],"med_apps_en":["Clinical Translation: Used as an exact-likelihood generative prior for medical inverse problems and unsupervised brain MRI anomaly scoring.","Evidence & Safety Boundary: Classic flow milestone; bijective dimensionality preservation makes high-resolution 3D flows memory-intensive compared to latent diffusion."],"attrs":{"上一代瓶颈":"RealNVP 固定通道置换限制特征混合，深层训练初始化不稳","核心想法":"在多尺度 flow 中用 actnorm、可逆 1×1 卷积和仿射 coupling 学习精确似然","关键改进":"可学习可逆通道混合与数据依赖归一化提升生成质量","医学适配":"常作医学 normalizing-flow 生成和异常检测结构基础","适用范围与证据":"经典 flow 架构；内存与似然语义问题限制临床直接应用"},"attrs_en":{"上一代瓶颈":"Fixed channel permutations in RealNVP restricted cross-channel mixing, and small-batch flow training suffered from activation instability.","核心想法":"Replace fixed channel reversals with a learnable invertible 1×1 convolution and stabilize deep flow training via data-dependent ActNorm.","关键改进":"ActNorm (scale/bias per channel) + LU-factored invertible 1×1 convolution reducing log-det cost from O(C³) to O(C).","医学适配":"Used as an exact-likelihood generative prior for medical inverse problems and unsupervised brain MRI anomaly scoring.","适用范围与证据":"Classic flow milestone; bijective dimensionality preservation makes high-resolution 3D flows memory-intensive compared to latent diffusion."},"paper_title":"Glow: Generative Flow with Invertible 1×1 Convolutions","paper_url":"https://proceedings.neurips.cc/paper/2018/hash/d139db6a236200b21cc7f752979132d0-Abstract.html","code_label":"作者/机构官方实现","code_url":"https://github.com/openai/glow","has_code":true,"image":"assets/7a61aa0f67c06be9cb68.avif"},{"id":"architecture_model_122_pfgm","num":122,"num_str":"122","year":2023,"year_str":"2023","venue":"ICML","venue_group":"ml","era_group":"era4","title":"PFGM++","family_id":"models_generative","family_code":"10","family_short":"生成、扩散与流匹配","family_en":"Generative, Diffusion & Flow","family_icon":"X","family_label":"生成模型：从潜变量与对抗学习到 diffusion、flow 与 consistency","archetype":"增广空间 Poisson 电场与 diffusion 连续统一的生成 flow","archetype_en":"augmented_poisson_electrostatic_flow","accent":"#6B5700","fig_badge":"Figure 1 · PDF p.2","fig_href":"https://proceedings.mlr.press/v202/xu23m.html","core_mech":"PFGM++ 用可调增广维度 D 的 Poisson 电场统一 PFGM 与 diffusion，而不是固定高斯前向噪声过程。","core_mech_en":"Embeds N-dimensional data on the z=0 hyperplane of an N+D augmented space and learns the high-dimensional Poisson electric field lines, unifying PFGM (D=1) and Diffusion (D→∞).","input_desc":"训练数据 x∈R^N；采样时为 N+D 维简单先验状态","input_en":"Training data x ∈ R^N embedded in R^{N+D}; hemispherical prior samples at large radius r_max during generation","output_desc":"沿学习电场 ODE 流回数据超平面的生成样本","output_en":"Samples generated by integrating the learned augmented electric field ODE back to the z=0 hyperplane","form_title":"核心公式 · D 维 Poisson 扰动核与反向场 ODE","form_title_en":"Core Formalism · Augmented D-Dimensional Heavy-Tailed Poisson Perturbation Kernel & Electric Field ODE","nodes":[{"name":"数据分布 p(x)","desc":"位于增广空间 r=0 的 N 维超平面","name_en":"p(x","desc_en":"Ingests training data x ∈ r^n embedded in r^{n+d}; hemispherical prior samples at large radius r_max during generation and prepares initial tensor representations (p(x)."},{"name":"D 维增广坐标","desc":"为每个样本附加半径 r 与方向，形成 N+D 维空间","name_en":"Stage 02","desc_en":"Executes Stage 02 to extract primary structural features and establish spatial/sequence encoding."},{"name":"Poisson perturbation kernel","desc":"按与 r、D 相关的重尾分布扰动数据，构造不同半径训练样本","name_en":"Poisson perturbation kernel","desc_en":"Performs Poisson perturbation kernel within the core augmented poisson electrostatic flow computation pathway."},{"name":"电场/方向网络","desc":"学习高维 Poisson 场的归一化方向或等价 score 参数化","name_en":"Stage 04","desc_en":"Performs Stage 04 within the core augmented poisson electrostatic flow computation pathway."},{"name":"Field matching loss","desc":"回归扰动样本指向数据电荷分布的目标场","name_en":"Field matching loss","desc_en":"Performs Field matching loss within the core augmented poisson electrostatic flow computation pathway."},{"name":"大半径简单先验","desc":"在半球/球面附近初始化采样状态","name_en":"prior","desc_en":"Performs prior within the core augmented poisson electrostatic flow computation pathway."},{"name":"Poisson flow ODE","desc":"从大 r 沿学习场积分到 r→0","name_en":"Poisson flow ODE","desc_en":"Applies Poisson flow ODE to project aggregated representations toward the target task head."},{"name":"生成样本","desc":"落回数据超平面得到 x","name_en":"Synthesized Sample","desc_en":"Produces samples generated by integrating the learned augmented electric field ode back to the z=0 hyperplane via Synthesized Sample."}],"design_principles":["把数据当作增广空间超平面上的电荷，用 Poisson 场定义生成轨迹。","增广维度 D 连续连接原 PFGM 与 diffusion 极限，可调鲁棒性和训练行为。","采样是沿学习场求解 ODE，从简单大半径分布流向数据。"],"design_principles_en":["Core Hypothesis: Generalize the augmented electrostatic dimension from D=1 to arbitrary D, proving that as D→∞ and r=σ√D, the Poisson kernel converges to Gaussian diffusion.","Architectural Delta: Provides a tunable robustness–rigidity knob D (e.g., D=64 or 2048) that improves ODE integration stability and error tolerance over standard EDM diffusion.","Mathematical Formalism: Augmented D-Dimensional Heavy-Tailed Poisson Perturbation Kernel & Electric Field ODE."],"med_apps":["为医学图像生成和逆问题提供 diffusion 之外的 score/flow 先验。","高维 ODE 仍会继承训练分布偏差；医学保真必须检查定量值、病灶保存和条件测量残差。"],"med_apps_en":["Clinical Translation: Evaluated on low-dose CT denoising and medical image generation as a more perturbation-robust drop-in alternative to score models.","Evidence & Safety Boundary: Theoretically elegant unification of electrostatic flows and diffusion; clinical adoption remains at an early research stage."],"attrs":{"上一代瓶颈":"原始 PFGM 与 diffusion 的关系和可扩展调节机制不清","核心想法":"在增广空间用高维电场/Poisson flow 连接数据分布与简单先验","关键改进":"以增广维度 D 连续统一 Poisson flow 与 diffusion，并改善鲁棒性和采样","医学适配":"提供医学生成与逆问题的新型 score/flow 先验选择","适用范围与证据":"有理论吸引力但医学实证有限；仍需与强 diffusion 公平比较"},"attrs_en":{"上一代瓶颈":"Diffusion models rely on Gaussian kernels with thin tails, whereas original PFGM (D=1) was difficult to scale to large conditional architectures.","核心想法":"Generalize the augmented electrostatic dimension from D=1 to arbitrary D, proving that as D→∞ and r=σ√D, the Poisson kernel converges to Gaussian diffusion.","关键改进":"Provides a tunable robustness–rigidity knob D (e.g., D=64 or 2048) that improves ODE integration stability and error tolerance over standard EDM diffusion.","医学适配":"Evaluated on low-dose CT denoising and medical image generation as a more perturbation-robust drop-in alternative to score models.","适用范围与证据":"Theoretically elegant unification of electrostatic flows and diffusion; clinical adoption remains at an early research stage."},"paper_title":"PFGM++: Unlocking the Potential of Physics-Inspired Generative Models","paper_url":"https://proceedings.mlr.press/v202/xu23m.html","code_label":"作者/机构官方实现","code_url":"https://github.com/Newbeeer/pfgmpp","has_code":true,"image":"assets/342a19412e82816a0d3d.avif"},{"id":"architecture_model_123_sit","num":123,"num_str":"123","year":2024,"year_str":"2024","venue":"ECCV","venue_group":"cv","era_group":"era4","title":"SiT","family_id":"models_generative","family_code":"10","family_short":"生成、扩散与流匹配","family_en":"Generative, Diffusion & Flow","family_icon":"X","family_label":"生成模型：从潜变量与对抗学习到 diffusion、flow 与 consistency","archetype":"stochastic interpolant 上的可扩展 Transformer flow/diffusion","archetype_en":"scalable_stochastic_interpolant_transformer","accent":"#6B5700","fig_badge":"Table 1 · PDF p.2","fig_href":"https://scalable-interpolant.github.io/","core_mech":"SiT 将 DiT 放入 stochastic interpolant 框架，用统一模型显式比较 velocity、score 和 diffusion 参数化。","core_mech_en":"Places the Diffusion Transformer (DiT) backbone inside a continuous-time Stochastic Interpolant framework to systematically decouple interpolation schedules, model targets, and samplers.","input_desc":"数据样本 x0、噪声 ε、连续时间 t 和可选类别条件","input_en":"Data sample x_0 (or latent), Gaussian noise ε, continuous time t ∈ [0,1], and conditioning label c","output_desc":"学习到的 velocity/score/noise 场及 ODE/SDE 生成样本","output_en":"Samples generated via configurable deterministic ODE or stochastic SDE integrators from the same SiT backbone","form_title":"核心公式 · 随机插值路径上的速度场匹配","form_title_en":"Core Formalism · Stochastic Interpolant x_t = α_t x_0 + σ_t ε Unifying Velocity & Score Parameterizations","nodes":[{"name":"数据与噪声端点","desc":"x0 来自数据，ε 来自简单高斯先验","name_en":"noise","desc_en":"Ingests data sample x_0 (or latent), gaussian noise ε, continuous time t ∈ [0,1], and conditioning label c and prepares initial tensor representations (noise)."},{"name":"Stochastic interpolant xt","desc":"由 α(t)x0、σ(t)ε 与可选随机项定义连续概率路径","name_en":"Stochastic interpolant xt","desc_en":"Executes Stochastic interpolant xt to extract primary structural features and establish spatial/sequence encoding."},{"name":"Patch/time/condition embedding","desc":"把 xt 切成 token，并加入时间和类别条件","name_en":"Patch/time/condition embedding","desc_en":"Performs Patch/time/condition embedding within the core scalable stochastic interpolant transformer computation pathway."},{"name":"Scalable Interpolant Transformer","desc":"DiT 式 AdaLN 条件 Transformer 建模全局 token 交互","name_en":"Scalable Interpolant Transformer","desc_en":"Performs Scalable Interpolant Transformer within the core scalable stochastic interpolant transformer computation pathway."},{"name":"v/score/noise prediction head","desc":"根据参数化选择输出 velocity、score 或 noise","name_en":"v/score/noise prediction head","desc_en":"Performs v/score/noise prediction head within the core scalable stochastic interpolant transformer computation pathway."},{"name":"加权 interpolant loss","desc":"路径、预测参数化与时间权重可独立选择","name_en":"interpolant loss","desc_en":"Performs interpolant loss within the core scalable stochastic interpolant transformer computation pathway."},{"name":"Probability-flow ODE / SDE solver","desc":"从噪声端沿预测场积分到数据端","name_en":"Probability-flow ODE / SDE solver","desc_en":"Applies Probability-flow ODE / SDE solver to project aggregated representations toward the target task head."},{"name":"生成样本","desc":"可配 classifier-free guidance","name_en":"Synthesized Sample","desc_en":"Produces samples generated via configurable deterministic ode or stochastic sde integrators from the same sit backbone via Synthesized Sample."}],"design_principles":["stochastic interpolants 用一套连续时间公式容纳 diffusion 与 flow。","插值路径、预测量和损失权重可分别选择，而不是被单一 DDPM 参数化绑定。","采用 DiT 式 Transformer 扩展模型容量，再用 ODE 或 SDE 求解。"],"design_principles_en":["Core Hypothesis: Use the Scalable Interpolant Transformer (SiT) to modularly ablate path interpolants (linear vs. trig), prediction targets (velocity vs. score), and diffusion coefficients.","Architectural Delta: Demonstrates that linear stochastic interpolants with velocity prediction and tunable SDE diffusion coefficients consistently outperform rigid DDPM schedules.","Mathematical Formalism: Stochastic Interpolant x_t = α_t x_0 + σ_t ε Unifying Velocity & Score Parameterizations."],"med_apps":["便于在相同 Transformer 骨架下公平比较医学 diffusion 与 flow matching 设计。","采样步数、guidance、3D 显存和条件泄漏都会影响临床可用性，生成质量不能替代病例级真实性验证。"],"med_apps_en":["Clinical Translation: Provides a clean modern recipe for training 2D/3D medical latent transformers across both ODE flow and SDE diffusion regimes.","Evidence & Safety Boundary: Important unifying generative framework; medical inverse-problem conditioning and quantitative audits remain active extensions."],"attrs":{"上一代瓶颈":"扩散与流匹配实现分散，目标和采样路径的关系难系统比较","核心想法":"以 stochastic interpolants 统一 diffusion 与 flow objectives，并用 Transformer 扩展生成","关键改进":"在统一连续时间框架中选择插值、预测参数化和损失权重","医学适配":"适合比较医学 latent/3D diffusion 与 flow matching 的训练设计","适用范围与证据":"生成建模重要统一视角；医学保真和逆问题证据仍早期"},"attrs_en":{"上一代瓶颈":"Comparisons between diffusion and flow matching conflated backbone architecture (U-Net vs. DiT), noise schedules, and ODE vs. SDE sampling.","核心想法":"Use the Scalable Interpolant Transformer (SiT) to modularly ablate path interpolants (linear vs. trig), prediction targets (velocity vs. score), and diffusion coefficients.","关键改进":"Demonstrates that linear stochastic interpolants with velocity prediction and tunable SDE diffusion coefficients consistently outperform rigid DDPM schedules.","医学适配":"Provides a clean modern recipe for training 2D/3D medical latent transformers across both ODE flow and SDE diffusion regimes.","适用范围与证据":"Important unifying generative framework; medical inverse-problem conditioning and quantitative audits remain active extensions."},"paper_title":"SiT: Exploring Flow and Diffusion-Based Generative Models with Scalable Interpolant Transformers","paper_url":"https://www.ecva.net/papers/eccv_2024/papers_ECCV/papers/09828.pdf","code_label":"作者/机构官方实现","code_url":"https://github.com/willisma/SiT","has_code":true,"image":"assets/f5641c51e1c6d45b0fc9.avif"},{"id":"architecture_model_124_lapirn","num":124,"num_str":"124","year":2020,"year_str":"2020","venue":"MICCAI","venue_group":"miccai","era_group":"era3","title":"LapIRN","family_id":"models_registration_geometry","family_code":"13","family_short":"可微配准与投影几何","family_en":"Registration & SE(3)","family_icon":"XIII","family_label":"配准与投影几何：可微变换、拓扑约束和 SE(3) 闭环","archetype":"Laplacian 金字塔上的粗到细残差形变场级联","archetype_en":"laplacian_pyramid_residual_registration","accent":"#1F4E79","fig_badge":"Figure 1 · PDF p.3","fig_href":"https://arxiv.org/abs/2006.16148","core_mech":"LapIRN 把配准写成 Laplacian 金字塔上的三层残差流：每层先 warp，再让下一层只修正剩余误差。","core_mech_en":"Decomposes large-deformation 3D registration into a 3-level coarse-to-fine Laplacian image pyramid where each level warps the previous estimate and refines only the residual displacement.","input_desc":"moving 体积 Im 与 fixed 体积 If","input_en":"3D moving volume I_m and fixed volume I_f decomposed into a 3-level Gaussian/Laplacian pyramid","output_desc":"组合位移场、形变后的 moving 图像与可选 diffeomorphic 场","output_en":"Composed full-resolution deformation field (or stationary velocity diffeomorphism) and warped volume","form_title":"核心公式 · 拉普拉斯金字塔中的逐级残差形变估计","form_title_en":"Core Formalism · Multi-Resolution Laplacian Pyramid Residual Displacement Composition","nodes":[{"name":"Moving/fixed 图像金字塔","desc":"建立低、中、高分辨率三层输入","name_en":"Moving/fixed","desc_en":"Ingests 3d moving volume i_m and fixed volume i_f decomposed into a 3-level gaussian/laplacian pyramid and prepares initial tensor representations (Moving/fixed)."},{"name":"Level 1 coarse network","desc":"在最低分辨率预测大尺度位移 φ1","name_en":"Level 1 coarse network","desc_en":"Executes Level 1 coarse network to extract primary structural features and establish spatial/sequence encoding."},{"name":"Spatial transformer 1","desc":"用上采样 φ1 先形变 moving，作为下一层初始化","name_en":"Spatial transformer 1","desc_en":"Performs Spatial transformer 1 within the core laplacian pyramid residual registration computation pathway."},{"name":"Level 2 residual network","desc":"结合中尺度 fixed、已形变 moving 与粗场，预测残差 Δφ2","name_en":"Level 2 residual network","desc_en":"Performs Level 2 residual network within the core laplacian pyramid residual registration computation pathway."},{"name":"Spatial transformer 2","desc":"组合粗场和中尺度残差后再次形变","name_en":"Spatial transformer 2","desc_en":"Performs Spatial transformer 2 within the core laplacian pyramid residual registration computation pathway."},{"name":"Level 3 refinement network","desc":"在全分辨率预测局部残差 Δφ3","name_en":"Level 3 refinement network","desc_en":"Performs Level 3 refinement network within the core laplacian pyramid residual registration computation pathway."},{"name":"无监督相似度 + 平滑正则","desc":"每层比较 warped moving 与 fixed，并约束位移梯度；diffeomorphic 版可积分速度场","name_en":"unsupervised + regularization","desc_en":"Applies unsupervised + regularization to project aggregated representations toward the target task head."},{"name":"最终组合形变","desc":"φ1、Δφ2、Δφ3 逐级组合并输出配准图像","name_en":"Stage 08","desc_en":"Produces composed full-resolution deformation field (or stationary velocity diffeomorphism) and warped volume via Stage 08."}],"design_principles":["低分辨率先捕获大位移，高分辨率只需预测局部残差。","每层把前一级形变场上采样并用于 warp，使级联具有明确初始化。","训练不需真实形变标签，以图像相似度和场平滑正则优化。"],"design_principles_en":["Core Hypothesis: Solve registration progressively from 1/4 → 1/2 → 1/1 resolution using feature-skip pyramid networks that predict incremental residual warps.","Architectural Delta: Coarse-to-fine residual warping + warm-start curriculum training + optional scaling-and-squaring diffeomorphic parameterization.","Mathematical Formalism: Multi-Resolution Laplacian Pyramid Residual Displacement Composition."],"med_apps":["适合 3D 脑、腹部和胸部 CT/MRI 的快速大形变配准。","相似度变好不保证解剖对应正确；需报告 Jacobian folding、TRE/landmark 与跨模态鲁棒性。"],"med_apps_en":["Clinical Translation: Widely used benchmark baseline for large-deformation lung CT inspiration–expiration and brain MRI registration.","Evidence & Safety Boundary: Classic multi-scale registration architecture; subsequent GradICON/uniGradICON offer stronger inverse-consistency guarantees."],"attrs":{"上一代瓶颈":"单尺度配准捕获范围有限，大形变时易落入局部最优","核心想法":"在由粗到细的图像金字塔上逐级预测并组合位移场","关键改进":"每级以前一级形变为初始化，兼顾大位移捕获和局部精化","医学适配":"用于 3D 脑、腹部和胸部 CT/MRI 快速无监督配准","适用范围与证据":"经典 coarse-to-fine 学习式基线；可逆性与拓扑保持仍需额外约束"},"attrs_en":{"上一代瓶颈":"Single-scale 3D registration networks failed on large respiratory or inter-subject displacements due to local minima and limited receptive fields.","核心想法":"Solve registration progressively from 1/4 → 1/2 → 1/1 resolution using feature-skip pyramid networks that predict incremental residual warps.","关键改进":"Coarse-to-fine residual warping + warm-start curriculum training + optional scaling-and-squaring diffeomorphic parameterization.","医学适配":"Widely used benchmark baseline for large-deformation lung CT inspiration–expiration and brain MRI registration.","适用范围与证据":"Classic multi-scale registration architecture; subsequent GradICON/uniGradICON offer stronger inverse-consistency guarantees."},"paper_title":"Laplacian Pyramid Networks for Fast Deformable Registration of Large Deformation","paper_url":"https://arxiv.org/abs/2006.16148","code_label":"作者/机构官方实现","code_url":"https://github.com/cwmok/LapIRN","has_code":true,"image":"assets/5887688e6a5abeadaa2d.avif"},{"id":"architecture_model_125_transmorph","num":125,"num_str":"125","year":2022,"year_str":"2022","venue":"Medical Image Analysis","venue_group":"journal","era_group":"era3","title":"TransMorph","family_id":"models_registration_geometry","family_code":"13","family_short":"可微配准与投影几何","family_en":"Registration & SE(3)","family_icon":"XIII","family_label":"配准与投影几何：可微变换、拓扑约束和 SE(3) 闭环","archetype":"层级 Swin Transformer 编码与卷积解码的无监督形变配准","archetype_en":"swin_transformer_hybrid_registration","accent":"#1F4E79","fig_badge":"Figure 1 · PDF p.4","fig_href":"https://pubmed.ncbi.nlm.nih.gov/36156420/","core_mech":"TransMorph 用层级 Swin encoder 取代纯 CNN 配准编码器，同时保留 U-Net 式 decoder 和可微 warping。","core_mech_en":"Replaces the convolutional encoder in VoxelMorph with a 3D hierarchical Swin Transformer encoder while retaining a convolutional U-Net decoder and Spatial Transformer warping.","input_desc":"moving 图像 Im 与 fixed 图像 If","input_en":"Concatenated 3D moving and fixed volumes (I_m, I_f)","output_desc":"稠密位移场 φ、warped moving 图像及可选不确定性估计","output_en":"Dense 3D displacement field φ, warped moving image I_m ∘ φ, and optional Bayesian uncertainty","form_title":"核心公式 · Transformer 全局对应建模与无监督形变约束","form_title_en":"Core Formalism · 3D Shifted-Window Transformer Correspondence Encoding + Differentiable Deformation Decoding","nodes":[{"name":"Moving/fixed pair","desc":"按通道拼接的 2D 或 3D 医学图像","name_en":"Moving/fixed pair","desc_en":"Ingests concatenated 3d moving and fixed volumes (i_m, i_f) and prepares initial tensor representations (Moving/fixed pair)."},{"name":"Patch partition/embedding","desc":"将图像对变为层级视觉 token","name_en":"Patch partition/embedding","desc_en":"Executes Patch partition/embedding to extract primary structural features and establish spatial/sequence encoding."},{"name":"Swin Transformer encoder","desc":"窗口与 shifted-window attention 建模局部和长程对应","name_en":"Swin Transformer encoder","desc_en":"Performs Swin Transformer encoder within the core swin transformer hybrid registration computation pathway."},{"name":"多尺度 Transformer features","desc":"patch merging 产生不同分辨率的对应线索","name_en":"multi-scale Transformer features","desc_en":"Performs multi-scale Transformer features within the core swin transformer hybrid registration computation pathway."},{"name":"U-Net 式卷积 decoder","desc":"逐级上采样并融合 encoder skip features","name_en":"U-Net convolution decoder","desc_en":"Performs U-Net convolution decoder within the core swin transformer hybrid registration computation pathway."},{"name":"Displacement field head","desc":"卷积输出每体素位移向量 φ","name_en":"Displacement field head","desc_en":"Performs Displacement field head within the core swin transformer hybrid registration computation pathway."},{"name":"Spatial transformer","desc":"以可微插值计算 Im∘φ","name_en":"Spatial transformer","desc_en":"Performs Spatial transformer within the core swin transformer hybrid registration computation pathway."},{"name":"NCC/相似度 + 平滑正则","desc":"无需真实形变标签；可扩展 diffeomorphic 或 Bayesian 版本","name_en":"NCC/ + regularization","desc_en":"Applies NCC/ + regularization to project aggregated representations toward the target task head."},{"name":"配准结果","desc":"稠密场、warped image 和可选 uncertainty","name_en":"Registered Output","desc_en":"Produces dense 3d displacement field φ, warped moving image i_m ∘ φ, and optional bayesian uncertainty via Registered Output."}],"design_principles":["Swin 的层级窗口注意力在可控成本下捕获远距离解剖对应。","Transformer encoder 提供多尺度 skip，卷积 decoder 恢复稠密局部位移。","Spatial transformer 把形变放回图像域，以相似度和场正则进行无监督训练。"],"design_principles_en":["Core Hypothesis: Leverage 3D Swin Transformer blocks in the encoder to capture larger effective receptive fields for cross-volume matching.","Architectural Delta: Hybrid 3D Swin encoder + CNN skip decoder + diffeomorphic/Bayesian variants benchmarked across brain MRI and CT.","Mathematical Formalism: 3D Shifted-Window Transformer Correspondence Encoding + Differentiable Deformation Decoding."],"med_apps":["是脑 MRI 与腹部 CT 中常用的 Transformer 配准基线。","attention 可表达长程匹配但不保证拓扑；必须检查 Jacobian folding、landmark TRE 和跨模态相似度适用性。"],"med_apps_en":["Clinical Translation: Standard Transformer-based 3D medical image registration baseline.","Evidence & Safety Boundary: Important architectural comparison point; attention in the encoder does not automatically prevent folding without GradICON/diffeomorphic constraints."],"attrs":{"上一代瓶颈":"CNN 配准局部感受野难处理远距离解剖对应","核心想法":"用 Swin Transformer 编码固定/移动图像的长程对应，再由卷积 decoder 输出形变","关键改进":"层级窗口注意力结合 U-Net 式多尺度解码增强全局匹配","医学适配":"成为脑 MRI 和腹部 CT Transformer 配准的常用基线","适用范围与证据":"重要架构基线；长程 attention 本身不保证拓扑、对称或跨域稳健"},"attrs_en":{"上一代瓶颈":"Small 3×3×3 CNN kernels in early encoder stages struggled to establish long-range spatial correspondence across large anatomical displacements.","核心想法":"Leverage 3D Swin Transformer blocks in the encoder to capture larger effective receptive fields for cross-volume matching.","关键改进":"Hybrid 3D Swin encoder + CNN skip decoder + diffeomorphic/Bayesian variants benchmarked across brain MRI and CT.","医学适配":"Standard Transformer-based 3D medical image registration baseline.","适用范围与证据":"Important architectural comparison point; attention in the encoder does not automatically prevent folding without GradICON/diffeomorphic constraints."},"paper_title":"TransMorph: Transformer for Unsupervised Medical Image Registration","paper_url":"https://pubmed.ncbi.nlm.nih.gov/36156420/","code_label":"作者/机构官方实现","code_url":"https://github.com/junyuchen245/TransMorph_Transformer_for_Medical_Image_Registration","has_code":true,"image":"assets/a90011a16ef8f12b4c32.avif"},{"id":"architecture_model_126_idir","num":126,"num_str":"126","year":2022,"year_str":"2022","venue":"MIDL","venue_group":"miccai","era_group":"era3","title":"IDIR","family_id":"models_registration_geometry","family_code":"13","family_short":"可微配准与投影几何","family_en":"Registration & SE(3)","family_icon":"XIII","family_label":"配准与投影几何：可微变换、拓扑约束和 SE(3) 闭环","archetype":"逐病例优化的坐标 MLP 连续形变表示","archetype_en":"implicit_coordinate_mlp_registration","accent":"#1F4E79","fig_badge":"Figure 1 · PDF p.2","fig_href":"https://proceedings.mlr.press/v172/wolterink22a.html","core_mech":"IDIR 将位移场本身作为坐标神经场，并在测试图像对上直接优化，而不是由训练好的网络一次预测 flow。","core_mech_en":"Parameterizes the continuous 3D deformation field φ(x) = x + u_θ(x) for a single image pair directly as a coordinate-based Implicit Neural Representation (SIREN MLP) optimized at test time.","input_desc":"一对 fixed/moving 图像及在图像域采样的连续坐标 x","input_en":"Continuous 3D spatial coordinates x ∈ [-1,1]³ sampled over a fixed/moving volume pair (I_f, I_m)","output_desc":"可在任意坐标查询的连续位移场 uθ(x) 和 warped moving 图像","output_en":"Resolution-independent continuous deformation field φ_θ(x) with exact autograd spatial derivatives","form_title":"核心公式 · 逐病例坐标神经场的连续配准优化","form_title_en":"Core Formalism · Per-Pair Continuous Coordinate MLP Deformation Field Optimization with Analytical Jacobian Regularization","nodes":[{"name":"Fixed 与 moving 图像","desc":"每一对病例单独优化，不需要跨病例预训练","name_en":"Fixed moving","desc_en":"Ingests continuous 3d spatial coordinates x ∈ [-1,1]³ sampled over a fixed/moving volume pair (i_f, i_m) and prepares initial tensor representations (Fixed moving)."},{"name":"连续坐标采样","desc":"从归一化 2D/3D 空间采样 x","name_en":"continuous sampling","desc_en":"Executes continuous sampling to extract primary structural features and establish spatial/sequence encoding."},{"name":"坐标/傅里叶特征","desc":"可将 x 映射到更高频的位置表示","name_en":"feature","desc_en":"Performs feature within the core implicit coordinate mlp registration computation pathway."},{"name":"Implicit coordinate MLP","desc":"以 θ 表示连续函数 x→uθ(x)","name_en":"Implicit coordinate MLP","desc_en":"Performs Implicit coordinate MLP within the core implicit coordinate mlp registration computation pathway."},{"name":"坐标变换 x+uθ(x)","desc":"将 fixed 网格映射到 moving 采样位置","name_en":"x+uθ(x","desc_en":"Performs x+uθ(x within the core implicit coordinate mlp registration computation pathway."},{"name":"可微 moving interpolator","desc":"在变换坐标处查询 moving 强度","name_en":"differentiable moving interpolator","desc_en":"Performs differentiable moving interpolator within the core implicit coordinate mlp registration computation pathway."},{"name":"图像相似度 + 形变正则","desc":"逐病例反向传播更新 θ，可加 Jacobian、hyperelastic 或 bending 约束","name_en":"+ regularization","desc_en":"Applies + regularization to project aggregated representations toward the target task head."},{"name":"连续形变场","desc":"优化后可在任意分辨率查询并生成 warped image","name_en":"continuous deformation field","desc_en":"Produces resolution-independent continuous deformation field φ_θ(x) with exact autograd spatial derivatives via continuous deformation field."}],"design_principles":["不在离散 voxel 网格直接存位移，而用坐标 MLP 参数化连续场。","每个图像对独立优化网络参数，因此无需训练集或预训练 checkpoint。","同一隐式函数可在任意坐标求值，并通过可微插值由图像相似度监督。"],"design_principles_en":["Core Hypothesis: Represent the displacement vector field u_θ(x) as a periodic-activation coordinate MLP optimized directly on the test pair via stochastic coordinate sampling.","Architectural Delta: Grid-free continuous parameterization + exact analytical Jacobian/hyperelastic/bending-energy derivatives via automatic differentiation.","Mathematical Formalism: Per-Pair Continuous Coordinate MLP Deformation Field Optimization with Analytical Jacobian Regularization."],"med_apps":["适合个体化 MRI/CT 配准、连续场分析和需要任意分辨率查询的场景。","逐病例迭代较慢且可能落入局部最优；连续 MLP 本身不保证 diffeomorphism，需显式拓扑正则。"],"med_apps_en":["Clinical Translation: Used for high-precision lung 4D-CT landmark tracking and patient-specific registration without training datasets.","Evidence & Safety Boundary: Representative implicit neural registration method; per-case optimization takes seconds to minutes rather than milliseconds."],"attrs":{"上一代瓶颈":"离散位移网格受分辨率限制，学习式配准受训练分布约束","核心想法":"以坐标 MLP 连续表示单对图像的位移场，并按相似度逐病例优化","关键改进":"连续可微形变表示无需预训练，可在任意坐标查询并正则化","医学适配":"用于 MRI/CT 个体化配准和连续形变建模","适用范围与证据":"INR 配准代表；逐病例优化较慢且相似度仍可能歧义"},"attrs_en":{"上一代瓶颈":"Discrete voxel-grid registration is tied to grid resolution, relies on finite-difference derivative approximations, and suffers from training-cohort bias.","核心想法":"Represent the displacement vector field u_θ(x) as a periodic-activation coordinate MLP optimized directly on the test pair via stochastic coordinate sampling.","关键改进":"Grid-free continuous parameterization + exact analytical Jacobian/hyperelastic/bending-energy derivatives via automatic differentiation.","医学适配":"Used for high-precision lung 4D-CT landmark tracking and patient-specific registration without training datasets.","适用范围与证据":"Representative implicit neural registration method; per-case optimization takes seconds to minutes rather than milliseconds."},"paper_title":"Implicit Neural Representations for Deformable Image Registration","paper_url":"https://2022.midl.io/papers/c2","code_label":"作者/机构官方实现","code_url":"https://github.com/MIAGroupUT/IDIR","has_code":true,"image":"assets/91ce6ea3f319e93d4b10.avif"},{"id":"architecture_model_127_deepdrr","num":127,"num_str":"127","year":2018,"year_str":"2018","venue":"MICCAI","venue_group":"miccai","era_group":"era2","title":"DeepDRR","family_id":"models_registration_geometry","family_code":"13","family_short":"可微配准与投影几何","family_en":"Registration & SE(3)","family_icon":"XIII","family_label":"配准与投影几何：可微变换、拓扑约束和 SE(3) 闭环","archetype":"学习材料/散射模块与解析 X-ray forward model 的混合模拟器","archetype_en":"physics_informed_deep_drr_simulator","accent":"#1F4E79","fig_badge":"Figure 1 · PDF p.3","fig_href":"https://arxiv.org/abs/1803.08606","core_mech":"DeepDRR 不是纯 GAN 渲染器，而是 3D 材料分解网络、解析材料/能谱 ray tracing、学习散射和解析噪声的组合 forward model。","core_mech_en":"Physics-based X-ray fluoroscopy simulator combining CNN 3D tissue material decomposition, analytical energy-dependent Beer–Lambert ray-casting, learned Rayleigh/Compton scatter, and quantum noise.","input_desc":"患者 CT、X-ray 源—探测器几何、能谱和曝光参数","input_en":"Volumetric 3D CT scan, C-arm source–detector geometry, X-ray spectrum E, and photon flux","output_desc":"含材料衰减、散射和噪声的逼真数字重建 X-ray/fluoroscopy","output_en":"Photorealistic synthetic fluoroscopy / Digitally Reconstructed Radiograph (DRR) with physical scatter and noise","form_title":"核心公式 · 材料感知 Beer–Lambert 投影、散射与噪声成像","form_title_en":"Core Formalism · Polychromatic Beer–Lambert Material Attenuation Integral + Learned Scatter & Quantum/Electronic Noise","nodes":[{"name":"CT volume","desc":"HU 体积与可选器械/植入物模型","name_en":"CT volume","desc_en":"Ingests volumetric 3d ct scan, c-arm source–detector geometry, x-ray spectrum e, and photon flux and prepares initial tensor representations (CT volume)."},{"name":"成像几何与能谱","desc":"源、探测器、姿态、像素尺寸和 X-ray spectrum","name_en":"Stage 02","desc_en":"Executes Stage 02 to extract primary structural features and establish spatial/sequence encoding."},{"name":"3D material-decomposition V-Net","desc":"把 CT 分成空气、软组织和骨等材料概率/体积","name_en":"3D material-decomposition V-Net","desc_en":"Performs 3D material-decomposition V-Net within the core physics informed deep drr simulator computation pathway."},{"name":"材料与能谱感知 ray tracer","desc":"按 Beer–Lambert 衰减积分计算 primary projection 和 beam hardening","name_en":"ray tracer","desc_en":"Performs ray tracer within the core physics informed deep drr simulator computation pathway."},{"name":"2D neural scatter estimator","desc":"从 primary/相关物理量预测低频散射成分，训练靶来自 Monte Carlo","name_en":"2D neural scatter estimator","desc_en":"Performs 2D neural scatter estimator within the core physics informed deep drr simulator computation pathway."},{"name":"Primary + scatter 合成","desc":"在探测器域组合直接光子与散射信号","name_en":"Primary + scatter","desc_en":"Performs Primary + scatter within the core physics informed deep drr simulator computation pathway."},{"name":"解析噪声注入","desc":"按 photon statistics 与电子噪声生成曝光相关随机性","name_en":"noise","desc_en":"Applies noise to project aggregated representations toward the target task head."},{"name":"Realistic DeepDRR","desc":"供 2D/3D 配准、器械检测和导航训练使用","name_en":"Realistic DeepDRR","desc_en":"Produces photorealistic synthetic fluoroscopy / digitally reconstructed radiograph (drr) with physical scatter and noise via Realistic DeepDRR."}],"design_principles":["材料分解由深网络完成，但 primary attenuation 仍由解析射线追踪计算。","用神经网络近似昂贵 Monte Carlo 的低频散射成分。","最后按曝光物理注入噪声，使合成 X-ray 不只是无噪投影。"],"design_principles_en":["Core Hypothesis: Decompose CT voxels into air/soft-tissue/bone/metal via a 3D CNN, integrate analytical mass attenuation across energy spectra, and add CNN-estimated scatter + Poisson noise.","Architectural Delta: Hybrid physics + deep learning forward model that allows models trained purely on synthetic CT projections to transfer zero-shot to real clinical C-arm X-rays.","Mathematical Formalism: Polychromatic Beer–Lambert Material Attenuation Integral + Learned Scatter & Quantum/Electronic Noise."],"med_apps":["可批量生成具有已知 3D 姿态和器械标签的 fluoroscopy，用于 2D/3D 配准与术中模型训练。","材料网络、能谱、散射和噪声任一失配都会造成 synthetic-to-real gap，必须用真实设备逐协议验证。"],"med_apps_en":["Clinical Translation: Foundational simulation engine for training intraoperative 2D/3D registration, surgical tool tracking, and pelvic/spinal landmark detection.","Evidence & Safety Boundary: Core medical projective simulation infrastructure; fidelity still depends on CT slice thickness and accurate C-arm spectrum modeling."],"attrs":{"上一代瓶颈":"简单线积分 DRR 与真实透视在散射、噪声和设备响应上差距大","核心想法":"结合 CT 材料分解、解析射线追踪与学习散射/噪声模型生成逼真 DRR","关键改进":"把物理 forward model 与深度学习散射估计结合，缩小合成到真实域差","医学适配":"为 2D/3D 配准、器械定位和术中导航生成训练数据","适用范围与证据":"医学 X-ray 合成基础设施；仿真质量仍取决于扫描与设备标定"},"attrs_en":{"上一代瓶颈":"Naive monochrome line-integral DRRs lacked polychromatic beam hardening, Compton scatter, and quantum noise, creating a severe sim-to-real gap.","核心想法":"Decompose CT voxels into air/soft-tissue/bone/metal via a 3D CNN, integrate analytical mass attenuation across energy spectra, and add CNN-estimated scatter + Poisson noise.","关键改进":"Hybrid physics + deep learning forward model that allows models trained purely on synthetic CT projections to transfer zero-shot to real clinical C-arm X-rays.","医学适配":"Foundational simulation engine for training intraoperative 2D/3D registration, surgical tool tracking, and pelvic/spinal landmark detection.","适用范围与证据":"Core medical projective simulation infrastructure; fidelity still depends on CT slice thickness and accurate C-arm spectrum modeling."},"paper_title":"DeepDRR: A Catalyst for Machine Learning in Fluoroscopy-Guided Procedures","paper_url":"https://arxiv.org/abs/1803.08606","code_label":"作者/机构官方实现","code_url":"https://github.com/arcadelab/deepdrr","has_code":true,"image":"assets/cd0518172231eefa4319.avif"},{"id":"architecture_model_128_pixelnerf","num":128,"num_str":"128","year":2021,"year_str":"2021","venue":"CVPR","venue_group":"cv","era_group":"era3","title":"pixelNeRF","family_id":"models_neural_fields_2d3d","family_code":"14","family_short":"2D→3D 与神经辐射场","family_en":"2D-to-3D & Neural Fields","family_icon":"XIV","family_label":"2D→3D 与神经场：表示能力、投影一致性和不可辨识性","archetype":"像素对齐图像特征条件化的跨场景 NeRF","archetype_en":"pixel_aligned_feature_conditioned_nerf","accent":"#1F4E79","fig_badge":"Figure 2 · PDF p.4","fig_href":"https://openaccess.thecvf.com/content/CVPR2021/html/Yu_pixelNeRF_Neural_Radiance_Fields_From_One_or_Few_Images_CVPR_2021_paper.html","core_mech":"pixelNeRF 将每个 3D 点与其投影像素的 CNN 特征绑定，使 NeRF 从单场景优化器变为跨场景条件模型。","core_mech_en":"Conditions a coordinate NeRF MLP on pixel-aligned 2D CNN feature vectors projected from 1 or a few input views, turning NeRF from a per-scene optimizer into a feed-forward cross-scene prior.","input_desc":"一张或少量带相机位姿的参考图像，以及目标相机射线","input_en":"1 to K calibrated input images + query 3D point x projected into each input view's camera coordinates","output_desc":"目标视角 RGB 图像和隐式密度/辐射场","output_en":"Feed-forward novel-view rendering and 3D volumetric density field from sparse views","form_title":"核心公式 · 像素对齐图像特征条件化的辐射场渲染","form_title_en":"Core Formalism · Pixel-Aligned View-Space CNN Feature Conditioning of Continuous Radiance Fields","nodes":[{"name":"带 pose 的参考图像","desc":"单视图或少视图，可来自此前未见场景","name_en":"pose","desc_en":"Ingests 1 to k calibrated input images + query 3d point x projected into each input view's camera coordinates and prepares initial tensor representations (pose)."},{"name":"共享 CNN image encoder","desc":"为每张参考图像生成保留空间位置的特征图","name_en":"CNN image encoder","desc_en":"Executes CNN image encoder to extract primary structural features and establish spatial/sequence encoding."},{"name":"目标射线 3D sample points","desc":"沿每个目标像素射线采样 x 与 view direction d","name_en":"objective 3D sample points","desc_en":"Performs objective 3D sample points within the core pixel aligned feature conditioned nerf computation pathway."},{"name":"相机投影与双线性采样","desc":"把 3D 点投到每张参考图，读取 pixel-aligned feature","name_en":"projection sampling","desc_en":"Performs projection sampling within the core pixel aligned feature conditioned nerf computation pathway."},{"name":"Feature-conditioned NeRF MLP","desc":"联合位置编码、方向和像素特征预测 density 与 color","name_en":"Feature-conditioned NeRF MLP","desc_en":"Performs Feature-conditioned NeRF MLP within the core pixel aligned feature conditioned nerf computation pathway."},{"name":"多视图 feature aggregation","desc":"对各参考视图的中间特征平均/汇聚","name_en":"multi-view feature aggregation","desc_en":"Performs multi-view feature aggregation within the core pixel aligned feature conditioned nerf computation pathway."},{"name":"Differentiable volume rendering","desc":"按透射率和密度沿射线积分颜色","name_en":"Differentiable volume rendering","desc_en":"Applies Differentiable volume rendering to project aggregated representations toward the target task head."},{"name":"新视角输出","desc":"跨场景一次 encoder 前向后即可条件化渲染","name_en":"Novel-View Rendering","desc_en":"Produces feed-forward novel-view rendering and 3d volumetric density field from sparse views via Novel-View Rendering."}],"design_principles":["3D query 点先投影回参考图，读取与该点对齐的局部图像特征。","NeRF MLP 不再只记忆单场景参数，而被 CNN 特征条件化以学习跨场景先验。","一张或少量参考图经前馈编码后即可对新对象推断和渲染。"],"design_principles_en":["Core Hypothesis: Extract a spatial CNN feature pyramid from each input view, project any 3D query point x onto the 2D image planes via camera intrinsics/extrinsics, and feed the bilinearly sampled features into the NeRF MLP.","Architectural Delta: Preserves explicit projective geometry via pixel-aligned local features rather than compressing the input into a single global latent vector.","Mathematical Formalism: Pixel-Aligned View-Space CNN Feature Conditioning of Continuous Radiance Fields."],"med_apps":["启发 sparse-view X-ray、内镜和患者特异解剖场中的图像条件神经场。","少视图未观测区域仍由训练先验补全；医学应用必须区分可见证据与先验生成部分。"],"med_apps_en":["Clinical Translation: Directly inspires sparse-view dual/single X-ray to 3D CT neural field priors (e.g., PerX2CT, DIF-Net).","Evidence & Safety Boundary: Foundational few-view conditional neural field; projective feature occlusion must be adapted for transmission X-ray imaging."],"attrs":{"上一代瓶颈":"原始 NeRF 每个场景都需多视图和长时间优化","核心想法":"从输入图像提取像素对齐特征并条件化 NeRF，使其跨场景推断新对象","关键改进":"学习跨场景先验，实现单张或少量视图的前馈条件化重建","医学适配":"启发 sparse-view X-ray、内镜和解剖场的患者先验建模","适用范围与证据":"少视图 NeRF 基础；自然图像辐射假设不能直接替代医学投影物理"},"attrs_en":{"上一代瓶颈":"Original NeRF had no cross-scene prior and collapsed completely when given only 1–3 input views.","核心想法":"Extract a spatial CNN feature pyramid from each input view, project any 3D query point x onto the 2D image planes via camera intrinsics/extrinsics, and feed the bilinearly sampled features into the NeRF MLP.","关键改进":"Preserves explicit projective geometry via pixel-aligned local features rather than compressing the input into a single global latent vector.","医学适配":"Directly inspires sparse-view dual/single X-ray to 3D CT neural field priors (e.g., PerX2CT, DIF-Net).","适用范围与证据":"Foundational few-view conditional neural field; projective feature occlusion must be adapted for transmission X-ray imaging."},"paper_title":"pixelNeRF: Neural Radiance Fields from One or Few Images","paper_url":"https://openaccess.thecvf.com/content/CVPR2021/html/Yu_pixelNeRF_Neural_Radiance_Fields_From_One_or_Few_Images_CVPR_2021_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/sxyu/pixel-nerf","has_code":true,"image":"assets/6eb4e482023af66574c3.avif"},{"id":"architecture_model_129_instant_ngp","num":129,"num_str":"129","year":2022,"year_str":"2022","venue":"ACM Transactions on Graphics / SIGGRAPH","venue_group":"journal","era_group":"era3","title":"Instant-NGP","family_id":"models_neural_fields_2d3d","family_code":"14","family_short":"2D→3D 与神经辐射场","family_en":"2D-to-3D & Neural Fields","family_icon":"XIV","family_label":"2D→3D 与神经场：表示能力、投影一致性和不可辨识性","archetype":"多分辨率哈希网格编码的小型神经场","archetype_en":"multiresolution_hash_grid_neural_field","accent":"#1F4E79","fig_badge":"Figure 3 · PDF p.4","fig_href":"https://nvlabs.github.io/instant-ngp/","core_mech":"Instant-NGP 的速度来自可学习多分辨率 hash-grid encoding 和空空间跳跃，而不是更深的 NeRF MLP。","core_mech_en":"Replaces fixed sinusoidal positional encodings with a multi-resolution hierarchy of learnable hash tables paired with a tiny fused-CUDA MLP, accelerating neural fields by 100×–1000×.","input_desc":"3D 坐标、观察方向及训练相机射线","input_en":"Continuous 3D coordinate x ∈ R³ mapped across L resolution grids via spatial hashing","output_desc":"快速优化的 density/color 场与实时新视角渲染","output_en":"Concatenated L×F interpolated feature vector decoded in microseconds into density/attenuation/SDF","form_title":"核心公式 · 多分辨率哈希网格插值与轻量神经场查询","form_title_en":"Core Formalism · Multi-Resolution Spatial Hash-Grid Trilinear Interpolation & Tiny MLP Readout","nodes":[{"name":"坐标 x 与方向 d","desc":"沿相机射线采样的连续位置和视角","name_en":"x d","desc_en":"Ingests continuous 3d coordinate x ∈ r³ mapped across l resolution grids via spatial hashing and prepares initial tensor representations (x d)."},{"name":"多分辨率网格 levels","desc":"从粗到细设置指数增长的 3D 网格分辨率","name_en":"mesh levels","desc_en":"Executes mesh levels to extract primary structural features and establish spatial/sequence encoding."},{"name":"可学习 hash tables","desc":"每层网格顶点经空间哈希映射到有限特征表，允许碰撞","name_en":"hash tables","desc_en":"Performs hash tables within the core multiresolution hash grid neural field computation pathway."},{"name":"三线性插值与拼接","desc":"查询邻近哈希特征并跨层拼成位置编码","name_en":"concatenation","desc_en":"Performs concatenation within the core multiresolution hash grid neural field computation pathway."},{"name":"小型 density MLP","desc":"预测 σ 和几何 latent，不需大 Fourier-feature MLP","name_en":"density MLP","desc_en":"Performs density MLP within the core multiresolution hash grid neural field computation pathway."},{"name":"方向条件 color MLP","desc":"用几何 latent 与方向编码预测 RGB","name_en":"color MLP","desc_en":"Performs color MLP within the core multiresolution hash grid neural field computation pathway."},{"name":"Occupancy grid/ray marching","desc":"跳过空空间并动态集中采样到占据区域","name_en":"Occupancy grid/ray marching","desc_en":"Applies Occupancy grid/ray marching to project aggregated representations toward the target task head."},{"name":"Volume rendering","desc":"沿射线累积颜色与透明度，反向更新哈希表和 MLP","name_en":"Volume rendering","desc_en":"Produces concatenated l×f interpolated feature vector decoded in microseconds into density/attenuation/sdf via Volume rendering."}],"design_principles":["多个空间尺度的可学习哈希表同时存储粗结构和细节。","哈希编码把表示容量放在局部特征表中，因此后端 MLP 可以很小。","occupancy skipping 与 GPU 融合内核显著缩短训练和渲染。"],"design_principles_en":["Core Hypothesis: Store trainable feature vectors directly in compact multi-resolution hash tables indexed by voxel corners, letting a tiny 2-layer MLP resolve hash collisions.","Architectural Delta: O(1) multi-scale hash lookup + implicit gradient-based collision resolution + occupancy grid empty-space skipping.","Mathematical Formalism: Multi-Resolution Spatial Hash-Grid Trilinear Interpolation & Tiny MLP Readout."],"med_apps":["可加速 CBCT attenuation field、医学 INR、配准场或内镜场景优化。","哈希碰撞和快速拟合可能隐藏局部伪影；定量衰减场需与投影残差和物理单位共同验证。"],"med_apps_en":["Clinical Translation: Core acceleration engine inside NAF (CBCT), implicit deformable registration, and real-time surgical scene neural fields.","Evidence & Safety Boundary: Essential coordinate-encoding infrastructure; high-frequency hash levels can fit measurement noise if not regularized."],"attrs":{"上一代瓶颈":"坐标 MLP 的 Fourier features 训练慢，细节与速度难兼顾","核心想法":"用多分辨率哈希网格编码坐标并以小 MLP 表示场景","关键改进":"可学习哈希表在不同尺度存储局部特征，使 NeRF 训练缩短到秒/分钟级","医学适配":"加速 CBCT attenuation fields、医学 INR 和配准场优化","适用范围与证据":"高效坐标编码基础；哈希碰撞和显存参数需按医学分辨率调节"},"attrs_en":{"上一代瓶颈":"Deep coordinate MLPs (8 layers × 256 channels) were computationally expensive to evaluate millions of times per optimization step.","核心想法":"Store trainable feature vectors directly in compact multi-resolution hash tables indexed by voxel corners, letting a tiny 2-layer MLP resolve hash collisions.","关键改进":"O(1) multi-scale hash lookup + implicit gradient-based collision resolution + occupancy grid empty-space skipping.","医学适配":"Core acceleration engine inside NAF (CBCT), implicit deformable registration, and real-time surgical scene neural fields.","适用范围与证据":"Essential coordinate-encoding infrastructure; high-frequency hash levels can fit measurement noise if not regularized."},"paper_title":"Instant Neural Graphics Primitives with a Multiresolution Hash Encoding","paper_url":"https://nvlabs.github.io/instant-ngp/","code_label":"作者/机构官方实现","code_url":"https://github.com/NVlabs/instant-ngp","has_code":true,"image":"assets/d5a6e3b635641744a95e.avif"},{"id":"architecture_model_130_mednerf","num":130,"num_str":"130","year":2022,"year_str":"2022","venue":"IEEE EMBC","venue_group":"journal","era_group":"era3","title":"MedNeRF","family_id":"models_neural_fields_2d3d","family_code":"14","family_short":"2D→3D 与神经辐射场","family_en":"2D-to-3D & Neural Fields","family_icon":"XIV","family_label":"2D→3D 与神经场：表示能力、投影一致性和不可辨识性","archetype":"以形状/外观潜变量条件化的生成式医学 NeRF","archetype_en":"generative_latent_conditioned_xray_nerf","accent":"#1F4E79","fig_badge":"Figures 1 and 2 · PDF pp.2–3","fig_href":"https://arxiv.org/abs/2202.01020","core_mech":"MedNeRF 把 NeRF 置于 GAN 式跨病例生成先验中，以 shape/appearance latent 从单 X-ray 合成视角，而非逐场景多视图优化。","core_mech_en":"Adapts GIRAFFE/GRAF 3D-aware generative radiance fields to X-ray projections, disentangling 3D shape and appearance latents to synthesize continuous-angle CT projections from a single X-ray.","input_desc":"训练时为未配对的 2D X-ray 与采样相机位姿；推理时以单张 X-ray 约束患者潜变量","input_en":"Unpaired 2D DRR/X-ray projections during GAN training; a single 2D X-ray during test-time latent inversion","output_desc":"视角可控的 3D-aware CT projection 合成","output_en":"Continuous-angle 3D-aware X-ray projection synthesis across 360° viewpoints","form_title":"核心公式 · 形状—外观潜变量解耦的单 X 线三维反演","form_title_en":"Core Formalism · Generative Shape–Appearance Latent Conditioning & Test-Time Latent Inversion from a Single X-Ray","nodes":[{"name":"2D X-ray distribution","desc":"以真实投影训练，无需每例 3D CT ground truth","name_en":"2D X-ray distribution","desc_en":"Ingests unpaired 2d drr/x-ray projections during gan training; a single 2d x-ray during test-time latent inversion and prepares initial tensor representations (2D X-ray distribution)."},{"name":"Shape/appearance latents","desc":"解耦患者解剖形态与投影外观/体深信息","name_en":"Shape/appearance latents","desc_en":"Executes Shape/appearance latents to extract primary structural features and establish spatial/sequence encoding."},{"name":"Camera pose","desc":"指定目标投影视角和射线","name_en":"Camera pose","desc_en":"Performs Camera pose within the core generative latent conditioned xray nerf computation pathway."},{"name":"Conditional radiance/density MLP","desc":"以 3D 点、方向和潜变量预测连续体密度与辐射/强度","name_en":"Conditional radiance/density MLP","desc_en":"Performs Conditional radiance/density MLP within the core generative latent conditioned xray nerf computation pathway."},{"name":"Differentiable ray integration","desc":"沿每条射线积分得到 X-ray-like 2D projection","name_en":"Differentiable ray integration","desc_en":"Performs Differentiable ray integration within the core generative latent conditioned xray nerf computation pathway."},{"name":"2D adversarial discriminator","desc":"区分合成与真实 X-ray，推动未配对生成训练","name_en":"2D adversarial discriminator","desc_en":"Performs 2D adversarial discriminator within the core generative latent conditioned xray nerf computation pathway."},{"name":"Single-X-ray latent fitting","desc":"以观测投影反求/优化匹配的患者 latent，再改变 pose","name_en":"Single-X-ray latent fitting","desc_en":"Applies Single-X-ray latent fitting to project aggregated representations toward the target task head."},{"name":"3D-aware projections","desc":"从单 X-ray 条件生成不同视角 CT 投影","name_en":"3D-aware projections","desc_en":"Produces continuous-angle 3d-aware x-ray projection synthesis across 360° viewpoints via 3D-aware projections."}],"design_principles":["用连续 NeRF 场表示体内外解剖结构及投影视角变化。","形状与外观/深度潜变量为生成器提供跨患者先验。","以 2D 对抗学习训练投影分布，再从单张 X-ray 约束患者 latent 做新视角合成。"],"design_principles_en":["Core Hypothesis: Train a 3D-aware conditional generative radiance field on 2D X-ray projections with a multi-scale PatchGAN discriminator, then invert latent codes (z_s, z_a) from a single test X-ray.","Architectural Delta: Disentangled shape/appearance conditioning + volumetric feature rendering + test-time latent + generator fine-tuning.","Mathematical Formalism: Generative Shape–Appearance Latent Conditioning & Test-Time Latent Inversion from a Single X-Ray."],"med_apps":["直接任务是单 X-ray 的 3D-aware projection synthesis，可用于视角数据增强研究。","单投影对应无限多 3D 解，未见结构主要来自生成先验；不能把合成视角当作真实 CT 或诊断重建。"],"med_apps_en":["Clinical Translation: Explored for single-view chest and knee X-ray 3D-aware view synthesis and data augmentation.","Evidence & Safety Boundary: Conceptual proof-of-concept; synthesized projections reflect a population GAN prior rather than guaranteed patient-specific 3D tomography."],"attrs":{"上一代瓶颈":"单视图到 3D 高度欠定，原始 NeRF 依赖多视图且建模可见光","核心想法":"以 GAN 条件先验和 NeRF 式场表示从单张 X-ray 生成视角可控的 CT 投影","关键改进":"学习跨病例生成先验并引入医学投影数据生成新视角","医学适配":"直接任务是单 X-ray 的 3D-aware projection synthesis；数据增强与表示学习属于潜在用途","适用范围与证据":"概念性医学 NeRF；生成投影不等价于患者真实 3D 解剖重建"},"attrs_en":{"上一代瓶颈":"Single-view X-ray to 3D reconstruction lacked multi-view supervision, while 2D GANs could not enforce 3D viewpoint consistency.","核心想法":"Train a 3D-aware conditional generative radiance field on 2D X-ray projections with a multi-scale PatchGAN discriminator, then invert latent codes (z_s, z_a) from a single test X-ray.","关键改进":"Disentangled shape/appearance conditioning + volumetric feature rendering + test-time latent + generator fine-tuning.","医学适配":"Explored for single-view chest and knee X-ray 3D-aware view synthesis and data augmentation.","适用范围与证据":"Conceptual proof-of-concept; synthesized projections reflect a population GAN prior rather than guaranteed patient-specific 3D tomography."},"paper_title":"MedNeRF: Medical Neural Radiance Fields for Reconstructing 3D-Aware CT-Projections from a Single X-Ray","paper_url":"https://pubmed.ncbi.nlm.nih.gov/36085823/","code_label":"作者/机构官方实现","code_url":"https://github.com/abrilcf/mednerf","has_code":true,"image":"assets/e7cf565c59a993626f3e.avif"},{"id":"architecture_model_131_endonerf","num":131,"num_str":"131","year":2022,"year_str":"2022","venue":"MICCAI","venue_group":"miccai","era_group":"era3","title":"EndoNeRF","family_id":"models_neural_fields_2d3d","family_code":"14","family_short":"2D→3D 与神经辐射场","family_en":"2D-to-3D & Neural Fields","family_icon":"XIV","family_label":"2D→3D 与神经场：表示能力、投影一致性和不可辨识性","archetype":"时间形变场与 canonical radiance field 的动态内镜 NeRF","archetype_en":"deformable_canonical_endoscopic_nerf","accent":"#1F4E79","fig_badge":"Figure 1 · PDF p.3","fig_href":"https://conferences.miccai.org/2022/papers/353-Paper1091.html","core_mech":"EndoNeRF 以时间条件 deformation MLP 把动态组织映射到 canonical NeRF，并显式利用手术器械 mask。","core_mech_en":"Reconstructs deformable soft-tissue scenes from single-viewpoint stereo robotic endoscopy by pairing a canonical static NeRF with a time-conditioned deformation field and tool occlusion masks.","input_desc":"双目/视频内镜帧、相机位姿、时间戳及手术器械二值 mask","input_en":"Robotic stereo endoscopy video frames, estimated stereo depth maps, timestamps t, and binary surgical tool masks","output_desc":"动态软组织的 canonical 几何、深度和新视角内镜图像","output_en":"Tool-free dynamic 3D soft-tissue surface geometry, depth maps, and novel-view renderings","form_title":"核心公式 · 动态内镜场到 canonical 空间的形变与时变渲染","form_title_en":"Core Formalism · Time-Conditioned Deformation Field Δx(x, t) Mapping Dynamic Tissue to a Canonical NeRF + Tool-Guided Ray Sampling","nodes":[{"name":"内镜视频/双目帧","desc":"带相机 pose 与时间 t 的 RGB 观测","name_en":"endoscopy","desc_en":"Ingests robotic stereo endoscopy video frames, estimated stereo depth maps, timestamps t, and binary surgical tool masks and prepares initial tensor representations (endoscopy)."},{"name":"Tool masks","desc":"标记器械遮挡区域，避免污染组织场优化","name_en":"Tool masks","desc_en":"Executes Tool masks to extract primary structural features and establish spatial/sequence encoding."},{"name":"Mask-guided ray sampling","desc":"主要从可见组织像素采样训练射线","name_en":"Mask-guided ray sampling","desc_en":"Performs Mask-guided ray sampling within the core deformable canonical endoscopic nerf computation pathway."},{"name":"Time-conditioned deformation MLP","desc":"将观察时刻点 x,t 映射到共享 canonical 坐标 x+Δx(x,t)","name_en":"Time-conditioned deformation MLP","desc_en":"Performs Time-conditioned deformation MLP within the core deformable canonical endoscopic nerf computation pathway."},{"name":"Canonical NeRF","desc":"在规范空间预测 density 与 view-dependent color","name_en":"Canonical NeRF","desc_en":"Performs Canonical NeRF within the core deformable canonical endoscopic nerf computation pathway."},{"name":"Differentiable volume rendering","desc":"沿变形后的射线积分 RGB 和 depth","name_en":"Differentiable volume rendering","desc_en":"Performs Differentiable volume rendering within the core deformable canonical endoscopic nerf computation pathway."},{"name":"Photometric/depth regularization","desc":"用可见组织像素和双目信息约束动态场","name_en":"Photometric/depth regularization","desc_en":"Applies Photometric/depth regularization to project aggregated representations toward the target task head."},{"name":"动态组织重建","desc":"生成新视角、深度和时序一致场景","name_en":"dynamic reconstruction","desc_en":"Produces tool-free dynamic 3d soft-tissue surface geometry, depth maps, and novel-view renderings via dynamic reconstruction."}],"design_principles":["把动态手术场景分成时间形变场和共享 canonical radiance field。","所有时刻先逆变形到同一规范空间，再查询密度和颜色。","器械 mask 引导射线采样，避免把临时遮挡建模成组织。"],"design_principles_en":["Core Hypothesis: Warp 3D points at time t via a displacement MLP Δx(x, t) into a shared canonical radiance field while masking out rays occluded by surgical instruments.","Architectural Delta: Tool-mask-guided importance ray sampling + stereo depth cue supervision + canonical-plus-deformation spatiotemporal factorization.","Mathematical Formalism: Time-Conditioned Deformation Field Δx(x, t) Mapping Dynamic Tissue to a Canonical NeRF + Tool-Guided Ray Sampling."],"med_apps":["可用于微创手术软组织重建、导航视图合成和动态场景分析。","镜面反射、烟雾、快速非刚性运动和器械 mask 误差会破坏亮度恒定与 canonical 对应假设。"],"med_apps_en":["Clinical Translation: Pioneered neural field 3D soft-tissue reconstruction for DaVinci robotic prostatectomy and minimally invasive surgery.","Evidence & Safety Boundary: Landmark surgical NeRF baseline; cannot handle topological tissue cutting/resection and requires minutes of offline optimization (later accelerated by EndoGaussian)."],"attrs":{"上一代瓶颈":"静态 NeRF 无法处理组织形变、器械遮挡和稀疏内镜视角","核心想法":"用可变形 NeRF 联合建模内镜场景外观、几何和手术组织动态","关键改进":"通过时间条件形变场与遮挡掩膜合成动态手术新视角","医学适配":"用于微创手术场景重建、导航和动态视图合成","适用范围与证据":"动态内镜 NeRF 早期代表；拓扑变化、镜面反射和临床标定仍困难"},"attrs_en":{"上一代瓶颈":"Robotic surgical scenes violate static NeRF assumptions due to non-rigid tissue deformation, smoke/specularities, and severe surgical instrument occlusion.","核心想法":"Warp 3D points at time t via a displacement MLP Δx(x, t) into a shared canonical radiance field while masking out rays occluded by surgical instruments.","关键改进":"Tool-mask-guided importance ray sampling + stereo depth cue supervision + canonical-plus-deformation spatiotemporal factorization.","医学适配":"Pioneered neural field 3D soft-tissue reconstruction for DaVinci robotic prostatectomy and minimally invasive surgery.","适用范围与证据":"Landmark surgical NeRF baseline; cannot handle topological tissue cutting/resection and requires minutes of offline optimization (later accelerated by EndoGaussian)."},"paper_title":"EndoNeRF: Neural Radiance Fields for Endoscopic View Synthesis","paper_url":"https://conferences.miccai.org/2022/papers/353-Paper1091.html","code_label":"作者/机构官方实现","code_url":"https://github.com/med-air/EndoNeRF","has_code":true,"image":"assets/ec8d0a4e84a315b411de.avif"},{"id":"architecture_model_132_graphsage","num":132,"num_str":"132","year":2017,"year_str":"2017","venue":"NeurIPS","venue_group":"ml","era_group":"era2","title":"GraphSAGE","family_id":"models_graph_neural_networks","family_code":"15","family_short":"图神经网络与医学拓扑","family_en":"Graph & Mesh Networks","family_icon":"XV","family_label":"图神经网络：当边、拓扑和关系本身就是医学信息","archetype":"邻居采样与可学习聚合的归纳式 GNN","archetype_en":"inductive_neighbor_sampling_graphsage","accent":"#5B3F8C","fig_badge":"Figure 1 · PDF p.2","fig_href":"https://proceedings.neurips.cc/paper/2017/hash/5dd9db5e033da9c6fb5ba83c7a7ebea9-Abstract.html","core_mech":"GraphSAGE 学的是可应用到新节点的聚合器，并用固定邻居采样实现归纳式 mini-batch GNN。","core_mech_en":"Inductive graph representation learning that samples fixed-size K-hop neighborhoods and applies learnable aggregator functions (mean, LSTM, pooling) to generalize to unseen nodes.","input_desc":"图 G=(V,E)、节点特征和待编码节点批次","input_en":"Graph G=(V,E), node attribute features x_v, and mini-batch of target nodes","output_desc":"可泛化到未见节点的 node embeddings 或节点预测","output_en":"Inductive node embeddings z_v generalizable to newly arriving unseen nodes or whole slides","form_title":"核心公式 · 采样邻域聚合的归纳式节点更新","form_title_en":"Core Formalism · Fixed-Size Neighborhood Sampling & Concatenated Self-vs-Neighbor Inductive Aggregation","nodes":[{"name":"节点、边与特征","desc":"可为患者相似图、细胞图或血管网络","name_en":"、 feature","desc_en":"Ingests graph g=(v,e), node attribute features x_v, and mini-batch of target nodes and prepares initial tensor representations (、 feature)."},{"name":"Fixed-size neighbor sampler","desc":"每层为批内节点采样固定数量一跳邻居","name_en":"Fixed-size neighbor sampler","desc_en":"Executes Fixed-size neighbor sampler to extract primary structural features and establish spatial/sequence encoding."},{"name":"邻居表示集合","desc":"上一层 embedding 形成局部无序 multiset","name_en":"Stage 03","desc_en":"Performs Stage 03 within the core inductive neighbor sampling graphsage computation pathway."},{"name":"Mean/LSTM/pooling aggregator","desc":"可学习地把邻居集合汇成单一向量","name_en":"Mean/LSTM/pooling aggregator","desc_en":"Performs Mean/LSTM/pooling aggregator within the core inductive neighbor sampling graphsage computation pathway."},{"name":"Self-neighbor concat + transform","desc":"拼接自身与邻居向量，线性变换、非线性并归一化","name_en":"Self-neighbor concat + transform","desc_en":"Performs Self-neighbor concat + transform within the core inductive neighbor sampling graphsage computation pathway."},{"name":"K-layer receptive field","desc":"重复采样聚合扩展到 K-hop 邻域","name_en":"K-layer receptive field","desc_en":"Applies K-layer receptive field to project aggregated representations toward the target task head."},{"name":"归纳节点 embedding","desc":"接监督 head 或无监督随机游走损失","name_en":"embedding","desc_en":"Produces inductive node embeddings z_v generalizable to newly arriving unseen nodes or whole slides via embedding."}],"design_principles":["学习邻居聚合函数，而不是为训练图中的每个节点单独记 embedding。","固定 fan-out 采样把大图训练转为可控 mini-batch 计算。","自身与邻居表示显式拼接，使中心信息与局部上下文分工。"],"design_principles_en":["Core Hypothesis: Learn aggregator functions over uniformly sampled fixed-size k-hop neighborhoods while explicitly concatenating a node's own previous state with its aggregated neighborhood.","Architectural Delta: Mini-batch neighborhood sampling bounding memory footprint + explicit self-feature concatenation preserving node identity against over-smoothing.","Mathematical Formalism: Fixed-Size Neighborhood Sampling & Concatenated Self-vs-Neighbor Inductive Aggregation."],"med_apps":["适用于患者相似图、病理细胞图、血管树和大规模生物网络。","采样会丢失稀有关键邻居，且临床图边的构造误差与群体偏差会被多层传播。"],"med_apps_en":["Clinical Translation: Enables scalable inductive training on million-cell whole-slide pathology graphs and dynamic clinical EHR cohorts.","Evidence & Safety Boundary: Essential scalable inductive GNN; uniform random neighbor sampling can miss rare diagnostic hub cells if degree distributions are skewed."],"attrs":{"上一代瓶颈":"谱 GCN 偏传导式且全邻居计算难扩展到新节点和大图","核心想法":"通过采样固定数量邻居并聚合其特征生成节点嵌入","关键改进":"可学习聚合器支持 mini-batch、归纳迁移与未见节点","医学适配":"用于患者相似图、细胞图、血管树和大规模病理图","适用范围与证据":"归纳 GNN 基础；邻居采样和构图偏差会直接影响医学结论"},"attrs_en":{"上一代瓶颈":"Full-batch transductive GCNs required holding the entire graph Laplacian in memory and could not embed unseen test nodes without retraining.","核心想法":"Learn aggregator functions over uniformly sampled fixed-size k-hop neighborhoods while explicitly concatenating a node's own previous state with its aggregated neighborhood.","关键改进":"Mini-batch neighborhood sampling bounding memory footprint + explicit self-feature concatenation preserving node identity against over-smoothing.","医学适配":"Enables scalable inductive training on million-cell whole-slide pathology graphs and dynamic clinical EHR cohorts.","适用范围与证据":"Essential scalable inductive GNN; uniform random neighbor sampling can miss rare diagnostic hub cells if degree distributions are skewed."},"paper_title":"Inductive Representation Learning on Large Graphs","paper_url":"https://proceedings.neurips.cc/paper/2017/hash/5dd9db5e033da9c6fb5ba83c7a7ebea9-Abstract.html","code_label":"作者/机构官方实现","code_url":"https://github.com/williamleif/GraphSAGE","has_code":true,"image":"assets/cfd45dfaaf29a4fe75b2.avif"},{"id":"architecture_model_133_graphormer","num":133,"num_str":"133","year":2021,"year_str":"2021","venue":"NeurIPS","venue_group":"ml","era_group":"era3","title":"Graphormer","family_id":"models_graph_neural_networks","family_code":"15","family_short":"图神经网络与医学拓扑","family_en":"Graph & Mesh Networks","family_icon":"XV","family_label":"图神经网络：当边、拓扑和关系本身就是医学信息","archetype":"以中心性、最短路径和边编码注入结构偏置的全局图 Transformer","archetype_en":"structural_bias_global_graph_transformer","accent":"#5B3F8C","fig_badge":"Figure 1 · PDF p.3","fig_href":"https://proceedings.neurips.cc/paper/2021/hash/f1c1592588411002af340cbaedd6fc33-Abstract.html","core_mech":"Graphormer 不做局部消息传递堆叠，而在全局 attention logits 中显式加入最短路径和边特征偏置。","core_mech_en":"Enables global all-pair Transformer self-attention over graphs by injecting degree centrality encodings into nodes and shortest-path spatial + edge-feature biases into attention logits.","input_desc":"带节点属性和边属性的图","input_en":"Attributed graph G=(V,E) with node features, edge features, node degrees, and all-pair shortest-path distances","output_desc":"节点上下文表示与 graph-level prediction","output_en":"Globally contextualized node representations and graph-level predictions","form_title":"核心公式 · 中心性、最短路与边编码注入图注意力","form_title_en":"Core Formalism · Graph Structural Bias Injection into Self-Attention Logits: (q_i k_j^T)/√d + b_{φ(v_i,v_j)} + c_{ij}","nodes":[{"name":"Attributed graph","desc":"节点特征、边特征与邻接结构","name_en":"Attributed graph","desc_en":"Ingests attributed graph g=(v,e) with node features, edge features, node degrees, and all-pair shortest-path distances and prepares initial tensor representations (Attributed graph)."},{"name":"Node feature embedding","desc":"把离散/连续节点属性映射到 Transformer 维度","name_en":"Node feature embedding","desc_en":"Executes Node feature embedding to extract primary structural features and establish spatial/sequence encoding."},{"name":"Centrality encoding","desc":"入度/出度 embedding 加到节点 token，表达节点重要性","name_en":"Centrality encoding","desc_en":"Performs Centrality encoding within the core structural bias global graph transformer computation pathway."},{"name":"Shortest-path spatial encoding","desc":"节点对最短路径距离作为 attention bias","name_en":"Shortest-path spatial encoding","desc_en":"Performs Shortest-path spatial encoding within the core structural bias global graph transformer computation pathway."},{"name":"Edge encoding","desc":"聚合最短路径上的边特征并注入节点对注意力","name_en":"Edge encoding","desc_en":"Performs Edge encoding within the core structural bias global graph transformer computation pathway."},{"name":"Virtual graph token","desc":"与所有节点交互以收集整图表示","name_en":"Virtual graph token","desc_en":"Performs Virtual graph token within the core structural bias global graph transformer computation pathway."},{"name":"Global self-attention blocks","desc":"每对节点可直接交互，同时加结构 bias","name_en":"Global self-attention blocks","desc_en":"Applies Global self-attention blocks to project aggregated representations toward the target task head."},{"name":"Graph prediction head","desc":"读取 graph token 或节点表示完成图级/节点级任务","name_en":"Graph prediction head","desc_en":"Produces globally contextualized node representations and graph-level predictions via Graph prediction head."}],"design_principles":["保留全局 self-attention，但用图结构编码补回 Transformer 缺少的拓扑归纳偏置。","中心性编码作用于单节点，最短路径距离和边编码作用于节点对。","virtual graph token 作为可学习全局汇聚器，避免手工 mean pooling。"],"design_principles_en":["Core Hypothesis: Allow every node to attend to every other node globally while encoding graph topology directly as additive biases inside the softmax attention matrix.","Architectural Delta: Centrality encoding + Shortest-Path Distance (SPD) spatial bias + multi-hop edge feature encoding along shortest paths.","Mathematical Formalism: Graph Structural Bias Injection into Self-Attention Logits: (q_i k_j^T)/√d + b_{φ(v_i,v_j)} + c_{ij}."],"med_apps":["适用于分子、脑连接组、细胞相互作用和患者关系图等全局依赖任务。","全局注意力随节点数二次增长，且最短路径/构图规则可能把技术性边误当生物学关系。"],"med_apps_en":["Clinical Translation: Excels on molecular property prediction, drug discovery, protein structure, and compact brain region connectome graphs (~100–500 ROIs).","Evidence & Safety Boundary: Leading Graph Transformer; O(N²) all-pair attention and shortest-path computation prohibit direct application to 100,000-node WSI cell graphs."],"attrs":{"上一代瓶颈":"普通 Transformer 忽略图拓扑，消息传递 GNN 长程传播易过平滑","核心想法":"把最短路径距离、节点中心性和边特征作为 attention bias 注入 Transformer","关键改进":"以结构编码让全局 self-attention 保留图归纳偏置","医学适配":"适用于分子、细胞相互作用、脑网络和患者关系图","适用范围与证据":"图 Transformer 代表；O(N²) 成本和拓扑构造限制大医学图扩展"},"attrs_en":{"上一代瓶颈":"Message-passing GNNs are bounded by the 1-WL isomorphism test and suffer from over-squashing across long graph bottlenecks.","核心想法":"Allow every node to attend to every other node globally while encoding graph topology directly as additive biases inside the softmax attention matrix.","关键改进":"Centrality encoding + Shortest-Path Distance (SPD) spatial bias + multi-hop edge feature encoding along shortest paths.","医学适配":"Excels on molecular property prediction, drug discovery, protein structure, and compact brain region connectome graphs (~100–500 ROIs).","适用范围与证据":"Leading Graph Transformer; O(N²) all-pair attention and shortest-path computation prohibit direct application to 100,000-node WSI cell graphs."},"paper_title":"Do Transformers Really Perform Bad for Graph Representation?","paper_url":"https://papers.nips.cc/paper/2021/file/f1c1592588411002af340cbaedd6fc33-Paper.pdf","code_label":"作者/机构官方实现","code_url":"https://github.com/microsoft/Graphormer","has_code":true,"image":"assets/12712389bae30220ea9a.avif"},{"id":"architecture_model_134_voxel2mesh","num":134,"num_str":"134","year":2020,"year_str":"2020","venue":"MICCAI","venue_group":"miccai","era_group":"era3","title":"Voxel2Mesh","family_id":"models_graph_neural_networks","family_code":"15","family_short":"图神经网络与医学拓扑","family_en":"Graph & Mesh Networks","family_icon":"XV","family_label":"图神经网络：当边、拓扑和关系本身就是医学信息","archetype":"3D 体素特征驱动的显式网格形变与自适应细分","archetype_en":"voxel_guided_progressive_mesh_gcn","accent":"#5B3F8C","fig_badge":"Figure 1 · PDF p.2","fig_href":"https://arxiv.org/abs/1912.03681","core_mech":"Voxel2Mesh 不先分割再 marching cubes，而由 3D 体素特征逐级驱动球形模板的 GCN 形变和细分。","core_mech_en":"Deforms a sphere template mesh progressively into a target 3D anatomical surface via Graph Convolutions conditioned on 3D CNN voxel features sampled at mesh vertices.","input_desc":"3D 医学体积与初始球形模板 mesh","input_en":"3D medical imaging volume (CT/MRI/EM) + initial genus-0 spherical template mesh","output_desc":"器官表面的顶点、三角面与可选体素分割","output_en":"Explicit 3D anatomical triangle mesh (vertices V, faces F) and auxiliary voxel segmentation","form_title":"核心公式 · 体素特征采样驱动的逐级网格变形","form_title_en":"Core Formalism · Learned Neighborhood Sampling of 3D Voxel Features Driving Progressive GCN Mesh Deformation & Unpooling","nodes":[{"name":"3D volume","desc":"CT/MRI 体素网格","name_en":"3D volume","desc_en":"Ingests 3d medical imaging volume (ct/mri/em) + initial genus-0 spherical template mesh and prepares initial tensor representations (3D volume)."},{"name":"3D CNN/U-Net encoder","desc":"提取从粗到细的体素特征图","name_en":"3D CNN/U-Net encoder","desc_en":"Executes 3D CNN/U-Net encoder to extract primary structural features and establish spatial/sequence encoding."},{"name":"初始 sphere mesh","desc":"固定拓扑的低分辨率顶点与三角面","name_en":"sphere mesh","desc_en":"Performs sphere mesh within the core voxel guided progressive mesh gcn computation pathway."},{"name":"Voxel-to-vertex feature sampling","desc":"按当前顶点坐标从体素特征图插值局部特征","name_en":"Voxel-to-vertex feature sampling","desc_en":"Performs Voxel-to-vertex feature sampling within the core voxel guided progressive mesh gcn computation pathway."},{"name":"Graph convolution deformation","desc":"结合邻接顶点与采样体素特征预测顶点位移","name_en":"Graph convolution deformation","desc_en":"Performs Graph convolution deformation within the core voxel guided progressive mesh gcn computation pathway."},{"name":"Adaptive mesh unpooling","desc":"逐级增加顶点并保留拓扑邻接，精化复杂表面","name_en":"Adaptive mesh unpooling","desc_en":"Performs Adaptive mesh unpooling within the core voxel guided progressive mesh gcn computation pathway."},{"name":"Surface + topology losses","desc":"Chamfer/point、edge、Laplacian 与法向等约束形状和网格质量","name_en":"Surface + topology losses","desc_en":"Applies Surface + topology losses to project aggregated representations toward the target task head."},{"name":"显式器官 mesh","desc":"直接输出可渲染、可测量的表面","name_en":"explicit organ mesh","desc_en":"Produces explicit 3d anatomical triangle mesh (vertices v, faces f) and auxiliary voxel segmentation via explicit organ mesh."}],"design_principles":["从简单球面模板出发，通过图卷积直接预测表面顶点位移。","每一级按顶点坐标从 3D CNN 特征图采样，使体素证据驱动 mesh。","逐级 unpool 增加网格分辨率，并以几何正则保持三角面质量。"],"design_principles_en":["Core Hypothesis: Sample multi-scale 3D U-Net encoder/decoder features directly at current 3D vertex coordinates and deform the mesh coarse-to-fine via GCN blocks.","Architectural Delta: Learned neighborhood voxel sampling + adaptive edge subdivision (unpooling) + normal/Laplacian/edge-length geometric regularizers.","Mathematical Formalism: Learned Neighborhood Sampling of 3D Voxel Features Driving Progressive GCN Mesh Deformation & Unpooling."],"med_apps":["可直接输出心脏、肝脏等器官的显式表面，便于形态测量和物理模拟。","固定球形拓扑难表达孔洞或拓扑变化；边界弱、病灶突出和薄结构可能被平滑正则拉回。"],"med_apps_en":["Clinical Translation: Produces smooth, genus-zero topological meshes for liver, hippocampus, synaptic junctions, and cardiac chambers.","Evidence & Safety Boundary: Strong explicit 3D surface baseline; fixed sphere topology cannot model organs with holes or variable branching without template modification."],"attrs":{"上一代瓶颈":"体素分割边界台阶化且高分辨率 3D 预测内存昂贵","核心想法":"从球形初始网格出发，用体素特征引导图卷积逐级形变和加密 mesh","关键改进":"联合体素编码与显式 mesh 顶点/拓扑学习直接输出表面","医学适配":"用于心脏、肝脏等器官可解释表面重建","适用范围与证据":"医学 mesh 深度学习代表；固定拓扑难处理孔洞和复杂拓扑变化"},"attrs_en":{"上一代瓶颈":"Voxel segmentation followed by Marching Cubes produced staircase artifacts, topological holes, and disconnected floating islands.","核心想法":"Sample multi-scale 3D U-Net encoder/decoder features directly at current 3D vertex coordinates and deform the mesh coarse-to-fine via GCN blocks.","关键改进":"Learned neighborhood voxel sampling + adaptive edge subdivision (unpooling) + normal/Laplacian/edge-length geometric regularizers.","医学适配":"Produces smooth, genus-zero topological meshes for liver, hippocampus, synaptic junctions, and cardiac chambers.","适用范围与证据":"Strong explicit 3D surface baseline; fixed sphere topology cannot model organs with holes or variable branching without template modification."},"paper_title":"Voxel2Mesh: 3D Mesh Model Generation from Volumetric Data","paper_url":"https://doi.org/10.1007/978-3-030-59719-1_30","code_label":"作者/机构官方实现","code_url":"https://github.com/cvlab-epfl/voxel2mesh","has_code":true,"image":"assets/c4ecce21ae0762cdfa72.avif"},{"id":"architecture_model_135_vox2cortex","num":135,"num_str":"135","year":2022,"year_str":"2022","venue":"CVPR","venue_group":"cv","era_group":"era3","title":"Vox2Cortex","family_id":"models_graph_neural_networks","family_code":"15","family_short":"图神经网络与医学拓扑","family_en":"Graph & Mesh Networks","family_icon":"XV","family_label":"图神经网络：当边、拓扑和关系本身就是医学信息","archetype":"3D MRI 体特征与图卷积联合的多皮层表面形变","archetype_en":"coupled_multi_surface_cortical_gcn","accent":"#5B3F8C","fig_badge":"Figure 3 · PDF p.4","fig_href":"https://openaccess.thecvf.com/content/CVPR2022/html/Bongratz_Vox2Cortex_Fast_Explicit_Reconstruction_of_Cortical_Surfaces_From_3D_MRI_CVPR_2022_paper.html","core_mech":"Vox2Cortex 将 3D U-Net 特征在顶点处采样，并以 GCN 同时形变四个互相关联的皮层表面。","core_mech_en":"Jointly deforms four topologically coupled brain cortical hemisphere templates (left/right white and pial surfaces) in seconds using 3D U-Net voxel features and Residual GCNs.","input_desc":"3D T1-weighted brain MRI 与四个初始皮层模板表面","input_en":"3D T1-weighted brain MRI + 4 initialized template meshes (~168,000 total vertices)","output_desc":"左右半球 white 与 pial 四个显式 cortical meshes","output_en":"4 high-resolution, topologically genus-zero cortical meshes (LH/RH white matter and pial surfaces)","form_title":"核心公式 · 保持模板拓扑的多皮层表面联合形变","form_title_en":"Core Formalism · Coupled Multi-Surface Cortical Mesh Deformation via Continuous ODE-like GCN Steps & Curvature Regularization","nodes":[{"name":"3D brain MRI","desc":"体素强度提供皮层边界和解剖上下文","name_en":"3D brain MRI","desc_en":"Ingests 3d t1-weighted brain mri + 4 initialized template meshes (~168,000 total vertices) and prepares initial tensor representations (3D brain MRI)."},{"name":"3D U-Net feature pyramid","desc":"提取多尺度体素特征并可辅助体素分割","name_en":"3D U-Net feature pyramid","desc_en":"Executes 3D U-Net feature pyramid to extract primary structural features and establish spatial/sequence encoding."},{"name":"四个初始 cortical meshes","desc":"左右 white/pial 表面具有固定且对应的拓扑","name_en":"cortical meshes","desc_en":"Performs cortical meshes within the core coupled multi surface cortical gcn computation pathway."},{"name":"Trilinear feature sampling","desc":"在每个 mesh 顶点处查询 U-Net 多尺度特征","name_en":"Trilinear feature sampling","desc_en":"Performs Trilinear feature sampling within the core coupled multi surface cortical gcn computation pathway."},{"name":"Graph convolution blocks","desc":"聚合局部 mesh 邻域与体素证据，预测各表面顶点位移","name_en":"Graph convolution blocks","desc_en":"Performs Graph convolution blocks within the core coupled multi surface cortical gcn computation pathway."},{"name":"Coarse-to-fine deformation stages","desc":"多次更新四表面并保持 white/pial 对应关系","name_en":"Coarse-to-fine deformation stages","desc_en":"Performs Coarse-to-fine deformation stages within the core coupled multi surface cortical gcn computation pathway."},{"name":"Surface/normal/edge/inter-surface losses","desc":"约束几何精度、网格质量和皮层层间结构","name_en":"Surface/normal/edge/inter-surface losses","desc_en":"Applies Surface/normal/edge/inter-surface losses to project aggregated representations toward the target task head."},{"name":"White/pial cortical surfaces","desc":"快速显式输出，可计算厚度和皮层形态","name_en":"White/pial cortical surfaces","desc_en":"Produces 4 high-resolution, topologically genus-zero cortical meshes (lh/rh white matter and pial surfaces) via White/pial cortical surfaces."}],"design_principles":["用 3D U-Net 提供体素域多尺度证据，用 GCN 维护显式皮层 mesh 拓扑。","同时形变左右半球的 white 与 pial 表面，而非独立逐表面重建。","粗到细顶点更新和表面几何正则使输出可直接用于皮层测量。"],"design_principles_en":["Core Hypothesis: Drive 4 coupled template meshes simultaneously through multiple Euler-like deformation steps conditioned on multi-scale 3D CNN features sampled at vertex coordinates.","Architectural Delta: Inter- and intra-surface geometric constraints preventing white/pial self-intersection + 1,000× speedup (<20 seconds vs. hours in FreeSurfer).","Mathematical Formalism: Coupled Multi-Surface Cortical Mesh Deformation via Continuous ODE-like GCN Steps & Curvature Regularization."],"med_apps":["面向脑 MRI white/pial surface extraction，可直接计算皮层厚度和表面形态。","模板拓扑和训练人群先验可能限制异常皮层、术后缺损或严重畸形；需检查自交、拓扑和亚毫米偏差。"],"med_apps_en":["Clinical Translation: High-speed neuroimaging baseline for cortical thickness analysis, Alzheimer's atrophy tracking, and large biobank processing.","Evidence & Safety Boundary: Domain-specialized explicit surface landmark; severe brain tumors or strokes that disrupt normal cortical topology remain challenging."],"attrs":{"上一代瓶颈":"传统皮层重建流程耗时且多阶段，通用 mesh 模型难满足嵌套皮层拓扑","核心想法":"由 3D MRI 体素特征驱动多表面 mesh deformation，同时预测皮层内外表面","关键改进":"联合 U-Net 体特征、图卷积和表面正则快速重建多层皮层","医学适配":"用于脑 MRI white/pial cortical surface extraction","适用范围与证据":"显式神经解剖表面强基线；异常 anatomy 与跨扫描协议仍具挑战"},"attrs_en":{"上一代瓶颈":"Classical FreeSurfer cortical surface reconstruction required 4–8 hours of CPU optimization per scan, while voxel segmenters failed to prevent self-intersections in tight sulci.","核心想法":"Drive 4 coupled template meshes simultaneously through multiple Euler-like deformation steps conditioned on multi-scale 3D CNN features sampled at vertex coordinates.","关键改进":"Inter- and intra-surface geometric constraints preventing white/pial self-intersection + 1,000× speedup (<20 seconds vs. hours in FreeSurfer).","医学适配":"High-speed neuroimaging baseline for cortical thickness analysis, Alzheimer's atrophy tracking, and large biobank processing.","适用范围与证据":"Domain-specialized explicit surface landmark; severe brain tumors or strokes that disrupt normal cortical topology remain challenging."},"paper_title":"Vox2Cortex: Fast Explicit Reconstruction of Cortical Surfaces from 3D MRI","paper_url":"https://openaccess.thecvf.com/content/CVPR2022/html/Bongratz_Vox2Cortex_Fast_Explicit_Reconstruction_of_Cortical_Surfaces_From_3D_MRI_CVPR_2022_paper.html","code_label":"作者/机构官方实现","code_url":"https://github.com/ai-med/Vox2Cortex","has_code":true,"image":"assets/fe3ed684cf120b7103b1.avif"},{"id":"architecture_model_136_gru","num":136,"num_str":"136","year":2014,"year_str":"2014","venue":"EMNLP","venue_group":"journal","era_group":"era1","title":"GRU","family_id":"models_temporal_biomedical","family_code":"16","family_short":"生理时序与波形模型","family_en":"Temporal Physiological AI","family_icon":"XVI","family_label":"生理时序模型：门控、膨胀卷积、长状态与领域预训练","archetype":"reset/update 双门控的循环状态更新","archetype_en":"dual_gate_recurrent_unit","accent":"#6B5700","fig_badge":"Figures 1 and 2 · PDF pp.2–3","fig_href":"https://aclanthology.org/D14-1179/","core_mech":"GRU 用 reset/update 两门和单一隐藏状态完成记忆更新，结构比 LSTM 更简洁。","core_mech_en":"Simplifies gated recurrence by merging cell and hidden states into a single vector h_t interpolated via an update gate z_t and a reset gate r_t.","input_desc":"时间序列 xt 与上一隐藏状态 ht−1","input_en":"Sequential physiological or clinical feature vector x_t and previous hidden state h_{t-1}","output_desc":"当前隐藏状态 ht、全序列表示或逐时刻预测","output_en":"Updated hidden state h_t or sequence prediction","form_title":"核心公式 · 更新门与重置门控制的时序状态递推","form_title_en":"Core Formalism · Coupled Update Gate Interpolation h_t = (1−z_t) ⊙ h_{t-1} + z_t ⊙ h̃_t & Reset Gate","nodes":[{"name":"xt 与 ht−1","desc":"当前观测和历史记忆","name_en":"xt ht−1","desc_en":"Ingests sequential physiological or clinical feature vector x_t and previous hidden state h_{t-1} and prepares initial tensor representations (xt ht−1)."},{"name":"Reset gate rt","desc":"sigmoid(Wr xt+Ur ht−1)，控制候选状态读取多少历史","name_en":"Reset gate rt","desc_en":"Executes Reset gate rt to extract primary structural features and establish spatial/sequence encoding."},{"name":"Update gate zt","desc":"sigmoid(Wz xt+Uz ht−1)，控制保留旧状态与写入新候选的比例","name_en":"Update gate zt","desc_en":"Performs Update gate zt within the core dual gate recurrent unit computation pathway."},{"name":"Candidate state h̃t","desc":"tanh(Wh xt+Uh(rt⊙ht−1))","name_en":"Candidate state h̃t","desc_en":"Performs Candidate state h̃t within the core dual gate recurrent unit computation pathway."},{"name":"Gated interpolation","desc":"以 zt 在 ht−1 与 h̃t 之间逐维插值形成 ht","name_en":"Gated interpolation","desc_en":"Performs Gated interpolation within the core dual gate recurrent unit computation pathway."},{"name":"共享时间递归","desc":"ht 传到下一时刻，参数跨时间共享","name_en":"Stage 06","desc_en":"Applies Stage 06 to project aggregated representations toward the target task head."},{"name":"序列任务 head","desc":"读取最后状态、池化状态或逐时刻状态完成分类/预测","name_en":"sequence head","desc_en":"Produces updated hidden state h_t or sequence prediction via sequence head."}],"design_principles":["reset gate 决定计算候选状态时遗忘多少过去。","update gate 直接插值旧状态与候选状态，为梯度和长期记忆提供短路径。","只有一个隐藏状态和两类门，比 LSTM 少一个 cell state 与一组输出门。"],"design_principles_en":["Core Hypothesis: Eliminate the separate cell state and control memory retention versus new candidate overwriting with a single complementary update gate z_t.","Architectural Delta: 25% fewer parameters than LSTM while retaining additive gradient highways via (1 − z_t) ⊙ h_{t-1}.","Mathematical Formalism: Coupled Update Gate Interpolation h_t = (1−z_t) ⊙ h_{t-1} + z_t ⊙ h̃_t & Reset Gate."],"med_apps":["是 ECG、EEG、生命体征和纵向病历的小数据时序强基线。","长序列逐步递归限制并行，缺失采样和时间间隔若未显式编码会被误当等距观测。"],"med_apps_en":["Clinical Translation: Widely used in compact wearable biosignal monitors, GRU-D missing-value clinical EHR time series, and edge medical devices.","Evidence & Safety Boundary: Lightweight recurrent baseline; like LSTM, remains bottlenecked by sequential step-by-step training on ultra-long sequences."],"attrs":{"上一代瓶颈":"vanilla RNN 梯度不稳，LSTM 门控和状态较复杂","核心想法":"以 update/reset gates 控制隐藏状态保留与重置，简化门控循环结构","关键改进":"仅用单一隐藏状态和两类门，在保留长依赖能力时减少参数","医学适配":"常用于 ECG、EEG、生命体征和纵向临床序列的小数据基线","适用范围与证据":"仍是轻量时序基线；串行计算和超长依赖能力弱于现代并行模型"},"attrs_en":{"上一代瓶颈":"LSTM required three separate gates and dual state vectors, increasing parameter count and overfitting risk on small clinical cohorts.","核心想法":"Eliminate the separate cell state and control memory retention versus new candidate overwriting with a single complementary update gate z_t.","关键改进":"25% fewer parameters than LSTM while retaining additive gradient highways via (1 − z_t) ⊙ h_{t-1}.","医学适配":"Widely used in compact wearable biosignal monitors, GRU-D missing-value clinical EHR time series, and edge medical devices.","适用范围与证据":"Lightweight recurrent baseline; like LSTM, remains bottlenecked by sequential step-by-step training on ultra-long sequences."},"paper_title":"Learning Phrase Representations Using RNN Encoder-Decoder for Statistical Machine Translation","paper_url":"https://aclanthology.org/D14-1179/","code_label":"未提供官方实现","code_url":"","has_code":false,"image":"assets/00958fd23a9b55326e37.avif"},{"id":"architecture_model_137_ecgfounder","num":137,"num_str":"137","year":2025,"year_str":"2025","venue":"NEJM AI","venue_group":"journal","era_group":"era4","title":"ECGFounder","family_id":"models_temporal_biomedical","family_code":"16","family_short":"生理时序与波形模型","family_en":"Temporal Physiological AI","family_icon":"XVI","family_label":"生理时序模型：门控、膨胀卷积、长状态与领域预训练","archetype":"大规模 150 标签监督预训练的 RegNet-1D 多导联 ECG encoder","archetype_en":"clinical_scale_1d_regnet_ecg_foundation","accent":"#6B5700","fig_badge":"Figure 1 · PDF p.10","fig_href":"https://doi.org/10.1056/AIoa2401033","core_mech":"ECGFounder 是 RegNet/Net1D 风格的 1D CNN foundation model，以超过千万波形和 150 类监督规模为核心，不应误写为通用 Transformer SSL。","core_mech_en":"1D RegNet-style residual CNN with Squeeze-and-Excitation blocks pretrained via multi-label clinical supervision across >10 million 12-lead ECGs and 150 diagnostic categories.","input_desc":"标准化的 12 导联或适配后的任意单导联 ECG 波形","input_en":"Raw multi-lead (12-lead) or lead-masked single-lead 1D ECG voltage waveform tensor","output_desc":"150 类诊断概率、通用 ECG embedding 与下游微调预测","output_en":"150-class diagnostic probability vector and general-purpose 1D ECG representation","form_title":"核心公式 · 1D RegNet-SE 残差编码与 150 标签心电预训练","form_title_en":"Core Formalism · Multi-Stage 1D Residual-SE Convolutional Backbone Trained on 150-Class Clinical ECG Ontology","nodes":[{"name":"Raw multi-lead ECG","desc":"滤波、定长切片和逐导联 z-score 后输入","name_en":"Raw multi-lead ECG","desc_en":"Ingests raw multi-lead (12-lead) or lead-masked single-lead 1d ecg voltage waveform tensor and prepares initial tensor representations (Raw multi-lead ECG)."},{"name":"Net1D/RegNet-1D stem","desc":"1D 卷积建立早期局部波形特征并下采样","name_en":"Net1D/RegNet-1D stem","desc_en":"Executes Net1D/RegNet-1D stem to extract primary structural features and establish spatial/sequence encoding."},{"name":"多阶段 residual bottlenecks","desc":"1×1、k×1 group convolution、1×1 卷积组成分阶段 RegNet blocks","name_en":"residual bottlenecks","desc_en":"Performs residual bottlenecks within the core clinical scale 1d regnet ecg foundation computation pathway."},{"name":"Squeeze-and-Excitation","desc":"按通道重标定导联/特征响应，融合跨导联相关性","name_en":"Squeeze-and-Excitation","desc_en":"Performs Squeeze-and-Excitation within the core clinical scale 1d regnet ecg foundation computation pathway."},{"name":"Temporal global pooling","desc":"汇聚不同时间位置的层级波形特征","name_en":"Temporal global pooling","desc_en":"Performs Temporal global pooling within the core clinical scale 1d regnet ecg foundation computation pathway."},{"name":"ECG foundation embedding","desc":"可冻结抽取或继续全量微调","name_en":"ECG foundation embedding","desc_en":"Performs ECG foundation embedding within the core clinical scale 1d regnet ecg foundation computation pathway."},{"name":"150-label sigmoid head","desc":"用心电专家/机器结构化诊断做大规模多标签监督预训练","name_en":"150-label sigmoid head","desc_en":"Applies 150-label sigmoid head to project aggregated representations toward the target task head."},{"name":"Out-of-box/transfer heads","desc":"心律失常、结构性心脏病、风险、人口学或单导联任务","name_en":"Out-of-box/transfer heads","desc_en":"Produces 150-class diagnostic probability vector and general-purpose 1d ecg representation via Out-of-box/transfer heads."}],"design_principles":["以 RegNet 设计规则构造多阶段 1D 残差 CNN，而非 Transformer 或自监督掩码模型。","group convolution 与 SE 通道注意力同时提取局部时序形态和多导联关联。","在千万级 ECG、150 个结构化诊断上做多标签监督预训练，再迁移到新任务或单导联。"],"design_principles_en":["Core Hypothesis: Scale a domain-engineered 1D CNN (Net1D / RegNet with SE channel attention and lead-dropout augmentation) across >10M clinical ECGs annotated with a 150-label hierarchical ontology.","Architectural Delta: Massive 10M-waveform clinical supervision + lead-masking augmentation enabling seamless transfer from 12-lead hospital ECGs to single-lead wearable patches.","Mathematical Formalism: Multi-Stage 1D Residual-SE Convolutional Backbone Trained on 150-Class Clinical ECG Ontology."],"med_apps":["可直接输出广泛 ECG 诊断概率，也可作为心律、结构病和风险预测的通用 encoder。","标签来自真实世界读图流程，可能包含机器解释与机构编码偏差；单导联适配不能假设等同于完整 12 导联证据。"],"med_apps_en":["Clinical Translation: High-performing open-weight ECG foundation baseline for arrhythmia diagnosis, structural heart disease screening, and wearable ECG triage.","Evidence & Safety Boundary: Proves that a well-engineered 1D CNN at 10M-sample clinical scale rivals or outperforms complex Transformers; prospective clinical trial validation remains the next frontier."],"attrs":{"上一代瓶颈":"ECG 模型多依赖单中心小数据和任务专用标签，跨机构泛化有限","核心想法":"在超过千万份原始多导联 ECG 上预训练通用时序编码器并迁移多任务","关键改进":"利用卫生系统规模波形和多任务评测学习可复用 ECG 表征","医学适配":"用于心律失常、结构性心脏病和风险预测等 ECG 任务","适用范围与证据":"超大规模 ECG FM 代表；设备、群体公平性和前瞻效益仍需验证"},"attrs_en":{"上一代瓶颈":"Prior ECG models were trained on narrow diagnostic subsets or small single-hospital cohorts, failing on rare arrhythmias and single-lead wearables.","核心想法":"Scale a domain-engineered 1D CNN (Net1D / RegNet with SE channel attention and lead-dropout augmentation) across >10M clinical ECGs annotated with a 150-label hierarchical ontology.","关键改进":"Massive 10M-waveform clinical supervision + lead-masking augmentation enabling seamless transfer from 12-lead hospital ECGs to single-lead wearable patches.","医学适配":"High-performing open-weight ECG foundation baseline for arrhythmia diagnosis, structural heart disease screening, and wearable ECG triage.","适用范围与证据":"Proves that a well-engineered 1D CNN at 10M-sample clinical scale rivals or outperforms complex Transformers; prospective clinical trial validation remains the next frontier."},"paper_title":"An Electrocardiogram Foundation Model Built on over 10 Million Recordings","paper_url":"https://doi.org/10.1056/AIoa2401033","code_label":"作者/机构官方实现","code_url":"https://github.com/bdsp-core/ECGFounder","has_code":true,"image":"assets/1202c03449ed835d1e34.avif"},{"id":"architecture_model_138_phydict","num":138,"num_str":"138","year":2026,"year_str":"2026","venue":"MICCAI 2026","venue_group":"ml","era_group":"era4","title":"PhyDiCT","family_id":"models_neural_fields_2d3d","family_code":"14","family_short":"2D→3D 与神经辐射场","family_en":"2D-to-3D & Neural Fields","family_icon":"XIV","family_label":"2D→3D 与神经场：表示能力、投影一致性和不可辨识性","accent":"#1F4E79","archetype":"phydict","archetype_en":"phydict","fig_badge":"Figure 1 · PDF p.3","fig_href":"https://papers.miccai.org/miccai-2026/paper/1942_paper.pdf#page=3","core_mech":"在固定预训练三维扩散先验上交替施加投影观测约束与去噪更新；文本报告、几何和预训练权重都是显式条件。","core_mech_en":"A frozen text-conditioned 3D diffusion prior is guided by differentiable projection consistency during inference; reports, geometry and pretrained weights are explicit conditions.","input_desc":"稀疏 X 光、采集几何、文本报告条件与预训练 MedSyn 权重","input_en":"Sparse X-rays, acquisition geometry, a report condition and pretrained MedSyn weights","output_desc":"与观测相容的三维肺部 CT 候选体；仍需验证患者特异性与域外可靠性","output_en":"A candidate 3D lung CT volume; patient-specific fidelity and external reliability still require validation","form_title":"计算机制","form_title_en":"Computation","nodes":[{"name":"观测与几何","name_en":"Observations and geometry","desc":"明确投影数量、角度、尺度与坐标。","desc_en":"Specify projection count, angles, scale and coordinates."},{"name":"冻结先验与报告","name_en":"Frozen prior and report","desc":"预训练权重与文本条件属于额外信息。","desc_en":"Weights and text are explicit additional inputs."},{"name":"引导采样","name_en":"Guided sampling","desc":"交替去噪和投影约束。","desc_en":"Alternate denoising and projection consistency."},{"name":"验证","name_en":"Validation","desc":"分别检查观测一致性与三维准确性。","desc_en":"Assess measurement agreement and 3D fidelity separately."}],"design_principles":[],"design_principles_en":[],"med_apps":[],"med_apps_en":[],"attrs":{"上一代瓶颈":"少量投影无法唯一确定患者三维结构；通用生成先验可能与实际观测不一致。","核心想法":"把冻结的三维先验与可微成像观测结合，在推理阶段约束候选体。","关键改进":"作者方案使用 Split Gibbs 思路引导采样，并提供额外计算细化。","医学适配":"论文针对肺 CT 和合成 X 光重建；文本条件不是免费获得的信息。","适用范围与证据":"本条为 source_route：已核原始源码和根许可证；未执行原模型、未验证临床效果。"},"attrs_en":{"上一代瓶颈":"Sparse projections leave unresolved depth; a generative prior may be inconsistent with the observations.","核心想法":"Constrain a frozen 3D prior with the differentiable image-formation model at inference.","关键改进":"The author method uses Split Gibbs guidance and an extra-compute refinement stage.","医学适配":"The paper studies lung CT with simulated X-rays. Report conditioning must be declared.","适用范围与证据":"Source route only: official source and root license checked; original inference and clinical performance were not tested here."},"paper_title":"PhyDiCT: Plug-and-Play CT Reconstruction from Sparse X-Rays via Differentiable Rendering and Strong Priors","paper_url":"https://papers.miccai.org/miccai-2026/0773-Paper1942.html","code_label":"官方实现","code_url":"https://github.com/batmanlab/PhyDiCT","has_code":true,"image":"paper-figures/phydict-figure-1.png"},{"id":"architecture_model_139_medisyn","num":139,"num_str":"139","year":2024,"year_str":"2024","venue":"arXiv","venue_group":"journal","era_group":"era4","title":"MediSyn","family_id":"models_generative","family_code":"10","family_short":"生成、扩散与流匹配","family_en":"Generative, Diffusion & Flow","family_icon":"X","family_label":"生成模型：从潜变量与对抗学习到 diffusion、flow 与 consistency","accent":"#6B5700","archetype":"medisyn","archetype_en":"medisyn","fig_badge":"Fig. 1 · arXiv v7","fig_href":"https://arxiv.org/html/2405.09806v7#S0.F1","core_mech":"在公开医学图文对上微调 Stable Diffusion 1.4 的条件去噪 U-Net，冻结文本编码器与 VAE，用同一个潜扩散模型根据文本生成跨专科二维医学图像。","core_mech_en":"MediSyn fine-tunes the conditional denoising U-Net of Stable Diffusion 1.4 on public medical image–text pairs while freezing the text encoder and VAE, using one latent diffusion model for text-guided 2D medical image synthesis across specialties.","input_desc":"生成时输入描述模态、解剖部位或疾病的文本提示与随机高斯潜变量，去噪器还接收扩散时间步；训练时使用医学图像与由模态信息、既有类别标签组成的配对文本。","input_en":"Generation takes a text prompt describing modality, anatomy or disease, together with a Gaussian latent sample; the denoiser also receives the diffusion timestep. Training uses medical images paired with captions assembled from modality information and existing class labels.","output_desc":"与文本提示条件对应的二维合成医学图像；作者演示采用512×512像素输出。","output_en":"A synthetic 2D medical image conditioned on the text prompt, with 512×512 output in the author demonstration.","form_title":"计算机制","form_title_en":"Computation","nodes":[{"name":"医学图像—文本对","name_en":"Medical image–text pairs","desc":"汇集六个专科、十种成像模态。将已有类别标签与模态信息写成文本；尽可能先按患者划分训练、验证与测试数据，再进入生成模型训练。","desc_en":"Six specialties and ten imaging modalities supply paired examples. Captions describe existing class labels and modality information; patient-level splitting is used wherever possible before model training."},{"name":"冻结 VAE 编码器","name_en":"Frozen VAE encoder","desc":"训练阶段把真实图像编码为较小的空间潜表示。这个编码器保持冻结，图像压缩不是本次医学微调的主要学习位置。","desc_en":"During training, a frozen VAE encoder maps real images to a smaller spatial latent representation. The image compressor is retained rather than being the main target of medical fine-tuning."},{"name":"冻结 CLIP 文本编码器","name_en":"Frozen CLIP text encoder","desc":"从 CLIP ViT-L 取出的文本编码器把提示转成条件表示。发布配置的交叉注意力条件维度为768；最终选定的 MediSyn 配置不更新该编码器。","desc_en":"A text encoder taken from CLIP ViT-L embeds the prompt. The released configuration uses a cross-attention condition dimension of 768, and the selected MediSyn configuration keeps this encoder frozen."},{"name":"潜空间加噪与时间步","name_en":"Latent corruption and timestep","desc":"向训练图像的潜表示加入高斯噪声；带噪潜变量与时间步共同定义当前去噪问题。生成时从随机高斯潜变量开始，而不是先输入某位患者的图像。","desc_en":"Gaussian noise corrupts an encoded training image. The noisy latent and timestep define the denoising problem; generation instead starts from a Gaussian latent sample rather than a patient image."},{"name":"医学微调条件 U-Net","name_en":"Medical fine-tuning of the conditional U-Net","desc":"U-Net 预测噪声，文本通过中间层交叉注意力参与计算。固定发布配置使用4通道潜输入/输出、64的样本空间尺寸、每块2层，以及320、640、1280、1280的块通道宽度。","desc_en":"The U-Net predicts noise, with text entering through intermediate cross-attention. The pinned release configuration specifies four input/output latent channels, sample size 64, two layers per block and block widths of 320, 640, 1280 and 1280."},{"name":"噪声预测均方误差","name_en":"Noise-prediction MSE","desc":"将预测噪声与实际加入的噪声比较，以均方误差更新 U-Net。训练中10%的提示被替换为空文本，为推理时的无分类器引导提供无条件分支。","desc_en":"Mean squared error compares predicted noise with the noise actually added, updating the U-Net. Ten percent of training prompts are replaced with empty text to support classifier-free guidance at inference."},{"name":"文本引导的迭代采样","name_en":"Text-guided iterative sampling","desc":"复用已训练 U-Net，在逐步变化的时间步上去噪潜变量。作者演示将其装入 Stable Diffusion 1.4 管线，采用空负提示与7.0的引导尺度；这些是演示配置，不是所有任务的最优值。","desc_en":"The trained U-Net repeatedly denoises the latent over successive timesteps. The author demo inserts it into a Stable Diffusion 1.4 pipeline and uses an empty negative prompt with guidance scale 7.0; these are demo settings rather than universal optima."},{"name":"冻结 VAE 解码器","name_en":"Frozen VAE decoder","desc":"将最后的去噪潜表示映射回像素空间。VAE 解码器在图像合成阶段使用，仍保留基础模型的预训练参数。","desc_en":"The frozen VAE decoder maps the final denoised latent back to pixels, retaining the base model's pretrained parameters during image synthesis."},{"name":"合成图像与下游评估","name_en":"Synthetic image and downstream evaluation","desc":"输出二维医学图像，分别评估视觉分布、图文对应和下游分类用途。图像逼真度、生成多样性与对真实数据训练的帮助是不同的评价问题。","desc_en":"The output is a 2D medical image. Distributional appearance, text alignment and downstream classifier utility are assessed separately; fidelity, diversity and usefulness for learning from real data are different evaluation questions."}],"design_principles":["潜空间承担扩散计算，像素空间主要由 VAE 处理。训练时编码真实图像并加入噪声；生成时从高斯潜变量开始，二者共享条件噪声预测器。","文本不是最终图像的标签预测结果，而是控制生成分布的条件。交叉注意力让 U-Net 的中间特征利用提示中的模态与医学语义。","最终发布路线只微调 U-Net；VAE 与 CLIP ViT-L 文本编码器保持冻结。论文还比较 SDXL 和 BiomedCLIP 文本编码器变体，不能把所有变体都称为已发布的 MediSyn 配置。","第4.2节描述的训练设计为15个epoch、有效批量128、SD学习率5×10⁻⁵、Bfloat16计算与10%空提示。损失比较预测噪声和加入噪声，生成图像并不需要逐像素配对的目标图像。","研究使用1,260,826个图文对，其中训练1,014,781、验证122,463、测试123,582；尽可能按患者约80∶10∶10划分。公开可获取不等于每个源数据集都允许任意再分发，数据仍保留各自使用条件。","本条的机制和原图对应 arXiv v7（2026-04-21），首次预印本公开于2024-05-16；期刊论文于2026-10-16发表。作者公开的是 U-Net 权重、配置与推理演示，本条不把它描述为完整公开训练工程。"],"design_principles_en":["Diffusion operates in latent space while the VAE handles the pixel representation. Training encodes and corrupts real images; generation starts with Gaussian latents, sharing the same conditional noise predictor.","Text is a condition on the generated distribution rather than a diagnostic label predicted from the output. Cross-attention lets intermediate U-Net features use modality and medical semantics from the prompt.","The selected release fine-tunes only the U-Net while freezing the VAE and CLIP ViT-L text encoder. SDXL and BiomedCLIP text-encoder configurations are also compared in the paper and should not all be presented as the released MediSyn configuration.","Section 4.2 specifies 15 epochs, effective batch size 128, SD learning rate 5×10⁻⁵, Bfloat16 computation and 10% empty prompts. The objective compares predicted and added noise; generation does not require a paired target image at inference.","The study curates 1,260,826 pairs, comprising 1,014,781 training, 122,463 validation and 123,582 test pairs, using approximately 80∶10∶10 patient-level splits wherever possible. Public availability does not give every source dataset unrestricted redistribution rights.","The mechanism and original figure here follow arXiv v7, dated 2026-04-21. The first preprint appeared on 2024-05-16 and the journal article on 2026-10-16. The authors release a U-Net, configuration and inference demonstration; this is not described here as a complete published training project."],"med_apps":["覆盖六个专科和十种成像模态：CT、X光、MRI、超声、内镜、显微、眼底、OCT、皮肤镜与临床照片。研究的是二维图像合成，不应据此推定完整三维体数据或任何未列出的模态。","论文用多种评估分别检查合成质量、加载与推理成本、医生对视觉真实性及图文对应的判断、训练图像近邻差异，以及低数据条件下的分类增强。每种评估回答的问题不同。","对皮肤镜和机器人辅助前列腺切除图像，MediSyn 的 FID 更低但 MS-SSIM 更高；肌骨X光方向相反。不能把“跨专科”简化为所有任务的保真度与多样性都同时改善。","论文给出的失败例包括：虽见过MRI和胸部X光，仍不能据此生成可靠的胸部MRI；此前未见过的疾病描述也可能得到医学上不准确的图像。","合成图像与训练近邻不同，不等于形式化隐私保证。训练模态不平衡、类别间差异与临床准确性仍需在所需用途上分别验证。"],"med_apps_en":["The six specialties span ten modalities: CT, X-ray, MRI, ultrasound, endoscopy, microscopy, fundoscopy, OCT, dermoscopy and clinical photography. The work studies 2D synthesis rather than establishing full 3D volume generation or support for unlisted modalities.","Separate evaluations examine synthetic quality, loading/inference cost, physician judgments of realism and text alignment, differences from training-image neighbors, and classifier augmentation with limited real data. These evaluations answer different questions.","In dermoscopy and robot-assisted prostatectomy images, MediSyn has lower FID but higher MS-SSIM than the task-specific counterpart; musculoskeletal X-rays show the reverse pattern. Cross-specialty training does not imply simultaneous fidelity and diversity improvements for every task.","The paper gives a concrete failure example: seeing MRI and chest X-rays does not enable reliable chest MRI generation. Previously unseen disease descriptions can also yield medically inaccurate images.","Differences from nearest training images do not establish a formal privacy guarantee. Modality imbalance, class-dependent behavior and clinical accuracy still require evaluation for the intended use."],"attrs":{"上一代瓶颈":"为每个专科、模态和部位维护独立生成模型，增加训练、部署与反复加载权重的成本；依赖私有训练数据也不便复现。MediSyn 研究能否让一个模型学习多种医学图像分布。","核心想法":"保留 Stable Diffusion 1.4 的潜扩散框架，在统一的医学图文数据上只微调 U-Net。VAE 负责像素与潜表示之间的映射，冻结的文本编码器提供提示条件。","关键改进":"通用性来自跨专科数据与训练设计，而非更换一套全新主干。作者比较六种基础模型及微调配置后，选定冻结 VAE 和文本编码器、仅更新 U-Net 的 SD1.4 配置作为 MediSyn。","医学适配":"用已有模态信息和类别标签构建提示，覆盖胃肠、放射、病理、外科、皮肤与眼科。用途是可控合成与低数据条件下的数据增强，学习目标仍是生成图像。","适用范围与证据":"原文显示图像保真度与多样性存在取舍，下游受益也因类别和数据量而异。已见过的模态与部位不能任意组合为新任务；新疾病提示可能产生不准确图像，且论文未给出形式化隐私保证。"},"attrs_en":{"上一代瓶颈":"Maintaining a generator for every specialty, modality and anatomical region adds training, deployment and repeated model-loading costs, while private training data limits reproducibility. MediSyn asks whether one model can learn diverse medical image distributions.","核心想法":"Retain the latent diffusion framework of Stable Diffusion 1.4 and fine-tune only its U-Net on a unified medical image–text collection. The VAE maps between pixels and latents, while a frozen text encoder supplies prompt conditions.","关键改进":"Generality comes from the cross-specialty data and training design rather than a completely new backbone. After comparing six model/training configurations, the authors select SD1.4 with a frozen VAE and text encoder and a fine-tuned U-Net as MediSyn.","医学适配":"Prompts use existing modality information and class labels across gastroenterology, radiology, pathology, surgery, dermatology and ophthalmology. The aim is controlled synthesis and augmentation in limited-data settings, with image generation remaining the learning objective.","适用范围与证据":"The paper reports tradeoffs between fidelity and diversity, with downstream gains varying by class and data regime. Familiar modalities and anatomy do not combine arbitrarily into unseen tasks; novel disease prompts may be inaccurate, and no formal privacy guarantee is established."},"paper_title":"A Generalist Model for Diverse Text-Guided Medical Image Synthesis","paper_url":"https://arxiv.org/html/2405.09806v7","code_label":"官方实现","code_url":"https://huggingface.co/hiesingerlab/MediSyn/tree/262620bc37bcf8c78cf98b0751a0bbfdc332bf36","has_code":true,"image":"licensed/medisyn/figure-1.png"},{"id":"architecture_model_140_percival","num":140,"num_str":"140","year":2026,"year_str":"2026","venue":"npj Digital Medicine","venue_group":"journal","era_group":"era4","title":"Percival","family_id":"models_vision_language","family_code":"07","family_short":"图文对齐与医学 VLM","family_en":"Vision-Language Models","family_icon":"VII","family_label":"图文对齐与生成式 VLM：开放语义不等于视觉事实","accent":"#7A3547","archetype":"percival","archetype_en":"percival","fig_badge":"Fig. 1 · journal 2026","fig_href":"https://www.nature.com/articles/s41746-026-03257-2_reference.pdf#page=3","core_mech":"把三维 CT 与放射学报告分别编码，用对称对比学习对齐全体扫描的视觉和语言表征，再以冻结图像向量支持检索、零样本分类及独立拟合的疾病与风险模型。","core_mech_en":"Separate encoders align whole-volume CT and radiology-report representations through symmetric contrastive learning. Frozen image embeddings support retrieval, zero-shot classification and separately fitted disease or prognostic models.","input_desc":"训练输入配对的三维 CT 与放射学报告。期刊版本将 CT 重采样为 1×1×3 mm，截断 HU 至 −1000～1000 并归一化到 [0,1]，补齐、中心裁剪为 XYZ 轴 352×352×128；图像塔的张量顺序为 B×1×128×352×352。","input_en":"Training takes paired 3D CT volumes and radiology reports. The journal pipeline resamples CT to 1×1×3 mm, clips HU to −1000…1000, normalizes to [0,1], then pads and center-crops to XYZ dimensions 352×352×128. The vision tensor is B×1×128×352×352.","output_desc":"图像与文本位于同一表示空间。Tiny、Small、Base 的共享维度分别为 192、384、768；Base 输出 768 维图像或文本向量。相似度用于跨模态检索及提示词分类，独立训练的下游头再输出疾病概率或 Cox 风险分数。","output_en":"Image and text lie in a shared space of 192, 384 or 768 dimensions for Tiny, Small and Base. Base produces a 768-dimensional image or text vector. Similarity supports cross-modal retrieval and prompt classification; separately trained downstream heads produce disease probabilities or Cox risk scores.","form_title":"计算机制","form_title_en":"Computation","nodes":[{"name":"体数据标准化","name_en":"Volume standardization","desc":"统一朝向、物理间隔、HU 范围和空间尺寸。XYZ 与 PyTorch 的 DHW 顺序要区分；发布配置把 XYZ 尺寸反转后交给视觉塔，预处理后的间隔不能由张量尺寸直接推断。","desc_en":"Standardize orientation, physical spacing, HU range and spatial size. Distinguish XYZ from PyTorch DHW: the release reverses XYZ image dimensions before building the vision tower, and tensor size alone does not establish voxel spacing."},{"name":"三维卷积分块","name_en":"3D convolutional patches","desc":"以空间 XYZ 的 16×16×8 体素为块；实现的 DHW 核与步长为 8×16×16。128×352×352 输入得到 16×22×22=7744 个区域标记，三维卷积将每块映射为 Transformer 特征。","desc_en":"Use XYZ patches of 16×16×8 voxels, implemented with DHW kernel and stride 8×16×16. A 128×352×352 volume yields a 16×22×22 grid, or 7,744 regional tokens, projected into Transformer features by a 3D convolution."},{"name":"位置编码与全局标记","name_en":"Position encoding and global token","desc":"为区域标记加入三维空间位置，前置一个 CLS 全局标记。固定代码对 AugReg 位置编码进行空间适配；完整序列包含 7744 个区域标记与 1 个全局标记。","desc_en":"Add 3D spatial position information and prepend a CLS token. The pinned implementation adapts AugReg position embeddings; the full sequence contains 7,744 regional tokens and one global token."},{"name":"AugReg 视觉 Transformer","name_en":"AugReg vision Transformer","desc":"在完整体数据序列上做多头自注意力。CLS 与所有区域标记双向交换信息，在多层中聚合扫描级结构；这里不是逐切片独立编码后再做层级注意力。","desc_en":"Multi-head self-attention operates on the full volume sequence. CLS exchanges information with all regional tokens and aggregates scan-level structure across layers; this is not independent per-slice encoding followed by hierarchical attention."},{"name":"图像投影与归一化","name_en":"Image projection and normalization","desc":"取最后一层归一化后的 CLS 输出，再以线性头映射到共享维度。Base 为 768 维；计算对比相似度前做 L2 归一化，使内积对应余弦相似度。","desc_en":"Take the final normalized CLS output and project it linearly into the shared space, 768 dimensions for Base. L2 normalization before contrastive similarity makes the dot product a cosine similarity."},{"name":"报告文本编码","name_en":"Report text encoding","desc":"另一条并行路径将报告分词并提供注意力掩码，送入 CXR-BERT-specialized。固定语言塔取第一个标记的最终隐状态，再通过线性投影与对应视觉变体对齐。","desc_en":"A parallel path tokenizes the report, supplies an attention mask and encodes it with CXR-BERT-specialized. The pinned language tower takes the first-token final hidden state and linearly projects it to the matching vision variant’s shared dimension."},{"name":"批内图文相似度矩阵","name_en":"In-batch image–text similarity","desc":"对 B 个扫描与 B 份报告形成 B×B 相似度矩阵。对角线对应真实图文对，其余项是批内负对；分布式训练先汇集多 GPU 特征，扩充对比集合。","desc_en":"A batch of B scans and B reports forms a B×B similarity matrix. The diagonal contains matched pairs and off-diagonal entries provide in-batch negatives. Distributed training gathers features across GPUs before constructing the contrastive set."},{"name":"双向对比目标","name_en":"Symmetric contrastive objective","desc":"同时优化图像找报告与报告找图像，两个方向的交叉熵取平均。相似度的缩放影响 softmax 锐度；公式的除数温度与代码的乘数缩放须按各自约定解释。","desc_en":"Optimize image-to-report and report-to-image matching, averaging cross-entropy in the two directions. Similarity scaling controls softmax sharpness; divisor temperature in the formula and multiplier scale in code must be interpreted under their own conventions."},{"name":"检索与提示词分类","name_en":"Retrieval and prompt classification","desc":"推理时可只编码 CT，并与预先编码的报告或“病变存在／不存在”提示比较。图文向量是匹配表示；双编码器本身不逐词生成报告，也不输出分割掩码。","desc_en":"At inference, CT embeddings can be compared with pre-encoded reports or pathology-present/pathology-absent prompts. These are matching representations: the dual encoder itself does not generate report tokens or segmentation masks."},{"name":"冻结表征后的任务建模","name_en":"Task models on frozen representations","desc":"将图像塔的向量作为独立模型的输入。论文疾病分类使用按解剖视野分别拟合的 L1 逻辑回归，预后使用 ridge Cox 模型；这些拟合目标与图文预训练目标不同。","desc_en":"Use vision-tower vectors as inputs to separate models. The paper fits field-of-view-specific L1 logistic regressions for disease classification and ridge Cox models for prognosis. Their fitting objectives differ from image–text pretraining."}],"design_principles":["三维块包含局部体素关系，完整序列注意力再连接远距离区域。以给定尺寸计算，区域标记数为 (128÷8)×(352÷16)×(352÷16)=7744，加上 CLS 后共 7745；输入分辨率改变会显著改变注意力计算规模。","两条编码路径在相似度空间相遇，不是在视觉编码中交叉注意全部报告词元。配对监督鼓励扫描与其报告相近，但报告未描述的影像细节不一定得到同等强度监督。","视觉参数约 6M、22M、86M 仅对应 Tiny、Small、Base 视觉塔。它们的共享空间为 192、384、768 维，不是所有变体都采用 768 维，也不能把视觉参数数目当成双塔总参数。","期刊预训练使用 436,787 个 CT—报告对、51,966 名参与者。配对验证集为 46,535 个体数据、5,774 名参与者；额外无报告验证 CT 用于图像侧下游分析。组合验证队列按论文报告为 123,603 个 CT、20,599 名参与者，不把子组人数直接相加。","AdamW、初始学习率 5×10⁻⁵、每 GPU 批量 48、4 张 NVIDIA B200 对应全局有效批量 192。固定 Base YAML 设定 16 个 epoch、clip 损失且不冻结语言塔；这些是所审阅发布配置，不是自选的最优训练建议。","本页公式采用标准除数温度 τ 的对称对比目标。期刊文字记 τ=10；固定代码的 CLIP 分支在未启用可学习缩放时把余弦相似度乘 10，若启用则使用 exp(logit_scale)。这两种写法不应被直接说成同一个数值温度。","本文以 2026 年期刊 Article in Press 与固定 v2 实现解释机制。首次预印本于 2025-07-03 公开，期刊于 2026-09-29 发表；早期 v1 的 DeiT、Clinical Longformer、粗块尺寸和 512 维表示不套用到本页 v2。","复现应同时固定物理间隔、轴顺序、空间裁剪、分块尺寸、所选双塔和投影维度，并按参与者划分数据。图像嵌入归一化与分类器的特征标准化是不同操作，要按具体下游协议处理。"],"design_principles_en":["Volumetric patches encode local voxel relationships, while full-sequence attention links distant regions. At the stated size, (128÷8)×(352÷16)×(352÷16)=7,744 regional tokens plus CLS gives 7,745 tokens. Resolution changes can substantially alter attention cost.","The two encoders meet in similarity space rather than cross-attending every report token inside the vision tower. Pair supervision brings a scan closer to its report; details omitted from the report need not receive equally strong supervision.","The approximate 6M, 22M and 86M parameter counts refer only to Tiny, Small and Base vision towers. Shared dimensions are 192, 384 and 768. Not every variant is 768-dimensional, and vision-only counts are not two-tower totals.","Journal pretraining uses 436,787 CT–report pairs from 51,966 participants. Paired validation contains 46,535 volumes from 5,774 participants; additional unpaired CT is used for image-side downstream analyses. Use the reported combined validation cohort of 123,603 CT volumes and 20,599 participants rather than summing subgroup participant counts.","AdamW, initial learning rate 5×10⁻⁵, per-GPU batch size 48 and four NVIDIA B200 GPUs yield a global batch size of 192. The pinned Base YAML sets 16 epochs, clip loss and an unfrozen language tower. These are reviewed release settings, not independently optimized recommendations.","The formula here uses the standard divisor-temperature τ convention. Journal prose states τ=10; the pinned CLIP branch instead multiplies cosine similarity by 10 when learnable scaling is disabled, or uses exp(logit_scale) when enabled. The numerical conventions should not be equated without conversion.","The explanation follows the 2026 journal Article in Press and pinned v2 implementation. The first preprint appeared on 2025-07-03; the journal article appeared on 2026-09-29. Earlier v1 choices—DeiT, Clinical Longformer, coarse patches and 512-dimensional features—are not attributed to this v2 route.","Reproduction should pin physical spacing, axis order, crop, patch size, tower choice and projection dimension, with participant-level splitting. Image-embedding L2 normalization and classifier feature standardization are distinct operations governed by the downstream protocol."],"med_apps":["跨模态检索比较 CT 与报告的共享向量；提示词分类比较同一病变的存在与不存在描述。它们使用文本相似度，不等同于已经校准的临床患病概率。","论文外部 CT-RATE 验证保留每个检查一个 CT，共 1,564 个体数据、18 类胸部标签，并区分零样本提示词分类与在 CT-RATE 训练数据上另拟合的线性探测。","疾病分类按胸部、腹部／盆腔分别拟合 L1 逻辑回归，使用影像时间附近的疾病状态；纵向预后则以基线之前无对应诊断者为对象，拟合 ridge Cox 风险模型。二者的队列和目标不同。","实验室指标关联和疾病表型分析使用从训练集拟合的 PCA 坐标，并在验证人群中开展发现与复现。统计显著的坐标关联帮助研究表征，但不意味着某个潜变量就是一个独立生物学机制。","期刊中的合成实验室数值来自额外三层 MLP，输入完整图像表征及影像与化验的时间差，用被试分组交叉验证；它不是双塔预训练自动输出的检验报告。","PMBB 的病例来源、影像视野和造影方式影响表征及验证范围。代码和已发布模型的可获取性，与原始患者影像、报告及生物库数据的访问条件分别处理。"],"med_apps_en":["Cross-modal retrieval compares CT and report vectors; prompt classification compares present/absent descriptions of one pathology. Both use text similarity rather than an already calibrated clinical disease probability.","External CT-RATE evaluation retains one CT per study, totaling 1,564 volumes and 18 thoracic labels. It distinguishes zero-shot prompts from linear probes separately fitted on CT-RATE training data.","Disease classification fits L1 logistic regression separately for chest and abdomen/pelvis fields of view, targeting disease status near imaging. Longitudinal prognosis instead excludes prior diagnoses of the target condition and fits ridge Cox models. Their cohorts and objectives differ.","Laboratory and disease-phenotype association analyses use PCA axes fitted on training embeddings and discovery–replication analyses in validation participants. Significant associations help characterize representations without identifying each latent coordinate as an independent biological mechanism.","Synthetic laboratory values in the paper come from an additional three-layer MLP using complete image features and the imaging-to-assay time difference, evaluated with subject-grouped cross-validation. They are not test reports automatically produced by dual-encoder pretraining.","PMBB case mix, field of view and contrast administration affect the learned representation and evaluation scope. Availability of code or released models is distinct from access conditions for original patient CT, reports and biobank data."],"attrs":{"上一代瓶颈":"窄解剖视野、单一造影条件或单一临床任务上的训练，限制了 CT 表征覆盖真实扫描差异的能力。","核心想法":"将全体 CT 的三维视觉编码器与报告文本编码器对齐，让医学报告提供扫描级语义监督。","关键改进":"期刊路线以 AugReg ViT 的三维分块与 CXR-BERT-specialized 组成双塔，并在不同视野、造影条件和临床用途的配对数据上统一训练。","医学适配":"同一 CT 表征被用于跨模态检索、胸部病变提示词分类、实验室指标关联、疾病分类和纵向风险研究；后几项通过独立统计或预测模型实现。","适用范围与证据":"外部 CT-RATE、院内验证及生物学关联回答不同问题。相似度分数、疾病概率与风险排序不可互换，观察性关联也不直接给出因果解释。"},"attrs_en":{"上一代瓶颈":"Training in narrow anatomical windows, contrast settings or clinical tasks limits coverage of real-world CT variation.","核心想法":"Align a whole-volume 3D vision encoder with a report encoder so that radiology text supplies scan-level semantic supervision.","关键改进":"The journal route pairs a 3D-patch AugReg ViT with CXR-BERT-specialized and trains jointly across fields of view, contrast settings and clinical indications.","医学适配":"The same CT representation supports retrieval, thoracic prompt classification, laboratory associations, disease classification and longitudinal risk research. The latter uses separate statistical or predictive models.","适用范围与证据":"External CT-RATE validation, internal evaluation and biological association studies answer different questions. Similarity, disease probability and risk rank are not interchangeable, and observational association does not directly establish causality."},"paper_title":"Generalizable CT vision-language modeling for population health and disease risk","paper_url":"https://www.nature.com/articles/s41746-026-03257-2_reference.pdf","code_label":"官方实现","code_url":"https://github.com/cams2b/percival/tree/9f7b648dd9854a0a7f466befc560548adc90cf00","has_code":true,"image":"licensed/percival/figure-1.png"},{"id":"architecture_model_141_medgemma","num":141,"num_str":"141","year":2026,"year_str":"2026","venue":"Nature Medicine","venue_group":"journal","era_group":"era4","title":"MedGemma","family_id":"models_vision_language","family_code":"07","family_short":"图文对齐与医学 VLM","family_en":"Vision-Language Models","family_icon":"VII","family_label":"图文对齐与生成式 VLM：开放语义不等于视觉事实","accent":"#7A3547","archetype":"medgemma","archetype_en":"medgemma","fig_badge":"Fig. 1 · journal overview 2026","fig_href":"https://www.nature.com/articles/s41591-026-04626-w/figures/1","core_mech":"以医学图文训练的 MedSigLIP 编码图像，将视觉表示与文本一起送入 Gemma 3，逐词生成医学回答。模型集合包括 4B 与 27B 多模态模型及 27B 纯文本模型。","core_mech_en":"A medically trained MedSigLIP encoder supplies visual representations to Gemma 3 alongside text for autoregressive medical answers. The collection contains 4B and 27B multimodal variants and a 27B text-only variant.","input_desc":"多模态变体接收医学图像与文本，可交错组织在对话中；27B Text 仅接收文本。期刊的视觉输入为 896×896，像素归一化至 (−1,1)。本页采用原始二维发布，1.5 的体数据流程属于后续版本。","input_en":"Multimodal variants take medical images and text interleaved in a conversation; 27B Text takes text only. The journal vision input is 896×896 with pixels normalized to (−1,1). This page covers the original 2D release; 1.5 volumetric workflows belong to a later version.","output_desc":"多模态与纯文本 MedGemma 均输出生成文本，例如图像问答、报告草稿和医学摘要。独立 MedSigLIP 输出用于分类与检索的表示，不直接生成回答，也不等于 MedGemma 的语言解码器。","output_en":"Both multimodal and text-only MedGemma produce generated text, including visual answers, draft reports and medical summaries. Standalone MedSigLIP supplies representations for classification and retrieval rather than generating answers.","form_title":"计算机制","form_title_en":"Computation","nodes":[{"name":"选择发布变体","name_en":"Select a release variant","desc":"固定作者示例提供 4b-it、27b-it 与 27b-text-it 三个模型标识。先选择多模态或纯文本路径，再决定是否提供图像；4B 与 27B 是参数规模，不是图像分辨率。","desc_en":"The pinned example offers 4b-it, 27b-it and 27b-text-it. Choose a multimodal or text-only path before supplying images. 4B and 27B denote parameter scales, not image resolution."},{"name":"组织图像与问题","name_en":"Compose images and a question","desc":"把图像和文字放进具有角色的消息结构，保留图像与问题之间的对应关系。作者示例用聊天模板构造模型输入，并在最后加入生成提示。","desc_en":"Place images and text in role-structured messages while preserving their correspondence. The author example uses a chat template and adds a generation prompt."},{"name":"图像预处理","name_en":"Image preprocessing","desc":"期刊的多模态编码器使用 896×896 图像和 (−1,1) 像素归一化。处理器管理模型需要的图像张量、文字标记和掩码；输入文件的原始尺寸不等于编码器尺寸。","desc_en":"Journal multimodal encoding uses 896×896 images normalized to (−1,1). The processor builds required image tensors, text tokens and masks; a file’s original size is not the encoder size."},{"name":"MedSigLIP 医学视觉编码","name_en":"MedSigLIP medical vision encoding","desc":"400M 规模的 SigLIP 视觉编码器经过医学图文增强，提取影像表示。训练同时保留通用领域数据，使专科适配与原有视觉能力在同一编码器中协调。","desc_en":"A 400M SigLIP vision encoder is enhanced with medical image–text data to extract image representations. General-domain replay balances medical adaptation with existing visual capability."},{"name":"对接视觉与语言","name_en":"Connect visual and language representations","desc":"视觉编码结果沿 Gemma 3 的多模态接口送入语言模型，与文本条件共同形成回答上下文。该节点标明视觉表示与文字条件的衔接位置。","desc_en":"Visual encoding enters the Gemma 3 multimodal interface and forms the answer context alongside text. This node locates the connection between visual representations and text conditions."},{"name":"Gemma 3 语言建模","name_en":"Gemma 3 language modeling","desc":"模型基于已经训练的 Gemma 3。多模态路线在视觉增强后继续进行包含交错图文的预训练，使解码器适应医学视觉表示；纯文本 27B 路线单独处理。","desc_en":"The model starts from pretrained Gemma 3. After vision enhancement, multimodal pretraining with interleaved images and text adapts the decoder to medical visual representations. The text-only 27B route is separate."},{"name":"逐标记生成","name_en":"Generate tokens autoregressively","desc":"作者示例执行 model.generate，限制新生成标记数，并支持确定性解码。输出依赖所给图像、问题和上下文；生成长度与输入长度应分别管理。","desc_en":"The author example calls model.generate with a limit on new tokens and deterministic decoding. Outputs depend on images, question and context; input and generated lengths are managed separately."},{"name":"提取回答标记","name_en":"Extract answer tokens","desc":"固定示例先记录输入 token 长度，再从生成序列中去掉输入前缀，以处理器或分词器解码新增部分，避免把问题本身重复当成模型回答。","desc_en":"The pinned example records input-token length, removes that prefix from the generated sequence and decodes only the newly generated tokens, avoiding repetition of the prompt as an answer."},{"name":"关联影像证据阅读","name_en":"Read with the image evidence","desc":"问答、报告生成与医学摘要是不同输出任务。阅读回答时检查影像所见、问题要求和遗漏信息；对于分类或检索，可选独立 MedSigLIP 表征与相应评估协议。","desc_en":"Visual answering, report generation and summarization are distinct tasks. Read answers against image findings, the question and omissions. Classification or retrieval can instead use standalone MedSigLIP with a suitable evaluation protocol."},{"name":"按任务验证结果","name_en":"Validate by task","desc":"论文区分图像问答、胸片分类、报告评估和医学文本任务。复现时固定数据划分、提示词、模型标识与解码方式，不把不同任务的分数当作同一种准确率。","desc_en":"The paper separates visual QA, chest-image classification, report evaluation and medical text tasks. Reproduction fixes splits, prompts, model identifiers and decoding rather than treating all scores as one accuracy."}],"design_principles":["图像编码与语言生成承担不同功能。MedSigLIP 把影像映射为可用表示，Gemma 3 根据图像表示和文字上下文生成新标记；不能把相似度检索接口等同于问答接口。","期刊多模态视觉输入为 896×896。独立发布的 MedSigLIP 使用 448×448，分享视觉权重并适配位置编码，以降低独立表征实验的计算成本；两个分辨率对应不同使用路径。","视觉增强阶段保留通用训练数据，并在混合中加入医学图文。随后多模态预训练重新适配视觉表示与语言模型；训练混合比例属于阶段与实验设定，不能当作推理参数。","期刊明确多模态变体采用视觉增强、多模态预训练和后训练阶段；27B Text 采用后训练路线。相同的参数规模不意味着相同输入模态或训练过程。","固定作者示例将 27b-text-it 分流到 text-generation，其余多模态变体进入 image-text-to-text。模型标识决定所支持的输入路径。","输入 token 与新增 token 的边界决定展示什么内容。先保存 input_ids 的长度，再截取生成序列的新部分，可以避免把输入问题误记为模型输出。","量化和设备映射属于部署策略。作者示例支持可选 4-bit 加载与 bfloat16；这不改变原论文的模型身份，也不能据此推断任意设备上的速度或精度。","本文公式说明给定图像与文本条件后的自回归分解。完整训练还包含视觉增强、多模态预训练与后训练各阶段的监督和数据组成。","技术报告首次公开于 2025-07-07，期刊发表于 2026-10-06。版本日期、模型发现日期、本站预览日期与正式发布日期分别记录，不把期刊日期当作首次公开时间。"],"design_principles_en":["Image encoding and language generation have different roles. MedSigLIP maps images to representations; Gemma 3 generates tokens conditioned on visual representations and text. Similarity retrieval is a different interface from question answering.","Journal multimodal vision input is 896×896. Standalone MedSigLIP uses 448×448, sharing vision weights with adapted positional embeddings to reduce representation-experiment cost. These resolutions belong to different usage paths.","Vision enhancement retains general training data and mixes in medical image–text data. Multimodal pretraining subsequently adapts the vision-language connection. Training mixture ratios belong to specific stages and experiments, not inference parameters.","Journal multimodal variants undergo vision enhancement, multimodal pretraining and post-training; 27B Text uses the post-training route. Equal parameter scale does not establish equal input modalities or training paths.","The pinned author example sends 27b-text-it to text-generation and multimodal variants to image-text-to-text. Model identifiers determine the supported input path.","The boundary between input and new tokens determines what is displayed. Recording input_ids length and slicing it from generated sequences avoids treating the question as model output.","Quantization and device mapping are deployment choices. The author example supports optional 4-bit loading and bfloat16; these do not change model identity or establish speed and accuracy on arbitrary devices.","The formula explains autoregressive factorization conditioned on images and text. Complete training also includes the supervision and data mixtures of vision enhancement, multimodal pretraining and post-training.","The technical report first appeared on 2025-07-07; the journal article appeared on 2026-10-06. Release, discovery, preview and formal publication dates are recorded separately."],"med_apps":["胸部影像问答：同时给出图像与明确问题，区分可见征象、位置描述和问题中额外提供的信息。","报告生成：以参考报告和影像所见共同评估，关注遗漏、额外发现和措辞，而非只比较文本是否流畅。","数字病理：本页原始版本以二维图像或图块进行理解；全切片的采样、聚合与新版流程需另行固定。","眼底与皮肤图像：按任务标签、疾病谱、设备与人群设计验证；不同图像来源会改变输入分布。","医学文本：27B Text 可用于文本问答、摘要与合成 EHR 任务，图像条件需要选择多模态模型。","表征任务：独立 MedSigLIP 可用于图像检索和分类实验，评价检索排序与分类阈值时采用各自协议。"],"med_apps_en":["Chest-image QA: supply an image and explicit question; distinguish visible findings, localization and additional facts supplied in the question.","Report generation: evaluate against both reference reports and image findings, checking omissions, extra findings and phrasing rather than fluency alone.","Digital pathology: the original release interprets 2D images or patches; whole-slide sampling, aggregation and newer workflows require separate versioning.","Retinal and skin images: validate against task labels, disease spectrum, devices and populations; image provenance affects the input distribution.","Medical text: 27B Text supports text QA, summarization and synthetic-EHR tasks; image conditioning requires a multimodal variant.","Representation tasks: standalone MedSigLIP supports retrieval and classification experiments, each with its own ranking or threshold protocol."],"attrs":{"上一代瓶颈":"通用视觉语言模型能理解多种输入，但医学中的细粒度所见、专科术语和任务协议仍需要专门适配。","核心想法":"沿用 Gemma 3 多模态骨架，先增强医学视觉表示，再让语言模型适应新的图像表示与医学任务。","关键改进":"把医学视觉编码器、交错图文预训练与任务后训练分开描述，提供多模态 4B/27B 与纯文本 27B 的互补选择。","医学适配":"医学图文覆盖放射影像、病理、眼底与皮肤图像，文本任务包括问答和摘要。独立 MedSigLIP 服务于表征型任务。","适用范围与证据":"本页解释 2025 年技术报告与 2026 年期刊对应的原始模型集合，并用 2025-07-09 作者示例核对三个模型标识；后续 1.5 属于独立版本。"},"attrs_en":{"上一代瓶颈":"General vision-language models handle diverse inputs, while fine medical findings, terminology and task protocols require domain adaptation.","核心想法":"Retain Gemma 3’s multimodal backbone, enhance medical visual representations, then adapt language modeling to the new representations and tasks.","关键改进":"Separate medical vision enhancement, interleaved multimodal pretraining and task post-training; offer complementary 4B/27B multimodal and 27B text-only variants.","医学适配":"Medical image–text data span radiology, pathology, ophthalmology and dermatology. Text tasks include answering and summarization; standalone MedSigLIP supports representation tasks.","适用范围与证据":"This page covers the original collection in the 2025 technical report and 2026 journal article, checking all three identifiers against the 2025-07-09 author example. Later 1.5 is a separate release."},"paper_title":"An open vision-language model for diverse medical applications","paper_url":"https://www.nature.com/articles/s41591-026-04626-w","code_label":"官方实现","code_url":"https://github.com/google-health/medgemma/tree/7ed0090a872511d806b34d56bc845b770ce13dc5","has_code":true,"image":"licensed/medgemma/figure-1.png"},{"id":"architecture_model_142_brain2vec","num":142,"num_str":"142","year":2026,"year_str":"2026","venue":"arXiv","venue_group":"journal","era_group":"era4","title":"Brain2Vec","family_id":"models_self_supervised_learning","family_code":"05","family_short":"自监督表征学习","family_en":"Self-Supervised Learning","family_icon":"V","family_label":"自监督学习：对比、聚类、自蒸馏与遮挡重建","accent":"#5B3F8C","archetype":"brain2vec","archetype_en":"brain2vec","fig_badge":"Fig. 1 · arXiv v1 · 2026","fig_href":"https://arxiv.org/html/2610.28411v1#S3.F1","core_mech":"用三维遮蔽自编码学习 T1 脑 MRI 表征。预训练重建被遮蔽体块，应用时提取 768 维全脑嵌入，或以编码器初始化下游模型。","core_mech_en":"A 3D masked autoencoder learns T1 brain MRI representations. Masked-volume reconstruction trains an encoder that supplies 768-dimensional embeddings or initializes downstream models.","input_desc":"经去颅骨、线性配准与强度标准化的单通道 T1 脑 MRI，采样为 128×128×128 体素。作者预处理与模型读取器共同定义输入空间。","input_en":"A single-channel T1 brain MRI after skull stripping, linear registration and intensity normalization, resampled to 128×128×128 voxels. Preprocessing and the loader define the input space.","output_desc":"预训练输出体块重建与遮蔽损失；表征模式输出 768 维 CLS 嵌入。分类、脑龄回归需要各自训练的下游头；解码器另用于潜变量操纵研究。","output_en":"Pretraining produces patch reconstructions and masked loss; representation mode yields a 768-dimensional CLS embedding. Classification and brain-age regression use separately trained heads. Decoder experiments probe latent changes.","form_title":"计算机制","form_title_en":"Computation","nodes":[{"name":"对齐三维输入","name_en":"Align the 3D input","desc":"先去颅骨并配准到共同模板，再缩放与标准化。解剖位置、体素网格和强度空间决定后续表征的可比性。","desc_en":"Skull stripping and atlas registration precede resizing and normalization, aligning anatomy, voxel grids and intensity space."},{"name":"划分三维体块","name_en":"Embed 3D patches","desc":"8×8×8 非重叠体块将 128³ 体积化为 4096 个位置。作者用核与步长均为 8 的 Conv3d 投影到 768 维，并加入三维位置编码。","desc_en":"An 8³ patch grid creates 4096 positions. A stride-8 Conv3d projects patches to 768 dimensions with 3D positional encoding."},{"name":"随机遮蔽 75%","name_en":"Mask 75% at random","desc":"预训练仅保留 1024 个可见体块，加入 CLS 标记后送入编码器。原始顺序索引用于解码阶段恢复位置。","desc_en":"Pretraining retains 1024 visible patches plus CLS. Stored indices restore original positions during decoding."},{"name":"编码可见上下文","name_en":"Encode visible context","desc":"基础模型使用 12 层、12 头 ViT。自注意力联合建模可见体块，编码器不接收被遮蔽位置的占位标记。","desc_en":"The base model uses twelve ViT layers and twelve heads, attending over visible patches without masked-position placeholders."},{"name":"恢复完整位置","name_en":"Restore the full grid","desc":"将编码结果投影到 512 维，补入共享可学习遮蔽标记，按 ids_restore 还原 4096 个体块位置并加入解码位置编码。","desc_en":"Project to width 512, insert learned mask tokens and use ids_restore to recover all 4096 positions."},{"name":"重建体块体素","name_en":"Reconstruct patch voxels","desc":"8 层、16 头解码器处理完整体块序列；线性预测头为每块输出 512 个体素值。目标是标准化强度空间中的重建。","desc_en":"An eight-layer, sixteen-head decoder and linear head predict 512 normalized voxel values per patch."},{"name":"只在遮蔽处计分","name_en":"Score masked patches only","desc":"按体块求体素均方误差，再只对遮蔽位置求平均。可见体块提供上下文，却不进入这一遮蔽重建损失的分母。","desc_en":"Average voxel MSE per patch, then average only masked positions. Visible patches provide context without entering that denominator."},{"name":"完整输入提取嵌入","name_en":"Extract a full-input embedding","desc":"表征推理关闭遮蔽。作者 inference.py 执行 forward_encoder(mask_ratio=0.0)，再读取 features[:,0,:]，得到基础模型的 768 维 CLS 表征。","desc_en":"Inference disables masking and selects features[:,0,:] from forward_encoder: the base model’s 768-dimensional CLS representation."},{"name":"选择下游学习方式","name_en":"Choose a transfer route","desc":"冻结编码器后训练 SVM／SVR，或用预训练参数初始化 ViT 再微调。两条路线的训练对象、输出与评价协议分别记录。","desc_en":"Train SVM/SVR models on frozen embeddings, or initialize and fine-tune a ViT. These routes have separate objectives and evaluation protocols."},{"name":"检查解剖解释","name_en":"Examine anatomical interpretation","desc":"论文结合注意力、区域体积相关性与潜变量操纵。解码后的区域变化可帮助研究表征；相关性、注意力与预测因果机制需分别理解。","desc_en":"The paper combines attention, regional correlations and latent manipulation. Reconstructed changes aid interpretation while these forms of evidence remain distinct."}],"design_principles":["三维体块的 512 个体素先被投影到 768 维；特征宽度与空间体块大小是两个参数。","75% 是预训练的体块遮蔽比例。4096 个空间位置保留 1024 个可见体块，再加入 CLS；提取嵌入时使用完整输入。","编码器仅处理可见体块；解码器补齐遮蔽标记并恢复位置。两者的序列长度、宽度和计算责任不同。","三维正弦余弦位置编码保留各轴空间信息；重排后的体块必须按位置索引恢复。","损失先平均每块的体素误差，再对遮蔽块求平均。输入已标准化，重建值属于该强度空间。","基础模型的编码器为 12 层、768 维；代码也提供 large 与 huge 构造器，本页参数固定在论文基础模型。","下游 SVM／SVR 消费冻结嵌入；ViT 微调则更新相应网络参数。冻结路线和微调路线应分别配置训练、验证与测试。","注意力可显示关注区域，区域相关性连接解剖描述，潜变量操纵考察解码变化；三类分析共同帮助理解表征。","作者讨论了训练数据偏向特定研究和较年长人群的问题。外部队列、扫描协议和年龄覆盖是迁移评估的重要部分。"],"design_principles_en":["A patch contains 512 voxels before projection to width 768; spatial patch size and feature width are separate parameters.","The 75% masking ratio belongs to pretraining: 1024 of 4096 patches remain, plus CLS. Embedding extraction uses the complete input.","The encoder sees visible patches; the decoder inserts placeholders and restores positions, with different lengths and widths.","Three-dimensional sinusoidal positions retain axis information; shuffled patches must return to their indexed locations.","Voxel error is averaged within each patch and then across masked patches in normalized intensity space.","This page fixes the paper’s base encoder at twelve layers and width 768, distinguishing the additional large and huge code constructors.","Frozen SVM/SVR features and ViT fine-tuning require separate train, validation and test configurations.","Attention, regional correlations and latent manipulation offer complementary views of learned representations.","Study composition, older participant coverage and acquisition protocols matter when evaluating transfer to external cohorts."],"med_apps":["输入核对：检查去颅骨、配准方向、128³ 网格与强度标准化，再比较同一编码器的嵌入。","脑龄回归：区分冻结嵌入加 SVR 与微调 ViT，分别报告年龄覆盖、误差和独立队列表现。","分类应用：疾病与风险因素标签各有定义；判别分数、阈值、召回率和精确率一同阅读。","研究划分：纵向扫描按参与者分组；预训练、下游训练及外部验证的数据角色分别记录。","解释实验：区域体积与潜变量的相关性可供研究，潜变量改变后的重建不作为患者病程模拟。","发布使用：原论文图按 CC BY-NC-ND 4.0 完整展示；作者软件另遵循非商业协议。本站的真实推理演示仍使用已批准的 ResNet-18。"],"med_apps_en":["Input checks: verify skull stripping, registration, the 128³ grid and normalization before comparing embeddings.","Brain age: distinguish frozen-feature SVR from fine-tuned ViT; report age coverage and external-cohort error.","Classification: read task definitions, thresholds, recall and precision alongside discrimination scores.","Study splits: group longitudinal scans by participant and record pretraining, downstream and external-validation roles.","Interpretation: regional correlations and reconstructed latent changes are research analyses, rather than patient-trajectory simulations.","Reuse: the unmodified original uses CC BY-NC-ND 4.0; author software has separate noncommercial terms. The site’s approved real-inference demonstration remains ResNet-18."],"attrs":{"上一代瓶颈":"标注有限的三维 MRI 任务难以逐个从头训练，预设区域体积又只覆盖特定解剖描述。","核心想法":"从遮蔽体块重建学习三维结构，再把编码器迁移到脑龄与分类任务。","关键改进":"用稀疏可见体块训练重型编码器，以完整序列训练较轻解码器；下游表征关闭遮蔽。","医学适配":"统一预处理后的 T1 脑 MRI，支持冻结嵌入和编码器微调两条路线。","适用范围与证据":"2026-10-20 首次公开的预印本；本页核对基础模型与固定作者实现，重建质量和下游预测分别解释。"},"attrs_en":{"上一代瓶颈":"Limited labels impede task-by-task 3D MRI training; predefined regional volumes cover selected anatomical descriptions.","核心想法":"Learn 3D structure by reconstructing masked patches, then transfer the encoder to brain age and classification.","关键改进":"Train a heavy encoder on visible patches and a lighter decoder on the complete sequence; disable masking for embeddings.","医学适配":"Standardized T1 brain MRI supports frozen features and encoder fine-tuning.","适用范围与证据":"Preprint first posted 2026-10-20. The base model and pinned implementation are checked; reconstruction and downstream prediction are evaluated separately."},"paper_title":"Brain2Vec: A Self-Supervised 3D Foundation Model for Structural Brain MRI","paper_url":"https://arxiv.org/abs/2610.28411","code_label":"官方实现","code_url":"https://github.com/CBICA/Brain2Vec/tree/154a7e5dab885bd40522fc74372aae90c665c638","has_code":true,"image":"licensed/brain2vec/figure-1.svg"},{"id":"architecture_model_143_evlf_fm","num":143,"num_str":"143","year":2026,"year_str":"2026","venue":"Nature Medicine","venue_group":"journal","era_group":"era4","title":"EVLF-FM","family_id":"models_vision_language","family_code":"07","family_short":"图文对齐与医学 VLM","family_en":"Vision-Language Models","family_icon":"VII","family_label":"图文对齐与生成式 VLM：开放语义不等于视觉事实","accent":"#7A3547","archetype":"evlf-fm","archetype_en":"evlf-fm","fig_badge":"Fig. 1 · Nature Medicine · 2026","fig_href":"https://www.nature.com/articles/s41591-026-04655-5/figures/1","core_mech":"将通用视觉、疾病级全局特征与像素级空间特征一起接入语言模型。先以医学指令监督微调，再通过组相对策略优化学习诊断与定位，并对齐解释中的临床发现。","core_mech_en":"A language model combines general visual tokens, global disease features and spatial pixel features. Medical instruction tuning precedes group-relative policy optimization for diagnosis, grounding and clinically aligned explanations.","input_desc":"医学二维图像与文字问题或指令。作者实现基于 InternVL3-8B，并为疾病编码器与像素编码器分别准备图像张量；体数据实验使用所选切片。","input_en":"A medical 2D image and a textual question or instruction. The InternVL3-8B implementation prepares separate image tensors for disease and pixel encoders; volumetric-study examples use selected slices.","output_desc":"自回归生成诊断、图像问答及解释文本；视觉定位任务输出边界框坐标。像素编码器提供空间特征，最终定位输出形式由任务指令与标注规定。","output_en":"Autoregressive diagnostic answers, visual-question answers and explanations; grounding tasks produce bounding-box coordinates. The pixel encoder supplies spatial features, while instructions and annotations define the output format.","form_title":"计算机制","form_title_en":"Computation","nodes":[{"name":"准备图像与问题","name_en":"Prepare image and question","desc":"同一医学图像按各编码器要求分别预处理，文字指令规定诊断、问答或定位任务。二维切片与完整体积的输入范围分别理解。","desc_en":"Preprocess the same image for each encoder. The instruction selects diagnosis, VQA or grounding; a 2D slice has a different scope from a full volume."},{"name":"保留通用视觉标记","name_en":"Retain general visual tokens","desc":"InternVL3 的视觉路径提取图像标记，经视觉连接器映射到语言嵌入空间，保留通用图文模型的视觉上下文。","desc_en":"InternVL3 extracts visual tokens and projects them into the language embedding space, retaining the general VLM context."},{"name":"编码全局疾病线索","name_en":"Encode global disease cues","desc":"MedImageInsight 的 DaViT-Huge 路径提取全局疾病表征。独立连接器将该表征转为一个疾病提示标记。","desc_en":"The MedImageInsight DaViT-Huge path extracts a global disease representation. A dedicated connector produces a disease-prompt token."},{"name":"保留密集空间网格","name_en":"Preserve a dense spatial grid","desc":"MedSAM 图像编码器产生空间特征，展平后逐位置投影。作者主配置保留 256 个空间标记，为局部病灶与解剖定位提供细节。","desc_en":"MedSAM supplies spatial features that are flattened and projected position by position. The main configuration retains 256 spatial tokens for local anatomy and findings."},{"name":"在标记序列中融合","name_en":"Fuse in the token sequence","desc":"将通用图像标记、一个疾病标记和空间标记拼接，填入语言模型的图像上下文位置，与文字一起处理。主训练脚本关闭可选的第二疾病编码器。","desc_en":"Concatenate general visual, disease and spatial tokens at the LLM image-context positions alongside text. The main script disables the optional second disease encoder."},{"name":"以医学指令监督微调","name_en":"Tune on medical instructions","desc":"第一阶段以参考回答的负对数似然学习任务。基础参数冻结，以 LoRA 与连接器适配医学内容；训练脚本显式配置语言与辅助视觉编码器的适配器。","desc_en":"Stage one learns reference responses with negative log-likelihood. Frozen base weights are adapted through LoRA and connectors, with explicit language and auxiliary-encoder settings."},{"name":"为同一问题采样一组回答","name_en":"Sample a group of responses","desc":"将合并后的监督微调模型作为策略初始化。对同一图像与问题生成多个候选，组内奖励差异决定相对优势。","desc_en":"Initialize the policy from merged SFT adapters. Generate several responses to the same input; reward differences within that group define relative advantages."},{"name":"组合任务与解释奖励","name_en":"Combine task and reasoning rewards","desc":"论文用诊断正确性和定位交并比描述任务奖励；归档代码细分为标签集合重合与边界框交并比。解释奖励匹配临床发现，并考虑遗漏、无依据陈述与矛盾。","desc_en":"The paper describes diagnostic correctness and grounding IoU; archived code uses label-set overlap and box IoU. Reasoning alignment considers clinical matches, omissions, unsupported statements and contradictions."},{"name":"按组相对优势更新","name_en":"Update with group-relative advantages","desc":"奖励在组内标准化，裁剪策略比率控制更新，KL 项约束与冻结参考策略的偏移。第二阶段冻结视觉路径和连接器，仅更新语言 LoRA。","desc_en":"Normalize rewards within the group, clip policy ratios and regularize against a frozen reference with KL. Stage two freezes vision and connectors and updates language LoRA."},{"name":"联合阅读回答与定位","name_en":"Read answer, explanation and location","desc":"分别核对诊断标签、边界框与解释中的影像发现。解释属于事后生成的文本；论文通过人工评价与忠实度分析检验它与证据的关系。","desc_en":"Check diagnostic labels, boxes and described findings separately. Explanations are post hoc text; the paper examines their evidence alignment through human evaluation and faithfulness analyses."}],"design_principles":["三条视觉路径各有职责：通用图像标记提供上下文，疾病提示概括全局，密集空间标记保留局部线索。","连接器把不同编码器的特征映射到同一语言嵌入宽度，再拼接为视觉上下文。","主配置 use_tsm2=False，仅保留 MedImageInsight 与 MedSAM 两个医学辅助编码器；代码的可选分支不等于主模型。","监督微调学习参考回答；组相对策略优化比较同一问题的一组采样回答，两阶段的目标与参数更新范围不同。","组内奖励标准化提供相对优势，无须另训练价值网络；策略裁剪与 KL 项控制更新幅度。","解释对齐按句匹配临床内容，以覆盖度与忠实度的调和平均兼顾遗漏与冗余。作者归档还加入同数据集对照参考，减少通用模板获得的奖励。","论文的诊断正确性描述与代码的标签集合 F1 实现分别记录；定位训练的连续交并比与阈值化评估指标分别阅读。","归档主训练配置的强化学习数据为分类与定位；问答评估不等于对所有开放式回答直接施加强化学习奖励。","首次预印本与期刊版的数据构成和结果有所变化。本页采用期刊版机制与原图，不混用两个版本的数值。"],"design_principles_en":["General visual tokens provide context, a disease prompt summarizes global cues, and dense spatial tokens preserve local information.","Dedicated connectors map encoder features into the LLM width before visual-context concatenation.","The main use_tsm2=False configuration retains MedImageInsight and MedSAM; optional code branches are separate variants.","SFT learns reference responses; GRPO compares grouped sampled responses, with different objectives and trainable parameters.","Within-group reward normalization supplies advantages without a learned critic; clipping and KL control policy updates.","Sentence-level alignment balances completeness and faithfulness with a harmonic mean. The archive adds same-dataset distractor references to reduce generic-template rewards.","Record the paper’s diagnostic correctness description separately from code’s label-set F1; distinguish continuous training IoU from thresholded evaluation.","The archived main RL configuration lists classification and grounding data; VQA evaluation does not imply RL on all open-ended answers.","The preprint and journal versions differ in data composition and results. This page uses the journal mechanism and original without mixing numerical results."],"med_apps":["图像输入：检查模态、所选切片、缩放与各编码器的归一化方式，再解释输出覆盖的空间范围。","诊断任务：核对疾病类别与标签集合，区分单标签正确率、多标签重合与校准。","视觉定位：对照原图检查边界框坐标、图像缩放与标注定义；连续交并比和阈值命中率各有意义。","解释阅读：把文本中的临床发现逐项对应影像或参考描述，并检查否定、遗漏与新增陈述。","迁移评估：分别记录内部数据、外部队列、零样本和少样本协议，以及机构与设备差异。","原图与实现：期刊图 1 按 CC BY-NC-ND 4.0 完整展示；作者软件归档另标注 CC BY 4.0。本站仅展示机制，真实推理实验沿用已批准的 ResNet-18。"],"med_apps_en":["Input: verify modality, selected slice, resizing and encoder normalization before interpreting spatial coverage.","Diagnosis: check class definitions and label sets, distinguishing single-label accuracy, multi-label overlap and calibration.","Grounding: inspect box coordinates, resizing and annotation conventions alongside continuous IoU and thresholded hits.","Explanations: map clinical statements to image findings or reference text and check negation, omissions and added claims.","Transfer: separate internal and external cohorts, zero-shot and few-shot protocols, institutions and devices.","Reuse: the complete journal Figure 1 uses CC BY-NC-ND 4.0; the author software archive separately lists CC BY 4.0. The approved live inference experiment remains ResNet-18."],"attrs":{"上一代瓶颈":"通用视觉语言模型的高层语义未必保留医学诊断线索与局部病灶细节。","核心想法":"让通用视觉、全局疾病与局部空间特征共同进入语言模型的上下文。","关键改进":"先做医学指令监督微调，再以任务奖励和临床解释对齐奖励优化同一生成策略。","医学适配":"统一诊断、图像问答与边界框定位，同时分别评估回答正确性与解释质量。","适用范围与证据":"2025-09-29 首次公开预印本，2026-10-29 发表期刊版；本页采用期刊原图与其引用的固定作者归档。"},"attrs_en":{"上一代瓶颈":"General VLM semantics can miss disease-specific cues and local findings.","核心想法":"Combine general vision, global disease and local spatial features in the LLM context.","关键改进":"Follow medical instruction tuning with task rewards and clinical reasoning alignment.","医学适配":"Support diagnosis, VQA and box grounding while evaluating answer quality and explanations separately.","适用范围与证据":"Preprint first public on 2025-09-29; journal publication on 2026-10-29. This page uses the journal original and its cited immutable author archive."},"paper_title":"A clinical multimodal vision language foundation model with fine-grain explainability","paper_url":"https://www.nature.com/articles/s41591-026-04655-5","code_label":"官方实现","code_url":"https://doi.org/10.5281/zenodo.21772695","has_code":true,"image":"licensed/evlf-fm/figure-1.png"}];
